!function(){"use strict";window.__bookText={adam_cain:{id:"adam_cain",title:"آدم وحواء — قايين وهابيل (شخصيات الكتاب المقدس ١-٢)",author:"قداسة البابا شنوده الثالث",url:"https://drive.google.com/file/d/1r8fM7tLnngLJvk1v_XVBRk5EVMch1YIu/view",file:"شخصيات الكتاب المقدس - آدم وحواء - قايين وهابيل - البابا شنودة الثالث",pageOffset:-1,review:{status:"needs-review",note:"نُقل الكتاب (من «مقدمة» ص٦ إلى نهاية قايين وهابيل ص٥٤ المطبوعة، أي ص٧ إلى ص٥٥ بترقيم الملف) بقراءة صفحات الكتاب الممسوحة بالنظر؛ حُذف الغلاف والفهرس وصفحة «كتب أخرى للبابا». الرقم المطبوع = ترقيم الملف − ١. ص٤٢ وص٤١ صفحتان للوحات بلا نص (ملاحظة بين قوسين). النسخة الممسوحة ضعيفة الجودة في بعض المواضع، فيلزم مطابقة نهائية مع الأصل، وبعض الكلمات قُرئت بأفضل ما تيسر."},chapters:[{title:"مقدمة",from:7,to:8},{title:"شخصيات الكتاب",from:9,to:15},{title:"١ — آدم وحواء",from:16,to:41},{title:"٢ — قايين وهابيل",from:42,to:55}],transcribed:[7,55],pages:{7:[{h:"مقدمة"},"ليس هذه دراسات فى العهد القديم ، ولا هى مقدمات لأسفاره ، إنما هى تأملات روحية ، تقدم منهجاً تأملياً فى الكتاب .","وقصتها قديمة معى ...","إذ كنت قد قمت بتدريس العهد القديم فى الكلية الاكليريكية ، عقب تخرجى فيها ، من اكتوبر سنة ١٩٤٩ ، أى منذ حوالى ثلاثين عاماً ... كما قمت بتدريس العهد الجديد من سنة ١٩٥٢ .",{h:"وكنت أرى الكتاب ـ كما قدمه الرب لنا ـ روحاً وحياة ..."},"وهذا ما أريد أن اقدمه لك ، أيها القارىء العزيز","تماماً ، كما قدمته فى محاضرات يوم الثلاثاء بالكاتدرائية الكبرى ، خلال ثلاث سنوات من ١٩٦٩ إلى ١٩٧٢ م","وأود من أجلك ، أن أتابع نشر هذه المجموعة ، التى احب ان تحتفظ بها معك ، كاملة ...","وثق أنك سترى حياتك الخاصة ، من خلال شخصيات الكتاب ... فالنفسية البشرية هى هى ، منذ آدم ، وحواء إلى يومنا هذا ...",{h:"وفى الكتب المقبلة من هذه السلسلة ، اود أن اقدم لك ، بمشيئة الرب :"},"١ ـ نوح البار","٢ ـ ابراهيم ولوط","٣ ـ يعقوب وعيسو","٤ ـ يوسف واخوته","٥ ـ صموئيل النبى","٦ ـ شاول وداود","٧ ـ داود النبى والملك","٨ ـ ارمياء النبى","٩ ـ نحميا","١٠ ـ اشعياء ... الخ .","وانتابع معك شخصيات العهد القديم ، حتى يوحنا المعمدان ... كما نتناول شخصيات العهد الجديد أيضا ، إن أحب الرب وعشنا"],8:[{h:"وهناك كتب أخرى عن تأملات فى أسفار الكتاب منها :"},"١ ـ دم ونار « عن ذبائح العهد القديم »","٢ ـ تأملات فى المزامير « وبخاصة مزامير الأجبية »","٣ ـ تأملات فى سفر نشيد الأناشيد","٤ ـ تأملات فى سفر الرؤيا","٥ ـ تأملات فى العظة على الجبل","واحتاج إلى صلواتك ، لكيما يعطى الرب وقتاً وقوة","كن معافى فى الرب","شنوده الثالث","٢٤ فبراير ١٩٨٠ « ١٦ أمشير »","« الاحد الثانى من الصوم الكبير »"],9:[{h:"شخصيات الكتاب"},{h:"* قدم لنا الكتاب المقدس الوانا متنوعه من « أناس الله القديسين » :"},"إنها صور متعددة من قديسين ، كل منهم له طابعه الخاص ، يختلفون فى العمر والجنس والوظيفة والحياة الاجتماعية والاسلوب الروحى .","وذلك لكى نتعلم أن القداسة ملك للكل ، وليست وقفا على فئة معينة من الناس دون غيرها ...","فلم يقدم لنا الكتاب حياة القداسة أو حياة الكمال ، قاصرة على الانبياء والرسل مثلا ، أو على الكهنة ورؤساء الكهنة ، أو على صانعى العجائب والمعجزات ، إنما هى للكل ، وهى بإمكان كل أحد ...",{h:"* قدم لنا الكتاب المقدس قديسين فى مراحل متفاوتة من العمر :"},"منهم الاطفال مثل صموئيل ، ومنهم الصبيان مثل داود وأرمياء . ومنهم الشباب مثل يوسف الصديق ، ويوناثان ، ومار مرقس ويوحنا الحبيب . ومنهم الرجال الناضجون مثل موسى وبطرس ، ومنهم الشيوخ مثل نوح واخنوخ وابراهيم ... وسمعان الشيخ",{h:"* قدم لنا رجالا ككل هؤلاء . كما قدم لنا نسوة قديسات ... مثل مريم العذراء ، وحنة النبية ، وسارة ، وراعوث ، واستير ، واليصابات ، ومريم اخت لعازر ... وغيرهن كثيرات ..."},{h:"* وكما قدم لنا قديسين متفاوتين فى العمر ، قدم لنا أيضا قديسين متفاوتين فى المركز الاجتماعى ، وفى الغنى والفقر : فالمسالة أولا وأخيرا مسألة قلب مستعد لعمل النعمة فيه ، ايا كان مركزه أو وضعه المالى أو وظيفته فى المجتمع"},"وهكذا قدم لنا الكتاب قديسين أغنياء جدا مثل أيوب الصديق ، وأبينا ابراهيم ، ويوسف الرامى . كما قدم لنا فقراء مثل الأرملة التى دفعت من أعوازها فلسين فى الصندوق ، ومثل ارملة صرفه صيدا التى استضافت ايليا النبى ، ومثل لعازر المسكين الذى كان يستعطى ، وكانت الكلاب تلحس قروحه ...","قدم لنا الكتاب رعاة غنم مثل داود واسحق ويعقوب ، وصيادى سمك مثل بطرس واندراوس ، وعشارين مثل متى وزكا ، وملوكا مثل داود ويوشيا ، ووزراء مثل دانيال ويوسف ، وأسرى حرب مثل الثلاثة فتية ، وابطالا مثل شمشون ، وقضاة مثل جدعون ، وطبيبا مثل لوقا ، وكاتبا مثل عزرا ، وخادما مثل لعازر الدمشقى ..."],10:[{h:"* وقدم لنا الكتاب أيضا قديسين متفاوتين فى ثقافتهم وعلمهم :"},"فبينما نرى موسى الذى « تهذب بكل حكمة المصريين » ، وبولس الذى كان من علماء عصره ، وسليمان الذى كان أحكم أهل الارض فى زمانه ، نرى أيضا جهال العالم الذين اختارهم الله ليخزى بهم الحكماء ...",{h:"* كذلك قدم لنا الكتاب أمثلة متفاوتة فى البتولية والزواج والترمل ، وكلها كانت تحيا حياة مقدسة طاهرة أحبها الرب ..."},"قدم لنا بتوليين قديسين مثل ايليا واليشع ويوحنا المعمدان ويوحنا الحبيب ، ومتزوجين قديسين مثل نوح البار ، وبطرس الرسول ، واخنوخ ابى الآباء الذى رفعه الله اليه ... كما قدم لنا من عاشوا حياة مقدسة فى اترمل مثل حنة النبية ، ومن تزوجوا بعد ترملهم مثل راعوث ، ومن تزوجوا بأكثر من واحدة مثل ابراهيم وموسى وداود ...","وعلى جبل التجلى ، ظهر السيد المسيح ، محاطا بايليا البتول ، وبموسى المتزوج ، والكل يحيط بهم نور عجيب .","وحول الصليب ، كانت مريم العذراء ويوحنا البتول ، مريم زوجة كلوبا التى انجبت عددا كبيرا من البنين والبنات ...",{h:"* قدم لنا الكتاب من عاشوا حياة مقدسة منذ البدء ، ومن جاءوا إلى الرب اخيرا ، ورحمهم الله وقبلهم اليه :"},"قدم لنا قديسين من بطون أمهاتهم ، مثل يوحنا المعمدان الذى من بطن امه امتلأ من الروح القدس . كما قدم لنا قديسين وقديسات عاشوا فى عمق الخطية قبل لقائهم بالرب ، مثل اللص اليمين ، والمرأة التى بللت قدمى الرب بدموعها ، ومثل راحاب الزانية ، وقدم لنا الكتاب اشخاصا عاشوا من قبل بعيدين عن الله ، مثل مريم المجدلية التى اخرج منها الرب سبعة شياطين ، والمرأة الكنعانية التى كانت من شعب ملعون أمى ...","وقدم لنا قديسين من مضطهدى الكنيسة ، مثل شاول الطرسوسى ، ومثل الجندى الذى طعن المسيح بالحربة .",{h:"* قدم لنا الكتاب المقدس شخصيات تحمل ألوانا من الروحيات ، متنوعة ، ومتغايرة ولكننا نراها كلها متكاملة :"},"قدم لنا ايليا الشديد الناري ، الذى اغلق السماء ثلاث سنين وستة أشهر فلم تمطر ، والذى قتل المئات من انبياء البعل وانبياء السوارى ، وانتهر آخاب الملك ، وقال لتنزل نار من السماء وتأكل الخمسين فنزلت واكلتهم . كما قدم لنا الكتاب ارمياء النبى الباكى الذى سكب دموعه ومراثيه ."],11:["وأرانا الكتاب كيف أن الله عمل فى الشخصية النارية ، كما عمل فى الشخصية الباكية . واستخدم الاثنين فى بناء ملكوته . فليس المهم هو نوعية الشخص ، إنما تسليمه لإرادته فى يد المشيئة الإلهية .","فى الكتاب نرى شخصية بطرس الرسول المملوءة غيرة وتسرعا واندفاعا ، مع شخصية توما المملوءة حرصا وشكا وتريثا وحبا للفحص وبعدا عن الاندفاع . وكلاهما فى يد الرب ، يعمل بهما . ونرى فى الكتاب كيف استخدم الله اناسا كما هم ، بينما غير البعض فحول يوحنا ابن الرعد ، تلميذ المعمدان إلى قلب كله حب ...",{h:"* وكل فضيلة تعجبنا ، نرى شخصيات فى الكتاب تمثلها :"},"نرى ايوب يمثل الصبر ، وسمعان الشيخ يمثل الرجاء والانتظار . نرى داود يمثل التوبة والانسحاق ، وابراهيم يمثل الطاعة والايمان . نرى يعقوب الهادىء المحتمل ، ويوحنا المعمدان المشهور بالشجاعة والمواجهة ، وبولس المملوء نشاطا وغيرة وحركة وتعليما كما نرى العذراء المشهورة بالصمت والتأمل ...",{h:"إنها باقة من الفضائل متنوعة الازهار والألوان والعطور :"},"يقدمها الكتاب المقدس ، فى اشخاص اتقنوها عمليا ، وتركوها لنا كقدوة ومثال . بحيث أننا إن أردنا صفة ما ، أو فضيلة ما ، سنجد حتما الشخص الذى يعطى لها صورة مثالية . وهكذا يكون الكتاب جامعا لكل ما نريد .",{h:"* لذلك لا ييأس أحد مفتكرا أن حالته لا تناسب دعوة الله :"},"فالله مستعد أن يدعوك كما أنت ، أيا كانت حالتك ، أو ثقافتك ، أو سنك ، أو مركزك ، أو وضعك الاجتماعى ... انه « الداعى الكل إلى الخلاص » ... ولعلك تجد مثيلا لك فى الكتاب المقدس ، قد عمل الله فيه وبه ...","لا تقل إذن « لست أصلح » . فليس المهم هو صلاحيتك ، انما المهم هو عمل الله معك . والله قادر أن يعمل مع الكل . قل له إذن « مستعد قلبى يا الله ، مستعد قلبى » « مز ٥٦ » .",{h:"* ومن الأمور المعزية أيضا فى الكتاب أنه قدم لنا مثاليات مثلنا ، لقديسين كانت لهم ضعفاتهم ونقائصهم وسقطاتهم :"},"ولكن روح الله قد عمل فيهم ، وأوصلهم إلى درجات عليا فى القداسة ، على الرغم من هذه الطبيعة التى يمكن أن تضعف أحيانا ، وتسقط ... وما أعمق وأصدق قول الكتاب : « ايليا ، كان انسانا ، تحت الآلام مثلنا ... » « يع ٥ : ١٧ ، ١٨ » ."],12:["ومع أنه كان تحت الآلام مثلنا ، إلا أنه « صلى صلاة » . واستطاع أن يغلق السماء ، وأن يفتحها .","قدم لنا الكتاب ابراهيم الذى خاف أن يقتلوه ، فقال عن زوجته سارة إنها اخته . ويعقوب الذى خدع أباه ، وسرق بركة أخيه . وشمشون الذى اغرته دليلة ، فكسر نذره . ونوحا الذى سكر وتعرى ، وداود الذى زنى وقتل ، وتوما الذى شك ، وبطرس الذى أنكر ...",{h:"لم يقدم لنا الكتاب قديسين معصومين ، أو بشرا من نوع الملائكة ، انما قدم بشرا مثلنا ، واقعا لا خيالا ..."},"قدم النفس البشرية التى نعرفها ، والتى اختبرناها ، « الأوانى الخزفية ، السهلة الكسر ، التى عمل فيها الخزاف العظيم ، وصنع منها أوانى للكرامة ، وجعلها رائحة بخور ذكية ... وكان « فضل القوة لله وليس لنا » . أما عن الحروب الروحية التى تعرض لها هؤلاء ، فيعزينا الكتاب بقوله :",{h:"« الحرب للرب ، والرب قادر أن يغلب بالكثير وبالقليل"},"قدم لنا الكتاب المقدس عينات من قديسين ، من نفس نوعنا ، يمكن أن تضعف ، ويمكن أن تسقط ، ويمكن أن تخطىء وأن تزل ...",{h:"* ولكن قدم لنا فى هؤلاء القديسين الذين اخطأوا ، صورا رائعة من التوبة . نصف الحقيقة أنهم أخطأوا ، والنصف الآخر ، الأروع ، أنهم تابوا ..."},"إن الكتاب المقدس صريح وواقعى . إنه يقدم لنا قديسين من نفس طبيعتنا ، التى يمكن أن تخاف ، وأن تشتهى ، وأن تفتر ، وأن تهرب ، وتختبىء من الله ... حتى السبعة ملائكة الذين للسبع كنائس فى آسيا ، نراهم من نفس الطبيعة البشرية العادية :","لذلك حينما ندرس هؤلاء الرعاة ، الذين وصفهم الكتاب بأنهم ملائكة ، لا ننسى أن واحدا منهم كان فاترا ، لا هو حار ، ولا هو بارد ، وكان الله مزمعا أن يتقيأه « رؤ ٣ : ١٦ » . ونرى واحدا آخر منهم ، على الرغم من تعبه وكده لأجل الله ، عاد وترك محبته الأولى ، وأرسل له الله قائلا « اذكر من اين سقطت وتب » « رؤ ٢ : ٥ » . ونرى ملكا ثالثا من ملائكة هذه الكنائس السبع ، يقول له الرب « إن لك اسما انك حى وأنت ميت » « رؤ ٣ : ١ » .","إنها نفس الطبيعة البشرية التى لباقى الناس ... والكتاب المقدس لا يكلمكم من وحى الخيال ، ولا يصور لكم قديسين لهم أجنحة من نور ونار ، يطيرون فى السماء ، ويسبحون فى أجواء القداسة العليا ...",{h:"* ولكن بعمل الله القوى الذى عمل فيهم ، بنعمته التى دخلت إلى قلوبهم ، بروحه القدوس الذى أرشدهم وقواهم وأشترك فى العمل معهم ... بهذا قد وصلوا إلى ما وصلوا اليه ... وتغيروا ..."}],13:["بطرس الذى خاف ذات مرة أمام جارية وانكر المسيح ، تحول إلى القديس بطرس الجبار العنيف ، الذى وقف امام ولاة وملوك ، وقال للشيوخ ولرؤساء الكهنة « ينبغى أن يطاع الله أكثر من الناس » ... جاهر بالإيمان ، وتعب لأجله ، وصار شعلة من نار ، وصلب ، ومات شهيدا ...","ما هذا يا أبى بطرس ؟ يجيب : لقد كنت ضعيفا مثلك ، وخائفا مثلك . ولكن الله عمل فى ضعفى ، وروحه قوانى وشددنى ، فشهدت له أمام الكل ...","إذن ، حينما نجد القديس بطرس الرسول قد ملأ الدنيا تبشيرا ، لا نقول إنه من طبيعة اخرى سامية غير طبيعتنا ... كلا ، إنه مثلنا . ولكنه فتح قلبه لعمل الله ، وسلم مشيئته لمشيئه القدوس ...","وإن رأينا انسانا مثل القديس بولس الرسول ، قد تعب أكثر من جميع الرسل ، وكرز فى كل أرجاء الأرض ، فلا نظن أنه قد ولد هكذا ... وإنما هو نفسه يعترف ويقول : أنا الذى كنت من قبل مجدفا ومضطهدا للكنيسة ، ولكننى رحمت لأننى فعلت ذلك بجهل ...","وإن عرفنا جبارا من جبابرة الروح والرعاية مثل القديس موسى النبى ، الذى أجرى الله على يديه معجزات فى ارض مصر ، وشق البحر بعصاه ، وضرب الصخرة ففجر منها الماء ، وأنزل من السماء المن والسلوى ... فلا نظن أنه قد ولد هكذا ... بل أنه عاش فى مبدأ حياته كأمير فى قصر فرعون ، بكل ما تحمل الإمارة من رفاهية وتنعم وكبرياء ، معتدا بنفسه ، يضرب المصرى فيقتله . ولكن الله أمسك به ، وعلمه طريقه . أمسكه « ابن النجار » ، بالفارة والمنشار ، وأزال نتوءاته ، وصنفره ، وعمل فيه ، حتى صار قديسا عظيما لا نستحق التراب الذى يدوسه بقدميه ... « وصار الرجل موسى حليما جدا ، أكثر من جميع الناس الذين على وجه الأرض » « عد ١٢ : ٣ » .","هذه عينات من الناس ، أخذها الله كما هى ، وعمل فيها ، وعمل معها ، وصارت له ، واخذت من بهائه ، ومن قوته ...",{h:"وبالنسبة اليك ، لا تشابه القديسين فى ضعفاتهم ، وإنما فى طهرهم ."},"لا تتهاون معتذرا بأن القديسين أنفسهم قد اخطأوا ، إنما انظر الى توبتهم وأعماقها العجيبة ، والتصاقهم الطبيعى بالله .",{h:"* وحينما نقول إنهم اخطأوا ، فلا نعنى أن حياتهم كلها كانت خطية . بل السقطات كانت الوضع العابر الطارىء فى حياتهم . أما القداسة فكانت الوضع الطبيعى الدائم ."},"إذا عرفنا أن داود فى وقت ما ، قد زنى وقتل . فليس معنى هذا أن حياته كلها كانت زنى وقتلا ، وليس معنى هذا أن يتطاول بعض الوعاظ على هذا القديس العظيم ، ولا يتحدثون إلا عن خطيئته بلون من الاستصفار !! وينسون أنه رجل الصلاة والتسبيح"],14:["والمزامير ، رجل المزمار والقيثار والعشرة الأوتار ، رجل الإيمان والوداعة ، الذى قال عنه الرب « فحصت قلب داود ، فوجدته حسب قلبى » .","إن الشر لم يكن طبيعة فى هذا البار ، الذى حل عليه روح الرب ، والذى هزم جليات ، واحتمل شاول ، وغفر لشمعى بن جيرا ، وسبح للرب تسابيح جديدة ... إنما هى صفات طارئة ، سمح بها الرب ليعطى قديسه اتشحاقا ودموعا ، ويصيره درسا فى التوبة ، كما كان درسا فى الصلاة ، وفى الوداعة ، وفى الشجاعة .","وبنفس الوضع حينما نذكر خوف ابينا ابراهيم ، وقوله عن امرأته سارة إنها أخته ... لا ننسى أبدا إيمان الرجل ، ونسكه ، وشجاعته ، وكرمه ، وطاعته للرب حتى رفع السكين ليقدم وحيده المحبوب محرقة ... ولا ننسى مذابحه وخيامه ، وتركه لأهله وعشيرته وسعيه وراء الرب ...",{h:"* كذلك فى حديثنا عن قديسى الكتاب ، ليس المهم نقطة البدء فى حياتهم ، فربما بدأ البعض منهم كأشخاص عاديين . إنما المهم هو ما انتهوا إليه ..."},"وهكذا يقول لنا الكتاب « انظروا إلى نهاية سيرتهم ، فتمثلوا بإيمانهم » « عب ١٣ : ٧ » . فجدعون مثلا بدأ كإنسان عادى جدا ، ومريم المجدلية بدأت بداية سيئة جدا ، وكذلك راحاب وباراباس . وشاول الطرسوسى بدأ مجدفا ومضطهدا للكنيسة ... ولكن نقطة البدء فى حياة القديسين لا تعنينا كثيرا ، بقدر ما يعنينا خط سيرهم ، وفتح قلوبهم له ، وكيف انتهوا وكملوا فى الإيمان ...",{h:"* كذلك يهمنا فى سير قديسى الكتاب ، ليس عملهم فقط وحياتهم وصفاتهم ، وإنما بالأكثر عمل الله معهم ، وطريقة معاملته لهم ..."},"لقد كانت حياة هؤلاء القديسين ، مجرد مجال عمل فيه الله . ونحن نهتم بهذه النقطة بالذات فى حياة قديسى الكتاب ... يهمنا جدا دور الله فى حياتهم . كيف عاملهم الرب ؟ وكيف عامل غيرهم من الناس الذين اتصلوا بهم ؟ كيف كانت معاملة الله لقديسيه ، وكيف كانت معاملته للأشرار ؟ ومعاملته للساقطين والتائبين وللقائمين ...",{h:"إن الكتاب هو سجل جميل لمعاملة الله مع الناس ..."},"ومن واقع هذه المعاملة نأخذ فكرة عن صفات الله الجميلة ، وعن حبه وطول أناته ، وحكمته وصلاحه ، وقوته وقدرته ... ونأخذ من كل هذا دروسا لأنفسنا ومجالا لتأملاتنا ."],15:[{h:"* وفى سير قديسى الكتاب ، لا نريد أن ندرس تاريخا ، وإنما أن نمتص حياة ..."},"فالكتاب المقدس لم يقصد به أن يكون كتاب تاريخ ، إنما هو كتاب إيمان ، وكتاب حياة . وهذا هو الفرق بين دراستنا للكتاب ، ودراستنا لكتب التاريخ . التاريخ يذكر أحداثا متتابعة ، ويقدم قصص أمم وشعوب ودول وسياسات وحروب ... ولكننا لا نفحص الأحداث ، بقدر ما نفحص حالة القلب .",{h:"إننا من خلال الأحداث ، ندرس النفس البشرية ، فى كل مشاعرها وأحاسيسها وتصرفاتها ، ندخل إلى أعماق النفس ، وندرس حروبها الروحية ، وندرس علاقاتها مع الله ومع الناس ومع ذاتها ، ومن كل ذلك نتعلم ..."},"والكتاب المقدس صريح جدا فى كشف النفس البشرية .","ونحن نريد أن نتناول هذه النفوس ، لكى نحللها ، ونفهمها ، ونرى فيها صورتنا نحن ، وما ينبغى أن نفعل ، ونحن نصلى لكى يعطينا الرب نعمة أثناء هذه التأملات ، ويوجهنا إلى الدروس الروحية النافعة لنا ، لنعرفها ، ونطبقها عمليا ...","وفيما ندرس هذه الشخصيات ، ندرسها لكى نحيا نحن ...","نحيا من خلال حياة هؤلاء ، ونستفيد من تجاربهم ، ومن خبراتهم ، ونستفيد من سقوطهم أيضا ومن قيامهم .","وإن تعرضنا لأخطاء ، فنحن لا ندينهم عليها ، انهم آباؤنا وأجدادنا ومعلمونا ، بل هم أيضا مثلنا العليا التى نقتدى بها ... وهم أحياء الله الذين نرجو شفاعتهم وبركتهم ...",{h:"والأخطاء التى نكشفها ، إنها تكشف لنا ضعف طبيعتنا ، طبيعتنا نحن بالذات ، وليس ضعفا لأولئك القديسين الذين لا نستحق أن نقبل التراب الذى داسوه بأقدامهم الطاهرة ..."},"بركة هؤلاء جميعا ، فلتكن معنا ، آمين ..."],16:[{h:"« ١ » آدم وحواء"},"أولا : بهاؤهما الأول","ثانيا : ٢٧ خطية وقعا فيها","ثالثا : نتائج هذه الخطايا وعقوباتها ."],17:[{h:"آدم وحواء"},"يحسن بنا أن نبدأ تأملاتنا فى شخصيات الكتاب بأبوينا الاولين ، آدم وحواء ، ونرى كيف خلقا وكيف كانا ، وميزات طبيعتهما الاولى فى عمق بهائها ومجدها ، وكيف قادهما الضعف البشرى ، وتطور بهما من سقطة الى أخرى ، حتى كثرت خطاياهما جدا ، وفسدت طبيعتهما البشرية .",{h:"بهاؤهما الأول"},{h:"١ ـ كانا مخلوقين ، غير مولودين ، لم يرثا فسادا من طبيعة سابقة :"},"آدم وحواء ، لم يولدا من دم ، ولا من مشيئة جسد ، ولا من مشيئة رجل ... لم يأتيا من زرع بشر ، ولم يرثا طبعا فاسدا من طبيعه سابقة عليهما ، انما خلقهما الله ، شيئا جديدا لم يطوث من قبل ، وبالطريقه التى أرادها الرب لهما .",{h:"٢ ـ خلقهما الله على صورته ومثاله . ولا يمكن أن يوجد أعظم من هذا ، أن يكون آدم وحواء على شبه الله ..."},"وفى ذلك يسجل سفر التكوين « وقال الله نعمل الإنسان على صورتنا كشبهنا ... فخلق الله الانسان على صورته ، على صورة الله خلقه . ذكرا وأنثى خلقهم » « تك ١ : ٢٦ ، ٢٧ » .","وما أكثر تأملات الآباء القديسين وتفسيراتهم ، الخاصة بخلق أبوينا الأولين على صورة الله ...","* قيل ان الله خلقهما على صورته فى البر والقداسه ، فى وضع فائق للطبيعة ... وهكذا كان كلاهما بارين بلا خطية ، حينما خلقهما الله متسربلين بالقداسه ...","* وقيل على صورته فى الجمال والبهاء والمجد ، أى اعطاهما قبسا من بهائه ، فكانا فى منتهى الجمال ، جسدا ونفسا وروحا ...","* وقيل ان الله خلق الانسان على صورته فى الخلود ، إذ وهب لهما نفسا خالدة ، نفخها فى أنف آدم ، نسمة حياة ، فصار آدم نفسا حية « تك ٢ : ٧ »","* وقيل إن الله خلقهما على صورته فى حرية الارادة .","* وقيل أيضا أن الانسان خلق على صورة الله فى التثليث والتوحيد : ذاتا ، لها عقل ناطق ، ولها روح . والذات والعقل والروح كائن واحد : كالذات الإلهية ، لها عقل ، ولها"],18:["روح ، والثلاثة كائن واحد ... انما الله غير محدود فى كل شىء ، والانسان محدود ...","* وقيل إن الله خلقهما على صورته فى الملك والسلطة . فكانا ملكين على الأرض ، لهما سلطة على كل كائناتها « تك ١ : ٢٨ » . وكان آدم نائبا لله على الأرض ، وممثلا للخليقة الأرضية كلها ...","* وقيل إن الله كان يعرف مسبقا بسقوط الانسان ، وبأنه سيخلى ذاته ويتجسد لكى يخلصه ، فخلق هذا الانسان على الصورة التى كان مزمعا أن يتجسد بها ، على شبهه ومثاله ...",{h:"٣ ـ وكان آدم وحواء يتصفان بالبساطة والبراءة :"},"ما كانا يعرفان الشر اطلاقا . كانا يعرفان الخير فقط ، ولا شىء سوى الخير . لذلك لم يفكرا وقت التجربة أن الحية يمكن أن تخدع وأن تكذب . فعبارات الكذب والخداع لم تكن موجودة فى قاموسهما فى ذلك العين .","وفى بساطتهما وبراءتهما ، ما كانا يعرفان بعضهما من الناحية الجنسية ، بل كطفلين ساذجين ـ ما كانا يفهمان الفروق العضوية فى تركيب جسديهما . وكما ذكر سفر التكوين « وكانا كلاهما عريانين ، آدم وامرأته ، وهما لا يخجلان » « تك ٢ : ٢٥ » .",{h:"٤ ـ وقد باركهما الله معا ، بنفس البركة ، واعطاهما سلطانا على الارض كلها بجميع كائناتها ، نفس السلطة لكليهما ..."},"وفى ذلك يذكر سفر التكوين « وقال الله نعمل الانسان كصورتنا ، فيتسلطون على سمك البحر ، وعلى طير السماء ، وعلى البهائم ، وعلى كل الارض ، وعلى الدبابات التى تدب على الارض » « تك ١ : ٢٦ » . « وباركهم الله وقال لهم اثمروا واكثروا واملأوا الارض ، واخضعوها ، وتسلطوا على كل سمك البحر ، وعلى طير السماء ، وعلى كل حيوان يدب على الارض » « تك ١ : ٢٨ »","وهكذا عاش الاثنان ، ولهما هيبة وسلطة ، على كل الارض ومخلوقاتها . ما كانا يخافان الوحوش أو دبيب الأرض ، بل عاشا وسط الاسود والنمور والفهود والحيات والثعابين وما أشبه ، فى حياة من الألفة والسلام ، لهما سلطان على كل هؤلاء . ترى الوحوش فيهما صورة الله ، فتعاملهما بالمهابة اللائقة بهما .","وآدم هو الذى سمى كل الحيوانات وكل ذوات الانفس بأسمائها « وكل ما دعا به آدم ذات نفس حية ، فهو اسمها . فدعا آدم بأسماء جميع البهائم وطيور السماء ، وجميع حيوانات البرية » « تك ٢ : ١٩ ، ٢٠ » ."],19:[{h:"٥ ـ وكان آدم وحواء اجتماعيين ، يتعاونان معا ..."},"حينما كان آدم وحده فى الجنة ، وجد التعاون والألفة بين جميع حيوانات الأرض « واما لنفسه ، فلم يجد معينا نظيره » « تك ٢ : ٢١ » . وصعد هذا الاشتياق ، أو هذا الاحتياج الى الله « فاوقع الرب الاله سباتا على آدم فنام . فاخذ واحدة من أضلاعه ، وملأ مكانها لحما . وبنى الرب إلإله الضلع التى أخذها من آدم امرأة ، وأحضرها إلى آدم » « تك ٢ : ٢١ ، ٢٢ » .","وشعر آدم بهذه الرابطة القوية التى تربطه بحواء ، وأنها جزء منه ، بينهما رابطة دم ولحم وعظم . « فقال آدم : هذه الآن عظم من عظامى ، ولحم من لحمى . هذه تدعى امرأة ، لأنها من امرء اخذت » « تك ٢ : ٢٣ »",{h:"٦ ـ ونحن نعجب من هذه المعرفة التى كانت لآدم :"},"* كيف عرف أن حواء ، قد أخذت من لحمه ومن عظامه ، بينما كان فى سبات ؟! هل اخبره الله بما حدث ، فى ظل علاقة المحبة بينه وبين الله ؟ أم كان هذا اللون من المعرفة ، من ضمن مواهبه التى كانت له ، الذى خلق فيه بوضع فائق للطبيعة ؟!","* كما أننا نعجب بآدم إذ أنه أعطى حواء اسما له دلالة وله عمق ، فسماها امرأة ، لأنها من امرء اخذت .","وفيما بعد ... بعد الخطية ، حينما ولدت امرأته ابنا ، أعطاها اسما آخر : « ودعا آدم اسم امرأته حواء ، لأنها أم كل حى » « تك ٣ : ٢٠ » . إنها حكمة اتصف بها آدم فى اطلاق الاسماء . ولعله استخدم هذه الحكمة ذاتها فى تسمية الحيوانات والطيور وكل ذوات الانفس الحية .","ليت أحد المتخصصين فى علوم اللغات ، يبحث مع بعض المتخصصين فى علوم الحيوان ، السر الذى يكمن وراء اسماء الحيوانات ، والحكمة التى بها اطلق آدم كل اسم على صاحبه ...","* كان آدم أيضا يعمل فى الجنة ويحفظها « تك ٢ : ١٥ » . فمن أين أوتى آدم هذه المعرفة بشئون كل النباتات الموجودة فى الجنة ؟ أتراه أيضا لون من الكشف الإلهى ، أو كانت معرفة آدم من نوع فائق لمعرفتنا ؟!",{h:"٧ ـ وقد خلق آدم وحواء بعد أن أعد الله لهما كل شىء"},"خلقهما فى اليوم السادس ، كقمة لمخلوقاته كلها ، وخلقهما بعد أن خلق من أجلهما كل شىء ، كما فى القداس الغريغورى ، من اجلهما أعد السماء لهما سقفا ، ومهد لهما الأرض كى يمشيا عليها ، رتب لهما قوانين الفلك ، ووضع لهما الشمس لضياء النهار ،"],20:["والقمر لإضاءة الليل . ونظم لهما الطبيعة وأجواءها ، وخلق لهما النبات لطعامهما ، والحيوانات لخدمتهما . واخيرا خلقهما ، ليتمتعا بهذه الطبيعة كلها .","وعندما تنتهى فترة إقامة البشرية على الأرض ، ويأتى الرب على السحاب ، ليأخذ باقى البشر ، ويسكن الانسان فى الأبدية ، حينئذ ستزول هذه الأرض وهذه السماء اللتان خلقهما الله ، لراحة الانسان ههنا ، إذ سيزول غرضهما بانتقال الانسان إلى جوار الله فى اورشليم السمائية .","ما أعظم قيمة هذا الانسان ، الذى من أجله خلق الله كل شىء . آدم صورة الله ، أعظم كائن على الأرض فى أيامه ، نائب الله ، المسلط منه على كل الخليقة الأرضية ...",{h:"٨ ـ وكان آدم وحواء سعيدين ، يعيشان فى جنة :"},"خلق الله جنة جميلة ، لكى يحيا فيها هذا الانسان سعيدا « غرس الرب الإله جنة فى عدن شرقا . ووضع هناك آدم الذى جبله » « تك ٢ : ٨ » . ويشرح سفر التكوين بعض تفاصيل هذه الجنة ، فيقول « وانبت الرب الإله من الأرض شجرة شهية للنظر وجيدة للأكل ، وشجرة الحياة فى وسط الجنة ، وشجرة معرفة الخير والشر . وكان نهر يخرج من عدن ليسقى الجنة » « تك ٢ : ٩ ، ١٠ » .","كان آدم سعيدا هو وحواء داخل الجنة . لم يكن هناك ما ينقصهما ، ولم يكن هناك ما يعكر صفوهما . كان كل شىء حولهما جميلا ، وعاشا فى اليوم السابع ، اليوم الذى قدسه الرب ، واتخذه للراحة ، له ولهما .","وهذه الطبيعه الجميلة الهادئة النقية التى خلقها الله لآدم وحواء ، يقول عنها الكتاب « ورأى الله كل ما عمله ، فإذا هو حسن جدا » « تك ١ : ٣١ » .",{h:"٩ ـ وعاش آدم أيضا فى عشرة الله ..."},"لم تكن سعادة هذا الانسان الأول ، من مجرد خلقه فى طبيعة ممتازة ، أو من سلطته على هذه الطبيعة ، أو من حياته فى جنة جميلة ، إنما لعل السبب الأول فى سعادته ، انه كان يحيا فى عشرة الله ... الله كان يظهر له ، وكان يكلمه ، وكان يباركه ، وكان يعلمه بنفسه ويقدم له الوصايا النافعة له .","كانت له علاقة مباشرة مع الله ، يشرحها سفر التكوين « نفخ فى أنفه نسمة حياة » « واخذ الرب الإله آدم ووضعه فى جنه عدن » وأحضر « الحيوانات » الى آدم ليرى ماذا"],21:["يدعوها « وباركهم الله وقال لهم : « اثمروا واكثروا واملأوا الأرض » « وأوصى الرب الإله آدم قائلا : من جميع شجر الجنة تأكل اكلا . وأما شجرة معرفة الخير والشر فلا تأكل منها »",{h:"١٠ ـ وقد عاش آدم وحواء فى الجنة نباتيين ..."},"* إن أكل اللحوم لم يسمح به الله إلا فى أيام نوح ، بعد خروجه واسرته من الفلك ، إذ يذكر سفر التكوين إن الله بارك نوحا وبنيه بنفس بركة آدم وحواء ، تقريبا ، وقال لهم « كل دابة حية تكون لكم طعاما . كالعشب الأخضر دفعت اليكم الجميع ، غير أن لحما بحياته دمه لا تأكلوه » « تك ٩ : ٣ ، ٤ »","أما ما قبل فلك نوح ، فلم يكن مصرحا بغير النبات ... وهذا ما يذكره سفر التكوين :","* لما خلق الله آدم وحواء ، سمح لهما بأكل الفاكهة والبقول ، أى ثمار الاشجار ، وذلك بقوله « إنى قد أعطيتكم كل بقل يبذر بذرا على وجه كل الأرض ، وكل شجر فيه ثمر شجر يبذر بذرا ، لكم يكون طعاما » . « ولكل حيوان الأرض ، وكل طير السماء وكل دابة على الأرض فيها نفس حية ، أعطيت كل عشب أخضر طعاما ، وكان كذلك » . « تك ١ : ٢٩ ، ٣٠ » .","* اذن لم يكن الانسان وحده نباتيا فى الجنة ، وإنما حتى الحيوانات أيضا بكل انواعها كانت نباتية : للانسان الثمار والبقول ، وللحيوان العشب الأخضر . ولم يكن هناك افتراس . لا الانسان يأكل الحيوان ، ولا الحيوان يأكل الانسان ، ولا الحيوان يأكل بعضه بعضا .","* وبعد السقوط فى الخطية : لما حدث أن الانسان ، كالحيوان اشتهى أن يأكل ، اعطاه الله الطعام المخصص للحيوان ، عشب الأرض . فقال الرب للانسان بعد السقوط « وتأكل عشب الأرض » « تك ٣ : ١٨ » ، وكان العشب مخصصا للحيوان من قبل « تك ١ : ٣٠ » .","وبقى الانسان بعد السقوط نباتيا ، يأكل ثمار الشجر والبقول والعشب ، بعد طرده من الجنة ، دون أن يأكل اللحوم ، لم يصرح له بها ، إلا بعد فلك نوح « تك ٩ : ٣ » .","* ومع ذلك كانت الأعمار طويلة جدا ، فى تلك الفترة من آدم حتى نوح ، كما يشرح الاصحاح الخامس من سفر التكوين :","عاش آدم ٩٣٠ سنة « تك ٥ : ٥ » ، وعاش نوح ٩٥٠ سنة « تك ٩ : ٢٩ » ، وعاش متوشالح ٩٦٩ سنة « تك ٥ : ٢٧ » ، وهو صاحب أطول عمر فى كل أجيال البشرية ، وكان نباتيا ."],22:[{h:"* لماذا اذن صرح الله بأكل اللحوم بعد فلك نوح ؟"},"يقول الكتاب « قبل الطوفان مباشرة » : « ورأى الرب أن شر الانسان قد كثر فى الارض ، وأن كل تصور أفكار قلبه إنما هو شرير كل يوم ، فحزن الرب أنه عمل الانسان فى الارض » « تك ٦ : ٥ ، ٦ » . وهكذا أغرق الرب العالم بالطوفان . وأبقى الرب بقية من البشرية . وسمح لها بأكل اللحوم ، لأن مستوى البشر لم يكن يحتمل غير هذا ...","(صفحة صورة بلا نص في الملف: رسم لآدم وحواء والحية بين أشجار الجنة)"],23:[{h:"خطايا عديدة لأبوينا الأولين"},"كانت طبيعتهما سامية جدا ، ولكنهما كانا يتمتعان فى نفس الوقت بحرية الارادة ، وبالحرية توجد امكانية السقوط .","والعجيب أن كثيرا من الكتاب يتحدثون عن خطية آدم أو خطية حواء ، كما لو كانت خطية واحدة لاغير !! بينما وقع ابوانا فى عديد من الخطايا ، نذكر منها هنا ٢٧ خطية ، بنوع من التحليل ، لكى نتعلم نحن أيضا التدقيق فى محاسبتنا لأنفسنا ... فما هى هذه الخطايا ؟",{h:"١ ـ العصيان أو المخالفة"},"وهذه هى الخطية الواضحة للكل . إن الله أمر ابانا آدم قائلا « من جميع شجر الجنة تأكل أكلا . وأما شجرة معرفة الخير والشر فلا تأكل منها . لأنك يوم تأكل منها موتا تموت » « تك ٢ : ١٦ ، ١٧ » . الخطية واضحة ، وقد سمعها آدم بنفسه من فم الله . وكانت تحفظها حواء « تك ٣ : ٢ » . ومع ذلك خالفها آدم وخالفتها حواء","ولو لم ينذر الله آدم وحواء من قبل ، لقلنا إنها ربما كانت خطية جهل . ولكن من الواضح انها خطية بمعرفة",{h:"٢ ـ المعاشرات الردئية"},"بدأت سلسلة الخطايا التى وقع فيها آدم وحواء بخطية « المعاشرات الردية التى تفسد الاخلاق الجيدة » « ١ كو ١٥ : ٣٣ » . فجلست أمنا حواء مع الحية « وكانت الحية أحيل جميع حيوانات البرية التى عملها الرب الاله » « تك ٣ : ١ » .","وحتى إن كانت امنا حواء ، بنقاوة قلبها وبساطتها ، لا تدرك ما فى الحية من خبث ، فانه كان يجب عليها أن تنتبه ، حينما أخذت الحية تكشف أوراقها ، وتقول كلاما عكس ما قاله الله نفسه لهما !!","ولكن امنا القديسة بدلا من أن تنتبه ، وقعت فى خطية الانقياد ، ووقعت أيضا فى خطية الشك . وقادتها هاتان الخطيتان إلى سقطات اخرى كثيرة",{h:"٣ ـ خطية الشك"},"قالت الحية فى خبث وهى تبذر بذور الشك « أحقا قال الله لا تأكلا من كل شجر"],24:["الجنة ؟! » .. أحقا ان الله الرحيم الطيب يمنعكما عن الأكل من كل الشجر ؟ وماذا يضيره لو جعلكما تأكلان ؟ أى شر فى هذا ؟!","فلما أجابت المرأة حسنا ، أخذت الحية تتعمق فى القاء بذور الشك ، فقالت « كلا ، لن تموتا ، بل الله عالم انكما يوم تأكلان منها تنفتح أعينكما ، وتكونان مثل الله عارفين الخير والشر » .. اذن الله خائف من أن تصيرا مثله ، لذلك يمنعكما ... ليس حبا منه لكما ، أو حرصا عليكما ، انما خشية من المنافسة ...","هذا هو الشك الذى القته الحية فى نفس حواء :",{h:"الشك فى صدق كلام الله ، والشك فى حب الله للبشر ، بل الشك أيضا فى انذار الله لهما بالموت . فهما ـ حسب كلام الحية ـ لن يموتا ، بل ستتحسن احوالهما ..."},"واستسلمت حواء إلى هذا الشك ، فسلمها إلى خطيئة اخرى :",{h:"٤ ـ خطية الانقياد"},"انقادت ـ وهى صورة الله ومثاله ـ الى الحية ومشورتها . فبدلا من أن تنتهر الحية على التشكيك فى كلام الله ، اطاعتها . وبهذا فقدت شخصيتها أمام إلحية ، بينما كان الله قد اعطاها سلطانا على جميع حيوانات الارض وعلى كل ما يدب على الارض ، فكانت الحية بذلك تحت سلطانها ، وكانت تملك أن تخضعها ، حسب قول الرب عن هذه الكائنات « واخضعوها » « تك ١ : ٢٨ » . فبدلا من إخضاعها ، خضعت لها .",{h:"ونفس هذا الانقياد الخاطىء ، الذى وقعت فيه حواء ، حدث بالنسبة الى ابينا آدم من جهة امراته حواء ، بينما الرجل رأس المرأة . وكان يجب على آدم ان يقود حواء الى الخير ، ويرفض ان يأكل الثمرة المحرمة من يدها ، ولكنه انقاد هو ايضا وأطاع . ووقع فى نفس ضعف الشخصية الذى وقعت فيه حواء ."},"لذلك فإن الله لم يقبل من حواء عبارة « الحية اغرتنى » . ولم يقبل من آدم عبارة « المرأة اعطتنى » .",{h:"كان يجب على كل منهما أن يكون قوى الشخصية ، ولا يقبل من غيره أية نصيحة أو أى توجيه ضد وصية الله الواضحة ."},"وكان انقياد حواء للحية ، يحمل داخله خطية اخرى هى :"],25:[{h:"٥ ـ ضعف الايمان"},"انقياد حواء للحية ، معناه أنها قبلت كلامها أكثر من كلام الله ، أو قل إنها صدقت الحية وكذبت الله . الله يقول عن ثمر الشجرة « لا تأكلا منه ولا تمساه ، لئلا تموتا » « تك ٣ : ٣ » . والحية تقول « كلا ، لن تموتا » . والمرأة تقبل كلام الحية ، وتميل إليه بقلبها ، وتترك كلام الله ، لا تخشاه ، ولا يتعبها انذاره ...",{h:"إذن فهذا ضعف ايمان بالله وبكلمته وبانذاره ، بل هو عدم ايمان بصدق الله ..."},"وضعف الايمان هذا ، قادها إلى خطية اخرى وهى :",{h:"٦ ـ الاستهانة وعدم مخافة الله"},"بدأت تستهين بحكم الله وبتهديده وعقوبته ، ولم تخف اطلاقا من أن تمد يدها وتأخذ ، كما لو كانت عبارة « موتا تموتا » ، لا تهز لها جفن ، ولا تحرك ضميرها أو قلبها ... !","على أن إغراء الحية وحديثها ، قاد المرأة إلى خطية اخرى ، ونست قلبها الطاهر ، وهى خطية الشهوة .",{h:"٧ ـ خطية الشهوة"},"نظرت المرأة الى الشجرة ، فاذا هى « جيدة للأكل ، وبهجة للعيون ، وإذا الشجرة شهية للنظر » ... فاشتهتها ...","كانت شجرة معرفة الخير والشر فى وسط الجنة ، وربما كانت حواء تمر عليها كل يوم وتراها . وكانت نظرتها إليها بسيطة ، لا تحمل شهوة ...",{h:"أما الآن فإن النظرة قد تغيرت ، لم تعد بسيطة كما كانت امس وقبلا من أمس ، ذلك لان القلب قد تغير ..."},"القلب قد دخلته شهوة ، فأصبحت نظرته إلى الشجرة مشبعة بالشهوة . وبالشهوة صارت الشجرة شيئا آخر مشتهى ، بل شيئا مفضلا على الكل ، حتى على وصية الله . صارت الشجرة « جيدة للأكل ، وبهجة للعيون ، وشهية للنظر » ...","لماذا ؟ لأن خطية اخرى قد دخلت القلب ... فما هى ؟",{h:"٨ ـ خطية الكبرياء"},"« يوم تأكلان منها تنفتح أعينكما وتصيران مثل الله ... » . هنا الاغراء الجبار"],26:["« تصيران مثل الله » أو تصيران الهين ... ! إن كان الأمر هكذا ، فلماذا نرضى ونكتفى بالمستوى البشرى ؟! ولماذا نأخذ من الله موقف الطاعة ، بدلا من موقف المساواة ؟! وعصفت شهوة الألوهية بهذه الإنسانة المسكينة فدخلتها الكبرياء .","واستطاعت هذه الكبرياء أن تحطمها ، كما حطمت الشيطان من قبل لأنه أراد أن يوقع الانسان فى نفس السقطة التى وقع فيها ... وماذا كانت سقطته ؟ يحكيها سفر أشعياء النبى فيقول :","« كيف قطعت الى الأرض يا قاهر الأمم ؟ وأنت قلت فى قلبك : اصعد إلى السموات ، أرفع كرسى فوق كواكب الله ... أصعد فوق مرتفعات السحاب ، أصير مثل العلى . لكنك انحدرت الى الهاوية ، الى أسافل الجب » « أش ١٤ : ١٢ ـ ١٥ »",{h:"إن عبارة « أصير مثل العلى » التى قالها فى قلبه ، هى نفس عبارة « تصيران مثل الله » التى اغرى بها حواء ..."},"إن الكبرياء هى التى أسقطت الشيطان ، وهى التى أسقطت الانسان الأول . وكما قال أحد القديسين : إن حواء اشتهت مجد الألوهية ، ففقدت ما كان لها من مجد البشرية .","على أن هذه السقطة ، وهذه الكبرياء ، كانت تحمل فى داخلها شهوة أخرى ، أو خطية أخرى ، وهى .",{h:"٩ ـ المعرفة المحرمة"},"« تصيران مثل الله ، عارفين الخير والشر » ... لقد قدم الشيطان للانسان هذا الاغراء ، إغراء المعرفة ... إلى متى تظل مقفل العينين لا تعرف ؟ ليتك تأكل لكى تنفتح عيناك المغمضتان ، وتذوق الدنيا وتعرفها ...","إلى متى يغلق الله عليكما فى هذه البساطة أو السذاجة ، التى يسمونها النقاوة أو البراءة ؟! فتظلان هكذا لا تدريان ولا تفهمان الجمال الموجود فى الدنيا ، واللذة الموجودة فى الثمرة ؟! لماذا يحرمكما الله من هذه المعرفة ؟!","أية معرفة يقصدها الشيطان ؟ لقد وهبهما الله فضل معرفته ، وجعلهما يعرفان الخير والبر ويذوقان ما فى هذه المعرفة من لذة . يجيب الشيطان إنهما حرما من معرفة الخير والشر » .","وهنا تبدو الخدعة الكبرى التى انطلت على حواء ... فما هى ؟",{h:"إنهما يعرفان الخير فقط ، والشيطان يريد لهما الآن « معرفة الخير والشر » أى أن تضاف إلى معرفتهما النقية ، معرفة الشر ...!"},"يا للخدعة الخبيثة ، التى قال عنها الحكيم « الذى يزداد علما ، يزداد غما » ، يقصد المعارف التى تشوه نقاوة الانسان ، أو تربك سلامه فكره ..."],27:["وأكل الانسان من شجرة المعرفة ، فصار جاهلا ... لأنه أخذ معرفة الشر إلى جوار معرفة الخير ، وماذا أصابه أيضا ؟!",{h:"١٠ ـ مشكلة الثنائية وفقدان البساطة"},"ومن ذلك اليوم ، والانسان يعيش معذبا ، يسبح فى بحر العالم ، يحيطه شاطئان : الخير والشر ، الحلال والحرام ، الصالح والطالح ، ما ينبغى وما لا ينبغى .","وللأسف ، فإن معرفة الشر عند كثيرين ، أرتبطت بشهوة الشر ، أو على الأقل ارتبطت بالصراع بين الخير والشر . وعاش الانسان حياته فى هذا الصراع ، وتشوهت أفكاره بمعرفة الشر ، وجلبت له هذه المعرفة الظنون والأفكار ، ووضعت فى عقله الواعى أو عقله الباطن صورا متعبة ، تظهر أحيانا كأحلام ، وأحيانا كشكوك وظنون ، وأحيانا كإدانة للآخرين ، أو كاشمئزاز من وضع معين ، أو كخوف من سقوط ... أو ارتياب فى نقاوة .",{h:"ولما أكلت حواء من شجرة المعرفة هذه ، بدأت ترى آدم رجلا يختلف عن أنوثتها . وبدأ آدم يراها أنثى تختلف عن رجولته . وبدأ الجنس يفتح أبوابه ."},"وكان أول باب هو الخجل . وأحس آدم وحواء أنهما عريانان ، وفكرا كيف يستران عريهما ... فقد الاثنان بساطتهما الأولى ...","ما كان أغناهما عن هذا كله ، لو أنهما لم يطلبا هذه المعرفة ، أو على الأقل طلبا المعرفة من الله وحده . ولكنهما وقعا فى خطية أخرى وهى :",{h:"١١ ـ طلب المعرفة من غير الله"},"كان الله هو المعلم الأول والوحيد للإنسان ، يعطيه من المعرفة ما يفيده وما يبقى على نقاوته .",{h:"ثم بدأ الانسان يتخذ له مرشدا غير الله ، يشير عليه بما يفعل ، ويعطيه معرفة اخرى . وكان هذا المرشد للأسف ، هو الشيطان الذى دخل الحية ، وأرشد الإنسان إلى ما فيه هلاكه ..."},"وشهوة المعرفة ، بعيدة عن الله ، ومن غير الله ، ملأت الانسان بمعارف ضيعته . ومازال الانسان يسعى إلى المعرفة منذ أكل من الشجرة . وفى كل يوم تنفتح عيناه بالأكثر ... وتجمع له الحواس أحيانا ما يضره ...","ويستمر فى ثنائية المعرفة ، التى تشمل الخير والشر ، إلى أن يهب له الله فى الابدية اكليل البر ، فيتقيأ ما أكله من معرفة الخير والشر ، ويعود لا يعرف غير الخير وحده ،"],28:["وينسى فى النعيم الأبدى ما كان قد عرفه فى العالم من شر . يمحو الله من ذاكرته ومن علمه ومعرفته كل معرفه الشر ، فى الانسان الجديد الذى يقوم من الأموات فى نقاوة لا تعرف شرا .",{h:"ويصير الجميع متعلمين من الله « يو ٦ : ٤٥ » . ولا يعود الشيطان يعلم ويرشد ويلقى أفكاره فى عقول الناس ... بل فى الأبدية ستأخذ معرفة بديلة ، هى معرفة الله الذى يكشف لنا ذاته . وكما قال ربنا يسوع المسيح لله الآب « هذه هى الحياة الأبدية ، أن يعرفوك أنت الاله الحقيقى وحده ، ويسوع المسيح الذى أرسلته » « يو ١٧ : ٣ » ."},"حينئذ يكون الله هو مصدر معرفتنا ، وكفه معرفتنا ، وتبطل مشورة الشيطان الذى أسقط أمنا حواء فى القديم ، فأكلت ...","وظهرت فى اكلها خطيئة اخرى وهى :",{h:"١٢ ـ حفظ الوصية عقلا لا اعمالا"},"كانت حواء تحفظ الوصية حفظا عقليا ! لذلك عندما سألتها الحية « أحقا قال الله لا تأكلا من كل شجر الجنة ؟ » ، صححت لها حواء منطوق الآية ، وذكرت تفاصيلها ، فقالت للحية « من ثمر شجر الجنة نأكل . وأما ثمر الشجرة التى فى وسط الجنة ، فقال الله لا تأكلا منه ولا تمساه لئلا تموتا » . أنه حفظ دقيق لم يكتف بالمنع عن الاكل ، بل عن اللمس أيضا ..",{h:"والعجيب أنها فى نفس الوقت الذى ذكرت فيه الوصية بهذه الدقة المعجبة ، عادت وكسرت الوصية ، ومدت يدها وقطفت وأكلت ... ! لقد حفظت الوصية عقلا لا عملا ..."},"أنها تذكرنى بالشاب الغنى الذى كان يحفظ الوصايا ، وقال عنها للسيد الرب « هذه حفظتها منذ حداثتى » . وفى نفس المناسبة مضى حزينا ، لأنه كان يعبد إلها آخر هو المال ، بينما تقول الوصية الأولى « لا تكن لك آلهة أخرى أمامى » « خر ٢٠ : ٣ » .","وفى الأكل من الشجرة ، وقعت حواء ، كما وقع آدم أيضا فى خطية أخرى وهى :",{h:"١٣ ـ الانحدار الى المستوى الجسدانى"},"الأكل ، وشهوة الأكل ، والنظر إلى الشجرة على أنها « جيدة للأكل » ... كلها أمور جسدانية انحدر إليها آدم وحواء ، بأسباب نفسانية ، سقطا بها عن المستوى الروحى ."],29:[{h:"ولذلك اعتبر البعض أى الوصية الأولى التى اعطيت للإنسان ، كانت وصية صوم ، تشبه صومنا فى هذه الأيام ، تأكل من الكل ماعدا نوعا واحدا هو الأطعمة الحيوانية . كذلك أعطى لآدم وحواء أن يأكلا من الكل ماعدا نوعا واحدا هو ثمر هذه الشجرة ."},"ولكن آدم وحواء كسرا هذا الصوم ، وأكلا من هذا الصنف المحرم . وبالأكل سقطا من المستوى الروحى إلى المستوى الجسدى .","وبهذا السقوط ، استمرت معهما حروب الجسد فيما بعد ، حتى أن بعض العقوبات التى فرضها الله عليهما ، كانت تحمل اشارة إلى هذا المستوى الجسدانى الذى هبطا إليه :","قال للمرأة « تكثيرا أكثر اتعاب حبلك ، بالوجع تلدين أولادا » .","وقال لآدم « أنك سمعت لقول امرأتك ، وأكلت من الشجرة التى أوصيتك قائلا لا تأكل منها ، ملعونة الأرض بسببك . بالتعب تأكل منها كل أيام حياتك ... بعرق جبينك تأكل خبزا ... وتأكل عشب الحقل » « تك ٣ : ١٦ ـ ١٩ »","هذه عقوبة الأكل . على أنه فى الأكل من الشجرة كانت توجد خطية أخرى :",{h:"١٤ ـ عدم القناعة"},"الله أعطى أبوينا الاولين أن يأكلا من كل شجر الجنة ، ماعدا واحدة . ولاشك أنه كانت توجد أثمار كثيرة جدا فى الجنة ، بل كان فيها كل نوع ثمر ... ولكن هذا كله لم يقتنع به آدم وحواء ولم يكفهما ، بل أرادا الأكل من هذا النوع الواحد الناقص . وهذا يدل على عدم القناعة .","ومازال مرض عدم القناعة موروثا حتى الآن « العين لا تشبع من النظر ، والاذن لا تشبع من السمع » « وكل الأنهار تجرى إلى البحر والبحر ليس بملآن » .","على أن حواء فى أكلها من الثمرة المحرمة ، لم تقع فقط فى كل هذه الخطايا ، إنما أضافت إليها خطية أخرى وهى :",{h:"١٥ ـ إعثار الآخرين"},"لم تقتصر أمرها على كسر الوصية والأكل من الشجرة ، وإنما يقول الكتاب إنها « أكلت ، وأعطت رجلها أيضا معها فأكل » « تك ٣ : ٦ » . وهكذا جرت غيرها إلى الخطأ ، وقادته إلى كسر الوصية ، وكانت سببا فى ضياعه ، ووضعت أول بذرة للعثرة ، ولإعثار الآخرين ..."],30:[{h:"والعجيب أن البعض يظنون أن خطية آدم وحواء هى مجرد الاكل من الشجرة ! فعلى الرغم من كل الخطايا التى ذكرناها ، توجد خطايا أخرى كثيرة ارتكبها أبوانا بعد الاكل من الشجرة ."},"فما هى هذه الخطايا ؟",{h:"١٦ ـ تغطية الخطية بأوراق التين"},"لما أكلا « انفتحت أعينهما ، وعلما أنهما عريانان » ، إذ فقدا نقاوتهما ، وفقدا بساطتهما الأولى . فبدلا من معالجة الخطية والتخلص منها ، والرجوع إلى النقاوة الأولى ، قاما بتغطية الخطية بأوراق التين . وهكذا تغطى آدم وحواء ولكن بقى القلب من الداخل غير سليم ، والشعور كما هو ...",{h:"واصبحت أوراق التين ترمز إلى تغطية الخطية ، دون التخلص منها ."},"ولهذا نرى أن الرب لم يوافق على فكرة أوراق التين . « وصنع الرب الاله لآدم وامرأته اقمصة من جلد والبسهما » « تك ٣ : ٢١ » .","ومن أين أتت اقمصة الجلد ؟ لعلها أتت من ذبيحة ، سفك دمها لأجلهما ، وتغطيا بجلدها . وهنا بدا الرمز العميق :",{h:"الخطية تعرى الانسان وتخجله ، والذبيحة تغطيه وتستره ، بل وتطهره ..."},"انه معنى ربما يكونان قد عرفاه بسيطا فى بادىء الأمر ، وأتى التعمق فيه على مر الزمن فيما بعد .","بعد الخطية ، شعر آدم وحواء بالعرى ، وبالخزى ، فاستترا بأوراق التين ... وماذا بعد ؟ لقد وقعا فى خطية أخرى كبيرة وهى :",{h:"١٧ ـ الهروب من الله"},"« سمعا صوت الرب الاله ماشيا فى الجنة ، عند هبوب ريح النهار ، فاختبأ آدم وامرأته من وجه الرب الاله فى وسط شجر الجنة » « تك ٣ : ٨ »","أصبح هناك تباعد بينهما وبين الله ... وجدت هوة فاصلة ... لم يعودا يفرحان بالوجود فى حضرة الرب . فحالما سمعا صوته مقبلا ، هربا من وجهه واختفيا ...","وصار الهروب من الله خطية موروثة فى نسل آدم وحواء . فما أن يقع الانسان فى"],31:["الخطية ، حتى يبدأ فى سلسلة من الهروب : يهرب من الصلاة ، لأنه يخجل من الكلام مع الله وهو فى الخطية ! ويهرب من الكنيسة ، ومن أب الاعتراف ، ومن الاجتماعات الروحية ، ومن الأصدقاء الروحيين ، إلى أن يقطع كل صلة له بالله ...!",{h:"ولعل الهروب من الله ، بالنسبة إلى آدم وحواء ، قد دفعت إليه خطية اخرى وهى الخوف"},{h:"١٨ ـ الخوف"},"والخوف إن لم يكن خطية فى حد ذاته ، فعلى الأقل هو انحدار فى المستوى ، إنحدار من مستوى الحب الالهى الذى كانا يعيشان فيه . ويقول القديس يوحنا الرسول « لا خوف فى المحبة ، بل المحبة الكاملة تطرح الخوف إلى خارج . لأن الخوف له عذاب . وأما من خاف ، فلم يتكمل فى المحبة » « ١ يو ٤ : ١٨ » .","واضح من إجابة أبينا آدم أنه خاف . ولا نقصد المخافة التى تحمل مهابة الله ، وإنما الخوف بمعناه الحرفى ، الذى يدعو إلى الهرب والاختفاء . وفى هذا يقول للرب « سمعت صوتك فى الجنة فخشيت ، لأنى عريان فاختبأت » « تك ٣ : ١٠ » .",{h:"وبالنسبة إلى آدم وحواء ، لا نقول فقط إنهما نزلا من مستوى الحب ، بل عملا أعمالا ضد محبة الله ."},{h:"١٩ ـ الخروج من محبة الله"},"* لاشك أن كسر الوصية كان عملا ضد محبة الله . لأن الرب يقول « الذى عنده وصاياى ويحفظها فهو الذى يحبنى » « يو ١٤ : ٢١ » . ويقول القديس يوحنا الحبيب « من قال قد عرفته ، وهو لا يحفظ وصاياه ، فهو كاذب وليس الحق فيه . وأما من حفظ كلمته ، فحقا فى هذا قد تكملت محبة الله » « ١ يو ٢ : ٤ ، ٥ » . اذن كسر الوصية ضد المحبة .","* ورغبة آدم وحواء فى أن يصيرا « مثل الله » حسب اغراء الحية ، كان عملا آخر ضد محبتهما لله .","* وتصديق كلام الحية ، عكس كلام الله ، كان أيضا عملا ثالثا ضد محبة أبوينا الأولين لله .","* وفى مناقشتهما مع الله ، كانت الطريقة لا تتفق والمحبة","* وهروبهما من وجه الله ، واختفاؤهما ، كان عملا رابعا منهما ضد محبة الله"],32:["كذلك فى خوف أبوينا واختبائهما ، وقعا فى خطية اخرى ، وهى عدم السعى للصلح مع الله .",{h:"٢٠ ـ عدم السعى إلى الخلاص"},"انهما انسانان قد كسرا وصية الله ، واصبح محكوما عليهما بالموت . فماذا فعلا للتخلص من حكم الموت هذا ؟ هل سعيا إلى الخلاص ؟ هل بذلا جهدهما لكى يصطلحا مع الله ، ولكى يعودا إلى علاقة الحب الاولى ؟ كلا .","لقد شل الخوف تفكيرهما ، فلم يقوما بأى عمل من أجل خلاص نفسيهما الهالكتين ، انما اكتفيا بالاختفاء من وجه الله .","وفى الاختفاء من وجه الله فى وسط الشجرة وقعا فى خطية اخرى وهى الجهل بالله وقدرته ...",{h:"٢١ ـ الجهل بالله وقدرته"},"إلى اين يهرب هذان المسكينان من وجه الرب ؟ وأين يختفيان ؟ لقد كان حفيدهما داود أكثر معرفة بالله حينما قال","« أين اذهب من روحك ؟ ومن وجهك اين اهرب ؟ إن صعدت إلى السموات فأنت هناك . وإن فرشت فى الهاوية فها أنت ... » « مز ١٣٩ : ٧ ، ٨ » ... فما معنى الاختباء وسط الشجر اذن ؟!","هل الشجر يخفيهما عن عين الله الفاحصة الخفيات والظاهرات ؟ أم أنهما جهلا قدرة الله على كل شىء ...","حقا إن الانسان لما أكل من شجرة المعرفة صار جاهلا ، لقد وعده الشيطان وعدا زائفا لم يبر به ...","وفى المناقشة بين الله وأبوينا الأولين ، نرى فى أجابتهما عددا كبيرا من الأخطاء ، منها",{h:"٢٢ ـ عدم ادانة النفس"},"إن كان هذا الانسان قد اكل من شجرة المعرفة ، وعرف الخير والشر ، فعلى الأقل اصبح يعرف أنه قد أخطأ .","ولكن كلمة « أخطأت » لم يقلها آدم اطلاقا ، ولم تقلها حواء .","لم يعترف احد منها بهذه الخطايا التى ذكرناها ، ولا بشىء منها . لم يقم احد منهما"],33:["بإدانة نفسه ، ولم تكن لأى منهما حكمة القديس مقاريوس الكبير الذى قال « أحكم يا أخى على نفسك ، قبل أن يحكموا عليك » ...","وياليتهما لم يدينا نفسيهما وصمتا ، بل انهما وقعا فى خطية أصعب ، وهى محاولة تبرير النفس ...",{h:"٢٣ ـ محاولة تبرير النفس"},"كل منهما حاول أن يبرر نفسه . حاول أن يوجد لنفسه عذرا أو أعذارا يغطى به خطيته ، أو يقلل من الجرم الذى وقع فيه . ولم يقبل الله شيئا من تبريراتهما وأعذارهما ، لأن الخطية واضحه .",{h:"امام الله يستد كل فم . وإن تكلم الانسان ، فإنما ليعترف ويدين نفسه ويطلب الرحمة ، وليس غير . أما محاولة تبرير النفس ، فهى نوع من المكابرة والكبرياء ."},"وفى تبرير كل من آدم وحواء لنفسه ، وقع فى خطية أخرى وهى القاء التبعة على الآخرين .",{h:"٢٤ ـ القاء التبعة على الآخرين"},"حواء ، تلقى التبعة فتقول « الحية غرتنى فاكلت » . وآدم يلقى التبعة على حواء « المرأة أعطتنى فاكلت » ...",{h:"ولا يلقى احد منهما بالتبعة على نفسه ..."},"ولم يكن إلقاء التبعة على الآخرين عذرا مقبولا : فآدم كان يستطيع أن يرفض الأكل ، ولا يسمع لحواء ، بل كان يستطيع أن يوبخها ، بل أكثر من هذا كان يمكنه أن ينصحها ويمنعها قبل الوقوع فى الخطية .","أما أن تقدم له من الثمرة فيأكل دون تفكير ، دون امتناع ، دون تذكر للوصية ، دون تذكر للعقوبة ، فهذا أمر لا يقبله أحد .","وحواء بالمثل ، كانت تستطيع أن ترفض إغراء الحية ...","وحينما ألقى آدم بالتبعة على حواء ، إنما وقع ضمنا فى خطية أخرى ، تخدش المحبة التى بينهما .",{h:"٢٥ ـ ضد محبة القريب"},"كما كسر آدم محبته لله ، كسر أيضا محبته للقريب . والقريب الوحيد هنا كان حواء . أتهمها أمام الله ، وحملها تبعة سقوطه فى الخطية .","وهكذا ألقى أول بذرة للخلافات الزوجية . ونشكر الله أن حواء لم ترد على آدم ، ولم تدخل معه فى مناقشة ، بل لزمت الصمت ، ومرت المشكلة من جهتها بسلام .","على أن اتهام آدم لحواء ، كان يحمل خطية أخرى :"],34:[{h:"٢٦ ـ الاختفاء وراء امرأة"},"ما كان يليق بأبينا آدم ـ الرجل الأول فى البشرية أن يختفى وراء امرأة لكى ينجو ! يقدمها للاتهام ، ويحملها المسئولية ، لكى يتبرر هو !","الأمر المثالى ، أن يتحمل اخطاءها ، وينسبها لنفسه ، كمسئول ، وينجيها من العقوبة ، ويتصدر الموقف ويتركها تختفى وراءه . يحمل خطاياها ، كما حمل المسيح خطايا عروسه الكنيسة ... لكن آدم فعل العكس .","لا أريد أن أعلق على الموقف بأكثر من هذا ! ...",{h:"٢٧ ـ عدم اللياقة فى الحديث"},"وفى دفاع آدم عن نفسه بإلقاء التبعة على المرأة ، فقد الليافة اللازمة فى التحدث مع الله نفسه ...!",{h:"فلم يكتف بقوله « المرأة أعطتنى فاكلت » وإنما قال له : « المرأة التى جعلتها معى ، هى أعطتنى »"},"وكأنه بهذا يشرك الله فى المسئولية ، أو يجعل الله صاحب السبب فى سقوطه ، لأنه أعطاه المرأة التى أعطته الثمرة ...! وكان تعبيرا غير لائق من جهة ادب الحديث مع الله . ولم يرد الله عليه ...","من هذه السقطات التى وقع فيها أبوانا الاولان سنستنتج :","* أن الخطايا ليست عواقر ، وأنها تلد خطايا أخرى ... ويكفى أن يجر الانسان أول الخيط ، لكى ينساب كله ، ويجد أن خطية تقوده إلى اخرى ... إلى غير انتهاء ...","* كذلك نستنتج أنه يلزمنا التدقيق فى محاسبتنا لأنفسنا وفى اعترافاتنا ...","فربما نظن أننا اقترفنا شيئا بسيطا ، بينما هذا الشىء يحوى العديد من الخطايا ، التى ربما تخفى عن معرفتنا ، ولكننا بقليل من التحليل ندركها ...","وها قد رأينا كيف سقط أبوانا آدم وحواء ، وكيف بدأ الفساد ينخر فى الطبيعة البشرية على مدى العصور ، حتى أتلفها تماما .","بقى أن نتأمل نتائج السقطة الأولى للبشرية :"],35:[{h:"نتائج هذه الخطايا وعقوباتها"},{h:"١ ـ اللعنة"},{h:"* اللعنة لم تصب أدم وحواء لسببين :"},"أولا : لأن الله كان قد باركهما قبلا « تك ١ : ٢٨ » وهبات الله بلا ندامه « رو ١١ : ٢٩ » ، لا يرجع فيها مهما حدث . إنها لا تتوقف على أمانتنا ، بقدر ما تتوقف على جوده هو وكرمه ...","ثانيا : لأنه لو لعن آدم وحواء ، لكانت اللعنة قد أصابت الجنس البشرى كله ، الموجود فى صلبيهما ، كما لعن فيما بعد كنعان وكل نسله ، وقابين وكل نسله ...","ولا يمكن أن يلعن الجنس البشرى كله ، ومنه سيأتى أنبياء وأبرار يباركهم الرب ويكونون بركة ... بل من نسل آدم سيأتى السيد المسيح ـ حسب الجسد ـ الذى سيسحق رأس الحية ، وبه « تتبارك جميع قبائل الأرض » « تك ١٨ : ٢٢ » .",{h:"* ولكن اللعنة أصابت الحية التى أغرت حواء بأكل الثمرة . وكذلك أصابت اللعنة الأرض التى تخرج ثمرا للأكل :"},"١ ـ فقال الله للحية « ملعونة أنت من جميع البهائم ومن جميع وحوش البرية . على بطنك تسعين ، وترابا تأكلين كل ايام حياتك . واضع عداوة بينك وبين المرأة ، وبين نسلك ونسلها . هو يسحق رأسك ، وانت تسحقين عقبه » « تك ٣ : ١٤ ، ١٥ »",{h:"ونلاحظ أن لعنة الحية ، كانت تحمل عقوبة ضمنية للإنسان"},"أصبحت هناك عداوة بينه وبين الحية ، ولم توجد من قبل أية عداوة وبين أحد من الخليقة كلها ، كما أن سلطانه على الحيوان قد اهتز ، فصارت الحية تستطيع أن تسحق عقبه ، وتؤذيه ! وهو الذى كان ملكا مسلطا على كل أنواع الخليقة . وهكذا ضاع جزء من هيبته ومن سلطته ...","على أن سلطان الحية قد اهتز عندما أعطانا السيد المسيح سلطانا أن ندوس الحيات والعقارب وكل قوة العدو ، وانتهى حينما سحق المسيح رأس الحية ... وعبارة « وترابا تأكلين كل ايام حياتك » ، فيها تعريض بالانسان الذى قال له الرب فى نفس المناسبة « أنت تراب والى التراب تعود » « تك ١٤ : ١٩ » .","الانسان البار ، هو صورة الله ومثاله . أما الإنسان الخاطىء فهو تراب ، وكتراب يصير"],36:["طعاما للحية ، لأنها تأكل ترابا كل أيام حياتها ... هذا هو المعنى الرمزى كما تأمله القديس اوغسطينوس ...",{h:"وفى داخل هذه العقوبة التى أوقعها الله على الحية ، وضمنا على الانسان ، كان يوجد الوعد بالخلاص ..."},"وعد بأن نسل المرأة سيسحق رأس الحية . وهذه كانت أول نبوءة عن مجىء السيد المسيح لخلاصنا .","ويظهر لنا هذا الوعد حنو الله على الخطاة ، ويزيده عمقا أنه وعد بالخلاص ، وعد به الله فيما هو يعاقب ويقتص من الخطية . حقا إن عدله مملوء رحمة ، وأنه رحيم فى عدله ، وصفاته لا تنفصل عن بعضها البعض ...","إن الله لم يلعن الانسان ، ولكنه لعن الحية التى أغوت الانسان ، وكانت فى لعنتها ، عقوبة ضمنية للانسان . كذلك لعن الله الارض التى يعيش عليها الانسان .",{h:"* وفى اللعنة التى أصابت الأرض ، كانت توجد أيضا عقوبة ضمنية موقعة على الانسان نفسه :"},"كانت لعنة الارض ضمن العقوبة التى أوقعها الله على الانسان ، إذ قال له « ملعونة الأرض بسببك . بالتعب تأكل منها كل أيام حياتك . وشوكا وحسكا تنبت لك ، حتى تعود إلى الأرض التى أخذت منها ... » « تك ٣ : ١٧ ـ ١٩ »",{h:"بهذه اللعنة بدأت الأرض تتمرد على الانسان ، كما أصبحت الحيوانات تتمرد عليه ، ممثلة فى الحية ، وهكذا فقد الانسان هيبته ، فيما كانت تعده الحية بالالوهية !!"},"أول تمرد للأرض ، يكمن فى عبارة « بالتعب تأكل منها كل أيام حياتك » . الأرض المباركة ، لا يتعب فيها الانسان . أما الارض الملعونة فتتعبه . كان آدم قبل الخطية يعمل فى الجنة ، ولكنه كان عملا مريحا ، ولم يذكر الكتاب مطلقا إنه كان يتعب فى عمله ، أو أنه كان يتعب ليحصل من الأرض على اكله ...","هذه اللعنة نجدها واضحة فى قول الرب لقايين ، أول انسان لعنه الله « متى عملت الأرض ، لا تعود تعطيك قوتها » « تك ٤ : ١٢ » .","وتمرد الارض يظهر أيضا فى عبارة « شوكا وحسكا تنبت لك » ... لأول مرة تسمع عن الشوك والحسك ، إذ لم يرد لهما ذكر من قبل فى نباتات الارض ، حينما نظر الله الى كل ما عمله فاذا هو حسن جدا ... إن الارض العطشانة ، المحرومة من بركة الله"],37:["وخيره ، يمكن أن تنتج شوكا وحسكا ، وهى تحرم من بركة الله وخيره ، بسبب خطية الانسان . لذلك قال له الله « ملعونة الارض بسببك »",{h:"إن الانسان البار ، به تتبارك الارض ، والانسان الخاطىء بسببه تلعن الارض ، كما ورد فى سفر التثنية « ٢٨ » ."},"يقول الرب لمن يحفظ وصاياه « مباركا تكون فى المدينة ومباركا تكون فى الحقل . ومباركة تكون ثمرة بطنك وثمرة أرضك ... » « تث ٢٨ : ٣ ، ٤ » . وبعكس ذلك يقول الرب لمن لا يحفظ وصاياه « ملعونا تكون فى المدينة ، وملعونا تكون فى الحقل ... ملعونة تكون ثمرة بطنك وثمرة أرضك » « تث ٢٨ : ١٦ ـ ١٨ » .","لما لعنت الارض ، قل خيرها ، وأصبحت تنتج شوكا وحسكا .",{h:"وجاء المسيح الذى حمل خطايانا على الصليب ، فحمل أيضا على جبينه الشوك والحسك الذى أنتجتهما خطية الانسان ."},"قلنا إنه كانت من نتائج الخطية اللعنه . وماذا أيضا ؟",{h:"٢ ـ الموت"},"« يوم تأكل منها موتا تموت » « تك ٢ : ١٧ » .",{h:"كان الموت هو العقوبة الاساسية للخطية ."},"والكل قد خضع له . مات آدم وحواء ، ومات كل نسلهما ، وسيموت نسل الذى يولد فيما بعد . ويظل الموت إلى أن ينتهى هذا العالم .","ويقول الكتاب إن « آخر عدو يبطل هو الموت » « ١ كو ١٥ : ٢٦ » . يحدث هذا فى نهاية العالم ، حينما تتغير طبيعتنا ونلبس الحياة ، أو كما يقول الرسول « هذا المائت يلبس عدم موت » « ١ كو ١٥ : ٥٣ » . عندئذ فقط نقول له « أين شوكتك يا موت ؟! » ... أما قبل هذه القيامة ، فتظل شوكة الموت فى أجسادنا جميعا ... نتيجة لخطيئة آدم وحواء ...",{h:"* ولكن لم يكن ممكنا أن يموت أبوانا فى التو واللحظة ..."},"وإلا تكون البشرية كلها قد انتهت وزالت ، ويكون الشيطان قد انتصر فى المعركة انتصارا ساحقا ، ولا يكون هناك خلاص ، الخلاص الذى أعده الرب لآدم وبنيه ..."],38:["لذلك تأجل هذا الموت إلى حين ، ريثما تلد حواء بنين وتربيهم . لأنه فيما بعد سيأتى من نسل المرأة من يسحق رأس الحية ، ويطلب ويخلص ما قد هلك .",{h:"* ومع تأجيل هذا الموت الجسدى ، كانت هناك أنواع اخرى من الموت ، تم بعضها فى التو واللحظة :"},"هناك الموت الروحى ، وكما قال القديس أوغسطينوس « موت الجسد هو انفصال الروح عن الجسد . أما موت الروح ، فهو إنفصال الروح عن الله » ...","ولهذا أعتبر الكتاب أن الخطية موت ، فقال الآب عن ابنه الضال « ابنى هذا كان ميتا فعاش » « لو ١٥ : ٢٤ » . وقال الرب لملاك كنيسة ساردس « إن لك إسما إنك حى ، وأنت ميت » « رؤ ٣ : ١ » . فالخطية موت روحى ، لأنها تفصل الإنسان عن الله ، لأنه لا شركة للظلمة مع النور ...",{h:"* وآدم وحواء قد ماتا هذا الموت الروحى يوم أكلا من الشجرة ، وماتا أيضا موتا آخر أدبيا :"},"فى هذا الموت الأدبى ، ضاعت كرامة هذا الإنسان الأول ، وفقد الحالة الفائقة للطبيعة التى خلق عليها ، كما سنشرح فى النقاط المقبلة للفداء ... وأكبر تعبير على هذا الموت الأدبى ، أن الله طرده من الجنة . وعبارة « طرد » تعنى كثيرا من جهة الموتين الأدبى والروحى . على أنه من جهة هذين الموتين ، ظل الله يعمل عملية إقامة من الأموات بالنسبة إلى آدم وبنيه ، لكى يرجعهم إلى رتبهم الأولى ، ولكى تتم مصالحة بينهم وبين الله . ولكن الأمر كان يتوقف على مدى الاستجابة الفردية لعمل النعمة فى كل إنسان على حدة ...",{h:"* بقى الموت الابدى ، وهو أخطر ما فى حكم الموت : وهو الذى خلصنا منه المسيح بالفداء ، حين مات عنا ..."},"ولكن آدم وحواء وبنوهما جميعا ، ظلوا تحت حكم هذا الموت فى كل العصور السابقة ، وكان كل الذين يموتون ، يذهبون إلى الجحيم ، والمؤمنون منهم ، الراقدون على رجاء ، يرتلون مع داود « انك لا تترك نفسى فى الجحيم ، ولا تدع قدوسك يرى فسادا » « مز ١٥ : ١٠ » .","ولأن الخطية حرمت الانسان من الحياة ، وأوقعته فى الموت ، لذلك رأينا أمرا خطيرا قد صدر من الله « وأقام شرقى جنة عدن الكاروبيم ، ولهيب سيف متقلب لحراسة طريق شجرة الحياة » « تك ٣ : ٢٤ » ."],39:[{h:"٣ ـ فقدان الصورة الالهية"},"فى حالة البر الأولى ، كان آدم على صورة الله ، ومثاله ، كما قال الله « نخلق الانسان كشبهنا » . أما فى حالة السقوط فقد فقد هذه الصورة الالهية .","وفساد طبيعة البشرية ، الذى ستتحدث عنه فى النقطة التالية ، لم يعد يتفق مع الصورة الالهية التى كانت له يوم خلق .","ولهذا نجد الله يخاطبه بلغة اخرى تتفق وصورته فى الخطية ، فيقول له « لأنك تراب ، وإلى تراب تعود » ...","كان صورة الله ، فأصبح ترابا .","ننتقل إذن الى النقطة الرابعة من نتائج الخطية ، وهى :",{h:"٤ ـ فساد الطبيعة البشرية"},"فقدت الطبيعة البشرية نقاوتها الاولى ، وبساطتها الاولى ، وعرفت الخطيئة ، واختبرتها ، ودخلت فى ثنائية معرفة الخير والشر ، وفى الصراع بين الجسد والروح ، وهبطت إلى المستوى الجسدى احيانا كثيرة . أصبح من السهل أن تخطىء ...","وقد رأينا فيما بعد ، كيف انهارت هذه الطبيعة البشرية ، وانحدرت إلى مستويات مؤسفة ، وتوارثت الوانا من الفساد ، إلى أن وصلت إلى محبة الخطية ، وإلى العبودية لها ، وإلى انكار الله ، والجهل به .","وفقد آدم وحواء هيبتهما ، وسلطتهما على الطبيعة ، وعلى الحيوان ، فتمردت عليهما الارض ، وصارت تنبت لهما شوكا وحسكا ، وتمرد عليهما الحيوان ، وقامت عداوة معه ...","وظهر فساد الطبيعة البشرية أيضا فى انحلالها ، فى تعب الجسد وتعب النفس ، وستبقى فى هذا الفساد إلى يوم القيامة حين « يلبس الفاسد عدم فساد » « ١ كو ١٥ : ٥٤ » .",{h:"٥ ـ تعب النفس"},"لأول مرة نسمع عن أمراض النفس : نسمع فى قصة آدم وحواء عن الشهوة ، وعن الخوف ، وعن الخجل « أى الخزى » ، ثم عن معرفة آدم لحواء ... وعن سائر تعب الروح الذى ذكرناه فى تحليل خطايا هما .","وكل هذه كانت بداية ، إلى أن نسمع فى قصة قايين ، فى حياة أبوية آدم وحواء ، عن الحسد والغضب والقتل ، وعن القلق والرعب وفقدان السلام الداخلى « تك ٤ »","وبدا أن امراض النفس والروح قد أخذت تزداد ، كمظهر من مظاهر فساد الطبيعة البشرية"],40:[{h:"٦ ـ تعب الجسد"},"أصبح آدم يأكل حبزة بعرق جبينه . يعمل فى الأرض وبالتعب يأكل منها كل أيامه ...","وأصبحت حواء بالوجع تلد أولادا ، كما قال لها الرب « تكثيرا أكثر اتعاب حبلك » « تك ٣ : ١٦ » .","وثمة تعب آخر ، هو شهوات الجسد وغرائزة وأشتياقاته ...","وقبل الخطيئة ، لم يكن هناك تعب ، ولا وجع ... وما هذا كله إلا مظهر آخر لفساد الطبيعة البشرية .","* * *","وبدا أن الحية لم تصدق فى خداعها . فبدلا من أرتقاء الانسان ليصير مثل الله ... انحدر إلى أسفل .",{h:"وكان انحدار آدم وحواء ، هو « مبتدأ الأوجاع »"},"ولم يعد هناك من حل ، سوى انتظار الخلاص الذى يأتى به المسيح ، حيث ينضح علينا بزوفاه فنطهر ، ويغسلنا فنبيض أكثر من الثلج ، ويمنحنا بهجة خلاصه « مز ٥٠ » ."],41:["(صفحة صورة بلا نص في الملف: رسم لقايين يرفع الفأس على هابيل)"],42:[{h:"« ٢ » هابيل"},"أول من وصف بأنه بار « عب ١١ : ٤ »","وأخوه قايين","أول قاتل على الارض « تك ٤ : ٨ »"],43:["لا شك أن قصة قايين وهابيل ، هى من القصص المؤثرة ، لأنها تمثل أول حادث قتل يحدث بين أخين ، بل بين شقيقين ، من أب واحد وأم واحدة ، ولم يكن يوجد فى الأرض اخوة غيرهما ... أى أن قايين لم يكن له فى الدنيا سوى أخيه هابيل ، ومع ذلك قام عليه وقتله ... !",{h:"كيف دخلت الخطية ؟ وكيف بدأت ؟ وكيف تطورت ؟ وماذا كانت نتائجها ؟"},"لقد ولد قايين ميلادا حسنا ، وسمى قايين . لأن أمه أعتبرت أنه قد اقتنته من الرب « تك ٤ : ١ » ، أى حصلت عليه من الرب ... وكان قايين عاملا فى الأرض ، وكان أخوه هابيل راعيا للغنم .","وظل هذان الأخوان يعيشان معا فى هدوء ، الى أن دخل بينهما نوع من التنافس ... لقد قدم كل منهما قربانا للرب ، فقبل الرب قربان هابيل ، ولم يقبل قربان قايين . فغضب قايين على أخيه هابيل وقتله ...",{h:"مشكلة هابيل ، أنه إنسان مقبول من الرب !"},"هكذا كانت مشكلة مريم أيضا ، التى اختارت النصيب الصالح ، وجلست عند قدمى المسيح ، فرضى عنها . واستاءت أختها مرثا ووجهت اليها اللوم وغضبت عليها ... !","ما ذنب مريم ، إذ جلست عند قدمى المسيح ورضى عنها ، وما ذنبها إذا كان عمل مرثا ليس فى مستوى عملها ؟!",{h:"قايين وجد أن قربانه غير مقبول كأخيه ، فدخله الحسد ... وكان هذا الحسد بدء الشر الذى دخل قلبه ، وانتهى به إلى قتل اخيه . وربما كان الحسد أيضا هو الذى دفع الشيطان إلى إسقاط آدم وحواء ، إذ رأى أن الله قد أحبهما وباركهما ، وأعطاهما سلطانا ومركزا ، وقد خلقهما على صورته ومثاله ، فحسدهما الشيطان ، ودبر خطته لاسقاطهما . ولذلك تقول فى القداس الالهى « والموت الذى دخل إلى العالم بحسد ابليس ، هدمته ... » ."},{h:"مساكين هم الأشخاص الذين يسيرون فى طريق الرب ، لأن الشر يتضايق من نجاحهم ومحبة الله لهم ، فيدبر لهم ما يشاء أن يدبر ... إنه حسد الشياطين وأعوانهم ..."},"سواء فى ذلك آدم ، الذى حسده الشيطان فى الجنة ... أو هابيل البار ، الذى قدم لله قربانا أفضل من أخيه قايين ، فحسده أخوه وقتله .","أو داود ، إذ مسحه صموئيل ملكا ، ونجح فى حياته ، فتضايق اخوته ، وتضايق أيضا شاول الملك ، ودبر لقتله ..."],44:["أو يوسف الصديق ، إذ كان انسانا موهوبا ، ومحبوبا عند أبويه ، فحسده اخوته ، وباعوه كعبد ...","أو السيد المسيح نفسه ، الذى كان يجول يصنع خيرا : فإذ رأى الكهنة أن « الكل قد ساروا وراءه » ، حسدوه ، وجمعوا عليه شهود زور ، واتهموه باطلا ، وقدموه للصلب ..","وهكذا كانت مشكلة هابيل ، أن قربانه كان مقبولا أمام الله ، فتضايق اخوه ، ويقول الكتاب فى ذلك : « فاغتاظ قايين جدا ، وسقط وجهه » « تك ٤ : ٥ »","اذن قايين لم يكن يسعى إلى محبة الله ، وإلى ارضاء قلب الله ، انما كان يبحث عن كرامته الشخصية ورضاه عن نفسه وعن مركزه .","لو كان يبحث عن محبة الله ، لكان فى حالة رفض الله لقربانه ، أن يفتش كيف يرضى الرب ، ولا مانع من أن يغير قربانه ، ويقدم ذبيحة كهابيل ، ويحسن تصرفه . ولعل هذا ما قصده الرب بقوله له « إن احسنت ، أفلا رفع » « ع ٧ » أى أفلا يرتفع وجهك ، إن أحسنت التصرف ، وإن أحسنت التقدمة ، وإن أحسنت التفكير والشعور ...",{h:"كانت أمامه فرصه لتحسين موقفه ، ولكنه لم يستغلها ، ولم يستفد من توجيه الرب ، الذى تنازل وكلمه .."},"كان أمامه أن يتضع ، ويشعر أن قربانه « من ثمار الأرض » ليس هو حسب مشيئة الرب ، وانما مشيئة الرب هى أن يقدم ذبيحة ، محرقة سرور للرب ، كما فعل أخوه البار هابيل . ولكن قايين لم يشأ أن يعترف بينه وبين نفسه أنه مخطىء فى تقدمته ، وأنه يجب أن يسلك كأخيه . انما ركز على كرامته .",{h:"كانت ذاته تتعبه . وليته كان يحب ذاته محبة سليمة !"},"إن الذى يحب ذاته محبة حقيقية طاهرة من الكبرياء والعناد ، لا مانع مطلقا من أن يصحح لهذه الذات اخطاءها ، ويعمل على تطهيرها من نجاساتها . أما محبة الذات الممتزجة بالكبرياء ، فإن كبرياءها تعميها عن رؤية أخطائها ، فتظل كما هى ، وتصر على سلوكها ... !",{h:"وهكذا كان قايين ، محبته لذاته ، حطمت هذه الذات ..."},"محبة جاهلة ، غير حكيمة ، لا تعرف النافع لها من الضار ... وقديما بكر فكر الشيطان فى ذاته ، فقال « اصعد إلى السموات ، ارفع كرسى فوق كواكب الله ... اصير مثل العلى » « أش ١٤ : ١٣ ، ١٤ » . وبهذه المحبة الخاطئة لنفسه ، ضيع نفسه ...","وبالمثل احب الانسان الأول ذاته محبة خاطئة . وإذ أراد أن يصير مثل الله عارفا الخير والشر » أضاع هذا الأنسان نفسه ، وطرد من الجنة ، ودخل فى حكم الموت ."],45:["قايين أيضا ، ركز كل تفكيره فى ذاته ، كيف يتفوق عليه أخوه ويحظى برضى الرب ، فرأى أن يتخلص من أخيه ...","يتخلص من هذا البار ، الذى كلما يراه تصغر نفسه ويشعر أنه أقل ... ورأى أنه إذا تخلص منه ، لا يبقى أمامه شخص أفضل ، يثير حسده .",{h:"كانت كبرياء الذات ، أهم عنده من نقاء الذات ."},"لقد نبهه الرب إلى أن هناك « خطية رابضة » . وقال له بكل وضوح « وإن لم تحسن ، فعند الباب خطية رابضة ، واليك اشتياقها ، وأنت تسود عليها » .","مازال فى متناول يدك أن تتخلص منها ...","إن الخطية ما زالت على باب فكرك ، وعلى باب قلبك ، وعلى باب ارادتك . وما زالت ارادتك فى يدك ، وأنت تسود عليها ... فاحذر لنفسك قبل أن تتورط ...",{h:"ما أعمق هذا الحنو ، فى معاملة الله للخطاة ..."},"إنه يظهر لقايين ، أول انسان هلك على الارض ، ويكلمه ، ويشرح له التجربة التى أمامه ، وينصحه ، بل ويناقشه أيضا : « لماذا اغتظت ؟ ولماذا سقط وجهك ؟ ليس السبب راجعا إلى أخيك ، بل يرجع اليك أنت نفسك . أنك لم تحسن التصرف . وإن احسنت سيرتفع وجهك . علاج مشكلتك فى أن تغير مسلكك وتحسن التصرف ، وليس فى أن تستسلم للخطية ... احترس لنفسك . عند باب قلبك وفكرك توجد خطية رابضة . حاول أن تنتصر عليها ، فأنت مازلت تسود عليها ...","حنو من الله ، أن يظهر للخاطىء ، ويشرح له ، ويحذره قبل أن يسقط ، ويريه طريق التخلص من خطيته ، ويسنده بنصائحه فى وقت تجربته ومحاربة العدو له .",{h:"قد يخطىء البعض ، ويظن أن الله لا يظهر إلا للقديسين !"},"إن ظهوره لقايين قبل سقوطه فى خطية القتل ، وتحذيره له ، إنما هو مثال عجيب لمحبة الله وطول أناته ، فى العهد القديم ، بل منذ بدء الخليقة ...","وكأنه يقول لقايين : تعال يا حبيبى ، لماذا أنت مغتاظ ولماذا يسقط وجهك ؟ أنا أريد أن اخلصك من غمك ، واعيد اليك سلامك . إن الخطية هى التى أفقدتك سلامك . تخلص منها ، يرجع اليك سلامك ...",{h:"لا تظن أن هابيل هو سبب متاعبك ... كلا ، إن متاعبك سببها الخطية الرابضة . فافحص نفسك جيدا ..."},"سبب متاعبك ، يكمن فى طريقة نظرتك إلى الأمور ، وفى ردود الفعل داخلك ازاء نجاح أخيك .."],46:["لو كانت فى قلبك محبة ، لكنت تفرح وتسر ، إن رضى الرب على أخيك ، فلا تغتم ولا تغتاظ . بالمحبة ، تفرح لفرح أخيك ، وتفرح لرضى الرب عليه ...",{h:"لكن قايين لم يفرح لفرح أخيه ، ولقبول قربانه ..."},"مثاله كان الابن الاكبر ، الذى لم يفرح إذ قبل الأب اخاه الأصغر ، وألبسه الحلة الأولى ، وجعل خاتما فى اصبعه ، وذبح له العجل المسمن ...","ذلك الأخ أيضا اغتاظ ، ولم يكن قلبه مستقيما تجاه أخيه ، وكان يفكر فى ذاته وليس فى أخيه ، ونفس الحسد اتعبه ...",{h:"حقا ، إنها قصة متكررة ، تحدث فى كل جيل ، سببها عدم نقاوة القلب ، والاستسلام لمشاعر الغيرة .."},"لماذا يكون نجاح أخيك ، له رد فعل خاطىء ؟ « كان ينبغى أن تفرح وتسر » لأن الله قبل قربان هابيل ... كان ينبغى أن تفرح أيضا لأن هابيل قد كشف لك الطريق الصالح الذى يرضى الرب ، حتى تسير فيه أنت أيضا ، وتحصل على نفس الرضى والقبول ..",{h:"العجيب أن قايين ، بعد أن كلمه الله ، لم يستجب لكلمة الله ، ولم يفتح لها قلبه ، بل فتحه للخطية ..."},"بعد أن نصحه الرب ، لم يستفد من النصيحة ، وانما تورط فى الخطية ، بالأكثر ، وقام على أخيه فقتله !","إنه يذكرنا بالشيطان فى قصة أيوب الصديق ، لما وقف أمام الله ، ولم يستفد من وجوده فى حضرة الله شيئا . وخرج من عند الله لكى يتعب أيوب الكامل والمستقيم ، ويهدم له بيته ، ويقتل له أولاده ، ويضيع كل غناه ... وبعد أن وقف ثانية أمام الله ، ازداد فى شره ، وضرب أيوب بقرح ردىء ، دون أن يستفيد شيئا من اللقاء مع الله وسماع كلمته ... !","يذكرنا أيضا بيهوذا الاسخريوطى ، الذى لم يستفد من عشرته من السيد المسيح ، ولا من أكله معه ، وغمسه لقمته فى نفس صحفته ، ولم يستفد من كلام الرب وتحذيراته ، وقام بعد العشاء ليخون سيده ويسلمه !",{h:"وسائل النعمة يستفيد منها من يشاء ، ويرفضها من يشاء . إنها لا ترغم الانسان على عمل الخير ..."},"الشاب الغنى ، تقابل مع السيد الرب ، وسمع نصيحة نافعة من فمه الالهى ، ولكنه بعد سماعها مضى حزينا ، ولم يقل الكتاب أنه نفذ شيئا من تلك النصيحة ..."],47:["أمر محزن ومخجل ، أن يسمع انسان نصيحة من فم الرب نفسه ، ثم يمضى حزينا ، ولا ينفذ . هكذا قايين أيضا ...","اذن ، فلا يجوز أن يحتج أحد ويقول « مشكلتى الوحيدة هى عدم وجود مرشدين روحيين . لو كان لى مرشد روحى حكيم ، لصرت قديسا » ..","هو ذا امامنا أمثلة لأشخاص ارشدهم الرب نفسه ، ولم يستفيدوا ، لأن القلب رفض أن يستجيب مثل الارض التى القى عليها البذار الرب نفسه ، فأنتجت شوكا ... أو سمحت للشوك أن يخنق زرعها ، وللطير أن يلتقط بذارها ...","لقد تقابل قايين مع الرب ، وللأسف لم يستفد . سعى الرب اليه ، وأراه الطريق ، ولكنه رفض أن يسير فى طريق الرب ، ولم يستجب إلا لفكر قلبه الردىء",{h:"المشكلة تكمن فى عدم وجود استعداد داخلى ."},"لا تقل « انى أذهب إلى الكنيسة ولا استفيد » .. لأن غيرك يذهب ويستفيد . لو كنت تريد أن تستفيد لأستفدت . إن لم تستفد من القداس ، يمكنك أن تستفيد من العظة . وإن لم تستفد من مجرد القراءات ، بل من مجرد الوجود فى الكنيسة ، فى جو روحى ... بل يمكنك أن تستفيد ـ لو أردت ـ من منظر الأيقونات ، ومن الشموع ... أو على الاقل تخلو إلى نفسك مع الله ، ولو لحيظات ...","وهكذا ، لأن قايين لم يكن لديه استعداد داخلى للاستفادة ، لم ينتفع بكلمة الرب له ...",{h:"لم تكن له أذنان للسمع ، فلم يسمع ..."},"ربما أثناء حديث الرب معه ، كان منشغلا بالغيرة التى فى قلبه ، وكان الحسد يسد أذنيه ، وكان الانفعال الداخلى أعلى صوتا فى قلبه ، وكانت ذاته حاتلا يحجب حكمة الوصية والنصيحة ...",{h:"وكلم قايين هابيل أخاه « ع ٨ » . ترى ماذا قال له ؟"},"اتراه قال له « هيا بنا إلى الحقل ، نقضى الوقت بعيدا عن الأسرة ، معا ... بعيدا عن ملاحظة الأبوين ... على أية الحالات ، لم يكن هابيل ينتظر خيانة من أخيه قايين . إنه شقيقه ، يمكنه أن ينام إلى جواره ويغمض عينيه ، دون أن يخشى شرا ، فى ثقة بهذه الأخوة ... لو كان فى قلبه ادنى شك من جهته ، لأحترس منه . ولكن حينما يأتى الشر ممن هم فوق مستوى الشك ، حينئذ تكون المأساة أعمق وأكثر تأثيرا فى النفس ..."],48:["« وقام قايين على هابيل أخيه وقتله » . وهكذا تطورت به الخطية من سىء إلى أسوأ ، وهو مستسلم لها ...","تطور من غيرة ، إلى حسد ، إلى غيظ ، إلى حقد ، إلى فكر الشر ، إلى تدبيره وتنفيذه ، إلى قتل أخيه ... وبعد أن كانت الخطية رابضة عند الباب ، دخلت إلى قلبه ، وسيطرت على فكره ومشاعره وأعصابه وانفعالاته .",{h:"وبعد أن كان يسود عليها ، صارت تسود عليه ..."},"ودفعته الخطية فى طريقها ، فخضع لها ونفذها ... وحينما نفذ ، اختفت من أمامه كل المثل ، لا محبة ، ولا أخوة ، ولا شفقة ، ولا ارضاء الله ...",{h:"وربما ظن قايين ، أنه لا يوجد أحد يراه ..."},"وأنه سوف لا يعلم أحد بجريمته ، وأنه قد تخلص من هذا المتفوق الذى تصغر نفسه أمامه ، وأن صوت هابيل قد سكت إلى الأبد .","وهابيل البار ، لم يستطع أن يدافع عن نفسه",{h:"وهكذا بدا أن الشر قد انتصر على الخير ..."},"وبدا أن الخير لم يستطع أن يدافع ، فهزمه الشر ...","نعم ، إن الشر فى الأرض ، يبدو دائما أكثر جراءة ، وأكثر عنفا ، وأكثر تسلطا . يعرف أن يضرب ، ويعتدى ، ويقتل ... والطرق امامه مفتوحة كلها ، بعكس الخير الذى يعف عن كثير من الوسائل التى يستخدمها الشر .",{h:"إن قصة قايين وهابيل ، ترينا مدى امكانيات الشر :"},"الشر يستطيع أن يدبر مؤامرات ، وأن يتنكر لكل القيم ، وأن يستخدم كل الوسائل مهما كانت خاطئة . يستطيع أن يخون ، وأن يخدع ، وأن يعتدى ، وأن يقتل . ومع كل ذلك يجرؤ أن يستر فعلته بالأكاذيب . ويقول فى جراءة حتى أمام الله « أحارس أنا لأخى ؟ ! ... »","الشر استطاع بالنسبة إلى السيد المسيح نفسه ، أن يقدم تهما باطلة ، وأن يحضر شهود زور ، وأن يتملق قيصر ، وأن يثير الشعب كله ، وأن يصلب البار","والشر استطاع أن يغتصب تابوت اليزرعيلى ، وفى نفس الوقت يلفق له تهما تجعله يستحق الموت ... !"],49:["نعم ، إن الشر قد ينتصر على الخير ... ولكن القصة لها تكملة ... وتكملتها إن الله موجود ، وأنه يحكم للمظلومين .","ربما لم يحسب قايين حسابا لوجود الله ولتدخله ، وظن أن الموضوع بينه وبين هابيل فقط ، وليس من ثالث يتدخل بينهما ، لكى يكمل القصة ، ويقيم التوازن .",{h:"هذا الثالث العادل ، تدخل بين الخير والشر ..."},"تدخل ليحاسب ويحاكم ، ويعاقب ، ويشرح للشر أن الأمر لم ينته بعد ، وأن هناك قوة اكبر ، وأن هناك عينا ترى ، وقضاء يحكم . وأن الله لا يترك عصا الخطاة تستقر على نصيب الصديقين .",{h:"وأثبت هذا الثالث ، أن انتصار الشر هو انتصار زائف ومؤقت ، وأن العبرة بالنهاية ، والنهاية هى انهيار الشر ."},"اذن ، لا تفقد الرجاء أبدا . إن أصابك شر ، وحتى إن قوى الشر عليك ، وعلى ظهرك جلدك الخطاة واطالوا اثمهم ، فلا يتزعزع قلبك . ثق أن الله يرى ويسمع ، ويكتب امامه سفر تذكرة « مل ٣ : ١٦ » . وثق أن الرب صديق هو يقطع أعناق الخطاة « مز ١٢٨ ... »",{h:"لا تنظر الى أوائل الأشرار ، وانما إلى نهايتهم ... واسأل نفسك : من الذى انتصر : قايين أم هابيل ؟"},"هابيل كتب اسمه فى سفر الحياة وهو « وإن مات ، يتكلم بعد » « عب ١١ : ٤ » . أما قايين فعاش على الأرض معذبا طول أيامه ، قلقا ، خائفا ، فاقدا سلامه . وانتظرته عذابات فى الأبدية أشد إيلاما .","إن الشر قد يرتفع على الخير ، ولكنه يتبدد : كمثال النار والدخان . الدخان يرتفع إلى فوق وفيما هو يرتفع ، تتسع رقعته ، وتقل حدته ، ويتبشر فيندثر ويضعف ويختفى . أما النار ، وإن ظلت تحته ، إلا أنها تستمر بعده فى قوتها وفى نقاوتها . إنها أقوى وأشد حرارة ... ولا تبالى بصعود الدخان إلى فوق ، فوقها ..",{h:"فرق كبير بين كبرياء الدخان ، فى ارتفاعه وضعفه وتبدده ، وبين تواضع النار ورزانتها وقوتها ..."},"قايين المرتفع على هابيل ، الذى كان يبدو اقوى منه ، لم يعمل حسابا لتدخل الله ..."],50:[{h:"هابيل لم يدافع عن نفسه ، فدافع الله عنه"},"لم يرو لنا الكتاب أن هابيل دافع عن نفسه ، أو أنه قاوم الشر ، أو حتى انه شكا أو أستنجد أو استغاث . لقد لاقى مصيره فى صمت ، ومات بيد أخيه ...","ولكن القصة لم تتم فصولا . إذ أن الله واجه قايين وساله « أين هابيل أخوك ؟ » . فأجاب « لا أعلم ، أحارس أنا لأخى ؟ ! » ...",{h:"وهكذا قادته خطية القتل إلى خطية الكذب ، فكذب على الله نفسه ، وقال له لا أعلم ، وهو أكثر الناس علما بمصير أخيه ! .. أو كان الوحيد من البشر الذى يعلم بمصير أخيه !!"},"كان قايين كفار فى مصيدة ، يحاول أن يفلت فلا يستطيع . أنه يتلمس طريقا للهروب من مسئولية جريمته . يدعى عدم المعرفة . يدعى أنه غير مسئول عن أخيه وعن حراسته !! لقد أمسكه العدل الالهى . فاخذ يكذب على فاحص القلوب والكلى ، والعارف بالخفيات والظاهرات ، على الله الذى أنذره من قبل ولم يسمع ...",{h:"حقا ، إن الكذب هو الابن البكر لكل خطية . هو الغطاء الذى يحاول الخاطىء أن يغطى به على خطيئته فلا تظهر ..."},"إنه أسهل طريقة ، وأول طريقة ، يحاول بها أن يهرب من المسئولية ، من العقوبة ، أو من العار والفضيحة ... يندر أن يوجد خاطىء لا يكذب . الذى يعترف بخطيئته ، هو التائب . أما الخاطىء المستمر فى خطيئته فإنه يكذب ليسترها .. ولكننا نفهم أن يكذب خاطىء على إنسان مثله . أما أن يكذب على الله نفسه ، فهذا أمر خطير له دلالته .",{h:"إن كذب قايين على الله ، يدل على بعده عن الايمان . إنه لا يعرف من هو الله ، وما هى قدرته ، وما هو علمه غير المحدود !"},"والعجيب أن الله هنا لم يجرح شعور قايين ، ولم يقل له إنه كذاب . بل لم يجادله اطلاقا فى كلامه ، وانما واجهه بالحقيقة التى تكشف كذبه ، فقال له « صوت دم أخيك صارخ إلىّ من الأرض » ... إن هابيل لم يتكلم ، ولكن دمه له صوت ، صارخ من الأرض ...",{h:"قد يصمت المظلومون . ولكن صمتهم له صوت صارخ إلى الله ."},"والله يسمع هذا الصوت ، صوت صمتهم الصارخ ... إن يوسف الصديق قد ظلمه اخوته ، وظلمته امراة فوطيفار ، وصمت ... ولكن صمته كان يصرخ إلى الله ، وسمع الله ، وتدخل لينقذه من الظلم ."],51:["والعمال الذين بخست أجورهم ، يقول الكتاب إن هذه الأجرة المبخوسة تصرخ ، والصراخ قد دخل إلى أذنى الرب « يع ٥ : ٤ » .",{h:"إن الله يقاتل عنكم وأنتم تصمتون ، لأنه يسمع صوت صمتكم ."},"إذا ظلم انسان وسكت ، فلا تظن أن الأمر قد انتهى عند هذا الحد . فإن صوت سكوته يرن فى أذنى الرب ، يقول الوحى الإلهى « من أجل شقاء المساكين وتنهد البائسين ، الآن اقوم يقول الرب ـ أصنع الخلاص علانية » « مز ١١ » . نعم ، قم أيها الرب إلإله ، وليتبدد جميع اعدائك ، وليهرب من قدام وجهك كل مبغضى اسمك القدوس ...","« صوت دم أخيك صارخ إلىّ من الارض . فالآن ملعون أنت من الأرض التى فتحت فاها لتقبل دم أخيك من يدك »","هنا بدأت العقوبة . هنا يجد الشر من يقف فى طريقه ، ويقاومه « لى النقمة ، أنا اجازى يقول الرب » .",{h:"إن لم يجد الشر رادعا على الأرض ، فهناك رادع من السماء ."},"ولأول مرة هنا يلعن الرب انسانا ... عندما أخطأ آدم قال له ملعونة الأرض بسببك ، ولكن لم يلعنه شخصيا .",{h:"لعنت الحية ، والأرض ، ولأول مرة هنا يلعن الانسان ."},"كان قايين قد فقد الصورة الإلهية نهائيا ، الصورة التى كانت للانسان حينما خلق على شبه الله ومثاله ...","ويلعنته ، لعن كل نسله أيضا ، وأصبحوا يدعون أولاد الناس ، بينما دعى أولاد شيث « أبناء الله » « تك ٢ : ٦ » . واستمرت هذه اللعنة ، حتى أفنى الله كل أبناء قايين بالطوفان .","« ملعون أنت من الأرض ، التى فتحت فاها لتقبل دم أخيك من يدك » . هذه الأرض التى تنجست بجريمة القتل ، وقبلت الدم المسفوك :",{h:"« متى عملت الأرض ، لا تعود تعطيك قوتها » « ع ١٢ » ."},"الأرض تتمرد عليك ، ولا تعطيك الخير الذى تقدر عليه ... بدلا من أن تعطيك عشرين أردبا ، تعطيك اثنين أو ثلاثة . لا تجد بركة فى عمل يديك ، ولا بركة من خير الأرض وثمارها ... بالنسبة إلى البار ، قال الرب « مباركة تكون ثمرة أرضك » « تث ٤ : ٢٨ » ، وبالنسبة إلى الخاطىء ، لعن الله ثمرة الأرض « تث ١٨ : ٢٨ » ... فلا تعود تعطيك قوتها ..."],52:["إن ثمار الأرض فى يد الله ، يباركها حينما يشاء ، مثلما بارك غلة العام السادس ، فكان يكفى ثلاثة أعوام ...","أما اذا سلك الانسان فى الخطية ، فقد يعاقبه الله بتمرد الارض عليه ، فلا تعطيه قوتها ، لا تعطيه خيرها ، كما تمردت من قبل على آدم ، وصارت تنبت له شوكا وحسكا .","المسألة اذن لا تنحصر فقط فى خبرة الانسان بالزراعة ، ومدى اتقانه لعمله فيها وخدمته لها ، إنما يحتاج أيضا إلى بركة . وتتبارك الارض متى ارضى قلب الله ، وإلا فإنه متى عمل الارض لا تعود تعطيه قوتها . لهذا نحن نصلى من أجل ثمار الأرض ، لكيما يصعدها الله كمقدارها ، ويفرح وجه الأرض ، فتكثر أثمارها » .","لقد لعن الرب قايين ، وأمر الأرض أن تتمرد عليه ، وماذا أيضا عن باقى عقوباته ؟ قال له الرب :",{h:"« تائها وهاربا تكون فى الأرض » ..."},"تفقد سلامك الداخلى ، تحيا فى قلق واضطراب وخوف تجرى وليس من مطارد . تشعر أن كل من وجدك سيقتلك . وهكذا بدأت الأمراض النفسية تعمق جذورها فى الانسان","فى خطية آدم ، دخله الخوف ، الخوف من الله وعقوبته أما فى خطية قايين ، فقد دخله الخوف من الناس ، أو الرعب بمعنى أصح « يكون كل من وجدنى يقتلنى » ... « ع ١٤ » .",{h:"لا سلام ، قال الرب ، للأشرار ..."},"الخاطىء يعيش منزعجا باستمرار . يخاف أن تنكشف خطيئته ويعرفها الناس . يخاف من الفضيحة والعار والسمعة السيئة . يخاف من العقوبة ، سواء عقوبة القانون ، أو انتقام من أساء إليها . يرتعب من نتائج أخرى لا يعرفها ، يصور له الاضطراب أمورا اخرى كثيرة ستحدث ... وأعداء كثيرين يطاردونه .",{h:"داخله يزعجه أكثر من أى ازعاج خارجى ..."},"أيهما لاقى العذاب أكثر : قايين أم هابيل .","هابيل قاسى الألم ربما لحظة أو لحظات . ضربة قاتلة أصابته فمات . أما قايين فإنه عاش العمر كله يتألم ويتعذب ، ويحطمه القلق والخوف والرعب والاضطراب . هابيل تألم بالجسد قليلا . أما قايين فإن نفسه تعذبت من الداخل ، ولا شك أن عذاب نفسه كانت له نتائجه على الجسد أيضا ...","هذه إحدى عقوبات الخطية تطارد الانسان ."],53:["« فقال قايين للرب : ذنبى أعظم من أن يحتمل . إنك قد طردتنى اليوم عن وجه الأرض ، ومن وجهك اختفى . واكون تائها وهاربا فى الأرض ، فيكون كل من وجدنى يقتلنى » ...","نلاحظ هنا أن عبارة « ذنبى أعظم من أن يحتمل » لم تكن عبارة توبة ، انما خوف من العقوبة ...","أى أن العقوبة أعظم من احتماله ، عقوبة أن يكون تائها وهاربا فى الأرض ، ومهددا من كل أحد بالقتل ... لذلك فإن الله الرحوم ، الذى يشفق على القلوب القاسية إذا ما تذللت أمامه ، طمأن قايين الخائف « وجعل له علامة لكى لا يقتله كل من وجده » « ع ١٥ » . بل قال له أيضا « كل من قتل قايين ، فسبعة أضعاف ينتقم منه »",{h:"ونلاحظ أن قايين لم يطلب مغفرة لخطيئته ، بل أنه لم يقل عبارة أخطأت . كل ما أتعبه هو العقوبة ..."},"وإذ جعل له الرب علامة لكى لا يقتله كل من وجده ، « خرج قايين من لدن الرب ، وسكن فى أرض نود » . وسكن معه الخوف والرعب كل أيام حياته . لقد قتل آخاه فى لحظات . ولكن الخوف ظل يقتله كل يوم وكل ساعة وكل لحظة ... وظلت خطيئته امامه كل حين ، لا تقوده إلى التوبة إنما تحطمه بالخوف . فمن أخذ بالسيف ، بالسيف يؤخذ ...",{h:"هناك مجرمون يتمنون العقوبة ، هربا من الأنزعاج الداخلى . وقد يسلمون أنفسهم للعدالة ويعترفون غير محتملين عذاب الضمير أو عذاب النفس ."},"داود ، قد غفر له الله خطيئته ، ونقلها عنه ، وسامحه من جهة العقوبة الأبدية . ولكن بشاعة الخطيئة ظلت أمامه فى كل حين ، وبسببها يبلل فراشه بدموعه ، ويمزج شرابه بالدموع ...","وظل قايين يطارده الخوف ، وترن فى أذنيه كلمات الرب « تائها وهاربا تكون فى الأرض » .",{h:"وأصعب من طرده من وجه الأرض ، أنه طرد من وجه الله أيضا ، فمن وجه الله يختفى ..."},"فالخطية هى انفصال عن الله ..."],54:["والخاطىء ينفصل بخطيئته عن الله . يختفى الله من حياته ، ويختفى هو من أمام وجه الله . يوجد حاجز كبير بينه وبين الله . ويشعر بهذا الفاصل ، ويفقد الدالة ومشاعر الحب ...",{h:"ولا ينكسر هذا العاجز إلا بالتوبة ، فيصرخ الانسان قائلا للرب : إلى متى تحجب وجهك عنى ..."},"ولكن الكتاب لم يقل إن قايين قد تاب ، ولم يقل إنه عاد فأصطلح مع الله . ولم يقل إن اللعنة زالت عنه ، أو أن الرب عاد فرضى عليه . لقد كان أول ابن لآدم وحواء بعد خطيئتهما ، وللأسف كان ابنا للهلاك . كان أول قاتل ، وأول انسان ملعون ، وأول انسان استحق العقوبة الأبدية ، إلى جوار عقوبته على الأرض .",{h:"إنه لم يقتل هابيل ، انما فى الواقع قد قتل نفسه ... وهابيل لم يمت ، بينما قايين أول أنسان مات ، موتا أبديا ."},"هل تظنون أن هيرودس قد قتل يوحنا المعمدان ؟ أم الواقع أن هيرودس قد قتل نفسه ، قتل روحه وحياته وأبديته . أما يوحنا فهو حى فى الفردوس يتنعم ...",{h:"إن الانسان الذى يخطىء إلى غيره ، إنما يخطىء إلى نفسه ."},"وما أقل الخطاة ، الذى يشعرون أنهم يحطمون أنفسهم ...","فليعطنا الرب بركة هابيل البار ، أول من ذكر له الكتاب أنه قدم محرقة للرب ، وذبيحة مقبولة ، نذكرها باستمرار فى كل قداساتنا . فنقول فى مقدمة أوشية بخور باكر « يا الله ، الذى قبل اليه قرابين هابيل الصديق ... اقبل اليك هذا البخور من أيدينا نحن الخطاة ... » .",{h:"وذبيحة هابيل الصديق تعطينا فكرة عن أهمية التقليد Tradition فى الكنيسة . لأن هابيل فى تقدمته لم ينفذ وصية مكتوبة انما أخذها عن أبيه ، الذى أخذها من الله ."},"لم تكن هناك وصايا مكتوبة أيام هابيل . ولكن كان هناك التقليد أو التسليم . جيل يسلم جيلا وصايا الرب . وظل الأمر هكذا فى كل ذبائح نوح وابراهيم ، واسحق ويعقوب وأيوب ، إلى أن وصلت الينا الشريعة المكتوبة على يد موسى النبى ، بعد آلاف من السنين عاشتها البشرية بالتقليد والتسليم من الآباء ...","وجميل جدا هو قول الكتاب عن تقدمة هابيل البار : « وقدم هابيل أيضا من أبكار غنمه ومن سمانها » « ع ٤ » ."],55:["لقد قدم البار أفضل ما عنده للرب","بل إنه نفذ وصية البكور ، قبل أن يقول الرب على يد موسى النبى « قدس لى كل بكر ، كل فاتح رحم ... إنه لى » « خر ١٣ : ٢ » .",{h:"أتراه قدم البكور ، بروح النبوة المكتوبة ، قبل الوصية المكتوبة ؟ أم تراه فعل ذلك عن طريق التقليد والتسليم أيضا ؟ أم هو القلب البار الحساس الذى يدرك مشيئة الرب ورغبته ، دون أن يتلقنها من معلم ..."},"إنه هابيل الذى شهد له أنه بار ، وشهد الله لقرابينه . وبه وإن مات يتكلم بعد « عب ٤ : ١١ »","إنه هابيل ، أول من قبل الرب منه ، أول من نظر الله اليه والى قربانه « تك ٤ : ٤ » . إنه رمز لكل ذبيحة مقبولة ، وكل قرابين مرضية للرب .",{h:"ولقد ذكره بولس الرسول فى مقدمة رجال الايمان : فقال « بالايمان ، قدم هابيل لله ذبيحة أفضل من قايين » « عب ١١ : ٤ » . إذن لم تكن هذه الذبيحة مجرد أمر تعوده هابيل ، أو تسلمه بلا فهم . وإنما كان عملا من أعمال الايمان « به شهد له أنه بار » ..."},{h:"إن هابيل يمثل الإيمان وهو بكر ، فى بداية معرفته . إنه أول انسان فى العالم ، وصف بكلمة الإيمان ."},"ترى ماذا كان الإيمان فى أيام هابيل ؟ ...","إنه على أية الحالات كان بداية لذلك المبدأ اللاهوتى القائل « بدون سفك دم لا تحصل مغفرة » « عب ٩ : ٢٢ »","الخطية كشفت عرى الانسان آدم ، والذبيحة غطته ، حينما صنع له الله اقمصة من جلد « تك ٣ : ٢١ » ، ورفض أن يغطى بورق التين ، بشىء من ثمار الأرض .",{h:"وعرف هابيل هذه الحقيقة : الله يريد الدم لا ثمار الارض . فقدم الدم من ابكار غنمه ومن سمانها . بينما قدم قايين من ثمار الارض ، وكأنه لا يؤمن بما حدث لأبويه ..."},"وكانت ذبيحة هابيل رمزا لذبيحة السيد المسيح .","وكان هابيل فى ذبيحته كاهنا للرب .","ولم يكن قايين كذلك ..."]}},anger_book:{id:"anger_book",title:"الغضب",author:"قداسة البابا شنوده الثالث (سلسلة الحروب الروحية ٣)",url:"https://drive.google.com/file/d/1asDMHIiO4wdcTyi0GME1AxmNHD53WdyP/view",file:"الغضب",pageOffset:0,review:{status:"needs-review",note:"نُقل الكتاب كاملًا (من «قصة هذا الكتاب» ص٥ إلى نهاية الفصل السادس ص١٢٤، الرقم المطبوع = ترقيم الملف) بقراءة صفحات الكتاب الممسوحة بالنظر؛ حُذف الغلاف وصفحات الفهرس الأخيرة (ص١٢٥–١٢٨). ما زال يحتاج مطابقة نهائية مع الأصل، وبعض أسماء القديسين والاقتباسات قُرئت بأفضل ما تيسر."},chapters:[{title:"قصة هذا الكتاب",from:5,to:6},{title:"الفصل الأول: الغضب المقدس",from:7,to:18},{title:"الفصل الثاني: الغضب الخاطئ أو الباطل",from:19,to:36},{title:"الفصل الثالث: أنواع ودرجات الغضب",from:37,to:48},{title:"الفصل الرابع: الاحتمال",from:49,to:72},{title:"الفصل الخامس: أسباب الغضب",from:73,to:92},{title:"الفصل السادس: علاج الغضب",from:93,to:124}],transcribed:[5,124],pages:{5:[{h:"قصة هذا الكتاب"},"فى أول حياتى كأسقف ، حينما بدأت أدرّس أقوال الآباء النسكية لطلبة الكلية الإكليريكية سنة ١٩٦٢ ، تناولت موضوعين هامين : أحدهما [ حياة السكون ] والثانى [ الغضب والإحتمال ] وقدمت للطلبة مذكرات مطبوعة فى هذين الموضوعين فى بداية سنة ١٩٦٣ أى منذ حوالى ٢٤ عاماً .","وكنت قد تتبعت أقوال الآباء التى قالوها فى [ الغضب ] وقمت بترجمتها :","فترجمت ليوحنا كاسيان ما ورد فى كتابيه : المعاهد Institutes ، والمقابلات أو المؤتمرات Conferences مع ما ذكره فى لقاءاته مع آباء قديسين مثل الأنبا بيامون ( فى المقابلة ١٨ ) ، والأنبا يوسف ( فى المقابلة ١٦ ) . وكذلك أقوال القديس دوروثيئوس كما وردت فى مجموعة الفيلوكاليا Philokalia ، وأقوال مار إسحق كما وردت فى ميامره ، وأقوال القديس مار أوغريس كما وردت فى ميامره عن محاربات الأفكار . يضاف إلى هذا قصص وأقوال قديسى البرية عن الغضب التى ذكرت فى بستان الرهبان ، أو فى كتاب القديس بلاديوس Historia Lausiaca المترجم إلى الإنجليزية تحت اسم The Paradise of the Fathers .","وكل ذلك وزعناه على الطلبة ، وامتحنوا فيه فى مادة أقوال الآباء ...","ثم أضيف إلى ذلك ما ترجمته من أقوال آباء كثيرين مثل القديس أوغسطينوس والقديس يوحنا ذهبى الفم .","ثم ألقيت محاضرات عن الغضب فى كنيسة الملاك ميخائيل بدمنهور فى سبتمبر سنة ١٩٦٥ قام ابننا القمص ميخائيل صليب بطبعها ونشرها ، وأعاد طبعها أكثر من مرة .","وألقيت محاضرات عن الغضب فى الكاتدرائية المرقسية الكبرى بالقاهرة فى ديسمبر سنة ١٩٧١ نشرت فى جريدة وطنى فى ١٩ / ١٢ / ٧١ ، وفى ٢٦ / ١٢ / ٧١ ."],6:["وألقيت محاضرات أخرى عن الغضب فى الكاتدرائية الكبرى فى أغسطس وسبتمبر سنة ١٩٨٦ م ضمن محاضرات ألقيناها عن حياة الوداعة .","ثم رأيت أخيراً أن أضع كتاباً عن الغضب والإحتمال يشمل كل ما جاء فى تلك المحاضرات التى ألقيت على مدى ٢٥ عاماً . وهو هذا الكتاب الذى بين يديك .","وقد سبق وصول هذا الكتاب إليك ، كتاب آخر قدمناه لك عن [ الهدوء ] . وكل من هذين الكتابين يكمل أحدهما الآخر ، ويدخلان معاً فى نطاق حياة الوداعة ...","وهذا الكتاب ليس عن الغضب فقط كحرب ، وإنما عن علاجه أيضاً ، بالإحتمال وبطرق روحية كثيرة .","وإن كان كتاب [ الغضب ] يدخل فى سلسلة [ حياة الوداعة والإتضاع ] ، ذلك لأن الإنسان الوديع المتواضع لا يُغضب أحداً ، ولا يغضب من أحد ... إلاّ أن الغضب أيضاً حرب روحية تدخل فى [ سلسلة الحروب الروحية ] ، هذه التى أصدرنا منها كتابين : الأول [ حروب الشياطين ] . والثانى [ الحروب الروحية ] . وقد شمل الحديث عن ١٤ حرباً روحية .","فليكن الغضب هو الحرب الثانية عشرة ، وليكن الجزء الثالث من هذه السلسلة . وإلى اللقاء مع البقية ..","البابا شنوده الثالث"],7:[{h:"الفصل الأول : الغضب المقدس"},"نوعان من الغضب","الغضب المقدس","غضب الله","غضب القديسين","الحزم لا الترفزة","اغضبوا لا تخطئوا","لا تغرب الشمس على غيظكم"],8:[{h:"نوعان من الغضب"},"يوجد نوعان من الغضب : أحدهما الغضب الخاطىء ، الذى نعتبره خطية واضحة ، أو مجموعة من الخطايا . ويعبر عن نفسه فى أغلب الأحيان بالنرفزة أو بالحدّة . وسيكون هذا النوع من الغضب هو موضوعنا الأساسى .","على أنه يوجد غضب آخر سليم ، لا عيب فيه . بل قد يكون غضباً مقدساً أو غضباً واجباً . وسنتحدث عنه الآن قبل أن نتكلم عن خطية الغضب .",{h:"الغضب المقدس"},"وهو غضب لأسباب مقدسة من أجل الحق ، ولا تدخل فيه الذات ، ويكون بأسلوب سليم ، وليس بعصبية أى ليس بنرفزة . ولا يكون بجهل ، ولا بسرعة ...","والكتاب المقدس يعطينا أمثلة من غضب الله ، وغضب الرسل والأنبياء . كما يعطينا التاريخ أمثلة من غضب القديسين .",{h:"غضب الله"},"كم من مرة غضب الله على البشر وعلى الخطاة .. والغضب هنا معناه عدم الرضا .","وكان الله فى غضبه ينذر أحياناً ، ويعاقب فى أحيان أخرى ، أو يوبخ وينتهر ."],9:["لقد غضب الله على أهل نينوى ، لما صعد شرهم أمامه ( يون ١ : ٢ ) . وأرسل لهم يونان النبى لينادى عليهم بالهلاك . ولكنهم لما تابوا ، لم يوقع الرب بهم الشر الذى تكلم أن يصنعه بهم ( يون ٣ : ١٠ ) .","وغضب الله على بنى إسرائيل لما عبدوا العجل الذهبى ، وأراد إفناءهم . ولكنه لم ينفذ فيهم هذه العقوبة بسبب شفاعة موسى النبى فيهم ( خر ٣٢ : ٧ ـ ١٤ ) .",{h:"الغضب هنا معناه عدم رضى الرب عن الشر . وأخذ التعبير صورة العقوبة أو التهديد بها ."},"وغضب الرب على قورح وداثان وأبيرام ، ففتحت الأرض فاها وابتلعتهم وبيوتهم وكل ما كان لهم ( عد ١٦ : ٣١ ) . وغضب على الشعب الذى تذمر بسببهم ، وضربهم بالوبأ . ومات فى ذلك اليوم أربعة عشر ألفاً وسبعمائة « لأن السخط كان قد خرج من قبل الرب » ( عد ١٦ : ٤٩ ، ٤٦ ) .","والأمثلة كثيرة فى الكتاب . ولذلك نطلب فى صلواتنا أن لا يغضب الله علينا .",{h:"ونقول للرب : « إرفع غضبك عنا » ( لحن افنوتى ناى نان ) ."},"وهذا هو ما قاله موسى للرب ، لما أراد إفناءهم : « لماذا يارب يحمى غضبك على شعبك ... ؟ » ( خر ٣٢ : ١١ ) . وهذا ما يقوله داود النبى فى المزمور : « يارب لا تبكتنى بغضبك ، ولا تؤدبنى بسخطك » ( مز ٦ : ١ ) . وارميا النبى يقول للرب فى مراثيه : « إردد نا يارب إليك فنرتد ، جدد أيامنا كالقديم . هل كل الرفض رفضتنا ؟ هل غضبت علينا جداً ؟ » ( مرا ٥ : ٢١ ، ٢٢ ) .","ومن أمثلة غضب الله على الشر والأشرار ، قول الرسول :",{h:"« لأن غضب الله معلن من السماء على جميع فجور الناس وإثمهم » ( رو ١ : ١٨ ) ."}],10:["وقد قيل أيضاً : « الذى لا يؤمن بالابن ، لن يرى حياة أبدية ، بل يمكث عليه غضب الله » ( يو ٣ : ٣٦ ) . كما قيل إن غضب الله يأتى على أبناء المعصية ( أف ٥ : ٦ ؛ كو ٣ : ٦ ) . وكلمة « الغضب » فى كل هذه الأمثلة تعنى العقوبة ، ولا تعنى النرفزة التى يقع فيها الناس .",{h:"لذلك من أمثلة غضب الله : يوم الدينونة :"},"والقديس يوحنا الرائى أبصر الخطاة خائفين فى ذلك اليوم ، حتى الملوك والعظماء والأغنياء والأمراء والأقوياء ... « أخفوا أنفسهم فى الغاير وفى صخور الجبال . وهم يقولون للجبال والصخور إسقطى علينا وأخفينا عن وجه الجالس على العرش وعن غضب الحمل . لأنه قد جاء يوم غضبه العظيم ، ومَنْ يستطيع الوقوف » ( رؤ ٦ : ١٥ ـ ١٧ ) . وقد أطلقت عبارة « كأس غضب الله » على العذاب الابدى ( رؤ ١٤ : ١٠ ) .",{h:"قداسة الله ترفض الشر وتنفر أو تشمئز منه وتدينه . وقد أطلق على هذا الرفض وهذه الدينونة عبارة « غضب الله » ."},"ومن أمثلة هذا الأمر أنه فى معجزة شفاء الرب لصاحب اليد اليابسة ، لما كان اليهود يراقبونه هل يشفيه فى السبت ... حدث أنه « نظر حوله إليهم بغضب ، حزيناً على غلاظة قلوبهم ، وقال للرجل : مد يدك .. » ( مر ٣ : ١ ـ ٥ ) . وعبارة « غضب » هنا تعنى إشمئزاز الرب من الشر . وكان غضبه فى هذا المثال بدون عقوبة .",{h:"ونلاحظ فى الحديث عن غضب الله ... إنه طويل الأناة بطىء الغضب ."},"أعلنها ناحوم النبى فقال : « الرب بطىء الغضب ... » . ( نا ١ : ٣ ) .","وقد صرح بهذا يونان النبى فى عتابه مع الله ، إذ قال له : « لأنى علمت أنك إله رؤوف ورحيم ، بطىء الغضب وكثير الرحمة ونادم على الشر » ( يون ٤ : ٢ ) . وقيل أيضاً : « الرب إله رحيم ورؤوف ، بطىء الغضب وكثير الإحسان » ( خر ٣٤ : ٦ ) .",{h:"إن الله بطىء الغضب . وأيضاً غضبه لا يستمر ."}],11:["إختبر داود النبى هذه الحقيقة فقال : « الرب رحيم ورؤوف ، طويل الروح وكثير الرحمة . لا يحاكم إلى الابد ، ولا يحقد إلى الدهر » ( مز ١٠٣ : ٨ ، ٩ ) . وقال فى تركيز :",{h:"« لأن للحظة غضبه .. » ( مز ٣٠ : ٥ ) ."},"والمقصود بغضب الله ، أن نستيقظ روحياً ، فلا نستغل رحمته ونستهين بغنى لطفه وإمهاله وطول أناته ( رو ٢ : ٤ ) ويقودنا ذلك إلى الاستهتار واللامبالاة ...",{h:"غضب القديسين"},"كان القديسون ودعاء . ولكن وداعتهم لم تكن تعنى سلبية مطلقة من جهة الشر ، أو عدم إنفعال على الإطلاق ، إذ كانوا يغضبون أحياناً غضباً مقدساً ، يعلنون به سخطهم على الخطية . وسنضرب لذلك أمثلة منها :",{h:"١ ـ غضب موسى النبى :"},"نعم ، موسى النبى الذى قال عنه الكتاب : « وأما الرجل موسى فكان حليماً جداً أكثر من جميع الناس الذين على وجه الأرض » ( عد ١٢ : ٣ ) . موسى هذا ، لما أبصر بنى إسرائيل يرقصون ويعبدون العجل الذهبى ، يقول الكتاب عنه : « فحمى غضب موسى . وطرح اللوحين من يديه وكسرهما ... ثم أخذ العجل الذى صنعوه وأحرقه بالنار وطحنه وذراه » ووبخ هرون ... ( خر ٣٢ : ١٩ ـ ٢١ ) .",{h:"ليس معنى الوداعة برودة فى الطبع ، بحيث لا ينفعل الإنسان إطلاقاً ، ولا يتحرك بالغضب !!"},"فالوديع قد يغضب أحياناً ، معبراً عن سخطه على الشر . ولكنه يغضب بأسلوب يتفق مع وداعته . يغضب ولا يخطىء ( أف ٤ : ٢٦ ) .","وهنا نرى موسى النبى يوبخ أخاه هرون فى حزم ، حتى أن هرون إرتبك أمامه ... ومع كل ذلك تشفع موسى فى الشعب لكى لا يفنيهم الله ."],12:[{h:"٢ ـ غضب اليهو :"},"كان الرابع بين أصحاب أيوب الصديق . وظل صامتاً طوال فترة حوارهم مع أيوب التى إستغرق سردها ٢٨ أصحاحاً . وأخيراً يقول الكتاب :",{h:"« فحمى غضب اليهو بن برخئيل البوزى من عشيرة رام . على أيوب حمى غضبه ، لأنه حسب نفسه أبر من الله . وعلى أصحابه الثلاثة حمى غضبه ، لأنهم لم يجدوا كلاماً وإستذنبوا أيوب » ( أى ٣٢ : ٢ ، ٣ ) ."},"تكلم اليهو ، ووبخ أيوب . ولم يستطع أيوب أن يجيب بحرف واحد كما أجاب على أصحابه الثلاثة . واليهو هو الوحيد الذى لم يوبخه الله من بين أصحاب أيوب . وكان فى غضبه يتكلم فى حكمة بكلام الله ، مع أنه كان أصغر الموجودين سناً ... ولم يخطىء إطلاقاً فى غضبه ، بل كان يُفَصِّلُ كلمة الحق باستقامة .",{h:"وعبارة « غضب اليهو » أو « حمى غضبه » لا تعنى هنا النرفزة ، إنما تعنى أن الذى حدث أمامه ، لم يسترح له ضميره ."},"لذلك وقف يحتج عليه ، ويبيّن الحق . لأنه كان ملآناً أقوالاً ، وكان روح باطنه يضايقه ( أى ٣٢ : ١٨ ) . وكان إنساناً لا يحب المحاباة ولا التملق ...","مثال آخر نذكره للغضب المقدس وهو :",{h:"٣ ـ غضب نحميا :"},"نحميا العظيم ، الذى غار غيرة للرب ، وأعاد بناء سور أورشليم ، بل أعاد البناء الروحى للشعب فى أيامه ، هو وزميله عزرا الكاتب .",{h:"لقد غضب جداً ، لأن العظماء يقرضون الشعب بالربا ."},"وكان الفقراء قد صرخوا يشتكون من هذا النير الواقع عليهم ، ومن أنهم فى جوعهم رهنوا بيوتهم وكرومهم وحقولهم . وهنا يقول نحميا : « فغضبت جداً حين سمعت صراخهم وهذا الكلام . وشاورت قلبى فىَّ . وبكّت العظماء والولاة . وقلت لهم إنكم تأخذون الربا كل واحد من أخيه . وأقمت عليهم جماعة عظيمة .. » ( نح ٥ : ١ ـ ٧ ) . لقد غضب . وعالج المشكلة بحزم ، وليس بعصبية . وأمر العظماء أن يردوا الربا الذى أخذوه من الفقراء . وأقام العدل بين الناس . وفى كل ذلك لم يخطىء ..."],13:[{h:"عقوبة عالى الكاهن :"},"لقد أخطأ أولاد عالى الكاهن خطية بشعة فى خيمة الإجتماع . وكان لابد من أخذ حق الله منهم . ولكنه تهاون فى ذلك ، ووبخهم بأسلوب غير حازم ( ١ صم ٢ : ٢٢ ـ ٢٥ ) .",{h:"وكانت النتيجة أن الله عاقب عالى الكاهن عقوبة مخيفة جداً ، لأنه لم يغضب غضبة مقدسة على أولاده ليردعهم عن خطاياهم ."},"وهكذا كلّم الله صموئيل النبى ـ وهو بعد صبى ـ وحمّله رسالة إلى عالى الكاهن . وقال له : « هوذا أنا فاعل أمراً فى إسرائيل ، كل مَنْ سمع به تطن أذناه . فى ذلك اليوم أقيم على عالى كل ما تكلمت به على بيته ... وقد أخبرته بأنى أقضى على بيته إلى الأبد ، من أجل الشر الذى يعلم أن بنيه قد أوجبوا به اللعنة على أنفسهم ولم يردعهم . ولذلك أقسمت لبيت عالى أنه لا يُكفّر عن شر بيت عالى بذبيحة أو بتقدمة إلى الأبد » ( ١ صم ٣ : ١١ ـ ١٤ ) .","ووقع عالى الكاهن من على كرسيه « فانكسرت رقبته ومات » كما مات إبناه ، وماتت كنته وهى تضع طفلها ( ١ صم ٤ : ١٨ ، ١٧ ، ٢٠ ) . وكانت عقوبة إلهية لعالى وابنيه وزوجة ابنه ، لأنه لم يغضب للرب .",{h:"هناك مواقف تحتاج إلى حزم . والحزم فيها يدخل فى نطاق الغضب المقدس ، ولا يكون غضباً خاطئاً ولا غضباً باطلاً ."},"وإن كان الشخص المسئول لا يغضب مطلقاً ، ولا يتصرف بحزم مهما كانت الأخطاء ، ولا يقيم الحق والواجب ، فإنه بلا شك يكون مخطئاً ، ويكون مقصراً فى مسئوليته . ولكن هناك فرق بين الحزم والنرفزة .",{h:"الحزم لا الترفزة"},"ولنضرب لذلك أمثلة من الحياة العملية :"],14:["١ ـ ربما تتقدم فتاة للتناول من سر الافخارستيا المقدس ، وهى فى زينة متبرجة غير لائقة ، فيثور عليها الأب الكاهن فى عصبية ظاهرة ، ويتنهرها بشدة ، وبكلمات قاسية أمام باقى السيدات ، فتترك الكنيسة وهى متألمة ساخطة ، وربما لا تعود إلى الكنيسة مرة أخرى . بينما كاهن آخر فى نفس الوقت ، يقول للفتاة كلمة حازمة فى هدوء وفى سر ، وبطريقة مقنعة وليست جارحة ، وتقتنع الفتاة ، وتنتبه للخطأ فلا تعاودة .","٢ ـ مثال آخر : مدرس فى مدرسة : لا يحفظ التلاميذ النظام ، فيفقد أعصابه ، ويظل يصيح ويوبخ وربما يشتم ويضرب ، ويلاحظ الطلبة أنه سهل الاستثارة فيتخذونه لعبتهم ، ويجدون لذة فى إثارته . بينما مدرس آخر يضبط نظام الفصل بحزم ، دون نرفزة ، و يكون موضع إحترام التلاميذ وطاعتهم .","٣ ـ وبنفس الوضع نتكلم عن أب جسدانى ، أو أى إنسان فى موضع الرئاسة ، أو فى وظيفة التربية . قد يتصرف فى حزم وحسم . ومن حقه بل من واجبه أن يتصرف هكذا . ولكنه فى غضبه لا يخطىء .",{h:"٤ ـ مثال آخر : وهو أن الكنيسة المقدسة قد غضبت على البدع والهرطقات وعالجتها بكل حزم ."},"واضح جداً موقف الكنيسة فى المجامع المسكونية والمكانية ، وفى أحكام الآباء البطاركة والأساقفة حماة الإيمان . بل إن رسولاً عظيماً إشتهر جداً بالحب حتى لقبوه : [ يوحنا الحبيب ] نراه يقول فى حزم فى آخر رسالته الثانية : « إن كان أحد يأتيكم ولا يجىء بهذا التعليم ، فلا تقبلوه فى البيت ، ولا تقولوا له سلام . لأن مَنْ يسلّم عليه ، يشترك فى أعماله الشريرة » ( ٢ يو ١٠ ، ١١ ) . هذا هو الحزم والغضب للحق ، فى غير نرفزة .",{h:"٥ ـ قال القديس دياراخوس : الغضب العفيف هو ذلك الذى لو استعملته حواء مع الحية ، ما كانت قد إنفعلت باللذة الألمية ."}],15:["أى لو كانت أمنا حواء غضبت لأن الحية قالت لها ما هو عكس وصية الله ، وفى هذا الغضب رفضت نصيحة الحية ، ما كانت قد أخطأت . ونقصد بالغضب هنا الحزم فى رفض كل غرض خاطىء . وندعو إلى هذا الحزم كل إنسان يتعرض لإغراء أثيم .",{h:"لا تقل ( الوداعة ) وتستسلم وتخطىء !!"},"٦ ـ ومثال آخر هو موقف بولس الرسول من خاطىء كورنثوس .","هذا القديس العظيم الذى تكلم عن المحبة كأعظم الفضائل ( ١ كو ١٣ : ١٣ ) ، نراه فى نفس الرسالة يغضب جداً بسبب ذلك الخاطىء الزانى ، و يصدر عليه حكماً شديداً يأمر فيه باسم ربنا يسوع المسيح : « أن يُسلّم مثل هذا للشيطان لهلاك الجسد ، لكى تخلص الروح فى يوم الرب » ( ١ كو ٥ : ٥ ) . وفى نفس الوقت يوبخ أهل كورنثوس توبيخاً شديداً ، حتى أنه يذكر فى رسالته الثانية إليهم أنه أحزنهم ويقول : « لأنه إن كنت أحزنكم أنا ، فمَنْ هو الذى يفرحنى إلاّ الذى أحزنته » ( ٢ كو ٢ : ٢ ) . وعاد فعفا عن ذلك الخاطىء لما تاب وانسحق ( ٢ كو ٢ : ٦ ، ٧ ) .",{h:"ولهذا كله يمكن أن يغضب الإنسان ولا يخطىء ، إن كان غضباً مقدساً . على أن هناك معنى آخر لقول الكتاب : « إغضبوا ولا تخطئوا » ( أف ٤ : ٢٦ ) ."},{h:"اغضبوا ولا تخطئوا"},"أجاب يوحنا كاسيان على سؤال هام هو :",{h:"متى ينفع الغضب ويصلح ؟"},"فقال إن الأستثناء الوحيد (١) الذى يصلح فيه الغضب ، هو غضبنا على خطايانا وشهواتنا ونقائصنا .","(١) يوحنا كاسيان : كتاب المعاهد : حرب الغضب ."],16:["ويرى أن هذا هو الاستعمال الطبيعى للغضب فينا . فيقول : [ إن لنا إستعمالاً للغضب مغروساً بامتياز فينا ، من أجله وحده فقط من المفيد والنافع لنا أن نسمح بالغضب . أعنى عندما نكون غاضبين وحانقين ضد عواطف القلب الشهوانية ومتكدرين ، لأن الأمور التى نخجل من فعلها أو التفوه بها أمام الناس ، قد قامت فى خفايا قلوبنا ... مرتعبين أقصى الرعب من عين الله الذى لا يمكن أن تخفى عليه أسرار القلوب ] .",{h:"وضرب كاسيان مثلاً بداود الملك ، عندما إشتهى أن يشرب ماء من بئر بيت لحم ،"},"فاقتحم ثلاثة من رجاله الأبطال معسكر العدو وجلبوا له الماء . ولكن داود ضرب به قلبه ، وغضب على نفسه كيف يرمى رجاله إلى الخطر لكى يشرب هو . وفى الحال سكب الماء على الأرض دون أن يرضى شهوته فى الشرب ، معبراً عن ذلك بقوله : حاشا لى يارب أن أفعل ذلك ، أن أشرب دم أولئك الرجال الذين خاطروا بأنفسهم ( ٢ صم ٢٣ : ١٥ ـ ١٧ ) .","ثم تعرض كاسيان لقول الكتاب : « اغضبوا ولا تخطئوا » ( أف ٤ : ٢٦ ) . وقد إقتبسها القديس بولس الرسول من مزامير داود ( مز ٤ : ٤ ) . وشرح أنها تنطبق على تفسيره فى حصر غضبنا ضد أنفسنا فقال : البعض أمروا أن يغضبوا بطريقة سليمة ، ولكن على أنفسنا وعلى الأفكار الشريرة التى تقوم فينا .",{h:"ووضح أنه بغضبنا على هذه الأفكار الشريرة لا نخطىء . أى لا يكون فى غضبنا خطأ . كما أن من نتيجة غضبنا على هذه الأفكار أننا لا نخطىء ."},"وقال إن تكملة الآية ( مز ٤ : ٤ ) تشرح أن هذا هو المعنى الأكثر وضوحاً . إذ بعدها مباشرة « الذى تقولونه فى قلوبكم ، إندموا عليه فى مضاجعكم » . أى أن كل ما تفكرون فيه فى قلوبكم ، عندما تندفع فيكم المثيرات .. هذا وبخوه وعدلوه بندم صحيح ...","وأراد كاسيان أن يثبت تفسيره هذا بحسبما وردت هذه الآية فى رسالة القديس بولس ، فقال : [ إن الرسول المغبوط بولس ، عندما استشهد بهذه الآية وقال : « إغضبوا ولا تخطئوا » أضاف : « لا تغرب الشمس على غيظكم ، ولا تعطوا إبليس مكاناً » ( أف ٤ : ٢٦ ) ] ."],17:[{h:"لا تغرب الشمس على غيظكم"},"يفسر كاسيان كلمة « الشمس » هنا تفسيراً رمزياً ، بأنها شمس البر ( ملا ٤ : ٢ ) . ولم يسمح كاسيان بتفسير الآية حرفياً ، وإلاّ كان الرسول يسمح بأن يستمر غيظنا حتى الغروب ..! .","وفى هذا يقول : إن كان شرعياً أن نغضب حتى غروب الشمس ، فإن تخمة سخطنا ، أو إنتقام غضبنا ، سيمكنه أن يلعب دوراً كاملاً للألم والإثارة الخطرة قبل أن تميل الشمس إلى غروبها .",{h:"ورأى كاسيان أن التفسير الحرفى لهذه الآية يتنافى مع ما تسلمه من تعليم الشيوخ الذين « لم يسمحوا للغضب ولا بلحظة واحدة يجد فيها مدخلاً إلى قلوبنا » ."},"وهكذا لجأ إلى التفسير الرمزى فقال : [ وعن هذه الشمس ، فإن الله يذكر ذلك بوضوح على لسان النبى عندما يقول : « ولكن لأُولئك الذين يخافون إسمى تشرق شمس البر والشفاء فى أجنحتها » ( ملا ٤ : ٢ ) ] .","ويستطرد : [ إن كان من الخطر أن يغرب شمس البر على سخطنا ، فإننا كنا عندما نغضب فإننا فى الحال نعطى لإبليس مكاناً فى قلوبنا ، فكيف إذن يوصينا الرسول قبلاً أن نغضب بقوله « اغضبوا ولا تخطئوا » ؟! ألا يقصد هذا بوضوح :",{h:"اغضبوا على أخطائكم وعلى طباعكم . لئلا إن قبلتموها ، فإن المسيح ـ شمس البر ـ يبدأ بسبب غضبكم أن يغرب عن عقولكم المظلمة . وإذ يرحل عنكم ، فإنكم تهيئون مكاناً لإبليس فى قلوبكم ."}],18:[{h:"تعليق :"},"إننا لا نمانع مطلقاً فى أن يكون أحد تفاسير هذه الآية « اغضبوا ولا تخطئوا » هو الغضب على خطايانا ونقائصنا . فليس كل غضب هو غضب على الآخرين فقط ، بينما توجد عيوب فى النفس تستلزم الغضب أيضاً ..",{h:"لذلك إغضب على الخشبة التى فى عينك ، قبل أن تغضب على القذى الذى فى عين أخيك ( مت ٧ : ٥ ) . ولا تطوى الليل دون أن تغضب على خطاياك .."},"فإن غضبت على نفسك الخاطئة ، لا تخطىء ، لأنه غضب فيه إصلاح لنقائصك . وغضبك على خطاياك ، إنما يدعوك إلى التوبة .","ونحن لا نريد أن نتمادى فى التفسير الرمزى ، لأن هناك حالات غضب مقدس غير غضبنا على أنفسنا ، ذكرنا أمثلة لها . وأيضاً لكى لا ندين القديسين الذين يغضبون من أجل الحق . إنما فى الغضب المقدس ، نفرق بين الغضب والنرفزة . فالنرفزة خطأ ... والقديسون قد غضبوا من أجل الحق دون نرفزة . فالنرفزة هى عدم ضبط للأعصاب ..."],19:[{h:"الفصل الثانى : الغضب الخاطىء أو الباطل"},"ما هو الغضب الخاطىء ؟","أقوال الكتاب فيه .","ذم الآباء له .","خطية منفرة ومركبة .","أمثلة من الغضب الخاطىء .","نتائج الغضب السيئة ."],20:[{h:"ما هو الغضب الخاطىء ؟"},"هناك غضب باطل ، عنه قال السيد المسيح له المجد : « قد سمعتم أنه قيل للقدماء لا تقتل ، ومَنْ قتل يكون مستوجب الحكم . وأما أنا فأقول لكم إن كل مَنْ يغضب على أخيه باطلاً ، يكون مستوجب الحكم » ( مت ٥ : ٢١ ، ٢٢ ) . والخطورة هنا أن السيد قد تحدث عن الغضب الباطل فى نطاق حديثه عن القتل ...",{h:"والغضب الباطل هو غضب لأسباب شخصية ، أو لأمور مادية أو عالمية ، وليس لسبب مقدس ."},"وقد وجه أحد الإخوة سؤالاً إلى القديس الأنبا بيمن عن معنى الغضب الباطل الذى ورد ذكره فى العظة على الجبل فى ( مت ٥ : ٢٢ ) فأجاب :",{h:"[ إن عاملك أخوك بالظلم والإساءة والاحتيال ، فغضبت بسبب هذا ، فإن غضبك هذا يكون باطلاً ، لأنك غضبت لأجل أسباب باطلة ... ] ."},"و يكمل القديس حديثه فيقول : [ ولكن إن أراد أحد أن يبعدك عن الله ، فحينئذ إن غضبت ، يكون ذلك شيئاً حسناً ] .","والغضب الباطل له مظهران : أولهما أنه لأجل أمور باطلة زائلة دنيوية أو لمسائل شخصية .",{h:"وثانيهما أن هذا الغضب يتم بطريقة باطلة ، يفقد فيها الإنسان أعصابه ويخطىء ..."},"وهكذا يمكن القول بأن الغضب الباطل هو أيضاً غضب خاطىء فيه النرفزة وتوتر الأعصاب مع ما يصاحب هذا من أخطاء سنذكرها إن شاء الله ..."],21:[{h:"أقوال الكتاب عنه"},"يكفى فى ذم الغضب ما ورد فى رسالة القديس يعقوب الرسول ، إذ يقول :",{h:"« لأن غضب الإنسان لا يصنع بر الله » ( يع ١ : ٢٠ ) ."},"ولعل المقصود هو الغضب الإنسانى ، الذى لأسباب بشرية ... فهو لا يتفق مع البر الذى يريده الله ... ولذلك نرى أن الرعاة يشترط فيهم الكتاب عدم الغضب . إذ ورد فى الرسالة إلى تيطس عن شروط الأسقف أنه « لا يكون غضوباً ... ولا ضراباً ... بل متعقلاً ورعاً ضابطاً لنفسه » ( تى ١ : ٧ ، ٨ ) .","وقد وردت آيات كثيرة فى سفر الأمثال ضد الغضب ، نذكر من بينها :",{h:"« الرجل الغضوب يهيج الخصام ، والرجل السخوط كثير المعاصى » ( أم ٢٩ : ٢٢ ) ."},"وسنذكر إن شاء الله هذه المعاصى الكثيرة المتسببة عن الغضب ، حينما نتحدث عن الغضب بصفته خطية مركبة . وقد ورد فى سفر الأمثال أيضاً : « الحجر ثقيل ، والرمل ثقيل . وغضب الجاهل أثقل منهما » ( أم ٢٧ : ٣ ) . وعن هذا الجهل ورد فى سفر الجامعة :",{h:"« لا تسرع بروحك إلى الغضب . لأن الغضب يستقر فى حضن الجهال » ( جا ٧ : ٩ ) ."},"ومن هنا يتبين أن الغضب بعيد عن الحكمة . فالحكيم يبعد عن الغضب الجاهل .","ونرى أن أبانا يعقوب أبا الآباء فى مباركته لأبنائه قبل موته ، تكلم بشدة عن غضب ابنيه شمعون ولاوى ، فقال :",{h:"« معلون غضبهما فإنه شديد ، وسخطهما فإنه قاس » ( تك ٤٩ : ٤٦ ) ."},"ومن أجل هذا السبب قال : « فى مجلسهما لا تدخل نفسى ، بمجمعهما لا تتحد كرامتى » . ولعله فى قراره هذا يذكرنا بقول الكتاب :"],22:[{h:"« لا تستصحب غضوباً ، ومع رجل ساخط لا تجىء » ( أم ٢٢ : ٢٤ ) ."},"ولا ننسى نصيحة الأم القديسة رفقة لإبنها يعقوب ، لما إشتد عليه غضب أخيه عيسو . فقالت له : « إهرب إلى أخى لابان إلى حاران ، وأقم عنده ... حتى يرتد سخط أخيك ، حتى يرتد غضب أخيك عنك .. » ( تك ٢٧ : ٤٣ ـ ٤٥ ) . ذلك لأن عيسو فى حقده على يعقوب من أجل البركة التى باركه بها أبوه ، قال فى قلبه ... أقتل يعقوب أخى ( تك ٢٧ : ٤١ ) .","والكتاب يمنعنا عن الغضب بأنواعه ، فيقول الرسول :",{h:"« ليرفع من بينكم كل مرارة وسخط وغضب وصياح ... وكونوا لطفاء بعضكم نحو بعض ، شفوقين متسامحين ، كما سامحكم الله أيضاً فى المسيح » ( أف ٤ : ٣١ ، ٣٢ ) ."},{h:"أقوال الآباء ضد الغضب"},"قال مار أوغريس : الغضب موجه بالطبيعة إلى إثارة الحرب مع الشياطين ، وإلى الصراع مع كل نوع من اللذة الخاطئة . ولكن الشياطين إذ تجذبنا إلى الشهوات العالمية ، تجعلنا نستخدم الغضب فى محاربة الناس ، الأمر الذى هو ضد الطبيعة .","القديس مار أوغريس","كما أن الماء يضطرب بقوة الريح ، كذلك الغضوب يضطرب بأفكار الرجز .","الإنسان الوديع هو مثل ينبوع رائق يروى كل أحد بطيبه . أما الغضوب فهو معكر كل حين ، ولا يعطى ماء للعطشان . النفس غير الغضوبة تصير مسكناً للروح القدس ، والمسيح يستريح فى قلب الوديع المملوء بالسلام .","عينا الغضوب شريرتان مملوءتان دماً ، وهو طالب بقلب قلق . وأما وجه الوديع فهو بهى ، وعيناه تنظران بحشمة ."],23:["صلاة الغضوب هى بخور نجس مرذول . وقربان الغضوب ذبيحة غير مقبولة .","القديس مار أوغريس","قال شيخ :","إن الذى يخاصمه أخوه ولا يحزن قلبه ، فقد تشبه بالملائكة . فإن خاصمه هو أيضاً ، ثم رجع من ساعته فصالحه ، فهذا هو عمل المجاهدين . أما الذى يُحزن إخوته ويحزن منهم ، ويمسك الحقد فى قلبه ، فهذا مطيع للشيطان ومخالف لله . ولا يغفر الله له ذنوبه ، إن لم يغفر هو لإخوته .","بستان الرهبان","إذا صار الإنسان كاملاً فى كل الحسنات ، بينما فى قلبه وجد على أخيه ، فهو غريب عن الله .","القديس الأنبا باخوميوس","ولو أقام الغضوب أمواتاً ، فما هو مقبول عند الله ، ولا يُقبل إليه أحد من الناس .","القديس الأنبا أغاثون","إن الذى يصوّم فمه عن الغذاء ، ولا يصوّم قلبه عن الغضب والحقد ولسانه عن الأباطيل ، فصومه باطل .","صلاة الحقود كبذار وقع على الصخر ... الحقود يستثمر فى صلاته ، ما يستثمره الزارع فى البحر من الحصاد .","النفس العاقر هى التى لبست الحقد والغيظ وضيق الصدر والكآبة والضجر والإضطراب ، وتدين قريبها بجيد ورديء .","مار إسحق","القلب المتوقد بالغضب هو فارغ من العزاء الخفى ، وعادم أيضاً من العزين الذين من خارج . لأن العزاء الجوانى هو الذى يقبل العزاء البرانى و يهتم به .."],24:["الموضع الذى فيه حركة الغضب والحسد ، لا يمكن أن تثبت أو تقام فيه الفضائل . وإن وُجدت فإنها تنحجب بظلمة الغضب والغيرة والتكدر .",{h:"إن كنت ترى أن المذمات توجعك ، فاعلم أنك مسروق من المجد الباطل ."},"مار إسحق","الرجل الشهوانى ، وإن لم يكن رزيناً ولا هادئاً ، لكن تفيض منه حلاوة الحب والرحمة . والرجل الغضوب ، وإن كان متأسساً فهيماً ، لكن يعمل فيه عكر الدم الأسود للظلام ، ونفسه مريرة ومملوءة كآبة وغيظاً ، وهو متغير اللون وسىء المنظر ..","سلاح الغضب يؤذى صاحبه . وسلاح التواضع يشرّف لابسيه .","طول الروح هو طبيب قانيه ... والغضب فى القلب كالسوس فى الخشب .","الغضب هو كلسبٌ كَلِبٌ ينبح على كل الناس . لأن الغضوب لا يستطيع أن يتكلم بالسلام .","الغضب يوصل إلى السخط . فعندما يجن الشخص ويتمكن السخط منه ، يمتلىء ضميره من الحقد . والحقد يحرك الغضب والرجز ، ويظهر سخطه عندما تسنح له الفرصة حسب إرادته .","القديس يوحنا الأسيوطى","الغضب هو ألم لا إستحياء فيه ولا خجل . ووداعة الرجل أن يقمع الغضب .","القديس مار إفرام","شيطان الحرد هذا ، مظلم ومرّ الفعل ، يذكّر النفس بأعمال قد عبرت أو هى مزمعة أن تحدث . ويوقظ الغضب ... وربما تختطف الشياطين العقل ، وتطيش به ، وتنقله من قرية إلى قرية ، ومن بيت إلى بيت ، وتذكره بكلام وبأعمال ترد إلى الضمير ..","قلب الغضوب مستوحش من أسرار الله ... إحذر من الحرود لأنه شيطان متجسد ...","الويل للحرود فإن قلبه مسكن للأفاعى ... الحرود مع مَنْ يصطلح ؟! لأنه دائماً يكدر قلبه و يُبعد عنه روح الله .","الشيخ الروحانى"],25:["قال الأب إيرايس : مَنْ لا يقدر أن يضبط لسانه وقت الغضب ، فلن يقدر أن يغلب ولا صغيرة من صغار الآلام .","قال شيخ : إحذر الغضب لأنه يظلم العقل ، ويلقى من النفس مخافة الله . إن الغضب أبو الجنون . فمَنْ يقبله لا يكون وديعاً أمام الله .","بستان الرهبان","الغضب هو حركة للجنون . والذى يقتنيه لنفسه فإنه يحيره ، ويجعل النفس مثل الوحوش ... الغضوب قلبه صغير ، يفكر أن يجازى الشر بالشر . له قساوة فى الكلام وفى الفعل . لا يشاء أن يرحم . يغضب حتى على الحيوان .","يتحرك بالغضب . يبغض أخاه بقلبه . يتقول عليه كلاماً رديئاً . يقاومه . يخاصم . يشتم . يدين .","الشيطان يلقى فىَّ غضباً على أخى . يمنعنى من الإجابة باتضاع . ينزع محبتى للإخوة . يذكرنى بالشر على أخى . كأنه زهدنى أو جلب علىَّ خسارة ، أو صنع بى ما لا يليق . يجعل قلبى مملوءاً بالشر أثناء الصلاة .","القديس مار أوغريس","الغضب هو أسرع الآلام كلها . إنه يثار ويلتهب ضد إنسان قد عمل أو يبدو أنه عمل للشخص ضرراً . وهو يقسّى النفس أكثر وأكثر . ويأسر العقل أثناء الصلاة ، ويجلب وجه مَنْ أساء ... وإذ يقيم فى النفس يتحول إلى عداء ...","القديس مار أوغريس","مَنْ يقدر أن يشرح بطريقة وافية الآثار الشريرة التى للغضب ؟ أية عظة يمكن أن تصف كيف أنه مخجل هذا المرض ؟!",{h:"إنك ترى أن آلام الشخص المصروع بروح نجس تظهر فى الذين يسيطر عليهم الغضب ..!"}],26:["تأمل جنباً إلى جنب علامات الشيطان وعلامات الغضب ، وأى فارق يوجد بين الاثنين ! عين مَنْ عليه شيطان حمراء كالدم وحائرة ، لسانه غير مستقر ، وكلامه خشن ، وصوته يُسمع حاداً كالنباح ... ويتنفس بشدة ...","وهذه العلامات مشتركة ... رأسه مندفعة بوحشية . ويداه تعملان حركات لا يشعر بها . وكل جسده يهتز . ورجلاه تتمايلان . هذا الوصف مشترك بين المرضين .","إنهما يختلفان فى شىء واحد . وهو أن أحدهما إختيارى ، والآخر يحدث لضحاياه ضد إرادتهم .","القديس اغريغوريوس","أسقف نيصص","السخوط يقتل نفسه .. هو غريب عن السلامة ، وعادم الصحة . لأن جسده يذوب كل حين ، ونفسه مغمومة ، وبشرته ضامرة ، ولونه لا نضارة له . وذهنه يتغير ، وأفكاره تنبع كفيض النهر . وهو ممقوت من الكل ، ومرذول عند الله والناس .","إنه خالٍ من طول الأناة ومن المحبة . ومن أجل أمر حقير يثير خصومات ، ويجمع لذاته البغض ..","القديس مار أفرام",{h:"خطية منفّرة ومركبة"},"ليس الغضب مجرد خطية بسيطة ، بل هو مجموعة من الخطايا مركبة معاً فى أسبابها وتشعباتها ونتائجها .",{h:"١ ـ خطية فيها الحدة والعصبية :"},"سواء من جهة حدة الصوت أو علوه أو إنفعاله ، يشترك فيها الصوت مع الأعصاب م الملامح أيضاً . و يكون الإنسان كله فى حالة غضب ، أو ثورة .."],27:[{h:"٢ ـ ومع الغضب يوجد عدم المغفرة :"},"لأنه لو حدث أن الشخص قد غفر لمَنْ أساء إليه ، ما كان يغضب عليه ولا ينفعل ولا يثور ... وحينما لا يغفر الإنسان لغيره فى حالة الغضب يعرض نفسه لفقدان غفران الله ، إذ قيل « إن لم تغفروا للناس زلاتهم ، لا يغفر لكم أبوكم السماوى زلاتكم » ( مت ٦ : ١٥ ) .",{h:"٣ ـ ويحمل الغضب داخله قسوة فى القلب :"},"تزداد شدة هذه القسوة بإزدياد حدة الغضب . وقد تصل فى بعض الحالات إلى الضرب وإلى الاعتداء . وقد تصل أحياناً إلى القتل ، كما فكر عيسو فى غضبه أن يقوم ويقتل يعقوب أخاه ( تك ٢٧ : ٤٥ ) . وقد قيل فى الكتاب : « الغضب قساوة » ( أم ٢٧ : ٤ ) .",{h:"٤ ـ ولذلك يحمل الغضب أيضاً لوناً من البغضة :"},"ذلك لأن « المحبة تحتمل كل شىء » ( ١ كو ١٣ : ٧ ) . ولكن فى وقت الغضب ، وبخاصة الغضب الشديد ، تختفى مشاعر المحبة . وإذا إزدادت حدة الغضب ومدته ، يتحول إلى كراهية ...",{h:"٥ ـ وخطية الغضب تتنافى مع الوداعة ومع اللطف :"},"فيها يفقد الإنسان وداعته . يفقد حلمه وهدوءه . ويفقد اللطف والبشاشة والحنان ، و يتحول إلى إنسان ثائر يقرب طبعه من طبع الوحوش ...",{h:"٦ ـ وفى الغضب يفقد فضيلة التواضع أيضاً :"},"لأنه كما يقول القديس دوروثيئوس : إن الإنسان المتواضع لا يُغضب أحداً ، ولا يغضب من أحد .","فالمتواضع باستمرار يجلب الملامة على نفسه فلا يغضب . كما أنه يلتمس بركة كل أحد وصلواته ورضاه ، لذلك لا يسمح لنفسه بأن يُغضب أحداً . أما الغضوب فهو على عكس هذا . ولذلك ..."],28:[{h:"٧ ـ خطية الغضب ترتبط دائماً بخطية إدانة الآخرين :"},"لأنه لولا أن الغضوب يدين غيره ، ما كان يثور عليه . وقد تصل هذه الإدانة إلى مستويات صعبة . وقد تكون على غير حق . وهنا ...",{h:"٨ ـ يقع الغضوب أحياناً فى خطية الظلم :"},"فيحكم على غيره بأحكام هو برىء منها ، أو على الأقل لم يصل إلى مستواها . وقد تدفعه إلى الغضب أفكار مبنية على سوء الظن . وفى سوء ظنه يتصور حدوث أمور لم تحدث . ولكنه فى ظلمه يؤكد أن ما يظنه هو حقيقة واقعة ..",{h:"٩ ـ وفى غضبه قد يقع فى الشتيمة والإهانة :"},"و يتلفظ بألفاظ جارحة ، ويفقد إحترامه لغيره ، و يتصرف بأسلوب غير لائق ، يلومه عليه الناس ، وقد يندم هو عليه حينما تهدأ أعصابه الثائرة .","وفى كل هذا يكون مداناً . لأن السيد الرب قال فى العظة على الجبل : « مَنْ قال لأخيه رقا ( أى أقل عبارة تدل على عدم الإحترام ) يكون مستوجب المجمع » ( مت ٥ : ٢٢ ) .",{h:"١٠ ـ وقد يقع فى كثير من خطايا اللسان :"},"ولا نستطيع أن نحصى هذه الخطايا ، لأنها تتوقف على مدى حدة الغضب ، ومدى عدم قدرة الغضوب فى ضبط أعصابه وفى ضبط مشاعره وفى ضبط لسانه .",{h:"١١ ـ وإذا ترسب الغضب فى القلب يلد حقداً :"},"وقد تبدأ المشاعر تتطور من غيظ وسخط ، حتى تصل إلى الحقد . ثم تتبادل المواضع : فالحقد أيضاً يلد غضباً وغيظاً وسخطاً ... و يصير القلب مستودعاً لعديد من المشاعر الخاطئة ، كل منها تشجع الأخرى .",{h:"١٢ ـ والغضب هو ثورة تهدف إلى الإنتقام :"},"فالغضوب يريد أن ينتقم لنفسه ، لكرامته أو لحقوقه . يريد أن يرد اعتباره . وأن يكافىء الشر بالشر . وبهذا يدخل فى الإنتقام . ولذلك فإن القديس بولس الرسول"],29:["يقول : « لا تنتقموا لأنفسكم أيها الأحباء ، بل اعطوا مكاناً للغضب » ( رو ١٢ : ١٩ ) . أى اعطوه مكاناً يخرج منه أو يتسرب منه . افتحوا له فتحة فى القلب يخرج منها ، ولا تخزنوه داخلكم .",{h:"١٣ ـ والغضب يحمل داخله خطية أخرى هى عدم الإحتمال :"},"لأنه لو إستطاع أن يحتمل إساءة المسىء ما كان يغضب . ولكن بغضبه يدل على ضيق الصدر وضيق القلب وعدم القدرة على الاحتمال .",{h:"١٤ ـ وقد يتحول الغضب إلى خصومة وإلى معارك :"},"لأنه ما يخطىء به الإنسان فى غضبه ، ربما لا يستطيع أن يعالج نتائجه . فما تلفظ به من شتائم أو إهانات أو ترديدات أو جرح للشعور أو إتهامات ظالمة ... هذا كله قد يترك فى نفسية الطرف الآخر تأثيرات عميقة قد تدفعه هو أيضاً إلى العداوة والإنتقام . وهكذا حتى لو تاب الغضوب عن غضبه ، ربما تظل نتائج غضبه باقية ..",{h:"١٥ ـ وتدخل فى خطية الغضب أيضاً خطية إعثار الآخرين :"},"فالغضوب يعثر الطرف الآخر الذى يغضب عليه ، و يعثر أيضاً كل مَنْ شاهد ثورة الغضب وسمع ما تردد فيها من ألفاظ غير لائقة ومن هياج وصياح ...",{h:"١٦ ـ ومع الغضب قد تكمن خطية التهور والإندفاع :"},"فغالباً ما يكون الغضب مصحوباً بالتسرع أو نتيجة للتسرع والإندفاع ، حيث يأخذ الإنسان قرارات خطيرة وهو فى حالة إنفعال . وتكون هذه القرارات ضد نفسه أو ضد الآخرين . ومثال ذلك غضب داود النبى من نابال الكرملى حيث قال : « هكذا يصنع الله لأعداء داود وهكذا يزيد ، إن أبقيت من كل ماله إلى ضوء الصباح بائلاً بحائط » وأمر غلمانه أن يتقلد كل واحد منهم سيفه ( ١ صم ٢٥ : ٢٢ ، ١٣ ) . وكان ـ فى حمو غضبه ـ على وشك أن يقتل نابال وكل الذين له ... لولا أن هدأته إبيجايل .",{h:"١٧ ـ وفى الغضب فقدان للصورة الإلهية :"}],30:["فالإنسان قد خُلق على صورة الله ومثاله ( تك ١ ) . ولكنه فى حالة الغضب لا يكون هكذا . بل يبدو فى صورة منفرة معثرة ، لا تتفق مع المستوى الروحى اللائق به .",{h:"١٨ ـ وقد يفقد الغضوب كثيراً من علاقاته :"},"يفقد علاقته بمَنْ يغضب عليه . كما أن كثيراً من قضايا الطلاق والمشاكل الزوجية سببها الغضب . وقد يفقد الإنسان علاقته بالله والكنيسة فى وقت غضبه ، إذ يتلفظ بألفاظ تجاديف ، و يهدد بترك الله والكنيسة .",{h:"١٩ ـ خطية الغضب أيضاً ضد فضيلة السلام :"},"إذ يفقد الإنسان سلامه الداخلى ، سلام القلب والفكر ، كما يفقد فى نفس الوقت سلامه مع الناس .",{h:"٢٠ ـ وخطية الغضب ضد فضيلة الفرح ، التى هى من ثمار الروح ..."},"لأن ساعة الغضب هى ساعة نكد وكآبة له ، وربما لغيره أيضاً ...",{h:"وهكذا يفقد غالبية ثمار الروح القدس فى القلب :"},"إذ يفقد المحبة ، والفرح ، والسلام ، وطول الأناة ، والوداعة ، واللطف ، والصلاح ... ماذا يبقى إذن له فى ثورة غضبه ؟!..",{h:"٢١ ـ والغضب أيضاً مصحوب بالجهل ..."},"جهل الإنسان بما يفيده وما يضره ، وجهله بالنتائج السيئة التى لغضبه ، إذ يفقد علاقاته مع الناس ، وقد يدمر سلام بيته وأسرته ، و يفقد سمعته وفكرة الناس عنه ، و يفقد أثناء كل ذلك روحياته وأبديته . وقد يفقد وظيفته أو ترقيته ، إن كان غضبه عنيفاً مع رؤسائه فى العمل ... وربما فى لحظة يضيّع ما بناه فى سنوات ..!",{h:"حقاً ، إنها خطية مدمرة .. ولذلك قال الكتاب :"},{h:"« لا تسرع بروحك إلى الغضب ، لأن الغضب يستقر فى حضن الجهال » ( جا ٧ : ٩ ) ."}],31:["إنسان يدمر كل ماله . يدمر ثمار الروح فى قلبه ، و يفقد صورته الإلهية ، ويخرب كل ما بينه وبين الناس من علاقات ... ويحاول أن يبرر كل ذلك فيقول [ إنها ساعة غضب ] ...!","وهل فى ساعة غضب يحدث كل هذا ؟!","حقاً ما أصدق قول الحكيم : « الحجر ثقيل . والرمل ثقيل . وغضب الجاهل أثقل منهما » ( أم ٢٧ : ٣ ) . وصدق ما قاله أبونا يعقوب عن ابنيه « ملعون غضبهما فإنه شديد ، وسخطهما فإنه قاس » ( تك ٤٩ : ٧ ) .",{h:"إذن هى خطية مركبة ... والغريب أن مَنْ يخطىء فى كل هذا ، يجمعه فى عبارة واحدة فى أعترافه أمام الأب الكاهن . فيقول مجرد كلمة [ غضبت ] أو [ وقعت فى خطية الغضب ] ."},'يقولها دون تفاصيلها البشعة ... ويرد عليه الأب الكاهن : [ معلهشى يا ابنى . ثانى مرة لا تغضب ] ... ويمضى المعترف فى هدوء ، وكأنه لم يعمل شيئاً !! " وبراءة الأطفال فى عينيه " !!...',{h:"أمثلة من الغضب الخاطىء"},{h:"١ ـ أول مثال فى العالم ، هو مثال قايين :"},"غضب لأن الله قبل ذبيحة أخيه هابيل ، بينما لم يقبل تقدمته هو . وفى هذا يقول الكتاب : « فاغتاظ قايين جداً وسقط وجهه » ( تك ٤ : ٥ ) .",{h:"وهنا نرى غضباً مصحوباً بالغيرة أو الحسد ."},"وظلت مشاعر الغضب تقتل كل خير فى قلب قايين . بل ظل الغيظ يلتهب حتى قال الكتاب : « وحدث إذ كانا فى الحقل ، أن قايين قام على هابيل وقتله » ( تك ٥ : ٨ ) .",{h:"ونلاحظ أن الغضب هنا مصحوب بالظلم وبالقسوة ."},"فما ذنب هابيل أنه بار ، وأن الله قد قبل ذبيحته ؟! وماذا كان بإمكانه أن يفعل"],32:["ليرد غضب أخيه عنه ؟! كان غضب قايين ظالماً بلا شك . وكان قاسياً إذ إرتكب أول جريمة قتل فى تاريخ البشرية . وحسناً أن السيد المسيح تحدث عن عقوبة الغضب أثناء حديثه عن جريمة القتل ( مت ٥ : ٢١ ، ٢٢ ) .",{h:"٢ ـ مثال غضب شمعون ولاوى :"},"قال عنهما أبونا يعقوب : « آلات ظلم سيوفهما ... » ( تك ٤٩ : ٥ ) . إنه نفس الغضب المصحوب بالقسوة والظلم . إنه يذكرنا بقول الكتاب : « مَنْ يغضب على أخيه باطلاً » ( مت ٥ : ٢٢ ) .",{h:"٣ ، ٤ ـ مثال عيسو ، ومثال داود :"},"غضب عيسو على يعقوب وأراد قتله . وربما يقول إن ذلك لأسباب روحية !! بسبب تمسكه بالبكورية والبركة . ولكن طلب الأمور الروحية لا يكون بوسائل خاطئة . لم تكن البركة هى السبب ، وإنما الذات ...","وداود غضب على نابال وأراد قتله ، لأسباب مادية ، لأنه لم يقدم له ولغلمانه طعاماً .",{h:"وهكذا كانت ( الذات ) وراء غضب داود ، كما كانت ( الذات وراء غضب عيسو ) ."},"سواء كانت الذات تطلب شيئاً روحياً أو مادياً . ولا شك أن كل غضب فى الدنيا وراءه الذات . والذات تقدم لنا مثالاً آخر من الغضب هو :",{h:"٥ ـ غضب شاول الملك على داود :"},"سببه الذات أيضاً . كان شاول يرى ذاته أقل من داود فى كل شىء ، و يرى داود ناجحاً فى كل شىء ، ومحبوباً من كل أحد . فانقلب الحسد فى قلبه إلى خوف من داود وشعبيته « وعاد شاول يخاف داود .. فصار شاول عدواً لداود كل الأيام » ( ١ صم ١٨ : ٢٩ ) ."],33:["كان يغضب لكل كلمة مديح تُقال عن داود ( ١ صم ١٨ : ٨ ) « فلما رأى شاول أنه مفلح جداً فزع منه » ( ١ صم ١٨ : ١٥ ) . وهكذا حاول قتله أكثر من مرة ، وطارده من برية إلى برية . بل حمى غضبه على ابنه يوناثان وشتمه لما دافع عن داود ( ١ صم ٢٠ : ٣٠ ) .",{h:"نتائج الغضب السيئة"},{h:"١ ـ تعرض يوحنا كاسيان لنتائج الغضب السيئة فقال :"},"[ يجب أن يستأصل بالكلية من أعماق النفس سم الغضب المميت ] . وقال إنه طالما يتبقى فى قلوبنا ، يعمى بظلمته المؤذية عن النفس ، ونتائج ذلك :","( أ ) لا يمكننا أن ننال الإفراز ولا الحكمة ولا النظر الداخلى ، لأن « الغضب يستقر فى حضن الجهال » ( جا ٧ : ٩ ) .","( ب ) لا نقدر أن نحصل على القوة الضابطة للبر ، لأن « غضب الإنسان لا يصنع برّ الله » ( يع ١ : ٢٠ ) .","( جـ ) يفقد الإنسان الكرامة وتقدير الناس ، حتى فى العاليات ... لأن « الرجل الغضوب يُحتقر » .",{h:"٢ ـ ومن نتائج الغضب خطايا كثيرة تعرضنا لها :"},"ولذلك قال الكتاب إن الرجل الغضوب كثير المعاصى ( أم ٢٩ : ٢٢ ) . انظر الفصل الخاص بأن الغضب ( خطية مركبة ) .",{h:"٣ ـ والغضب من الناحية الطبية مضر بالصحة :"},"وعلى رأى أحد العلماء حينما قال : إن جسم الإنسان أثناء الغضب يفرز سموماً . وفى التعبير العادى نقول عن الغضوب إن دمه قد تعكر .","والغضب قد يجلب أمراضاً كثيرة منها إرتفاع ضغط الدم ، وأمراض الأعصاب ، والسكر ، وبعض أمراض القلب والمعدة . وقد تجد الإنسان أثناء غضبه يرتعش أو يهتز ، وكذلك صوته وألفاظه ."],34:["ولذلك حسناً قال السيد المسيح : « طوبى للودعاء ، لأنهم يرثون الأرض » ( مت ٥ : ٥ ) . فبالإضافة إلى أنهم يرثون « أرض الأحياء » ( مز ٢٧ : ١٣ ) ، فهم أيضاً لا يتعرضون لقصر العمر بسبب الغضب ، لأن الودعاء لا يغضبون .",{h:"٤ ـ ومن نتائج الغضب السيئة : العثرة وضياع السمعة :"},"فالغضب باعتباره خطية مكشوفة ومفضوحة ، يكون باستمرار معثراً للآخرين ، ولا يعطى صورة طيبة بالنسبة إلى مَنْ يغضب ويثور ويترفز ، ويبدو أمام الناس فاقد الأعصاب ، غير مسيطر على نفسه ، لا يستطيع أن يضبطها ...","وهكذا كما يقع فى إدانة غيره أثناء غضبه ، هو أيضاً يجعل الغير يدينونه .",{h:"ويبدو الغضوب وقد تشابه فى أخلاقه مع الشخص الذى هو يغضب عليه :"},"فالشخص الآخر قد أخطأ وتسبب فى هذا الغضب . والشخص الغضوب قد قابل الخطأ بخطأ هو الغضب وفقدان الأعصاب . وبدا أن الاثنين فى مستوى متشابه من الضعف . كل منهما لا يسلك بأسلوب روحى .",{h:"ويبدو الغضوب ضعيفاً ، لأنه عاجز عن الاحتمال ."},"والذى يحتمل ، ويسيطر على أعصابه ، فلا تثيره أخطاء غيره ، لا شك أنه شخص قوى . ولهذا يقول الرسول : « يجب علينا نحن الأقوياء أن نحتمل ضعفات الضعفاء ، ولا نرضى أنفسنا » ( رو ١٥ : ١ ) . إذن الذين يحتملون هم الأقوياء . أما الضعفاء فهم الذين يخطئون ، وهم نحن فى حالة عدم إحتمالنا لهم ...",{h:"٥ ـ ومن نتائج الغضب إساءة العلاقات مع الآخرين :"},"هناك خطايا قاصرة على الشخص نفسه مثل أفكاره وشهواته الداخلية . أما خطية الغضب ( النرفزة ) ، فإنها تمتد إلى علاقته بالآخرين . وربما فى ساعة غضب يفقد الإنسان علاقات كانت طيبة مع الآخرين واستمرت طيبة لمدة سنوات . وقد يهدأ هذا الإنسان بعد غضبه . ولكن الذين أساء إليهم بغضبه عليهم لا يهدأون . و يستمر معهم التأثر والضيق . وربما يحاول أن يصالحهم فلا يستطيع . وهذه من نتائج الغضب السيئة .",{h:"بالغضب نخسر الأصدقاء ، ونزيد ونثبّت عداوة الأعداء :"},"وهكذا لا نستبقى صديقاً ، ولا نصالح عدواً . وتكون خسارة لنا على طول"],35:["الخط ولو تفكّر الإنسان فى هذه النتائج قبل غضبه ، ما كان يغضب . أو على الأقل لا يكون مسرعاً فى الغضب ، حسب وصية الكتاب ( يع ١ : ١٩ ) .",{h:"٦ ـ ومن نتائج الغضب السيئة عرقلته للصلاة وللتناول :"},"قيل فى بستان الرهبان : أخ أغضبه أخوه . فلما دخل قلايته ، إستحى أن يصلى إلى الله بسبب الوجع المتقد فى قلبه . ولكنه لما تطارح قدام الله قائلاً : [ يا سيدى الرب ، قد غفرت لأخى من كل قلبى ] ، للوقت سمع صوتاً يقول له : [ قد أخذت شبهى . إذن صلِّ لى بدالة ] .",{h:"وقال فى ذلك القديس مار أوغريس :"},"كلما أردت أن تنتقم من الذين ظلموك ، فإن هذا يصير لك معثرة فى وقت الصلاة ، إذا أردت أن تصلى كما ينبغى ... فكلما تذكرت الشر الذى لأخيك ، تصلى وأنت مظلم العقل .","لذلك إلق من نفسك أفكار الغضب ، ولا تدع الرجز يسكن فيك . وحينئذ لا تقلق فى وقت الصلاة .","كل هذا قاله الآباء عن مجرد الغضب الداخلى . أما من جهة الغضب الذى تثور به على أخيك وتؤلمه به ، فإن الرب يقول فى العظة على الجبل :",{h:"« إن قدمت قربانك قدام المذبح ، وهناك تذكرت أن لأخيك شيئاً عليك ، فاترك هناك قربانك قدام المذبح ، واذهب أولاً اصطلح مع أخيك » ( مت ٥ : ٢٣ ، ٢٤ ) ."},"طبيعى إن جرح شعور الآخرين وإيلامهم بالحدة والنرفزة والألفاظ القاسية والإساءة إليهم ... كل ذلك يمنع التقدم إلى التناول من الأسرار المقدسة . ولذلك فنحن نبدأ القداس الإلهى بصلاة الصلح . ويقول الأب الكاهن : « إجعلنا مستحقين كلنا يا سيدنا أن نقبل بعضنا بعضاً بقبلة مقدسة ، لكى ننال بغير إنطراح فى دينونة من موهبتك غير المائتة السمائية » . إذن الذى يتناول بغير مصالحة مَنْ قد أساء إليهم ، يقع فى دينونة ...","على أن كثيراً من الآباء يرون أن كلمة ( قربان ) فى قول الرب ( مت ٥ : ٢٣ ) لا تعنى التناول فقط ، وإنما الصلاة عموماً ."],36:[{h:"رأى يوحنا كاسيان :"},"ففى تعليقه على قول الكتاب : « لا تغرب الشمس على غيظكم » ( أف ٤ : ٢٦ ) ، مثبتاً أن المقصود هو « شمس البر » ( ملا ٤ : ٢ ) ، قال :","كيف يمكننا أن نظن أن الرب يسمح أن يبقى غيظنا ولو إلى لحظة ؟! حيث أنه لم يسمح لنا أن نقدم ذبيحة صلواتنا الروحية ، إن كنا نعلم أنه توجد عند شخص آخر مرارة ضدنا ، قائلاً : « ... إذهب أولاً إصطلح مع أخيك ، وبعدئذ تعالَ وقدم قربانك » ( مت ٥ : ٢٤ ) . كيف إذن يمكن أن نستبقى عدم رضى على أخينا ، لا أقول لمدة أيام عديدة ، وإنما حتى إلى غروب الشمس ، إن كان غير مسموح لنا أن نقدم صلواتنا إلى الله ، بينما هذا الأخ له شىء ضدنا ؟!","ومع ذلك فنحن قد أمرنا من الرسول أن « نصلى بدون إنقطاع » ( ١ تس ٥ : ١٧ ) و « فى كل مكان نرفع أيادى طاهرة بدون سخط ولا نزاع » ( تى ٢ : ٨ ) .",{h:"يبقى إذن : إما أننا لا نصلى على الإطلاق ، مستبقين هذا السم فى قلوبنا ، ونصير مذنبين من جهة هذه الوصية الرسولية أو الإنجيلية التى أمرنا بها أن نصلى فى كل مكان وبدون إنقطاع . وإما ـ إن خدعنا أنفسنا ـ نجرؤ أن نسكب صلواتنا ضد الأمر الإلهى ."},"وعندئذ ينبغى أن نعرف إننا لا نقدم وقتذاك للرب أية صلاة ، وإنما مزاجاً عنيداً مع روح متمردة ! ... لأن صلواتنا تفقد فاعليتها إن كان لأحد من الإخوة شىء ضدنا ...",{h:"والله لا يقبل صلاة من إنسان حاقد على غيره ."},"وقد يحاول الغضوب أن يصلى ، ولكن فكره يتشتت أثناء صلاته ، و يسرح فى الأسباب التى من أجلها قد غضب ، أو فى الطرق التى يريد أن يعبر بها عن غضبه ، أو ينتقم بها ممّنْ أغضبه . و يتصور أشياء كثيرة . و يكون كمَنْ يكلم نفسه أو يكلم غيره . و يعرف أن صلاته لم تكن صلاة . وإنما البركان الذى فى داخله مازال ينفث حمماً ...!"],37:[{h:"الفصل الثالث : أنواع ودرجات الغضب"},"١ ـ مقدس وباطل .","٢ ـ الغضب الخفى ( بالقلب والفكر ) .","٣ ـ السخط والحقد .","٤ ـ الغضب باللسان .","٥ ـ الإنتقام .","٦ ـ الغضب غير المباشر .","٧ ـ الغضب الثائر العدوانى .","٨ ـ درجات من الغضب .","٩ ـ تطور الغضب .","١٠ ـ أنواع من رد الشر بالشر ."],38:[{h:"مقدس وباطل"},{h:"١ ـ ذكرنا من قبل أن هناك نوعين من الغضب : الغضب المقدس ، والغضب الباطل . وإن الغضب المقدس يكون لأسباب مقدسة ، وبأسلوب مقدس ، ويبعد عن النرفزة والصياح والضجيج ، كما لا يكون لأسباب شخصية ، ولا لأسباب مادية . وليس بسبب الكرامة العالمية ."},"الغضب المقدس الذى من أجل الله ، ومن أجل القداسة والحق فلا يفقد فيه الإنسان أعصابه . إنما يتصف فيه بالحزم . وهناك فرق بين الحزم والنرفزة ...","ولكن حديثنا فى هذا الفصل سيتركز على الغضب الخاطىء .",{h:"الغضب الخفى ( بالقلب والفكر )"},{h:"٢ ـ وفى الغضب الباطل يوجد أيضاً نوعان : غضب داخلى مستتر ، وغضب واضح ظاهر . والغضب الداخلى هو غضب الفكر والقلب ."},"أنت قد لا تسىء إلى أخيك باللسان ، وقد لا تجرحه بأية كلمة . وربما تبدو صامتاً لا ترد الإهانة بإهانة . ولكن مع ذلك كله قد يكون الغضب فى فكرك وفى مشاعر قلبك . قد تكون هناك ثورة فى داخلك ، ولكنها مكبونة . وهنا لا تستطيع أن تقول إنك لم تغضب . ففى الواقع إنك غضبت ، ولكنك كتمت غضبك .",{h:"ربما كبتك لغضبك يكون لأسباب روحية أو غير روحية ."},"السبب الروحى هو ضبط النفس ، ومنعها من الخطأ ، وتهدئة النفس ريثما تجد حلاً روحياً لتصريف الغضب من داخلك . وفى هذه الحالة نقول إنك لم تحتمل ، وفى نفس الوقت لم تثر . إنفعلت فى داخلك ، ولكنك وقفت عند هذا الحد ، حتى لا تخطىء بلسانك ، ولا تخطىء بتصرفك ، ولا تنتقم لنفسك . وهذا طبعاً أفضل من النرفزة والحدّة .",{h:"وربما يكون كبت الغضب بسبب الخوف ..."}],39:["الخوف من الشخص المخطىء إليك ، لأنه أقوى منك ، أو فى موقف رئاسى ، وتخشى نتائج الغضب فربما تؤدى إلى حالة أسوأ . وقد يكون الخوف هو من أن يأخذ الناس عنك فكرة سيئة . فتكون قد عالجت الغضب بالمجد الباطل !",{h:"وقد يكون سبب السكوت هو تجهيز للإنتقام فيما بعد :"},"فأنت صامت ، لا لأنك غفرت ، ولا لأنك إحتملت . وإنما لأن الفرصة الآن غير مواتية للرد . والغضب الظاهر قد يكشف نواياك ، ومن الحكمة أن تظل هذه النوايا فى الكتمان ، إلى أن يحين الوقت الذى تنتقم فيه لنفسك ، وبقوة ، وبدون أن تقع فى مسئولية ...! وكل هذه خطايا مكتومة مع الغضب المكبوت .",{h:"وفى كل ذلك يكون الفكر منشغلاً بالخطية ، والقلب كذلك :"},"يكون غضب الإنسان مالكاً لكل مشاعر القلب ، ومالكاً للفكر . و يظل ذهن الإنسان يشبع مقاصده بأفكار الرد والإنتقام ، ومحاولة أخذ حقه بأنواع وطرق شتى ، ومجازاة من أغضبه بأساليب متنوعة ، وبصور يريدها أن تحدث ، و يتخيل حدوثها كما لو كانت واقعاً . وفى هذا كله يخطىء بقلبه .",{h:"وقد تحدث الآباء عن هذا النوع من الغضب فقالوا :"},{h:"قال مار أوغريس :"},"لا تسلم ذاتك إلى فكر الغضب ، وتقاتل قلبك على الذى أحزنك .","إذا نظر الشياطين أننا لم نقدر على إحتمال السبّ ، حينئذ يأتون خفية ، ويحاربون العقل . حتى كأن الذين صنعنا معهم سلاماً ( غفرنا لهم ) هم عندنا . ونثور عليهم وهم ليسوا عندنا .",{h:"وقال مار إشعياء :"},"إن أساء إليك أخ ، وجاء آخر وعاب فيه عندك ، فاحفظ قلبك لئلا يتجدد فيه ذكر الشر الذى أساء به إليك ذلك الإنسان .","إن كنت فى قلايتك ، وتذكرت أن إنساناً أساء إليك وأحزنك ، فقم فى الحال ، وصلّ من أجله من كل قلبك أن يغفر الله له ولك . و بذلك تنطفىء عنك محبة مكافأة الشر بالشر .","إذا ذهبت لتتناول جسد الرب ودمه الأقدسين ، فإياك أن يكون فى قلبك حقد"],40:["أو غيظ على إنسان . فإن علمت أن فى قلب إنسان شيئاً ضدك ، فاذهب واطلب مغفرته ، لئلا تأخذ دينونة لنفسك وهلاكاً .","إن الإنسان الذى فى قلبه مكافأة شر لأخيه ، جميع عمله باطل .",{h:"السخط والحقد"},{h:"قال يوحنا كاسيان :"},"ماذا عساى أن أقول عن أولئك الذين حتى غروب الشمس لا يضعون حداً لحقدهم ، وإنما يطيلونه إلى أيام عديدة . ويغذون شعور الضغينة نحو الذين أثيروا ضدهم ، ويقولون بالكلام إنهم ليسوا غضبانين ! ولكنهم فى الواقع والعمل متعكرون للغاية . إذ لا يكلمونهم بمسرة ، ولا يخاطبونهم باللطف المألوف .","ويظنون أنهم لا يخطئون فى هذا ، لأنهم لا يطلبون إنتقاماً لأنفسهم مما أصابهم ! ولكن حيث أنهم لا يجرأون ـ أو لا يستطيعون على أية الحالات أن يظهروا غضبهم علناً ـ فإنهم لأجل خسارتهم يسوقون إلى داخلهم سم الغضب ، و يلاطفونه سراً فى قلوبهم ، ،فى صمت يتغذون عليه فى أنفسهم ..!","ولكن يبدو أن هذا ليس هو النهاية عند كل أحد .","فالبعض لا يستطيعون أن يرضوا سخطهم وحقدهم تماماً ، إلاّ إذا نفذوا دافع الغضب إلى أقصى ما يستطيعون . ونعرف أن هذا هو حال أولئك الذين يكبحون مشاعرهم ـ ليست بغرض تهدئتها ، وإنما لأن فرصة الإنتقام تعوزهم ! ـ لأنهم لا يقدرون أن يفعلوا شيئاً ضد الذين غضبوا عليهم أكثر من أن يتكلموا معهم بدون اللطف المعتاد .","إن السخط الذى يربى فى القلب ، فعلى الرغم من أنه قد لا يؤذى الناس المحيطين ، إلاّ أنه يطرد بهجة نور الروح القدس ( من قلب صاحبه ) مساوياً فى ذلك للسخط الذى يظهر علانية .",{h:"قال مار افرام :"},"مَنْ يخفى فى قلبه حقداً ، يضاهى مَنْ يربى فى حجره حية .","الدخان يطرد النحل . والحقد يطرد المعرفة من القلب ."],41:[{h:"وقال شيخ ( من البستان ) :"},"مَنْ يحقد على أخيه ، قد خزن ذنوبه فى ذاته وختم عليها .",{h:"الغضب باللسان"},"٤ ـ قد لا يقتصر الغضب على مشاعر القلب ، أو أفكار العقل . وإنما قد يحاول الغضوب أن يعبر عن غضبه باللسان ، فيشتم أو يسبّ ، أو يدين ، أو يهدد ، و يتوعد بالإنتقام ... ويقع فى كثير من أخطاء اللسان واشباهها .",{h:"قال القديس أوغسطينوس :"},"إنه يهدد كما لو كان سيحيا على الدوام . لا يفكر فى نفسه أنه يمكن أن يموت فجأة وهو يتكلم . لا يتذكر المكتوب « تخرج أرواحهم ، فيعودون إلى ترابهم . فى ذلك اليوم تهلك كل أفكارهم » ( مز ١٤٦ : ٤ ) . ولكن الذى لا يفكر فى اليوم الأخير ، يتكلم بكبرياء : ... سأفعل كذا . سأريك . ستعرف مع مَنْ يجب أن تتصرف . سوف لا أجعلك تعيش ...!","وأنت ، ربما لا تكون قد تلفظت بأمثال هذه الكلمات ، ولكنك فكرت فيها فى أعماق مخادع الفكر الداخلية ، وعلى الأقل قد إنحصرت بالشهوة الرديئة فى الإنتقام . فيجب على الأقل أن تقمعها داخل فكرك .",{h:"الإنتقام"},"٥ ـ الغضب فى طبيعته حركة إنتقامية ، يريد بها الإنسان أن ينتقم لنفسه ويرد الشر بالشر . غير أنه أحياناً يتمم هذه الرغبة الإنتقامية وأحياناً يقف عند حد . والإنتقام درجات ...",{h:"يقول القديس أوغسطينوس :"},"ما هو الغضب ؟ إنه شهوة الإنتقام . يشتهى الإنسان أن ينتقم لنفسه . بينما الله لم ينتقم بعد . ومازال بطول أناته ينتظر أن يرجع الخطاة ..."],42:["ومن نكون نحن حتى نطلب الإنتقام . تُرى لو طلب الله الإنتقام منا ، أين يكون مصيرنا ؟ إننا فى كل يوم نخطىء إلى الله الذى لم يسىء إلينا فى أى أمر . والله لا يشاء أن ينتقم لنفسه منا . فهل نطلب نحن أن ننتقم لأنفسنا ؟ اغفروا إذن . من كل قلوبكم اغفروا ...",{h:"ويتحدث القديس ذهبى الفم عن اضرار الإنتقام علينا ، فيقول :"},"الإنتقام هو شر عظيم ، لدرجة أنه يسحب حقاً رحمة الله ، ويلغى المغفرة التى منحت من قبل لخطايا غير محصاة . لأن الذى سومح على دين عشرة آلاف وزنة ، وبعد أن نال نعمة عظيمة كهذه لمجرد سؤاله ... حدث أنه لما قسا على رفيقه مطالباً بمائة دينار ، سُلّم للمعذبين . وطولب بأن يدفع العشرة آلاف وزنة ، ولم يسمح له بتقديم أى عذر أو دفاع ، وإنما تحمل أقصى عقوبة . وطولب بأن يسلّم كل الدين الذى كان الله المحب الرحوم قد ساعه فيه من قبل ( مت ١٨ : ٢٣ ـ ٣٥ ) .",{h:"الغضب غير المباشر"},{h:"٦ ـ ولعل من أمثلته الواضحة ما يمكن تسميته بالصمت المثير :"},"فقد يوجد شخص أعصابه قوية جداً ، يقف فى منتهى البرود ، والجو يغلى ، دون أن يغضب ، ويستطيع ببروده وصمته أن يثير الطرف الآخر ، ويجعله يغضب ويخطىء ... ويظن أنه برىء ولم يرتكب خطأً ، بينما هو المتسبب فى خطأ أخيه . وكان يمكنه بكلمة لطيفة أو عبارة هادئة ، أن يهدىء هذا الذى يتكلم معه .",{h:"إنه مسئول عن غضب زميله ، لأنه أعثره وأثاره وأسقطه :"},"فليس المطلوب فقط هو أنك لا تغضب ، وإنما أيضاً لا تتسبب فى غضب غيرك . وقد شرح هذا الأمر القديس الأنبا يوسف فى لقائه مع يوحنا كاسيان .",{h:"قال الأنبا يوسف :"},"نهراً هكذا بإخوتنا الغاضبين ، حتى أننا بنظراتنا الصامتة نستفزهم إلى الغضب أكثر من إثارتهم بتوبيخات عاضبة . وفى نفس الوقت نظن أننا لسنا مذنبين فى شىء أمام الله ، لأننا لم نسمح بأن يخرج من شفاهنا شىء يشوهنا أو يدينا فى حكم الناس ! كما لو أنه فى نظر الله مجرد الكلمات فقط هى التى تدعى خطأ !"],43:["إن ديّانا سيسأل فى إمعان نظر : ليس فقط كيف قامت المعركة ، وإنما بغضب مَنْ قامت ؟ ... ليست المسئولية فقط فى أن يدفع إنسان بيده رجلاً أعمى إلى أسفل . بل قد يساوى به فى الذنب ، مَنْ امتنع عن أن ينقذ ذلك الأعمى ـ وهو على حافة السقوط فى حفرة ـ حين كان ذلك فى قدرته وقت سقوطه .","لذلك ليست فضيلة أن يمسك إنسان لسانه ، بينما يتصنع ملامح معينة بها يزداد غضب مَنْ كان يجب عليه معالجته ، وقد أصبح بهذا مسئولاً عن خسارته وتلفه .","أليس الإنسان لأجل هذا السبب يعتبر أكثر ذنباً ؟! لأنه حاول أن يحصل على فخر لنفسه ... بصمته ... عن طريق سقوط أخيه !","هناك نوع من الغضب عكس هذا تماماً وهو :",{h:"الغضب الثائر العدوانى"},"٧ ـ وهو الغضب الذى يعلو فيه الصوت ، ويحتد . وقد يتحول إلى الضرب أو الاعتداء ، أو على الأقل يصل إلى الإهانة والشتيمة والتجريح .","وقد يكون فى هذا الغضب نوع من الإيذاء ، يضر به الإنسان فى معيشته ، أو فى سمعته ، أو يتهمه بإتهامات توقعه فى أضرار جسيمة ، أو يحرض عليه مَنْ يهينه أو يعتدى عليه ... وقمة هذا الغضب قد تصل إلى القتل ...",{h:"درجات من الغضب"},"٨ ـ قال القديس سيرابيون : توجد ثلاثة أنواع من الغضب :","( أ ) نوع من الغضب يثور فى الداخل .","( ب ) نوع آخر ينفجر فى الكلمات والعمل والتصرف ... وهو الذى تحدث عنه الرسول بقوله : « اطرحوا عنكم كل غضب وسخط » ( كو ٣ : ٨ ) .","( جـ ) النوع الثالث وهو ليس مثل هذين يغلى و يعمل فى ساعة ، ولكنه يستمر أياماً وفترات طويلة ."],44:["وهذه الثلاثة كلها ينبغى أن تدان منا باشمئزاز .",{h:"وقال القديس أوغسطينوس :"},"[ وذلك فى شرحه لعبارتى « باطلاً ، ورقاً » ، و « يا أحمق » ( مت ٥ : ٢٢ ) ] :","إنه يوجد تدرج فى الخطايا المشار إليها :","( أ ) فالأول غضبان ويحفظ الشعور مخفياً فى قلبه .","( ب ) أما إذا نتج عن هذا الشعور تعبير من الغضب ليس له أى معنى محدد ، ولكنه يوضح شعور العقل هذا بواسطة الإنفعال .. فإن هذا بالتأكيد أكثر من حالة قيام الغضب وكبحه بالصمت .","( جـ ) أما إذا كان الأمر ليس مجرد تعبير عن الغضب ، وإنما سُمعت كلمة يستخدمها المجتمع فى نقد واضح ضد الشخص الذى وجهت إليه ، فمن يشك فى أن هذا أكثر ...؟!","فإن كان لا يجوز الغضب على الأخ باطلاً ، ولا قول رقا ، ولا قول يا أحمق ، فبالأحرى لا يجوز إطلاقاً أن يُحتفظ بشىء من التحقير فى العقل .",{h:"لأن هذا التحقير قد يتحول إلى كراهية .."},"وعن هذه قيل فى موضع آخر « لا تغرب الشمس على غيظكم » ( أف ٤ : ٢٦ ) . وقال القديس أوغسطينوس إنه لا يتجو من هذه كلها ، إلاّ الذى لم ينتفخ بروح المجد الباطل .",{h:"ثم تحدث القديس باستفاضة عن الغضب والبغضة :"},"فقال : لأنه ما هو الغضب ؟ هو شهوة الإنتقام . وما هى البغضة ؟ هى غضب مزمن . لأنه إذا تأصل الغضب ، فإنه يدعى بغضة ... وقد تحول بطول الاستمرار ..",{h:"الغضب عبارة عن قذى ، والكراهية خشبة ."},"قد نجد أحياناً خطأً فى شخص غضبان ، إلاّ أننا نستبقى الكراهية فى قلوبنا من نحوه . و يقول السيد المسيح « لماذا تنظر القذى الذى فى عين أخيك . وأما الخشبة التى فى عينك فلا تفطن لها ؟! » ( مت ٧ : ٣ ) . كيف نما القذى وتحول"],45:["إلى خشبة ؟ لأنه لم يُستأصل فى الحال . لأنك لم تبالِ أن تشرق الشمس وتغرب مراراً على غيظك ، فجعلته يتأصل ...","إرتعد إذن على الأقل من الذى قال :",{h:"« مَنْ يبغض أخاه ، فهو قاتل نفس » ( ١ يو ٣ : ١٥ ) ."},"إنك لم تجرد سيفاً ، ولم تجرح ولم تقتل به أحداً . إنما هى مجرد فكرة البغضة فى قلبك ، وبها أعتبرت قاتلاً ومذنباً أمام الله . الرجل الآخر حىّ ، إلاّ أنك قد قتلته ، فى قلبك ...","اصلحوا إذن نفوسكم وقوّموها . وإن كانت فى بيوتكم حيات وعقارب ، ألا تتعبون لتنظيف بيوتكم منها ، لكى تستطيعوا أن تسكنوها باطمئنان ؟!","إنكم تجعلون الغضب يزمن فى قلوبكم . وهناك تنمو أنواع كثيرة من البغضة ، من الخشب ، وتنمو كثير من العقارب ومن الحيات . ألا تنظفوا إذن بيت الله الذى هو قلوبكم ؟ ليتكم تنفذون ما تقولونه فى صلواتكم « كما نغفر نحن أيضاً ... » وهكذا تقولون فى ضمان « اغفر لنا .. » .",{h:"تطور الغضب"},{h:"٩ ـ قال القديس دوروثيئوس :"},"الذى هزم الإنفعال ، فقد هزم الشياطين ... ولكن ماذا نقول عن أنفسنا عندما لا نستسلم فقط للإنفعال والغضب ، وإنما أيضاً نستمر حانقين ؟!","كثيراً ما تقوم المتاعب والمضايقات بين الإخوة . ولكنهم ـ كقاعدة ـ يسرعون إلى تسوية هذه الخلافات و يهدأون . ولكن قد يحدث فى بعض الأحيان أن أخاً ـ بعد أن ينحنى لأخيه ويقيم السلام ـ يستمر يغذى شعوراً فى قلبه ضد أخيه ، ويلصق بأفكار ضده .","هذا حنق أو حقد . ويلزم حرص كبير ، حتى لا يقسو الشخص فيه ويهلك . إن الذى أقام سلاماً فى الحال مع شخص آخر بعد تهييج منه ، هذا قد عالج"],46:["الغضب . ولكنه ( إذا استمر يغذى شعوراً ضده فى قلبه ) يكون مستبقياً الحنق ، لأنه مستمر فى إستيائه من أخيه .",{h:"لأن الحنق شىء ، والغضب شىء آخر ، والإنفعال أو التهييج شىء ثالث ، والاضطراب شىء آخر ."},{h:"ولكى نفهم الأمر بوضوح أكثر ، سنقدم لك مثالاً :"},{h:"مثال الفحمة المشتعلة"},"( أ ) لكى تشعل ناراً ، يأخذ الشخص قطعة صغيرة من الفحم ويشعلها . هذه هى كلمة الأخ الذى أساء إليك . إن إستطعت أن تحتملها ، فقد أطفأت الفحم .","( ب ) ولكن إن فكرت : [ لماذا قال ذلك ؟ وإن كان هذا هو الحال ، فإنى أنا أيضاً سأقول له كذا وكذا . ولو لم يكن يقصد أن يسىء إلىَّ ، ما كان قد قال تلك الكلمة . فبالتأكيد يجب أن أسىء إليه بالمثل ] .",{h:"ها أنت تضع بعض الوقود أو ما شابه ذلك لتبدأ النار . وتكون قد أنتجت دخاناً الذى هو الاضطراب ."},"( جـ ) والاضطراب هو حركة وتقلب فى الأفكار ، تقوم وتهييج القلب .","والتهييج هو قيام إنتقامى ضد الشخص الذى أساء إليك . وهو يثير الجسارة . وقد قال القديس مرقس [ سوء النية إذ تغذيها الأفكار ، تهيج القلب . ولكن الصلاة تقتلها ] .","لو كنت قد إحتملت تلك الكلمة الصغيرة التى قالها أخوك ، كنت قد أطفأت الفحمة الصغيرة قبل أن تنتج اضطراباً . ولاتزال بعد تستطيع إن أردت أن تطفىء حتى الاضطراب فى بدايته بالصمت والصلاة ، وحتى بمجرد إنحناءة من القلب .","( د ) أما إذا إستمررت تدخن ، أى أن تهيج وتثير القلب بالأفكار : [ لماذا فعل ..؟ وأنا أيضاً بالمثل ... ] ، فإن هذا سيشمل القلب ويولد التهاب التهييج . وإن أردت تستطيع أن تطفىء حتى التهييج ، قبل أن يقود إلى الغضب ( النرفزة ) ."],47:["( هـ ) ولكن إن إستمررت تثير وتهيج نفسك ، فإنك تكون مثل إنسان يضيف وقوداً إلى النار . وهكذا تنتج لهيباً الذى هو الغضب .",{h:"والغضب إذا إستمر ، يتحول إلى حقد ، لا يتخلص منه الشخص إلاّ بعد أن يسفك دمه ، أى عرقه وجهده وتعب نفسه !!"},"وهكذا سمعت عن معنى الإضطراب والتهيج والغضب والحقد .","فهل رأيت إذن ، كيف أنه من كلمة واحدة أتى هذا الشر ؟! لأنك إن كنت قد لمت نفسك من الابتداء ، واحتملت بصبر كلمة أخيك ، عوضاً عن أن تنتقم لنفسك منه بكلمتين أو بخمسة وهكذا ترد الشر بالشر ، نعم لو كنت قد إحتملت ، لكنت قد تخلصت من كل هذه الشرور . لذلك أقول لك :",{h:"تخلّص من الآلام دائماً ، وهى لا تزال صغيرة .."},"وذلك قبل أن تتأصل وتقوى فيك ، وتبدأ فى أن تضعفك وتجعلك تقاسى الكثير منها .",{h:"شىء هو أن تحتثّ ورقة عشب صغيرة . وشىء آخر هو أن تقتلعها من جذورها بعد أن صارت شجرة ."},{h:"درجات من مكافأة الشر بالشر"},"١٠ ـ تعرض القديس دوروثيئوس هذا الموضوع أيضاً فقال :","١ ـ يستطيع واحد أن يرد الشر بالشر ، وإنما بالكلام والتعبير . وقد يظن أنه لا يرد الشر بالشر بالفعل ، ولكنه فى الحقيقة قد برده بكلمة أو عبارة أو إشارة أو نظرة ، لأن كل هذا يقدر أن يسىء إلى أخيه ، وهذا أيضاً هو رد الشر بالشر .","٢ ـ وآخر لا يحاول أن ينتقم بالفعل ، ولا بكلمة أو عبارة أو إيماءة . ولكنه فى قلبه يسكن الحقد ضد أخيه ، وفيه مرارة ضده .","٣ ـ وآخر ليست فيه مرارة ضد أخيه . ولكنه إن سمع شخصاً يسبه أو ينتقده أو يقلل من شأنه ، فإنه يبتهج . وهكذا يرد الشر بالشر فى قلبه ."],48:["٤ ـ وآخر لا يغذى حقداً فى قلبه ، ولا يبتهج بسماع تحقير مَنْ أساء إليه ، بل قد يحزن لشتمه . ولكنه لا يفرح بنجاحه . مثال ذلك إنه قد يتضايق إذا مدح أو كرم . هذا أيضاً لون من الحقد .","٥ ـ يحدث أحياناً أنه إن أساء أحد إلى آخر ، فإنهما ينحنيان الواحد للآخر و يصطلحان . وهكذا يعيش الواحد منهما فى سلام مع مَنْ أساء إليه ، ولا تكون فى قلبه أفكار ضده . ولكن قد يحدث بعد مضى بعض الوقت أن يقول هذا المسىء شيئاً ضاراً عنه ، فيبدأ أن يتذكر الإساءة السابقة ، و يضطرب ، ليس فقط من الثانية ، بل بسبب الأولى أيضاً .","مثل هذا الإنسان يشبه شخصاً قد غطى جرحه بقطعة من الشاش . الجرح قد إلتأم ، ولكن موضعه لايزال حساساً . ولذلك إن إصطدم بشىء صلب ، فإنه فى الحال يبدأ أن يدمى . وهذا يعنى أن الجرح قد غطى ، ولكنه لم يشفَ بالتمام . مازال هناك أثر للحقد ، بسببه ينفتح الجرح بسهولة إذا إرتطم بأقل إرتطامة .."],49:[{h:"الفصل الرابع : الإحتمال"},"أقوال الآباء فى الاحتمال .","أقوال متفرقة لبعض الآباء .","أمثلة لقديسين إحتملوا .","الاحتمال الحقيقى .","الاحتمال يظهر بالتجربة .","شكلية تحويل الخد الآخر ."],50:[{h:"أقوال الآباء فى الإحتمال"},"القديس الأنبا أنطونيوس يرى الاحتمال فى عدم الرد ، وفى حفظ القلب وضبط النفس ، والتشبه بالسيد المسيح ، فيقول :","إرفض الرد على مَنْ يبغضك . ولا تفكر فى قلبك بالشر ، ولا تقاتل أحداً ، وإن إستفزك باطلاً فلا تغضب .","وقال : تشبّه بالسيد المسيح ، فإنه لما شُتم لم يشتم عوضاً ( ١ بط ٢ : ٢٣ ) .","القديس الأنبا أنطونيوس","وقال أيضاً : لا تحزن ولا تتألم ولو قليلاً على شىء لهذه الدنيا . ولا تقلق إذا شتمك جميع الناس ... بل إحزن بالحرى إذا عملت ما يستوجب الشتيمة .","القديس الأنبا أنطونيوس","والقديس الأنبا باخوميوس يدعو أيضاً إلى التشبه بالمسيح ، وإلى عدم الحزن بسبب الإفتراء عليك . فيقول :","إن إفترى أحد عليك ، فلا تفتر أنت عليه . بل إفرح واشكر الله . وقال : [ لا تحزن إذا إفترى الناس عليك ، بل إحزن بالحرى إذا أخطأت إلى الله ] . وقال كذلك : [ إذا رذلك الناس وافتروا عليك فلا تحزن ، لأن ربك دُعى ضالاً ، وبعلزبول وبه شيطان ، ولم يتذمر ( يو ٧ : ٢٠ ) . فاقتن لك وداعة قلب ، وأذكر أن ربك والهك سيق كخروف للذبح ، ولم يفتح فاه .. ( إش ٥٣ : ٧ ) .","القديس الأنبا باخوميوس","والقديس برصنوفيوس يرى أن عدم الإحتمال يدل على بقاء الإنسان العتيق ، كما أننا به نحزن الإخوة ونعثرهم ، ونفقد حلاوة الحياة الروحية والوداعة والهدوء ... فقال :"],51:["مَنْ لا يحتمل التبكيت والإهانة ، فإن الإنسان العتيق لايزال حياً فيه بعد ..","وقال : إذا إتفق وشتمك إنسان ، وأتاك الفكر أن ترد عليه ، قل لفكرك : إن أنا رددت عليه أحزنته وأعثرته ، فلا أصبر أنا قليلاً ، والأمر يجوز بسلام ..","وقال أيضاً : كن وديعاً بقلبك . واذكر الخروف الوديع وكم صبر ، على الرغم من أنه لم تكن له خطية ، لكنه إحتمل الشتم والضرب وسائر الأوجاع حتى الموت ... لذلك إتعب وجاهد لكى يبعد عنك الغضب والحرد بمعونة الله الحق ، بمعونة المسيح الذى أحبك .","وقال كذلك : إذا لم يكن الإنسان جلداً صبوراً ، فلن يستطيع أن يعيش مع الناس فى هدوء وسلام . قال الرسول : « صرت مع الكل مثل الكل ، لأربح الكل » ( ١ كو ٩ : ٢٢ ) . هذه هى طريق المسيح ، لأنه بكل وداعة وسكون جاء ليخلص الناس ...","وقال : كل مَنْ لا يحتمل الشتيمة ، فلن يبصر التسبحة ... وكل مَنْ لا يترك الغضب ، فلن يتذوق حلاوة الحياة . فاحرص بكل قوتك أن تكون غريباً عن الغضب . وليكن قدوة ومثالاً لمنفعة الكل ، ولا تدنْ أحداً ، ولا تحكم على أحد .","القديس برصنوفيوس","وقال القديس برصنوفيوس أيضاً : إن كنت تريد السلوك فى طريق الله ، فليكن عندك الذين يضربونك مثل الذين يكرمونك ، ومهينوك مثل مادحيك ، والمفترون عليك مثل مباركيك ، ومعزنوك مثل مفرحيك . وهكذا كان أبا مقاريوس يقول : [ إن كنت تعتبر الإهانة كالشرف ، واللوم كالمديح ، والفقر كالغنى ، فلن تموت ] ...","القديس الأنبا برصنوفيوس","وبنفس الأسلوب تقريباً تحدث الأنبا بفنوتيوس .","حدث أن مضى إليه ثلاثة إخوة وسألوه كلمة ، فقال لهم : إمضوا وليكن عندكم الحزن أفضل من الفرح ، والتعب أفضل من النياح ، والإهانة أفضل من الكرامة . وليكن عطاؤكم أكثر من أخذكم .","القديس بفنوتيوس"],52:["قال القديس يوحنا الأسيوطى : مَنْ إقتنى الصبر يرتاح فى ضيقاته . والذى ليس له طول روح يتضايق ..","القديس يوحنا الأسيوطى","مار أوغريس يرى أن الإحتمال يأتى بالسكوت ، مع تنقية القلب من إرضاء النفس ، ومن محبة مجد الناس . فيقول :","الذى يحتمل الإهانة بشجاعة ، فإنه يرتفع على الحكم . لأن داود لم يجاوب الذى شتمه ، بل صبر على فرية ذاك ( ٢ صم ١٦ : ١٠ ) . كذلك أنت لا تشتم شاتمك ...","إحتمل الشتيمة ، فإن الإحتمال هو الذى ينميك ويزيدك فى الفضيلة . إغلق باب شفتيك ، الذى هو باب الغضب . والذين يغضبونك لا تجاوبهم بالجملة ، لكى بسكوتك تهدىء شفتى الذى شتمك . إذا ما أجمت فمك ، غلبت الشاتمين الغاضبين عليك . وإذا ما سكتّ ، فإنك لا تضر من الشتيمة ، و يندم أولئك بسبب سكوتك .","إذا ما إحتملت الشاتم بطول روح ، فانزع من قلبك مجد الناس ، لكى تطرح عنك الفكر الذى يجعلك تتظاهر بالفضيلة . وتحفّظ من أن تهتم بمرضاة نفسك ـ ولا سيما فى خلوتك ـ لئلا يرفعك الفكر بالأكثر ، وتستهين بالذى قسّى قلبه عليك .","إننى أعرف واحداً من الإخوة إحتمل شتمة ظلم من إنسان خائف من الله . فلما مضى إلى قلايته فرح وحزن . ففرحه كان لأنه شُتم ظلماً ولم يقلق . وحزنه كان على الأخ الخائف الله الذى أضلته الشياطين . والشيطان الذى أضل ذلك الأخ فرح هو أيضاً وحزن . فرح لأجل خسارة الأخ الذى أضله . وحزن لأنه لم يقدر أن يقلق الأخ المشتوم .","القديس مار أوغريس","ويرى مار إسحق أن الإحتمال دليل على الرحمة ، وأنه يطهر القلب ، ويعطى الإنسان دالة عند الله ، كما تفرح به ملائكته . وينال عزاء ههنا على"],53:["الأرض ، على الرغم من التعب الذى يحتمله . كما أنه يتوج فى الملكوت بتاج لا يفنى . وفى ذلك كله يقول :","حقيقة الرحمة تتبين بالصبر على الظلم .","الصبر الاختيارى على الظلم يطهر القلب .","اصبر على التحقير ، مع الإتضاع بفكر وقصد الفضيلة ، لتفوز بدالة القلب عند الله .","مَنْ يصبر على المسبات الواردة إليه باتضاع ، فقد بلغ الكمال . وإن الملائكة يفتنون به عجباً . لأنه لا توجد فضيلة أشرف من هذه ولا أكبر ، وهى عسرة التثقيف .","مَنْ قدر على إحتمال الظلم بفرح ... فإن هذا قد قبل العزاء من الله تعالى محسوساً ، بتوسط إيمانه دائماً به .","كل كلمة قاسية صعبة يحتملها الإنسان بافراز ، من غير سبب ذنب ، أما فى ذلك الوقت فإنه يقبل إكليل شوك من أجل المسيح . وطوباه لأنه يتوج ـ فى وقت لا يشعر به ـ بتاج لا يلم به فساد .","مار إسحق",{h:"إن القديس الأنبا يوسف يرى أن الشخص الذى يحتمل هو الأقوى ، فيقول :"},"الرجل الأقوى هو الذى يمكنه أن يخضع لإرادة غيره .","والذى يُخضع إرادته الخاصة لإرادة أخيه ، يكون أقوى من الذى يكون متمسكاً بإرادته . لأن الأول باحتماله وصبره على قريبه ، تتكون له شخصية قوية وشديدة . بينما الآخر تكون شخصيته ضعيفة مريضة تريد أن تُرفَّه وتتدلل .","ولا يظن المحتمل أنه قد فقد شيئاً من كماله ، على الرغم من أنه تنازل عن شىء من حزمه . ولكنه من الناحية الأخرى قد ربح كثيراً من فضيلة الإحتمال وطول الأناة ، لأنه هكذا قال الرسول : « يجب علينا نحن الأقوياء أن نحتمل ضعفات الضعفاء » ( رو ١٥ : ١ ) وقال أيضاً : « إحملوا بعضكم أثقال بعض ."],54:["وهكذا تمموا ناموس المسيح » ( غل ٦ : ٢ ) . لأن الضعيف لا يمكن أن يسند ضعيفاً .","ونلاحظ أن طبيعة الضعفاء هى هكذا دائماً : إنهم سريعون فى تصرفهم ، ومستعدون لتوبيخ الآخرين وبذر بذور العراك ، بينما لا يقدرون على إحتمال أقل إساءة .","القديس الأنبا يوسف",{h:"والقديس مار افرام السريانى يرى أن الضعيف محتاج إلى مَنْ يحتمله ، وإن إحتمال الأمور الصغيرة تدريب لإحتمال الأمور الكبيرة وحمل الصليب ، فيقول :"},"إن كنت ما تحتمل محنة صغيرة ، فكيف تحتمل الكبيرة ؟! وإن كنت ما تحتمل إهانة ، فكيف تحمل صليبك ؟! وإن كنت لا تحتمل صليبك ، فكيف ترث المجد فى السموات مع القائلين : « من أجلك نمات كل النهار ، حُسبنا كغنم للذبح » ( رو ٨ : ٣٦ ) . أشاء أن أسكت أيها الحبيب من أجل خزى وجهى . ولكن وجع قلبى يضطرنى أن أتكلم :",{h:"يا حبيبى إحمل الضعيف ، فإن القوى ما يحتاج إليك ."},{h:"فقد كتب إن الأقوياء لا حاجة لهم إلى طبيب ، بل الذين حالتهم سيئة . فأنتم أيها الأقوياء ، إحملوا ضعف الذين لا قوة لهم ."},"القديس مار افرام","وقال مار افرام أيضاً : مَنْ يشأ أن يعيش فى كل موضع عيشة سلامية ، فلا يطلب نياحه ( راحته ) ، بل نياح رفيقه بالرب . وهكذا يجد النياح ( الراحة ) .","القديس مار افرام",{h:"والقديس يرى أن الإحتمال قوى ، وأن الطريق إلى مصادقة الله ، هو عدم إحزان أحد من البشر ، فيقول :"},"[ مَنْ إحتمل عدوه عند شتمه إياه فهو قوى وحكيم . أما مَنْ لا يحتمل الشتيمة ، فلا يحتمل الكرامة كذلك . لأن الشتيمة أقل ضرراً من الكرامة ] ."],55:["وقال أيضاً : إن شئت أن تصادق الله ، فلا تحزن أحداً من الناس ، حتى لو أكثر الإساءة إليك ، بل أترك الأمر لله . أما إذا صادقت الله فسوف يقوم الكل عليك ، ويجعلون عقبهم على رأسك . وأخيراً إكليلاً من ياقوت يضمون عليك ، وتاجاً ملوكياً على رأسك .","القديس الأنبا تيموثاوس",{h:"والقديس الأنبا إشعياء ، يرى أن الإنسان يحتمل إهانة الغير ، ويطلب منه المغفرة ، ولا يلومه فى قلبه . لذلك يقول :"},"إذا وجه إليك إنسان كلمة قاسية ، فلا تشمئز أو يستكبر قلبك . ولكن بادر واصنع مطانية . ولا تلمه فى قلبك ، وإلاّ فالغضب يثور عليك ...","إن إفترى أحد عليك بشىء لم تصنعه ، فلا تجزع ولا تغضب ، بل إتضع واصنع مطانية . وسواء كنت قد فعلت أو لم تفعل ، ففى كلا الحالين قل : إغفر لى .","وقال أيضاً : فلنتحمل تعيير إخوتنا إذا هم رذلونا ، لكى نتخلص من العظمة .","القديس الأنبا إشعياء",{h:"والأنبا نيلس السينائى يرى أنه يمكن تسوية كل المسائل بدون غضب ، وينبغى أن نسامح الآخرين ليسامحنا الله ، فيقول :"},"لا يوجد غضب على الإطلاق ضد أخيك يمكن تبريره . فإن تأملت تجد أن المسألة يمكن أن تسوى تماماً بدون غضب . لذلك إبذل كل جهدك لكى لا يتحرك فيك الغضب .","وقال أيضاً : دع المدين الذى كانت عليه عشرة آلاف وزنة يعلمك أنه إن لم تسامح مدينك ، فسوف لا يسامحك الله . لأنه قيل « فغضب عليه وسلمه للمعذبين » ( مت ١٨ : ٣٤ ) .","الأنبا نيلس السينائى","وقال القديس برصنوفيوس : مادام قلبك يتحرك بالغضب وبالحقد وبسائر الأوجاع العتيقة ، فلن تدخل فيه الحكمة ..."],56:["وقال : إن الرسول يقول « إننا بأحزان كثيرة ينبغى أن ندخل إلى ملكوت السموات » ( أع ١٤ : ٢٢ ) . فالذى يطلب النياح فى كل شىء ، فليسمع « إنك أخذت خيراتك فى حياتك » ( لو ١٦ : ٢٥ ) .","القديس برصنوفيوس",{h:"أقوال متفرقة لبعض الآباء"},"قال القديس أوغسطينوس : مَنْ يرغب أن ينال معونة إلهية من أجل ضعفه ، ينبغى أن يحتمل ضعف الآخرين ، و يعينهم على قدر إمكانه .","قال شيخ : حامل الأموات يأخذ الأجرة من الناس . وحامل الأحياء ( أى المحتمل ) يأخذ الأجرة من الله .","قال القديس مرقس الناسك : علامة المحبة غير المتصنعة هى مغفرة الإساءات .","قال القديس غريغوريوس : إن كنت غير مذنب إلى الله ، فلا تغفر للمذنبين إليك . وإن كنت تعلم أنك مذنب فسلّف الرحمة وقدمها قدامك . فإن الله يضاعف الرحمة للمرحومين .","سأل أخ شيخاً : [ إنى أريد أن أستشهد من أجل الله ] فأجابه [ مَنْ إحتمل رفيقه فى وقت الشدة ، فذاك قد أصبح داخل أتون الثلاثة فتية ] .","قال أنبا يوحنا القصير : كن ساكناً بين إخوتك مثل ميت عادم كل غضب ، لأن من الغضب تأتى الخطية .","قال شيخ : لو إحتمل الإنسان أخاه قليلاً وقت حرده وغضبه ، ثم عاد ذاك بعد قليل إلى نفسه ، وعرف كيف إحتمله أخوه ، فإنه يضع نفسه من أجله .","قال أنبا أور : إن وقع بينك وبين أخيك حزن ، وجحد ما قاله فيك ، فلا تلاججه . وإلاّ فمصيره أن يتقح و يقول [ نعم ، أنا قلت ] ...","قال شيخ : إستعد كل حين لأن تقبل الأتعاب والشدائد مع الضيقات الآتية"],57:["عليك . ولا تصغر نفسك ، بل إقتنِ لك صبراً ، وثبّت أفكارك قائلاً : [ إن هذه إنما أتت علىَّ بسبب خطاياى ] . فإن صنعت هكذا ، فإن معونة الله ونعمته تدركك سريعاً .","قال أنبا زينون : ليس شىء يصيرنا مثل الله سوى عدم الحقد ، وأن نكون بلا شر قبالة الذين يسيئون إلينا .","وقال القديس يوحنا ذهبى الفم : إن أردت ألاّ يتأتى لك حزن ، فلا تُحزن إنساناً ما .",{h:"من أقوال أنبا إشعياء تلميذ مار إسحق ."},"ثلاث فضائل قال إنها تعطى نوراً للذهن على الدوام وهى : أن لا نعرف شراً عن أحد من الناس ، وأن نصنع الصلاح مع الذين يؤذوننا ، وأن نحتمل ونصبر على ما يأتى إلينا من الأعداء .","وبعد ما حذّر من المحارنة وقيام الهوى الذى هو ثمرة العظمة ، حرض على الإتضاع لأنه قال : إعدد نفسك لتحمل الإهانة ، وتهدئة قلوب المعتدين عليك ، وتواضع للذين يطلبون أن يتكبروا عليك . واقْتَنِ سكوناً بإفراز ، وسلاماً حصيناً الذى هو الإتضاع .","وإذا ما أهنت من إنسان ، اغصب نفسك على ألا تحارنه أو تكافئه بالمثل ، حتى إن كنت قد قاسيت منه شروراً فى دفعات كثيرة . فإذا ما صنعت هكذا ، يهرب منك شيطان العظمة والغضب ، وتمتلىء من نور النعمة والتواضع .","* * *"],58:[{h:"أمثلة لقديسين إحتملوا"},"تاريخ القديسين حافل بقصص الإحتمال ، بل إن كان القديسين قد إحتملوا ، ولكننا نود أن ننتقى هنا بعض أمثلة نقدمها للإحتمال ، والمثال الأول منها يعطى صورة عن الرغبة فى إقتناء فضيلة الإحتمال ...",{h:"١ ـ مثال لإحتمال امرأة بارة :"},"قصّ الأنبا بيامون هذه القصة عن الفائدة التى نجنيها من الخطاة . وسنوردها هنا باختصار ( كما نشرها يوحنا كسايان ) :","امرأة من أسرة غنية ذهبت إلى القديس الأنبا أثناسيوس ، وطلبت منه امرأة لتعينها . فأوصى أن يقدموا لها أحسن أرملة فى الهدوء والطاعة والخدمة ... إلخ . وفعلاً ذهبت الأرملة إلى منزلها وخدمتها أحسن خدمة . فرجعت المرأة البارة إلى القديس أثناسيوس وقالت له : [ إننى أردت أرملة تعيننى ] . فلما تأكد أنهم أعطوها أفضل امرأة ، عندئذ فكّر فى الأمر وقال لهم سراً : أعطوها أسوأ أرملة .",{h:"فقدموا لها أرملة مشهورة بالشجار والشتائم وكثرة الكلام وخلق المشاكل ..."},"فأحضرتها إلى منزلها ، وكانت تخدمها وتصبر على معاملتها . وهذه تثور وتشتمها وتتمرد عليها وتقول لها : [ إنكِ أخذتينى من الراحة إلى التعب بدلاً من إراحتى ] . وكانت تتمرد عليها . وتطور الأمر حتى كانت تمد يدها إليها ...!",{h:"كل ذلك وهى صابرة ببشاشة . وتعلمت كيف تنتصر على الغضب ، ليس بمقاومتها ، وإنما بالخضوع لها بأكثر إتضاع ."},"وهكذا عندما نالت فضيلة الصبر التى إشتاقت إليها ، ذهبت إلى الأسقف وشكرته . وقالت له : [ إنك أعطيتنى حقاً امرأة لتعيننى وتشددنى . أما الأولى فكانت تكرمنى بالأكثر وتدللنى بخدماتها ] ."],59:["وقد إختتم أنبا بيامون هذه القصة بقوله : [ هذا مثال كاف قيل عن جنس المرأة ، حتى أننا بهذه القصة لسنا نتثقف فحسب ، بل بالأكثر نخزى لأننا لانستطيع أن نحفظ الصبر ، إلاّ إذا لجأنا إلى المغارات والقلالى ...! وهو بهذه العبارة يقصد النوع الخاطىء من التوحد .. أما التوحد الحقيقى فيقصده إنسان ناجح فى الإحتمال والصبر . ولكنه يبغى التفرغ للعبادة والتأمل .",{h:"٢ ـ مثال القديس الأنبا بفنوتيوس :"},"كان الأنبا بفنوتيوس قديساً عظيماً سار بسرعة عجيبة فى الطريق الرهبانى ، وأصبح موضع ثقة الجميع وإعجابهم . واعتبره الشيوخ كواحد منهم ، وهو لايزال شاباً .",{h:"من أجل هذا حسده أحد الرهبان ودبر له مكيدة :"},"ذلك أنه فى أحد أيام الآحاد ، إنتهز فرصة وجوده فى الكنيسة ، ودخل قلايته ودسّ فيها مخطوطة تحت السعف . ثم ذهب هذا الراهب إلى الكنيسة . وبعد إنتهاء الصلاة شكا إلى الأنبا إيسيذيروس ـ فى مجمع الرهبان كلهم ـ أن مخطوطته قد سرقت منه ، ولا يدرى مَنْ أخذها . فتملكت الدهشة جميع الرهبان . وتعجبوا كيف يمكن أن يحدث أمر فظيع مثل هذا فى الاسقيط ، أن تُسرق مخطوطة راهب منه ؟!","وعهد القديس الأنبا إيسيذيروس إلى ثلاثة من الشيوخ بتفتيش القلالى ، بينما بقى الرهبان فى الكنيسة . وأخيراً عثر على المخطوطة فى قلاية الأنبا بفنوتيوس . وكان ذلك موضع دهشة الجميع .",{h:"ولم يدافع الأنبا بفنوتيوس عن نفسه ، وإنما طلب من الرهبان بدموع كثيرة أن يصلوا من أجله ."},"كما طلب أن تفرض عليه عقوبة ، و يعطى قانوناً للتوبة . ومرّ أسبوعان على الأنبا بفنوتيوس فى تذلله ، وهو يحضر إلى الكنيسة دون أن يدخل ، وإنما يتضرع إلى الداخلين بدموع أن يصلوا عنه ...",{h:"أما الأخ الذى دسّ له المكيدة ، فقد صرعه روح نجس ."}],60:["وفى صرعه كشف الأمر على حقيقته . وقد صلى عليه القديس الأنبا إيسيذيروس الذى كانت له موهبة إلهية عظيمة فى إخراج الشياطين ، إلاّ أنّ الشيطان الذى صرعه لم يفارقه . وكانت هذه هى الحالة الوحيدة التى لم يستطع فيها الأنبا إيسيذيروس أخراج شيطان !",{h:"وذلك أن الرب كان قد أعد هذه المناسبة ليرفع بها وجه عبده القديس بفنوتيوس الذى هو برىء ، إحتمل التهمة فى إنسحاق وهدوء . فصلى الأنبا بفنوتيوس على الشاب ، فخرج منه الشيطان ."},{h:"٣ ـ إحتمال القديس يوحنا القصير :"},"فى إحدى المرات دُعى أنبا يوحنا إلى الكنيسة . فاجتمع حوله الإخوة وسألوه أسئلة من جهة أفكارهم . فقال له واحد من الشيوخ : [ إنك يا يوحنا تشبه امرأة فاجرة تزين نفسها لكى يكثر عشاقها . هكذا أنت ] . فتنهد أنبا يوحنا وقال [ بالصدق هكذا يا أبى ] . وبعد ذلك سأله شيخ يحبه : [ ألم تضطرب من الداخل ؟ ] . فقال له : [ كلا ، بل كما أنا فى الخارج ، هكذا كنت فى الداخل ] .","قال أنبا يوحنا القصير : دفعة لما كنت ذاهباً فى طريق الاسقيط ببعض الليف ، سمعت الجمال يقول لى كلمات . كان قد أوشك أن يجعلنى بها أغضب ، ولكننى للتو تركت الليف وهربت ...","وحدث مرة أنه كان جالساً مع الإخوة قدام الكنيسة ، وكان كل منهم يكشف له أفكاره . فنظر أحد الشيوخ وأمتلأ حسداً عليه ، فقال له : [ يا يوحنا ، إنك ممتلىء سحراً ] . فأجابه [ الأمر هكذا كما تقول يا أبتاه ، ولكن إن كان هكذا حكمك علىَّ مجرد ما نظرته فى الظاهر ، فما عساك كنت تقول لو علمت أيضاً بما عندى فى الخفاء ؟! ] ..."],61:[{h:"٤ ـ إحتمال القديس موسى الأسود :"},"أراد رئيس الأساقفة البابا ثاؤفيلوس أن يمتحن الأنبا موسى الأسود عند رسامته قساً . فقال للكهنة : [ إذا جاء الأنبا موسى إلى المذبح ، فاطردوه لنسمع ماذا يقول ] . فلما دخل إنتهروه وطردوه قائلين : [ اُخرج يا نوبى إلى خارج الكنيسة ] . فخرج الأنبا موسى وهو يقول : [ حسناً فعلوا بك يا رمادى اللون يا أسود الجلد . وحيث أنك لست إنساناً ، فلماذا تحضر مع الناس ؟! ] .","ولما رأوا إحتماله أعادوه إلى الكنيسة ، فعاد بهدوء دون أن يتذمر ..",{h:"٥ ـ قصة راهب عمّال :"},"طلب أحد الرهبان ممّنْ يسكنون البرية مكاناً لنفسه ، فجاء إلى دير من أديرة الصعيد . وكان سكان ذلك الدير كلهم قديسين . فبعدما أقام عندهم أياماً ، قال لرئيس الدير : [ صلِّ علىَّ يا أبى ، واخلِ سبيلى ، فإنى لست أريد البقاء ههنا ] . فسأله الرئيس [ لأى شىء يا ابنى ؟ ] .","فأجابه قائلاً : [ إنه لا يوجد ههنا تعب ، والآباء كلهم قديسون . وأما أنا فإنى إنسان خاطىء ، أريد أن أمضى إلى موضع حيث اُهان واُشتم . لأنه بالإزدراء والإهانة يخلص الخطاة ] . فتعجب منه الأب ، وعلم أنه عمّال . فأخلى سبيله قائلاً : [ امضِ وتقوَّ ] ...",{h:"٦ ـ قصص متفرقة من سير الآباء :"},"★ لما زار الأنبا أمونيوس القديس أنطونيوس ، أخرجه خارج القلاية ، وأراه صخرة عظيمة ، وقال له : [ إشتم هذه الصخرة واضربها ] . ففعل كما أمره . فقال له القديس أنطونيوس : [ هل تكلمت الصخرة ؟ ] فقال [ لا ] . فقال له [ إنك تستطيع أن تكون هكذا فتخلص ] .","★ قيل عن الأب الكبير إيسيذيروس قس الاسقيط : إن كل مَنْ كان عنده أخ صغير النفس أو شتام أو عليل ، ويطرده من عنده ، كان القس إيسيذيروس يأخذه إلى عنده ، و يطيل روحه عليه ، ويخلص نفسه ."],62:["★ سأل أخ الأنبا إيسيذيروس : [ لماذا تخافك الشياطين جداً ؟ ] . فقال الشيخ [ لأنى منذ ترهبت ، جاهدت كثيراً ألا اسمح للغضب أن يدخل إلىَّ ] ..","★ قصد الأب يوحنا السريانى أناسٌ أشرار خبثاء . فأخذ ماء فى طست وغسل أقدامهم . فما كان منهم إلاّ أن إحتشموا من إكرامه لهم وتابوا .","★ سكن شيخ مع إخوة . واعتاد أن يقول لهم عن الشغل دفعة واحدة . فإذا لم يفعلوه ، قام هو وعمله بدون غيظ .","★ سأل اخوة الأنبا أرمانيوس قائلين : [ ماذا يجب أن نتدبر ؟ ] . فأجابهم الشيخ [ لا أتذكر أنى سألت فى وقت من الأوقات إنساناً أن يعمل شيئاً ، ما لم أسبق فأجعل فى خاطرى أنى لا أغضب متى خالفنى ولم يعمل بما قلته له . وهكذا عشنا عمرنا كله بسكون وسلام ] .","★ أخ أغضبه أخوه . فلما دخل قلايته إستحى أن يصلى إلى الله بسبب الوجع المتقد فى قلبه . ولكنه لما تطارح قدام الله قائلاً : [ يا سيدى ، لقد غفرت لأخى من كل قلبى ] للوقت جاءه صوت يقول له : [ قد أخذت شبهى . إذن صلِّ لى بدالة ] ..","★ أحد محبى الجهاد فى النسك رأى رجلاً يحمل ميتاً على نعش ، فقال له : [ أتحمل ميتاً ؟ إذهب واحمل الأحياء ] .","★ ذهب بعض الشيوخ إلى شيخ كان يسكن البرية ، لكيما يكشفوا له أفكارهم و ينتفعوا بمعرفته . فوجدوا شباناً كانوا يرعون الغنم خارج قلايته . وكانوا يقولون بعضهم لبعض كلاماً لا يليق . فقال الشيوخ لهذا الشيخ المتوحد : [ يا أبانا ، كيف إنك لم تأمر هؤلاء الشبان أن يكفوا عن الشتائم ؟ ] فقال لهم الشيخ : [ يا إخوتى ، صدقونى ، لقد أردت مرات عديدة أن آمرهم . ولكنى وبخت نفسى قائلاً : إن كنت لا تستطيع أن تحتمل هذا الأمر الصغير ، فكيف يمكنك أن تحتمل تجربة أقسى إن أتت عليك ؟! ] . ولذلك لم أقل لهم أية كلمة قط ، حتى يصير هذا الأمر مذكراً لى أنه ينبغى أن أحتمل الأشياء التى تصادفنى ..."],63:[{h:"الإحتمال الحقيقى"},{h:"ليس الإحتمال هو مجرد السكوت على الإهانة ، أو الصبر على الضيقة . فهذا مجرد إحتمال خارجى ينبغى أن يكون معه الإحتمال الداخلى ."},"وكثيرون يقولون بألسنتهم ألفاظ إحتمال ، أو ألفاظ إتضاع ، بينما يكون داخلهم بركان ثائر متقد . ولا تكون قلوبهم قد إحتملت ، ولا تكون أفكارهم هادئة .",{h:"والبعض يثور ويقول إننى صريح لا أخفى ما أبطن ."},"ويقول : [ إن ما فى قلبى ، يخرج على لسانى ] . وحسن جداً أن يكون صريحاً . ولكن ليس حسناً أن يثور . والواجب أن يجعل داخله هادئاً ، ليتفق مع الهدوء الخارجى . ويدرب قلبه على الإحتمال ، ليكون محتملاً من الداخل ومن الخارج معاً .",{h:"الإحتمال الحقيقى ، هو أن يحتمل الإنسان بلا تذمر ، وبلا تضجر ، وبلا غضب وبلا حزن ."},"ويحتاج الأمر إلى تدريبات كثيرة ، سنذكرها إن شاء الله فى الفصل الأخير من هذا الكتاب الخاص بعلاج الغضب . كما يحتاج الأمر إلى فضائل يتصف بها الإنسان ، وتساعده على الإحتمال الحقيقى غير الزائف .",{h:"الإحتمال ينبغى أن يكون بمحبة ."},"وكما قال الكتاب : « المحبة تحتمل كل شىء . المحبة لا تحتد ولا تقبّح ... » ( ١ كو ١٣ : ٦ ، ٧ ) .","وقيل أيضاً : « المحبة تستر كثرة من الخطايا » ( ١ بط ٤ : ٨ ) « المحبة تستر كل الذنوب » ( أم ١٠ : ١٢ ) . والاحتمال الصادر عن الحب هو إحتمال راسخ وغير مظهرى . مثاله إحتمال الأم لطفلها ، واحتمال الأب الروحى لأخطاء أبنائه ."],64:[{h:"وينبغى أن يكون الإحتمال باتضاع وبفرح :"},"وفى ذلك يقول القديس مار أوغريس [ محب المجد الباطل إذا شُتم يحزن . أما المتضع فهو يحتمل بفرح ] .","ومع الإتضاع لا يوجد تذمر ، ولا شعور بالظلم ، بل يوجد شعور باستحقاق الألم . و يفرح الإنسان المتضع إذ يحسب الإهانة التى حدثت له بمثابة المجازاة ، كما شعر داود حينما أهانه شمعى بن جيرا وشتمه وشمت به ( ٢ صم ١٦ : ١٠ ) .",{h:"ولا يكون الإحتمال الحقيقى تظاهراً ، وإنما من عمق القلب ."},"وفى ذلك قال القديس افرام السريانى [ مَنْ يُوبخ فيصمت بتخابث ، يخبىء فى ذاته حقداً . أما مَنْ يجاوب بوداعة سلامية ، فيكون غير حقود ] . وقال القديس الأنبا يوسف :",{h:"[ الإحتمال التصنعى كثيراً ما يثير الغضب بأكثر مهارة من الكلمات . والصمت المغيظ يفوق أكثر الشتائم بشاعة فى تأثيره ] ."},"وحسناً قال عنه النبى « كلماتهم ألين من الزيت ، إلاّ أنها كالنبال » ( مز ٥٥ : ٢١ ) . وعن مثل هذا يمكن أن يقال أيضاً « بفمه يكلم صديقه بالسلام . ولكنه يصنع له الفخاخ سراً » ( إر ٩ : ٨ ) . وهنا لا يكون الصمت إحتمالاً ، ولا تكون الكلمات الهادئة محبة ، وإنما تخفى إنتظاراً لفرصة الإنتقام .",{h:"الإحتمال يظهر بالتجربة"},{h:"لا يمكن أن يوصف الإنسان بأنه محتمل ، إلاّ إذا تعرض لأسباب تدعو إلى الغضب أو التضايق والتذمر ، وإجتاز ذلك بهدوء وبسلام قلب ، دون أن يخطىء ."},"وقد شرح ذلك القديس بيامون ( فى المقابلة ١٨ ) وقال :","إن الصبر لا يكون مستحقاً للمديح والإعجاب ، عندما يكون الهدوء محفوظاً ، فى حالة عدم التعرض لسهام الأعداء . ولكنه يكون عظيماً ومجيداً ، إذا ما هبت"],65:["عليه عواصف التجربة وبقى غير متزعزع ... وفى ذلك يكون قد تشدد بالأكثر","ومن الواضح أنه لا يمكن أن يُدعى أحد صبوراً ، إلاّ إذا إحتمل بدون تضايق كل الإهانات الموجهة إليه . ولذلك ليس باطلاً أن يمدحه سليمان قائلاً : « الرجل الصبور أفضل من الجبار . والذى يكبح غضبه ( مالك روحه ) خير ممّنْ يأخذ مدينة » ( أم ١٦ : ٣٢ ) . وأيضاً « الإنسان الكثير الاحتمال ( بطىء الغضب ) هو كثير الفهم . أما قصير الروح فهو غبى جداً » ( أم ١٤ : ٢٩ ) .",{h:"لأن قوة أى إنسان ليست أهلاً للمديح ، إن قد نال صفة حسنة بسبب أنه لم يُجرَّب . كما أنه بالتأكيد لا يوجد محل للإنتصار ، حيث لا يوجد صراع ولا حرب . لأنه « طوبى للرجل الذى يحتمل التجربة ، لأنه إذا تزكّى ينال إكليل الحياة ، الذى وعد به الله الذين يحبونه » ( يع ١ : ١٢ ) ."},{h:"وتحويل الخد الآخر لا يدل على إحتمال ، إن كان ذلك بشكلية غير نابعة من شعور قلبى حقيقى . وإنما هى مظهرية فى حرفية تنفيذ الوصية ."},{h:"شكلية تحويل الخد الآخر"},"يشرح هذا الأمر القديس الأنبا يوسف ( فى المقابلة ١٦ مع كاسيان ) فيعرض لنا نوعين من هذه الشكلية هما :","( أ ) إنسان يستفز آخر بكلمات حتى يغضبه و يثيره لضربه . فإذا ما لُمس بأقل لطمة ، يسرع فى الحال بتقديم الخد الآخر للطم ، حتى يأخذ مظهر المسيحى المحتمل المتقد تماماً لوصية الرب القائل « فحول له الآخر أيضاً » ( مت ٥ : ٣٩ ) .",{h:"وهكذا يظن أنه ينفذ الوصية عن طريق خسارة أخيه وعثرته !"},"وفى الواقع يحضرنا فى هذه المناسبة قول القديس بطرس الرسول « لأنه أى مجد هو إن كنتم تلطمون مخطئين فتصبرون ؟! بل إن كنتم تتألمون عاملين الخير فتصبرون ، فهذا فضل عند الله » ( ١ بط ٢ : ٢٠ ) . وهكذا قال الرسول أيضاً لا يتألم أحدكم ... كفاعل شر ، أو متداخل فى أمور غيره ( ١ بط ٤ : ١٥ ) ."],66:[{h:"فهذا الذى يثير غيره ليلطمه فيحتمل ، هو إنسان لم يتألم من أجل البر ، وإنما كفاعل شر مستحق للعقوبة ."},"كما أنه سبب عثرة لأخيه ، وسيسأله الله عن سقوط هذا الأخ فى خطية الغضب وفى خطية الضرب . كما أن هناك نقطة أخرى وهى :",{h:"( ب ) تقديم الخد الآخر يكون فى إنسحاق وليس فى كبرياء ."},"ومثال هذه الكبرياء مَنْ يقدم خده الآخر فى غضب وعصبية وهو يقول لمَنْ لطمه [ تفضل إضرب كما تشاء . خذ راحتك .. أنا استحق . أنا الغلطان . إضرب ... ] !! بطريقة يبدو فيها أنه يسجل عليه أخطاءه ، بل يثيره و يعطيه فرصة ليزيد هذه الأخطاء . ولا يظهر فى ذلك أى أثر للإحتمال أو الإتضاع أو محاولة التهدئة ، بعدم مقاومة الشر وتحديه وإثارته .",{h:"والقديس يوسف يشرح تحويل الخد الآخر بأنه الداخلى :"},"فيقول : إن الخد الآخر لا يمكن أن يوجد إلاّ فى الإنسان الداخلى ... بمعنى أنه إذا ما تقبّل خدك الأيمن الخارجى لطمة من الضارب ، فإن الإنسان الداخلى أيضاً ـ بموافقة متضعة ـ يقدم خده للضارب ، مشاركاً الإنسان الخارجى فى إحتماله ، مخضعاً ذاته للإهانة من الضارب . أى أن الإنسان الداخلى لا يضطرب من الضربات التى يتلقاها الإنسان الخارجى . وبهذا يريد مخلصنا أن نتخلص بالتمام من كل دوافع الغضب فى أعماق النفس من الداخل .","ولعل هذا يذكرنا بقول القديس الأنبا أنطونيوس :",{h:"إذا وبخك شخص من الخارج ، فوبخ نفسك من الداخل ، كمستحق لما حدث لك ..."},"وهكذا يكون هناك إنسجام بين حالتك فى الخارج والداخل . فلا تكون هناك لطمة فى الخارج ، وتذمر فى الداخل ، وإنما تقدم الداخل للطمة أخرى عن طريق لوم النفس ، وإشعارها بالخطأ وإستحقاق ما أصابها من إهانة . وسنشرح هذا إن شاء الله فى باب ( علاج الغضب ) عن طريق لوم النفس .","إن شكلية تحويل الخد الآخر ، لا تهدىء الموقف ، مهما استُخدمت معها"],67:["ألفاظ لا خطأ فيها ، ولكنها تقال بروح الغضب والإثارة . يقول القديس يوسف عن أمثال هؤلاء :",{h:"إنهم لا يفشلون فقط فى تخفيف نار الغيظ التى إشتعلت ، بل بالأكثر يلهبونها بأشد عنف ، سواء فى مشاعرهم الخاصة ، أو فى شعور الأخ الغضبان ."},"وحتى إن قدر هؤلاء بطريقة ما أن يهدئوا و يسكنوا أنفسهم ، إلاّ أنهم لا يجنون ثمار البر ، بينما هم يدعون لأنفسهم فخر الاحتمال عن طريق خسارة قريبهم ! وهكذا فإنهم يبعدون عن تلك المحبة التى قال عنها الرسول إنها « لا تطلب ما لنفسها » ( ١ كو ١٣ : ٥ ) .",{h:"ليس المطلوب منك فقط أن تكون هادئاً بعيداً عن الغضب ، إنما أيضاً أن تعمل على تهدئة الطرف الآخر بقدر إمكانك ."},"فلا تأخذ مظهر الهادىء المحتمل ، وتظهره فى صورة الثائر المعتدى .",{h:"عدم الدفاع عن النفس"},{h:"من مظاهر الإحتمال عند القديسين عدم الدفاع عن النفس ، وقبول بعض التهم الرديئة فى صمت كما لو كانوا مذنبين . وكل ذلك بسبب الإتضاع الذى هو دعامة قوية للإحتمال ."},"وقد شرح مار إسحق هذا الأمر بتفصيل فقال :","إن كنت متواضعاً على الحقيقة ، فإن ظلمت لا تضطرب ، ولا تعتذر عن الأمر الذى جير عليك فيه . بل إقبل مثلبة وكلمات الظلم كأنها حق ، ولا تصرف الاهتمام إلى اقناع الناس بأنك قد اتهمت ظلماً ...","لأن قوماً قد سموا أنفسهم فسقة بإرادتهم ، ولم يكونوا كذلك . وآخرون صبروا على اسم الزنا وهم بعيدون عنه ، وكانوا يربون الثمرة ( ابن الخطيئة ) التى ليست منهم بدموع كما لو كانت تخصهم ، والتمسوا الصفح من ظالميهم ومشهريهم بنحيب وذرف عبرات عن إثم ما فعلوه ، بينما أنفسهم متوجة بكل طهارة وعفاف [ لعله يقصد هنا القديسة مارينا مثلاً ] ."],68:["وطائفة كانوا يتشكلون بزى الجهال ، لئلا يشرف قدرهم و يتمجدوا بما فيهم من السيرة الفاضلة المكتومة ، وهم قد تملحوا بالملح الإلهى ، ثابتين بكل هدوء ورزانة عقل . حتى أنهم من سمو أفعالهم الكاملة حظوا بالملائكة القديسين منادين بعظم شرفهم [ ولعله يقصد كمثال : القديسة الهبيلة ] .","وأما أنت يا هذا ، فإنك تظن أنك ذو إتضاع ، وما تقدر أن تمسك نفسك عن السب ، ولا تقدر أن تحتمل ساكتاً .","فإن كنت تريد أن تعلم هل أنت متواضع ، إختبر نفسك بما ذكرناه ، وهل أنت تضطرب وتتكدر بمثل تلك الأسباب .","مار إسحق السريانى",{h:"تعليق"},{h:"إن الدفاع عن النفس ليس خطيئة تتعب الضمير ."},"فمن حق الإنسان أن يدافع عن نفسه . وقد قال السيد الرب « إن أخطأ إليك أخوك ، فوبخه ، وإن تاب فاغفر له » ( لو ١٧ : ٣ ) . وقال أيضاً « إن أخطأ إليك أخوك ، فاذهب وعاتبه بينك وبينه وحدكما . إن سمع فقد ربحت أخاك . وإن لم يسمع فخذ معك أيضاً واحداً أو اثنين ، لكى تقوم كل كلمة على فم شاهدين أو ثلاثة . وإن لم يسمع منهم فقل للكنيسة . وإن لم يسمع من الكنيسة ، فليكن عندك كالوثنى والعشار » ( مت ١٨ : ١٥ ـ ١٧ ) .",{h:"إذن فمعاتبة الأخ ليست خطيئة ، وكذلك شكواه إلى الكنيسة . بل إن الشكوى إلى الدولة ليست أيضاً خطيئة .."},"ونحن نعلم أن القديس بولس الرسول ، رفض أن يسلمه الوالى لليهود ، وقال له « أنا واقف لدى كرسى ولاية قيصر ، حيث ينبغى أن أحاكم ... إلى قيصر أنا أرفع دعواى » فقال له فستوس الوالى « إلى قيصر رفعت دعواك . إلى قيصر تذهب » ( أع ٢٥ : ١٠ ، ١٢ ) .",{h:"وبولس إحتج لما أرادوا أن يجلدوه ، وله الجنسية الرومانية ."}],69:["فلما مدوه للسياط قال لقائد المائة « أيجوز لكم أن تجلدوا إنساناً رومانياً غير مقضى عليه ؟! » . حينئذ إختشى الأمير لما علم أنه رومانى ( أع ٢٢ : ٢٥ ، ٢٩ ) .",{h:"إن رفع قضية فى المحكمة ، لا يدخل فى باب الغضب ، إذ قد يتم فى هدوء . لكنه يُناقش فى باب الاحتمال ."},"إذا أراد الإنسان أن يحتمل ويصبر صامتاً ، فهذه فضيلة له . وإن أراد أن يعاتب أو يشتكى إلى الكنيسة أو إلى قيصر ، فلا يكون قد أخطأ فى شىء . هذا حقه . وهو ليس مرغماً من جهة الدين أن يتنازل عن حقه .","أما الآباء النساك الذين تحدث عنهم مار إسحق ، فقد فضلوا أن ينالوا بركة الاحتمال ، وبركة فضيلة الاتضاع ، وفضائل المغفرة للمسيئين ، ومحبتهم ، والصبر على الإساءة . كل ذلك بنكران عجيب للذات . ولو دافعوا عن أنفسهم ما كانوا قد أخطأوا . ولكنهم فضّلوا حمل الصليب على حماية أنفسهم من الظلم .",{h:"أما بولس الرسول فلم يعتفِ من فضيلة الاحتمال ، ولم يرفض الجلد ولا الموت ..."},"من جهة الجلد قال عن نفسه « فى الضربات أوفر ... خمس مرات قبلت من اليهود أربعين جلدة إلاّ واحدة . ثلاث مرات ضُربت بالعصى . مرةً رجمت ... » ( ٢ كو ١١ : ٢٣ ـ ٢٥ ) . ولكن لعله إشتكى إلى قيصر ، لأنه أراد أن يذهب إلى رومه ليبشرها ! لذلك عندما تقابل مع يهود رومه قال لهم عن ذلك الموقف « ... كانوا يريدون أن يطلقونى ، لأنه لم تكن فىَّ علة واحدة للموت . ولكن لما قاوم اليهود ، إضطررت أن أرفع دعواى إلى قيصر ، ليس كأن لى شيئاً لأشتكى به على أمتى . فلهذا السبب طلبت لأراكم وأكلمكم ... » ( أع ٢٨ : ١٨ ـ ٢٠ ) .",{h:"على أية الحالات ، الأمر يحتاج إلى حكمة : متى يدافع الإنسان عن نفسه ، ومتى يصمت ؟"},"كما أن النساك الذين ماتوا عن العالم ، لهم مستوى روحى معين ، قد لا يستطيعه الذين يعيشون فى العالم ."],70:[{h:"هل الوحدة هروب من الغضب ؟"},{h:"الهروب من الناس ، ليس هروباً من الغضب ، فأساس الغضب والاحتمال هو داخل القلب . تأتى بنقاوة القلب من الغضب ، بالحب والاتضاع والاحتمال والمغفرة ، وليس بالهروب من أسباب الغضب . وهذا الهروب ليس إحتمالاً ..."},"ليس إنتصارك على حرب الغضب ، يأتى بالوحدة ، حيث لا يوجد أحد يغضبك . وأحياناً يتعرض الإنسان لحرب الغضب وهو فى الوحدة ، و يسقط . ربما حشرة تتعبه وتضايقه ، أو رمال تملأ أذنيه وأنفه وعينيه وتردم له مغارته . أو قد تهب ريح شديدة فتطير أوراقه . وهناك أيضاً حروب الشياطين .","أما يتدرب الراهب على فضيلة الإحتمال ، وهو فى مجمع الرهبان . فإذا أتقنها وأتقن الفضائل التى تكتسب وسط الناس ، والتى يسمونها « فضائل المجمع » حينئذ يُسمح له بالوحدة . وقد قال الآباء :",{h:"الذى لا يستطيع أن يحتمل مضايقات الإخوة فى المجمع ، كيف يمكنه أن يحتمل مضايقات الشياطين فى الوحدة ؟!"},{h:"رأى يوحنا كاسيان :"},"تعرض لهذا الموضوع فى كتابه « المعاهد » Institutes فقال :","أحياناً عندما نُغلب من الكبرياء أو عدم الاحتمال ، ونريد أن نحسن طباعنا الخشنة الفظة ، نشكو من إحتياجنا إلى الوحدة ، كما لو كنا سنجد فضيلة الاحتمال هناك ، حيث لا يثيرنا أحد !","ونبرر اضطرابنا بأن سببه أخطاء إخوتنا ، وليس الخطأ فى عدم إحتمالنا !! وإذ نلقى باللوم على الآخرين ، لا يمكننا أن نصل إلى فضيلة الاحتمال ، ولا إلى الكمال ."],71:["أما عن أخطاء الآخرين ، فإن إرادتهم لا تقع تحت سلطاننا ، ولكن الجزء الأساسى فى تقومنا وسلام ذهننا ، إنما يتعلق بإرادتنا نحن .",{h:"إن عدم غضبنا يجب ألا ينتج عن كمال غيرنا ، وإنما عن فضيلتنا نحن وطول أناتنا ."},"وبالإضافة إلى هذا ، فإن الكاملين الذين تنقوا من كل الأخطاء ، هم الذين ينبغى أن يطلبوا البرية . وإذ يكونون قد تخلصوا بدقة من كل أخطائهم وسط مجمع الإخوة ، يدخلون حينئذ إلى البرية ، ليس هروباً فى جبن ، وإنما بغرض التأمل الإلهى ، والرغبة فى إدراك الأمور السمائية إدراكاً أكثر عمقاً . وهذا لا ينال إلاّ فى الوحدة .",{h:"لأن أية أخطاء لم تُعالج بعد ، إن حملناها معنا إلى البرية ، فإننا نجدها مختفاة فينا غير مقضى عليها ."},"بل إن الوحدة تقوى هذه الأخطاء بالأكثر ، لأن الإنسان يبدو فى عينى نفسه صبوراً متضعاً ، طالما هو لا يصطدم مع أحد فى حديث . ولكنه يرتد إلى طبيعته السابقة ، حينما تحدث أية فرصة للألم . وإذا بتلك الأخطاء التى كانت مخبأة تظهر على السطح . ومثل جياد غير ملجمة ـ تغذت مدة طويلة فى كسل ـ تندفع من حواجزها بكل وحشية وتحفز لتحطيم سائسها .","أو هى تشبه كل أنواع الحيات السامة أو الحيوانات المتوحشة ، التى بينما تبقى فى وحدة وفى مرابضها تبدو غير مؤذية ، لأنها فى الواقع لا تؤذى أحداً ... ولكنها عندما تجد فرصة لإيذاء أحد ، ففى الحال تخرج السمّ المختزن فيها ، وتظهر وحشية طبيعتها .","ونحن نتذكر ـ حينما كنا فى الوحدة ـ أن شعور الإثارة كان يزحف علينا ، ضد فلمنا لأنه كان أصغر أو أكبر مما يجب ! أو على المراة عندما تبرى برداءة أو بغير الحدة التى كنا نريدها ! حتى أننا لم نكن نستطيع أن نتخلص من إنزعاج ذهننا ، إلاّ بأن نشتم المادة التى لا تحس ، أو على الأقل نشتم الشيطان ..!","لذلك فإن عدم وجود أناس يثور غضبنا عليهم ، لا يجدينا نفعاً كوسيلة"],72:["للكمال . لأنه ـ إن لم يكن الاحتمال موجوداً فينا ـ فإن مشاعر الألم التى تسكن قلوبنا ، يمكن بالسواء أن تنفق ذاتها على الجمادات ، ولا تسمح لنا بأن نوجد فى حالة سلام مستمر .","من أجل كل هذه الأمور هناك قاعدة فى الأديرة وهى :",{h:"لا يسمح للمبتدىء فى الرهبنة أن يدخل مباشرة إلى حياة الوحدة ."},"وإنما يتدرب أولاً فى حياة المجمع ، حتى إذا إكتسب ما يسمونه باسم [ فضائل المجمع ] ـ أى المحبة والإحتمال والوداعة وخدمة الآخرين والمسالمة مع الناس ... إلخ ـ حينئذ يسمحون له بالوحدة ، والحبس فى القلاية .",{h:"لئلا إذا دخل إلى الوحدة بأخطائه ، تعيش معه هذه الأخطاء فى الوحدة ، وتنمو لأنها غير ظاهرة ..."},"ولا تكون الوحدة دليلاً على نقاوته ، وإنما غطاء لأخطائه تحجبها من الظهور . وإذ لا تظهر يظن فى نفسه البر ، فيحارب بالمجد الباطل بينما له أخطاء تحتاج إلى علاج .","مثال ذلك : متوحد شرح لأحد الآباء الشيوخ كيف أنه صار له سلطان على الشياطين فى حروب روحية عديدة ! فأجابه الشيخ : إذهب واخضع نفسك للمجمع ، حينئذ ستجد نفسك ليس لك سلطان إلاّ على عصاك !",{h:"هذا كله بالنسبة إلى الرهبان ، أما عن العلمانيين ، فقد يلجأون إلى الاعتزال بدلاً من الوحدة ، أو يلجأون إلى حياة الإنطواء والبعد ..."},"وليس فى شىء من هذا إنتصار ، وإنما هروب ...","وعلى كلٍ فالهروب من الشر ، خير من الوقوع فيه ...","فقد يعجز إنسان عن إحتمال شخص ما ، فيعتزله .","فى هذا التصرف يكون قد إبتعد عن الاصطدام وأخطائه . ولكنه إن أراد أن يتدرب على فضيلة الاحتمال قد يعاشر هذا النوع ، كما فى قصة المرأة البارة ( ص ٥٨ ) . ولكن ليس الجميع فى هذا المستوى . وكل شخص يسلك حسب مستواه ..."],73:[{h:"الفصل الخامس : أسباب الغضب"},"أسباب داخلية :","١ ـ الطبع .","٢ ـ الذات ، الكرامة .","٣ ـ يريد حسب هواه .","٤ ـ حب التسلط .","٥ ـ عدم المحبة وعدم الاحترام .","٦ ـ الإرهاق العصبى والجسدى .","٧ ـ الإلحاح .","٨ ـ المشغولية .","٩ ـ متاعب الذكاء .","١٠ ـ الغضب القبلى .","١١ ـ أسباب نفسية .","١٢ ـ قلة الحكمة .","١٣ ـ حرب شيطانية .","١٤ ـ قلة الإتضاع .","أسباب خارجية :","١٥ ـ أخطاء الآخرين .","١٦ ـ عدم الطاعة .","١٧ ـ أسباب مالية ومادية .","١٨ ـ دعوى الدفاع عن الحق .","١٩ ـ أصلاح الآخرين .","٢٠ ـ ضعفات خارجية ."],74:["الغضب له أسباب كثيرة جداً ، تختلف من شخص إلى آخر . وهذه الأسباب إما أن تكون أسباباً داخلية ، تتعلق بنفسية الإنسان الغضوب وعقله وقلبه وأسلوبه فى التعامل . وإما أن تكون للغضب أسباب خارجية من الظروف المحيطة أو البيئة أو تصرفات الآخرين وأخطائهم .","وسنتناول الأمرين معاً ، ونبدأ بالأسباب الداخلية ، لأنها أكثر فاعلية .",{h:"الأسباب الداخلية للغضب"},"وهى تتعلق بطبع الإنسان ، وحساسيته . ومقدار تدخل الأنا ( الذات ) فى تصرفاته وحساسيته نحو تصرفات الآخرين ، ونحو كرامته وحقوقه . ويدخل فيها أيضاً مقدار سعة صدره ، ونوعية أعصابه ، ومشاعره نحو الآخرين ، وهل فيها عداوة أو حقد أو عدم إحترام . كذلك تتدخل فى غضبه أيضاً نقائصه الروحية والنفسية ، وأيضاً حالته الجسدية وما يعانيه من مرض أو إرهاق ... إلخ . ولنتناول هذه الأمور جميعها بالتفصيل ، لنناقشها معاً بنعمة الله :",{h:"الطبع"},"هناك إنسان طبعه نارى ، حاد ، سريع الانفعال ...","هذا النوع يثور بسرعة ، ويتفعل بسرعة ، وربما لأتفه الأسباب . وقد يكون هذا الطبع قد وصل إليه بالوراثة ، أو تتصف به أسرته . أو قد يكون نتيجة لتهاونه مع أخطاء روحية ، تحولت فيه بالتكرار إلى عادة ، ثم تطورت حتى صارت طبعاً ملازماً له ، يتصرف به تلقائياً .",{h:"إنه يذكرنى ببعض المواد السريعة الإشتعال ."},"الخشب قد يشتعل . ولكنه فى إشتعاله أقل من القش الذى يشتعل بسرعة . وكلاهما أقل فى إشتعالهما من الكحول أو البنزين أو المغنسيوم ، هذه المواد التى هى"],75:["سريعة الإشتعال جداً . وأخطر منها الدينياميت والبارود مثلاً ، الذى يشتعل وينفجر . وكل من هذه المواد لها طبيعتها الخاصة بها ...",{h:"كذلك الناس لهم طباع ، بعضهم يشتعل ببطء ، والبعض بسرعة ولكنه هوائى كالكحول . وبعضهم يشتعل وينفجر ."},"وبعضهم يشتعل ويُشعل غيره معه ، ويمتد لهيبه إلى كل مَنْ حوله . عكس ذلك الصخر مثلاً ، تقترب منه النار فلا تقدر على إشعاله . أما الماء فمن طبيعته أن يطفىء النار . ولكن إن تمكنت منه النار وهو محصور فى إناء ، فإنها تسخنه ، وربما تبخره أيضاً ... فمن أية طبيعة أنت ؟ وهل طبعك له تدخل فى غضبك ؟ أم أن غضبك له أسباب عارضة يزول بزوالها ؟!...",{h:"قد يوجد إنسان حسّاس جداً . أقل كلمة قد تجرحه ، وأقل تصرف قد يؤذيه ، ويبكيه ، ويقلقه ."},"إنه نوع من الطبع المرهف . مشاعره كالحرير ، أقل خدشة تترك تأثيرها على نسيجه . نخشى عليه حتى من النسيم العليل ، فقد يجعله يطير أو يهتز !! وهذا النوع يؤول أى تصرف ـ مهما كان بريئاً ـ تأويلاً سيئاً يبرر به غضبه !",{h:"وهناك طبع آخر فيه قسوة أو خشونة ."},"ومثل هذا له إستعداد أكثر للغضب ، وللإيذاء وجرح شعور الآخرين . ولعل من أمثلة هذا النوع شمعون ولاوى اللذان قال عنهما أبوهما يعقوب « ملعون غضبهما فإنه شديد ، وسخطهما فإنه قاس » ( تك ٤٩ : ٧ ) .",{h:"ومع ذلك كله ، فالطبع يمكن علاجه :"},"يمكن تغيير الطبع تماماً ، أو تهذيبه ، أو تخفيفه ، أو تحويله . وذلك بالتثقيف عن طريق المرشد والأب الروحى . أو بطريق الجهاد والتدريب والصلاة من الشخص نفسه . وكذلك مؤازرة النعمة وعمل الروح من جهة تدخل الله ومعونته .","و يقدم لنا التاريخ القديس الأنبا موسى الأسود ، الذى كان قبل توبته يتصف بالقسوة الشديدة والعنف والإيذاء ، ولكنه تحول إلى إنسان وديع طيب خدوم ومحب للإخوة فلا يعتذر إنسان عن غضبه بأن طبعه هكذا . المفروض أن ينتصر على طبعه"],76:[{h:"الذات والكرامة"},"يندر أن يوجد غضب ، ليس وراءه الذات والكبرياء ...",{h:"حيث يغضب الإنسان من أجل كرامته أو من أجل حقوقه ."},"والمعروف أن الأنسان ـ فى حالة غضبه ـ يكون مركزاً فى الإهتمام بذاته ، ولا تهمه إطلاقاً مشاعر الشخص الذى يغضب عليه . كل ما يفكر فيه هو كرامته ، التى يكون حساساً جداً لكل ما يمسها . أما كرامة غيره فلا يفكر فيها إطلاقاً أثناء غضبه . إن ( الأنا ) Ego هى التى تحكم الموقف تماماً . « كرامتى التى أُهينت أو جُرحت .. وحقوقى التى ضاعت أو ظلمت فيها . أنا لا يمكن أن أعامل بهذا الأسلوب . أنا سأرد بالمثل أو أكثر . لابد أنى أعلّم من أمامى درساً لن ينساه » ...! وهكذا تتكرر كلمة ( أنا ) مراراً ساعة الغضب ..",{h:"وهذه ( الأنا ) هى التى تفسد العلاقات العائلية والإجتماعية :"},"إنها وراء كل خلاف بين زوجين . فلو فكّر كل زوج فى إراحة زوجته لا فى راحته هو ، وفى إسعادها لا فى إسعاد نفسه على حسابها . ولو فكّر فى المحافظة على كرامتها وشعورها ، تماماً كما يفكر فى كرامته هو وشعوره ... لو عاش معها بهذا الأسلوب ـ الذى تختفى فيه الأنا ـ ما حدث خلاف على الإطلاق . وكذلك لو تصرفت الزوجة بنفس الأسلوب . ولو وضع كل منهما فى ذهنه وفى قلبه أن رسالته فى الزواج هى أسعاد شريكه فى الحياة ...",{h:"كذلك يدخل فى موضوع الذات ، محبة المديح .."},"فالغضب قد لا يكون سببه إهانة حدثت ، إنما قد يكون السبب أيضاً أن الإنسان المحب للمجد الباطل لم يقابل بالمديح الذى ينتظره ، أو بالاحترام الذى يتوقعه ، مثلما غضب هامان على مردخاى ( أس ٣ : ٥ ) .",{h:"إن محب الكرامة يتطلب معاملة خاصة ، إن لم يجدها يغضب . وهو لا يحتمل نقداً ولا معارضة ، ولا حتى نصحاً ."}],77:["وذلك إن وجد فى النصح ، أو فى التعليق على تصرفاته ، ما يمس كرامته ، أو ما يقلل من العظمة التى يتصورها لنفسه ، فيثور ويغضب وينتقم لكرامته ! ومثل هذا الشخص لا يستطيع أن يعيش إلاّ فى جو من المديح ، أو من التملق والنفاق ، من تابعين له فى كل عمل وكل فكر ...",{h:"وهذا الشخص أيضاً لا يقبل عتاباً ، ولا توجيهاً ، بل يغضب ."},"فالعتاب يشعره أنه قد أخطأ فيغضب . والتوجيه يشعره أنه ينقصه شىء ليعرفه ، ويرى هذا ضد كرامته . بعكس الودعاء المتضعين الذين يقابلون التوجيه بشكر .",{h:"وهكذا يعجم معارفه عن التحدث معه بصراحة . وبذلك يفقد الصداقة المخلصة النصوحة ."},"إن الثقة الزائدة بالنفس تُوجد داخل القلب غروراً ينفر منه الناس . والغرور يجعل صاحبه يقابل كل مناقشة بثورة إما أنه يرى مناقشته ضد الاحترام الواجب تقديمه له ، لأن أفكاره فوق مستوى النقاش . أو أنه يرى مَنْ يناقشه أقل من مستواه . وهكذا يصل إلى إستعلاء الفكر . وهذا الاستعلاء يرهق نفسيته وأعصابه .",{h:"ويتحول الجدال معه إلى عراك ، ربما يهين فيه مناقشه ."},"عن مثل هذا الإنسان إبعد كل البعد ، كما قال الكتاب « لا تستصحب غضوباً » ... كما أن النقاش لا يأتى معه بنتيجة سوى الصراخ والصياح والإصرار على عدم الاقتناع . وهو يبرر غضبه بأن رأيه هو السليم دائماً ، ورأى غيره هو المخطىء . ويرى أنه يجب أن يدافع عن رأيه . فإن لم يملك الدليل ، فأمامه الغضب والضجيج ...",{h:"كما لو كان سيكسب المناقشة بعلو الصوت ، أو يقهر غيره بغضبه عليه وإهانته له ."},"ولذلك فمثل هذا الغرور يدفع هذا الشخص الغضوب إلى إحتقار غيره ، واحتقار كل ما لهذا الغير من آراء وأفكار .. سبب غضبه كبرياء ، ونتيجة غضبه كبرياء ..!","هناك سبب آخر للغضب ، وهو رغبة الإنسان فى أن يتم كل شىء حسب هواه ."],78:[{h:"يريد حسب هواه"},{h:"( أ ) الذى يريد كل شىء حسب هواه ، لابد أن يصطدم بغيره فيغضب . إنه يتضايق من الذين يقفون ضد إرادته ، أو لا يسلكون حسب هواه ."},"وطبيعى أن الناس يختلفون فى الفكر والاتجاه ، وفى الشعور والإرادة . ولا يمكن لهذا الشخص أن يجد كل الناس يوافقونه أو يسيرون فى تياره . فإن أصر على إتجاهه ، ورفض التنازل عن هذا الهوى ، لابد أن يصطدم بالناس ويغضب ..! سواء فى داخل بيته ، أو فى مكان عمله ، أو فى دائرة نشاطه ..",{h:"( ب ) وقد يغضب الإنسان لأن له رغبة لم تتحقق ."},{h:"مثال ذلك الابن المدلل ، الذى يقدّم رغبات يصر على تحقيقها مهما كان الأمر ."},"وقد يكون ذلك غير ممكن ، أو ليس من صالحه ، أو ليس مناسباً من جهة الوقت . ولكنه يغضب ، وقد يثور لأن رغبته لم تتحقق .","وقد تغضب الزوجة أيضاً بالمثل لرغبات تطلبها لم تتحقق ، ولنفس السبب قد يغضب المرؤوس من رئيسه .",{h:"بل قد يغضب الإنسان أحياناً على الله تبارك اسمه ، بسبب الصلوات التى لم تتحقق ..!"},"وقد يغضب من أب اعترافه ، إذ لم يوافقه على رغبة معينة ، يرى أنها ليست فى صالحه ، أو ليست فى مستواه ... كما لو كان أب الاعتراف هو مجرد جهاز تنفيذ ، إن لم يوافق يعرض نفسه لغضب أبنائه . وبهذا يفقد وضعه كمرشد وقائد روحى ..!",{h:"حب التسلط"},"حب التسلط مرض نفسى وروحى يقع فيه كثيرون ، ولابد أن يقود إلى الغضب ، مادام هذا التسلط يريد أن يفرض إرادته على غيره ، بحق أو بغير حق ."],79:[{h:"هذا المتسلط يتدخل فى شئون غيره ، ويقيم نفسه وصياً أو رقيباً ، مما يؤدى إلى غضب هذا الغير ، وإلى غضب المتسلط الذى يريد خضوع غيره"},"فهو يريد أن يفرض رأيه فى البيت وفى العمل وفى الكنيسة ، وربما فى كل مكان يحل فيه . وإن لم يأخذوا برأيه ـ أو بأوامره ـ يغضب ! وربما يعاند ويشاجر ويعلو صوته ، أو يفرض رأيه بالعنف ! وبالعناد وتصلب الرأى !","كالزوج فى البيت ، الذى لا يتعامل كزوج بقدر ما يتعامل كحاكم وسلطان يأمر وينهى ، مهما كانت الأوامر ممكنة التنفيذ أم لا . وويل للتى لا تطيع ..! وكالأخ الذى يريد أن يسيّر أخته حسب هواه ، فى دخولها وفى خروجها ، فى لبسها وفى زينتها ، فى طريقة كلامها ، فى معاملاتها ... لا عن اقناع وتوعية . وإنما بالإرغام ، لمجرد فرض السلطان . وإلاّ فقد ينتهر ويضرب ويتحكم .. بقوة ...","وقد يحاول أن يفرض هواه أيضاً على والديه وإخوته ، وربما على زملائه فى الدراسة والعمل ، وإلاّ ... فالغضب والصياح والعراك والعنف !!",{h:"عدم المحبة وعدم الإحترام"},"( أ ) المعروف أن « المحبة تحتمل كل شىء ( ١ كو ١٣ : ٧ ) .",{h:"فإن كره شخص إنساناً ، قد يغضب عليه بسرعة ، ولا يحتمله فى أى خطأ مهما كان ضئيلاً ، بعكس أخطاء لأحبائه قد يحتملها بكل هدوء مهما كانت أشد خطأ ! وبهذا تحتمل الأم طفلها ولا تغضب عليه . ويحتمل الزوج زوجته مادام يحبها . فإن بدأ يغضب عليها ويقسو فى المعاملة ، تكون محبته بلا شك قد قلت . وإن وصل الغضب إلى الطلاق ، تكون المحبة قد زالت ..."},{h:"( ب ) ويدخل فى هذا الباب أيضاً الحقد السابق ، والرغبة فى الانتقام أو فى الايذاء ."},"هذه التى تكون مترسبة فى القلب ، وتنتظر فرصة لتظهر فيها وتعبر عن مشاعرها المكبوتة ، وعن ثورتها لسبب لم يغفر بعد ."],80:["ذو الحقد السابق لا يحتاج إلى سبب حاضر ، إنما قد يغضب بلا سبب . عنده رصيد قديم يكفيه . وربما يختلق سبباً بغير داع ، كما فى قصة الذئب والحمل .","( جـ ) عدم إحترام شخص ما ، يساعد الغضب عليه . لأن الإنسان عادة لا يغضب على مَنْ يحترمهم ، سواء كانوا كباراً من جهة المركز أو من جهة القرابة .",{h:"فإذا غضب على هؤلاء الكبار ، ورفع صوته عليهم ، يكون قد فقد إحترامه لهم ."},"الغضب عموماً يدل على عدم إحترام وعدم تقدير بالنسبة إلى الكبار أو إلى أى أحد . والإنسان الذى يتعود أن يحترم الكل ، ويكلم الكل برقة وأدب وتوقير لا يكلم أحداً بغضب . إلاّ إذا إستلزم الصالح حزماً معيناً ...",{h:"الإرهاق الجسدى والعصبى"},"إذا كان الإنسان مرهقاً جسدياً ، من تعب ، أو قلة نوم ، أو عمل فوق الطاقة ، قد تكون أعصابه غير محتملة . فإن حدث ضغط عليه من الخارج ، قد يغضب ، و يتصرف بغير إحتمال ، بينما لا تكون طباعه هكذا .",{h:"والإنسان فى حالة الإرهاق والتعب العصبى لا يحتمل نقاشاً . فإن ناقشه أحد فغضب ، وهو يعرف أنه مرهق ، يشترك معه فى مسئولية الغضب ."},"لذلك على الإنسان أن يتحين الوقت المناسب للنقاش ، ولا يضغط على إنسان مرهق عاجز عن الاحتمال ، كما لا يتعب مريضاً بنقاش ، وهو فى حالة تعب أو ألم لا تساعده صحته ولا أعصابه ولا قدرته على التفكير والتركيز .","وإن المستريح جسدياً وعصبياً يجد فرصة تساعده على بحث الأمور بالتروى والهدوء ، ويكون أقدر على الاستماع وحل المشاكل . بينما الإنسان المرهق لا تكون له نفس الإمكانية . وإن حدث ضغط عليه ، قد لا تحتمله أعصابه ، ويكون عرضة للغضب أو للتوتر ."],81:[{h:"الإلحاح"},{h:"( أ ) وربما يكون من أسباب الإرهاق العصبى : كثرة الإلحاح ."},"فهناك نوع من الناس يطلب طلباً من شخص ، و يعرف أنه غير موافق عليه ، أو غير متفرغ له . ولكنه يكرر الطلب ، و يلح و يلح ، و يصر على ما يريد ، بطريقة متتابعة تتعب النفس وترهق الأعصاب ، حتى يثور عليه الشخص الذى يتقدم إليه بالطلب .",{h:"وهذا الذى ألح قد لا يظن أنه لم يقع فى خطية غضب . ولكنه مسئول لأنه كان السبب فى غضب غيره . أرهقه ، وأثاره وأعثره ."},"وقد ضغط عليه بما هو فوق إحتماله . وهنا ينطبق القول « نفس تؤخذ عوضاً عن نفس » وأيضاً « ويل لمَنْ تأتى من قبله العثرات » ( مت ٨ : ٨ ) .","لا يكفى أن الإنسان لا يغضب ، وإنما يجب ألا يتسبب فى غضب غيره .",{h:"( ب ) ويقع فى نفس الخطأ مَنْ يستمر فى الكلام مع شخص مشغول غير متفرغ له ."},"هو أيضاً يرهقه و يثيره ويعثره ويغضبه ، لأنه غير مستطيع أن يترك مشغوليته ليتفرغ له ، بينما هذا مصرّ على أن يتحدث إليه ... وقد يطيل الحديث حتى يتعبه .","مثال ذلك إنسان يطلب شخصاً آخر فى مكالمة تليفونية ، وهو لا يعرف إن كان مشغولاً أو غير مشغول . وقد يكون معه فى نفس الوقت ضيوف . وقد رفع السماعة ظاناً أنها كلمة وتنتهى . ولكن الشخص يستمر فى الكلام . وكلما أشار إليه بأنه مشغول ، لا يبالى ويستمر يتكلم ، حتى يثيره ويغضبه .",{h:"المشغولية"},"شئان بين اثنين : أحدهما لديه وقت متسع للناس وأحاديثهم ومشاكلهم ومناقشاتهم . والآخر مشغول إلى أبعد حد ، ليس لديه وقت مطلقاً لإطالة الحديث ،"],82:["أو للتفرغ للمشاكل والمناقشات وليس لديه وقت للمقابلات أو للزيارات . إن قابل أحداً يريد أن ينتهى من موضوعه بسرعة ، لأن له أموراً أخرى تشغله .",{h:"لذلك فالمشغولون عرضة للوقوع فى الغضب ، أكثر من الذين هم فى فراغ"},"التلميذ مثلاً فى فترة الامتحانات ليس لديه وقت للمقابلات والأحاديث . فإن أراد أحد أن يشغله بموضوع سيثير غضبه . وإن جاءت أسرة صديقة للزيارة فى أيام الإمتحانات ، وأطالت الجلسة والحديث ، يكون أهل البيت ضاغطين على أعصابهم بسبب إضاعة الوقت ، مهما كانت الأسرة عزيزة عليهم .","وهكذا كل زيارة أو حديث فى وقت غير مناسب .",{h:"متاعب الذكاء"},"أحياناً يحتاج الإنسان الذكى إلى مستوى معين يتعامل معه . لأن التعامل مع مستوى أقل بكثير ، قد يتعبه ، و يوقعه فى الغضب .","مثال ذلك : إنسان يعرض عليه أمراً ، فيفهم مقصده تماماً من أول عبارة . ولكن ذلك الشخص يظل يشرح ويطيل مما لا يحتاج إليه هذا الذكى إطلاقاً .","وتكون هذه الإطالة وهذه الشروحات ثقلاً على أعصابه تتعبه . وبخاصة إن أظهر لذلك الشخص أنه فهم ما يريد أن يقول ، ومع ذلك استمر يشرح و يطيل ، كأنه مع إنسان يحتاج إلى فهم ...","أو قد يحدث العكس . وهذا الإنسان هو الذى يبدأ الكلام ، و يشرح . والذى يتكلم معه لا يفهم ، و يسأل أسئلة لا معنى لها ، تسبب ضيقاً .",{h:"إن الذين يتعاملون مع الأذكياء يعجبون جداً بعقلهم وفهمهم ، ولكنهم أحياناً يشكون من غضبهم بسبب ما ذكرناه وأشباهه ."},"لهذا فإن الأذكياء الذين يتصفون بالاحتمال وطول الروح ، هم بركة كبيرة . ولعلهم يضعون فى أذهانهم الفارق فى مقدرات مَنْ يتعاملون معهم ، ويحتملونهم على هذا الأساس ."],83:[{h:"الغضب القبلى"},"أى نسبة لعادات القبيلة ، حيث يغضب الكل لغضب واحد منهم . ولعل هذا يوضحه قول الشاعر :","إذا غضبت عليك بنو تميم      وجدت القوم كلهم غضابا","وهكذا إن بحثت حالة كل فرد ، لا تجد سبباً شخصياً قد أغضبه ، إنما هو قد غضب تضامناً مع غيره بروح القبيلة كما تعوّد .","وهذا الأمر يحدث كثيراً فى مجال العائلات ، والمجتمعات الصغيرة ، كما يحدث أيضاً حتى بين الدول التى تجمعها روابط معينة أو معاهدات أو تحالفات ، أو التى تكون من جنس واحد أو مذهب واحد ... إلخ .",{h:"أسباب نفسية"},{h:"قد يغضب الإنسان مثلاً ، بسبب سوء الظن :"},"فإن أساء الظن بإنسان ، قد يتعب منه ، ويغضب عليه وهو برىء ، إذ ـ بسوء الظن ـ يلصق به الكثير من المتاعب ، ويحمله مسئوليتها .","ويدخل فى هذا النطاق ، إن كان أحد قد أخذ فكرة رديئة عن إنسان ، ورسخت فى قلبه وذهنه بعمق ، بحيث أصبح غير قادر على تغييرها . وبهذه الفكرة يغضب عليه .",{h:"وقد يغضب الإنسان أحياناً بدافع التشاؤم ."},"كإنسان يكره الرقم ١٣ فيكون مستعداً أن يتضايق بسبب أى شىء يحدث ، ملقياً المسئولية على هذا الرقم ، إن كان تاريخ اليوم مثلاً ، أو رقم الجلوس له كطالب ، وما أشبه . ويغضب كيف وقع هذا الرقم من نصيبه ؟! وكيف لم يجد شقة لسكناه إلاّ فى بيت رقم ١٣ أو مضاعفاته ؟! أو يغضب لأن رقم التليفون الذى أعطى له ، أو رقم العربة التى إشتراها يبدأ برقم ١٣ ...!"],84:[{h:"وقد يغضب الإنسان إن كانت نفسيته تعوزها البساطة ."},"فمن طريق فقدانه للبساطة يقع فى تعقيدات كثيرة تدفعه إلى الغضب دفعاً ، وتصور له الأمور مقلقة ! بينما لو تناول الموضوع ببساطة ، لأمكن أن يمر بسلام .","وقد يغضب الإنسان إن كان من عيوبه النفسية أنه ضيق الصدر ، أو أنه يشكو من القلق وتوقع الشر ، وما شابه ذلك ... فكل ما يحدث له ، يفسره بطريقة تدفعه إلى الغضب وإلى الشكوى والتذمر .",{h:"قلة الحكمة"},{h:"الإنسان القليل الحكمة ، لا يعرف كيف يتصرف ، لذلك يعالج كل مشاكله بالنرفزة والسخط على كل شىء ."},"أما الحكيم ، فإذ يجد حلاً ، لا يقع فى الكآبة والسخط ، ولا يجد سبباً للغضب ، لأن كل الأمور تسير ميسّرة ...","وصدق الكتاب حينما قال « الغضب يستقر فى حضن الجهال » ( جا ٧ : ٩ ) وهم أيضاً جهال ، لأنهم يجهلون النتائج السيئة لغضبهم .",{h:"حرب شيطانية"},"قد يكون الغضب حرباً شيطانية يقاتل بها الإنسان ، و يوغر قلبه على أخيه ، ويحثه على قتاله . وهى إحدى الحروب المعروفة التى ذكرها الآباء ضمن حديثهم عن [ الثمانية أفكار المقاتلة للنفس ] . والشيطان يعرف أن يدبر أسباباً لها ويحبكها ، ويملأ قلب الإنسان غيظاً وحنقاً ورغبة فى القتال .",{h:"فقدان الإتضاع"},"قد يكون سبب الغضب إهانة من الخارج . ولكن إن كان القلب قوياً"],85:["من الداخل ، فإنه يحتملها ولا يضطرب . وهذه القوة الداخلية تأتى من تواضع القلب . لذلك يرى الآباء الذى يغضب بسبب إهانة ، يدل على أنه فاقد للإتضاع . وهذا هو سبب غضبه .","لذلك يقول القديس بيامون فى مقابلته مع يوحنا كاسيان :","إن الصبر الحقيقى والهدوء لا ينالان أو يحفظان بدون إتضاع عميق فى القلب . أما إذا كنا نضطرب عندما يهاجمنا أحد ، فمن الواضح أن أساس الاتضاع لم يُوضع فينا بإحكام . ولذلك إن هبت عاصفة ولو صغيرة ، يهتز البناء كله ويضطرب .","وهكذا عندما يُقهر أحد من خطأ ، و يشتعل بنار الغضب ، يجب ألاّ يعتبر أن مرارة الإهانة الموجهة إليه هى سبب خطيئته ، وإنما بالحرى ظهور ضعفه المخفى .",{h:"وهذا حسب مثال ربنا ومخلصنا الذى قاله عن البيتين : الواحد منهما مؤسس على الصخر ، والآخر على الرمل ."},"فمن الاثنين يقول إن عواصف المطر والسيول والرياح صدمتهما بالتساوى . ولكن المؤسس على الصخر الصلب لم يتأذّ على الإطلاق من قوة الصدمة . بينما المؤسس على الرمل المتحرك المتنقل ، إنهار فى الحال . وبالتأكيد يظهر أنه لم يسقط بسبب إندفاع العواصف والسيول عليه ، وإنما لأنه كان مبنياً على الرمل .",{h:"لأن القديس لا يختلف عن الخاطىء من حيث التعرض للتجربة ، إنما يختلف عنه فى أنه لا يُقهر حتى من الهجوم القوى ، بينما الآخر يُقهر حتى من أقل تجربة ."},"إن عقلنا ـ ما لم يكن مشدوداً بقوة من حماية الله الذى يقول فى الإنجيل « ملكوت الله داخلكم » ( لو ١٧ : ٢١ ) ، فباطلاً نتخيل أننا نستطيع أن نهزم ضربات العدو الهوائى بمساعدة أشخاص يعيشون معنا ، أو نتفاداها ببعد المكان ، أو نبعدها بحماية الجدران .",{h:"لذلك يلزمنا ألا نبحث عن سلامنا فيما هو خارج منا ."},{h:"لأن كما أن « ملكوت الله داخلكم » ، كذلك أعداء الإنسان هم الذين من « أهل بيته » ( مت ١٠ : ٣٦ ) ."}],86:["فلا يوجد عدو لى أكثر من قلبى الخاص ، الذى هو حقاً من أهل بيتى ، القريب لى . وحينما يكون الذين من أهل بيتنا ( أى مشاعرنا وأفكارنا ) ليسوا ضدنا ، فإن ملكوت الله يمكن ضمانه أيضاً فى سلام فى القلب .","فإن فحصت الأمر بتدقيق ، أجد أنه لا يمكن أن يؤذينى أى إنسان ـ مهما كان مؤذياً ـ ما لم أحارب ضد نفسى بقلب مشاكس !",{h:"فإن أصابنى ضرر ، فالخطأ لا يرجع إلى هجوم الآخرين ، وإنما إلى عدم إحتمالى أنا شخصياً ."},"لأنه كما أن الطعام القوى الدسم هو صالح لإنسان فى صحة جيدة ، كذلك هو مضر لإنسان مريض . لكنه لا يمكن أن يضر الإنسان الذى يتناوله ، ما لم يساعده على الضرر ضعف مَنْ يتناوله .",{h:"أخطاء الآخرين"},"لا شك أن أخطاء الآخرين توضع فى مقدمة الأسباب الخارجية للغضب . سواء كانت هذه الأخطاء فى حق الشخص الذى يغضب ، أو فى حق الجماعة ، أو هى أخطاء ضد المبادىء والقيم .",{h:"إنها أخطاء تثير الضمير . ولكنها عند البعض تثير الأعصاب ."},"ومن حق الضمير أن يثور ضد الخطأ ، فهذا علامة صحية . أما ثورة الأعصاب فليست الحل السليم . إذا إرتبط عمل الضمير بالحكمة وبالهدوء ، حينئذ نعالج الأمر بغير نرفزة ، محتفظين بأعصابنا سليمة .",{h:"أول شىء فى أخطاء الآخرين يثير الغضب ، هو الإهانة والإساءة ."},"سواء كانت موجهة لنا شخصياً ، أو لأحبائنا ، أو لمعتقداتنا ومثلنا وكل ما هو مقدس ومحترم فى نظرنا . وليست الإهانات الواضحة فقط ، إنما ما يظنه الشخص إهانة حسب مقاييسه الخاصة ، وحسب فهمه للأمور .","وربما لا تكون هناك إهانة فعلية قد صدرت من أحد ، إنما نقل الكلام صوّرها"],87:["هكذا ، فأهاجت السامع وأغضبته .","وكم من أمور حدثت بحسن نية ، ولكنها فهمت بطريقة واضحة ، واعتبرت إهانات . ولكن التفاهم أوضحها . وبالعتاب الهادىء إتضح الأمر على حقيقته ، فزال الغضب ...",{h:"وقد يكون سبب الغضب هو أخطاء الآخرين فى العمل ."},"كإنسان يعمل ، فيهمل فى عمله ، أو يتكاسل ، أو لا يقوم بمسئوليته بطريقة جادة ، أو يتغيب كثيراً بلا سبب مقبول ، أو لا يتقن عمله ، أو لا يكون مخلصاً وأميناً فى العمل ، أو يكون غير منتج ، أو لا تكون مواعيده سليمة ... إلى سائر هذه الأسباب التى تتسبب فى غضب صاحب العمل ، أو المشرف عليه .",{h:"ومن الأسباب المثيرة أيضاً الغش والخداع فى التعامل ."},"حيث لا يستريح الإنسان للتعامل مع أشخاص غير مستقيمين ، أو لا يتكلمون بالصدق ، فيغضب لكذبهم وخداعهم ، ويغضب لمحاولاتهم فى ستر الكذب بخداع آخر ، وبأساليب اللف والدوران التى لا تنتهى ...",{h:"عدم الطاعة"},"إنها من الأسباب الرئيسية للغضب بالنسبة إلى كل مَنْ هو فى مسئولية أو فى منصب . فالأب يغضب لعدم طاعة أولاده ، والرئيس يغضب لعدم طاعة مرؤوسيه . والمدرس يغضب لعدم طاعة تلاميذه .",{h:"عدم الطاعة يشعر الشخص بعدم إحترام الآخرين له ، وعدم تقديرهم لكلامه أو أوامره أو نصائحه . أو تشعره بعنادهم ولامبالاتهم . فيغضب ويثار ..."},"وقد لا يضع الآمر فى ذهنه نوعية الأمر الذى أصدره ، ومدى إمكانية تنفيذه ، وظروف الأشخاص الذين أمرهم ، والعوائق التى وقفت أمامهم . وبدلاً من التفاهم يغضب . أو قد يكون العيب عندهم فعلاً ، وقد أخطأوا ."],88:[{h:"أسباب مالية ومادية"},{h:"قد يحدث الغضب أيضاً لسبب مالى أو لأية خسارة مادية . وكثيراً ما تحدث مشاكل عائلية بسبب المال ."},"يدخل فى هذا الأمر البخل كسبب للغضب ، والإسراف أو التبذير كسبب آخر للغضب ، وكذلك الخلاف حول أمور الميراث والوصية . وكل ما يدخل فى نطاق المعاملات التجارية ، والضرائب والجمارك ، والبيع والشراء . والتلاعب بالأسعار ، واحتكار الأسواق ، وغش الأصناف ، وحيل التنافس ... وما إلى ذلك من أسباب للغضب بسبب المال .","وفى نطاق الوظائف يدخل فى أسباب الغضب ، نقص المرتب ، أو تأخر المنحة ، أو العلاوة ، أو الترقية ، أو المكافأة ، أو الحوافز ، أو الشعور بالظلم إذا قورنت معاملته المالية بمعاملة الآخرين ...",{h:"وما يقال عن المال ، يقال أيضاً عن كل المقتنيات ."},"فقد يحدث خلاف بين زوج وزوجته بخصوص الجهاز وأثاثات المنزل ، وكل لوازمه المادية من طعام وشراب وملابس ، وأجهزة ، وترفيهات ، ومصروفات متعددة ، ولوازم الأولاد . وكل هذا يمكن معالجته بغير غضب ، إذا وُجد الحب ...",{h:"دعوى الدفاع عن الحق"},{h:"١ ـ كم من أناس يغضبون ويثورون بحجة الدفاع عن الحق !"},"والدفاع عن الحق فضيلة . ولكن ( النرفزة ) ليست وسيلة فاضلة للدفاع عن الحق . بحيث أن البعض يتشاجرون ويتشاتمون ، ويستخدمون القسوة والعنف وإهانة الآخرين ، كل ذلك باسم الحق ، والدفاع عن الحق .",{h:"والعجيب فى ذلك ، أن ضميرهم لا يوبخهم على غضبهم ."}],89:["يظنون ذلك نوعاً من الغضب المقدس ! على أن الغضب المقدس ينبغى أن يكون مقدساً فى وسيلته كما فى هدفه . والشخص الذى لم يتنقَ بعد من خطايا العنف والشتيمة والعصبية والقسوة ، هذا لم يصل بعد إلى الدرجة التى يؤتمن فيها على الدفاع عن الحق . ولعله يسمع عبارة :",{h:"أيها الطبيب ، إشفِ نفسك أولاً ( لو ٤ : ٢٣ ) ."},"٢ ـ ويقول مار إسحق فى ذلك : « إن أردت أن تعرف الرجل السائب القلب ، إستدل عليه من كثرة كلامه ، ومن تخبط حواسه ، ومن مقاومته لكل شىء . يقول ويريد أن يغلب . لأن الذى ذاق الحق ، ولا أيضاً بسبب الحق يقاوم ويحارن ( أى يعارك ويجادل ويحتد ) . لأن الذى يظن أنه يغير على الحق بحرانه مع الناس ، هذا إلى الآن ما عرف الحق كيف هو !.. لأنه حيث يحل الروح ، فأيضاً الحب والإتضاع يوجدان . وهذه هى علامة الروح ...",{h:"٣ ـ ومار إسحق يتحدث تحت عنوان ( الغضب ومدرسة معرفة الخير والشر ) فيرى أن من أسباب الغضب أن نفحص أعمال الناس هل هى خير أم شر ، ونحاسبهم بالعدل ، ونبعد فى ذلك عن الحب والسلام والتواضع ."},"فيقول : مدرستان فى داخلنا : واحدة لمعرفة الخير والشر . والأخرى للتدرب على معرفة الحق المتعلق بالحياة والنور .","أما مدرسة معرفة الخير والشر ، فهى المختصة بأصول العدل والإختبار . وهذه تولد الغيرة والاضطراب والاحتداد والضيق والحسد والغضب ومحبة الغلبة مع باقى الآلام .","وأما مدرسة الحق ـ التى هى مكتب النعمة ـ ففيها الحب والسلام والهدوء والتواضع والصبر ، مع بقية ثمار الروح القدس التى كتب عنها بولس الرسول ( غل ٥ : ٢٢ ، ٢٣ ) . ومن الثمرة تعرف الشجرة . فالآن يجب عليك أن تميز فى أية مدرسة أنت تتربى ...",{h:"إذا دخلت النفس مكتب معرفة الخير والشر ، يلقن فيها العدل ، ويدرب على الغيرة والغيظ والحسد والحزن ..."}],90:["وإذا دخلت النفس مكتب معرفة الحق ، ففيه النعمة تلقن الرحمة والتحنن على الصالحين والأشرار بالسواء . وتربى القلب على الحب والسلام والفرح والهدوء مع الإتضاع والصبر على حمل الضعف وعجزه مع باقى ثمار الروح القدس .",{h:"أكثر الناس يكملون حياتهم فى مكتب العدل ، وقد جعلوا أنفسهم قضاة وحكاماً لجميع الناس ، ويزنون الأعمال الصالحة والرديئة التى للآخرين بالعدل ."},"ولم يعرفوا قط أن هناك مكتباً آخر يلقن النعمة والرحمة ، حيث الحب الفائض على الجميع بلا تفريق على الصالحين والأشرار بالسواء ، لأنهم يعيشون فى جو القريب .","كثيرون بعد جهد يفلتون من مكتب العدل ، و يدخلون فى مكتب النعمة الذى أظهره سيدنا ببشارته ، حيث يعجب الإنسان بعظم مواهب الله .",{h:"الغضب بحجة إصلاح الآخرين"},"كثيرون يتطوعون لإصلاح الآخرين . ولكنهم يفعلون ذلك فى غضب ، وليس فى حب . وهكذا يقعون فى خطايا عديدة . إذ يظنون أن إصلاح الآخرين هو فى إهانتهم وتحقيرهم والغضب عليهم . ويكون ذلك بأسلوب منفر ، لا يجببهم فى الخير .",{h:"يقول مار إسحق : الذى يشتعل بالغضب من أجل تقويم الآخرين ( أى إصلاحهم ) ، هذا ليس متواضعاً .."},"و يضيف : لأن التواضع الحقيقى هو مبتعد عن كل غضب ، ونقى من سائر حركات الغيرة . و يسأل بمحبة ، وما يتألم ولا يتكدر . لأن الذى هو متواضع ، فمن البدء تتبعه قوة الاحتمال والصبر .","٣ ـ و يوحنا كاسيان أيضاً يدين [ الغضب بحجة إصلاح الآخرين ] :","فإنه لما إستشهد بقول بولس الرسول « لينزع منكم كل غضب وكل سخط"],91:["وصياح وكلام ردىء مع كل خبث » ( أف ٤ : ٣١ ) ، علّق على ذلك بقوله : عندما يقول الرسول « لينزع منكم كل غضب ( أى النرفزة ) ، فإنه لا يستثنى شيئاً مهما كان لازماً أو نافعاً لنا ، حتى فى إصلاح الآخرين ، لئلا ينطبق عليه القول « أيها الطبيب إشفِ نفسك أولاً » ( لو ٤ : ٢٣ ) . أو لئلا إذ يرى قذى فى عين أخيه ، لا يرى الخشبة التى فى عينه ! إذ كيف يبصر أن يخرج القذى من عين أخيه ، وهو الذى له خشبة الغضب فى عينه ؟! ( مت ٧ : ٣ ـ ٥ ) .",{h:"٤ ـ والقديس مار أوغريس له نفس الرأى فيقول :"},"... هذا الأمر يصير لك ويلحقك من قبل العدو ، أعنى أن تفكر بغضب فى تقويم أخيك الكسلان . أما تقويم أخيك الكسلان ، فجيد هو ، وإذا ما طلبته وجدته . ولكن لا يكن ذلك بغضب لأن كل الأشياء قد تجىء بغير غضب ...",{h:"انظر لئلا فيما تريد أن نشفى آخر من أمراضه النفسية ، تصير أنت فى أمراض ليس لها برء ..."},"إجعل بالك ألا تؤلم أحداً من الإخوة عندما تصلحه ، وإلاّ فإنك تكون فى كل زمانك غير متخلص من شيطان الكآبة ، ويكون لك ذلك عثرة فى كل حين ، وللذى تصلى لأجله .",{h:"من أقوال الآباء"},{h:"قال مار أوغريس :"},"المجد الباطل ، ومحبة المال ، يحركان الغضب ... وقال أيضاً : الذى يطلب الكرامة يتعظم قلبه ، حتى لا يحتمل كلمة إهانة واحدة . محب المجد الباطل إذا شُتم يحزن ، أما المتضع فإنه يحتمل بفرح .",{h:"وقال القديس أرسانيوس :"},"من أربعة أمور يتولد الغضب : المعاملة ، والمساومة ، والإنفراد برأيك فيما تهواه نفسك مع عدولك عن مشورة الآخرين ، وإتباع شهواتك ."],92:[{h:"وقال الأنبا موسى :"},"بأربعة أمور يتحرك فى الإنسان الغضب : الأخذ والعطاء ، وإقامة الهوى ، ومحبة الإنسان أن يعلّم غيره ، وظنه فى نفسه أنه عاقل .",{h:"وقال مار إفرام :"},"هيولى النار الحطب . وهيولى الغضب : إستعلاء الرأى .",{h:"وقال القديس يوحنا الأسيوطى :"},"الذى يريد أن يقيم هواه فى كل شىء ، يتلف ودّ المحبة بمقاومته . فإياك أن تشتهى إقامة هواك فى كل شىء ، لئلا يبغضك الناس .",{h:"وقال أحد الرهبان :"},"من أجل هذا تركت عنى إرادتى ، لكى أنزع معها مسببات الغضب الذى يحارب الإرادة فى كل حين ، ويقلق العقل ويطرد المعرفة .",{h:"وقال أنبا إشعياء :"},"الغضب هو أنك تريد أن تقيم هواك ، وتغلب بالمقاومة ، وما تقطع هواك بالإتضاع . يقوى فيك الغضب والحنق على الذى يمنعك من تكميل هواك . وتطلب أن تعلّم . وتغضب على الذين يزدرونك . وتحب إستعمال العالم ، أعنى الغنى والمقتنى . وتغضب على مَنْ هو أغنى منك . وتحب الأخذ والعطاء . لأنه بالحقيقة من الأخذ والعطاء فى المتاجرات العالمية ، يشتد الغضب ويلتهب الحنق .","وقال الأنبا إشعياء أيضاً : أما الغضب فمن قساوة القلب .",{h:"وقال الأنبا دياراخس :"},"يأتى الغضب من محبة الكرامة . وكأننى أحببت كرامتى أكثر من أبديتى .",{h:"وقال مار إفرام أيضاً :"},"مَنْ يضحك على قريبه يستنهض غضبه . والمصلح مغبوط لأنه يُدعى ابن الله ."],93:[{h:"الفصل السادس : علاج الغضب"},"١ ـ بالتواضع .","٢ ـ بلوم النفس .","٣ ـ إعتبار المسىء كطبيب .","٤ ـ الرد بالآيات .","٥ ـ الإبطاء فى الغضب .","٦ ـ الجواب اللين .","٧ ـ الحكمة .","٨ ـ تذكر نتائج الغضب السيئة .","٩ ـ عدم التدرج إلى أسوأ .","١٠ ـ نقاوة القلب وليس الإنطواء .","١١ ـ المحبة والإحسان والهدايا .","١٢ ـ التفاهم والعتاب .","١٣ ـ التصريف وليس الترسيب .","١٤ ـ معالجة الغضب بست فضائل .","١٥ ـ تذكر مثال الله .","١٦ ـ هدوء الصوت والملامح .","١٧ ـ تداريب متنوعة ."],94:["هناك وسائل كثيرة لتفادى الغضب ، ولمقاومته ، ولعلاجه بالكلية . ونذكر من بين هذه الوسائل :",{h:"تواضع القلب"},"قال القديس دوروثيئوس عبارة جميلة هى :",{h:"[ الإنسان المتواضع لا يُغضب أحداً ، ولا يغضب من أحد ] ."},"ذلك أنه باستمرار يأتى بالملامة على نفسه فى كل شىء ، ولا يحسب أن أحداً قد أساء إليه ، بل أنه يرى كل ما يحدث له هو سبب خطاياه ... وإن كان لا يسمح لنفسه بأن يلوم أحداً ، ولا فى فكره ، فبالتالى لا يغضب على أحد ..",{h:"المتواضع يطلب بركة كل أحد ، وصلاة كل أحد . لذلك هو لا يُغضب أحداً ، بل بالحرى يطلب صلواته ."},"الذى يغضب يعتقد أنه على صواب ، ولذلك يغضب لأنه يرى أن إساءة قد لحقت به بدون وجه حق . وهكذا نراه يركزّ على أخطاء غيره ، ويثور على أخطاء غيره ، بينما المتواضع لا يفكر إلاّ فى خطاياه هو . ويرى أنه يستحق ما أساء به الناس إليه ، بل يستحق ما هو أكثر من إساءاتهم . لذلك فلا مجال إذن للغضب عليهم . وأفضل ردّ هو أن يقول مع اللص اليمين :",{h:"« نحن بعدل جوزينا ... ننال إستحقاق ما فعلنا » ( لو ٢٣ : ٤١ ) ."},"لذلك فإنه لا يوجد فى داخل المتواضع ما يثيره ضد مَنْ أساء إليه . بل أنه أكثر من ذلك لا يشعر إطلاقاً أن هناك إساءة قد وجهت إليه . فربما النقيصة التى نسبت إليه هى حقيقة موجودة فيه . هكذا المتواضع ...",{h:"أما الذى يغضب ، فهو الذى يبرر نفسه . لذلك يثور على النقص الذى يُنسب إليه ."},"وفيما يثور يحتج على ما وُصف به من أخطاء ، ويرى أنها إهانات ومسبة لا يصح أن توجه إليه . ويدافع عن نفسه بكل قوة ، وينسب إلى مَنْ ( أساء ) إليه ،"],95:["الظلم والكذب والإفتراء والإعتداء على كرامة الأبرياء ... إلخ .. وعكس ذلك المتضع :","إننا عندما نغضب من غيرنا ، نكون قد نسينا خطايانا الخاصة ولم نعد نذكرها ، ولم نعد نتبكت عليها !","لأن الذى ينشغل بخطاياه ، ويضعها أمامه فى كل حين ، لا يفكر أبداً فى خطايا الآخرين ، سواء ضده أو ضد غيره . أما الذى ينشغل بخطايا الآخرين ، فواضح أنه لا يفكر فى خطاياه ... و يكون قد بَعُد عن إتضاع القلب .",{h:"يقول مار إسحق :"},"إذا ما بدأت أفكار التواضع تتحرك فيك ، متأسسة برحمة الله ، فمن قبل كل شىء يؤخذ منك الضجر ، ويُعطى لك إعتراف وشكر دائم ... وتجد ذاتك على الدوام مذنباً إلى كل أحد فى كل حين . ولن يظهر أن أحداً من الناس قد أساء إليك أبداً . بل فى جميع الشرور التى تحدث لك ، تجد أنك أنت ذاتك هو السبب فى حدوثها ، وكذلك فى كل ما يحدث لك من ضنك وحزن .","وباقتصار أقول لك الحق : مادمت لم تجد التواضع بعد ، فأكثر من كل شىء تتجرب بالضجر . والضجر يولد لك الملامات . وعلى الدوام تجد كثرة من الناس قد أساءوا إليك .","★ وقال : كمال الاتضاع هو إحتمال الوقائع الكاذبة بفرح .","★ قال شيخ : إن أردت أن تنجح فى إطفاء الغضب والرجز ، فاقتنِ الإتضاع ... لأن الاتضاع يحرق الشياطين .","★ وقال القديس سمعان العمودى :","الشرور هى مرتبطة بعضها بالبعض الآخر ، لأن البغضة هى من الغضب . والغضب من الكبرياء . والكبرياء من المجد الفارغ . والمجد الفارغ هو من قلة الإيمان ...","★ حقاً إن شيطان المجد الباطل إذا سار فى طريق ، يقول له شيطان الغضب : خذنى معك ."],96:["لذلك نقول : إذا أراد إنسان أن يقاوم الغضب ، عليه أن يقاوم محبة المديح والكرامة ، وكل مظاهر الكبرياء والمجد الباطل ومحبة العظمة . لأنه إن تمسك بأمثال هذه الأمور ، لن يستطيع أن يقاوم الغضب ، ولابد أنه سيثور لكرامته . وسوف يقول له شيطان المجد الباطل : كيف يعاملونك هكذا ؟! وكيف تقبل على نفسك هذا الوضع وهذا الكلام ؟! وكيف تسكت ولا تمحو الإهانة التى أصابتك ؟! ....","★ أخ سأل الأنبا بفنوتيوس قائلاً :","[ يا أبتاه ، لقد أتى بعض الإخوة إلى أبى ، ولست قادراً على السكنى معهم ] . فأجابه القديس [ لو كان فيك إتضاع ، لاستطعت السكنى مع الوحوش . فكم بالأحرى الإخوة ] .","★ وقال القديس أوغسطينوس :","عندما يصيب البعض أذى ، فهى الكبرياء التى تجعله يرغب فى الانتقام .. كما لو كانت عقوبة الغير يمكنها أن تنفعه بشىء ..! وكأنه يبحث عن علاجه فى معاقبة غيره !","★ وقال القديس باسيليوس : إن إعتياد التواضع يقطع الغضب من النفس ... بينما الكبرياء تقيم الغضب ...","★ قال شيخ : إياك والقساوة . فإن شيطاناً لا يخرج شيطاناً .","★ والآباء يرون أن المتواضع يفكر فى أبديته فلا يغضب ، متذكراً أنه سيقف أمام الله فى يوم الدينونة العظيم ليعطى حساباً عن أخطائه ، لذلك فهو لا يزيدها بالغضب ...","★ قال القديس دوروثيئوس :","مَنْ يضجر من شدائد هذا الدهر ، فهو جاهل بشدائد الدهر العتيد ، وإفتراق النفس عن الجسد ، والصعوبات التى ستنالها ، وكيف تنسى تصرف هذا الدهر .","فينبغى أن نذكر بلا نسيان الأعمال التى سندان عليها .","ويذكرنا هذا بقول القديس دياراخس : إننى فى ساعة الغضب أكون مهتماً بأبديتى أكثر من كرامتى !"],97:["إن علاج الغضب بالاتضاع موضوع واسع كثير التفاصيل . ولكى نفهمه بأكثر وضوح ، ننتقل إلى نقطة أخرى يتصف بها المتضعون ، وتساعدهم على عدم الغضب وهى : لوم النفس ...",{h:"لوم النفس"},"الإنسان الذى يلوم نفسه فى كل ما يحدث له ، لا يلوم غيره . وهكذا لا يجد سبباً للغضب .",{h:"فأنت تغضب لأنك تأتى باللوم على غيرك وتراه مستحقاً لغضبك ."},"أما إذا وصلت إلى فضيلة لوم النفس ، فإن الغضب يبعد عنك تلقائياً ، أقصد غضبك على الآخرين . وذلك لأنك تكون قد وجهت طاقتك الغضبية ، لتغضب بها على نفسك .","لأنك إن كنت براً فى عينى نفسك ، يظهر لك جميع مَنْ اصطدموا بك مخطئين . أما إذا كنت خاطئاً فى عينى نفسك ، فإنك تشعر أن الجميع أبر منك ، ولا ترى أن أحداً قد أساء إليك .","★ فى إحدى المرات زار البابا ثاوفيلس جبل نتريا المشهور بالمتوحدين وقال للأب الروحى لرهبان ذلك الجبل [ ما الذى اقتنتموه من الفضائل أيها الأب طول هذا الزمان ؟ ] فأجاب الشيخ المتوحد :",{h:"[ صدقنى يا أبى ، لا يوجد أفضل من أن يرجع الإنسان بالملامة على نفسه فى كل شىء ] .."},"★ ولكن كيف يمكن ممارسة هذه الفضيلة ، إذا إصطدم إنسان بآخر ، بحيث يكون صادقاً مع فكره أو ضميره ، ولا تكون ملامته لنفسه مجرد ملامة زائفة أو مصطنعة ، هو فى أعماقه لا يصدقها ؟",{h:"يشرح القديس دوروثيئوس هذا الأمر فيقول :"},"لماذا يحدث فى بعض الأحيان أن يسمع إنسان شتائم فلا يهتم بها ، وإنما"],98:["يحتملها غير مضطرب كما لو كان لم يسمعها ! بينما فى أوقات أخرى يضطرب فى الحال عند سماعها ؟","الناس يضطربون ... إما لأنهم ليسوا فى حالة داخلية حسنة . أو لأنهم يكرهون مَنْ يشتمهم . أو لأسباب أخرى . ولكن السبب الأساسى للاضطراب ، هو أننا لا نلوم أنفسنا .","وقد وضح القديس دوروثيئوس الأمر فى النقاط الآتية :",{h:"١ ـ إن وقعت ضيقة على المتواضع ، فبسرعة يلوم نفسه انه يستحقها . ولا يلوم أو يوبخ أحداً ."},"وهكذا يحتمل كل شىء يصيبه ، بسرعة ، وبدون إضطراب ، وبدون حزن ، وبهدوء كامل . وبهذا لا يغضب من أحد ، ولا يُغضب أحداً .",{h:"٢ ـ ربما يقول البعض : [ إذا أساء إلىَّ أخ ، وفحصت ذاتى فوجدت أننى لم أقدم له سبباً ، فكيف يمكننى أن ألوم نفسى ؟! ] ."},"فى الواقع إذا إختبر الإنسان نفسه فى خوف الله ، فإنه سيجد أنه كان السبب ، إما بكلمة ، أو بفعل ، أو بنظرة ...",{h:"٣ ـ وعلى أية الحالات إن ثبت أنه فى هذه المرة لم يعط سبباً ، فربما يكون قد أساء إليه فى وقت آخر بطريقة ما ، أو ربما يكون قد أساء إلى أخ آخر ( يحبه ) ."},"٤ ـ أو ربما يكون قد أساء إلى إنسان آخر ، وعليه أن يحتمل من أجل ذلك .",{h:"٥ ـ أو ربما يكون السبب من أجل خطية أخرى إرتكبها ."},"ولذلك فإنى أقول إنه إن فحص الإنسان نفسه بخوف الله ، وفى حزم يسأل ضميره ، فإنه لا يمكنه أن يفشل فى أن يجد نفسه مذنباً . وهكذا يلوم نفسه .","★ وقال القديس دوروثيئوس أيضاً :","فى كل مناسبة يجب أن ننظر إلى فوق ، سواء فعل البعض نحونا خيراً ، أو تحملنا الأذى من أى أحد . يجب أن ننظر إلى فوق ، ونشكر الله على كل ما يحدث لنا ... معتبرين كل الخير الذى يحدث لنا أنه من عمل تدبير الله الرحيم . وأن كل الشر هو نتيجة لخطايانا الخاصة ."],99:[{h:"قال الأنبا بيمن :"},"حينما يذهب الإنسان الذى يلوم نفسه ـ فى أى ضرر أو إهانة أو أية ضيقة أخرى تحل به ـ يعتبر نفسه مقدماً أنه يستحق كل شىء غير سار . ولهذا فإنه لا يضطرب أبداً ... فهل توجد حالة أكثر من هذه تخلصاً من الحزن ؟!",{h:"يقول القديس مرقس الناسك :"},"★ توجد فى العقل ثلاث مناطق : الطبيعية ، والفائقة للطبيعة ، والمضادة للطبيعة :","فعندما يدخل العقل فى منطقته الطبيعية ، يجد ذاته أنه هو سبب الأفكار الشريرة والآلام ، و يعترف لله بخطاياه .","ولكنه عندما يدخل فى المنطقة المضادة للطبيعة ، ينسى عدل الله ، ويحارب الناس ظاناً أن معاملتهم له غير لائقة .","أما عندما يرتفع إلى المنطقة الفائقة للطبيعة ، فإنه يجد فى ذاته ثمار الروح القدس التى أظهرها الرسول « محبة فرح سلام ... وما أشبه » ( غل ٥ : ٢٢ ، ٢٣ ) .","★ وقال أيضاً : يستحيل أن تغفر إساءات الناس من كل القلب ، بدون المعرفة الحقيقية . لأن هذه المعرفة تظهر لكل أحد أن ما يصيبه هو مستحق له .",{h:"قال القديس برصنوفيوس :"},"إن عرض للإخوة ـ إما عن نسيان أو سهو ـ فلم يعاملوك بما كان ينبغى أن يعاملوك به من الجميل ، قل [ لو شاء الله ذلك ، لكانوا قد فعلوه بى ] . وإن هم أتوك ، فاقبلهم بسرور وقل : [ إنى غير مستحق ] . ودع عنك تزكية نفسك . أما إن كنت تقول إنك حسناً قلت ، وحسناً فهمت ، فلا حسناً قلت ولا حسناً فهمت .",{h:"قال القديس الأنبا أنطونيوس :"},"ينبغى لمَنْ يُشتم ، أن يعتقد فى نفسه أنه هو السبب فى شتمه لسوء فعله . فيصبح الشاتم مذللاً له من الخارج ، فى الوقت الذى يكون هو فيه مذللاً لنفسه من الداخل . مثله فى ذلك داود النبى الذى منع أصحابه من قتل شاتمه ، إذ قال لهم"],100:["« دعوه فإن الرب جعله يشتمنى . دعوه حتى ينظر الرب ذلى و يرحمنى » ( ٢ صم ١٦ : ١١ ، ١٢ ) .",{h:"قال الأنبا إشعياء :"},"إذا شتمك إنسان ، فلا تجبه حتى يسكت . وفتش نفسك بخوف الله ، فلعلك تجد أن ما سمعته كائن فيك ، وأن العلة هى منك ...",{h:"وقال مار إسحق :"},"★ الذى يلوم نفسه على الدوام ، ويشجبها تحت كل إنسان ، ترتعب منه الشياطين ، ولا يقترب منه شيطان الغضب والحسد والحزن . ويمتلىء نفسه أمناً وسلاماً وحباً وفرحاً . ويصير محبوباً عند الله والملائكة والناس .",{h:"وأما الذى يزكى نفسه ، ويلوم قريبه ويدينه بقلبه ، فإن شيطان الغضب يسلمه إلى شيطان الحزن . وشيطان الحزن يسلمه إلى شيطان الاحتداد . وفى كل وقت يكون متكدراً متسجساً من اللذين لا يمدحونه ."},"★ وقال أيضاً : إذا قيل عنك ردىء ، وانحصر ضميرك ، ولو أنك تطوى يومين يومين صوماً بالمسوح والتوبة وكل أنواع الصلاة والدموع ، فلست تنعتق من ضنك الضمير ، ولا يعطيك الرب راحة ، إلى أن تضمر من كل قلبك أنك بالحقيقة مسىء ، باقتناع قلبى أنك بالحقيقة قد أسأت .","وهناك أمر نافع فى إحتمال الإساءة ، يمنع الغضب هو :",{h:"إعتبار المسىء كطبيب"},"يرى الآباء أن المتكلم عنا بالسوء ، ربما رأى فينا عيوباً لا نراها نحن ، فتحدث عنها ، كاشفاً لنا أخطاءنا لنتفاداها . فالأولى بنا أن نشكره ، بدلاً من الغضب عليه . إنه بمثابة مرآة روحية ، أو هو بمثابة طبيب . كما أنه يعالجنا من البر الذاتى ."],101:[{h:"قال القديس الأنبا أنطونيوس :"},"إفتكر فى شاتمك أنه قد عتقك من السبح الباطل إن إحتملته بمعرفة . وأنه قد أرسل لك على لسانه الدواء النافع .",{h:"وقال القديس الأنبا باخوميوس :"},"★ إذا تويخ أحدنا من أحد إخوانه ولم يقبل ، بل حقد عليه ، فقد إغتال الشياطين نفسه . ولست أقول هذا فقط . بل إن لم تعتبره كطبيب معالج ، فقد ظلمت نفسك ... فسبيلك أن تعترف بأنه كطبيب أرسله المسيح إليك .",{h:"فإن كنت تحب المرض ، فلا تحتج على البرء .."},"أما هذا الوجع الذى ظهر لك ، فدليل على ضعف نفسك . ولولا ذلك ما كنت تحزن من الدواء . لذلك ينبغى أن تعترف بالفضل للأخ ، لأنك به عرفت مرضك القاتل . فعليك أن تقبله مثل دواء شاف مرسل من عند يسوع المسيح .",{h:"وإن كنت لم تقتصر على عدم شكره فحسب ، بل خلقت حوله شكوكاً ، فقد كان الأحرى بك أن تقول ليسوع المسيح : لست أريد أن تشفينى ، ولا أشاء أن أقبل شيئاً من أدويتك ."},"★ وقال : الأحزان هى مكاوى يسوع ... فمكوى يسوع هو ذاك الذى يهينك . لأنه إن كان يشتمك ، إلاّ أنه يريحك ويخلصك من السبح الباطل ... فإن لم تحتمل شرب الأدوية ، تظلم نفسك وحدك . أما الأخ فلم يسبب لك ضرراً ما .",{h:"★ وقال القديس الأنبا أثناسيوس :"},"مَنْ يعاتبك ويوبخك على زلاتك ، أحببه مثل نفسك ، واتخذه لك صديقاً .",{h:"★ وقال شيخ :"},"إنه يجب على الإنسان الشكر لا التحقيق . وأن يعتقد فيهم ( أى فيمَنْ يتحدثون عن عيوبه ) أنهم أطباء يداوون جراح نفسه ، ذلك إن كان ذا ألم وإنفعال . أما إن كان عديم الإنفعال والألم : فيرى أنهم محسنون يسببون له ملك السموات .","★ إن مرض الغضب هو داخل نفسك . والذى أهانك لم يوجده ، إنما"],102:["كشفه لك . فاشكره ، وعالج نفسك من الداخل . لأن الإهانة التى أصابتك من الخارج ، لا تضرك بشىء ، ولا تؤثر على أبديتك .","هل تظن أنك ستعالج نفسك ، أو تنقى قلبك ، عن طريق أولئك الذين يقابلونك بالمديح والترحاب والكلام الطيب ، طالبين صلواتك ودعواتك وبركاتك ...؟! هل هؤلاء سيساعدونك على التخلص من أخطائك ؟!","وهل ستنال فضيلة الاحتمال عن طريق هؤلاء ، أو هل ستنال عن طريقهم فضيلة المغفرة للمسيئين ، وفضائل الوداعة والهدوء والاتضاع . أم تنال كل هذا عن طريق إنسان يسمح الله بأن ( ينكشك ) ، و يثيرك . ويبقى بعد هذا أن تستفيد روحياً من هذه الإثارة لصلاح نفسك ، بدلاً من أن تضر ذاتك وتزيد أخطائها بالغضب والصياح والنرفزة ... !",{h:"★ بل من أين تعلم أنك مصاب بداء النرفزة والغضب ، إن لم يقل لك أحد كلمة تغيظك وتتعبك ؟"},"إنه مثل ترمومتر صادق أظهر لك أن حرارتك مرتفعة جداً وتحتاج إلى علاج . هل تقذف بهذا الترمومتر وتكسره ، لأنه كان صريحاً معك . أما تشكر الله لأنه كشف لك داءك عن طريقه ؟...","إذا قال لك طبيب [ عندك وساخة فى المعدة ] ، هل تطبق على رقبة الطبيب وتصيح غاضباً [ هذا الطبيب قد شتمنى ] ، أم أنت تشكره على حسن تشخيصه وتسلك فى علاج نفسك ؟!",{h:"★ هذا الذى أغضبك ، شبهه أحد القديسين بتشبيه دقيق ."},"فقال : إذا أحضرت إناء فيه سائل كريه الرائحة جداً ، وعليه غطاء محكم . ثم يقوم أحد الناس بفتح الغطاء ، فتفوح الرائحة النتنة ... فهل الشخص الذى فتح الغطاء هو الذى وضع النتونة فى السائل ؟ أم السائل هو النتن ، وقد إنكشفت الآن نتانته . وتوجد فرصة للغسل والتنظيف تنقى الإناء مما هو فيه ...",{h:"★ إفرح إذن بالمرآة الروحية التى تكشف لك نفسك ."},"ولن تجد هذه المرآة الروحية عند المجاملين أو المتملقين . ولن تجدها عند كل"],103:["إنسان محب يراعى شعورك ويخشى أن يكلمك بصراحة ، إن كان يعرف مسبقاً أنك تغضب من الصراحة . إنما تجد هذه المرآة عند أولئك الذين يقولون لك رأيهم فيك ، دون مراعاة لشعورك ، غضبت أو لم تغضب ... فلا تحطم هذه المرآة ، وحاول أن تستفيد مما تكشفه لك ... هذا إذا كنت حقاً تحب القداسة ونقاوة القلب ...","هناك طريقة أخرى لمقاومة الغضب وهى الرد بالآيات :",{h:"الرد بالآيات"},{h:"★ إحفظ الآيات الخاصة بذم الغضب ، وردّدها ، ولتكن موضع تأملاتك ، وتذكرها كلما حوربت بالغضب ."},"وسنذكر لك هنا أمثلة من هذه الآيات ، هى :","١ ـ « غضب الإنسان لا يصنع بر الله » ( يع ١ : ٢٠ ) .","٢ ـ « الغضب يستقر فى حضن الجهال » ( جا ٧ : ٩ ) .","٣ ـ « ملعون غضبهما فإنه شديد ، وسخطهما فإنه قاس » ( تك ٤٩ : ٤٦ ) .","٤ ـ « لا تستصحب غضوباً ، ومع رجل ساخط لا تجىء » ( أم ٢٢ : ٢٤ )","٥ ـ « الرجل الغضوب يهيج الخصام ، السخوط كثير المعاصى » ( أم ٢٩ : ٢٢ ) .","٦ ـ « الحكماء يصرفون الغضب » ( أم ٢٩ : ٨ ) .","٧ ـ « لينزع من بينكم كل مرارة وسخط وغضب وصياح » ( أف ٤ : ٣١ ) .","٨ ـ « الغضب قساوة ... » ( أم ٢٧ : ٤ ) .","٩ ـ « لا تتغاضبوا فى الطريق » ( تك ٤٥ : ٢٤ ) .","١٠ ـ « الحجر ثقيل ، والرمل ثقيل ، وغضب الجاهل أثقل منهما كليهما » ( أم ٢٧ : ٣ ) .","★ كذلك إحفظ بعض الآيات الخاصة بالوداعة والهدوء وردّدها .","( انظر كتابنا عن الهدوء ، والوداعة ضمن ثمار الروح ) ."],104:["★ وقد أورد القديس مار أوغريس آيات عديدة عن الرد على الغضب بالآيات ، نذكر أمثلة منها لمجرد معرفة المنهج :","قال : الفكر الذى ما يشاء أن يكف عن الغضب إذا تاب إليه أخوه ، يرد عليه بالآيــة « فإن تاب فاغفر له » ( لو ١٧ : ٣ ) . والذى لا يشاء أن يصالح أخاه ، ويختلق لذلك حججاً ، يرد عليه بقول الرسول : « لا تغرب الشمس على غيظكم » ( أف ٤ : ٢٦ ) . والذى يغضب على شخص إقترض منه وتواتى فى إعادة ما إقترضه ، يرد عليه بقوله : « وإن كان قد ظلمك فى شىء ، أو كان لك عليه دين ، فاحسب ذلك علىَّ » ( فل ١٨ ) . والذى يفرح بزلة أعدائه ، يرد عليه بقوله « بكاء مع الباكين » ( رو ١٢ : ١٥ ) .",{h:"★ وبمنهج مار أوغريس يمكن للإنسان أن يعرف الأسباب التى تدفعه إلى الغضب ، ويعرف الآيات التى ترد عليها ويستخدمها ."},"★ كذلك يمكنه إستخدام الآيات الخاصة بالسلام ومنها قول القديس يعقوب الرسول :","« مَنْ هو حكيم وعالم بينكم ، فليرِ أعماله بالتصرف الحسن فى وداعة الحكمة . ولكن إن كانت لكم غيرة مُرّة وتحزب فى قلوبكم ، فلا تفتخروا وتكذبوا على الحق . ليست هذه الحكمة نازلة من فوق ، بل هى أرضية نفسانية شيطانية . لأنه حيث الغيرة والتحزب ، هناك التشويش وكل أمر ردىء »",{h:"« أما الحكمة التى من فوق ، فهى أولاً طاهرة ، ثم مسالمة مترفقة مذعنة ، مملوءة رحمة وأثماراً صالحة .. » ."},"« وثمر البر يزرع فى السلام ، من الذين يفعلون السلام » ( يع ٣ : ٣ ـ ١٨ ) .","طريقة أخرى لمقاومة الغضب وهى الإبطاء فى الغضب .",{h:"الإبطاء فى الغضب"},"الغضب هو حركة سريعة ، تثار فتندفع . والإبطاء يمنعها ."],105:["الإبطاء فى الغضب يعطى فرصة للتحقق ، ولتهدئة النفس من الداخل ، والتحكم فى الأعصاب وفى اللسان .","ولذلك يقول معلمنا يعقوب الرسول « ليكن كل إنسان مسرعاً فى الاستماع ، مبطئاً فى التكلم ، مبطئاً فى الغضب . لأن غضب الإنسان لا يصنع برّ الله » ( يع ١ : ١٩ ، ٢٠ ) .","وهذا أيضاً يقول سليمان الحكيم فى سفر الأمثال :",{h:"« تعقل الإنسان يبطىء غضبه » ( أم ١٩ : ١١ ) ."},"فالإنسان العاقل لا يسلّم نفسه بسرعة إلى إنفعال الغضب ، إنما يتناول الأمر بكل هدوء ورزانة ، وموضوعية ، و يدرسه ، و يفكر فى نتائجه ، وفى أسلم الحلول لمعالجته كما يتحقق هل الكلام الذى سمعه وأثاره هو حق أو باطل . وهكذا يكون بطيئاً فى غضبه . وقد قال الحكيم :",{h:"« لا تسرع بروحك إلى الغضب ، لأن الغضب يستقر فى حضن الجهال » ( جا ٧ : ٩ ) ."},"وبهذا رأى أن الإسراع فى الغضب ، يؤدى إلى جهالة . وهذا واقع عملى . فكثيراً ما نرى أشخاصاً يغضبون بسرعة ، ثم يرجعون فيندمون على كل ما فعلوه ، و يرونه إندفاعاً غير حكيم ، ينقصه التروى والفحص . و يقول الواحد منهم عن غضبه [ لم أكن فى عقلى ] ...!",{h:"ومن الجميل أن الله قد وُصف بأنه بطىء الغضب :"},"قال عنه يونان النبى « لأنى علمت أنك إله رؤوف ورحيم ، بطىء الغضب وكثير الرحمة » ( يون ٤ : ٢ ) . وقيل عنه فى سفر الخروج « الرب إله رحيم ورؤوف ، بطىء الغضب وكثير الإحسان ... غافر الإثم والمعصية والخطية » ( خر ٣٤ : ٦ ، ٧ ) . ونلاحظ هنا بأن صفة بطىء الغضب مقترنة بصفات الرحمة والرأفة والمغفرة . ونفس هذه الصفات وردت فى سفر يوئيل النبى إذ يقول « إرجعوا إلى الرب إلهكم ، لأنه رؤوف رحيم ، بطىء الغضب ، وكثير الرأفة » ( يوء ٢ : ١٣ ) ."],106:["وسليمان الحكيم يمتدح الإبطاء فى الغضب ، ويرى أنه « يسكّن الخصام » ( أم ١٥ : ١٨ ) وأنه يدل على الحكمة فيقول :",{h:"« بطىء الغضب ، كثير الفهم » ( أم ١٤ : ٢٩ ) ."},"إنه يفهم مضار الغضب ونتائجه السيئة ، ويفهم أنه لا يصنع بر الله ، ولا يقيم سلاماً مع الناس ، بل يضرب الشخص الغضوب نفسه صحياً ونفسياً ، وروحياً إذ يوقعه فى خطايا كثيرة ، ويجعله عثرة لغيره . لذلك إبطاؤه فى الغضب ، يدل على فهمه ...",{h:"والمعروف أن الإبطاء فى الغضب يمنعه أو يصرفه ."},"وذلك لأن الإبطاء فى الغضب ، يجعل الإنسان يجتاز مرحلة الإنفعال ، و يدخل فى دائرة التعقل ، وأيضاً الصبر . وبهذا يتبدد الدافع إلى الغضب . وربما بسبب هذا الإبطاء يهدأ الطرف الآخر ، وتبطل إثارته .",{h:"آفة الغضب السرعة ، والتصرف باندفاع بدون تفكير ."},"فلو أنك أبطأت ، وبدأت تفكر ، ولم تترك نفسك فريسة للإندفاع ، فلابد أنك ستستطيع أن تهدىء نفسك ، وتحتفظ بأعصابك . وقد مدح سليمان الحكيم هذا الأمر فقال « البطىء الغضب خير من الجبار . ومالك روحه خير ممّنْ يأخذ مدينة » ( أم ١٦ : ٣٢ ) .",{h:"لذلك قيل إن تلفظ كلمة فى غضبك ، فكّر فى نتائجها ."},"المعروف أن الكلمات فى حالة الغضب ، تخرج بلا ضابط ، ولذلك كثيراً ما تكون خاطئة جداً ، وتسبب مشاكل ، كما تكون موضع نقد . أما أنت ، فلا تندفع بالكلام ، وتباطأ ريثما تفهم جيداً : ماذا ينبغى أن تفعل . واعلم أن الإبطاء فى الغضب يحمل فضيلة ضبط النفس .",{h:"إن لم تعرف كيف تتصرف : إسكت ."},"فالسكوت فى حالة الغضب فضيلة . لأن تبادل الكلمات الشديدة ، يشعل الغضب بالأكثر من الطرفين . والكلمة الإنفعالية التى هى نتيجة لإساءة سابقة ، تصبح مبرراً لإهانة لاحقة . وتزيد الجو توتراً . على أن هناك وسيلة تصلح أحياناً أكثر من السكوت ، وهى الجواب اللين ."],107:[{h:"الجواب اللين"},"يقول الوحى الإلهى فى سفر الأمثال ( أم ١٥ : ١ ) .",{h:"« الجواب اللين يصرف الغضب . والكلام الموجع يهيج السخط » ."},"إذا إحتدم الغضب ، فإنه لا يعالج بالكلمات الموجعة ، لأنه كما قال القديسون [ النار لا تطفىء ناراً . لكن يطفئها الماء ] . ولذلك فإن الكلمة اللطيفة قد تكون أقدر على إطفاء نار الغضب .",{h:"انظر إلى الأب فى قصة الابن الضال ، وكيف تعامل مع غضب ابنه الأكبر ..."},"كان كلام هذا الابن شديداً على أخيه الصغير وعلى أبيه أيضاً ، وقد رفض أن يشترك فى الفرح برجوع أخيه « غضب ولم يرد أن يدخل » ( لو ١٥ : ٢٨ ) . واتهم أخاه بأنه أنفق معيشته مع الزوانى ، كما اتهم أباه بالبخل ، قائلاً له « ها أنا أخدمك سنين هذا عددها ... وجدياً لم تعطنى لأفرح مع أصدقائى » ... ومع كل هذه الإتهامات وغيرها ، كلمه أبوه بكل رقة قائلاً له « يا ابنى ، أنت معى كل حين . وكل ما لى هو لك » .","★ يقدم مار إسحق الكلمة اللينة كعلاج للغضب ، فيقول :","[ الكلمة اللينة تحطم الأعضاء . وشرارة الغضب ـ إن نفخت فيها ـ أثارت الحنق ، وإن تلافيتها بحب وسلام تطفئها . وحريتك مسلطة على الأمرين . ومن داخلك يخرج الاثنان : أعنى الكلام الطيب والسلام ، أو كلام التشامخ والغضب ] .","★ تذكر الكلام اللين اللطيف الذى تكلمت به ابيجايل مع داود وهو فى عنفوان غضبه ، وكيف إستطاعت أن تهدئه وتعالجه من شهوة الإنتقام وهو يريد أن يقتل زوجها . بينما الكلام الموجع الذى قاله ذلك الزوج ، كان سبباً فى إثارة داود ( ١ صم ٢٥ ) .",{h:"★ ربما يكون الجواب اللين ، فى كلمة فكاهة أحياناً ."}],108:["تُظهر أنه لا غضب ولا بغضة فى قلبك ، وتبسط جواً من المرح يزول فيه الغضب . وينطبق عليها قول الكتاب « وللضحك وقت » ( جا ٣ : ٤ ) . ولكن ليكن ذلك بروح مودة ، لئلا ضحكك يثير الطرف الآخر ...",{h:"★ العجيب أن كثيراً من أولاد الله ، تنقصهم البشاشة أحياناً !"},"ولا يضعون أمامهم سوى قول الكتاب « بكآبة الوجه يصلح القلب » ( جا ٧ : ٣ ) . ولذلك ترى وجوههم جادة باستمرار ، وملامحهم صارمة عابسة . فهؤلاء إن صادفتهم مشكلة غضب ، يزيدونها حدّة بهذه الجدية فتشتعل . بينما يكون الحل فى إبتسامة لطيفة وكلمة رقيقة ، والتنازل عن كآبة الوجه ولو إلى ليحظات لإصلاح علاقتهم مع إخوتهم .",{h:"★ لذلك كثيراً ما تكون البشاشة علاجاً للغضب ."},"الشخص البشوش يستطيع أن يستوعب الموقف فى لطف ، و يرد بملامح مبتسمة مريحة ، وبوجه مبتسم ، ولا يستطيع الغضوب أن يستمر فى غضبه أمامه ، بل قد يجبره على الابتسام بروح الدعابة والكلمة الطيبة فينفك غضبه . هنا ونقول : أليس بعض من أهل العالم أنجح من كثير من المتدينين المتزمتين ، الذين يرفضون أن يبتسموا فى الأوقات التى يلزم فيها الإبتسام !!",{h:"★ وقد يكون الجواب اللين هو كلمة إعتذار أو إتضاع ."},"سرعان ما يتلاشى معها غضب الطرف الآخر ، ولا يجد أمامه شيئاً آخر يقوله ...","★ أو قد تكون كلمة مديح أو إطراء ، تظهر تقديرك له ، ويخفى معها شعوره بأنك أهنته أو جرحته ...","والسيد المسيح يقدم الصورة المثلى للكلمة اللينة فى التعامل مع الإهانة بل ومع اللعنة ، فيقول :",{h:"« باركوا لاعنيكم ، أحسنوا إلى مبغضيكم » ( متى ٥ : ٤٤ ) ."},"وعلى هذا النهج يقول القديس بطرس الرسول « كونوا جميعاً ... ذوى محبة أخوية ، مشفقين لطفاء ، غير مجازين عن شرٍ بشرٍ ، أو عن شتيمة بشتيمة ، بل بالعكس مباركين .. عالمين أنكم لهذا دعيتم » ( ١ بط ٣ : ٨ ، ٩ ) ."],109:["ومع كل ذلك فإن علاج الغضب يحتاج إلى حكمة :",{h:"الحكمة"},{h:"ربما لا يصلح أسلوب واحد للتهدئة مع جميع أنواع الغضوبين ، ومع مختلف الحالات والأسباب :"},"فمع إنسان قد يصلح السكوت ، إن كانت كل كلمة يمكن أن تثيره بالأكثر . ومع آخر ربما يثيره صمتك ، ويحتاج إلى كلمة تهدئة .",{h:"والأمر يحتاج إلى حكمة : متى تتكلم ؟ ومتى تصمت ؟"},"وهنا نجد الحكيم يضع أمامنا تصرفين مختلفين تماماً للتعامل مع نوعيات مختلفة من الناس فيقول :","لا تجاوب الجاهل حسب حماقته ، لئلا تعدله أنت ( أم ٢٦ : ٤ ) .","جاوب الجاهل حسب حماقته ، لئلا يكون حكيماً فى عينى نفسه ( أم ٢٦ : ٥ ) .","إذن حسب ظروفه الحالة تتكلم أو تصمت ، وكذلك حسب ما تتوقعه من نتائج . المسألة تتوقف على الحكمة والإفراز وتقدير الظروف .",{h:"انظر إلى الشخص الذى أمامك : ماذا يريحه ويهدئه ."},"إن وجدت أن الاعتذار إليه يهدىء غضبه ويريحه ، فلا مانع ، إعتذر إليه . وإن رأيت أنه سيتخذ الاعتذار إثباتاً لإساءتك إليه ، فتزيد ثورته من أجل كرامته ، تكون الحكمة إذن فى تبرير الموقف ، وتوضيح تقديرك لكرامته .",{h:"تذكر نتائج الغضب السيئة"},{h:"ولعل من أهم هذه النتائج : هزيمة الإنسان من الداخل ، وعثرته للناس فى الخارج ، وخسارته للآخرين ، بل خسارته لصحته أيضاً ولروحياته وأبديته ، مع تعقد الأمور بالأزيد نتيجة لهذا الغضب ."}],110:["★ قال مار إسحق : عندما تكون مغتاظاً من نكد ، انظر بدقة إلى الأعداء الصعبة ، المتحركة فيك من الداخل ، ومن الخارج . فمن الداخل الآلام المرة ، والإحتداد والحقد والغضب والشر ، التى تهاجم فضائل نفسك وتفسدها ، وتخييها من حلاوة الحب الإلهى . ومن الخارج : الناس الأشرار الذين يخجلونك ، و يعيرون بك أصدقاءك .","بينما حينما تكون حلواً بشوشاً طيباً ، انظر داخلك كيف أن بنى بيتك يفرحون بك ويفرحونك ، أعنى السلام ، الهدوء ، الحب ، الود ، نور المعرفة ، الرجاء بالله .. ( انظر هذا الكتاب من ص ٣٣ إلى ص ٣٨ ) .",{h:"فإن اقتنع الإنسان بأن الغضب سيضره من نواح متعددة ، حينئذ يجد دافعاً داخلياً يمنعه من الغضب أو من إكماله ."},"وهنا نتعرض لنقطة أخرى فى علاج الغضب وهى :",{h:"عدم التدرج إلى أسوأ"},{h:"فى كل مرحلة تصل إليها فى غضبك ، إحترس من أن تتمادى وتصل إلى ما هو أسوأ ."},"فإن دخل الغضب إلى فكرك ، إحترس من أن يصل إلى قلبك ، ويربك مشاعرك تجاه الآخرين . وإن وصل إلى قلبك إحترس من أن يصل إلى ملامحك ، فيكفهر وجهك وتظهر بأسلوب غير مشرف . وإن ساد الغضب على ملامحك ، إحترس من أن يسود على لسانك ، فتتلفظ بألفاظ قاسية . وإن أدرك الغضب لسانك ، إجعله أن يقف عند حد فى أخطاء اللسان فهى متعددة . وإن سقطت فى أخطاء اللسان ، إحترس من أن يصل الغضب إلى يدك ، فتقع فى الإيذاء والإعتداء . وإن وصلت إلى ذلك ، إحترس من القسوة بكل ألوانها ...",{h:"ضع للغضب حدوداً فى كل مرحلة :"},{h:"لا تجعله يصل إلى مستوى الحقد والكراهية ."}],111:["إحترس من أن يسوّد قلبك من جهة أشخاص معينين ، أو أن تترسب أمور فى أعماق نفسك ، كلما تذكرها تغضب ، وكلما يأتى ذكرها تحتد","إحترس من أن تنطبع مشاعر الغضب فى عقلك الباطن ، وتصبح مصدراً لأحلام فيها غضب وقسوة وعنف وحقد ، واستمرارية لحالتك الروحية المريضة .",{h:"إحترس أيضاً من أن يلد الغضب شروراً أخرى ."},"و يكون هذا الغضب مقدمة ومصدراً لخطايا عديدة ، شرحناه فى حديثنا عن الغضب كخطية مركبة منفرة ( من ص ٢٦ إلى ٣١ ) .",{h:"نقاوة القلب وليس الإنطواء"},{h:"البعض يظن أن علاج الغضب يكون بالوحدة والهروب من المجتمع ، وفى الواقع إن هذا نوع من الإنطواء وليس الوحدة ."},"الوحدة يلجأ إليها إنسان ناجع فى حياته الإجتماعية ، يحب الناس ويحبونه . ولكنه يحب الوحدة بالأكثر لأنها تعطيه فرصة للتأمل والإنشغال بالله والصلاة والقراءة . وليس لأنه عاجز عن التكيف مع المجتمع المحيط به ، وليس كراهية للناس وتعقد القلب من جهتهم ...",{h:"فالشخص الغضوب إن ذهب إلى الوحدة ، يرافقه غضبه فيها !"},"★ قال شيخ : [ إذا كان وجع يقاتلك فى موضع ما ، وتترك ذلك الموضع ظناً منك أنه يخف عنك دون أن تقاتله ، فاعلم أنك إذا لم تغلبه حيث قاتلك ، فإنه سوف يسبقك إلى كل موضع تمضى إليه ] .",'[ لأننى أعرف أن أخاً كان ساكناً فى دير ، وكان مداوماً على السكوت ، إلاّ أنه كان كل يوم يتحرك من وجع الغضب . فقال فى نفسه " أمضى وأسكن وحدى فى قلاية . وحيث إنه ليس هناك أحد ساكناً سواى ، فسوف أهدأ ويخف عنى وجع الغضب " . فخرج وسكن وحده فى مغارة . وفى أحد الأيام ملأ القلة ماء ووضعها'],112:['على الأرض . ولوقتها تدحرجت وإنسكب ما فيها . فأخذها وملأها مرة ثانية ووضعها على الأرض فانسكبت كذلك ، فملأها دفعة ثالثة فانسكبت أيضاً . فغضب وأمسكها وضرب بها الأرض فكسرها . فلما رجع إلى قلبه ، علم أن الشياطين قد سخروا به . فقال فى نفسه " هوذا قد إنغلبت وأنا فى وحدتى كذلك . فلأذهب إلى الدير ، لأنه فى كل موضع يحتاج الإنسان إلى جهاد وصبر ومعونة من الله " . ثم قام ورجع إلى موضعه ] .',"إنسان راهب من شدة التجارب والمحن المتكاثرة عليه ، قال [ لنمض من ههنا إلى موضع آخر ] . فبينما هو يلبس حذاءه ، أبصر الشيطان فى زى رجل مقابله يلبس الحذاء أيضاً . فقال له [ إلى أين أنت ماضٍ كذلك ؟ ] . فأجاب قائلاً [ إلى الموضع الذى أنت ماضٍ إليه . لأنى أنا من أجلك مقيم فى هذا الموضع . فإن أردت الإنتقال من ههنا ، فسوف انتقل بدورى . لأنى أنا ملازم لك حيثما سكنت ] ..!","★ من أجل هذا كان الآباء يدربون أبناءهم الروحيين على الوداعة والتواضع والاحتمال وعدم الغضب ، قبل أن يسمحوا لهم بالإنفراد فى الوحدة .",{h:"إذن يجب على الإنسان أن يهدىء قلبه من الداخل ، وينقى قلبه من الغضب والغيظ . ولا ينفعه أن ينطوى على ذاته ، وقلبه ساخط نافر مملوء بمشاعر خاطئة ."},"نقاوة القلب هذه هى العلاج الحقيقى لمشكلة الغضب ، مادام السبب هو داخلنا ، أعنى عدم الاحتمال ، وعدم المحبة ، وعدم المغفرة .","فلنهتم إذن بهذه الأمور ، لنعالج نفوسنا من الغضب .",{h:"المحبة والإحسان والهدايا"},"إن أحببنا الناس ، أمكننا أن نحتملهم ، لأن المحبة « تحتمل كل شىء » ( ١ كو ١٣ : ٦ ) ."],113:[{h:"قال القديس مار أوغريس :"},"الغضب والكراهية يزيدان تهيج القلب . والرحمة والوداعة تهدئانه .","الوديع ـ ولو صنعوا به الشر ـ لا يتخلى عن المحبة ، لأنه من أجلها يتمهل و يصبر بصلاح .",{h:"فإن كان فعل المحبة هو طول الروح ، فهى غريبة عن الغضب . لأن الغضب يقيم البغضة والرجز ، والمحبة تبطل الثلاثة ."},"« مياه كثيرة لا تستطيع أن تطفىء المحبة » ( نش ٨ : ٧ ) .","إذاً أردت أن تدوس وجع القلب والغضب ، اقتنِ طول الروح والمحبة فى قلبك ، وإلبس فرح البساطة .",{h:"ولا تجعل فرحك يكون حزناً لرفيقك ."},"وقال القديس مار أوغريس أيضاً :","الذى يمسك الغضب بالتمهل ، والحزن بالمحبة ، فهو يغلب وحشين رديئين بهاتين الفضيلتين .","وقال : الهدايا تبطل السجس . ويقنعك يعقوب حين تلقى عيسو بالهدايا عند خروجه للملاقاته ومعه أربعمائة رجلاً ( تك ٣٣ : ١ ) .","★ وفى موضع الهدايا ومعالجتها للغضب ، يقول الكتاب :",{h:"« الهدية فى الخفاء تفئأ الغضب » ( أم ٢١ : ١٤ ) ."},"ولكن موضوع الهدايا هذا ، يحتاج إلى حكمة . لأنها فى حالة قبولها يمكن أن تدل على محبة وتعالج الغضب . أما إن كان قلب إنسان مملوءاً بالسخط ، فهناك إحتمال أنه قد يرفض مثل هذه الهدية ، فيسوء الوضع ويزداد الغضب . فيجب أن يكون مقدم الهدية حكيماً ، ويدرس الموضوع برؤية . فقد يقول الطرف الآخر [ يصالحنى أولاً ، ويعالج أسباب غضبى . ثم أقبل منه الهدية ] .",{h:"★ أما مقابلة الإساءة بالإحسان ، فإنها مبدأ روحى ."},"وفى ذلك يقول الكتاب « لا يغلبنك الشر ، بل إغلب الشر بالخير » ويقول"],114:["أيضاً « إن جاع عدوك فاطعمه ، وإن عطش فاسقه » ( رو ١٢ : ٢٠ ، ٢١ ) .","ويقول السيد فى العظة على الجبل « أحسنوا إلى مبغضيكم » ( مت ٥ : ٤٤ ) . إن مثل هذا الإحسان يستطيع أن ينزع البغضة من القلب ، وبالأولى الغضب .","★ قال القديس الأنبا بيمن : الشر لا يُغلب بالشر . ولكن إن أساء أحد إليك ، فاحسن أنت إليه . فإنك باحسانك إليه تستأصل الشر . لأنه ينبغى ألاّ نكافىء شراً بشر .","فى حالة غضبك من إنسان ، ضع فى قلبك قول الكتاب :",{h:"« رابح النفوس حكيم » ( أم ١١ : ٣٠ ) ."},"وقل لنفسك [ لماذا أخسر الناس ؟! وهل هذه حكمة أن أخسرهم ؟! ] . وتذكر قول بولس الرسول « فإنى إذ كنت حراً من الجميع ، استعبدت نفسى للجميع ، لأربح الكثيرين ... صرت للضعفاء كضعيف لأربح الضعفاء . صرت للكل كل شىء ، لأخلص على كل حال قوماً » ( ١ كو ٩ : ١٩ ـ ٢٢ ) .",{h:"التفاهم والعتاب"},"وهذه القاعدة وضعها السيد المسيح نفسه ، وتعامل بها مع الكتبة والفريسيين الذين كانوا يقابلون تصرفاته بغضب .",{h:"★ فكان السيد يستخدم معهم طريقة الاقناع ، ومناقشة الفكر ."},"كان يغضبون عليه مثلاً ، لأنه يقوم ببعض المعجزات فى يوم سبت . فكان يرد على نقدهم له ، ليس بالغضب ، وإنما بالإقناع . فيقول لهم إن سقط خروف فى يوم سبت ، ألا نمسكه ونقيمه ( مت ١٢ : ١١ ) . ويقول لهم عن ختان الطفل فى اليوم الثامن من ميلاده ، وربما يكون يوم سبت إن « الكهنة يدنسون السبت » وهم أبرياء ( مت ١٢ : ٥ ) . ويقول لهم إن الله يريد رحمة لا ذبيحة . كلها طرق إقناع ...",{h:"★ لم يكن يرد على إنتقاداتهم بالغضب ، إنما بالإقناع ."}],115:["وهكذا عندما غضبوا لصياح الأطفال فى يوم دخوله أورشليم ، أقنعهم بقوله إن الكتاب يقول « من أفواه الأطفال والرضعان هيأت سبحاً » ( مت ٢١ : ١٦ ) .","وبالمثل رد على إنتقاداتهم بأن تلاميذه يأكلون بأيد غير مغسولة ، رد أيضاً بالإقناع بقوله « ليس ما يدخل الفم ينجس الإنسان ، بل ما يخرج من الفم هذا ينجس الإنسان » ( مت ١٥ : ١١ ) .",{h:"إن التفاهم أسلوب جميل يشرح الأمور ، ويزيل الغضب من جذوره ، من أسبابه ، إن كانت قد فُهمت خطأً ."},"★ وموضوع العتاب وضع السيد المسيح أسسه كما ورد فى قوله « إذهب وعاتبه فيما بينك وبينه » ( مت ١٨ : ١٥ ) .",{h:"التصريف وليس الترسيب"},"هناك طريقتان للتعامل مع الغضب ، وفيهما يبدو الإنسان هادئاً . وهما طريقة التصريف ، وطريقة الترسيب .",{h:"★ أما التصريف ، فمعناه أنه قد صرف الغضب تماماً من أعماق قلبه ، ولم يعد فى داخله أى شىء ضد أخيه ."},"ولا يتم هذا إلاّ عن طريق المغفرة الكاملة ، التى تنسى الإساءة ، بل ربما تلتمس العذر للمسىء ... أو عن طريق التواضع العميق ، الذى يشعر فيه الإنسان أنه هو المخطىء ، وهو السبب فى كل ما حدث . وبهذا لا يوجد غضب فى القلب على الإطلاق .","وعن تصريف الغضب ، قال الرسول « لا تنتقموا لأنفسكم أيها الأحباء ، بل اعطوا مكاناً للغضب » ( رو ١٢ : ١٩ ) أى إفسحوا له مكاناً ينصرف منه .. ولا تكتموه ...","وعن هذا التصريف أيضاً قال الكتاب :",{h:"« أما الحكماء ، فيصرفون الغضب » ( أم ٢٩ : ٨ ) ."}],116:["وبتصريف الغضب يصبح القلب صافياً صفاء حقيقياً ، من الداخل تماماً كما من الخارج . ولا يكون هناك أى شىء يشوب العلاقات مع مَنْ كان سبباً للغضب ، بل يعود الود كما كان ...",{h:"على أن هذا التصرف قد يحدث أحياناً بالتدريج :"},"مثل جرح قد نظفته تماماً ، وشفى والتأم . ولم يعد يؤلمك فى شىء . ولكن موضعه لايزال حساساً ، بحيث إن أصابته أية صدمة تكون أكثر تأثيراً عليه ، وأكثر إيلاماً ... ولكن بالوقت يزول الألم تماماً تماماً ، و يصبح موضع الجرح كأى موضع آخر فى الجسم من حيث التعرض للألم ....",{h:"★ أما الترسيب ، فهو صفاء خارجى ، مع وجود الغضب كامناً فى أعماق النفس ، ثابتاً فى الفكر !"},"مثال ذلك زجاجة دواء مكتوب عليها [ رج الزجاجة قبل الاستعمال ] . يكون فيها الدواء صافياً ورائقاً من فوق ، مع وجود مواد مترسبة فى القاع . بحيث إذا رججت الزجاجة ، يتعكر السائل الرائق كله ، إذ يختلط بما رسب فى القاع ...","فقد يحدث أن إنساناً يهدىء نفسه من الإنفعال الظاهرى . وفى قلبه هو غير مقتنع بما حدث له . هو من أجل الله ، ومن أجل الوصية ، قد سكت . ولكن كلاماً فى داخله لايزال موجوداً . وربما يكون قد هدأ قلبه أيضاً بأسباب كثيرة ، ونسى الموضوع ...",{h:"ولكن يحدث أنه إذا تكررت الإساءة ، يغضب ليس بسبب هذه الإساءة الجديدة ، إنما بسبب القديمة أيضاً ."},"ذلك لأن الإساءة القديمة لم تنتهِ بعد ، لاتزال موجودة فى قلبه ، كامنة ومترسبة ، لم يعطها مكاناً لتنصرف . إنما إستبقاها وغطى عليها بصفاء ظاهرى ، وبنسيان مؤقت ...","ماذا نقول إذن عن هدوئه وصفائه السابقين ؟ وكيف نحلل الموقف ؟ وما حكمنا على الطريقة التى اتخذها فى التعامل مع الغضب ؟ وما سبب الترسيب فى هذه الحالة ؟ نقول :"],117:[{h:"إنه حاول معالجة نتائج غضبه ، ولم يعالج أسبابه .."},"فلم يسمح للغضب أن تنتج عنه حدّة أو خصومة ، أو محاولة لرد الشر بالشر .. أما أسباب الغضب فظلت باقية فى أعماق نفسه تحتاج إلى تصريف .","وقد تعرض القديس دوروثيئوس لهذه النقطة فى الجزء الأخير من حديثه عن رد الشر بالشر .","هذا ننصحك بتصريف غضبك ، وليس بمجرد ترسيبه .",{h:"لأن الترسيب كثيراً ما يؤثر على المحبة ، وعلى نقاوة القلب . وقد يبعد سلبيات الغضب ، بينما لا توجد له إيجابيات المحبة ."},"فأنت فيه لا تنتقم ولا تثور ، ولا تخطىء بلسانك ، وقد تتحاشى أيضاً أن تخطىء بفكرك .. ومع ذلك فإن فى قلبك جرحاً لم يندمل بعد ... تتجاهله فترة . ولكن إن تذكرته ، يعود الألم ، سواء أظهرته أو أخفيته ...! والمفروض أن يتم تصريف لكل هذه المشاعر المترسبة ، و يصل القلب إلى حالته الطبيعية ، التى تقابل فيها الطرف الآخر بالود والحب ، وكأنه لم يحدث بينكما أى شىء يعكر هذه المودة .",{h:"معالجة الغضب بست فضائل"},{h:"★ بفضيلة المغفرة :"},"وفى ذلك يقول القديس أوغسطينوس : [ فلا يستبقِ أحد ضد نفسه شيئاً ، برفضه أن يغفر ، لئلا يتبقى ذلك ضده عندما يصلى ] .","و يقول فى تعليقه على ( لو ١٧ : ٢٣ ) « وإن أخطأ إليك سبع مرات فى اليوم ... فاغفر له » يقصد مهما أخطأ . لئلا يخطىء إليك ثمانى مرات ، فلا تريد أن تغفر !! ما معنى إذن سبع مرات ؟ معناها ( دائماً ) ، مهما أخطأ وتاب ...","حقاً إن المغفرة الحقيقية تقتلع كل جذور الغضب من القلب ."],118:["وبأية فضيلة أخرى نقتلع الغضب ؟",{h:"★ بفضيلة الزهد :"},"لأن الزاهد فى العالم لا يجد سبباً يجعله يغضب . إنه قد إرتفع فوق مستوى الكرامة والحقوق ، وارتفع فوق كل ما يتنازع حوله الناس فى العالم .","يقول مار اسحق فى ذلك :","[ الصبر الإختيارى على الظلم يطهر القلب . والصبر يحدث من رفض الإنسان لهذا العالم . لأنه إذا ما نظر حقيقة الأشياء ، عند ذلك يثبت بلا حزن على الظلم والجور ] .","[ لأن الذين صار عندهم العالم بمنزلة مائت ، يصبرون على الضوائق بفرح ، لأنهم قد ماتوا بأفكارهم عن العالم . أما الذين رائحة هذا العالم موجودة فى فكرهم ، فليست تتركهم محبة المجد الباطل . لكن عندما يتسخطون بأفكارهم بالغضب ، يقعون فى أفكار الكآبة التى من هذا تتولد ] .","[ آه من هذه الفضيلة ، فضيلة الزهد ورفض العالم ، ما أصعب تقويمها . وما أكثر مجدها عند الله ] ...","يمكنك أيضاً أن تنتصر على الغضب بفضيلة الرقة واللطف .",{h:"★ بفضيلة الرقة واللطف :"},"والكتاب المقدس يدعونا إلى هذه الفضيلة فيقول القديس بطرس الرسول « كونوا جميعاً متحدى الرأى بحس واحد ، ذوى محبة أخوية ، مشفقين لطفاء » ( ١ بط ٣ : ٨ ) . ويقول القديس بولس الرسول « ليرفع من بينكم كل مرارة وسخط وغضب وصياح ... وكونوا لطفاء بعضكم نحو بعض ، شفوقين متسامحين ، كما سامحكم الله أيضاً فى المسيح » ( أف ٤ : ٣١ ، ٣٢ ) .","يمكننا أن نقضى على الغضب بفضيلة أخرى :"],119:[{h:"★ بالصلح والسلام :"},{h:"على أن نسرع بالمصالحة ، لأننا كلما نباطأنا فيها ، تزداد الأمور تعقيداً ، ويتطور الأمر داخل القلب إلى أسوأ ."},"ولهذا فإن الكنيسة تضع أمامنا نصيحة هامة ، نتذكرها فى بدء كل يوم ، فى صلاة باكر ، وذلك فى فصل من رسالة بولس الرسول إلى أهل أفسس حيث يقول لهم :","« أسألكم أنا الأسير فى الرب أن تسلكوا كما يليق بالدعوة التى دعيتم إليها ، بكل تواضع القلب والوداعة وطول الأناة ، محتملين بعضكم بعضاً فى المحبة ، مجتهدين أن تحفظوا وحدانية الروح برباط الصلح الكامل ، لكى تكونوا جسداً واحداً وروحاً واحداً ... » ( أف ٤ : ١ ـ ٤ ) .",{h:"والمصالحة تعيد الأمور إلى مجاريها ، وتزيل الغضب :"},"وقد طوّب الروح صانعى هذه المصالحات بقوله « طوبى لصانعى السلام ، لأنهم أبناء الله يدعون » ( مت ٥ : ٦ ) .","يمكننا أيضاً الإنتصار على الغضب بالصلاة والترتيل :",{h:"★ بالصلاة والترتيل :"},"قال القديس مار أوغريس : [ إذا تحرك الغضب يمكن أن يهدأ بالمزامير والكرم والرحمة ] . [ الغضب إذا هاج يخمده الترتيل وطول الأناة والرحمة ] .","فإذا إشتعل فيك الغضب ، إرفع قلبك إلى الله : اطلب منه أن يمنحك هدوءاً ووداعة وصبراً واحتمالاً . صلّ أيضاً من أجل السبب فى الغضب ، وأن يتدخل الله لحلّ الإشكال . صلّ من أجل الشخص الذى أثارك ليس فقط لكى ينصفك الله منه ، وإنما من أجل أبديته ولكى يغفر الله لك وله . قل له : إن كنت أنا يارب قد أعثرت هذا الإنسان أو أغضبته أو ضايقته فى شىء ، فساعنى ، ونجه من الغضب واصلح بينى وبينه .","حينئذ تلصق النعمة بك ، ويمنحك الله هدوءاً وسلاماً ."],120:["يمكننا أن ننتصر على الغضب أيضاً بفضيلة طول الأناة وسعة القلب أو سعة الصدر .",{h:"★ بطول البال وسعة القلب :"},"بعض الناس صدرهم ضيق ، يغضبون بسرعة ، ولأتفه الأسباب . أما أنت فكن واسع الصدر طويل البال . وتذكر قول الكتاب عن سليمان الحكيم « وأعطى الله سليمان حكمة وفهماً كثيراً جداً ، ورحبة قلب كالرمل الذى على شاطىء البحر » ( ١ مل ٤ : ٢٩ ) . وتذكر فى طول البال الحقيقة الآتية :",{h:"إذا القيت قطعة من الطين فى كوب ماء فإنها تعكره . ولو القيت هذا الطين فى المحيط فإنه لا يتعكر ."},"يأخذ المحيط حفنة الطين و يفرشها فى أعماقه بكل هدوء دون أن يتعكر . فكن أنت كذلك واسع القلب ولا تتضايق بكل سبب . وهنا أذكر قول بولس الرسول لأهل كورنثوس :","« فمنا مفتوح إليكم أيها الكورنثيون . قلبنا متسع . لستم متضيقين فينا ، بل متضيقين فى أحشائكم . فجزاء لذلك أقول كما لأولادى : كونوا أنتم أيضاً متسعين » ( ٢ كو ٦ : ١١ ـ ١٣ ) .","لهذا كله أقول عن فضيلة الاحتمال :",{h:"إن فضيلة الإحتمال لا يمكن أن تُكتسب وحدها ، إنما متحدة بفضائل أخرى ."},"تدخل فيها أيضاً المحبة والوداعة وطيبة القلب ... إلخ .",{h:"تذكر مثال الله"},"إننا عندما نغضب حينما يسىء الناس إلينا ، لا تكون راسخة فينا الأمثولة التى تركها الله أمامنا : إذ يسىء الناس إليه بكل أنواع الإساءات ، ويكسرون"],121:["كل وصاياه ، و يغضبون عليه أحياناً ويجدفون ، ومع ذلك فهو يغفر ، ولا يرد عليهم بنتيجة أخطائهم .. قال أحد القديسين :",{h:"كلما أرى غضب الناس ، أزداد حباً لله ، الذى يحتمل كل سيئاتنا ولا يغضب .."},"حقاً ما أعجب الله فى إحتماله .. إنه يحتمل كل الأخطاء ، لكل الناس ، وفى كل العصور . وما يزال فى صدره الإلهى متسع كبير لأخطاء الناس فى المستقبل أيضاً ... على الرغم من أنهم خليقته وعبيده ... بينما الناس لا يحتملون غلطة واحدة فى حقهم ، من بشر مساوين لهم ، أو ربما أعلى منهم مقاماً .",{h:"فإن حاورنا بالغضب على أحد ، فلنتذكر كم مرة أخطأنا إلى الله ، ولم يغضب علينا !!"},"ولنتعلم من الله : الصبر ، والاحتمال ، والمغفرة ، وعدم الغضب ، وعدم المعاملة بالمثل ، وعدم المجازاة عن كل خطأ ....","ولنتذكر أيضاً أمراً عجيباً ... وهو أننا بعد أن نخطىء إلى الله ، نقف لنصلى إليه ، ونتحدث معه ، ونطلب منه طلبات ... دون أن نعتذر إليه ، أو حتى نصالحه ...",{h:"هدوء الصوت والملامح"},{h:"يمكن للإنسان أن يدرب نفسه على أمرين هما : علو الصوت ، وحدة الصوت . حتى لا يتحول غضبه إلى صياح وعراك ."},"★ فالصوت العالى عثرة ، وهو يفضح الغضب أمام الناس ويعلنه . ويظهر الشخص الغاضب كإنسان عاجز عن التحكم فى أعصابه ، وعاجز عن الهدوء أثناء نقاشه . وهذا أمر غير مشرف له من كل ناحية ، وموضع لنقده مهما كان على حق ."],122:["وما أجمل أن يتخذ مثل هذا الغاضب مثال السيد المسيح الذى قيل عنه فى وداعة حديثه ونقاشه إنه :",{h:"« لا يخاصم ، ولا يصيح ، ولا يسمع أحد فى الشوارع صوته » ( مت ١٢ : ١٩ )"},"كذلك قيل عن السيد الرب فى العهد القديم ، حينما تحدث مع إيليا : إنه تكلم معه فى « صوت منخفض خفيف » ( ١ مل ١٩ : ١٢ ) .","لهذا حاول فى غضبك ، أن تتحكم فى علو صوتك .",{h:"بعلو الصوت تريد أن تغلب بأعصابك ، لا باقناعك ."},"أما الإنسان القوى فى رأيه ، الواثق بأدلته وبراهينه وإقناعه ، فإنه لا يحتاج مطلقاً إلى علو الصوت . ولا يشعر فى داخله بضعف أو نقص يحاول تعويضه بالصوت العالى .",{h:"وكثيراً ما يعلو صوت إثنين فى مناقشة ، حتى ما تستطيع أن تميز صوت أحدهما من الآخر ."},"وفى حمو الغضب لا يترك أحدهما للآخر فرصة للكلام ، بل يقاطعه ليتكلم هو . ولا يحتمل سماع صوته ، فيحاول أن يسكته ، لكى يقول ما يريد . والناس ينظرون فى عجب ، ولا يستطيعون أن يحترموا أو أن يتابعوا هذه المناقشة الغاضبة ...",{h:"★ وقد يكون مظهر الغضب هو حدة الصوت وعنفه ."},"حتى إن لم يكن عالياً ، ولكن نبرته شديدة وقاسية ، تدل على قلب غاضب وأعصاب ملتهبة ، وقد تثير سامعها . إذ تعمل فى طياتها أن المتكلم يلفظ كلامه بسلطان أو بأسلوب التحدى .",{h:"★ وإن إختلطت حدة الصوت بعلوه ، تكون غير محتملة . كذلك إن إرتبطت بملامح غاضبة ."},"انظر إلى وجهك فى مرآة أثناء غضبك ، ستجد أنه ليس من السهل إحتمال ملامحك . لذلك تدرب على هدوء الصوت والملامح ."],123:[{h:"تداريب متنوعة"},"١ ـ درب نفسك على عدم الغضب . ولا تتسبب فى إغضاب غيرك .","٢ ـ إبعد عن أسباب الإثارة على قدر ما تستطيع . ولا تضخم من قدر الأسباب ، ولا تأخذ الأمور بتأزم .","٣ ـ إن وجدت ناراً ، فلا تنفخ فيها ، ولا تضع عليها وقوداً .","٤ ـ عاشر الودعاء ، لكى تتعلم منهم الهدوء وضبط النفس ، وعدم الغضب مهما كانت المثيرات ، مع أخذ الأمور ببساطة .","٥ ـ لا تتفاهم مع الناس وأنت مرهق جسدياً أو غير محتمل ، أو وأنت متعب نفسياً أو عصبياً .","٦ ـ تخيّر الوقت الصالح للمناقشة . ولا تناقش أحداً وهو مرهق ، أو مشغول ، أو وهو غير مستعد للحديث معك .","٧ ـ لا تضغط على الآخرين ، ولا تتعب أعصابهم بالإلحاح .","٨ ـ بروح المحبة ، فكّر فى راحة مَنْ يبغضك ، وليس فى راحة نفسك ، ولو كنت صاحب حق .","٩ ـ لا تكن سريعاً فى غضبك . بل حاول أن تفهم غيرك . فكثيراً ما يكون الغضوب متسرعاً وأهوج ، يحكم قبل أن يفهم .","١٠ ـ هناك مثيرون كثيرون ، همهم أن يعكروا الأجواء الصافية ، فلا تصدق كل ما يقولون ، ولا تنفعل بسرعة وبدون تحقيق .","١١ ـ ضع فى نفسك أن الغضب لا يحل مشاكلك بل يعقدها .","١٢ ـ لا تظن أن الرجولة والشجاعة هى أن تقيم الدنيا وتقعدها . فالإحتمال دليل القوة . والنرفزة مظهر للضعف والعثرة ."],124:["١٣ ـ تدرب على البشاشة ، وعلى هدوء الملامح والصوت والحركات .","١٤ ـ لا تنتظر من الناس مثاليات ، إن لم تجدها تغضب . بل عش فى الواقع ، وتعامل مع كل أحد حسب طباعه .","١٥ ـ لا تحاسب كل إنسان حساباً عسيراً على كل لفظ وكل تصرف . ولا تؤول كلامه بسوء ظن إلى معانٍ تتعبك .","١٦ ـ اترك الحساسية الزائدة نحو كرامتك وحقوقك ، التى تجعلك تغضب لأقل سبب ، فتفقد صداقة وعشرة الناس .","١٧ ـ لا تقم نفسك معلماً لغيرك ، ولا رقيباً على تصرفات الناس . ولا تكن كثير الإنتقاد والتوبيخ والتوجيه .","١٨ ـ لا تكن شديداً فى عتابك بحيث تخسر أحباءك .","١٩ ـ إن وقعت فى الغضب ، حاول أن تتخلص منه فى بدايته ، ولا تجعله يتطور معك إلى ما هو أسوأ .","٢٠ ـ راقب الأخطاء التى تقع فيها أثناء غضبك . ودرب نفسك على التخلص منها . وكما تعالج نتائج غضبك ، عالج أسبابه .","٢١ ـ ليست كل صراحة ممدوحة . فكثيرون لا يحتملون أن تكشف أخطاءهم بصراحتك . الصراحة يجب أن تمتزج بالحكمة والمحبة واللطف .","٢٢ ـ لا تحاول إرغام الناس على قبول رأيك أو إتباع مبادئك . ولا تنتظر أن تسير كل الأمور حسب هواك .","٢٣ ـ إبعد عن التدخل فى خصوصيات الناس . ولا تحاول أن تسأل إنساناً عن أسراره الخاصة أو أسرار غيره .","٢٤ ـ إن ثار عليك أحد ، فلا تقابل ثورته بثورة . بل اعمل على تهدئته بقدر طاقتك وكن مسالماً فى معاملاتك ."]}},faith_life:{id:"faith_life",title:"حياة الإيمان",author:"قداسة البابا شنوده الثالث",url:"https://drive.google.com/file/d/1yHqM7AYCgFo6-ejDm43YJJMas1GXptxh/view",file:"حياة الإيمان.pdf",pageOffset:2,review:{status:"needs-review",note:"نُقل الكتاب (من «قصة هذا الكتاب» إلى آخر الفصل العاشر، ص٤ إلى ص١٠٩ بترقيم الملف) بقراءة صفحات الكتاب الممسوحة بالنظر؛ حُذف غلاف الكتاب والفهرس وإعلان «الكتاب المقبل». ملاحظات للمراجعة: (١) في الملف صفحتان مطبوعتان (٥٨ و٥٩) وردتا بترتيب معكوس فنُقلتا بترتيب القراءة، (٢) بعد عنوان الفصل الثامن يبدأ النص التالي في منتصف جملة فلعل صفحة ناقصة من ملف المصدر، (٣) بعد ص٨٢ المطبوعة يزيد رقم الصفحة المطبوعة عن ترقيم الملف بمقدار ٣ بدل ٢ لذلك قد تظهر أرقام الصفحات في الواجهة أقل بواحد في الجزء الأخير، (٤) عناوين الفصول المزخرفة قرئت بأفضل ما تيسر."},chapters:[{title:"قصة هذا الكتاب والمقدمة",from:4,to:6},{title:"الفصل الأول: ما أعظم الإيمان",from:7,to:10},{title:"الفصل الثاني: ما هو الإيمان (الإيقان بأمور لا ترى)",from:11,to:32},{title:"الفصل الثالث: درجات وأنواع من الإيمان",from:33,to:44},{title:"الفصل الرابع: علاقة الإيمان بالسلام وعدم الخوف",from:45,to:54},{title:"الفصل الخامس: علاقة الإيمان بنقاوة القلب",from:55,to:60},{title:"الفصل السادس: بساطة الإيمان",from:61,to:66},{title:"الفصل السابع: طاعة الإيمان أو حياة التسليم",from:67,to:80},{title:"الفصل الثامن: ما يقوي الإيمان",from:81,to:89},{title:"الفصل التاسع: ما يضعف الإيمان",from:90,to:101},{title:"الفصل العاشر: اختبار الإيمان",from:102,to:109}],transcribed:[4,109],pages:{4:[{h:"قصة هذا الكتاب"},"إنه ثمرة أكثر من ١٥ محاضرة ألقيت كلها فى الكاتدرائية المرقسية بدير الأنبا رويس بالقاهرة (ماعدا الثلاث محاضرات الأولى) . وقد حان الآن نشرها بناء على دعوة من مجلس كنائس الشرق الأوسط الذى قرر عقد اجتماع عن الإيمان فى منتصف سبتمبر ١٩٨٤ .","أما هذه المحاضرات ـ مصدر هذا الكتاب ـ فهى حسب تواريخها كالآتى :","١ ـ محاضرة ألقيت فى مؤتمر عن الإيمان عقد فى كنيسة المنصورة يوم ١٩٦٦/٦/١ .","٢ ، ٣ ـ محاضرتان عن الإيمان ألقيتا فى القاعة المرقسية بدير الأنبا رويس يومى الجمعة ١٩٦٦/٧/٨ ، ١٩٦٦/٧/١٥ .","٤ ـ ٧ ـ أربع محاضرات ألقيت فى الكاتدرائية الكبرى سنة ١٩٧١ تأملاً فى « كما قسم لكل واحد نصيباً من الإيمان » (رو ١٢ : ٣) .","٨ ـ محاضرة عن الإيمان ألقيت فى الكاتدرائية الكبرى فى أواخر مايو سنة ١٩٧٣ بمناسبة عودة رفات القديس أثناسيوس إلى القاهرة .","٩ ـ محاضرة عن عوائق الإيمان ألقيت يوم الجمعة ١٩٧٥/٥/٢٣ .","١٠ ـ محاضرة يوم الجمعة ١٩٨٠/٢/٢٢ ، موضوعها (ناظرين إلى ما لا يرى) .","١١ ـ محاضرة يوم الجمعة ١٩٨٠/٧/٢٥ ، موضوعها (بساطة الإيمان) .","١٢ ـ محاضرة يوم الجمعة ١٩٨٠/٩/٢٦ ، موضوعها (لا يعلم إلى أين يذهب) .","١٣ ـ محاضرة يوم الجمعة ١٩٨٠/١٠/٣ ، موضوعها (الإيقان بأمور لا ترى) .","١٤ ـ محاضرة يوم الجمعة ١٩٨١/٨/١٤ ، موضوعها (طاعة الإيمان) .","١٥ ـ محاضرات متفرقة نشرت فى مجلة الكرازة .","وقد سجلت هنا هذه التواريخ لمن يريد أن يحصل على التسجيلات الصوتية الخاصة بحياة الإيمان ، راجياً للقارىء العزيز حياة مملوءة بالإيمان .","البابا شنوده الثالث"],5:[{h:"مقدمة"},{h:"ليس الإيمان هو مجرد اعتناق مجموعة من العقائد ، تتلوها فى « قانون الإيمان » ... إنما الإيمان هو حياة تحياها أو هو عقيدة تقود إلى حياة ..."},"لأنه ما فائدة الإيمان بالله ، بدون أن تكون لك علاقة بهذا الإله : تطيعه وتحبه ، وتكون لك عشرة معه تؤهلك إلى عشرة دائمة فى ملكوته ؟!","وما فائدة الإيمان بالأبدية والحياة بعد الموت ، إن لم تعد نفسك لها بالتوبة ، وبالسهر الروحى الدائم ، وبمحبة الله .","وما فائدة الإيمان بالفضيلة ، إن كنت لا تحياها .","لذلك فإن هناك فرقاً كبيراً جداً بين الإيمان النظرى الذى لا يخلص النفس ، والإيمان العملى الذى تظهر ثماره فى حياتك . وهكذا تحيا حياة الإيمان ...","إننا من أجل حياة الإيمان ، وضعنا كتابنا هذا ...","نشرح لك ما هو الإيمان ، وما هى درجاته وأنواعه ، وما أهمية الإيمان فى حياتنا ، وما عظمته ... ؟","ولقد أردنا أن نقف قليلاً عند قول القديس بولس الرسول : « جربوا أنفسكم : هل أنتم فى الإيمان ؟ إمتحنوا أنفسكم » (٢كو ١٣ : ٥) .","فليس كل إنسان يقول إنه مؤمن ، هو مؤمن بالحقيقة . بل المقياس لذلك هو قول الرب « من ثمارهم تعرفونهم » (متى ٧ : ١٦) .","لأن هناك من له إسم المؤمن ، وليس له قلب المؤمن ، ولا حياة المؤمن . فما هى حياة المؤمن هذه ؟","حياة الإيمان ترتبط بالسلام والاطمئنان وعدم الخوف . فإن وقع فى الخوف ، يقول له الرب « يا قليل الإيمان ، لماذا شككت » (متى ١٤ : ٣١) ."],6:["وحياة المؤمن ترتبط بنقاوة السيرة ، لأن المؤمن يشعر دواماً أن الله أمامه يرى ويسمع ويسجل كل ما يعمله . لذلك يشعر بالإستحياء ، ويخاف أن يخطىء أمام الله .","وحياة المؤمن هى حياة التسليم للمشيئة الإلهية ، فى إيمان كامل أن الله هو صانع الخيرات ، وكل ما يسمح به هو خير . لذلك بالإيمان يعيش أولاد الله فى هدوء وفى فرح وفى رضى بكل ما يريده الرب لهم .","وحياة الإيمان ، لا ترى شيئاً مستحيلاً على الرب . بل كما يقول :",{h:"« كل شىء مستطاع للمؤمن » (مر ٩ : ٢٣) ."},"لذلك فإن المؤمن لا يهتز فى أية ضيقة تحل به ، بل يؤمن تماماً أن الله عنده حلول كثيرة ، وأنه لا بد سيتدخل ويصنع مشيئته ...","المؤمن لا يجادل الله ولا يناقشه فيما يفعله ، بل يقبل كل شىء بثقة كاملة فى حكمة الله وفى محبته .","المؤمن ينظر دائماً إلى ما لا يرى ، أكثر مما ينظر إلى المرئيات « لأن الأشياء التى تُرى وقتية ، أما التى لا ترى فأبدية » (٢كو ٤ : ١٨) .","إن أبطال الإيمان ليسوا هم فقط الذين دافعوا عن العقيدة ، وإنما هم الذين عاشوا فى الإيمان الحى المثمر العامل بالمحبة ...","وهذا الكتاب الذى بين يديك يعطيك فكرة مبسطة عن حياة الإيمان كيف تكون ؟ وكيف تختبر عملياً هل أنت فى الإيمان .","البابا شنوده الثالث"],7:[{h:"الفصل الأول"},{h:"ما أعظم الإيمان"}],8:["لعل أهمية الإيمان تبدو واضحة فى قول الرسول عن الرب :",{h:"« بدون إيمان ، لا يمكن إرضاؤه » (عب ١١ : ٦) ."},"وتبدو أهمية الإيمان أيضاً ، فى أن الرسول قد وصفه بأنه إحدى الفضائل الثلاث الكبار « الإيمان والرجاء والمحبة » (١كو ١٣ : ١٣) ، وذكر أنه الوسيلة التى يحيا بها الإنسان البار فقال :",{h:"« أما البار ، فبالإيمان يحيا » (عب ١٠ : ٣٨) ."},"والإيمان هو بدء الطريق الموصل إلى الله . لأنه كيف يمكن أن تثبت فى الله ، والله فيك ، وكيف يمكنك أن تسير مع الله وتحفظ وصاياه ، إن لم تؤمن أولاً بوجوده وبصفاته الإلهية ، وتؤمن بكتابه وبكل ما ورد فيه ... ؟",{h:"الإيمان إذن هو بدء الطريق إلى الله . وأول الشروط اللازمة للخلاص"},"حسب قول الرب نفسه « من آمن واعتمد خلص » (مر ١٦ : ١٦) ، « لكى لا يهلك كل من يؤمن به ، بل تكون له الحياة الأبدية » (يو ٣ : ١٦) ، « الذى يؤمن به لا يدان ، والذى لا يؤمن به قد دين ... » (يو ٣ : ١٨) . وكما وبخ اليهود قائلاً : « إن لم تؤمنوا أنى أنا هو ، تموتون فى خطاياكم » (يو ٨ : ٢٤) .","إن دم المسيح موجود ، قادر أن يخلص كل أحد . ولكنه لا يخلص بدون إيمان . ولهذا قال القديسان بولس وسيلا لحافظ السجن فى فيلبى « آمن بالرب يسوع ، فتخلص أنت وأهل بيتك » (أع ١٦ : ٣١) .",{h:"من أجل هذا الإيمان كتبت الأناجيل ، وكرز بها الرسل ."},"وهكذا يقول القديس يوحنا الإنجيلى فيما كتبه بوحى من الروح القدس « ... أما هذه فقد كتبت لتؤمنوا أن يسوع المسيح إبن الله ، ولكى تكون لكم إذا آمنتم حياة بإسمه » (يو ٢٠ : ٣١) .","الإيمان هو بدء الحياة مع الله ، وهو رفيق الطريق طول هذه الحياة ، لذلك من أهمية الإيمان علاقته بالبر ."],9:["وهكذا يتحدث الرسول عن البر الذى حُسب بالإيمان (عب ١١ : ٧) ، وعن الإيمان الذى حُسب براً (يع ٢ : ٢٣) .","ويتحدث الكتاب عن التبرير بالإيمان (رو ٥ : ١) .",{h:"والإيمان هو العنصر الأساسى اللازم لصنع المعجزات ، ولتقبلها :"},"لهذا ما أعظم قول الرب لأعمى أريحا بارتيماوس : « إيمانك قد شفاك » (لو ١٨ : ٤٢ ، مر ١٠ : ٥٢) . وما أجمل قوله لذلك الأبرص الذى طهر « إيمانك خلصك » (لو ١٧ : ١٩) . وهكذا قال أيضاً لنازفة الدم « ثقى يا إبنة : إيمانك قد شفاك » (متى ٩ : ٢٢) . كذلك فإنه لما سمع الأعميين اللذين صرخا « إرحمنا يا ابن داود » ، قال لهما : « بحسب إيمانكما ليكن لكما » فانفتحت أعينهما (متى ٩ : ٢٩) .","ومن الناحية الأخرى ، نرى أن السيد الرب لما جاء إلى وطنه « لم يصنع هناك قوات كثيرة لعدم إيمانهم » (متى ١٣ : ٥٨) .",{h:"إن قوة الله قادرة أن تصنع معك الأعاجيب . ولكنها تنتظر إيمانك ."},"وحسب إيمانك يعطيك . ولهذا فإن المعجزات تحدث مع البعض ، ولا تحدث مع البعض الآخر ، مع أن قوة الله هى هى .","ولكن ماذا عن الشخص ضعيف الإيمان ؟ هذا عليه أن يصلى مع أبى الولد الذى عليه روح الأخرس قائلاً : « أؤمن يا سيد . فأعن عدم إيمانى » (مر ٩ : ٢٤) . وهنا نقول إنه فى غالبية الأحوال يصنع الله المعجزة بحسب الإيمان ، ولكن ...",{h:"فى أحيان أخرى يصنع المعجزة لكى نؤمن ."},"وهكذا فى الحالين ، يرتبط الإيمان بالمعجزة : فإما أن يكون سابقاً لها ، وإما أن يكون نتيجة لها ...",{h:"إن الإيمان ـ أياً كان نوعه ـ هو قوة ."},"يكفى أن يؤمن الإنسان بفكرة ، فتراه يعمل بقوة المسيح لكى ينفذها . الإيمان يعطيه عزيمة وإرادة وجرأة ما كانت عنده من قبل ."],10:["حقاً حيثما يوجد الإيمان ، توجد معه القوة . فالصلاة المملوءة إيماناً ، هى الصلاة القوية . الذى يؤمن بالصلاة وفاعليتها ، تراه يصلى بحرارة وإيمان وقوة . والعظة التى يقولها إنسان وهو مؤمن بكل كلمة فيها ، تكون عظة قوية ، ينتقل بها إيمانه إلى قلوب الناس .",{h:"ومن أهمية الإيمان أيضاً إرتباطه بعديد من الفضائل ، تنبع منه :"},"فمن نتائج الإيمان القوة ، والطمأنينة ، والشجاعة ، والسلام القلبى ، وعدم الخوف ، وعدم القلق .","ومن ثماره أيضاً : حياة النقاوة والبر ، وحياة التسليم الكامل لله ، وحياة التجرد والزهد ، وحياة الصلاة ... وفضائل عديدة أخرى","ونحن نعدك أيها القارىء العزيز ، أننا لا ننتهى من هذا الكتاب ، حتى نحدثك عن هذا كله بمشيئة الله .",{h:"أما الآن فنريد أن نسأل : ما هو هذا الإيمان ؟"},"ما هو هذا الإيمان ، الذى من نتائجه الخلاص والتبرير ؟","وما هو هذا الإيمان ، الذى من نتائجه كل هذه الفضائل ؟","وما هو هذا الإيمان ، الذى يقدر على صنع الآيات والعجائب ، والذى قال عنه الرب : « كل شىء مستطاع للمؤمن » (مر ٩ : ٢٣) ."],11:[{h:"الفصل الثانى"},{h:"ما هو الإيمان"},"الإيقان بأمور لا ترى","« جربوا أنفسكم هل أنتم فى الإيمان ... إمتحنوا أنفسكم » (٢كو ١٣ : ٥) ."],12:[{h:"ما هو الإيمان ؟"},"كلمة إيمان قد يدعيها كل إنسان يعبد الله ... وربما لا يكون مؤمناً بالحقيقة ...",{h:"قد يكون له إسم المؤمن ، ولكن ليس له قلب المؤمن ."},"ليس الإيمان هو أن يولد الإنسان من أسرة متدينة تؤمن بوجود الله ، فيصير مؤمناً تلقائياً بوجود الله . إنما الإيمان له معنى أو معان أعمق من هذا بكثير ... نعم له معنى قد يشمل الحياة الروحية كلها ، وله معنى قد يصنع الأعاجيب .","فى إحدى المرات لم يستطع تلاميذ الرب أن يخرجوا شيطاناً من إنسان مصروع ، فسألوا الرب عن سر ذلك فقال لهم « لعدم إيمانكم » (متى ١٧ : ٢٠) ... ووبخ الجمع قائلاً : « أيها الجيل غير المؤمن ، الملتوى » (متى ١٧ : ١٧) .","ليكن ذلك الجيل غير مؤمن . ولكن رسل المسيح نفسه ، أُطلق عليهم حينذاك عبارة « عدم إيمانكم » ؟ ... يا للهول . وهنا يستطرد المسيح قائلاً لتلاميذه : « الحق أقول لكم لو كان لكم إيمان مثل حبة خردل ، لكنتم تقولون لهذا الجبل : إنتقل من هنا إلى هناك . فينتقل » (متى ١٧ : ٢٠) .",{h:"حقاً ، ما هو هذا الإيمان ، الذى حبة خردل منه ، تستطيع أن تنقل الجبل ؟ ! ..."},"لذلك حسناً قال الرسول : « إختبروا أنفسكم : هل أنتم فى الإيمان ؟ إمتحنوا أنفسكم » (٢كو ١٣ : ٥) .","على أن الكتاب يروى لنا شيئاً عجيباً ... أخطر من هذا بكثير ... فما هو ؟ إنه حال إنسان يبدو مؤمناً بالرب ، ويصلى ، ويصنع المعجزات ، وهو غير مؤمن بالحقيقة ! بل غير مقبول أمام الله ! هوذا الرب نفسه يقول :","« ليس كل من يقول لى يارب يارب ، يدخل ملكوت السموات ... » (متى ٧ : ٢١) ."],13:["ويتابع الرب كلامه قائلاً : « كثيرون سيقولون لى فى ذلك اليوم : يارب يارب ، أليس باسمك تنبأنا ، وباسمك أخرجنا شياطين ، وباسمك صنعنا قوات كثيرة ؟ فحينئذ أصرح لهم إنى لم أعرفكم قط . إذهبوا عنى يا فاعلى الإثم » (متى ٧ : ٢٢ ، ٢٣) .","ماذا نسمى هؤلاء الذين يقولون يارب يارب ... باسمك صنعنا كذا وكذا ... ؟ أهم مؤمنون بالحقيقة ؟ !",{h:"ربما يكون هذا إيماناً ظاهرياً ، أو إيماناً شكلياً ، أو إيماناً بالإسم ، أو مجرد إيمان عقلى ، ولكنه ليس إيماناً حقيقياً مقبولاً أمام الله !"},"فما هو إذن الإيمان الحقيقى المقبول أمام الله ؟ نسأل الرب فيجيب :","« ليس كل من يقول لى يارب يارب ... بل الذى يفعل إرادة أبى الذى فى السموات (متى ٧ : ٢١) . ويذكرنا هذا أيضاً بقصة العذارى الجاهلات اللاتى استعملن أيضاً عبارة يارب يارب . ووقفن وراء الباب المغلق يقلن : ياربنا ياربنا إفتح لنا . فسمعن منه تلك الإجابة الصريحة المرعبة « الحق أقول لكن إنى ما أعرفكن » (متى ٢٥ : ١٢) .",{h:"إن عبارة يارب لا تفيد مطلقاً ، إن كنت تنتظر العريس بمصباح لا زيت فيه ، أو إن جئت بعد أن أغلق الباب ..."},"ما هو الإيمان إذن ؟ وما علاقته بالزيت الذى يرمز إلى الروح القدس ، وإلى المسحة المقدسة ؟ وما علاقته بمشيئة الآب الذى فى السموات ؟","إنه هذا الإيمان الحى ، المقبول من الله ، كما سنشرح بالتفصيل فيما بعد ...",{h:"إذن الإيمان ليس مجرد عقيدة ، إنما هو أيضاً حياة ."},"يمكن أن تختبره بثماره فى حياتك ... فهكذا قال الرب « من ثمارهم تعرفونهم ... كل شجرة جيدة تصنع أثماراً جيدة ... لا تقدر شجرة جيدة أن تصنع أثماراً ردية . ولا شجرة ردية أن تصنع أثماراً جيدة . فإذن من ثمارهم تعرفونهم » (متى ٧ : ١٦ ـ ٢٠) .",{h:"بهذا تختبر نفسك : هل إيمانك له ثمر ؟ لأنه من ثمارهم تعرفونهم ."}],14:["وهكذا يعلمنا القديس يوحنا الحبيب : « بهذا نعرف أننا قد عرفناه ... » ، كيف ؟ « إن حفظنا وصاياه » ، « من قال قد عرفته ، وهو لا يحفظ وصاياه ، فهو كاذب وليس الحق فيه ... » (١يو ٢ : ٣ ، ٤) ... إذن الإيمان يختبر بحياة الطاعة لوصايا الله . والذى لا تكون له هذه الطاعة لا يعتبر مؤمناً بالحقيقة . بل لا نقول عنه إنه قد عرف الله ...",{h:"إن هناك وسائل كثيرة لاختبار الإيمان ، سنحدثك عنها فى باب خاص ."},"والقديس بولس الرسول يقدم لنا قائمة رائعة لرجال الإيمان فى رسالته إلى العبرانيين (عب ١١) . وكلهم من ذلك النوع الذى ظهر الإيمان فى حياته الخاصة ...","مثل أبينا أخنوخ الذى لم يقل الكتاب عنه إنه دافع عن عقيدة معينة ، كالقديس أثناسيوس الرسول الذى دافع عن العقيدة ضد الأريوسية ، أو كالقديس كيرلس الكبير الذى دافع عن العقيدة ضد النسطورية ، ومثل باقى أبطال الإيمان فى العقيدة ...","إنما كان أخنوخ من أبطال الإيمان ، لأنه « أرضى الله » (عب ١١ : ٥) . أو كما قال سفر التكوين « وسار أخنوخ مع الله » (تك ٥ : ٢٢ ، ٢٤) .","وأنت قد لا تكون لاهوتياً عميقاً فى المعرفة مثل القديس أثناسيوس أو القديس كيرلس . ولكنك بلا شك فى إمكانك أن تحيا فى منهج أبينا أخنوخ الذى سار مع الله . وأن تحيا مثل باقى رجال الإيمان الذين ذكرهم القديس بولس الرسول الذين « أقروا بأنهم غرباء ونزلاء على الأرض ... وكانوا يبتغون وطناً أفضل أى سماوياً » (عب ١١ : ١٣ ، ١٦) .","لقد كان أبونا إبراهيم من رجال الإيمان ، لأنه « لما دعى أطاع » (عب ١١ : ٨) ، فخرج وراء الله « وهو لا يعلم إلى أين يذهب » . وحُسب من رجال الإيمان ، لأنه صدق مواعيد الله حق وهو يقدم إبنه وحيده ، واثقاً أن الله قادر على الإقامة من الأموات (عب ١١ : ١٧ ـ ١٩) .","ووضعت زوجته ساره فى قائمة أبطال الإيمان ، لأنها صدقت قول الرب « إذ حسبت الذى وعد صادقاً » (عب ١١ : ١١) .",{h:"إذن ليس أبطال الإيمان هم فقط أبطال الدفاع عن العقيدة ، إنما أيضاً"}],15:[{h:"أولئك الذين صدقوا الرب ، وأرضوه ، وساروا معه ، وصنعوا براً (عب ١١ : ٣٣) ."},"وأيضاً أولئك الذين « عذبوا ولم يقبلوا النجاة ، لكى ينالوا قيامة أفضل » ، وأولئك الذين « طافوا فى جلود غنم وجلود ماعز ، معتازين مكروبين مذلين ، « تائهين فى برارى وجبال ومغائر وشقوق الأرض ، « وهم لم يكن العالم مستحقاً لهم » (عب ١١ : ٣٥ ـ ٣٨) .","هؤلاء كلهم كانوا مشهوداً لهم بالإيمان (عب ١١ : ٣٩) .","فى كل هذا يعطينا الكتاب معنى واسعاً لكلمة الإيمان .","ومعلمنا القديس بولس الرسول يقول لنا فى معنى الإيمان هذا :",{h:"« الإيمان هو الثقة بما يرجى ، والإيقان بأمور لا ترى » (عب ١١ : ١) ."},"وعبارة أمور لا ترى هى عبارة واسعة جداً ، سندخل فى تفاصيلها بعد حين إن شاء الله . ولكننا نقول كمثال : أنت ترجو أشياء كثيرة بعد الموت . ترجو حياة أخرى دائمة ، وعشرة مع الملائكة والقديسين . وترجو رؤية الرب فى الفردوس . وترجو القيامة من الموت بجسد روحانى غير قابل للفساد (١كو ١٥) . وترجو النعيم الأبدى بعد القيامة العامة . وأنت تثق بوجود كل هذه الأمور ، ثقة يقينية كاملة لا شك فيها ، دون أن ترى من كل ذلك شيئاً ... إنه الإيمان .",{h:"الإيمان فوق مستوى الحواس :"},{h:"وهنا نرى أن الإيمان يرتفع فوق مستوى الحواس :"},"إنه لا يتعارض مع الحواس ، إنما هو مستوى أعلى من مستوى الحواس . وهو قدرة أعلى من قدرة الحواس التى لها نطاق معين لا تتعداه . فالحواس المادية تدرك الماديات . غير أن هناك أشياء غير مادية ، تخرج عن نطاق قدرة الحواس المادية . وحتى قدرة الحواس بالنسبة للأشياء المادية ، هى محدودة أيضاً . وكثيراً ما تستعين الحواس بعديد من الأجهزة لمعرفة أشياء مادية أدق من أن تدركها حواسنا الضعيفة . فكم بالحرى إذن الأمور غير المادية ، التى قال عنها الرسول إنها « أمور لا ترى » ؟ !"],16:["إن ما يرى بالعين المادية يدخل فى نطاق (العيان) وليس الإيمان (٢كو ٥ : ٧) . فالروح مثلاً لا ترى ولا تدرك بالحواس المادية . سواء كانت روح بشر أو ملائكة . وعدم إدراك الحواس لها لا يعنى عدم وجودها . إنما يعنى أن قدرة الحواس محدودة . لها نطاق معين تعمل فيه لا يصل إلى مستوى الروح .",{h:"والله روح (يو ٤ : ٢٤) . لذلك فإنه لا يدرك بالحواس المادية ."},"لذلك فإننى عجبت من رائد الفضاء الذى قال إنه صعد إلى السماء ولم ير الله ! وقد ظن فى تهكمه أنه يمكن أن يرى الله بهذه العين الجسدية القاصرة التى لا ترى كثيراً من الماديات ! كما أن الله فى كل مكان ، فى الأرض وفى السماء وما بينهما ، ولا يحده مكان . فإن كان لم ير الله على الأرض ، فلن يراه أيضاً فى السماء ، ولا فى أى موضع آخر ، لأن الله لا يُرى إلا بالإيمان ... تراه بالروح (١كو ٢ : ١٠) .","عدم رؤيتك لله بعينك ، لا يعنى أن الله غير موجود . إنما تفسير ذلك هو أن عينك قاصرة . ومهما قويت ، فإن لها نطاقاً محدوداً تعمل فيه ، هو نطاق الماديات . ولذلك قلنا إن الإيمان أعلى من مستوى الحواس .",{h:"فى العهد القديم ، كان مستوى الناس ضعيفاً ، فكان تأثير الحواس فى الدرجة الأولى والأهم ، لذلك كان الله يظهر لهم فى السحاب والضباب والنار ."},"لقد كلمهم من على الجبل وسط البروق والرعود ، والجبل يدخن ، وقد صعد دخانه كدخان الأتون . وارتجف كل الجبل جداً . وكان سحاب ثقيل على الجبل ، وصوت بوق شديد ، فارتعد كل الشعب الذى فى المحلة (خر ١٩ : ١٦ ـ ١٨) . وكان المنظر هكذا مخيفاً حتى قال موسى أنا خائف ومرتعد (عب ١٢ : ٢١) .","بهذا الأسلوب كانوا يفهمون قوة الله وأهمية الوصية المعطاة لهم . أما فى حياة الإيمان ، فإن القلب يفهم قوة الله فى غير حاجة مطلقاً إلى هذا الإعتماد الكبير على الحواس . إن الإيمان مستوى أعلى من الحواس ، لا يعتمد عليها ، ولا يحتاج إليها ."],17:[{h:"والإيمان مستوى أعلى من العقل :"},"إن العقل قد يوصلك إلى بداية الطريق . أما الإيمان فيكمل معك الطريق إلى أقصاه . الإيمان لا يتعارض مع العقل . ولكنه يتجاوزه إلى مراحل أبعد بما لا يقاس ، لا يستطيع العقل بمفرده أن يصل إليها .","وما لا يدركه العقل ، نسميه « غير المدرك » . ونحن نصف الله بأنه « غير مدرك » . لأنه أيضاً غير محدود . بينما العقل البشرى محدود ، ولا يدرك سوى الأمور المحدودة ، التى تدخل فى نطاقه . العقل يستطيع أن يوصلك إلى مجرد معرفة الله ، وإلى بعض صفاته . ولكن بالإيمان « الروح يفحص كل شىء ، حتى أعماق الله » (١كو ٢ : ١٠) . وبالنسبة إلى المؤمن ، يكشف الله له ذاته . أو يكشف له ما تحتمل الطبيعة البشرية أن تدركه ...",{h:"العقل قد لا يدرك أشياء كثيرة ، ولكنه يقبلها ."},"العقل ليس من طبيعته أن يرفض كل ما لا يدركه . بل حتى فى المحيط المادى فى العالم الذى نعيش فيه ، توجد مثلاً مخترعات كثيرة لا يدركها إلا المتخصصون . ومع ذلك فالعقل العادى يقبلها ، ويتعامل معها ، دون أن يدرك كيف تعمل ، وكيف تحدث . والموت يقبله العقل ، ويتحدث عنه ، ومع ذلك فهو لا يدركه ، ولا يعرف كيف يحدث .","فإن كان العقل يقبل أموراً كثيرة فى عالمنا ، وهو لا يدركها . فطبيعى لا يوجد ما يمنعه من قبول أمور أخرى أعلى من مستوى هذا العالم .",{h:"العقل لا يدرك (المعجزة) كيف تتم . ولكنه يقبلها ويطلبها ، ويفرح بها ."},"لقد سميت المعجزة معجزة ، لأن العقل يعجز عن إدراكها وعن تفسيرها . ولكنه يقبلها بالإيمان ... الإيمان بوجود قوة غير محدودة ، أعلى من مستواه ، يمكنها أن تعمل ما يعجز العقل عن إدراكه . وهذه القوة هى قوة الله القادر على كل شىء .",{h:"إننا نحترم العقل . ولكننا فى نفس الوقت ندرك حدود النطاق الذى يعمل فيه . ولا نوافق العقل المغرور الذى يريد أن يعى كل شىء ، رافضاً كل ما هو فوق مستوى إدراكه ."}],18:["ينبغى للعقل أن يتضع ، ويعرف مستواه ، « ولا يرتئى فوق ما ينبغى » (رو ١٢ : ٣) . وفى الأمور التى هى فوق إدراكه ، يجب أن يسلم قياده للإيمان .","أما إن أراد العقل أن يحطم كل ما لا يدركه ، فإنه سيحطم نفسه أخيراً ، ويفقد الإيمان . ويحصر نفسه فى دائرة ضيقة جداً ، هى دائرة إدراكه المحدود .","والذين يسلكون هكذا ، إعتاد البعض أن يسميهم (العقلانيون) ، لأنهم يعتمدون على العقل وحده ، دون الإيمان ودون الروح !",{h:"إن العاقل يمكنه أن يصل إلى الله . أما العقلانى فلا يصل ."},"والمؤمنون عاقلون ، ويحترمون العقل ، ويستخدمونه أيضاً فى الأمور الدينية واللاهوتية . ويوجد بين المؤمنين فلاسفة وحكماء وأشخاص على مستوى عال من الفكر والذكاء . ولكنهم على الرغم من كل هذا ، لا يمزجون العقل بالغرور ، ولا يثقون بقدرة العقل على إدراك كل شىء . وإنما فى بساطة واتضاع ، يعترفون أن عقولهم محدودة ، وقاصرة عن إدراك كل ما يحيط بالله غير المدرك ... وبالإيمان تقبل قلوبهم وعقولهم ما هو فوق مستوى العقل ...",{h:"العقل البسيط المتواضع ، هو الذى يقبل الإيمان ، والمعجزة ."},"نقصد بعبارة (المتواضع) إنه لا يعتز بإدراكه الخاص . ولا يحطم كل ما هو فوق إدراكه . ونقصد بعبارة (البسيط) ، العقل الذى لا يعقد الأمور ، ولا يصر على إدخال كل شىء فى حدود معامله ومقاييسه الخاصة .","ولعلنا سنعود إلى هذه النقطة ، حينما نتحدث عن (بساطة الإيمان) .",{h:"الإيمان ليس هو مجرد تلاوة قانون الإيمان ، إنما هو حياة نحياها ."},"إن كنت تحيا فى الإيمان ، والإيمان له ثماره فى حياتك العملية ، فإنك تستطيع أن تختبر إيمانك بالفضائل التى تبدو واضحة فى حياة المؤمن ، وهى عديدة ... وبها تنفذ قول الرسول « إمتحنوا أنفسكم : هل أنتم فى الإيمان ؟ إختبروا أنفسكم » (٢كو ١٣ : ٥) ."],19:[{h:"الإيقان بأمور لا ترى"},"قال الرسول فى معنى الإيمان إنه « الثقة بما يرجى ، والإيقان بأمور لا ترى » (عب ١١ : ١) . ونود أن نعرف تفسير هذه العبارة .",{h:"الإيقــان :"},"أى التأكد الشديد ، والثقة ، والعقيدة التى لا تعرف شكاً . ليس الأمر مجرد فكر أو رأى ، أو معلومات نتيجة قراءة أو سماع . إنما يقين أكيد بوجود هذه الأمور التى لا ترى .",{h:"وهنا يبدو الفرق بين رجال الإيمان ، ورجال البحوث العلمية ."},"أصحاب البحوث العلمية ، لا تدخل فى نطاق عملهم كل تلك الأمور التى لا ترى . وهم لا يكونون فى حالة يقين من شىء إلا إذا فحصوه تماماً بكل أجهزتهم ومقاييسهم العلمية . وعلى نفس هذا المنهج كل أصحاب المذاهب المادية .","أما المؤمنون فهم ليسوا كذلك . إنهم يتبعون قول الرب « طوبى لمن آمن دون أن يرى » (يو ٢٠ : ٢٩) .","المؤمن يقبل مثلاً فكرة الخلق من العدم . أما الباحث العلمى ، فترفض أبحاثه هذا الأمر ، كما ترفض أيضاً أن يشبع من خمس خبزات خمسة آلاف رجل (غير النساء والأطفال) ، وتفيض عنهم إثنتا عشرة قفة مملوءة . أما المؤمن فيقبل كل هذا ...",{h:"المؤمن يقبل أولاً فكرة الله القادر على كل شىء . ثم فى دائرة يقينه من جهة هذه القدرة غير المحدودة ، يقبل كل شىء ..."},"وهكذا يريح نفسه من شكوك غير المؤمن ومن بحوثه وفحوصه الكثيرة . وهو ليس فقط يقبل ما لا يرى ، ويكون موقناً بوجود غير المرئيات ، بل إنه أكثر من هذا يعايش ما لا يرى ، ويركز فيه كل تفكيره وكل عواطفه ، حسبما قال الرسول « غير ناظرين إلى الأمور التى ترى ، بل إلى التى لا ترى ، لأن التى ترى وقتية . أما التى لا ترى فأبدية » (٢كو ٤ : ١٨) ."],20:["ولعلك تسأل : كيف ننظر ما لا يرى ؟ فأقول بالإيمان .","ما هى إذن هذه الأمور التى لا ترى ؟ لعل فى مقدمتها الله نفسه ، وصفاته ، وعمله ، وكل ما يتعلق به .",{h:"١ ـ الله ، وصفاته ، وعمله :"},"إن الله لا يُرى ، وقد قال القديس يوحنا الإنجيلى : « الله لم يره أحد قط ... » (يو ١ : ١٨) . حقاً من يستطيع أن يرى اللاهوت ؟ ! لا أحد . ومع ذلك فأنت تؤمن به من كل قلبك ، وبكل ثقة . ولا يعتمد هذا الإيمان مطلقاً على الحواس . أو قل إنك تراه بتلك الحواس الروحية المدربة (عب ٥ : ١٤) . تلك الحواس غير المادية التى تدربت أن ترى ما لا يرى . ولنا أمثلة على ذلك من الكتاب :",{h:"يقول داود النبى « تقدمت فرأيت الرب أمامى فى كل حين ، لأنه عن يمينى فلا أتزعزع » (مز ١٥) ."},"فكيف رأى الرب أمامه وعن يمينه كل حين ؟ لا شك أنه رآه بعين الإيمان . وفى بعض الترجمات يقول « جعلت الرب أمامى كل حين » . أى أنه ناظر إليه باستمرار ، ناظر إلى ما لا يرى ، مركزاً فيه فكره وشعوره .",{h:"وبنفس المعنى يقول إيليا النبى « حى هو رب الجنود الذى أنا واقف أمامه » (١مل ١٨ : ١٥) ."},"فكيف شعر أنه واقف أمام الرب ؟ وكيف كان يرى الرب أمامه فى كل حين ؟ ... ليس بالحواس الجسدية طبعاً ، لأن الحواس الجسدية ليست هى التى تحرك قلب المؤمن . بل إن الرب أمامه بالإيمان . وهو بالإيمان يرى ما لا يرى .",{h:"إن كنت فى الإيمان ، فلا بد ستثق إن الله أمامك فى كل حين ، وتتصرف وفق هذا الإيمان : إنه يراك ويسمعك ..."},"وإن عشت فى الإيمان ، فستثق أن الله فى وسط شعبه ، حسب وعده الصادق « ... هناك أكون فى وسطهم » (متى ١٨ : ٢٠) ، « ها أنا معكم كل الأيام وإلى انقضاء الدهر » (متى ٢٨ : ٢٠) . إنك لست تراه بعينك الجسدية ، ولكنك تؤمن تماماً أنه فى وسطنا . لست محتاجاً أن ترى بعينيك لكى تصدق . فأنت تؤمن دون أن ترى . أو ترى ما لا يرى ."],21:[{h:"ما هى حياتنا الروحية يا إخوتى ؟ إنها ليست سوى انتقال من نطاق المحسوسات والمرئيات إلى نطاق ما لا يرى ."},"ونحن نعيش فى ما لا يرى ، بملء الثقة أنه موجود أمامنا . وهذا هو الفرق بين المؤمن وغير المؤمن .","غير المؤمن يريد أن يرى كل شىء بعينيه ، وإلا فإنه لا يصدق .","أما المؤمن فإنه لا يجعل من عينيه حكماً على كل ما يؤمن به ... ولا كل حواسه ، ولا المعلومات الظاهرة . بل إن قلبه يوقن بوجود أمور لا يراها بعينيه ... إن اعتماد الإنسان على عينيه لكى يصدق ، أمر وبخ الرب عليه تلميذه توما قائلاً له « لا تكن غير مؤمن بل مؤمناً » « ألأنك رأيتنى يا توما آمنت ؟ ! طوبى للذين آمنوا ولم يروا » (يو ٢١ : ٢٧ ، ٢٩) .","قلنا إنه من ضمن الإيقان بأمور لا ترى ، الإيمان بالله ... ولكننا لا نعنى بهذا مجرد الإيمان بوجود الله ، وإنما الإيمان أيضاً بصفاته وبعمله .","فتؤمن مثلاً بصلاح الله وخيريته . وبأنه لا يصنع إلا خيراً . وتؤمن أنه ضابط الكل ، يرقب كل شىء وكل أحد . وتؤمن أن الله قادر على كل شىء ، وأن « غير المستطاع عند الناس ، مستطاع عند الله » (لو ١٨ : ٢٧) . وتؤمن بمحبة الله لك ولغيرك ...","كل هذه الصفات ، لا تراها . ولكن تؤمن بوجودها ، وتؤمن برعاية الله للكون ، وحفظه له جملة ، ولكل فرد فيه على حدة ... وتؤمن أن الله يعمل ، سواء رأيت عمله أو نتائج عمله ، أو لم تر شيئاً ...",{h:"٢ ـ ومن الأشياء التى لا ترى أيضاً مواعيد الله ."},"وقد حسب من رجال الإيمان أولئك الذين « لم ينالوا المواعيد ، بل من بعيد نظروها وصدقوها وحيوها ، وأقروا بأنهم نزلاء وغرباء على الأرض » (عب ١١ : ٣) . وهؤلاء نظروا المواعيد بالإيمان ، إذ صدقوا ما قيل لهم من قبل الرب ...","ومن هذه المواعيد « ما أعده الله للذين يحبونه » وكلها من الأمور التى لا تُرى ، إذ قال عنها الرسول « ما لم تره عين ، ولم تسمع به أذن ، ولم يخطر على قلب بشر » (١كو ٢ : ٩) ."],22:[{h:"ومن الأمور التى لا ترى ، إنذارات الله ."},"لقد آمن نوح بكلام الرب أنه سيحدث طوفان ، مع أن كلمة (طوفان) هذه ، كانت جديدة على سمعه وعلى معرفته . ولم يحدث طوفان من قبل فى أيامه ، ولا فى أيام سابقيه . ولكنه آمن بحدوث هذا الشىء لم يره أحد من قبل . وظل سنوات يعمل فى بناء الفلك ، محتملاً استهزاء الناس به وبفلكه وتهكمهم ... وكانت سنوات من الإيمان .","ولذلك اعتبر أبونا نوح من رجال الإيمان لأنه صدق إنذار الله بالطوفان . وبالإيمان رأى هذا الطوفان قائماً قبل أن يكون . ولذلك دخل الفلك هو وبنوه ونساؤهم . وكما قال معلمنا القديس بولس الرسول « بالإيمان نوح ، لما أوحى إليه عن أمور لم تر بعد ، خاف فبنى فلكاً لخلاص بيته ... » (عب ١١ : ٧) . بينما معاصروه لم يصدقوا إنذار الله ، ولم يؤمنوا بصدق كلام الله فهلكوا ...","ونفس الوضع نقوله عن أبينا لوط وأهل سدوم . هو صدق إنذار الله قبل أن يحدث . مع أنها كانت المرة الأولى التى تنزل فيها نار من السماء ، كما كانت المرة الأولى التى يحدث فيها طوفان فى أيام نوح .","أما أهل سدوم الذين لم يؤمنوا بإنذار الله فقد هلكوا ، كما هلك الذين لم يؤمنوا بإنذار الله أيام نوح .","وهوذا إنذارات الله الخاصة بالأبدية وبالدينونة قائمة أمامنا ، ومع ذلك فالناس مازالوا فى شرورهم وأخطائهم ، كأن الله لم يقل شيئاً ... لا مخافة الله فى قلوبهم ، ولا خشية الأبدية ، ولا حرصاً ، ولا توبة ...","تحدثنا عن الله وعن صفاته وعمله ، وعن مواعيده وإنذاراته ، ضمن الأمور التى لا ترى . ونضيف على ذلك :",{h:"٣ ـ سكنى الروح وعمله فينا ، من الأمور التى لا ترى :"},"صموئيل النبى صب من قنينة الدهن على الصبى داود ، فحلّ عليه روح الرب (١صم ١٦ : ١٣) . ولم ير أحد روح الرب وهو يحل عليه . ولكن هكذا كان . إنه من الأمور التى لا ترى"],23:["وكان الرسل يضعون أيديهم على الناس ، فيحل عليهم الروح القدس (أع ٨ : ١٧) . وما كان أحد يرى الروح القدس وهو يحل على الناس . ثم أصبح الروح القدس ينال بالمسحة المقدسة (١يو ٢ : ٢٠ ، ٢٧) . وعرفت هذه المسحة باسم (الميرون) . ولم يكن أحد يرى الروح ، إنما ثماره تظهر فى الحياة .","أنت تعرف تماماً أن هناك قوة خفية تعمل فيك وتعمل معك ، دون أن تراها ، هى التى قال عنها الرب « ولكنكم ستنالون قوة متى حل الروح القدس عليكم » (أع ١ : ٨) . هذه القوة ، قوة الروح هى التى تعمل فيك كل خير ، وتساعدك فى كل خدمة ، وتحميك من كل خطية ...",{h:"هنا ونقول إن حياتنا كلها تصبح شركة مع الروح القدس (٢كو ١٣ : ١٤) ."},"ما هذه الشركة ؟ وكيف تحدث ؟ وكيف نصبح شركاء للطبيعة الإلهية فى العمل ؟ إن هذا من الأمور التى لا ترى . لا نراها ولكن نؤمن بها . نؤمن بروح الله العامل فى الكنيسة ، الساكن فيها .","هوذا الرسول يقول « أما تعلمون أنكم هيكل الله ، وروح الله يسكن فيكم » (١كو ٣ : ١٦) ، « أم لستم تعلمون أن جسدكم هو هيكل للروح القدس الذى فيكم ، الذى لكم من الله » (١كو ٦ : ١٩) .","وسكنى الروح فينا أمر لا نراه . قد نرى ثماره فقط . أما نفس السكنى فلا نراها . والروح لا تراه .","ومن عمل الروح فينا قول الرب لنا عن الوقوف أمام الولاة والملوك « لأنكم تعطون فى تلك الساعة ما تتكلمون به . لأن لستم أنتم المتكلمين ، بل روح أبيكم يتكلم فيكم » (متى ١٠ : ١٩ ، ٢٠) .","كيف يتكلم روح الله فينا ؟ إن هذا من الأمور التى لا ترى .",{h:"٤ ـ وعمل النعمة فينا ، من الأمور التى لا ترى :"},"تأتينا زيارات من النعمة ، تشعلنا بمحبة الله . لا نراها ولكن نحسها . ولا شك أن عمل النعمة فينا هو من الأمور التى لا ترى ."],24:["يقول القديس يوحنا الإنجيلى « أما النعمة والحق فبيسوع المسيح صارا » (يو ١ : ١٧) . فما هى هذه النعمة العاملة فينا ؟ ما هى هذه النعمة التى عاش بها القديس بولس الرسول فقال « ... ولكن بنعمة الله ، أنا ما أنا . ونعمته المعطاة لى لم تكن باطلة » (١كو ١٥ : ١٠) . ويقول عنا جميعاً « فإن الخطية لن تسودكم ، لأنكم لستم تحت الناموس ، بل تحت النعمة » (رو ٦ : ١٤) . ويقول لتلميذه تيموثاوس الأسقف « فتقو أنت يا إبنى بالنعمة التى فى المسيح يسوع » (٢تى ٢ : ١) .","نحن لا نرى هذه النعمة بعيوننا الجسدية ، فهى من الأمور التى لا ترى . ولكننا نلمسها فى حياتنا . وعمل نعمة الله فينا هو فوق الحواس . ونحن نتقبل هذه النعمة من الله . ونأخذها بركة من الكنيسة التى تردد لنا قول القديس بولس الرسول « نعمة ربنا يسوع المسيح ، ومحبة الله ، وشركة الروح القدس تكون مع جميعكم ، آمين » (٢كو ١٣ : ١٤) .","إن هذا يجعلنا ننتقل إلى نقطة أخرى هى البركة :",{h:"٥ ـ البركة أيضاً هى من الأمور التى لا ترى :"},"سواء البركة التى من الله نفسه مباشرة ، أو بركة الله التى تأتى عن طريق الوالدين ، أو من الكنيسة من الأب الكاهن . كلها أمور لا ترى .","لقد قال الله لأبينا ابرآم أبى الآباء « أباركك ، وأعظم إسمك . وتكون بركة . وأبارك مباركيك ... وتتبارك فيك جميع قبائل الأرض » (تك ١٢ : ٢ ، ٣) . لقد رأى ابرآم ثمار هذه البركة فى حياته . ولكن البركة نفسها : ما هى ؟ إنها من الأمور التى لا ترى .","واسحق بارك يعقوب إبنه ، فصار مباركاً . وبكى عيسو لأنه لم يحصل على هذه البركة (تك ٢٧) . ويعقوب بارك افرايم ومنسى قائلاً « الملاك الذى خلصنى من كل شر يبارك الغلامين » (تك ٤٨ : ١٦) . وصار الغلامان مباركين . ولكن افرايم صار أكثر بركة من أخيه ، لأن أبانا يعقوب وضع عليه يده اليمنى (تك ٤٨ : ١٧ ـ ٢٠) .","ما هى هذه البركة ؟ وكيف سرت من يد إسحق ومن يد يعقوب ؟ وكيف"],25:["سرت من أيدى الآباء الرسل ؟ وكيف تسرى من أيدى خلفائهم ومن رجال الله جميعاً ، كما يروى لنا الكتاب ... ؟","إنها كلها أمور لا ترى . ونحن نؤمن بالبركة مع أنها لا ترى ، ونسعى إلى طلبها ونوالها . ونأخذها من أيدى الآباء والأمهات ومن الآباء الكهنة ومن كل رجال الله المباركين . ونعرف تماماً أن ابرآم كان بركة للعالم حسب قول الرب . وأن يوسف الصديق كان بركة فى بيت فوطيفار وبركة فى كل أرض مصر ، وأن إيليا النبى كان بركة فى بيت أرملة صرفة صيدا ...","نقول هذا كله ، ونحن لا نستطيع وضع معنى محدد للبركة ، فهى أوسع بكثير من الألفاظ المحدودة . وهى أمر لا يرى . نرى ثماره فقط . ولكن البركة نفسها . من يستطيع أن يراها ويشخصها ؟ !","كيف سرت البركة من يد السيد المسيح إلى الخمس خبزات والسمكتين ، فصار هذا الطعام البسيط كافياً لعدة آلاف من الناس ، وفاض عنهم إثنتا عشرة قفة مملوءة ؟ كيف حدث هذا الأمر ؟ وما نوعيته ومفعوله بالضبط ... كلها أمور لا ترى ...",{h:"٦ ـ ومن ضمن الإيمان أيضاً بما لا يرى ، الإيمان بوجود الملائكة وعملهم :"},"نحن نؤمن بوجود الملائكة ، والملائكة أرواح لا ترى . وربما لا نكون قد رأينا ملاكاً فى حياتنا كلها . ومع ذلك نؤمن أنهم حولنا وأن « ملاك الرب حال حول خائفيه وينجيهم » (مز ٣٤ : ٧) . ونوقن بأن الملائكة تملأ الكنيسة . ونثق أنهم معنا فى كل مواضعنا « أليسوا جميعهم أرواحاً خادمة ، مرسلة للخدمة لأجل العتيدين أن يرثوا الخلاص » (عب ١ : ١٤) .",{h:"كثيرون يفرحون حينما يرون العذراء فى رؤيا ، أو يرون قديسين ."},"ولكن أعظم من هذا أن تؤمن بأن كل هؤلاء حولك ، دون أن تراهم . ليس من الضرورى أن يرسل لك الله حمامة بيضاء أثناء حضورك إجتماعات المساء فى الكنيسة ... إنما أنت تؤمن ـ دون أن ترى ـ أن الكنيسة مملوءة بأرواح الملائكة . وترفرف عليها أرواح القديسين الذين يرسلهم الله لخدمة البشر ..."],26:["إن جيحزى تلميذ أليشع ، خاف لما رأى الأعداء عيطين بالمكان ...",{h:"ولكن أليشع ، الرجل المفتوح العينين ، فكان يرى الملائكة يدافعون عن المدينة ضد هؤلاء الأعداء ."},"لذلك طمأن غلامه قائلاً له « لا تخف ، لأن الذين معنا أكثر من الذين علينا ... » (٢مل ٦ : ١٦) . وصلى من أجله لكى يفتح الرب عينيه فيرى ، إذ كان جيحزى ليس له الإيقان بأمور لا ترى .",{h:"٧ ـ ومن الإيقان بما لا يرى أيضاً : الإيمان بالروح ، والعالم الآخر :"},"نحن لا نرى الروح . ولكننا نوقن بوجودها . وحينما يموت إنسان ، نقول إن روحه فارقت جسده . ونحن لم نر هذه الروح تفارق الجسد .","كذلك الإيمان أيضاً يشمل مصير هذه الروح ، فى الفردوس أو الجحيم . ويشمل أيضاً عودة هذه الروح إلى الجسد بالقيامة . ومصير هذا الإنسان القائم من الأموات فى الأبدية بعد الدينونة العامة ...","وكل هذه الأمور : الروح ـ القيامة ـ الأبدية ـ الدينونة (الحساب) ـ الفردوس ـ النعيم ـ الجحيم ... كلها أمور لا ترى . لذلك فالإيقان بوجودها جميعاً يدخل فى نطاق الإيمان . حقاً إن العالم الآخر بكل ما فيه ، لا يتحدث عنه أحد إلا بالإيمان . والذى يؤمن بالحياة بعد الموت ، إنما يوقن بأمور لا ترى .",{h:"٨ ـ لقد آمن الناس بمجىء المسيا ، دون أن يروه :"},"حتى المرأة السامرية ، قالت للرب « أنا أعلم أن المسيا ـ الذى يقال له المسيح ـ يأتى . فمتى جاء ذاك يخبرنا بكل شىء » (يو ٤ : ٢٥) .","وهكذا كان الجميع موقنين بمجىء المسيا ، حسب وعد الرب . وكانوا ينتظرونه بكل شوق . ويعرفون ما قاله اشعياء النبى « ها العذراء تحبل وتلد ابناً ، وتدعو إسمه عمانوئيل » (اش ٧ : ١٤) . وما كانوا قد رأوا من قبل عذراء تلد ، ومع ذلك آمنوا بهذا الأمر فيما بعد ...","ويشبه الإيمان الذى كان به أهل العهد القديم ينتظرون مجىء المسيا ، هكذا"],27:["نحن فى العهد الجديد ننتظر مجىء الرب ثانية ، على السحاب ، حسب وعد الرب (متى ٢٤ ، ٢٥) ، وحسب بشرى الملاكين للتلاميذ (أع ١ : ١١) .","لم نر الرب من قبل على سحاب السماء مع ربوات قديسيه ، فى مجد أبيه ، ومعه ملائكته القديسون . ولكننا نؤمن بمجيئه فى هذا المنظر الذى لم نره من قبل . لأن الإيمان هو الإيقان بأمور لا ترى .",{h:"٩ ـ الفداء أيضاً هو من الأمور التى لا ترى :"},"فى الفداء ، من محبة المسيح لنا ، حمل جميع خطايانا ومات عنها « كلنا كغنم ضللنا . ملنا كل واحد إلى طريقه . والرب وضع عليه إثم جميعنا » (اش ٥٣ : ٦) . وهكذا قال عنه القديس يوحنا المعمدان « هذا هو حمل الله الذى يرفع خطية العالم » (يو ١ : ٢٩) . وقال القديس يوحنا الرسول « وهو كفارة لخطايانا ، ليس لخطايانا فقط ، بل لخطايا كل العالم أيضاً » (١يو ٢ : ٢) . وقال القديس بولس الرسول « مسامحاً لكم بجميع الخطايا ، إذ محا الصك الذى علينا » (كو ٢ : ١٣ ، ١٤) . وقال أيضاً « عاملاً الصلح بدم صليبه » (كو ١ : ٢٠) .","ونحن نرى الصليب فقط ، وقد يراه البعض عاراً ! ! أما ما فى الصليب من حب ، ومن فداء وكفارة ، ومن مغفرة ومحو للصك المكتوب ، وحمل خطايا العالم ، وأيضاً ما فى الصليب من عمل المصالحة ... فكل هذه أمور لا ترى . نراها نحن بالإيمان ...","بطرس الرسول ـ قبل الإيمان بكل هذا ـ ما كان يرى فى الصليب سوى الضياع والعار ... ! لذلك قال « حاشاك يارب » (متى ١٦ : ٢٢) . فانتهره الرب ، إذ لم يكن يرى الأمور التى لا ترى ...","إن الصليب كان يمثل عمق إحسانات الرب إلينا . ولكن الكتبة والفريسيين لم يروا هذا ، لأن عيونهم ما كانت تبصر . لأنهم « لو عرفوا لما صلبوا رب المجد » (١كو ٢ : ٨) .","إن هذا يقودنا إلى نقطة أخرى وهى :"],28:[{h:"١٠ ـ إحسانات الله الخفية ، هى من الأمور التى لا ترى :"},"إننا نشكر الله فقط على إحساناته التى نراها أو التى نعرفها . ولكن هناك إحسانات أخرى لا ترى ينبغى أن نشكره عليها أيضاً . ولذلك عندما ندخل بالإيمان فى حياة التسليم ، ندخل تلقائياً فى حياة الشكر الدائم . كما قال الرسول « شاكرين فى كل حين ، على كل شىء » (أف ٥ : ٢٠) .",{h:"وفى هذا الشكر الدائم ، نشكر على التجارب أيضاً ..."},"لأننا نشعر أنه توجد فيها إحسانات خفية من الله ، نحن لا نبصرها . وإن أبصرناها ، لا بد أن نغنى مع القديس يعقوب الرسول قائلين « إحسبوه كل فرح يا إخوتى ، حينما تقعون فى تجارب متنوعة » (يع ١ : ٢) .","وبهذا نرى الإيمان يعطى معنى روحياً للألم ، الألم الذى يسمح الله به من أجل بركات معينة كامنة فيه ، هى من الأمور التى لا ترى ، ولكننا نتقبلها بالإيمان ، واثقين من محبة الله الصانع الخيرات ، وواثقين من قول الكتاب « كل الأشياء تعمل معاً للخير ، للذين يحبون الله » (رو ٨ : ٢٨) .",{h:"١١ ـ وجود الله فى حياتنا ، وقوته العاملة فينا ، من الأمور التى لا ترى :"},"ما أجمل قول الرب لأبينا يعقوب « وها أنا معك . وأحفظك حيثما تذهب . وأردك إلى هذه الأرض » (تك ٢٨ : ١٥) ... كان الرب معه يحفظه حيثما يذهب ... ولم يكن يرى الرب وهو معه . ولكن من المريح للنفس أن يشعر الإنسان بهذا ، ويوقن به ، فيحيا فى اطمئنان دائم وفى فرح ...","ولم يكن هذا الأمر ميزة لأبينا يعقوب فقط ، بل أن الرب يقول « ها أنا معكم كل الأيام وإلى انقضاء الدهر » (متى ٢٨ : ٢٠) .",{h:"إن شعورنا بوجود الله معنا ، يشعرنا بقوة إلهية ترافقنا وتحفظنا ."},"هذه القوة هى العاملة فيك ومعك منذ أن تدخل فى شركة الروح القدس ، فيشترك الروح القدس معك فى العمل . وهكذا فى الكنيسة الأولى كنا نرى أن ملكوت الله قد أتى بقوة (مر ٩ : ١) ، « وبقوة عظيمة كان الرسل يؤدون الشهادة"],29:["بقيامة الرب يسوع ، ونعمة عظيمة كانت على جميعهم » (أع ٤ : ٢٣) . قيل عن القديس اسطفانوس أول الشمامسة إنه كان « مملوءاً إيماناً وقوة » (أع ٦ : ٨) ، وإنه وقف ضد عدة مجامع « ولم يقدروا أن يقاوموا الحكمة والروح الذى كان يتكلم به » (أع ٦ : ١٠) . هذه هى القوة فى الإيمان . أما الذى يؤمن ، ولكنه يخاف من إعلان إيمانه ، فهو إنسان ضعيف الإيمان ، لا يؤمن بقوة الله العامل معه .","المرأة نازفة الدم ، كانت تشعر أنها لو لمست ولو هدب ثوب المسيح ، ستخرج قوة من المسيح تشفيها . وقد كان (متى ٢٠ : ٢١ ، لو ٨ : ٤٦) .",{h:"وأنت إن آمنت بقوة الرب ، والتصقت به ، ستنالها ."},"ليكن لك هذا الإيمان وهذا الشعور ، فى كل تفاصيل حياتك : فى خدمتك وفى صلاتك ، وفى عملك . كما قال القديس أنطونيوس عن أبا مقار الكبير « إن قوة عظيمة تخرج من هاتين اليدين » .",{h:"حتى فى حالة سقوطك : آمن أن هناك قوة ستخلصك ."},"إن كنت أنت أضعف من الشياطين ، آمن أن الله الذى يحبك هو أقوى منهم ، وهو قادر أن يخلصك من الخطية ، وفى قوة إيمان تضرع إلى الله أن يمنحك القوة التى تنتصر بها فى حياتك الروحية ، واطلب إليه أنه هو « يقودك فى موكب نصرته » (٢كو ٢ : ١٤) .","حتى إن طالت بك المدة ، آمن أن قوة الرب ستصلك ولو فى المزيع الأخير ، لكى تنقذك . قوة الرب هذه غير مرئية ، ولكنها موجودة ، ومستعدة أن تعمل مع كل الذين يطلبونها مؤمنين .","عليك أن تبصر أن هذه القوة تصحبك ، ليس فى حياة التوبة فقط ، إنما فى كل نواحى حياتك الروحية ... حتى إن تكلمت ، يشعر الناس بقوة الكلمة ومفعولها ...",{h:"إن المؤمن هو إنسان قوى ، يؤمن بقوة الله العاملة فيه ."},"هوذا القديس بولس الرسول يقول « أتعب أيضاً مجاهداً ، بحسب عمله الذى يعمل فىّ بقوة » (كو ١ : ٢٩) . ويقول أيضاً عن الله « القادر أن يفعل فوق كل شىء ، أكثر جداً مما نطلب أو نفتكر ، بحسب القوة التى تعمل فينا » (أف ٣ : ٢٠) ."],30:["وبفضل هذا الإيمان بقوة الله العاملة ، التى قد لا نراها ولكن نؤمن بها ، عاش القديس بولس فى ملء الثقة ، وأمكنه أن يقول :",{h:"« أستطيع كل شىء فى المسيح الذى يقوينى » (فى ٤ : ١٣)"},"عبارة كلها قوة ، وكلها إيمان ، وكلها ثقة بعمل الله . ونحن نسأل : هل هذه العبارة هى من شأن قديس عظيم فقط مثل بولس الرسول ؟ فيجيبنا الرب نفسه « كل شىء مستطاع للمؤمن » (مر ٩ : ٢٣) .","لعل هذه القوة هى اختبار لحياتنا الروحية : هل نحن فى الإيمان ؟","إنها قوة نسعد بها فى حياتنا ، ونحيا مطمئنين .","فى حياتنا أيضاً داخل الكنيسة ، نسعد بأمور كثيرة لا ترى ...",{h:"١٢ ـ من الأمور التى لا ترى ، ما يحدث فى المعمودية :"},"يقول بولس الرسول « لأن جميعكم الذين اعتمدتم للمسيح ، قد لبستم المسيح » (غل ٣ : ٢٧) . حقاً ما أعجب هذا السر ! من رآه ؟ ! إنه من الأمور التى لا ترى . وقال حنانيا الدمشقى لشاول الطرسوسى « أيها الأخ شاول ... لماذا تتوانى ؟ قم اعتمد واغسل خطاياك » (أع ٢٢ : ١٦) . من رأى هذه الخطايا وهى تغسل ؟ إنها أمور لا ترى ، نقبلها بالإيمان ، كما قال الرسول « بمقتضى رحمته خلصنا ، بغسل الميلاد الثانى » (تى ٣ : ٥) . هذا الخلاص الذى ننلناه فى غسل الميلاد الثانى ، أمر لم نره ، ولكننا نؤمن به حسب قول الرب « من آمن واعتمد ، خلص » (مر ١٦ : ١٦) .","ثم ما معنى هذا الميلاد الثانى ؟ وما معنى الولادة من فوق ، والولادة من الله . والولادة من الماء والروح ؟ كل هذه التى تحدث عنها الرب بنفسه (يو ٣ : ٣ ـ ٦) . كلها أمور لا ترى فعملية الولادة من الله سرّ لا يرى . نحن نرى الإنسان يغطس فى جرن المعمودية . ولكننا لا نرى كيف يولد من الروح . وطوبى لمن آمن دون أن يرى . لذلك حسن أن الكنيسة أطلقت على هذا الأمر إسم (سر) .","أتريد أن تدخل العقل هنا ؟ العقل قاصر عن أن يدخل ."],31:["يقول الرسول « مدفونين معه بالمعمودية ، التى فيها أقتم أيضاً معه ... مسامحاً لكم بجميع خطاياكم » (كو ٢ : ١٢) . ويقول نفس المعنى فى الرسالة إلى رومية ، ويضيف بأن إنساننا العتيق قد صلب معه ، وأننا نسلك فى جدة الحياة (رو ٦ : ٣ ـ ٦) . فمن رأى هذا الموت وهذا الدفن ، والقيامة ، والمسامحة بالخطايا ، والحياة الجديدة ، وصلب الإنسان العتيق ... إنها كلها أمور لا ترى . ولكن نؤمن بها ...",{h:"١٣ ـ سر الأفخارستيا أيضاً ، هو من الأمور التى لا ترى :"},"فيه ترى بالإيمان أن الخبز والخمر اللذين أمامك قد صارا جسد الرب ودمه (بعد صلاة التقديس) . هنا لا تجعل حواسك تحكم ، لأن الحواس الجسدية لا تبصر سوى الأمور التى ترى . أما الحواس الروحية فتستمع إلى قول المسيح « هذا هو جسدى ... هذا هو دمى » (متى ٢٦ : ٢٦ ، ٢٨) ، « من يأكل جسدى ويشرب دمى ، فله حياة أبدية ... لأن جسدى مأكل حق ، ودمى مشرب حق . من يأكل جسدى ويشرب دمى ، يثبت فىّ وأنا فيه » (يو ٦ : ٥٣ ـ ٥٦) .",{h:"أنا لا أجادل الرب فيما يقوله ، إنما أتقبله فى إيمان ."},"فهذا هو الإيمان « الإيقان بأمور لا ترى » . أما التى تُرى فهى الخبز والخمر . وهكذا يقول القديس بولس الرسول « كأس البركة التى نباركها ، أليست هى شركة دم المسيح . الخبز الذى نكسره ، أليس هو شركة جسد المسيح » (١كو ١٠ : ١٦) . ويقول أيضاً « إذن أى من أكل هذا الخبز ، أو شرب كأس الرب ، بدون استحقاق ، يكون مجرماً فى جسد الرب ودمه ... يأكل ويشرب دينونة لنفسه ، غير مميز جسد الرب » (١كو ١١ : ٢٧ ، ٢٩) .","وكيف نميز أن هذا جسد الرب ، حتى لا ننال دينونة ؟",{h:"هنا نرتفع فوق مستوى الحواس ، وفوق مستوى العقل ، بالإيمان ."},"عقولنا هى التى تتعبنا حينما نتقبل أسرار الكنيسة . وحواسنا تتعبنا أيضاً . ونحتاج إلى بساطة الإيمان . نصدق ما قاله المسيح . ونصدق ما قاله رسوله القديس بولس الرسول ولا نجادل ."],32:[{h:"١٤ ـ وبالإيمان بما لا يرى نتقبل ما فى المسيحية من أسرار :"},"نتقبل (وضع اليد) الذى ناله برنابا وشاول من الرسل ، لكى يفرزا للخدمة (أع ١٣ : ٢ ، ٣) . ووضع اليد الذى ناله تيموثاوس من بولس الرسول (٢تى ١ : ٦) . ونوقن أن فى ذلك سراً .","ونتقبل السلطان الذى أعطاه الرب بقوله « إقبلوا الروح القدس . من غفرتم خطاياه تغفر له . ومن أمسكتم خطاياه أمسكت » (يو ٢٠ : ١٣) ، « كل ما تربطونه على الأرض يكون مربوطاً فى السماء وكل ما تحلونه على الأرض يكون محلولاً فى السماء » (متى ١٨ : ١٨) .","هذا السلطان غير مرئى ، ولكنه سر نراه بالإيمان . إنه ليس لكل أحد ، ولا يأخذه أحد من نفسه بل المدعو من الله كما هرون (عب ٥ : ٤) .","وهكذا فى باقى الأسرار التى لا نراها ، ولكن نؤمن بها ...",{h:"إن رؤية ما لا يرى ، هى الرؤية الروحية الحقيقية :"},"لعلها هى التى عناها رب المجد بقوله لتلاميذه القديسين « أما أنتم فطوبى لعيونكم لأنها تبصر » (متى ١٣ : ١٦) . تبصر ماذا ؟ تبصر المسيح وعجائبه . وأيضاً تبصر ما لا يرى ، مثلما أبصر القديس يوحنا رؤياه العجيبة . ومثلما أبصر القديس بولس السماء الثالثة وكثرة من الإستعلانات (٢كو ١٢ : ٢ ، ٧) ، أمور « لا ينطق بها ، ولا يسوغ لإنسان أن يتكلم عنها » (٢كو ١٢ : ٢) .","أما أولئك الذين لم تكن لهم هذه الحاسية الروحية ، فقد وبخهم الرب بقوله « أغمضوا عيونهم لئلا يبصروا » (متى ١٣ : ١٥) . وكرر رسوله عنهم نفس التعبير (أع ٢٨ : ٢٧) . وعبارة أغمضوها قد تعنى أنهم لم يدربوا نفوسهم على رؤية الروحيات . أو أنهم رفضوا أن يروا الروحيات من فرط انشغالهم بالماديات .","كان جيحزى لا يبصر ما يبصره معلمه أليشع (٢مل ٦ : ١٧) . وأيضاً مثلها كان مرافقو شاول الطرسوسى فى وقت الرؤيا الإلهية ، وقد قال عنهم الكتاب « وقفوا صامتين ، يسمعون الصوت ، ولا ينظرون أحداً » (أع ٩ : ٧) ."],33:[{h:"الفصل الثالث"},{h:"درجات وأنواع من الإيمان"},"« كما قسم الله لكل واحد نصيباً من الإيمان » (رو ١٢ : ٣) ."],34:[{h:"درجات من الإيمان :"},"يختلف الناس فى نوعية إيمانهم ودرجته حسبما « قسّم الله لكل واحد نصيباً من الإيمان » (رو ١٢ : ٣) .","وقد يبالغ البعض ، وإذ يجد إنسان ناقصاً فى إيمانه ، يقول عنه إنه غير مؤمن على الإطلاق . وهذا الحكم ضد تعليم الكتاب المقدس كما سنرى . والبعض قد يخلط بين كلمة (المؤمنين) وكلمة (المختارين) ، كما لو كانتا تدلان على معنى واحد .","فلنتأمل إذن أنواع الإيمان ودرجاته :","١ ـ هناك نوع « حديث الإيمان » وهذا قد أمر الرسول بعدم سيامته فى درجة الأسقفية « لئلا يتصلف » (١تى ٣ : ٦) .","٢ ـ وهناك نوع « قليل الإيمان » أو « ضعيف الإيمان » .","وسنضرب أمثلة من الإنجيل لهذا النوع :","أ ـ الذين يشكون فى عناية الرب بهم فى المأكل أو الملبس . هؤلاء ضرب الرب لهم مثلاً بزنابق الحقل التى ولا سليمان فى كل مجده كان يلبس كواحدة منها . ثم وبخهم قائلاً « فإن كان عشب الحقل الذى يوجد اليوم ويطرح غداً فى التنور ، يلبسه الله هكذا ، أفليس بالحرى يلبسكم أنتم يا قليلى الإيمان ؟ ! » (متى ٦ : ٢٨ ـ ٣٠ ، لو ١٢ : ٢٨) .","ب ـ كذلك وبخ التلاميذ لما فكروا أنهم لم يأخذوا معهم خبزاً ، فانتهرهم قائلاً « يا قليلى الإيمان » (متى ١٦ : ٨) .","ج ـ ووبخ الرب القديس بطرس لما خاف بعدما مشى معه على الماء فبدأ يغرق . حينئذ أمسكه الرب قائلاً له « يا قليل الإيمان ، لماذا شككت ؟ » (متى ١٤ : ٣١) .","د ـ وبالمثل وبخ التلاميذ لما خافوا حينما غطت الأمواج السفينة أثناء نومه فيها . حينئذ قال لهم « ما بالكم خائفين يا قليلى الإيمان » (متى ٨ : ٢٦) ."],35:[{h:"إذن الخوف ، والشك فى معونة الله دليلان على قلة الإيمان ."},"هـ ـ وقد ضرب الرسول مثلاً فى ضعف الإيمان بالأخ الذى يعثر من أكل ما ذبح للأوثان . وأمر بأن ضعيف الإيمان لا يجوز إدانته ولا الإزدراء به ، وقال « هو لمولاه : يثبت أو يسقط . ولكنه سيثبت لأن الله قادر أن يثبته » (رو ١٤ : ١ ـ ٤) .","هنا ويعجبنى والد الطفل المصروع ، لما سأله الرب « أتؤمن ؟ » لكى يشفيه . حينئذ أجاب « أؤمن يارب . أعن عدم إيمانى » (مر ٩ : ٢٤) .","إن الإيمان الضعيف يحتاج إلى من يصلى لأجله ، لكى يعينه الرب . ولا يجب مطلقاً أن نزدرى به . فالله قادر أن يثبته .",{h:"٣ ـ هناك نوع ثالث : هو الإيمان المحدود :"},"ونقصد به الذى يؤمن بالرب فى حدود معينة ، ولا يصل إيمانه إلى ما هو أبعد منه ... مثال ذلك مريم ومرثا ، اللتان كانتا تؤمنان أن الرب يقدر أن يشفى أخاهما من المرض فلا يموت . أما إن مات ، فقد كانت إقامته من الأموات أمراً لم يكن إيمانها قد وصل إليه .","لذلك كل منها قالت للرب « لو كنت ههنا ، لم يمت أخى » (يو ١١ : ٢١ ، ٣٢) . ولما قال الرب لمرثا « سيقوم أخوك » أجابته « أنا أعلم أنه سيقوم فى القيامة فى اليوم الأخير » (يو ١١ : ٢٤) . ولما ذهب الرب إلى القبر وقال « إرفعوا الحجر » ، قالت مرثا « يا سيد قد أنتن ، لأن له أربعة أيام » (يو ١١ : ٣٩) .",{h:"إن الله لم يرفض هذا الإيمان المحدود ، إنما أعطاه فرصة لينمو ."},"لذلك قال لمرثا « من آمن بى ، ولو مات فسيحيا » . ووبخها عند القبر قائلاً « ألم أقل لك إن آمنت ترين مجد الله » (يو ١١ : ٢٥ ، ٤٠) . وأعطاها فرصة أن ترى مجد الله فى إقامة أخيها لعازر ، لتؤمن ، وليؤمن أيضاً اليهود الذين شهدوا المعجزة .",{h:"وهنا كان الإيمان لاحقاً للمعجزة ، وليس سابقاً لها ."},"وربما كان ذلك لأن تلك المعجزة كانت الأولى من نوعها ، أى إقامة ميت بعد"],36:["أربعة أيام من موته ، بعد أن أنتن .","٤ ـ نوع رابع ، من الإيمان الضعيف ، هو البطء القلب فى الإيمان . وربما يكون عن بطء فى الفهم ، أو عن عدم إدراك ، فلا يأتى إيمانه سريعاً . وكان هذا هو نوعية إيمان تلميذى عمواس من جهة قيامة الرب . ولذلك وبخهما قائلاً « أيها الغبيان والبطيئا القلوب فى الإيمان بجميع ما تكلم به الأنبياء . أما كان ينبغى أن المسيح يتألم ... » (لو ٢٤ : ٢٥ ، ٢٦) . ثم بدأ يشرح لهما الأمور المختصة به فى جميع الكتب ... لكى يؤمنا ، أو لكى يعالج هذا البطء فى إيمانها ، الناتج عن عدم فهم أو عدم معرفة .","وفى هذا المثال أيضاً نقول : إن علاج الأخطاء الخاصة بالإيمان ، هو الوضع السليم . وهذا أفضل من الإزدراء أو التحقير الذى لا يأتى بنتيجة ولا يوصل إلى الإيمان السليم .",{h:"٥ ـ وهناك حالة خطيرة هى الإيمان الميت :"},"فقد قال القديس يعقوب الرسول « الإيمان بدون أعمال ميت » (يع ٢ : ٢٠ ، ١٧) . وقال إن مثل هذا الإيمان لا يقدر أن يخلص صاحبه (يع ٢ : ١٤) . ورأى أن الإيمان الحى ينبغى أن تكون له أعمال تدل عليه ، فقال « أنا أريك بأعمالى إيمانى » (يع ٢ : ١٨) .",{h:"٦ ـ هناك أيضاً إيمان غير ثابت :"},"مثال ذلك أن السيد المسيح (قبيل القبض عليه) قال لتلميذه بطرس « هوذا الشيطان طلبكم لكى يغربلكم كالحنطة . ولكنى طلبت من أجلك ، لكى لا يفنى إيمانك » (لو ٢٢ : ٢١ ، ٢٢) .","فى ذلك الوقت إهتز إيمان بطرس ، لكنه عاد بعدئذ إلى قوته الأولى .","٧ ـ وهناك حالات وصفها الكتاب بأنها خروج عن الإيمان السليم . ومنها :","أ ـ قال القديس بولس الرسول « إن كان أحد لا يعتنى بخاصته ، ولاسيما أهل بيته ، فقد أنكر الإيمان ، وهو شر من غير المؤمن » (١تى ٥ : ٨) ."],37:["ب ـ وقال عن الأرامل الحدثات اللائى يرجعن فى نذرهن للبتولية « أرفضهن ، لأنهن متى بطرن على المسيح ، يردن أن يتزوجن . ولهن دينونة ، لأنهن رفضن الإيمان الأول » (١تى ٥ : ١٢) .","ج ـ وقال كذلك « محبة المال أصل لكل الشرور . الذى إذا ابتغاه قوم ، ضلوا عن الإيمان ، وطعنوا أنفسهم بأوجاع كثيرة » (١تى ٦ : ١٠) .","د ـ وقال « إحفظ الوديعة ، معرضاً عن الكلام الباطل الدنس ... الذى إذ تظاهر به قوم ، زاغوا من جهة الإيمان » (١تى ٦ : ٢١) .",{h:"هل بعد هذه الأمثلة نستطيع أن ننكر علاقة الإيمان بالأعمال ؟ !"},"لأنه هنا بعمل خاطىء يقال إن إنساناً أنكر الإيمان ، أو رفض الإيمان ، أو ضل أو زاغ عن الإيمان ... لعلنا بأمثال هذه المقاييس نمتحن أنفسنا ، عملاً بقول الرسول « إختبروا أنفسكم : هل أنتم فى الإيمان » (٢كو ١٣ : ٥) .",{h:"٨ ـ أخطر حالة هى « الإرتداد عن الإيمان » :"},"يقول الرسول « فى الأزمنة الأخيرة يرتد قوم عن الإيمان تابعين أرواحاً مضلة » (١تى ٤ : ١) . وعبارة الإرتداد عن الإيمان ، تعنى أنهم كانوا فى الإيمان ثم ارتدوا","ويتحدث الرسول عن الإرتداد العظيم الذى يسبق مجىء المسيح فيقول إنه « لا يأتى إن لم يأتِ الإرتداد أولاً » (٢تس ٢ : ٣) .","هذا من الجهة العامة ، أما عن الناحية الفردية فيقول « أما البار فبالإيمان يحيا . وإن ارتد لا تسرّ به نفسى » (عب ١٠ : ٣٨) . وهنا يتكلم عن ارتداد إنسان مؤمن بار كان بالإيمان يحيا .",{h:"مادام المؤمن يمكن أن يرتد ، إذن المؤمنون هم غير المختارين . فالمختارون يبقون على إيمانهم كل حياتهم ، حتى ملاقاة الرب ..."},"كل ما ذكرناه فى الأنواع السابقة ، هو عن السلبيات فى الإيمان . نتابع كلامنا إذن عن الإيجابيات الإيمانية ."],38:[{h:"٩ ـ النمو فى الإيمان :"},"يقول القديس بولس لأهل تسالونيكى « نشكر الله كل حين من جهتكم أيها الأخوة ... لأن إيمانكم ينمو كثيراً » (٢تس ١ : ٣) . وقال عن أهل كورنثوس إنهم يزدادون فى الإيمان (٢كو ٨ : ٧) .","إذن الإيمان فضيلة كسائر الفضائل ، يمكن أن ينمو فيها الإنسان ...",{h:"١٠ ـ حفظ الإيمان والثبات فيه :"},"يقول الرسول عن نفسه فى أواخر حياته ، ووقت انحلاله قد حضر « ... أكملت السعى ، حفظت الإيمان . وأخيراً وضع لى إكليل البر » (٢تى ٤ : ٧ ، ٨) .","ويقول لأهل كولوسى « ... ليحضركم قديسين وبلا لوم ولا شكوى أمامه ، إن ثبتم على الإيمان ... » (كو ١ : ٢٣) .","وأقوى من الثبات فى الإيمان ، تعبير آخر هو :",{h:"١١ ـ الرسوخ فى الإيمان :"},"يقول القديس بطرس الرسول عن محاربات إبليس « ... فقاوموه راسخين فى الإيمان » (١بط ٥ : ٩) .","وهناك درجة أخرى من الإيمان هى :",{h:"١٢ ـ الغنى فى الإيمان :"},"يقول القديس يعقوب الرسول « أما اختار الله فقراء العالم أغنياء فى الإيمان ، وورثة الملكوت الذى وعد به الذين يحبونه » (يع ٢ : ٥) .","وهناك درجة أزيد من الغنى فى الإيمان وهى :",{h:"١٣ ـ الإمتلاء من الإيمان :"},"قيل عن القديس اسطفانوس أول الشمامسة « فاختاروا اسطفانوس رجلاً مملوءاً من الإيمان والروح القدس » ، « وأما اسطفانوس فإذ كان مملوءاً إيماناً وقوة ، كان يصنع عجائب وآيات عظيمة ... » (أع ٦ : ٥ ، ٨) .","كل هذه الصفات تقال عن حالة لازمة للإيمان هى :"],39:[{h:"١٤ ـ الإيمان العامل بالمحبة :"},"يقول القديس بولس الرسول « فى المسيح يسوع ، لا الختان ينفع شيئاً ولا الغرلة ، بل الإيمان العامل بالمحبة » (غل ٥ : ٦) .","ولعله ذكر عبارة الإيمان العامل ، لأن الإيمان بدون أعمال ميت (يع ٢ : ٢٠) . أما عبارة المحبة ، فلأنه بها يتعلق الناموس كله والأنبياء (متى ٢٢ : ٤٠) .","وهناك نوع عظيم من الإيمان هو :",{h:"١٥ ـ الإيمان الذى يصنع العجائب :"},"تحدث السيد الرب عن « آيات تتبع المؤمنين » (مر ١٦ : ١٧) . وقال القديس يعقوب الرسول « صلاة الإيمان تشفى المريض » (يع ٥ : ١٥) .","ولكن لعل قمة هذا الأمر تبدو فى قول الرب « كل شىء مستطاع للمؤمن » (مر ٩ : ٢٢) .","ولعل هناك نوعاً آخر ، ليس لصانع الأعجوبة ، إنما للذى يتقبلها وهو :",{h:"١٦ ـ إيمان الثقة والتصديق :"},"وهو الذى كان يتطلبه الرب ممن تحدث معه المعجزة . وأحياناً يسأله « أتؤمن ؟ » . وكما قال للأعميين اللذين طلبا منه الشفاء « أتؤمنان أنى أقدر أن أفعل هذا ؟ » (متى ٩ : ٢٨) .","وقد طوّب الرب هذا النوع من الإيمان ، مثلما قال للمرأة الكنعانية « عظيم هو إيمانك » (متى ١٥ : ٢٨) . ومثلما قال عن قائد المائة « لم أجد ولا فى اسرائيل إيماناً بمقدار هذا » (متى ٨ : ١٠) .",{h:"١٧ ـ كل الإيمان :"},"يقول القديس بولس الرسول « إن كان لى كل الإيمان حتى أنقل الجبال ... » فاعتبر أن هذا الإيمان الذى ينقل الجبال ، هو كل الإيمان ، أى قمته ، ولا شىء بعده ."],40:[{h:"أنواع من الإيمان :"},"هناك فرق كبير بين نوعين من الإيمان : إيمان نظرى ، وإيمان عملى .",{h:"١ ـ الإيمان النظرى (العقلى) :"},"هو إيمان فكرى ، فلسفى . مجرد الإقتناع العقلى بوجود الله ، وبوجود الأمور التى لا ترى دون أن يكون لذلك أى تأثير على الحياة . وهناك نص يثبت أن الشياطين لهم هذا النوع من الإيمان . إذ يقول القديس يعقوب الرسول عن الإيمان الميت ، الخالى من الأعمال :",{h:"« أنت تؤمن أن الله واحد . حسناً تفعل . والشياطين يؤمنون ويقشعرون » (يع ٢ : ١٩) ."},"وسفر أيوب يعطينا دليلاً عملياً على هذه النقطة . لأن حديث الشيطان مع الله تبارك إسمه يثبت هذا الإيمان النظرى ، إذ يقول الشيطان للرب « هل مجاناً يتقى أيوب الله ؟ أليس أنك سيجت حوله ... باركت أعمال يديه . ولكن إبسط الآن يدك ومس كل ماله ، فإنه فى وجهك يجدف عليك » (أى ١ : ٩ ـ ١١) . ولما أخذ إذناً من الله للتصرف ، ذهب ليعمل ضد أيوب . وفى المرة الثانية قال أيضاً للرب « ... ولكن الآن إبسط يدك ومس عظمه ولحمه ، فإنه فى وجهك يجدف عليك » (أى ٢ : ٥) .","وهذا الكلام كله يثبت أن الشيطان يؤمن عقلياً بأن هذا هو الله ، وأنه هو الذى بارك أعمال أيوب ، وهو القادر أن يمس ماله ، وأن يمس لحمه وعظمه . وأن أى عبارة تصدر من أيوب ضد الله تعتبر تجديفاً على الله ...","ومع كل هذا ، كان الشيطان يحارب ملكوت الله وأولاده ، ولا يزال .",{h:"إيمان الشيطان العقلى الذى تحدث عنه معلمنا يعقوب ، هو أيضاً إيمان ميت ، حسب قول الرسول نفسه « إيمان بدون أعمال ميت » (يع ٢ : ٢٠) . فإن كان الإيمان الخالى من الأعمال الصالحة إيماناً ميتاً ، فكم بالأكثر المشحون بالأعمال الردية ومقاومة كل صلاح أياً كان ..."},{h:"إن الإيمان العقلى سهل . ما أسهل إثبات وجود الله بالأدلة العقلية وبالبراهين"}],41:["العديدة . المهم هو الإيمان العملى .","هذا يقودنا إلى النوع الهام من الإيمان ، وهو :",{h:"٢ ـ الإيمان العملى :"},"هو الإيمان الذى تظهر علاماته فى الحياة العملية ، حياة إنسان يؤمن أن الله كائن أمامه ، يراه ويحسه ، ويتصرف بما يليق بهذا الإيمان . وهو يحب هذا الإله الذى يؤمن بوجوده وبعنايته ورعايته وحفظه ، ويكلم هذا الإله المحبوب فى صلواته وتضرعاته ، ويخشى أن يفعل شيئاً يجرح قلبه المحب ... وفى اطمئنانه لعمله لا يخاف ولا يضطرب ، بل يحيا فى سلام دائم ، مسلماً حياته كلها لتدبيره الحكيم ...",{h:"وهكذا يقوده الإيمان إلى عديد من الفضائل لا تحصى ."},"وهذا النوع من الإيمان سيكون موضوع كتابنا هذا بمشيئة الرب ، حيث سنشرح كيف يقود الإيمان حياتنا كلها لتصبح حياة الإيمان .","وهذا المفهوم ينقلنا إلى صفة أخرى من صفات الإيمان السليم وهى :",{h:"٣ ـ إيمان دائم :"},"ونعنى به أنه لا يكون إله مناسبات . فلا يظهر إيماننا فقط حينما نكون فى الكنيسة أو فى اجتماع روحى ، أو حينما نصلى ، أو نقرأ الكتاب ، أو نتقدم للتناول . وإنما يظهر هذا الإيمان فى كل وقت ، وكل مكان ، فى خارج الكنيسة كما فى داخلها . الله أمامنا باستمرار ، وفى فكرنا باستمرار ، بإيمان لا يتغير . إنه ليس فقط إله الكنائس وإله الكتاب ، إنما هو إله القلب والفكر جميعاً ، وإله الحياة كلها .",{h:"٤ ـ إيمان دون أن يرى :"},"إيمان لا يعتمد على الحواس ، وينطبق عليه قول الرب « طوبى للذين آمنوا دون أن يروا » (يو ٢٠ : ٢٩) . ليس مثل العلماء الذين لا يؤمنون بشىء ، إلا إذا أحضروه فى معاملهم ، وتيقنوا منه بأبصارهم وأجهزتهم . وليس مثل الصدوقيين الذين أنكروا وجود الملائكة والقيامة والأرواح (أع ٢٣ : ٨) ، لأنهم لا يرون شيئاً من ذلك كله ..."],42:[{h:"٥ ـ إيمان الثقة والإختبار :"},"إنه ليس الإيمان بالله الذى نقرأ عنه فى كتب اللاهوت ، أو فى المعاهد الدينية ، أو فى الكنائس وفى فصول التعليم الدينى على أنواعها . وإنما إيمان بالله الذى اختبرناه فى حياتنا ، وعاشرناه ، وأدخلناه فى كل تفاصيل حياتنا ، واختبرنا عملياً قول داود النبى « ذوقوا وانظروا ما أطيب الرب » (مز ٣٤ : ٨) ... ووجدنا أن الله عجيب عجيب ، إلى أبعد الحدود ، فوق ما يتصور العقل ... حياتنا كلها مجرد عشرة معه ، ذقنا فيها حلاوته وحبه ورعايته . ورأينا أيضاً قوته وجلاله . وجربنا كيف يدخل فى مشاكلنا ويحلها ، بطرق ما كانت تخطر على عقولنا .","ونتيجة للإختبار ، صارت لنا ثقة ، غير مبنية على الكتب ، وإنما على ما لمسناه بأيدينا ... لذلك إيماننا إيمان حقيقى راسخ فى قلوبنا .",{h:"٦ ـ إيمان قوى :"},"وهو الإيمان الذى يستطيع كل شىء (مر ٩ : ٢٣) . ويمكنه أن ينتصر على كل عقبة . ولا يرى أمامه شيئاً مستحيلاً . بل كما قيل عن زربابل « من أنت أيها الجبل العظيم ؟ ! أمام زربابل تصير سهلاً » (زك ٤ : ٧) .","إنه الإيمان الذى يستطيع أن يضع قدمه فى الماء ، لكى يعبر البحر الأحمر فى أيام موسى النبى (خر ١٤ : ٢٢) ، وأن يعبر نهر الأردن فى أيام يشوع (يش ٣) . ويستطيع أن يمشى فى داخل الغمر العظيم ، والمياه تحيط به مثل سور ، عن يمين وعن شمال ، دون أن يخاف ...","إنه الإيمان الذى يستطيع أن يضرب الصخرة فيتفجر منها الماء (خر ١٧ : ٦) . وهو الإيمان الذى يسير فى الصحراء بلا زاد وبلا مرشد ، يجمع طعامه من المن النازل من السماء يوماً بيوم (خر ١٦ : ٢١) . وترشده السحابة نهاراً ، وعمود النار ليلاً (عد ٩ : ١٥ ـ ٢٣) .","إنه الإيمان القوى الذى استطاع أن ينقل الجبل المقطم على يد سمعان الدباغ ، أيام البابا ابرآم بن زرعه ."],43:["وهو الإيمان القوى الذى استطاع به إيليا النبى أن يقول « لا يكون طلّ ولا مطر فى هذه السنين إلا عند قولى » (١مل ١٧ : ١) . وهكذا « لم تمطر على الأرض ثلاث سنين وستة أشهر . ثم صلى فأعطت السماء مطراً » (يع ٥ : ١٧ ، ١٨) . وهكذا استطاع أن يغلق السماء ويفتحها .","ما أكثر الأمثلة عن هذا الإيمان القوى . ولكن هناك أمثلة أخرى عن هذا الإيمان القوى ، تبدو فى مظهر آخر هو :",{h:"٧ ـ إيمان لا يتزعزع :"},"إنه إيمان ثابت ، لا يتأثر مطلقاً بالعوامل الخارجية : فهو يؤمن بمحبة الله سواء كان على جبل التجلى أو على جبل الجلجثة .","يؤمن بمحبة الله الذى يعطيه من سارة نسلاً فى ظروف تدعو إلى اليأس ، تماماً كما يؤمن بمحبة الله وهو يقول له : خذ إبنك وحيدك الذى تحبه إسحق ، وأصعده هناك محرقة على الجبل الذى أريك إياه (تك ٢٢ : ٢) .",{h:"إن إبراهيم وهو يرفع بيده السكين على إبنه اسحق ، ما كان يشك مطلقاً فى محبة الله ، ولا فى صدق مواعيده ..."},"لم يتزعزع إيمانه مطلقاً فى هذا الإله ، ولا فى أنه سيكون له من اسحق نسلاً مثل نجوم السماء ورمل البحر فى الكثرة ...","إن الإيمان الثابت لا يتغير بالظروف الخارجية المحيطة به ، لأن ثقته ثابتة فى الله ، وسلامه القلبى لا يستمده من الظروف الخارجية ، إنما من الله نفسه ومحبته وصدق مواعيده .",{h:"٨ ـ الإيمان كموهبة :"},"هناك إيمان عادى ، وإيمان يعتبر موهبة من الروح القدس . ولا شك أن هذا له درجة عالية تفوق الإيمان العادى بكثير ...","يقول القديس بولس الرسول فى حديثه عن المواهب « فأنواع مواهب موجودة ، ولكن الروح واحد ... ولكنه لكل واحد يعطى إظهار الروح للمنفعة . فإنه لواحد"],44:["يعطى بالروح كلام حكمة ... ولآخر إيمان بالروح الواحد . ولآخر مواهب شفاء بالروح الواحد ... » (١كو ١٢ : ٤ ـ ٩) .","وهكذا أيضاً وضع الإيمان ضمن ثمار الروح (غل ٥ : ٢٢) .","ويبدو هنا أننا لا نستطيع أن نفصل الإيمان عن عمل الروح القدس : إما من ثمار الروح ، وإما من مواهب الروح . ولكل منها درجته ...",{h:"٩ ـ الإيمان السليم :"},"ما أكثر ما يؤمن الناس بأفكار ، أو مذاهب ، سياسية أو اجتماعية ، ويعطيهم إيمانهم بها قوة على التنفيذ ، وعلى نقلها إلى عقول الناس ...","ولكننا نود فى هذه الصفحات أن نتحدث عن الإيمان السليم ، الذى يكون له طابع روحى وصلة وطيدة بالله « الإيمان العديم الرياء » (١تى ٢ : ٥) ، « الإيمان المسلّم مرة للقديسين » (يه ٣) ... هذا الإيمان الطاهر النقى فكراً وسلوكاً . وهذا يجعلنا نقول :",{h:"إن الإيمان ، ليس هو مجرد عقيدة ، إنما هو حياة ... أو هو حياة مؤسسة على عقيدة . أو هو عقيدة إختبارية عاشها الناس ، وليست مجرد أفكار فى الكتب ."},"وما نريد أن نتحدث عنه فى هذا الكتاب هو هذه الحياة ، حياة الإيمان ..."],45:[{h:"الفصل الرابع"},{h:"علاقة الإيمان بالسلام وعدم الخوف"}],46:["من صفات المؤمن ، أن يكون قلبه مملوءاً بالسلام والهدوء . لا يضطرب مطلقاً ، ولا يقلق ، ولا يخاف ، لأنه يؤمن بحماية الله له ... وهو يحتفظ بسلامه الداخلى ، مهما كانت الظروف الخارجية تبدو مزعجة .","يخاف الشخص الذى يشعر أنه واقف وحده . أما الذى يؤمن أن الله معه فلا يخاف ...","١ ـ هوذا داود النبى يقول « إن يحاربنى جيش ، فلن يخاف قلبى . وإن قام علىّ قتال ، ففى هذا أنا مطمئن » (مز ٢٧ : ٣) . وإن سألته عن السبب فى هذا ، يجيب فى نفس المزمور « الرب نورى وخلاصى ، ممن أخاف ؟ ! الرب حصن حياتى ، ممن أرتعب » (مز ٢٧ : ١) . لقد اختبر الرب ومعونته وحمايته ، فقال عندما اقترب إلىّ الأشرار ليأكلوا لحمى ، مضايقى وأعدائى عثروا وسقطوا » (مز ٢٧ : ٢) .",{h:"إنه لا يستمد سلامه من تحسن الظروف الخارجية من حوله ، إنما يستمد سلامه من عمل الله فيها ومعه ."},"لذلك فهو يقول فى مزمور الراعى « إن سرت فى وادى ظل الموت ، لا أخاف شراً » لماذا ؟ « لأنك أنت معى » (مز ٢٣ : ٤) .","إن كان لك هذا الإيمان ، أن الله معك ، فلن تخاف ، مهما حاربك جيش ، أو قام عليك قتال ، حتى إن سرت فى وادى ظل الموت .",{h:"٢ ـ ولعل هذا السلام وعدم الخوف ، نراهما فى مقابلة إيليا النبى لآخاب :"},"كان آخاب الملك يفتش عن إيليا النبى فى كل مكان لكى يقتله . ومع ذلك فإن إيليا ذهب ليتراءى لآخاب . ولما حذره عوبديا من الخطر ، أجاب إيليا « حى هو رب الجنود الذى أنا واقف أمامه ، إنى اليوم أتراءى له » (١مل ١٧ : ١٤ ، ١٥) . وقد كان . قابل إيليا آخاب الملك ، ولم يخف منه . بل وبخه على عبادته للأصنام (١مل ١٧ : ١٨) . إيليا لم يكن يخاف ، لإيمانه أنه واقف أمام رب الجنود ."],47:[{h:"٣ ـ وبالمثل كان داود فى لقائه مع جليات الجبار :"},"داود ـ الصبى الصغير ـ كان بالإيمان مملوءاً بالسلام لا يخاف جليات ، بل يتكلم بثقة ... ويقول لشاول الملك « لا يسقط قلب أحد بسببه » (١صم ١٧ : ٣٢) . أما الملك وكل جيشه فكانوا خائفين ، ومرتاعين جداً . لأنهم لم يكونوا ناظرين إلى الله الذى لا يرى ... بل كانوا مركزين أبصارهم فى هذا الذى يرونه أمامهم « الرجل الصاعد » الذى « طوله ست أذرع وشبر ، وقناة رمحه كنول النساجين ، ووزن درعه خمسة آلاف شاقل نحاس » (١صم ١٧ : ٤ ـ ٧) .","داود رجل الإيمان ، لما دخل إلى ميدان المعركة أدخل الله معه ، وأدخل روح الإيمان والإطمئنان إلى قلوب رجال الحرب بقوله « من هو هذا الأغلف حتى يعير صفوف الله الحى ... لا يسقط قلب أحد بسببه » (١صم ١٧ : ٢٦ ، ٣٢) . وقال لذلك الجبار « أنت تأتى إلىّ بسيف ورمح . وأنا آتى إليك باسم رب الجنود » (١صم ١٧ : ٤٥) . أعنى : أنت تأتى إلىّ بالأمور التى ترى ، وأنا آتى إليك بالذى لا يرى .",{h:"وسنلاحظ أن إسم الله لم يفارق لسان داود . وكان يمنحه سلاماً"},"وبهذا الإيمان ، وهذا السلام القلبى ، وبهذه الثقة تقدم داود إلى ذلك الجبار المرعب ، وقال له فى يقين الإيمان « اليوم يحبسك الرب فى يدى ... فتعلم كل الأرض أنه يوجد إله ... لأن الحرب للرب » (١صم ١٧ : ٤٦ ، ٤٧) .","حقاً إن الرجل المؤمن لا يعرف الخوف ، مهما كانت الظروف مخيفة من حوله ... سلامه القلبى لا يفارقه مطلقاً ... بل يمنحه الإيمان أيضاً شجاعة وبسالة .",{h:"٤ ـ فى وسط الضيقة ، أياً كانت ، نرى الإيمان يعطى سلاماً ."},"ضيقة تحل بإثنين : أحدهما مؤمن والآخر غير مؤمن . فيضطرب غير المؤمن ويخاف ويقلق ، ويتصور أسوأ النتائج ، وتزعجه الأفكار ... أما المؤمن فيلاقيها بكل اطمئنان ، وبسلام قلبى عجيب . وقد يسأله البعض عن شعوره إزاء الضيقة فيقول « هذه المشكلة ، سيتدخل الله فيها ويحلها ، وستؤول إلى الخير » . وقد تسأله كيف سيتدخل الله ؟ وكيف سيحلها ؟ فيجيبك : أنا لا أعرف . ولا يهمنى هذا . إنما أعرف أننا لا نهتم بمشاكلنا ، فالله هو المهتم بالكل ..."],48:[{h:"حقاً إنى لا أعرف كيف ستحل المشكلة . ولكنى أعرف الله الذى سيحلها ."},"وهكذا يقوده الإيمان إلى الإطمئنان . وهكذا أولاد الله يعيشون دائماً فى سلام ، بل وفى فرح ، شاعرين أن الله معهم ، هو الذى يتولى كل أمورهم ، ويعمل من أجلهم ما لا يستطيعون عمله لأجل أنفسهم ...",{h:"٥ ـ إن يونان ـ حتى وهو فى بطن الحوت ـ لم يفقد إيمانه وسلامه ."},"بل إنه صلى إلى الرب وهو فى بطن الحوت ، صلاة كلها إيمان ، وقال فى ثقة « ولكننى أعود أنظر هيكل قدسك » (يون ٢ : ٤) . ونذر للرب نذراً وقال : « أما أنا فبصوت الحمد أذبح لك . وأوفى بما نذرته . للرب الخلاص » (يون ٢ : ٩) .","حتى وهو فى بطن الحوت ، كان يرى خلاص الرب . وكان يرى أنه سيخرج منه ، ويرى الهيكل المقدس ، ويذبح للرب ويوفى نذوره .","إنه الإيمان مصدر كل سلام وراحة . لا خوف فيه ولا قلق .",{h:"٦ ـ فإذا قلّ الإيمان ، حينئذ يخاف الإنسان ."},"بطرس فى إيمانه استطاع أن يمشى مع الرب فوق الماء ، ناسياً كل قوانين الجاذبية . فلما تذكرها وخاف حينئذ سقط ، فوبخه الرب قائلاً « يا قليل الإيمان لماذا شككت » (متى ١٤ : ٣١) .","وهكذا ربط الرب بين الخوف والشك وقلة الإيمان . وحقاً إنه ترابط عجيب :",{h:"الشك يضعف الإيمان . وضعف الإيمان يؤدى إلى الخوف . والخوف يسبب السقوط ."},"وبنفس الوضع نتحدث عن التلاميذ لما هاجت عليهم الأمواج فى السفينة . رؤيتهم الأمواج تغطى السفينة ، بينما الرب نائم فيها ، جعلتهم يشكون فى اهتمام الرب بهم . والشك أضعف إيمانهم ، فخافوا . لذلك وبخهم الرب قائلاً « ما بالكم خائفين يا قليلى الإيمان » (متى ٨ : ٢٦) .",{h:"فى كل مرة تخاف ، وبخ نفسك على قلة إيمانك ."},"قل لنفسك أين هو إيمانى بأن الله موجود ، وبأنه ضابط الكل يرى كل شىء ؟"],49:["وأين إيمانى بمحبة الله ، وبتدخله فى مشاكلى ، وبقدرته على كل شىء ، وأين إيمانى بأن الله صانع الخيرات ، وبأنه لا بد سيصنع معى خيراً ؟ !","هذه الأفكار كلها تقوى إيمانك ، وتمنحك سلاماً ، وثقة بعمل الله .",{h:"الإيمان مريح للنفس . لأن الذى يؤمن بوجود الله ، لا يشعر بالوحدة . بل يثق أن هناك قوة إلى جواره"},"إنه يؤمن بوجود هذه القوة القادرة على كل شىء ، التى تسانده ، والتى كلها حب وعدل . وهى تعمل لخير الجميع ، وتتراءف على كل من هو فى ضيقة ... وإذ يطمئن إلى هذه القوة الإلهية الحافظة ، يمتلىء قلبه سلاماً ، ولا يقلق ولا يخاف ... أما غير المؤمن ، فإذ لا يثق بقوة خفية تسنده ، نراه يتعب ، ويقف وحيداً فى ضيقاته فاقداً للسلام ...",{h:"٧ ـ القديس بطرس كان فى السجن ، وقد نام نوماً ثقيلاً ."},"مع أن هيرودس الملك ، لكى يرضى اليهود ، كان قد قتل القديس يعقوب بن زبدى أحد الإثنى عشر ، وأمر بالقبض على القديس بطرس وألقاه فى السجن « مسلماً إياه إلى أربعة أرابع من العسكر ليحرسوه » . وكان مزمعاً قتله بعد الفصح (أع ١٢ : ١ ـ ٤) .","وعلى الرغم من السجن ، ومن الحراسة المشددة ، ومن توقع القتل ... نام بطرس فى السجن ، واثقاً من وجود حراسة إلهية تحرسه ، أكثر من حراسة العسكر عليه . وكان نوماً ثقيلاً ، لدرجة أن الملاك الذى أتى لينقذه ، ضربه فى جنبه ليوقظه (أع ١٢ : ٧) ...","أى سلام قلبى هذا ، الذى يجعل إنساناً فى مثل هذه الظروف ينام ، وهو فى السجن ، وفى نفس الليلة التى كان فيها هيرودس الملك مزمعاً أن يقدمه للقتل ... !",{h:"إنه الإيمان بحفظ الله ، إن أراد له حياة على الأرض ... أو الإيمان بالأبدية السعيدة ، إن شاء الله له أن يستشهد ."},"وفى كلتى الحالتين ، الأمر يدعو إلى الفرح . لذلك كان السلام يملأ قلبه . وكان ينام فى هدوء . وما كانت الأمور الخارجية تزعجه ...","ولعله كان هناك سبب آخر لهذا السلام ، وهو أنه « كان بطرس محروساً فى"],50:["السجن . وأما الكنيسة فكانت تصير منها صلاة بلجاجة إلى الله من أجله » (أع ١٢ : ٥) .",{h:"الإنسان المؤمن هو الذى يستطيع أن ينام فى حضن الله ويستريح ."},"إنه يسلم حياته وكل مشاكله للرب . ويقول للرب : ما دمت أنت قد استلمت هذه الموضوعات ، فأنا سوف لا أشغل نفسى بها . إنها قد انتهت بالنسبة إلىّ ، وانتقلت إلى يديك أنت ، وأنا واثق أنك ستصنع كل خير . أما أنا فمطمئن إلى عملك ، وسأنام وأستريح . لذلك حسناً قيل فى المزمور إنه « يعطى أحباءه نوماً » (مز ١٢٧ : ٢) .",{h:"٨ ـ دانيال النبى والثلاثة فتية ، مثال للإيمان المملوء بالسلام ."},"دانيال كان ينتظر أن يلقى فى جب الأسود ، ومع ذلك لم يفقد سلامه ، ولم يفقد أيضاً شجاعته . واحتفظ بإيمانه ، وصلى إلى الله إلهه بكل مجاهرة ، وبلا خوف .","فى جب الأسود ، كان قلب دانيال أقوى من قلوب جميع الأسود التى معه ... وكأنه يقول : وماذا إن ألقونى فى جب الأسود ؟ أليس الرب هناك أيضاً . أوليس هناك ملاكه يسد أفواه الأسود ...","وكذلك الثلاثة فتية ما خافوا من أتون النار .","لا شك أن الإيمان يخلق فى القلب كل شجاعة وجرأة ، وينزع منه كل خوف .",{h:"٩ ـ وهكذا كان القديسون فى طريقهم إلى الإستشهاد ."},"كانوا يغنون أغانى الفرح ، ويسبحون الله ، وهم فى طريقهم إلى الموت . وما كان الموت يزعجهم ، ولا العذاب . كان إيمانهم بالحياة الأخرى ، وبالأبدية السعيدة ، وبعشرة الرب فى الفردوس ، كل ذلك كان يملأهم سلاماً بل وفرحاً ، بل أيضاً اشتياقاً إلى الموت ، مغنين مع بولس الرسول « لى اشتهاء أن أنطلق وأكون مع المسيح . فذاك أفضل جداً » (فى ٢ : ٢٣) .","إن الموت لا يخيف المؤمن ، بل يفرحه ...",{h:"١٠ ـ فى كل ضيقة وصعوبة وعقبة ، المؤمن لا يخاف ، ولا يفقد سلامه ."},"المؤمن ينتصر على العقبات ، دون أن يخاف منها . يشعر أن الله سيحل"],51:["الصعوبات التى تصادفه ، ولا يتركه وحده فيها .","أما غير المؤمن فربما الصعوبات تصيبه بالتردد والخوف . وبعدم إيمانه يجبن . بل عدم الإيمان قد يصور له صعاباً ومخاوف غير موجودة ، كأن « الأسد فى الطريق . الشبل فى الشوارع » (أم ٢٦ : ١٣) .","أما المؤمن فلا يخاف مطلقاً مهما صادفته المصاعب والمتاعب . إنه يلاقيها كلها فى هدوء وفى اطمئنان واثقاً بعمل الله معه .",{h:"١١ ـ بهذا الإيمان والإطمئنان ، وقف القديس أثناسيوس يحارب الأريوسية ."},"بكل ما كان للأريوسية من صلة بالإمبراطور ، وتأثير عليه وعلى حاشيته . بل بكل ما كان لها أيضاً من تضليل للشعب ، وضغط على الأساقفة وإقناع لبعضهم ، وإثارة جو عام من الشك . حتى قيل لهذا البابا المؤمن :",{h:"[ العالم كله ضدك يا أثناسيوس ] فأجاب [ وأنا أيضاً ضد العالم ]"},"وهكذا لم ترهبه قرارات النفى من الأباطرة ، ولا قرارات الحرم من بعض الأساقفة ، ولا الشكوك المنتشرة فى كل مكان ، ولا الإتهامات الباطلة التى يلصقونها به . وإنما ظل يطوف من بلد إلى بلد ، بكل ثقة ، يعلم ويقنع ، ويزيل الشكوك ، ويثبت الناس فى الإيمان ، ويكتب الردود والمقالات ، ويدحض براهين الأريوسيين ... إلى أن انتصر أخيراً ، وانتصر الإيمان على يديه . وقال القديس جيروم :",{h:"[ مر وقت ، كاد فيه العالم كله أن يصبح أريوسياً ، لولا أثناسيوس ]"},"هذا هو الإيمان الذى لا يعرف خوفاً ولا اضطراباً ، ولا تهزه الأحداث ، بل يحتفظ بسلامه وسط النيران المتقدة إلى أن يطفئها الله ...","إن إيمان القديس أثناسيوس بالعقيدة التى كان يدافع عنها ، منحه قوة جبارة ، وقف بها ضد جميع المقاومات . وكل قوة أثناسيوس ، إنما تكمن فى إيمانه ، الإيمان الذى يستطيع أن يصنع الأعاجيب .",{h:"١٢ ـ بالإيمان بشر أناس بالمسيح فى بلاد تأكل لحوم البشر ولم يخافوا ."},"ودخلوا فى مجاهل أفريقيا ، وفى الغابات ، وفى مناطق خطرة حتى من جهة"],52:["طبيعتها ومناخها وطبائع أهلها . ولم يخافوا . إيمانهم بالله الحافظ لهم ، أعطاهم قوة وشجاعة . وكذلك إيمانهم بخيرية وأهمية العمل الذى يقومون به ، أهمية أن يوصلوا كلمة الله للنفوس التى هناك حتى لا تهلك فى عدم إيمان . كل هذا أعطاهم قوة ، ونزع الخوف من قلوبهم ، فتمموا عملهم ، ولم تثنهم عنه الغربة ، ولا قسوة المناخ ، ولا وحشية الناس ، ولا خطورة الطبيعة ...",{h:"١٣ ـ بالإيمان أخذ أبونا نوح معه الوحوش فى الفلك ولم يخف ."},"مادام الله قد قال له خذها معك اثنين اثنين ، إذن فسيأخذها . والله الذى أصدر الأمر سيحفظه منها . وستكون معه كما كانت مع آدم فى الفردوس ، يعيش معها بلا خوف ، وبكل سلام فى القلب ... وقد كان .","أبونا نوح كان مؤمناً بكلمة الله له ، لذلك لم يخف .",{h:"١٤ ـ بل إن كل من آمن بفكرة ، يعطيه الإيمان بها قوة لتنفيذها ."},"وهكذا كان المصلحون فى كل زمان ومكان . آمنوا بفكرة ، فجاهدوا بكل قوة لتنفيذها . وبسبب إيمانهم احتملوا الكثير من الضيق ، حتى أكملوا عملهم .","غاندى مثلاً آمن بحق الإنسان فى الحرية ، وآمن بسياسة عدم العنف . وأعطاه هذا الإيمان قوة عجيبة إستطاع بها أن يحرر الهند ، وأن يعطى الحقوق للمنبوذين متساوين مع إخوتهم . واستطاع أن يحتمل الكثير لكى لا يسلك أتباعه بعنف ، ولا يلاقون العنف بالعنف . إيمانه بالفكرة أعطاه القوة على تنفيذها ، فكم بالأكثر بما لا يقاس : الإيمان بالله .",{h:"١٥ ـ بل حق الإيمان بالعلم يصنع الأعاجيب . مثال ذلك رواد الفضاء ."},"وأقصد كمثال إيمانهم بما قيل لهم عن منطقة إنعدام الوزن . وكيف أن الإنسان فيها يمكن أن يمشى فى الجو دون أن يسقط . من من الناس يجرؤ أن يمشى فى الجو دون أن يخاف . أما الذى جعلهم ينفذون ذلك فهو إيمانهم الأكيد ببحوث العلماء الذين قالوا بهذا . والإيمان يعطى قوة وشجاعة . فكم بالأكثر الإيمان بالله .",{h:"إن الفرق بين أشجع الناس وأخوف الناس ، هو الإيمان ."},"إن الشخص الجرىء هو الذى لديه إيمان ، بأنه لن يحدث له ضرر ما ، أو هو"],53:["المؤمن بلزوم عمله وضرورته مهما حدث له ، أو هو المؤمن بصفة الشجاعة وعدم الخوف . أما الجبان فهو على عكس هذا كله .",{h:"١٦ ـ أيضاً الإيمان بالأبدية ، يعطى الإنسان راحة وسلاماً ."},"إذ يوقن أنه لا بد سينال حقه ، إن لم يكن على الأرض ، ففى السماء . ولا يكن مظلوماً هنا وهناك . كذلك سينال سعادته كاملة : مالم يتحقق منها هنا ، سيتحقق بكل تأكيد فى النعيم الأبدى . وهكذا يعيش مرتاحاً ، ولو كان مثل لعازر المسكين .",{h:"١٧ ـ الإيمان بقوة الصليب وعلامة الصليب ، يمنع الخوف ."},"الذى يؤمن بالصليب وقوة الصليب وعلامة الصليب ، كثيراً ما يشعر باطمئنان إذ يحتمى وراء هذا الصليب .","فإن تعرض لخوف أو خطر ، ورشم ذاته بعلامة الصليب ، يمتلىء قلبه سلاماً ، ويحس أن قوة تحميه ، وتمنع عنه الخوف ، ويحس أن قلبه دخلته قوة لم تكن فيه من قبل . وصارت له علامة الصليب سلاحاً .",{h:"وهناك إنسان آخر له إيمان كبير بفاعلية المزامير ."},"يتلوها فى أى وقت ، أو فى وقت الحاجة ، فيشعر أن المزمور فيه قوة خاصة ، تطمئن قلبه وتمنحه سلاماً . فإن كان خائفاً مثلاً ، وتلا مزمور ٩١ (الساكن فى ستر العلى) ، أو ٢٣ (الرب يرعانى) ، أو ٢٧ (الرب نورى وخلاصى) ... للوقت يشعر بسلام داخله ، وبأن قوة المزمور قد حلت عليه .","نحن نعرف أن المزامير قد قيلت بالروح (متى ٢٢ : ٤٣ ، ٤٤) . وأنها كجزء من الكتاب ، قالها داود مسوقاً بالروح القدس (٢بط ١ : ٢١) . لذلك لها قوة بلا شك .",{h:"آخرون لهم إيمان فى أرواح القديسين وعملها لأجلهم ."},"لذلك يشعرون بسلام ، حينما يطلبون صلاة ومعونة قديس يحبونه ويثقون بدالته عند الله .","أذكر بهذه المناسبة راهباً أثيوبياً متوحداً ، كان يعيش فى مغارة فى وادى"],54:["النطرون . فى إحدى المرات ضلّ طريقه بالليل ، إذ كان يشكو وقتذاك من ضعف فى بصره . وأقبل عليه الليل والظلام . فرسم دائرة واسعة على أرض الصحراء ، وحوّطها بعلامة الصليب من كل ناحية ، ونام داخلها . وفى الصباح رأى آثار الدبيب والحيوانات خارج الدائرة ، ولم تستطع أن تدخلها لتؤذيه .","أتذكر منذ زمن طويل ، أننى كنت مسافراً فى سفينة ، وقد هاجت الأمواج جداً عليها ، وخاف الركاب . ونظرت فرأيت من بين الركاب معنا إنساناً طيباً جداً كنت أثق كثيراً بقداسته . فاطمأن قلبى . وقلت فى داخلى « من المحال أن يسمح الله بغرق السفينة ، وفى داخلها هذا الإنسان الطيب الذى يحب الله » . ونجت السفينه فعلاً ، ولم يحدث لها أى ضرر .","لقد كان مجرد وجود هذا الإنسان الطيب سبباً فى السلام وتقوية الإيمان . وربما كان هذا شعور ركاب آخرين ...","إن القصص الإختبارية فى هذا المجال ، لا تدخل تحت حصر . وكلها تقوى الإيمان . ولكنى لست أرى الآن مجالها ...","نكتفى بهذا الجزء وندخل فى علامة أخرى من علامات الإيمان ..."],55:[{h:"الفصل الخامس"},{h:"علاقة الإيمان بنقاوة القلب"}],56:[{h:"لا شك أنك تخجل أن تخطىء أمام إنسان بار تحترمه ."},"وقد تكون فى حضرته فى منتهى الحرص ، تستحى من أن ترتكب شيئاً مشيناً أمامه . لا تحب أن يأخذ عنك فكرة سيئة ، أو أن تسقط من نظره ... بل قد تحترس أيضاً من الخطأ أمام أحد خدمك أو مرءوسيك ، لئلا يحتقرك فى داخله ، أو يقل احترامه لك ...",{h:"لذلك ففالبية الخطايا تعمل فى الخفاء ، إما بسبب الخوف أو بسبب الإستحياء ."},"وهكذا قيل عن الخطاة إنهم « أحبوا الظلمة أكثر من النور ، لأن أعمالهم شريرة » (يو ٣ : ١٩) . وقال الرب عن أعدائه المتآمرين عليه « هذه ساعتكم وسلطان الظلام » (لو ٢٢ : ٥٣) .",{h:"فإن كنت تخجل أو تخاف من إنسان يراك ، فكم بالأولى الله ؟ !"},"فإن آمنت تماماً بأن الله موجود فى كل مكان أنت فيه ، يراك ويسمعك ويرقبك ، فلا شك سوف تخجل أو تخاف من أن ترتكب أى خطأ ... أمام الله . ولهذا فإن القديس يوسف الصديق عندما عرضت عليه الخطية ، رفض الخطية قائلاً :",{h:"« كيف أفعل هذا الشر العظيم ، وأخطىء إلى الله » (تك ٣٩ : ٩) ."},"إعتبر أنه خطأ إلى الله . كسر لوصاياه . وعدم احترام له ، إذ يفعل الشر قدامه بلا حياء ... فهل عندك هذا الشعور ؟ هل تضع الله أمامك فى كل خطية تحارب بارتكابها . وهل تذكر ما قاله الرب لكل ملاك من ملائكة الكنائس السبع (فى سفر الرؤيا) . إذ قال لكل منهم :",{h:"« أنا عارف أعمالك » (رؤ ٢ : ٢ ، ٩ ، ١٣ ، ١٩ ، رؤ ٣ : ١ ، ٨ ، ١٥) ."},"لو عرفت هذا ستخجل وتخاف ، وتمتنع عن الخطية ، لأن خوف الله سيكون أمام عينيك باستمرار فى كل مرة تحاول فيها أن تخطىء",{h:"بل إنك تشعر بالاستحياء من أرواح الملائكة والقديسين ."},"إن كنت تؤمن من كل قلبك أن ملائكة الله حالة حولنا (مز ٣٤ : ٧) . وأننا « صرنا منظراً للعالم ، للملائكة والناس » (١كو ٤ : ٩) ... حينئذ لابد ستخجل"],57:["من الملاك الذى حولك ، والذى لقداسته لا يحتمل رؤية بعض الخطايا فيتركك ... وكذلك لابد ستخجل من أرواح القديسين ومن أرواح أقربائك ومعارفك ... وبهذا الخجل تبعد عن الخطية ، وتقترب إلى حياة النقاوة .",{h:"وإن كنت تؤمن أن الله قدوس ، ستخشى أن تظهر نجاساتك أمام هذه القداسة غير المحدودة ."},"وفى كل مرة تقول فى صلاتك « قدوس قدوس قدوس » ستشعر فى داخلك بخزى عظيم على الماضى ، ولا تجرؤ على ارتكاب الخطية فى المستقبل . إن اشعياء النبى عندما سمع السارافيم يسبحون الرب بهذه التسبحة « قدوس ... » صرخ قائلاً « ويل لى قد هلكت . لأنى إنسان نجس الشفتين ... » (اش ٦ : ٣ ، ٤) .",{h:"إن كنت تؤمن أن الله فاحص القلوب وقارىء الأفكار ..."},"وأنه يعلم كل ما يخطر على فكرك وفى قلبك من مشاعر وخطط وتدابير ، حينئذ كنت تخاف من معرفته لدواخلك وتخجل من قدسيته ، وتبتعد عن هذه الأفكار والمشاعر ، فتصل إلى حياة النقاوة .",{h:"ولعلك تقول :"},"أنا أؤمن بكل هذا : أؤمن أن الله موجود ، وأنه يرى كل شىء ويسمع ، وأنه يفحص القلوب ويقرأ الأفكار ... ومع ذلك أنا لا أزال فى أخطائى ... أجيبك على هذا بأنه :",{h:"ربما تؤمن بكل هذا نظرياً . ولكنك لا تحيا حياة تليق بإيمانك ... !"},"إن الذى يحيا فى هذا الإيمان بأن الله يراه ، والملائكة تراه ، وأرواح المنتقلين تراه ... عملياً لو وضع هذا الفكر فى قلبه ، لكان يخجل ، وتصغر نفسه فى عينيه ، ولا يجرؤ أن يكمل خطاياه . ولكن على رأى أحد الآباء ـ كما ورد فى بستان الرهبان ـ كل خطية يسبقها إما الشهوة ، أو التهاون ، أو النسيان .",{h:"لعل الإنسان يكون أثناء الخطية ناسياً الله وملكوته ."},"ولعله يكون ناسياً أنه صورة الله ومثاله ، إن كان يؤمن حقاً بهذا . ولعله يكون ناسياً أيضاً كل وصايا الله ، وكل إنذاراته ، مع أنه نظرياً يؤمن بكل هذا ، ولكن لا يحياه . هو كما قلنا : له إسم المؤمن ، وليس له حياة المؤمن ..."],58:[{h:"لذلك : إن كنت تؤمن بالأبدية ، فضع الأبدية أمامك لكى لا تخطىء ."},"إن الذى يؤمن حقاً بأن الموت يأتى كلص (١تس ٥ : ٢) ، والذى يؤمن بأن الله عادل . وقد قال إنه سيأتى ليجازى كل واحد حسب أعماله (رؤ ٢٢ : ١٢) ، والذى يؤمن بالحياة بعد الموت ، والدينونة ، والثواب والعقاب ، والوقوف أمام الله فى ذلك اليوم الرهيب الذى فيه تفتح الأسفار ، وتكشف النيات والأفكار ، وتعلن كل أعمال بنى البشر أمام الكل ... الذى يؤمن بهذا حقاً ، إيماناً عملياً ، من الصعب عليه أن يخطىء ، بل يجد رادعاً داخله يثنيه ، خوفاً وخجلاً ... وتراه دائماً يستعد للملاقاة الرب فى ذلك اليوم ...","ولماذا أتكلم عن الدينونة ، إنى أقول من ناحية أخرى :",{h:"إن كنت تؤمن بمحبة الله ، فإنك تخجل أن تجرح محبته ."},"كثيراً ما تقول « الله محبة » (١يو ٤ : ٨ ، ١٦) . ولكنك أثناء الخطية ، لا تكون فى حالة إيمان عملى بمحبته . بل ربما لا تكون هذه المحبة فى فكرك إطلاقاً .","إن كنت تؤمن حقاً بأن المحبة هى الرباط المقدس الذى يربطك بالله ، فكيف يمكن أن تخطىء ؟ ! « المولود من الله لا يخطىء » (١يو ٣ : ٩) .",{h:"بل أنت لا تخطىء ، إن كنت تؤمن بالفضيلة كمنهج حياة ."},"كثيرون يتحدثون عن الفضيلة ، ويدعون الآخرين إليها ، ويمجدونها كثيراً . ولكنهم لا يحبونها . لا يؤمنون عملياً فى أعماقهم بأن تكون الفضيلة هى منهج حياة لهم . وإن آمنوا بذلك عملياً ، لعاشوا فى حياة النقاوة ، مبكتين أنفسهم بشدة على كل ضعف ...",{h:"أيضاً الذى يؤمن بفناء هذا العالم ، يزهده ولا يخطىء ."},"مثلما كان يقول داود النبى « غريب أنا على الأرض ، فلا تخف عنى وصاياك » (مز ١١٩ : ١٩) ، « غريب أنا عندك ، نزيل مثل جميع آبائى » (مز ٣٩ : ١٢) . وهكذا عاش رجال الإيمان فى كل جيل « أقروا إنهم غرباء ونزلاء على الأرض ... يبتغون وطناً أفضل ... سماوياً » (عب ١١ : ١٣ ، ١٦) ... زهدوا كل شىء فى هذه الدنيا ، وأطاعوا قول الرسول « لا تحبوا العالم ولا الأشياء التى فى العالم ... لأن العالم يمضى وشهوته معه » (١يو ٢ : ١٥ ، ١٧) ."],59:[{h:"وبهذا الإيمان عاشوا فى العالم ، دون أن يعيش العالم فيهم ."},"وكان هؤلاء « الذين يستعملون العالم ، كأنهم لا يستعملونه » (١كو ٧ : ٣١) . وبهذا الإيمان ـ على نطاق أكبر ـ عاش الرهبان والمتوحدون وسكان الجبال فى زهد ونسك « وهم لم يكن العالم مستحقاً لهم ، تائهين فى برارى وجبال وشقوق الأرض » (عب ١١ : ٣٨) . وشُهد لهم بالإيمان ...","هكذا يفعل الإيمان ، فى تنقية القلب . وكما قال الرسول :",{h:"« هذه هى الغلبة التى تغلب العالم ، إيماننا » (١يو ٥ : ٤) ."},"إيماننا بأن نعيش على الأرض « غير ناظرين إلى الأشياء التى تُرى ، بل إلى التى لا تُرى . لأن التى ترى وقتية ، أما التى لا ترى فأبدية » (٢كو ٤ : ١٨) . نعم إن الإيمان بفناء العالم ، هو الذى يجعلنا نغلب العالم ، ونتنقى من العالم وما فيه .",{h:"إن الإيمان بالأبدية ، يعطى الإنسان يقظة فى ضميره ."},"وهكذا يكون له باستمرار ضمير حىّ : يحكم على كل عمل ، ليس فقط من جهة نجاحه أو فشله ، أو من جهة نتائجه فى حياتنا الحالية ... إنما يحكم على الأمور بمنظار الأبدية ... لأن كل تصرف يتصرفه ، له دخله فى مصيره الأبدى ، وربما فى مصائر الناس ... فكل خير يعمله محفوظ له فى السماء . وكل خطأ يقترفه فى حق الناس أو فى حق نفسه ، سيعطى عنه حساباً فى يوم الدين .",{h:"وأيضاً الإيمان بوجود الله أمامنا ، يمنح القلب اتضاعاً ."},"يمنحه اتضاعاً فى القلب ، واتضاعاً فى التصرف ، ويمنحه خشية وخشوعاً لأنه واقف أمام الله . مثلما قيل عن القديس بطرس ، إذ كان يصيد (بعد القيامة) إنه لما عرف أن الرب قد أتى « ائتزر بثوبه ، لأنه كان عرياناً » (يو ٢١ : ٧) .","فى حضرة الرب يقف كل إنسان فى خشوع . وبقدر إحساسه بوجود الله ، على هذا القدر يكون خشوعه . وهكذا يختلف الناس فى شعورهم أثناء الصلاة ، فمنهم من يركع ومن يسجد ، أمام عظمة الله غير المحدودة ... أما الذى يكون جالساً أثناء الصلاة ، فماذا أقول عنه ؟ !","والإحساس الدائم بوجود الله ـ حتى فى غير وقت الصلاة ـ يجعل الإنسان فى"],60:["اتضاع دائم ، لأن العظمة هى لله وحده . وتعاظم الإنسان عمل ضد الإيمان ...",{h:"لذلك فنحن نرى الملائكة القديسين فى هذا الخشوع الدائم ."},"يقول الكتاب عن طغمة السارافيم « لكل واحد ستة أجنحة : باثنين يغطى وجهه ، وباثنين يغطى رجليه ، وباثنين يطير » (اش ٦ : ٢) . فإن كان الملاك الساراف ، يغطى وجهه ورجليه فى حضرة الله ، من بهاء عظمة الله ، فماذا نقول نحن ؟ وكيف ينبغى أن نكون خاشعين وفى اتضاع قدامه ...","إلى هذه الدرجة نرى الإيمان ينقى القلب ، ويمنحه خشية وحياء واتضاعاً ...",{h:"فالذى يؤمن بأهمية الله بالنسبة إليه ، يخشى من اقتراف الخطية ، لأنها انفصال عن الله . وما أخطر أن ينفصل إنسان عن الله ."},"أما الذى لا يؤمن بخطورة الخطية ، وبخطورة نتائجها الروحية ، فإنه يتساهل معها ويسقط ، ويفقد نقاوته . أنظر مدى شعور داود بخطورة الخطية حينما قال للرب « لك وحدك أخطأت ، والشر قدامك صنعت » (مز ٥١) . وانظروا إلى يوسف الصديق ، إذ يؤمن أنه حينما يخطىء إلى أحد ، إنما « يخطىء إلى الله » (تك ٣٩ : ٩) .","كل هذه المشاعر الإيمانية إما أنها تجعل الإنسان يمتنع عن الخطية مثل يوسف ، أو ينسحق بعدها مثل داود . وكلا الأمرين من علامات نقاوة القلب ."],61:[{h:"الفصل السادس"},{h:"بساطة الإيمان"}],62:[{h:"بساطة الإيمان ، كثير من المفكرين يشتهونها ولا يجدونها ."},"مرّ أحد الفلاسفة على فلاح بسيط ، يصلى فى حرارة شديدة وهو ساجد فى خشوع ، يكلم الله بلجاجة ودالة ، كأنه واقف أمامه ... فقال : أنا مستعد أن أتنازل عن كل فلسفتى ، مقابل أن أحصل على شىء من إيمان هذا الرجل البسيط ، الذى يكلّم من لا يراه ، بكل هذه الثقة ...","لقد شعر الفيلسوف بأن هذا الرجل البسيط ، يمتلك شيئاً ثميناً لم يستطع هو بكل فلسفته أن يحصل عليه ... وهو الإيمان .",{h:"بساطة الإيمان « تصدق كل شىء » يختص بالله ، وتقبله بلا فحص وبلا جدال ... أعنى ذلك الجدال الذى يشتهر به العقلانيون ..."},"وهذه البساطة تذكرنا بإيمان الأطفال ، الذين يؤمنون بكل الحقائق اللاهوتية والروحية ، فى ثقة كاملة لا تشك ولا تكذّب ، ولا تقدم أى اعتراض من العقل . ولعل هذا من الأسباب التى دعت السيد المسيح أن يقول لتلاميذه « إن لم ترجعوا وتصيروا مثل الأطفال ، فلن تدخلوا ملكوت السموات » (متى ١٨ : ٣) ... قد يكون إيمان الإنسان الكبير أكثر عمقاً . ولكن إيمان الطفل أكثر براءة وبساطة وصدقاً . إيمان حقيقى لا شك فيه . ليت إيمانك يكون قوياً ، كإيمان طفل .",{h:"أنا لست أوافق الذين يقولون إن الأطفال غير مؤمنين ..."},"هوذا بولس الرسول يقول لتلميذه تيموثاوس « إنك منذ الطفولية تعرف الكتب المقدسة القادرة أن تحكمك للخلاص ، بالإيمان الذى فى المسيح يسوع » (٢تى ٣ : ١٥) . وما أعظم امتداح الرب للطفل الذى أقامه وسط تلاميذه (متى ١٨ : ٢ ، ٣) .",{h:"الذى يسلك فى بساطة الإيمان ، يعيش بعيداً عن تعقيدات العقل ."},"ويعيش بعيداً عما يقدمه العقل من شكوك وأفكار ، وربما من أضاليل . حقاً إن العقل وزنة من الله . ولكنها كثيراً ما تضل إن بعدت عن الإيمان .",{h:"الإيمان هو نوع من التجلى ، يقدمه الله للعقل لكى يستنير ."}],63:["وإن وقف العقل وحده ، فإنه يتعب صاحبه بأفكاره ... لو كان الصبى داود يعتمد على عقله وفكره ، لخاف من جليات مثلما خاف شاول الملك وكل الجيش ... ولكنه اعتمد على الإيمان البسيط ، الذى قال به لجليات « اليوم يحبسك الرب فى يدى » (١صم ١٧ : ٤٦) . ولكن كيف يحبسه الرب فى يده ؟ هذا شىء لم يفكر فيه داود ، إنما تركه إلى الله نفسه ، لأن الحرب للرب كما قال (١صم ١٧ : ٤٦) ... هذا هو الإيمان . وبه انتصر داود ، أكثر من الذين كانوا يستخدمون العقل ميزاناً للأمور ...",{h:"فى الإيمان البسيط ، المسألة ليست مسألة تفكير ، إنما مسألة ثقة ."},"وحتى إن قال العقل إن الحرب لا بد أن تبحث ما مدى توازن القوى فى القتال ، وكيف تتفوق إحداها ؟ فالإجابة بسيطة : وهى أن الله إذا دخل المعركة ، فإنه سيغير الفكرة البشرية عن ميزان القوى ، فيصبح الطفل داود ومعه قوة الله ، أقوى بكثير من جليات الجبار بدون هذه القوة . وهنا نرى أن الإيمان ـ مع بساطته ـ لا يتعارض مع العقل وموازينه ...",{h:"الذى يحيا بالإيمان البسيط ، يعيش بلا همّ ."},"لأن الهمّ غالباً ما يأتى نتيجة التفكير الكثير ، الذى يفكر فى المشاكل بطريقة عقلانية . ولكن فى بساطة الإيمان يعمل الإنسان ما يستطيعه ، ويترك العنصر الأهم لله نفسه ، ولا يحمل هماً . وإيقانه بأن الله يعمل ، يعطيه سلاماً فى القلب ، ولا يسمح للهم بالسيطرة على مشاعره .","الذى له الإيمان البسيط لا يحمل هماً ، لأنه قد ترك تدبير أموره إلى الله . وإذ وثق بحسن تدبير الله لحياته ، صار لا يهتم بالغد ، لأن إله الغد هو المهتم به . وكل ما يحدث له فى حياته يتلقاه بعبارة « كله للخير » ، « كل الأشياء تعمل معاً للخير ، للذين يحبون الله » (رو ٨ : ٢٨) .","أما الذى يضع تفكيره مكان التدبير الإلهى ، فإنه يتعب كثيراً ، ويحمل همومه بدلاً من أن يحملها الله عنه .",{h:"كذلك مما ينزع الهمّ ، ثقة الإيمان البسيط باستجابة صلاته ."},"ولعلكم جميعكم تعرفون قصة تلك البلدة التى أتعبها الجفاف لعدم سقوط المطر ،"],64:["فقرر أهلها إقامة يوم للصلاة من أجل أن يسقط الله المطر على الأرض . ودعى الكل لكى يصلوا . ولكن طفلة ذهبت وهى تحمل معها مظلة (شمسية) . فلما سألوها عن ذلك ، قالت : ألسنا سنصلى من أجل المطر ؟ ماذا نفعل إذن ، حينما يستجيب الله صلاتنا ويسقط المطر ، وليست معنا شمسيات ؟ ! لقد كان لها الإيمان باستجابة الصلاة . ومن أجل إيمانها أنزل الله المطر ...",{h:"هذا الإيمان البسيط ، له قوته بالنسبة إلى المعجزات والرؤى"},"لقد تحدث المعجزة بالنسبة إلى شخص ، ولا تحدث بالنسبة إلى شخص آخر . لأن الأول فى بساطة الإيمان يصدقها ويقبلها . أما الآخر فإن الصعوبات التى يقدمها عقله ، تجعله يشك فى داخله من جهة إمكانية حدوثها .","ونفس الوضع يحدث بالنسبة للرؤى . البعض يرى المناظر الإلهية والإستعلانات ببساطة إيمانه . والبعض لا يراها بتعقيدات عقله . والأمر واضح جداً كما حدث فى ظهور السيدة العذراء بكنيستها فى الزيتون بالقاهرة .",{h:"العقل يحاول أن يحلل كل شىء علمياً ، وإلا فإنه لا يصدّق . بينما الإيمان يحتاج إلى تصديق ، فى بساطة ، بعيدة عن تعقيدات العقل ..."},"لذلك فالمعجزات والرؤى تحدث بالأكثر مع البسطاء . أما (العقلاء كثيراً ! !) الذين ينكرونها ويستهزئون بصدقها ، فإنها لا تحدث لهم إلا نادراً ، لكى تجذبهم إلى الإيمان ، أو لتكون شاهداً عليهم (يو ١٥ : ٢٢) .","إن اليهود لم يصدقوا حتى معجزة منح البصر للمولود أعمى ، وقالوا له إن الذى شفاه رجل خاطىء ! ! (يو ٩ : ٢٤) . كان العقل يضع أمامهم مشكلة الشفاء فى يوم السبت ، لكى يضيّع بها إيمانهم (يو ٩ : ١٦) .","لذلك حسناً قال السيد المسيح عن هؤلاء وأمثالهم ، وممجداً للبسطاء : « أحمدك أيها الآب ... لأنك أخفيت هذه عن الحكماء والفهماء ، وأعلنتها للأطفال » (متى ١١ : ٢٥) . حقاً هؤلاء الأطفال يقصد بهم البسطاء فى إيمانهم ... أما هؤلاء الحكماء والفهماء فى هذه الآية ، فهم المعتزون بإدراكهم وفهمهم ، والمعتمدون على عقلهم وحده ، بعيداً عن الإيمان ... حتى أن بعض الروحيين أمسك رأسه بين يديه"],65:["وقال : « إن هذه هى الثمرة التى أكل منها آدم وحواء » ... يقصد الثمرة البعيدة عن الله ...",{h:"فى إحدى الليالى ، قبل رهبنتى ، كنت راجعاً من زيارة أحد الآباء فى الجبل ."},"وكان الظلام قد انتشر ، فقيل لى « لا ترجع وحدك إلى الدير لئلا تضل الطريق » . وكنت أعرف الطريق جيداً ، وأؤمن بإرشاد الله فيه ، ومع ذلك قلت « إن ضللت طريق ، سأبيت فى الصحراء حتى الصباح . وكنت مؤمناً من أعماق بستر الله فى هذا ، وبخاصة لأن كثيراً من الأعراب يبيتون فى الصحراء بلا خوف ، ولكن قيل لى « إنك بسيط أزيد مما يجب ، ولا تعرف الجبل . لأن الجبل مملوء بالحشرات والدبيب ، وهناك خطر الوحوش أيضاً ، وأخطار أخرى من جهة الجو ... وظل (العقل) ينصب فى أذنى ، ليزيل ما فى قلبى من بساطة الإيمان ... ورجعت ليلتها إلى الدير مع أحد الآباء . ولم يعطنى (العقل) وقتذاك فرصة أختبر فيها عمل الله مع الساثرين ليلاً فى الصحراء ، ولا حتى اختبار إيمان الإعرابى الذى يبيت كل ليلة هناك ، وتبيت معه عناية الله وستره ...","أشكر الله أنى عوضت ذلك فيما بعد حينما سكنت فى الجبل وحدى .",{h:"إن العقل يمكنه أن يصور خطورة فى كل مكان . وفى نفس الوقت لا يعطى مجالاً للتفكير فى عمل الله ... وعلى العكس يطرح غير المؤمن فى عقدة الخوف ."},"ليس معنى هذا أن يلقى الإنسان بنفسه فى التهلكة ، بلا حكمة . وإنما إذا احترس بقدر طاقته ، ثم وجد نفسه فيما يسمونه خطراً ، فحينئذ بكل بساطة يثق فى حفظ الله وستره . ويغنى مع داود النبى « يسقط عن يسارك ألوف ، وعن يمينك ربوات . وأما أنت فلا يقتربون إليك » (مز ٩١) .",{h:"الإيمان البسيط يثق بأن يد الله تتدخل للإنقاذ ولحل كل مشكلة ."},"هو يثق تماماً أن الله كمحب للبشر ، وكصانع للخيرات ، لا بد سيتدخل فى المشكلة ـ حسب وعوده لأولاده ـ وتمتد يده لحلها","أما كيف يحدث هذا ؟ فهذا ما لا يسأل عنه الإيمان البسيط .",{h:"إنه يتقبل عمل النعمة فى بساطة ، دون أن يفحص كيف تعمل ."}],66:["وكم من مرة حاولنا أن نحل مشاكلنا بطرق بشرية . ثم فشلت هذه الطرق جميعها ، ولم تأت بنتيجة . وكانت بصمات الله واضحة ، فوق كل فكر .",{h:"الإيمان البسيط يثق بعمل الله ، عقيدياً ، وعن طريق الخبرة ."},"الإيمان يدخل الإنسان فى دائرة الإختبارات . والإختبارات تعمق الإيمان وتبنيه على أسس واقعية وليس على مجرد أسس نظرية . والإيمان والإختبار يقويان بعضهما بعضاً ... حتى يصل الإنسان إلى يقين بديهى وهو بساطة الإيمان .",{h:"الإيمان البسيط يثق أن كل شىء مستطاع ، وليس هناك مستحيل ."},"إنه يوقن تماماً أن الله قادر على كل شىء ، ولا يعسر عليه أمر (أى ٤٢ : ٢) . مهما كان صعب الفهم أو صعب الحدوث . إنه يؤمن بقول الرب « غير المستطاع عند الناس ، مستطاع عند الله » (لو ١٨ : ٢٧) .","وأنا لا تدهشنى عبارة « كل شىء مستطاع عند الله » إنما تذهلنى عبارة « كل شىء مستطاع للمؤمن » (مر ٩ : ٢٣) .",{h:"وهكذا فإن الإيمان البسيط الموقن بهذا ، يرتفع فوق كل الشكوك ."},"إنه إيمان قوى ، أقوى من كل شك . لأن الشكوك هى من عمل العقل ، والعقل معتز بمقاييسه . أما المؤمن فقد اجتاز مرحلة العقل ، وعاش فى مجال أعلى منها وأعمق . فأعلى من الشكوك توجد بساطة الإيمان .",{h:"مشكلة الدين ، أن البعض يحاول أحياناً أن يحوله إلى فلسفة ، وأن يخرجه من القلب ، ومن الروح ليحصره فى نطاق العقل ."},"وهذا هو الأمر الذى حاربه القديس بولس الرسول بكل قوته ، فقال إن كرازته كانت « لا بحكمة كلام ، لئلا يتعطل صليب المسيح ... » (١كو ١ : ١٧ ـ ٢٠) .","يقيناً أن المؤمن البسيط ، الذى يكتنز إيمانه فى أعماقه ، فوق مستوى الفحص ، هو أقوى إيماناً من بعض علماء اللاهوت ، الذين يستمدون إيمانهم من الكتب التى يظنون أن لهم فيها حياة ... وقد يكون إيماناً يمكن أن تزعزعه أفكار عقلية مضادة ...",{h:"درّب نفسك على حياة الإيمان البسيط . وانتفع بما مرّ فى حياتك أو حياة غيرك من خبرات . ولا تجعل كثرة التفكير تبعدك عن الإيمان !"}],67:[{h:"الفصل السابع"},{h:"طاعة الإيمان أو حياة التسليم"}],68:["إن الذى يؤمن بمحبة الله له ، وسهره على راحته ، وبحكمة الله وحسن تدبيره لحياته ، وبأن الله صانع الخيرات ، يعمل لأجله كل خير ... هذا يمكنه أن يسلّم حياته لله ، يدبرها كيفما يشاء .","وبهذا الإقتناع يحيا باستمرار فى طاعة الإيمان .",{h:"إنه يسلم حياته لله وهو مطمئن وسعيد ..."},"أما الذى لا يحيا فى حياة التسليم ، فإنه على العكس يعيش قلقاً على حياته ، ويظل يفكر : ماذا أكون ؟ وكيف أكون ؟ ومتى أكون ؟ وهل ينبغى أن أغير ما أنا فيه ؟ وبأية وسيلة ؟ أم أظل كما أنا ... ؟ ويتعبه التفكير ، وغالباً ما يفقد سلامه ، ويظل فى سعى مستمر ، ومناقشة الأمور مع نفسه ، إلى غير نهاية ... ولا يفكر مطلقاً أن يستريح ، ويترك الأمر لله مثل رجل الإيمان ...",{h:"الإنسان المؤمن عندما يسلم حياته لله ، لا يشترط عليه شروطاً ، ولا يطلب منه ضمانات ، ولا يراقب الله فى عمله معه ..."},"إنه واثق بالله كل الثقة ، فى محبته ، وفى حكمته ، وفى قدرته . مؤمناً أن الله يعرف ما هو الخير له أكثر مما يعرف هو . لذلك يسلم حياته فى يدى الله ، وينساها هناك . وهكذا نراه لا يحمل هماً .","مادام هو مؤمناً بعمل الله من أجله ، لا يمكن أن يقلق ويهتم ، ولا يمكن أن يتعب نفسه بالتفكير . فالمؤمن يحيا فى راحة ، أكثر من الذى يفكر لنفسه ويتعبه تفكيره ...",{h:"كثيرون لا يقبلون التسليم لله ، إلا إذا فشلت طرقهم البشرية !"},"منهجهم الأساسى هو الإعتماد على الذراع البشرى كل الإعتماد : إما اعتداداً بذهنهم وقدراتهم وحيلهم ، أو لتعودهم هذا الأسلوب ، أو لخطأ عقيدى عندهم ، أو اقتناعاً بأن الله لا يلجأ إليه إلا فى حالة العجز والفشل الكاملين ! حينئذ يأتون إلى الله ، لأنهم جربوا كل حيلة وكل وسيلة وما وصلوا إلى غايتهم ، ولأن فكرهم تعب وأنهك بلا فائدة . فلم يبق سوى الله !"],69:[{h:"ليس هذا هو الإيمان ، إنما هذا هو الإضطرار إلى الله ."},"الإيمان هو أن تلجأ إليه فى الصغائر ، كما تلجأ إليه فى الكبائر .","قال السيد المسيح « بدونى لا تقدرون أن تعملوا شيئاً » (يو ١٥ : ٥) . ذلك لأن كل طاقة لنا هى من عنده ... حتى الفكر الصائب ، وحتى مجرد الإرادة الطيبة ، وحتى القدرة على العمل . وذكاؤنا هذا الذى نعتمد عليه ، هو أيضاً من عنده . وما أصدق قول الرسول « لأن الله هو العامل فيكم أن تريدوا وأن تعملوا لأجل المسرة » (فى ٢ : ١٣) .",{h:"إن عملنا فى الواقع ، هو أن نشترك مع الله ، فى عمله لأجلنا ."},"وهذه هى شركتنا مع الطبيعة الإلهية ، شركتنا مع الروح القدس : نشترك مع الله فى العمل . كما قال القديس بولس الرسول عن نفسه وعن زميله أبولس « نحن عاملان مع الله » (١كو ٣ : ٩) .","وكل عمل لا يشترك الله معنا فيه ، لا يكون عملاً مقدساً ، ولا عملاً مباركاً . وتسليمنا الإرادة لله ، هو نوع من الشركة معه ، نكون فيه كآلات طيعة بين يديه تعمل مشيئته . هو يسيّرها كيفما يشاء . وهى تعمل بفكره وإرادته ، أو بتسليم إرادتها لإرادته ، كشركة الحواس مع المخ ...",{h:"إن أخطر ما يهدد الحياة الروحية ، هو استقلال الإنسان عن الله ."},"وهذه هى الخطية الكبرى التى وقع فيها شاول الملك فرفضه الله (١صم ١٦) . كان يعمل بفكره وبتدبيره ، بعيداً عن مشورة الله وعن شركته . ولا يرى أنه محتاج إلى أن يشترك الله معه فى العمل . وكأنه يقول : مادمت أستطيع أن أعمل هذا العمل ، فسأعمله ، بكل قوة ، وبكل سرعة ، وحتى بدون صلاة ... لأن إرادتى وحدها هى التى سوف تعمله ... ! وبدون اعتماد على الله . وإن فشلت ، ألجأ إليه ! مادام الله قد وهبنى عقلاً وإرادة ، فلماذا لا أستخدمهما ؟ ! ... وكثيرون مثل شاول ...",{h:"الله قد وهب البشرية العقل والإرادة . ولكن ليس لتستقل عنه !"},"وليس لكى تعتد بذاتها . فالكتاب يقول « وعلى فهمك لا تعتمد » (أم ٣ : ٥) . ولنتذكر أن خطيئة الإنسان الأول ، كانت محاولته الحصول على المعرفة بعيداً عن الله (تك ٣) ..."],70:["ومتى بدأ الإنسان يقول « أنا أعرف ، وأنا أقدر ، ولا أجد الحاجة فى هذا الأمر إلى الله ! ؟ » يكون حينئذ قد بعد عن الإيمان بالله ، ودخل فى الإيمان بالأنا (الذات) الـ Ego ...",{h:"أما المؤمن فلا يكتفى بالإعتماد على الله ، بل يسلمه كل شىء ..."},"ويقول له : حياتى هى صنع يديك ، وهى الآن بين يديك ، إفعل بها ما تشاء . حيثما تسيرنى أسير ، وكيفما تصيرنى أصير . أنا ليست لى إرادة خاصة ، فإرادتى الوحيدة هى أن أصنع إرادتك ، وأن أتحد بإرادتك ، فأريد ما تريده أنت ، أنت يا صانع الخيرات ...","لست أقول عن شىء إننى أعرف . فكل معرفة الإنسان هى جهالة عند الله (١كو ١ : ٢٠) . المعرفة الحقيقية هى من عندك يارب وحدك . أنت هو الحكمة (١كو ١ : ٢٤) . أنت « المذخر فيه كل كنوز الحكمة والعلم » (كو ٢ : ٣) .",{h:"ولأنى أعترف أنى لا أعرف ، لذلك سلمت حياتى فى يديك ."},"أنت تعرف الخير أكثر مما أعرفه . وأنت تعرف الخير لى أكثر مما أعرفه لنفسى . وأنا واثق بحكمتك وبحسن تدبيرك لحياتى . حتى إن شئت لى التجربة أو الضيقة ، فأنا أقبلها باعتبار أنها خير خالص هو من يديك . ولولا ذلك ما كنت أنت المحب ترضاها لى . حقاً فى حالات كثيرة ، لا نعرف أين هو الخير !",{h:"إن حياة التسليم لا تعرف الشكوى ولا التذمر ، بل تقبل كل شىء برضى وفرح ..."},"مادمت يا أخى تثق بحكمة الله فى تدبيرك ، فلماذا إذن أنت تشكو أو تتذمر أو تضجر . إذا دخل التذمر إلى حياتك ، فافحص نفسك جيداً ، لئلا يكون إيمانك قد ضعف وأنت لا تدرى .",{h:"الذى يحيا حياة الإيمان والتسليم ، يحيا دائماً فى فرح وفى شكر ."},"إنه لا يشكو بل يشكر ، الإبتسامة لا تفارق شفتيه ، والبشاشة لا تفارق وجهه ، والفرح لا يفارق قلبه . إنه يؤمن بحكمة الله ومحبته . ويؤمن أن مشيئة الله دائماً صالحة ومفيدة . وهو يخضع لمشيئة الله فى فرح ...","لا يخضع لمشيئة الله فى تغصب واضطرار . وكأن قلبه يقول لله : « ماذا أفعل"],71:["يارب ؟ أنت هو القوى وأنا الضعيف . وكل ما تعمله أنا أقبله . وأنا منتظر نهاية هذا الأمر ... ! ! » . لا شك أن هذا كلام إنسان متعب فى داخله ، يتكلم بكلام تذمر فى أسلوب تسليم . وليس التسليم هكذا ...",{h:"إذن ما معنى « لتكن مشيئتك » فى حياة الإيمان وحياة التسليم ؟"},"الإنسان المؤمن يقول فى رضى قلبى كامل : أنا يارب خاضع لمشيئتك ، لأنى أحب مشيئتك من أعماقى ، وأثق بك وبها . مشيئتك هذه أصلحت أفكارى ، وأصلحت أحكامى على بعض الأمور ، وعدلت مسارى وطريقى ... ما أجمل طرقك يارب « ما أبعد أحكامك عن الفحص ، وطرقك عن الإستقصاء » (رو ١١ : ٣٣) . مشيئتك هذه هى أجمل أغنية فى فمى ، وأحلى الأخبار فى أذنى . فلتكن مشيئتك إذن ، لأنه لا توجد مشيئة أخرى أياً كانت أصلح منها . إلى جوارها أشعر بجهالة أية مشيئة تتعارض معها ، سواء كانت لى أو لغيرى ...",{h:"ليست حياة التسليم ، هى الخضوع لسياسة الأمر الواقع ، دون اقتناع !"},"وليست هى الخضوع لسياسة الضغط الإلهى (!) الذى يفرض سلطانه عليك فرضاً ! وأنت مضطر أن تخضع له سواء أردت أو لم ترد ! !","لا يا أخوتى ، ليس هذا هو معنى عبارة « لتكن مشيئتك » . فحياة التسليم تعلمنا أن نشعر بأن مشيئة الله هى الخير الكامل ، وهى أصلح ما يصلح لنا ، وهى سبب فرحتنا وبهجتنا ، ولهذا كان داود النبى يتغنى بأحكام الله . ويقول للرب : أحكامك هى درسى . أحكامك هى لذتى . أنا أتأمل أحكامك وأدرسها (مز ١١٩) .",{h:"التسليم لله ينبغى أن يكون تسليماً حقيقياً ، وليس حسب الظاهر ."},{h:"البعض يظن أنه يسلّم حياته لله ، بينما يفرض على الله خططه !"},"كلما يتصرف الله فى حياته ، يحاول أن يستوقف الله ، ويقول له : إنتظر يارب لأرى ما أنت فاعل بى . لا يصلح هذا الأمر . إعمل كذا وكذا لأستريح . وهكذا يود أن يشتغل عند الله وزير تخطيط . هو يخطط ، والله ينفذ ! !","كلا ، ليس التسليم هكذا ، إنما هو أن تترك الله يعمل حسبما يشاء ، وترضى بما يعمل . ولا تقاوم خطط الله بتصرفاتك . لا تقاوم مشيئته بما تعمله حسب هواك ..."],72:[{h:"الإنسان المؤمن يترك التدبير لله . ولا يقبل أن يدبر نفسه بنفسه ."},"ماذا كانت خطية أبينا آدم سوى أنه بدأ يدبر نفسه : كيف يصل إلى المعرفة ؟ كيف يصير مثل الله ؟ كيف يكوّن نفسه وبينها ... وهكذا سقط .",{h:"وخطية الشيطان ، هى أنه بدأ يدبر نفسه ، ويبنيها ويكبرها حسب هواه !"},"« أصعد إلى السموات . أرفع كرسىّ فوق كواكب الله ... أصعد فوق مرتفعات السحاب . أصير مثل العلى » (اش ١٤ : ١٣ ، ١٤) . إنها خطط تشبه أحلام اليقظة ، رسمها الشيطان لنفسه « فانحدر إلى الهاوية ، إلى أسافل الجب » .",{h:"وبالمثل الذين بنوا برج بابل ، جلسوا يخططون لبناء أنفسهم ، ففشلوا ."},"قالوا « هلم نبنِ لأنفسنا مدينة وبرجاً رأسه فى السماء . ونصنع لأنفسنا إسماً لئلا نتبدد على وجه الأرض » (تك ١١ : ٤) . فكان تخطيطهم ضدهم . وما خشوه ، هو الذى صاروا إليه « فبددهم الله على وجه كل الأرض » (تك ١١ : ٩) .","أما الإنسان الروحى فلا يفعل هكذا ، بل فى حياة التسليم يقول :",{h:"« إن لم يبن الرب البيت ، فباطلاً يتعب البناءون » (مز ١٢٧ : ١) ."},{h:"الله هو الذى يبنينا وليس نحن . إذن نسلمه أنفسنا لينبنيها ."},"وهكذا نعيش فى راحة ، مطمئنين إلى عمل الله فينا ، وإلى نجاح عمله . نقف ونتأمل ، فنرى عجائب من تدبيره . واثقين أنه يعمل الخير ، مهما كان الذى يحدث أمامنا غريباً ، أو صعباً ، أو ضد ما كنا نرجوه .",{h:"ليس المهم أن نفهم ما يعمله الله . إنما المهم أننا بالإيمان والتسليم نتقبله ."},"والكتاب المقدس حافل بأمثلة التسليم فى حياة رجال الإيمان :","١ ـ أبونا ابراهيم مثلاً ، كانت بداية قصته مع الله ، هى قول الله له « أترك أهلك وعشيرتك وبيت أبيك ، إلى الأرض التى أريك » (تك ١٢ : ١) .",{h:"وأبونا ابراهيم لم يسأل لماذا ؟ ولا إلى أين ؟ بل أطاع ..."},"هذه هى حياة التسليم ، التى لا تجادل ولا تناقش ، بل تقبل وتطيع ، بلا تردد . تدع فهمها جانباً ، وتركز على أمر الله ."],73:[{h:"٢ ـ وهكذا كان نوح فى الفلك ، وكان يونان فى بطن الحوت ، وكان موسى فى البحر الأحمر ... فى حياة تسليم كامل ."},"إنها طاعة الإيمان . مادام الله يريد هذا ، فنحن لا نناقشه . وما هو عقلنا المحدود الضعيف ، حتى يناقش الله غير المحدود ، كلى الحكمة ... ؟ ! إن موسى فى بدء إرساليته جادل الله فى كيف يدخل إلى فرعون (خر ٣) ، ولكنه لما نما فى الإيمان والتسليم لم يجادل فى دخوله البحر الأحمر ...",{h:"٣ ـ القديسة العذراء مريم عاشت كمثال لحياة الطاعة والتسليم ."},"مع كل محبتها للبتولية ، قيل لها أن تخطب لرجل وتعيش معه فى بيت واحد ، فأطاعت . وأرسل لها الله ملاكاً يقول لها إنها ستحبل وتلد ، فقالت له « هوذا أنا أمة الرب . ليكن لى كقولك » (لو ١ : ٣٨) ... ومع ولادتها لله الكلمة ، ورؤيتها كل ما أحاط بهذا الميلاد من معجزات ، قيل لها أن تهرب به إلى مصر وتتغرب هناك ، فقبلت كل ذلك فى طاعة الإيمان . وفى تسليم أيضاً رجعت من مصر ، وقبلت أن تسكن فى الناصرة (متى ٢ : ٢٣) ، التى قيل إنها لا يخرج منها شىء صالح (يو ١ : ٤٦) .","وكان شعارها فى حياة التسليم هذه ، عبارتها الخالدة « ليكن لى كقولك » .",{h:"٤ ـ ولعل الإيمان والتسليم يظهران فى حياة الرسل فى طاعتهم التلقائية لقول الرب « إتبعنى » أو « هلم ورائى » ."},"هكذا قال الرب لمتى (لاوى) . وهو فى مكان الجباية (مر ٢ : ١٤) فلم يناقش وإنما « ترك كل شىء وقام وتبعه » (لو ٥ : ٢٨) . ولم يفكر مطلقاً فى كل مسئولياته وعمله .","وبالمثل لما دعا الرب بطرس وأندراوس وباقى الرسل ، يلخص القديس بطرس كل قصص هذه الدعوة بقوله للرب « تركنا كل شىء وتبعناك » (لو ١٨ : ٢٨) .","إنها طاعة الإيمان التى تتبع الرب حيثما ذهب ، بلا سؤال ، بلا استفسار ، بلا تفكير فى المستقبل . وكما سنشرح أن كلاً منهم أطاع ، وهو لا يعلم إلى أين يذهب (عب ١١ : ٨) .",{h:"ونحن كثيراً ما ندعى ، فنحاول أولاً أن نطمئن على مستقبلنا ."},"لذلك نسأل الكثير من الأسئلة . ونحصل على ما نستطيعه من الضمانات ."],74:["وبكل هذا نخرج من الإيمان إلى العيان ... إلى المستقبل الذى نراه بعيوننا ونطمئن إليه ، وليس إلى المجهول الذى نراه بالإيمان ، ونقبله بحياة التسليم والطاعة ...",{h:"٥ ـ من أمثلة حياة الإيمان والتسليم والطاعة ، أرميا النبى ."},"سار وراء الله بالإيمان ، فى طرق لم يفكر مطلقاً أن يسير فيها ... وأخيراً لخص خبرته فى حياة التسليم فى عبارة عميقة قال فيها « عرفت يارب أنه ليس للإنسان طريقه . ليس لإنسان يمشى أن يهدى خطواته » (أر ١٠ : ٢٣) . ولماذا لا يهدى خطواته ؟ لأن الله هو الذى يقود هذه الخطوات ويهديها ...",{h:"هذه هى حياة التسليم ، أن تسير وراء الله ، وليس وراء فكرك ."},"تسير ليس وراء هواك ورغباتك ، وليس وراء مشيئة الناس أو مشورة الناس ، إنما وراء الله نفسه الذى يقود حياتك . يضعها فى أى وضع ، وفى أى موضع ، حسب أعماق حكمته . فاسأل نفسك هل الله هو الذى يقود حياتك ؟ أم تقودها رغبة معينة ، هى التى تحدد تصرفاتك ومسير خطواتك ؟",{h:"٦ ـ من الأمثلة العجيبة فى حياة التسليم : يوسف الصديق ."},"أظهر له الله بالرؤى أنه سيصير سيداً لإخوته ، وسيسجدون له جميعهم (تك ٣٧ : ١٠) . فماذا كان تحقيق الوعد ؟ أخذه إخوته وألقوه فى بئر ليقتلوه . ثم باعوه كعبد . وسحبه المديانيون من البئر ليبيعوه للإسماعيليين (تك ٣٧ : ٢٨) . ثم بيع لفوطيفار ليخدم فى بيته ...",{h:"وفى كل هذا لم يحتج يوسف متذمراً على الرب وعلى أحلامه ..."},"بل سكت . وسلّم فى هدوء لما سمح به الرب ، وسلك بكل أمانة وإخلاص . وقبل الحياة كخادم ... ولكنه رضى بالبلوى ، والبلوى لم ترض به ! فإذا بتهمة باطلة رديئة تلفق ضده ، ويلقى به فى بيت السجن كفاعل إثم ... !",{h:"ولم يحدث أن يوسف سأل الرب لماذا ؟ ... أو أين هى وعودك ؟"},"سكت فى مثل رائع لحياة التسليم وطاعة الإيمان . ولم يتذمر مطلقاً . وفى المرة الوحيدة التى خرج فيها قليلاً جداً عن حياة التسليم ، وقال لرئيس السقاة بعد أن فسّر له حلمه « حينما يصير لك خير ، تصنع إلىّ إحساناً ، وتذكرنى لفرعون ، وتخرجنى من هذا البيت » (تك ٤٠ : ١٤) ... لما فعل هذا ، أجاب الوحى الإلهى على هذا"],75:["الطلب بقوله « ولكن لم يذكر رئيس السقاة يوسف ، بل نسيه » (تك ٤٠ : ٢٣) ...","ولكن الله لم ينس يوسف ، الذى بقى فى السجن فى حياة التسليم ، حتى أخرجه الله منه بمجد عظيم ...",{h:"٧ ـ ومن أمثلة حياة التسليم وطاعة الإيمان : داود النبى ."},"كان « يرعى الغنيمات القليلات فى البرية » . وأرسل له الله صموئيل النبى ومسحه ملكاً . ولكنه لم يسلمه من الملك شيئاً ... وبقى يرعى الغنيمات القليلات ، دون أن يتذمر . ثم اختير خادماً للملك شاول المرفوض من الله الذى بغته روح ردىء من قبل الرب (١صم ١٦ : ١٤) ... ولم يحتج داود .",{h:"لم يقل أنا الملك المختار من الله . فكيف أخدم هذا المرفوض ؟ !"},"بل فى حياة التسليم تقبل الوضع . وكان يهدىء شاول الملك حينما تبغته الشياطين ... وظل شاول يطارد داود من برية إلى برية ، ويحاول قتله ، حسداً منه وغيرة ... ولم يحدث مطلقاً أن داود ناقش الله ، أو قال له أين مواعيدك ؟ أين المسحة المقدسة من النبى العظيم ؟ ولم يقل له ماذا فعلت من شر حتى أستحق كل هذا ؟ ! ... بل انتظر ، فى هدوء وفى تسليم ، خلاص الرب . وقد كان ...",{h:"٨ ـ ومن أمثلة حياة التسليم : تلاميذ الرب ."},"دعاهم الرب للخدمة كما قال لبطرس وأندراوس « هلما ورائى فأجعلكما صيادى الناس » (متى ٤ : ١٩) . ومرت ثلاث سنوات وهم يتبعونه ، دون أن يخدموا . ولم يصيدوا أحداً . ثم ضلب الرب . وخافوا ، وأغلقوا على أنفسهم فى العلية لئلا يصيدهم اليهود ... ومع كل ذلك لم يشكوا . وبقوا فى حياة الإيمان والتسليم .","وأخيراً بعد حلول الروح القدس ، تمم الرب وعده . وفى يوم واحد تمكن بطرس بعظة واحدة من أن يصيد ثلاثة آلاف نفس ... ولو أنه كان كل يوم يصيد نفسين ، ما وصل إلى هذا الرقم كله ، ولكن حياة التسليم تقول للرسول : « إنتظر الرب . تقوّ ، وليتشدد قلبك . وانتظر الرب » (مز ٢٧ : ١٤) .","نعم يارب سأنتظر وعدك فى صيد الناس . ولكن هل إلى ثلاث سنوات وأكثر ؟ إنه لكذلك . ولكن « ليس لكم أن تعرفوا الأزمنة والأوقات التى جعلها الله فى سلطانه وحده » (أع ١ : ٨) .",{h:"إن حياة التسليم لا تناقش الرب فى مدى الإنتظار الطويل لمواعيده ."}],76:["إنها لا تقول له : لماذا يارب تجعل بطرس ينتظر أكثر من ثلاث سنوات ليصير صياداً للناس ؟ ولماذا تترك ابراهيم ينتظر خمسة وعشرين عاماً حتى تحقق له وعدك فى ميلاد اسحق ؟ ولماذا تترك داود فى مذلته من شاول عشرات السنوات ، حتى تحقق له اختيارك له ملكاً ... ؟",{h:"إن حياة التسليم لا تشك ، وترى فى الإنتظار حكمة إلهية ."},"فقد كان داود صبياً حين اختياره . وكان الإنتظار نافعاً له حتى يكبر وينضج ، وحتى يزداد الناس حباً له يوماً بعد يوم . كذلك كان الإنتظار نافعاً لبطرس حتى تكتمل تلمذته للرب ، وحتى يحين موعد حلول الروح القدس لينال به قوة هو وسائر الرسل . كذلك كان الإنتظار نافعاً لولادة اسحق ، ليصير إبناً للموعد ...",{h:"٩ ـ من أجمل الأمثلة فى حياة التسليم : تقديم اسحق محرقة ."},"لقد صبر ابرآم خمساً وعشرين سنة ، حتى ولد له اسحق ، إبنه المحبوب الذى أخذ المواعيد من أجله . وفرح به فرحاً لا يوصف . وكبر اسحق . وإذا بالرب يقول لأبينا ابراهيم « خذ إبنك ، وحيدك ، الذى تحبه ، إسحق ... وأصعده محرقة على أحد الجبال الذى أريك » (تك ٢٢ : ٢) ... أى قلب يمكنه أن يحتمل هذا ؟ ! وأى عقل يسمع هذا ولا يشك ... ؟ !",{h:"ولكن أبانا ابراهيم فى حياة التسليم ، لم يناقش ، ولم يتردد فى التنفيذ . بل بكّر صباحاً ، وأخذ إسحق ليذبحه ... ولم يحسب نفسه أحنّ من الله ... ولم يشك فى محبة الله ولا فى حكمته ..."},"إن الطاعة لا تكون فى الأمور السهلة فقط ، وإنما تظهر فى قمة سموها فى الأمور التى تبدو صعبة جداً فى التنفيذ .",{h:"حياة التسليم تظهر فى الدخول من الباب الضيق والطريق الكرب ."},"مادمت أنت يارب موافقاً على هذا الباب الضيق ، فإنه يكون أصلح الأبواب للدخول . ولا نناقشك ... بل نفرح بذلك ، ونرى أنك تختبر به محبة أولادك ، ونقاوة قلوبهم ، وتعد به لهم أكاليل فى ملكوتك ...","وبهذا الإيمان ، إستقبل الشهداء والمعترفون كل أنواع الآلام فى فرح . وكل أولادك يارب كانوا « يحسبونه كل فرح حينما يقعون فى تجارب متنوعة » (يع ١ : ٢) ."],77:[{h:"لا يعلم إلى أين يذهب"},"« بالإيمان ، إبراهيم لما دعى أطاع ... فخرج وهو لا يعلم إلى أين يذهب » (عب ١١ : ٨)","١ ـ هكذا سار أبونا ابراهيم وراء الله ، إلى المجهول ... لم يكن يعلم إلى أين الطريق ، إنما كان واثقاً أن الله يصحبه فى الطريق ، ويرشد خطاه ...",{h:"٢ ـ وهكذا حدث مع آبائنا الرسل الأطهار ، لما دعاهم الرب فتبعوه ."},"وهم لا يعلمون إلى أين ... إذ لم يكن للمسيح مقر معروف ، بل لم يكن له أين يسند رأسه (لو ٩ : ٥٨) . كان يطوف المدن والقرى يعلّم ويشفى ، مع أنه لم تكن له وظيفة رسمية فى المجتمع اليهودى ... ولم يكن له دخل مالى معروف . وحتى لما دعا تلاميذه ، قال لهم « لا تحملوا ذهباً ولا فضة ولا نحاساً فى مناطقكم ... ولا تحملوا معكم شيئاً للطريق » (متى ١٠ : ٩ ، مر ٦ : ٨) .","ولو سألت أحد تلاميذه وقتذاك : ما هو عملك ؟ وما هو مستقبلك مع المسيح ؟ لوقف وأوقفك معه ، أمام علامة استفهام كبيرة لا يعرف لها جواباً ، سوى حياة التسليم ... يكفيه أنه سائر مع المسيح ، مع أنه معه وفى وجوده لا يعمل شيئاً ... المسيح يعمل كل شىء ، وتلاميذه مجرد متفرجين .",{h:"٣ ـ خذوا مثالاً لذلك القديس مار مرقس الرسول حينما دخل الإسكندرية :"},"دخلها وهو لا يعلم إلى أين يذهب ، إذ لم تكن هناك كنيسة يستقر فيها ، ولم يكن له هناك شعب ، ولا مسكن ... بل على العكس كانت الوثنية فى كل مكان ، وكانت اليهودية تقاوم الإيمان ... ولكن بالإيمان جاء مارمرقس إلى مصر ، وأرشد الله خطاه إلى إنيانوس ، وما كان فى فكره هذا الأمر ...","وما حدث لمار مرقس ، حدث تقريباً لباقى الرسل . تتنوع الأمكنة والأسماء ، ولكن قلب الموضوع واحد . وكأن كل رسول كان يقول :"],78:[{h:"لو كانت الخدمة عملاً بشرياً ، لكان يهمنى أن أعرف خطة مسيرى . أما الخدمة عمل إلهى ، فلا يهمنى إلى أين أذهب . أنا مع الله . حيث قادنى أسير ."},"٤ ـ يوحنا المعمدان كان يرى أن واجبه هو أن يشهد للحق . فشهد للحق ، وقال لهيرودس الملك « لا يحل لك » ولم يهتم بعد ذلك إلى أين يذهب : إلى السجن ، إلى الموت ... ليكن ما يكون . رسالة الله تتم فى طاعة إيمانية كاملة . أما الحياة ، وأما المصير ، فهما مسلمان لله ... إلى التمام .","وهكذا كان بولس الرسول يشهد للرب ... وبعد ذلك لا يهمه إلى أين يذهب : « أشدة أم ضيق أم اضطهاد أم جوع أم عرى أم خطر أم سيف » ، يقول فى ثقة بحياة التسليم « لكننا فى هذه جميعها ، يعظم انتصارنا بالذى أحبنا » (رو ٨ : ٣٥ ، ٣٧) .","بهذا الأسلوب ، سار أولاد الله جميعهم فى طريق الحياة فى حياة التسليم .",{h:"كل ما يهمهم هو أن الله يقودهم . ولكن لا يعنيهم إلى أين ... ولكنهم واثقون بالإيمان ، أنه سيقودهم إلى المراعى الخضراء ، وإلى ينابيع الماء الحى . خبرتهم مع الله تجعلهم مسرورين بقيادته ، واثقين بمحبته ."},{h:"٥ ـ إسحق بن ابراهيم حمل الحطب وراء أبيه ، ولم يعلم إلى أين يذهب ."},"كل ما تعلمه فى حياته ، هو التسليم والطاعة ، وبها سار حتى إلى المذبح . وربطه إبراهيم أبوه ووضعه على المذبح فوق الحطب (تك ٢٢) ، ورفع عليه السكين . كل هذا وإسحق فى تسليم كامل . لم يشك فى محبة أبيه ، ولم يشك فى محبة الله ... وانتصر على طول الخط .","بتسليمه هذا ، كسب طاعة الإيمان ، وكسب حياته ، وكسب وعود الله ...",{h:"٦ ـ لعازر الدمشقى لما سافر ليختار زوجة لإسحق ، ما كان يعلم إلى أين يذهب ."},"ولكنه سلّم خطاه لله ليرشده . ودبر الله له كل شىء بطريقة عجيبة وقف أمامها مذهولاً . وتم كل شىء حسبما طلب منه سيده ابراهيم . ولهذا قال « الرب"],79:["أنجح طريق » (تك ٢٤ : ٥٦) .","ولعل لعازر الدمشقى كان يقول « لم أكن أعلم إلى أين أنا أذهب . لكنى كنت أعلم تماماً أن الله ذاهب معى » .","ونفس الوضع تقريباً حدث ليعقوب فى رحلته إلى خاله لابان . وما أجمل قول الرب له « ها أنا معك . أحفظك حيثما تذهب » (تك ٢٨ : ١٥) .",{h:"٧ ـ الشعب فى البرية ، أتراه كان يعلم إلى أين يذهب ؟ !"},"ما كان يعلم شيئاً . كان الله يقوده يوماً بيوم . وكان يرتحل بإرشاد إلهى ، ويقف بإرشاد إلهى . وكان هذا الإرشاد يتمثل فى السحابة تظلله نهاراً ، وعمود النار يهديه ليلاً ... والشعب فى تسليم كامل لقيادة الله ، لا يسأله إلى أين ... ؟","وما كانت أمام موسى النبى خطة لمسيره ، ولا خريطة لمسيره . وكأنه يقول :",{h:"يكفينا يارب أن تكون سحابتك فوق رؤوسنا ، وعمود النار أمامنا . نحن لا نحدد مسارنا ، إنما تحدده مشيئتك الصالحة . أما نحن فيسعدنا أننا تحت قيادتك . حيثما سارت سحابتك نسير . وحيثما حلت نستظل تحتها ... يفرحنا أننا نرى فوق تابوت العهد الضباب الذى يمثل وجودك ."},"فلتتحرك خيمة الإجتماع فى البرية نحو المجهول . إنه مجهول بالنسبة إلينا . ولكنه فى علمك ومعرفتك منذ الأزل . وهذا يكفينا ، لكى نسلّم خطانا لهذا المجهول ، ونحن فى ملء الثقة بأننا فى طريق كنعان ...",{h:"٨ ـ القديس الأنبا أنطونيوس أب جميع الرهبان ، حينما دخل إلى الجبل ، أتراه كان يعلم إلى أين يذهب ؟ ! وكذلك القديس الأنبا بولا أول السوّاح ..."},"وأيضاً كل السواح والمتوحدين حينما توغلوا فى البرية الجوانية ، ما كان أمامهم هدف مكانى معين يقصدونه . كل ما كان أمامهم هو الهدف الروحى وهو أن ينفردوا بالله فى حياة السكون والهدوء ، مسلمين حياتهم بالكلية له « تائهين فى البرارى والجبال وشقوق الأرض » ...","تسأل كل واحد من التائهين فى البرارى : أتعلم أين أنت ؟ فيجيبك :",{h:"على خريطة المكان ، لست أعلم أين أنا ... ولكن على خريطة الحب ، أعلم أننى فى حضن الآب ."}],80:[{h:"٩ ـ ولعل البعض يسأل : أما ينبغى أن يحسب كل إنسان حساب النفقة ، حسب وصية الرب نفسه (لو ١٤ : ٢٨) ؟"},"إن حياة الإيمان ، هى أبعد ما تكون عن علم الحساب الذى يقصدونه . إذن ما الذى يقصده الرب بأن يجلس الإنسان أولاً ويحسب النفقة ؟",{h:"حساب النفقة هو : هل عندك من الإيمان ما يكفى ؟"},"هل عندك من الإيمان ما تسلّم به الأمر كله لله لكى يدبره ؟ إنك تفعل ما تستطيعه . ولكن هذا هو أقل المطلوب . أما العنصر الأساسى فهو إيمانك بما يفعله الله ، وتسليمك له كل الأمر ...","وهذا كان منهجنا ، حينما كنا نريد أن نبنى كنيسة أو أى مشروع للخدمة والرعاية . لم يكن السؤال الأساسى هو « من أين التكاليف ؟ » ، إنما كان السؤال الأساسى هو : هل الله موافق على هذا البناء أم لا ؟ فإن كان موافقاً فهو الذى سيقوم بكل تكاليفه . وما علينا إلا أن نبدأ ، ويد الله تكمل العمل معنا « وإن لم يبن الرب البيت ، فباطلاً يتعب البناءون » (مز ١٢٧ : ١) .",{h:"الإيمان هو أن تغمض عينيك ، وتبصر الله ."},"طالما أنت تفتح عينيك ، فأنت تسير بالحواس الجسدية . أما إن أغمضت هذه العين الجسدانية ، حينئذ سوف تسلك بالقلب والروح .","إن تأكدت بحواسك الروحية أن الله سيذهب معك فى طريق ، سر فيه ولو كان فى وادى ظل الموت . يقيناً ، هناك سوف لا تخاف شراً لأن الرب معك (مز ٢٣) .",{h:"١٠ ـ هذه هى حياة التسليم ، التى فيها يختار الرب لنا ما نشاء ، دون أن نختار نحن لأنفسنا . آخذين درساً من قصة لوط وإبراهيم ."},"لوط اختار لنفسه السكنى فى سادوم ، الأرض المعشبة (تك ١٤ : ١٠ ، ١١) . وكان يعلم إلى أين يذهب . أما إبراهيم فلم يختر لنفسه شيئاً . إنما قال له الرب « إرفع عينيك وانظر ... جميع الأرض التى أنت ترى ، لك أعطيها » (تك ١٠ : ١٤ ، ١٥) ... وماذا كانت النتيجة ؟ لوط سبى وهو فى سادوم وأنقذه إبراهيم (تك ١٤) . ثم احترق كل ماله فى سادوم وخسر الكل ...","وهكذا كانت حياة التسليم التى لإبراهيم ذات نتيجة أفضل ..."],81:[{h:"الفصل الثامن"},{h:"(عنوان الفصل مطبوع بخط مزخرف مقلوب في ملف المصدر الممسوح ولا يمكن قراءته بدقة. ويبدو أن ما يلي هذه الصفحة في الملف يبدأ في منتصف جملة؛ فلعل صفحة أو أكثر ناقصة من ملف المصدر.)"}],82:["١١ : ١٩) . هذا هو « الله الذى آمن به ، الذى يحيى الموتى ، ويدعو الأشياء غير الموجودة كأنها موجودة » (رو ٤ : ١٧) .","بالإيمان بقدرة الله على كل شىء ، دخل موسى فى البحر الأحمر وعبره . ودخل يشوع فى نهر الأردن وعبره ، كل منها مع شعبه ...",{h:"د ـ كذلك ينبغى أن تثق بحكمة الله ، وبأن كل تدابيره صالحة ، حتى لو كنت لم تفهم بعد أعماق هذه الحكمة ..."},"إن آمنت بحكمة الله ، تعيش فى سلام ، وتقبل كل شىء برضى . أما إن كانت (حكمتك) البشرية لا تثق بحكمة الله ، ستعيش فى تذمر وشكوى وتعب نفسى ... لذلك فى كل ما يحدث لك ، قل له : أنا واثق يارب بحكمتك وحسن تدبيرك . وإن كان فهمى الآن عاجزاً ، لابد أننى سأعرف بعد حين ما قصدته بى ، كما عرف يوسف الصديق .","إن ثقتك بأن الله صانع الخيرات ، وأنه أب محب ، وحكيم فى تدابيره ، ويريد لك الخير ، وقادر على ذلك ... كل هذا يعمّق إيمانك ، ويمنحك سلاماً فى قلبك ...","هناك وسيلة أخرى لتقوية الإيمان ، وهى :",{h:"٢ ـ الثقة فى صدق مواعيد الله :"},"لقد وعد الله أبانا ابرآم بأنه سوف يعطيه نسلاً ، وأعطاه ولو بعد زمن . ووعده بأن نسله سيكون كنجوم السماء فى الكثرة ، وقد كان ... مع أن زوجته كانت عاقراً ، وكان هو قد تقدم فى الأيام وشاخ .","ووعد الله شعبه بأنه سيرده من السبى . وردّه كما وعد .","ووعد إيليا وقت المجاعة ، بأنه سيعوله . وعاله بأعجوبة (١مل ١٧ : ٣ ـ ٦) .","ووعد الله أمنا حواء بأن نسلها سيسحق رأس الحية (تك ٣ : ١٥) . وقد حقق هذا الوعد على الصليب فى ملء الزمان .","ووعد الله بأنه سيسكب روحه على كل بشر (يوئيل ٢ : ٢٨) . وفعل ذلك فى يوم الخمسين ، ومازلنا هياكل لروحه القدوس (١كو ٣ : ١٦) ...","وعود الله كلها صادقة . ويعوزنا أن نتتبع وعود الله منذ القديم ."],83:[{h:"ولكن هناك وعوداً دائمة لله ، يريحنا أن نحيا فيها بالإيمان ."},"وذلك كقوله « ها أنا معكم كل الأيام وإلى انقضاء الدهر » (متى ٢٨ : ٢٠) ، « حيثما اجتمع اثنان أو ثلاثة بإسمى ، فهناك أكون فى وسطهم » (متى ١٨ : ٢٠) ، « أعطيكم فماً وحكمة لا يقدر جميع معانديكم أن يقاوموها » (لو ٢١ : ١٥) ، « لا تهتموا كيف أو بما تتكلمون ، لأنكم تعطون فى تلك الساعة ما تتكلمون به . لأنكم لستم المتكلمين ، بل روح أبيكم الذى يتكلم فيكم » (متى ١٠ : ١٩ ، ٢٠) . وكذلك قوله عن الكنيسة إن أبواب الجحيم لن تقوى عليها (متى ١٦ : ١٨) .","ليتنا نعيش فى هذه الوعود بكل قلوبنا ، لكى تقوى إيماننا .",{h:"وليتك أيها القارىء المحبوب تجمع كل وعود الله وتقرأها باستمرار . وتقول لنفسك : لابد أن يكون الله صادقاً فى وعوده . وبالتالى لابد أن أعيش سعيداً بهذه الوعود الإلهية ..."},"إن دوام التذكار لوعود الله ، يطمئن النفس ، ويقوى الإيمان ...","وأيضاً مما يقوى الإيمان :",{h:"٣ ـ النظر إلى الله ، وليس إلى الظروف المحيطة :"},"قبيل عبور البحر الأحمر ، كل الظروف المحيطة كانت تدعو إلى اليأس . أما موسى النبى فإنه دعا الناس أن ينظروا إلى الله ، وقال لهم « قفوا وانظروا خلاص الرب ... الرب يقاتل عنكم وأنتم تصمتون » (خر ١٤ : ١٣ ، ١٤) .","كذلك فى حرب داود وجليات . لو نظر إلى الجبار القوى المتحدى ، ليئس . لكنه بالإيمان نظر إلى الله الذى سيحبسه فى يده (١صم ١٧) .","نفس الوضع فى معجزة الخمس خبزات والسمكتين . لما نظر التلاميذ إلى الطعام الموجود ، والآلاف المنتظرة ، قالوا « ما هذا لمثل هؤلاء ؟ ! » . ولكن المسيح نظر إلى فوق وبارك . ولو نظر التلاميذ هكذا بالإيمان إلى فوق ، لاطمأنوا ورأوا قوة الله .","مرثا نظرت إلى قبر أخيها الميت منذ أربعة أيام ، فقالت قد أنتن . أما الرب فقال لها : ألم أقل لك إن آمنت ترين مجد الله (يو ١١ : ٣٩ ، ٤٠) .",{h:"إذن علينا أن ننظر دائماً إلى فوق ، فيدخل الإيمان إلى قلوبنا ."}],84:["ننظر إلى الله المحب القادر على كل شىء ، ولا نركز أفكارنا فى الظروف المحيطة .","لا تنظر إلى قوة أعدائك ، إنما أنظر إلى الله الذى ينقذك منهم .","لا تنظر إلى الخطية التى « طرحت كثيرين جرحى ، وكل قتلاها أقوياء » (أم ٧ : ٢٦) ، إنما أنظر إلى الرب يسوع الذى « يخلص شعبه من خطاياهم » (متى ١ : ٢١) .","كذلك من الأمور التى تقوى الإيمان :",{h:"٤ ـ قصص الإيمان ، ومعاشرة رجال الإيمان :"},"وهكذا عندما أراد الله أن يعطى دروساً فى الإيمان ، قال « تأملوا زنابق الحقل ... ولا سليمان فى كل مجده كان يلبس كواحدة منها » (متى ٦ : ٢٨ ، ٢٩) . فإن كان عشب الحقل ... « يلبسه الله هكذا » « أفليس بالحرى يلبسكم أنتم يا قليل الإيمان » .","وقال أيضاً « أنظروا إلى طيور السماء » . وفى إحدى المرات ، فعلت كما أمر الرب ، ونظرت إلى عصفورة فى حقل الدير ... أمامها الكثير من الحبوب . ولكنها التقطت اثنتين أو ثلاثاً ، وتركت الباقى كله وطارت « لم تجمع إلى مخازن » كما قال الرب . كانت واثقة أنها فى كل مكان تحل فيه ، سيرزقها الله قوتها ، فلماذا تخزن إذن ؟ أو لماذا تترك الجو العالى الفسيح ، وتقبع إلى جوار الحبوب لتخزن كما تفعل زميلتها النملة (القليلة الإيمان ! ) التى لا ترتفع إلى فوق ...",{h:"وقد أعطانا الرب مثالاً شبيهاً فى قصة (المن) وجمعه ."},"كانوا يجمعونه ، على قدر حاجتهم ، يوماً بيوم ، دون أن يخزنوا ... والذين خالفوا هذه القاعدة وخزنوا منّاً « تولد فيه الدود وأنتن » (خر ١٦ : ٢٠) .","كلما يقرأ الإنسان قصصاً عن الإيمان ، والثقة بالله ، والأعاجيب التى تحدث مع قديسيه ، يمتلىء قلبه إيماناً ، ويحب هذه الحياة المملوءة إيماناً ... كذلك كلما يعاشر رجال الإيمان ، يتعلم منهم ، وتثيره حياتهم وعمل الله معهم ، لكى يتمثل بإيمانهم » (عب ١١ : ٧) . لذلك قال أحد الآباء « شهية هى أخبار القديسين » ..."],85:[{h:"من أجل هذا سجل لنا الكتاب سيراً من الإيمان ، لنتأثر بها ونتعلم ."},"ولكى تقوى إيماننا ، إذ نرى أمامنا أمثلة عملية لحياة الإيمان التى نشتهيها . ونرى أمامنا الطريق الذى سلكه رجال الإيمان . وكيف عاملهم الله ، وكيف تعاملوا هم معه ... وماذا أيضاً ؟",{h:"إن كانت القراءة توثّر ، فإن المعاشرة تأثيرها أعمق بلا شك ."},"لذلك عاشروا الذين يتصفون بالإيمان ، وامتصوا الإيمان منهم . فإن الإيمان يناله الإنسان بالتسليم ، أكثر مما يناله بالتعليم . أنظروا كيف يعيشون ، وكيف يظهر الإيمان فى حياتهم ، وكيف يتعاملون مع الله ، وكيف يتصرفون إزاء الأحداث ...","وإن أردتم أن تقووا إيمانكم ، لابد من صفة تتصفون بها وهى :",{h:"٥ ـ إتضاع القلب والفكر :"},"الإنسان المتضع يقبل كل ما يأتى من الله برضى . أما الفكر المعتد بذاته فإنه يناقش ويجادل ، ويرفض ما لا يعجبه ، فلا يصل إلى الإيمان الذى يصل إليه المتضع .",{h:"الإنسان المتضع يعترف أن عقله محدود ، وكل قدراته محدودة ، ولا يمكنه أن يستوعب الله غير المحدود ، ولا يدرك أعماق حكمته وصفاته . لذلك يقبل فى إيمان ولا يشك . وإن ضغط عليه الفكر ، ينسكب أمام الله ويقول « أحكامك يارب فوق فهمى ، وأعمالك فوق معرفتى . من أنا قدامك ؟ وكل معرفتى هى جهالة أمامك ."},{h:"أنا آخذ منك عن طريق التسليم ، وليس عن طريق الفحص ..."},"أعطنى يارب إيمان الأطفال ، وليس إيمان الفلاسفة والحكماء (لو ١٠ : ٢١) . حادثة مثل إلقاء الثلاثة فتية فى أتون النار ، دون أن يحترقوا (دا ٣ : ٢٥) . هذه ، هل نخضعها لفهمنا المحدود ، أم نتقبلها بالإيمان فى اتضاع الفكر الذى ينحنى أمام المعجزة ؟ ! والمعجزة هى عمل الله القادر على كل شىء ...","الإيمان يحتاج إلى اتضاع الفكر وبساطة القلب ، وأيضاً إلى :"],86:[{h:"٦ ـ الخبرة مع الله :"},"إلق نفسك فى دائرة الله . عش معه واختبره . جرب الإتكال عليه . حينئذ سترى عجائب من عمله معك . أما إن كنت طوال حياتك تحصر نفسك فى دائرة إمكانيات الفكر ، والذكاء البشرى ، وخبرات المجتمع ، ومشورات الناس ، بعيداً عن الله ، تأكل كل يوم من شجرة معرفة الخير والشر ، فكيف تصل إذن إلى الإيمان ؟ !","إذن إختبر عملياً وجود الله فى حياتك . عاشره لتعرف من هو . وكما قال داود النبى « ذوقوا وانظروا ما أطيب الرب » (مز ٣٤ : ٨) .","ولعل سائلاً يسأل : وكيف ندخل فى الخبرة مع الله ؟ أقول :",{h:"٧ ـ إبصر الله فى كل أمر :"},{h:"الناس لا يقوى إيمانهم ، لأنهم يعيشون فى عالم ، فصلوه عن الله ."},"كل ما يحدث فى هذا العالم ، يرجعونه إلى أسباب عديدة ولا يذكرون إسم الله كأنما الكون يدور ... بدون الله .","أ ـ مثال : العالم يستطيع أن يحطم الذرة ، ويستخدم القوة النووية ، ويصنع سفن الفضاء ، ويصل إلى القمر ، ويدور حول الكون ، ويتعامل مع الإلكترونات ... ويصرخ الناس ويقولون : ما أعظم العقل البشرى ! أو ما أعظم الشعب الذى اخترع كل هذه المخترعات ... ! ولا يذكرون إسم الله إطلاقاً ...","أما المؤمن فيقول : مبارك أنت يارب الذى خلقت هذا العقل البشرى ، ووهبته كل هذه الإمكانيات ، وكشفت له ما وضعته فى الطبيعة من قوى ... إن كان عبيدك الترابيون يعرفون كل هذا ، فكم وكم تكون أنت يا غير المحدود ، القادر على كل شىء ؟ ! وهكذا يقوى إيمان المؤمن بإرجاعه كل قوة وكل عجيبة إلى الله ...","ب ـ مثال آخر : يمرض إنسان بمرض خطير . ويستطيع طبيب أن ينقذه من الموت فيشنى . وينذهل المريض وأقرباؤه من مهارة الطبيب ، ويشكرونه فى الجرائد ويمدحونه . ويعتبرونه سبب الشفاء . أما الله فلا يتردد إسمه مطلقاً على أفواههم . ولكن المؤمن يقول : نشكر الله الذى شنى المريض ، وكانت يده مع يد الطبيب ."],87:["ج ـ مثال ثالث : إنسان يتعرض لحادث تصادم يكاد يودى بحياته ، لولا أن سائق العربة يوقفها بمهارة على بعد سنتيمترات من الرجل . ويصرخ الناس : يا لمهارة السائق ! بينما المؤمن يقول : لقد منح الله هذا الإنسان عمراً جديداً ...",{h:"ليتك فى كل حادث ، تبحث عن أصبع الله فيه ، ليقوى إيمانك ."},"إبحث عن حكمة الله وعمل الله فى كل ما يمر بك من الأحداث اليومية ، حينئذ ستجد الله كائناً أمامك كل يوم ، تلمسه وتتعامل معه ، وتشعر بوجوده فى كل ما يمر بك من صغيرة وكبيرة . وبهذا يزداد إيمانك يوماً بعد يوم .","د ـ مثال رابع : المؤمن إذا مرّ على حديقة ورأى زهرة من الزهور ، لا يكتفى بالتمتع بشكلها ورائحتها كما يفعل العلمانيون ... إنما يقف أمامها مندهشاً ويقول : ما هذا الجمال الذى خلقته يارب ؟ ! وما هذه الألوان العجيبة التى يعجز أمهر الفنانين عن أن يصنعوا مثلها ... لا شك أن الزهور الصناعية جميلة ومتقنة ، ولكنها ليست فى هذا التناسق ، كما أنها لا حياة فيها ، ولا نضارة ، ولا رائحة لها . إنها جمال ميت ... !",{h:"حقاً ، إن التأمل فى الطبيعة بهذا الأسلوب ، يقوى الإيمان ..."},"أهل العالم يتأملون الطبيعة منفردة ، قائمة بذاتها ، وقد فصلوها عن الله . أما الذى يريد أن يقوى إيمانه ، فإنه يرى الله فى الطبيعة ... أليست هى صنعة يديه ؟ ... وهكذا كان داود النبى يقول « السموات تحدث بمجد الله ، والفلك يخبر بعمل يديه (مز ١٩ : ١) . أتراك تعجب بليلة قمرية جميلة ، دون أن تمجد الله خالق القمر ؟ !","تذكر الله هكذا ، ليكون الله بالنسبة إليك حقيقة عملية ، وليس مجرد حقيقة عقلية تثبتها البراهين ... بهذا تحيا مع الله كل يوم .",{h:"إن أردت أن يقوى إيمانك ، لا تفضل مخلوقات الله على الله ."},"لا تبهرك الطبيعة ، وتنسى الله خالقها . لا يبهرك العقل البشرى وتصرفه فى المادة . وإنما قل : عجيب أنت يارب ! كيف خلقت المادة هكذا ، بهذه الخاصية وبهذا المفعول ، بحيث يمكن للعقل أن يستخدمها فى كل هذه الأغراض ... ! أتراننا نعجب بطبيب يستخلص دواء من مادة معينة ، بينما ننسى الله الذى وضع هذه"],88:["الخاصية فى تلك المادة ، حتى يمكنها أن تخدم غرض الطبيب ... !","أمر آخر يمكنه أن يقوى إيمانك وهو :",{h:"٨ ـ إتخذ الرب صديقاً لك :"},"لو فعلت هذا ، لأمكن أن يقوى إيمانك ، لأنك ستكون علاقة مع الله وتتحدث معه بدالة بلا خوف ، فتتوطد صلتك به .","كثيرون ينظرون إلى الرب كمجرد إله أو سيد . ولكن هل نظرت إليه أيضاً كصديق ومحب ، تثق به وبمحبته وبإخلاصه لك . إنه يقرع على بابك ، ويطلب إليك أن تفتح له كصديق ، فيدخل ويتعشى معك وأنت معه (رؤ ٣ : ٢٠) . إن قبلت صداقة الله ومحبته ، ستدخل فى الإيمان الحقيقى ... تشتاق إلى رؤياه كصديق ، وتحكى له أسرارك ، وتتمتع بعشرته ومحبته ... وتحرص كصديق له ألا تخدش شعوره أو تغضبه . وهو نفسه سيكشف لك أسراره ، كما كشف لإبراهيم (تك ١٨ : ١٧) .","إن الله يريدك هكذا ، لأنه قال « لا أعود أسميكم عبيداً ... بل أحباء » (يو ١٥ : ١٥) ... إتخذه إذن كصديق أو كأب ، تؤمن بأبوته ومحبته ، كما تؤمن بسلطانه وقدرته . تحدثه عن أسرارك ، ويحدثك عن أسراره .",{h:"من قصص الصداقة والصراحة مع الله ، مسح إيليا لأليشع نبياً ."},"قال الرب يوماً لإيليا النبى العظيم إذهب « إمسح ياهو بن نمشى ملكاً على اسرائيل ... وامسح أليشع بن شافاط ، نبياً عوضاً عنك » (١مل ١٩ : ١٦) .","لم يقل إيليا : حسناً يارب أن أمسح ياهو ملكاً . ولكن كيف أمسح نبياً عوضاً عنى ؟ وهل استغنيت عن خدماتى ؟ هل يحدث هذا بعد تعبى الكثير من أجلك ، وبعد وقوفى ضد آخاب الملك وزوجته إيزابل ، وبعد تخليصى البلاد من كل أنبياء البعل وأنبياء السوارى ؟ ... هل تغيرت محبتك لى ؟ !","لم يقل شيئاً من هذا ، ولم يشك فى محبة الله ، بل فعل كما أمره ، واثقاً من محبة الله ومن حكمته . بل اعتبرها دالة وصداقة بينه وبين الله ، بها يشركه الله معه فى تنفيذ الخطة الإلهية ، حتى لو كان منها مسح نبى عوضاً عنه . فهذا لا يدل على أن الصداقة بينه وبين الله قد انتهت أو نقصت .","بدليل أن الله رفعه إليه إلى السماء فى مجد (٢مل ٢ : ١١) . وبدليل أنه"],89:["ظهر معه بعد زمن على جبل التجلى يتحدث إليه (مر ٩ : ٤) . إنها المحبة التى يصارحه بها الله ، حتى فى الأمور التى تمسه . وكان مسح نبى عوضاً عنه ، متدمه لترقيته إلى حالة أفضل ، هى أعظم من نبى ...",{h:"٩ ـ صلاة لأجل الإيمان :"},"أطلب من أجل إيمانك فى صلاتك ، لكى ينمو ويزداد .","قل له : إعطنى يارب أن أؤمن بك الإيمان كله . إعطنى أن أحبك وأثق بك فى كل شىء ، وأؤمن أنك تفعل بى خيراً مهما كانت الدنيا مظلمة أمامى . إشعرنى بأن عقلى أصغر بكثير من أن يفهم حكمتك وأحكامك . أنا أعرف أنك صانع الخيرات ، وأنك محب ، وأنك ترى كل شىء ، وقادر على كل شىء . ومع ذلك كثيراً ما أضعف ... فأعن ضعف إيمانى ..."],90:[{h:"الفصل التاسع"},{h:"ما يضعف الإيمان"}],91:["الشيطان يعمل باستمرار ، وبكل جهده ، على إضعاف إيمان المؤمنين .","ويحاول هو وأعوانه أن يضلوا ولو أمكن المختارين أيضاً » (متى ٢٤ : ٢٤) . ولا يكتفى هؤلاء بمجرد إضعاف الإيمان ، بل يحاولون أن يوصلوا فريستهم حتى إلى الإرتداد . وهكذا فى آخر الأيام يرتد كثيرون عن الإيمان « تابعين أرواحاً مضلة وتعاليم شياطين » (١تى ٤ : ١) . وما أخطر قول الكتاب فى المجىء الثانى للمسيح « ولكن متى جاء ابن الإنسان ، ألعله يجد الإيمان على الأرض ؟ ! » (لو ١٨ : ٨) .","فما هى وسائل الشيطان فى إضعاف الإيمان ؟ إنها كثيرة : بعضها عنيف جداً . وبعضها هادىء قد لا يحسه أحد :",{h:"١ ـ الذات :"},{h:"كثيراً ما تقف الذات ضد الله ، وترفضه لأنه ضد رغباتها الخاطئة :"},"تشعر الذات أن الله يحد حريتها ، التى تشتهى أشياء لا يوافق الله عليها . فلكى تتمتع بهذه (الحرية) أو بهذا التسيب ، تنفصل عن الله ، كما انفصل الإبن الضال عن بيت أبيه (لو ١٥ : ١١ ـ ١٤) ، لكى ينفق ماله حسب هواه ... أو ترفض الله . ولعل الوجوديين الملحدين من أمثلة الرافضين لله . وهؤلاء صار شعارهم هو :",{h:"من الخير أن الله لا يوجد ، لكى أوجد أنا ..."},"وهؤلاء قد أخطأوا فَهم المعنى الحقيقى للوجود ، والمعنى الحقيقى للحرية . فليست الحرية هى أن يفعل الإنسان ما يشاء ، فقد تكون مشيئته خاطئة . إنما الحرية الحقيقية هى أن يتحرر الإنسان من كل شىء يشينه ... يتحرر من العادات الرديئة التى تستعبده ، ومن الشهوات الدنسة التى تنجسه . ويتحرر من سيطرة المادة عليه ، هذه التى تمنع روحه من إنطلاقها ومن العشرة مع الله التى هى الوجود الحقيقى ...","ومن معوقات الذات للإيمان ، رغبة الإنسان فى الشعور بذاته ، فى القوة والعظمة والكبرياء ... وهنا يرى الله منافساً له ...",{h:"وهكذا وجد هيرودس أن مولود بيت لحم سينافسه الملك ، فرفض الإيمان"}],92:["به ، وحاول أن يتخلص منه بقتله ... وكان من أمثال هيرودس أيضاً : الكتبة والفريسيون ، الذين رأوا أن المسيح قد أخذ مكانتهم وشعبيتهم كمعلم . فقال بعضهم لبعض « أنظروا ، إنكم لا تنفعون شيئاً . هوذا العالم قد ذهب وراءه » (يو ١٢ : ١٩) . ومن أجل الذات أيضاً رفض كل هؤلاء الإيمان بقيامة المسيح ، لئلا تكون دليلاً يجلب عليهم دم ذلك البار (أع ٥ : ٢٨) ... إن الذات من أكبر معرقلات الإيمان ، لذلك قال الرب :",{h:"« من أراد أن يتبعنى ، فلينكر ذاته ... » (متى ١٦ : ٢٤) ."},"وقال أيضاً « من وجد حياته يضيعها . ومن أضاع حياته من أجلى يجدها » (متى ١٠ : ٣٩) . وهكذا نجد أن القديس بولس الرسول ، من أجل الإيمان يقول « لست أحتسب لشىء ، ولا نفسى ثمينة عندى » (أع ٢٠ : ٢٤) ، « بل أنى أحسب كل شىء أيضاً خسارة ، من أجل فضل معرفة المسيح يسوع ربى ، الذى من أجله خسرت كل الأشياء وأنا أحسبها نفاية ، لكى أربح المسيح وأوجد فيه » (فى ٣ : ٨ ، ٩) . فهل أنت كذلك ؟ أم ...",{h:"هل إيمانك يتعطل بسبب ذاتك ؟ بسبب رغباتك وغرائزك وأفكارك وشهواتك ؟ !"},"هل هناك تعارض بين الله وذاتك ؟ إن كان كذلك ، إنكر ذاتك . قاومها . إنتصر عليها . لأن مالك روحه خير من مالك مدينة (أم ١٦ : ٣٢) .","إن الكتبة والفريسيين والكهنة والشيوخ ، كانوا يحرصون على ذاتهم حرصاً خاطئاً . كانت فى ذات كل منهم عيوب ، وكان المسيح يكشفها ، حتى دون أن يتكلم عنها . بمجرد المقارنة تنكشف . لذلك كانوا يكرهونه ، ولم يؤمنوا به ، لأنه نور يهتك ظلمتهم ... ووقفت ذاتهم ـ التى تود أن تتغطى ـ عقبة فى طريق إيمانهم .",{h:"لا ننس أن الشيطان نفسه ، كانت ذاته سبباً فى ضياع إيمانه ."},"وذلك حين فكر كيف تكبر هذه الذات ... كيف يصعد إلى السموات ، ويرتفع فوق كواكب الله ، ويصير مثل العلى (اش ١٤ : ١٤) . فوقفت (عظمة) ذاته ضد الإيمان بالله . أما الملائكة الأطهار فاحتفظوا بمكانتهم ، لأنهم فى إيمانهم بالله حسبوا أنفسهم « خدامه العاملين مرضاته » (مز ١٠٣ : ٢١) ."],93:[{h:"كثيرون أنفسهم جميلة فى أعينهم . ذاتهم هى صنمهم ."},"يمنعهم عن حياة الإيمان : محبة الذات ، والإعتداد بالذات ، والرغبة فى تكبير الذات ، وتفخيم الذات ، وتحقيق شهوات الذات ، والهروب من كل من يكشف هذه الذات أو يظهر مساوئها ... وهكذا يريدون أن تحيا ذاتهم فى جو من التدليل والمجاملة والمديح . يتضايقون من كل كلمة صريحة ومن كل تأنيب وكل تأديب . فكيف يمكنهم أن يحيوا فى الإيمان ؟ !","إن كنت كذلك أصلح ذاتك لكى تتضع أمام الله ، فتحيا فى الإيمان ...","كذلك من الأمور التى تضعف الإيمان :",{h:"٢ ـ سيطرة الحواس :"},"وفى هذا وقع القديس توما الرسول ، حينما رفض الإيمان بقيامة الرب ، وقال « إن لم أبصر فى يديه أثر المسامير ، وأضع أصبعى فى أثر المسامير ، وأضع يدى فى جنبه ، لا أؤمن » (يو ٢٠ : ٢٥) وقد تنازل الله لضعف توما ، وسمح له أن يتأكد بحواسه قائلاً له « ولا تكن غير مؤمن بل مؤمناً » ، ووبخه قائلاً « لأنك رأيتنى ياتوما آمنت ؟ ! طوبى للذين آمنوا دون أن يروا » (يو ٢٠ : ٢٧ ، ٢٩) . هذا الذى يبصره الإنسان ، نسميه عياناً لا إيماناً . ولكنه قد يؤدى إلى الإيمان ...",{h:"أهذا إيمان ضعيف ؟ هناك ما هو أسوأ : أى الذى يرى ولا يؤمن ."},"مثال ذلك : الكهنة الذين رأوا القبر الفارغ ولم يؤمنوا بالقيامة . والكتبة والفريسيون الذين رأوا معجزات المسيح كشفاء المولود أعمى وإقامة الموتى ولم يؤمنوا . هؤلاء رافضون للإيمان لأسباب فى قلوبهم . وينطبق عليهم قول أبينا ابراهيم لغنى لعازر « ولا إن قام واحد من الموتى يصدقون » (لو ١٦ : ٣١) .",{h:"٣ ـ إخضاع الإيمان للعقل :"},"وقد قلنا قبلاً إن العقل له حدود لا يتعداها ، وإن الإيمان مستوى أعلى منه . ولكن هناك أشخاصاً يريدون أن تعى عقولهم اللا محدود ، وما هو فوق إدراكهم ، وإلا فإنهم يرفضون كل هذا ! ... يريدون أن تخضع اللاهوتيات كلها للفحص العلمى ... وهذا غير ممكن منطقياً . وليس من العقل ، أن يخضع غير المحدود"],94:["للعقل ، الذى هو محدود !","ولعل من أمثلة هذا فى أيامنا ما يعرف فى بعض المعاهد باسم علم اللاهوت الجديد New Theology حيث يريدون إخضاع الوحى والمعجزة للبحث العلمى البحت ، أو لمجرد التفسير الرمزى . وبهذا ينكرون كثيراً من المعجزات ومن قصص الكتاب ، ويدخلونها فى علم الأساطير Mythology ! ! حقاً إن العقل يضل ، إذا حاول أن يرتئى فوق ما ينبغى له أن يرتئى (رو ١٢ : ٣) . وبهذا ينحرف عن الإيمان ، ويحاول أن يقود غيره فى نفس الإنحراف .",{h:"٤ ـ معاشرة الشكاكين :"},"كما أن معاشرة رجال الإيمان تقوى الإيمان ، كذلك معاشرة الشكاكين تغرس الشك فى العقول والقلوب ، إن كانت بمداومة ، أو من النوع العميق التأثير ، أو كان المستوى الخاضع للشكوك أقل فى المعرفة أو المستوى العقلى ، أو كان غير عميق فى الإيمان .",{h:"ولهذا فإن الكتاب يمنع من مخالطة المنحرفين فى إيمانهم وفى أفكارهم ."},"يقول القديس يوحنا الرسول « إن كان أحد يأتيكم ولا يجىء بهذا التعليم ، فلا تقبلوه فى البيت ، ولا تقولوا له سلام . لأن من يسلم عليه يشترك فى أعماله الشريرة » (٢يو ١٠ ، ١١) . وهكذا منعت الكنيسة الخلطة بالهراطقة والمبتدعين ...","وكم من أناس خالطوا جماعات غير مسيحية مثل شهود يهوه والسبتيين ، فكانت النتيجة أنهم انحرفوا فى تياراتهم . وكم من أعضاء فى الكنيسة خالطوا طوائف غريبة أو ملحدين ، فتأثرت معتقداتهم بهم إلى حد بعيد .",{h:"وحتى من جهة السلوك والروحيات ، مخالطة الشكاكين تضعف الإيمان :"},"قد تحدث لك تجربة أو مشكلة وتقبلها فى إيمان ، وتسلم الأمر لله شاكراً إياه على كل حال . ثم يزورك شخص قليل الإيمان ، فيظل يشرح لك خطورة الموضوع ، ويخيفك جداً من نتائجه ، حتى تفقد سلامك القلبى ، ويضعف إيمانك فى حفظ الله وتقلق ...","لذلك كن حريصاً جداً فى اختيار من تعاشرهم وتختلط بأفكارهم .","وهذا يقودنا إلى نقطة أخرى تضعف الإيمان وهى :"],95:[{h:"٥ ـ الإنقياد وضعف الشخصية :"},"من هذا النوع ، مريم المجدلية : لقد رأت القبر الفارغ ، وسمعت بشارة الملاك ، بل إنها رأت السيد المسيح نفسه بعد قيامته ، وأمسكت بقدميه ، وسمعت صوته ، وكلفها برسالة ... ولكنها مع ذلك قالت ثلاث مرات « أخذوا سيدى ، ولست أعلم أين وضعوه » (يو ٢٠ : ٢ ، ١٣ ، ١٥) . وفى هذا إنكار للقيامة . فما السر فى هذا التحول ؟ وكيف ضعف إيمانها بعدما رأت المسيح وكلمته ؟ (مر ١٦ : ٩ ، مت ٢٨ : ٩)","كانت المجدلية صغيرة فى سنها . وقد ضعفت شخصيتها أمام الشائعات التى نشرها كهنة اليهود ضد القيامة . كما ضعفت أمام عدم تصديق التلاميذ أولاً للقيامة (مر ١٦ : ١١ ، ١٣ ، ١٤) . فبدأت تلعب بها الشكوك والأوهام ، وررددت بفمها ما سمعته من شائعات .",{h:"لم يستطع إيمان المجدلية أن يصمد أمام الشائعات وكلام الناس ..."},"فاهتزت من الداخل بسبب التأثير الخارجى الضاغط ، وانقادت إليه ... !","وكثير من الناس يهتزون من الداخل ، ويتحولون عن إيمانهم الأول ، عقيدة أو سلوكاً ، بسبب استهزاء الناس . وبسبب أن شخصيتهم أضعف من أن تصمد .","إن الله يريد أن تكون شخصياتكم قوية . وكما يقول الرسول :",{h:"مستعدين كل حين ، لإجابة كل من يسألكم عن سبب الرجاء الذى فيكم » (١بط ٣ : ١٥) ."},"إن أولاد الله لا يليق بهم أن يكونوا ضعفاء ، من النوع الذى يهتز إيمانه ، أو تهتز روحياته ، وينقاد لأى فكر خارجى . بل إنهم يعملون بقول الرسول « إذن يا إخوتى الأحباء ، كونوا راسخين غير متزعزعين ... » (١كو ١٥ : ٥٨) .","أيضاً من النوع الذى تحول عن إيمانه بسبب الإنقياد : أمنا حواء . فالكلام الذى سمعته من الحية ، جعلها تتحول عن إيمانها ، وينتهى الأمر بطردها من الجنة !","ما أكثر الذين ينقادون وراء الشائعات ويصدقونها . وما أكثر من يرددون كلاماً عن المجىء الثانى ويصدقه الناس . ويقولون إن (المسيح الدجال) Anti Christ قد وُلد ، وأنه فى ولاية بأمريكا ، وأن عمره الآن ١٧ سنة ! ! وأن العالم سينتهى فى هذه"],96:["السنة أو غيرها ! ! وما أكثر التواريخ التى حددها شهود يهوه والسبتيون عن المجىء الثانى ، ولم يتم منها شىء ...",{h:"وقد يضعف إيمان البعض وينقادون وراء من يدّعى الرؤى والأحلام ."},"ويظنون أن ما يدعيه من الرؤى والأحلام ، كلها حقيقية ومن الله ! ثم ينخدعون بما يقوله من كلام ، ولو ضد معتقداتهم أو مبادئهم الروحية . ولقد حذّر الرب من هؤلاء منذ أيام موسى النبى فقال :","« إذا قام فى وسطك نبى أو حالم حلماً ، وأعطاك آية أو أعجوبة ، ولو حدثت الآية أو الأعجوبة التى كلمك عنها ، قائلاً : لنذهب وراء آلهة أخرى لم تعرفها ونعبدها . فلا تسمع لكلام ذلك النبى أو الحالم ذلك الحلم . لأن الرب إلهكم يمتحنكم لكى يعلم هل تحبون الرب إلهكم من كل قلوبكم ... » (تث ١٣ : ١ ـ ٣) .","إن الإنقياد من الأسباب التى تضعف الإيمان . وكذلك من أسبابه :",{h:"٦ ـ الخوف :"},{h:"الخوف يضعف الإيمان . وضعف الإيمان يؤدى إلى الخوف ."},"القديس بطرس ، الرسول العظيم ، لما خاف أنكر المسيح ، وسب ولعن وحلف أنه لا يعرف الرجل (متى ٢٦ : ٧٤) . وهكذا ضعف إيمانه . بل قال له المسيح قبلها « طلبت من أجلك لئلا يفنى إيمانك » (لو ٢٢ : ٣٢) .","وكثيرون فقدوا إيمانهم بسبب خوفهم . ولهذا فإن سفر الرؤيا وضع الخائفين فى مقدمة الهالكين فقال « وأما الخائفون وغير المؤمنين والرجسون ... فنصيبهم فى البحيرة المتقدة بالنار والكبريت » (رؤ ٢١ : ٨) . ووضعه الخائفين قبل غير المؤمنين ، ربما المقصود بها الخائفين الذين بسبب خوفهم يصيرون غير مؤمنين .","بيلاطس البنطى ، كان مؤمناً فى أعماقه أن يسوع الناصرى برىء من التهم التى ألصقها به اليهود . وكان واثقاً أنهم أسلموه حسداً . وقد حاول أن يطلقه . وقال عنه « هذا البار » ... ولكنه أخيراً استسلم لضعفه ، وأسلم المسيح للصلب ، إذ خاف أن يقال عنه إنه ضد قيصر ..."],97:["أما الإنسان الروحى ، فهو لا يفقد إيمانه إطلاقاً ، لأنه لا يخاف ...","ومن الأمور التى تضعف الإيمان أيضاً :",{h:"٧ ـ الشهوة :"},"كثيرون فقدوا إيمانهم بسبب الشهوة . ولعل من أمثلتهم دياس مساعد بولس الرسول فى الكرازة والتبشير ، الذى قال عنه القديس بولس أخيراً « ديماس قد تركنى ، لأنه أحب العالم الحاضر » (٢تى ٤ : ١٠) . ومحبة العالم تضعف الإيمان ، لأنها عداوة لله (يع ٤ : ٤) .","ومن أمثلة الذين فقدوا إيمانهم بسبب الشهوة : الشاب الغنى ... هذا ترك المسيح « ومضى حزيناً لأنه « كان ذا أموال كثيرة » (متى ١٩ : ٢٢) . إذن شهوة المال يمكن أن تضعف الإيمان :","وما أكثر الذين تركوا المسيح من أجل إمرأة أو منصب ...",{h:"شهوة النساء ضيعت إيمان سليمان الحكيم ، أحكم أهل الأرض ..."},"وذلك أنه « أحب نساء غريبة » (١مل ١١ : ١) . وكان فى زمان شيخوخة سليمان و أن نساءه أملن قلبه وراء آلهة أخرى . ولم يكن قلبه كاملاً مع الرب إلهه كقلب داود أبيه . فذهب سليمان وراء عشتاروت الهة الصيدونيين ، وملكوم رجس العمونيين . وعمل سليمان الشر فى عينى الرب ... » (١مل ١١ : ٣ ـ ٦) ... إلى هذا الحد سقط هذا الحكيم العظيم ، ولو أننا نؤمن أنه تاب فى أواخر أيامه . وكان سفر الجامعة من دلائل توبته .",{h:"وشهوة المال أضاعت إيمان حنانيا وسفيرا ، فهلكا ."},"فوقعا فى « الكذب على الله » (أع ٥ : ٤) ، وأيضاً فى « تجربة روح الرب » (أع ٥ : ٩) . وماتا الإثنان هالكين ...",{h:"وشهوة المال أيضاً ضيّعت إيمان بلعام . وكان نبياً وله نبوءات جميلة عن المسيح (عدد ٢٢ ـ ٢٤) . وأخيراً وقع فى ضلالة لأجل أجرة الإثم » (٢بط ٢ : ١٥) . وهكذا كان معثرة لكل الشعب ، وعلّم بالاق طريق الخطية (رؤ ٢ : ١٤) ... فهلك وأهلك غيره ..."}],98:[{h:"وشهوة العظمة والتقدم على الآخرين ، أضاعت إيمان كثيرين :"},"لعل من بين هؤلاء « ديوتريفس » الذى كان « يحب أن يكون الأول » . لذلك قاوم القديس يوحنا الحبيب ، وطرد إخوة كثيرين من الكنيسة (٣يو ١٠) .",{h:"وشهوة الألوهية ضيعت إيمان كاروب عظيم ، فتحول إلى شيطان ، وكان من قبل ملاكاً من نور ، له بهاء ومجد ..."},"إن الشهوات من أكبر الأمور التى تضعف الإيمان أو تضيعه .","ومن الأسباب التى تضعف الإيمان ، الضيقات وضغط الظروف الخارجية .",{h:"٨ ـ الظروف الخارجية :"},"ولعل من أمثلة هذا الأمر جدعون لما ضعف إيمانه فى عناية الله : قال له الملاك « الرب معك يا جبار البأس . فقال له جدعون : أسألك يا سيدى إذا كان الرب معنا ، فلماذا أصابتنا كل هذه (البلايا) ؟ وأين كل عجائبه التى أخبرنا بها آباؤنا ... والآن قد رفضنا الرب وجعلنا فى كف مديان » (قض ٦ : ١٢ ، ١٣) .",{h:"وهكذا قد تضعف الإيمان الضيقة إذا طالت ، أو إذا اشتدت ."},"التلاميذ لما اشتدت عليهم الأمواج فى السفينة ، ضعف إيمانهم وشكوا قائلين للرب « أما يهمك أننا نهلك » (مر ٤ : ٣٨ ـ ٤٠) .","وبنو اسرائيل لما طالت بهم المدة فى عبودية فرعون ، صغرت نفوسهم وضعف إيمانهم فى الخلاص (خر ٤ : ١) .","هناك سبب خطير آخر يسبب ضعف الإيمان ، وهو :",{h:"٩ ـ ضلالات الشياطين :"},"ومن هذه الضلالات : الرؤى الكاذبة . فإن الشيطان ـ لكى يخدع البشر ـ يستطيع أن « يغيّر شكله إلى شبه ملاك نور » (٢كو ١١ : ١٤) . بل يستطيع أن يقدم عجائب كاذبة كما قيل عن المقاوم ضد المسيح فى آخر الزمان « الذى مجيئه بعمل الشيطان بكل قوة وبآيات وعجائب كاذبة ، وبكل خديعة الإثم فى الهالكين » (٢تس ٢ : ٩ ، ١٠) . وقال الرسول إن كل هذا سوف يسبب الإرتداد قبل مجىء"],99:["المسيح (٢تس ٢ : ٣) ، أى ضياع الإيمان بسبب هذه الضلالات الشيطانية التى تخدع الناس .","إن الشيطان قد يخدع الناس بأحلام وبنبوءات كاذبة ، وبأفكار ضلالات وبدع ، لكى يحطم الإيمان فى قلوبهم ... بل قد يرسل إليهم « مُسحاء كذبة وأنبياء كذبة . ويعطون آيات عظيمة وعجائب (متى ٢٤ : ٢٤) . وقد يقول لهم هذا هو المسيح . ولذلك سبق المسيح فأنذر وقال « إن قال لكم أحد : هوذا المسيح هنا أو هناك ، فلا تصدقوا » (متى ٢٤ : ٢٣) .","وكل هذا يحتاج إلى إفراز ، وكما قال الرسول « لا تصدقوا كل روح . بل إمتحنوا الأرواح هل هى من الله . لأن أنبياء كذبة كثيرين قد خرجوا إلى العالم » (١يو ٤ : ١) .","ومن الأشياء الأساسية التى تحارب الإيمان :",{h:"١٠ ـ الشـــــك :"},{h:"الشك يضعف الإيمان . وضعف الإيمان يولد الشك ..."},"تماماً كما قلنا عن الخوف . وكلاهما يسبب الآخر ، أو ينتج عنه .","أ ـ وكان الشك من الحروب التى حارب بها الشيطان أبوينا الأولين ليضيع إيمانها . فقال لها « أحقاً قال لكما الله ... ؟ ! كلا ، لن تموتا » (تك ٣ : ١ ـ ٤) .",{h:"فإن حاربتك الشكوك من جهة وجود الله أو بعض العقائد الأساسية ، فلا تخف . هذه محاربات من العدو ، وليست إنكاراً منك للإيمان . وبخاصة إن كان قلبك رافضاً لها . لذلك فى مثل هذه الحالات يجب أن تصلى لكى يرفع الرب عنك هذه الحروب . وأن تغير مجرى تفكيرك ، بأن تنقل أفكارك إلى موضوع آخر تنشغل به ."},"أما إن كانت الشكوك منك ، وأنت مقتنع بها ، فعليك أن تعالجها بفهم إيمانى سليم ، بسؤال المتخصصين فى اللاهوت ، وبقراءة الكتب المفيدة فى موضوعك .","على أن هناك حروباً أخرى للشك أخف من هذه ، نذكر منها :",{h:"ب ـ الشك فى معونة الله ، أو فى أن الله قد تخلى عنك ."},"إن الرب يوبخ على هذا الشك قائلاً « يا قليل الإيمان ، لماذا شككت » (متى"],100:["١٤ : ٣١) . وهنا يربط بين الشك وقلة الإيمان . لأن الإنسان القوى الإيمان لا يمكن مطلقاً أن يشك فى محبة الله ورعايته .","ولكن الضيقات الكثيرة المستمرة ، قد تضغط على القلب أحياناً فيقول : « لماذا يارب تقف بعيداً ، لماذا تختنى فى أزمنة الضيق » (مز ١٠ : ١) .","إنه عتاب ، وليس ضعفاً فى الإيمان . وقد يبدو للمرتل أن الرب يقف بعيداً . ولكنه يرقب بكل حب ، وبكل حرص على سلامة أولاده . كالنسر الذى يعلم فراخه الطيران ، وكالأب الذى يعلم إبنه العوم . يتركه قليلاً ليتدرب ويكتسب خبرة . ويرقبه بكل حرص . فإن رأى خطراً يحيق به ، يسرع إلى حمله وإنقاذه .","هناك أيضاً مثال الأم التى تعلم إبنها المشى . فتتركه ليقوم ويسقط وتشتد عظامه وتقوى عضلاته ويتعلم . أما إن كانت فى كل صرخة منه ، تسرع وتحمله على كتفها فإنها بهذا ستضره . لأنه لن يتعلم ، ولن تقوى عظامه كما ينبغى ...",{h:"إن أزمنة الضيق ، هى مدرسة لنا ، نتدرب فيها على الصلاة والتمسك بالله . ونتدرب فيها على الإيمان ، ونرى فيها كيف أن الله يعمل ، وبقوة ..."},"ويقيناً أن الله يعمل ، مهما كنت لا تراه ولا تلمس عمله .","إن الإنسان قد يشك إن نظر فقط إلى المتاعب ، وليس إلى الله . وهكذا نرى أن بطرس قد شك حينما نظر إلى الماء الذى تحت قدميه ، ولم ينظر إلى المسيح الذى يمسك بيديه . وإذ هبط إيمان بطرس ، هبط هو أيضاً إلى الماء ، ولكن إلى لحظة ، وأنقذه الرب .","قد يكون أولاد الله « كحملان وسط ذئاب » ، ولكنهم لا يشكون ولا يخافون . فمادام الراعى الصالح وسط الحملان ، فلن تقوى عليهم الذئاب ولا حتى الأسود .","إن أبانا ابرآم لم يشك فى محبة الله وعنايته ، على الرغم من صعوبة الأمر الصادر إليه بتقديم إبنه اسحق محرقة . وكأنه يقول :",{h:"إن قلبى ليس أحن من قلب الله على إبنى إسحق ، ولا أنا أستطيع أن أدبر مستقبل إسحق كما يدبره الله ،"},"فمادام الرب موافقاً على شىء ، فلا بد أن أوافق أنا عليه أيضاً بالضرورة ، لأنى"],101:["لست فى حكمة الله ولا فى محبته . لتكن إذن مشيئته .",{h:"إن الذى لا يشك ، يعيش دائماً فى راحة وفى سلام ."},"يحيا دائماً مطمئناً ، لا تتعبه العوامل الخارجية . ولا يفرض على الله حلولاً معينة ، يتضايق إن لم ينفذها الله ! بل هو يرضى بكل حل يأتى من عند الله حسب وافر حكمته الإلهية .","ما أكثر المتاعب التى تولدها الشكوك فى القلب وفى الفكر ... مثل القلق والخوف والإضطراب وقلة المحبة . مجرد الشك نفسه هو تعب . نار تحرق ...",{h:"الشك يعالج بالثقة ويعالج بالحب . فمن يحب شخصاً لا يشك فيه . وهكذا نحن مع الله ، لا نشك فيه ، لأننا نحبه ونثق به . وإيماننا به لا يسمح لنا مطلقاً أن نشك فى معاملاته الإلهية لنا ، وفى معاملاته الأبوية لنا . مبارك هو فى كل ما يعمله ."},{h:"إن الإيمان يقتل الخوف والشك . والخوف والشك قد يقتلان الإيمان ."},"تمسك إذن بإيمانك ، لأنه هو العنصر الأقوى ، وهو العنصر المنتصر دائماً . حينئذ سوف تحيا فى فرح وسلام واطمئنان ، بلا خوف ، بلا شك ، كل أيام حياتك ."],102:[{h:"الفصل العاشر"},{h:"إختبار الإيمان : هل أنتم فى الإيمان"},"« جربوا أنفسكم : هل أنتم فى الإيمان ؟ إمتحنوا أنفسكم » (٢كو ١٣ : ٥) ."],103:["هناك طرق كثيرة لاختبار الإيمان ، يمكن استنتاجها من كل ما سبق . ونريد أن نقول ههنا إن الرسول ـ فى حياة الإيمان ـ لا يتكلم عن مجرد الإيمان ، أى الإعتراف باسم الرب ، وإنما يذكر بالتخصيص :",{h:"١ ـ الإيمان العامل بالمحبة (غل ٥ : ٦) :"},"إختبر إذن إيمانك بالمحبة حسبما شرحها الرسول فى (١كو ١٣) ...","المحبة تتأنى ، وترفق ، ولا تحسد ، ولا تتفاخر ، ولا تنتفخ ، ولا تقبّح ، ولا تطلب ما لنفسها ، ولا تحتد ، ولا تظن السوء ، ولا تفرح بالإثم ... وتحتمل كل شىء ، وتصدق كل شىء ، وترجو كل شىء ، وتصبر على كل شىء » (١كو ١٣ : ٤ ـ ٧) .","فهل توجد فيك كل هذه الصفات ، ليكون إيمانك سليماً ؟ لقد قال الرسول « إن كان لى كل الإيمان حتى أنقل الجبال ، ولكن ليست لى محبة ، فلست شيئاً » (١كو ١٣ : ٢) . بهذه المحبة يمكنك أن تختبر إيمانك ...","بل إنك تختبر الإيمان بالأعمال عموماً .",{h:"٢ ـ تختبر الإيمان بالأعمال عموماً :"},"ذلك لأن الرسول يقول « وأنا أريك بأعمالى إيمانى » (يع ٢ : ١٨) . فبالأعمال تختبر إيمانك هل هو إيمان حى أم ميت لأن « الإيمان بدون أعمال ميت » (يع ٢ : ٢٠) . والإيمان الميت لا يقدر أن يخلص أحداً (يع ٢ : ١٤) .","والقديس بولس الرسول أكثر من تحدث عن أهمية الإيمان ، نراه يقول :",{h:"« يعترفون بأنهم يعرفون الله ، ولكنهم بالأعمال ينكرونه » (تى ١ : ١٦) ."},"وفى رسالته الأولى إلى تيموثاوس يشدد كثيراً على هذه النقطة ، فيقول إن « الذى لا يعتنى بخاصته ... قد أنكر الإيمان وهو شر من غير المؤمن » (١تى ٥ : ٨) . وإن الأرامل اللائى رفضن نذر البتولية قد « رفضن الإيمان الأول » (١تى ٥ : ١٢) . وإن الذين يحبون المال ، قد « ضلوا عن الإيمان » (١تى ٦ : ١٠) . وإن"],104:["المهتمين بالكلام الباطل الدنس « قد زاغوا من جهة الإيمان » (١تى ٦ : ٢١) .",{h:"إذن سلوك الإنسان يمكن أن يكون اختباراً لإيمانه ."},"هوذا القديس يوحنا الرسول يقول « من قال قد عرفته ، وهو لا يحفظ وصاياه ، فهو كاذب وليس الحق فيه » (١يو ٢ : ٤) ، « من قال إنه ثابت فيه ، ينبغى أنه كما سلك ذاك يسلك هو أيضاً » (١يو ٢ : ٦) . وبهذا نقول :",{h:"٣ ـ نختبر إيماننا بنقاوة القلب :"},"ولماذا ؟ لأن الذى يؤمن أن الله كائن أمامه ، وأن الله قدوس يكره الخطية ، وأنه عادل يجازى كل إنسان حسب أعماله ، هذا يخاف أن يخطىء أمام الله ، ويستحى أن يخطىء ، كما يستحى أن يجرح قلب الله المحب ، إن كان يؤمن بمحبة الله .","هوذا الرسول يقول « كل من يخطىء ، لم يبصره ولا عرفه » (١يو ٣ : ٦) . يقيناً إن الذى يخطىء ، لا يكون فى فكره أثناء الخطية أن الله يرى ويسمع ويسجل ... ويقيناً إن الذى يظلم ، لا يكون مؤمناً تماماً أن هناك إلهاً موجوداً « يحكم للمظلومين » (مز ١٤٦ : ٧) . ولذلك إذا قيل لظالم « ربنا موجود » يخاف ويرتعش .","ويقيناً إن المتكبر ، أو المنتفخ بالمديح ، لا يشعر مطلقاً أنه قائم أمام الله . إن هيرودس لما خاطب الشعب ومدحوه قائلين « هذا صوت إله ، لا صوت إنسان » فابتهج بهذا المديح ، لم يكن عنده إيمان أن الله أمامه ، لذلك « ضربه ملاك الرب ، لأنه لم يعط مجداً لله . فصار يأكله الدود ومات » (أع ١٢ : ٢١ ـ ٢٣) .","المؤمن الحقيقى يمكن اختباره أيضاً بالزهد وعدم اشتهاء الأمور التى فى العالم ، فالمؤمنون مكتفون بما هم فيه (فى ٤ : ١١) .","وبالنسبة لاحتياجاتهم ، لا يحتجون على شىء ، ولا يحتاجون إلى شىء .","نقطة أخرى فى حياة الإيمان هى :",{h:"٤ ـ يُختبر الإيمان بما يمنحه من قوة :"},"هل لديك قوة الإيمان التى تشعر بها أن كل شىء مستطاع ؟"],105:["وكما قال الرب « كل شىء مستطاع للمؤمن » (مر ٩ : ٢٣) . هل تشعر أن هناك شيئاً صعباً أو مستحيلاً ، أو لا يصدق إيمانك بأن الله يمكن أن يعمله ؟ هل تقف فى شك أمام الأشياء التى تحتاج إلى معجزة ؟ ! هل يمكنك أن تقول كما قال القديس بولس الرسول « أستطيع كل شىء فى المسيح الذى يقوينى » (فى ٤ : ١٣) . هل تهزك العقبات والصعوبات بحيث تقول « لا فائدة » ؟ ! هل يحاربك اليأس ؟",{h:"إن اليأس ضد الإيمان ، وضد الرجاء ، من كل ناحية ."},"لا شك إن المنتحرين فقدوا إيمانهم ورجاءهم ، وشعروا أنه لا حل ، كما فقدوا الإيمان بحقيقة الحياة بعد الموت فى الأبدية ومصير المنتحرين فيها .","وكذلك الذين استسلموا للأمر الواقع ، أو للضغوط الخارجية ، وخضعوا للخطية ، لم يؤمنوا إطلاقاً أن هناك قوة يمكن أن تسندهم وتخلصهم .","إن الإيمان قوة لمن يستطيع أن يستخدمها فى ثقة بلا شك .",{h:"أخشى أن يكون الإيمان فى أيدى البعض كعصا أليشع فى يد جيحزى (٢مل ٤ : ٣١) . وأخشى أن يكون الصليب فى أيدى البعض كذلك : يحسنون حمله ورشمه ، وليس الإيمان به . معهم الصليب وليست معهم قوته التى هى كامنة فى الإيمان به وبعمله ..."},"هل تظنون أن عصا موسى هى التى شقت البحر الأحمر ؟ أم هو إيمان موسى حامل هذه العصا ومستخدمها باسم الرب ؟",{h:"فهل لك قوة الإيمان التى كانت لموسى حينما ضرب البحر بعصاه ؟"},"إنك كثيراً ما تصلى . ولكن هل فى صلاتك الإيمان الذى يعطى لهذه الصلاة قوة ؟ ما أعجب قول الكتاب حين قال عن إيليا إنه « صلى صلاة » (يع ٥ : ١٧) . وهذه الصلاة لم تكن عادية كصلوات باقى الناس ، إذ أنها استطاعت أن تغلق السماء مرة ، وأن تفتحها مرة أخرى ...","إختبر إيمانك إذن بالقوة التى لك نتيجة علاقتك بالله ."],106:[{h:"٥ ـ إختبار الإيمان فى الضيقة :"},"الضيقات تحل بكل أحد . ولكن هناك فرقاً كبيراً بين المؤمن وغير المؤمن فى الروح التى تُستقبل بها الضيقة .",{h:"إن كانت الضيقة تفقدك سلامك ، فاعرف أن إيمانك ضعيف ."},"المؤمن يستقبل الضيقة مؤمناً أنها للخير ، وأن الله سيحلها . فلا يتضايق فى داخله ، ولا يضطرب ، ولا تنشغل أفكاره بها ، ولا يتعب قلبه بالحزن والألم . إنما يواجه الضيقة بثلاث آيات هى « كل الأشياء تعمل معاً للخير ، للذين يحبون الرب » (رو ٨ : ٢٨) ، و « إحسبوه كل فرح يا إخوتى ، حينما تقعون فى تجارب متنوعة » (يع ١ : ٢) . وأيضاً « كل شىء مستطاع للمؤمن » (مر ٩ : ٢٣) . وبهذا الإيمان يفرح قلبه فى الضيقة ، ويتعزى الناس بفرحه .",{h:"المؤمن يضع الله بينه وبين الضيقة ، فتختفى الضيقة ويظهر الله ."},"ويذكر يد الله التى كانت مع القديسين فى كل ضيقاتهم « وملاك حضرته خلصهم » (اش ٦٣ : ٩) . يذكر ما حدث لموسى ويوسف وداود وأيوب ودانيال وللثلاثة فتية . وكل هذه الذكريات تزيده إيماناً بالله وثقة فى تدخله وعمله . وهكذا لا يتزعزع فى الضيقة ، ولا يشك ولا يحزن ولا يحمل هماً ... بل يقول مع المرتل « نجت أنفسنا مثل العصفور من فخ الصيادين . الفخ انكسر ونحن نجونا ، عوننا من عند الرب الذى صنع السماء والأرض » (مز ١٢٤) .",{h:"يقول للرب : مادمت أنت موافق على الضيقة ، فأنا أفرح بها ."},"ليس فقط أقبلها ، أو أرضى بها ، إنما أحسبه كل فرح أن الرب يعطينى بركة هذه الضيقة ... ما أجمل ما قيل عن الآباء الرسل بعد أن جلدوهم « وأما هم فذهبوا فرحين ... لأنهم حُسبوا مستأهلين أن يهانوا من أجل إسمه » (أع ٥ : ٤١) .",{h:"المؤمن مهما بدت كل الأبواب مغلقة ، يرى باب الله مفتوحاً ."},"إنه يؤمن بالله ، الذى بيده مفاتيح السماء والأرض « الذى يفتح ولا أحد يغلق » (رؤ ٣ : ٧) . ويرتل هذا المؤمن مع القديس يوحنا الراثى قائلاً « بعد هذا نظرت ، وإذا باب مفتوح فى السماء » (رؤ ٥ : ١) . بل اختبار الإيمان بأن ترى"],107:["جميع الأبواب مفتوحة أمامك . وكلما ترى أمامك باباً مغلقاً ، تقول : ليس هذا هو الباب الذى يريدنى الله أن أدخل منه . هناك أبواب أخرى كثيرة مفتوحة عند الله . وهناك أبواب مغلقة الآن سيفتحها فيما بعد ... وبهذا الإيمان تستريح .",{h:"٦ ـ إختبار الإيمان ببعض الوصايا :"},{h:"أ ـ من الوسائل التى يُختبر بها الإيمان : العشور أو العطاء عموماً . وبخاصة إذا كان هذا المؤمن محتاجاً ، أو مطلوب منه أن يعطى من أعوازه ."},"ضعيف الإيمان يقول « إن كان المرتب كله أو الإيراد كله لا يكفى ، فكيف يكون الحال إن نقص أيضاً عشره ؟ ! » . أما المؤمن فإنه يقول : إن إعطائى العشور ، يجعل الباقى مباركاً فيكفى ويزيد ...",{h:"إن العشور إختبار روحى عرضه الرب نفسه فى سفر ملاخى فقال :"},"هاتوا جميع العشور ... وجربونى بهذا ، قال رب الجنود : إن كنت لا أفتح لكم كوى السماء ، وأفيض عليكم بركة حتى لا توسع ... (ملا ٣ : ١٠) . فإن كان الشخص ـ على الرغم من هذا الوعد الإلهى ـ لا يدفع ، فلا شك أن إيمانه يكون ضعيفاً فى وعد الله وفى بركته . وقبل ذلك فى وصيته ...",{h:"إن كان هذا فى العشور ، فماذا عن وصيته : من سألك فاعطه ؟ (متى ٥ : ٤٢) . وماذا عن وصية « إذهب بع كل مالك واعطه للفقراء » (متى ١٩ : ٢١) . وماذا عن وصية « بيعوا أمتعتكم [ أو مالكم ] واعطوا صدقة » (لو ١٢ : ٣٣) ؟"},"بهذا يختبر إيمانك : هل الله قادر أن يعولك بما يبقى بعد دفع نصيب الفقراء ؟ وأيضاً هل هو قادر أن يعولك دون أن تكنز لك كنوزاً على الأرض (متى ٦ : ١٩) .",{h:"ب ـ من الوصايا التى يختبر بها الإيمان أيضاً : حفظ يوم الرب ."},"هل أنت تفرح بيوم الرب لكى تقضيه مع الرب ؟ أم أنت تفضل عليه مشغوليات أخرى عديدة ؟ هل أمورك العالمية أهم فى نظرك ؟ وهل تأجيلها أمر لا تحتمله ولا تستطيع ترتيبه بتنظيم وقتك ؟ إنه إختبار لإيمانك ."],108:[{h:"ج ـ وكذلك من الإختبارات الهامة : مدى محبتك للصلاة :"},"هل تنساها وتمر عليك أوقات كثيرة لا تصلى فيها ؟ وهل إذا وقفت للصلاة ، تفكر كيف تنتهى منها لتنشغل بأمور أخرى تهمك بالأكثر ؟ وهل أثناء صلاتك تسرح فى أمور أخرى ، وتنسى أنك واقف أمام الله تخاطبه ؟ إن كنت كذلك فلا يكون إيمانك قوياً بالله وبعشرته وبلذة الحديث معه ...","وهكذا إن وضعنا باقى أمور الصلاة ، وباقى بنود العمل الروحى ، لتكون مجالاً لاختبار إيمانك .",{h:"٧ ـ إختبر إيمانك بمدى اهتمامك بأبديتك :"},"هل أنت مركز كل فكرك بقلبك فى هذا العالم الحاضر ، ومدى نجاحك فيه ، ومدى تمتعك به ؟ أم أنت تهمك أبديتك ، ويهمك مصيرك فى العالم الآخر ، وتعد العدة لتلك الحياة كما يقول الرب « لتكن أحقاؤكم ممنطقة ، ومصابيحكم موقدة . وأنتم تشبهون أناساً ينتظرون سيدهم متى يرجع من العرس ، حتى إذا جاء وقرع يفتحون له للوقت . طوبى لأولئك العبيد الذين إذا جاء سيدهم يجدهم ساهرين » (لو ١٢ : ٣٥ ـ ٣٧) .",{h:"إن السهر الروحى إختبار عميق للإيمان ."},"أما الغافل عن أبديته ، فأين هو إيمانه ؟ ! أين إيمانه بالحياة الأخرى ، والإستعداد لها بالتوبة والعمل الصالح ، وبعشرة الله ومحبته ، وبالزيت جاهزاً فى مصباحه ... ؟ !",{h:"٨ ـ إختبر إيمانك بصحة العقيدة :"},"هل هو إيمان سليم بعيد عن البدع وأخطاء العقيدة ، وعن المفاهيم الخاصة ؟ وهل هو « الإيمان المسلّم مرة للقديسين » (يه ٣) . الذى أودعه الرسل أناساً أمناء كانوا أكفاء أن يعلموا آخرين أيضاً (٢تى ٢ : ٢) . وهل هو موافق لكل تعليم الكتاب ، أم تتبع فيه أناساً يعلمون فكرهم الخاص ؟ بهذا إختبر إيمانك .","أقول هذا لأن العقيدة لها تأثير عملى فى حياة الإنسان الروحية ."],109:[{h:"٩ ـ إختبر إيمانك بصفات الإيمان السليم :"},"هل إيمانك إيمان عملى ؟ هل هو ثابت لا تزعزعه الظروف ؟ هل هو لا يضعف ولا يشك ؟ هل هو مملوء بالسلام لا يعرف خوفاً ؟ وهل تعرف حياة التسليم وطاعة الإيمان ، وهل إيمانك إيمان حى مثمر ؟ وهل هو ينمو ويزداد ؟ وهل ...","لست أريد أن أذكر باقى صفات الإيمان لتمتحن بها نفسك .",{h:"إنما إن أردت مزيداً من الموازين ، يمكن أن تعيد قراءة هذا الكتاب من أوله ."}]}},hope_life1:{id:"hope_life1",title:"حياة الرجاء (الجزء الأول)",author:"قداسة البابا شنوده الثالث",url:"https://drive.google.com/file/d/1uWJQKpRcLbUpPBCYDaONF9sXA5byCT7k/view",file:"حياة الرجاء (الجزء الأول)",pageOffset:-1,review:{status:"needs-review",note:"نُقل الجزء الأول (من «قصة هذا الكتاب» إلى ص٩٩ المطبوعة، أي ص٦ إلى ص١٠٠ بترقيم الملف) بقراءة صفحات الكتاب الممسوحة بالنظر؛ حُذف الغلاف والفهرس. ينتهي الملف في منتصف الفصل السابع. الرقم المطبوع = ترقيم الملف − ١. ما زال يحتاج مطابقة نهائية مع الأصل، وعناوين الفصول المزخرفة قُرئت بأفضل ما تيسر."},chapters:[{title:"قصة هذا الكتاب والمقدمة",from:6,to:8},{title:"الفصل الأول: الرجاء",from:9,to:19},{title:"الفصل الثاني: كل الأشياء تعمل معًا للخير",from:20,to:31},{title:"الفصل الثالث: تعالوا إليّ يا جميع المتعبين",from:32,to:41},{title:"الفصل الرابع: سعي الله لخلاصنا",from:42,to:59},{title:"الفصل الخامس: اهتمام الله بالأشياء الصغيرة",from:60,to:81},{title:"الفصل السادس: الله حنون عطوف",from:82,to:89},{title:"الفصل السابع: أحفظك حيثما تذهب (جزء)",from:90,to:100}],transcribed:[6,100],pages:{6:[{h:"قصة هذا الكتاب"},"كثيرون جداً يحتاجون إلى كلمة تعيد إليهم الرجاء ... يحتاجون إلى نافذة من نور ، تبدد الظلمة التى تكتنف نفوسهم ...","نفوسهم تصغر أمام المشاكل التى تبدو معقدة ، وبلا حل ... وتزيد حروب الشيطان من المخاوف فى عدم حلها ...","كذلك يظنون أنه لا فكاك من الخطايا التى استمرت معهم زماناً ، حتى صارت شبه مسيطرة عليهم ، يكررونها فى كل اعتراف بلا توبة ، مهما حاولوا التوبة ...","هؤلاء يقولون مع داود النبى ما ردده فى المزمور الثالث :",{h:"« كثيرون يقولون لنفسى : ليس له خلاص بإلهه » (مز ٣) ."},"وللأسف لا يكملون باقى المزمور وما فيه من رجاء ...","* * *","ولأهمية هذا الموضوع ، وحاجة الكثيرين إليه ، تكلمت فى عظات عديدة جداً عن الرجاء ودخل الرجاء ضمن عظات أخرى من الصعب أن أحصيها ، ولذلك لما أردت أن أجمع كل ما قلته فى موضوع الرجاء ، بدا الأمر صعباً ... مما تسبب فى تعطيل صدور هذا الكتاب الذى دخلت أجزاء من مقالاته فى المطبعة ، وجمعت ... وانتظرت اخوانها ، وطال الانتظار ... وتحيرت ماذا أقدمه للطبع ، وماذا أتركه أو أرجئه ؟ ؟","وأخيراً اكتفيت بهذه المقالات الخمس عشرة التى ضمها هذا الكتاب ، حتى يمكن أن يصدر الآن . على أن أستبقى المقالات الأخرى الخاصة بالرجاء ، لكى تنشر فى جزء ثان ، أو تضاف إلى هذا الكتاب عند إعادة طبعه بمشيئة الله .","* * *"],7:["والرجاء هو أحد الفضائل الثلاث الكبرى التى ذكرها الرسول فى (١كو ١٣ : ١٣) .","وأعنى بها : الإيمان ، والرجاء ، والمحبة .","ولقد أصدرنا لك كتاباً عن (حياة الإيمان) فى بداية الثمانينات . وها هوذا كتاب عن الرجاء . وبقى كتاب ثالث نصدره عن المحبة ... محاضراته كلها جاهزة ، لا تنقصها سوى مراجعة بسيطة وتقدم إلى المطبعة ... بصلواتك .","و بهذا تكمل المجموعة إن شاء الله .","البابا شنوده الثالث"],8:[{h:"الفصل الأول"},{h:"الرجاء"}],9:["الرجاء هو احدى الفضائل الثلاث الكبرى التى ذكرها معلمنا بولس الرسول فى رسالته الأولى إلى كورنثوس حيث قال .. « الإيمان والرجاء والمحبة هذه الثلاثة » (١كو ١٣ : ١٣) ، وهذه الثلاثة ترتبط بعضها بالبعض الآخر فالإيمان يلد الرجاء ، لأن الذى يؤمن بالله ، إنما يكون له رجاء فيه ، والذى يكون له رجاء فى الله ، يحبه وهكذا يصل إلى قمة العلاقة بالله فى المحبة .","* * *","الرجاء قديم قدم البشرية ، بل أقدم منها ، فأول رجاء عرفه البشر ، هو رجاء فى الخلاص ، حينما وعد الرب قائلاً لآدم وحواء « إن نسل المرأة سوف يسحق رأس الحية » (تك ٣ : ١٥) .","وظل هذا الرجاء فى قلوبهم آلاف السنين حتى تحقق أخيراً فى تجسد الرب ، وفى صلبه عن البشرية .","وحتى الذين لم ينالوا هذا الرجاء ، عاشوا فيه ، وكما قال معلمنا بولس « لم ينالوا المواعيد ، لكنهم نظروها من بعيد وصدقوها » (عب ١١ : ١٣) .","وهكذا رقدوا على رجاء ، إلى أن افتقدهم الرب وأرجعهم إلى الفردوس مرة أخرى .","* * *","على أن الرجاء كان موجوداً قبل آدم وحواء ، فى قصة الخليقة الأولى ، كان هناك رجاء لتلك الأرض الخربة الخاوية المغمورة بالمياه ، وعلى وجه الغمر ظلمة (تك ١ : ١) .","وحقق الله لها هذا الرجاء حينما قال « ليكن نور فكان نور » . ورتب الله هذه الأرض الخربة ، فإذا بها فى أجمل صورة ممكنة ، فيها الأشجار والأثمار والأزهار"],10:["والأطيار . ورأى الله أن كل شىء فيها حسن جداً . ولذلك مهما كانت الأرض خربة فى يوم من الأيام ومهما كانت خاوية ، ومهما كانت مغمورة بالمياه ، ومهما كانت مظلمة ، فهناك رجاء أن الله يخرج منها هذه الصورة الجميلة من الطبيعة المملوءة بالجمال التى نراها الآن .","* * *",{h:"الرجاء إذن هو شىء هام فى الحياة ولو فقد الإنسان الرجاء فقد كل شىء ، لأن"},"الإنسان الذى يفقد الرجاء ، يقع فى اليأس ، ويقع فى الكآبة ، وتنهار معنوياته ، ويقع فى القلق ، والاضطراب ومرارة الانتظار بلا هدف وقد يقع بذلك ألعوبة فى يد الشيطان ، لذلك نقول إن الشيطان هو الذى يقطع الرجاء .","أما أولاد الله فباستمرار عندهم رجاء ، يعيشون فى الرجاء فى كل وقت ... فى الضيقة يعيشون فى رجاء ، ومهما تعقدت الأمور ، ومهما بدا أن الله قد تأخر عليهم ، ومهما بدا كل شىء مظلماً ، هناك رجاء .","* * *",{h:"وأولاد الله عندهم رجاء أيضاً فى الحياة الأخرى ، فى العالم الآخر فى تحقق وعد الرب من حيث ما لم تره عين وما لم تسمع به أذن ولم يخطر على بال إنسان ."},"هذه هى الحياة الأخرى التى نجاهد على الأرض لكى ننالها . وعلى رأى معلمنا القديس بولس الرسول « إن كان لنا رجاء فى هذا العالم فقط ، فنحن أشقى جميع الناس » (١كو ١٥) .","وهناك رجاء أيضاً حتى للخطاة فى التوبة ، بل أشر الخطاة على الأرض لهم رجاء .","* * *","وهناك رجاء للص وهو على الصليب فى أخطر ساعات حياته . وهناك رجاء لزكا رئيس العشارين الذى كان يمثل قمة الظلم فى عهده ، وهناك رجاء للمجدلية التى كان فيها سبعة شياطين فإذا بها إحدى المرعات القديسات ، وقد استحقت أن تكون مبشرة للأحد عشر بالقيامة . وهناك رجاء حتى للشجرة التى لم تثمر ثلاث سنوات ، فقال الرب « انقب حولها وأضع زبلاً ، لعلها تثمر فيما بعد » (لو ١٣ : ٨) .","* * *"],11:[{h:"المسيحية تعطى رجاء حتى للقصبة المرضوضة وللفتيلة المدخنة ."},"القصبة المرضوضة قادر الله أن يعصبها ، والفتيلة المدخنة قادر الله أن يرسل لها ريحاً فتشتعل ، وهذا من جهة الرجاء قال الرب « شجعوا صغار النفوس » . وأعطى فى ذلك رجاء حتى للركب الخلعة ، وحتى للأيدى المسترخية .","* * *","فى المسيحية يوجد رجاء للأفراد ، ويوجد رجاء للهيئات ، ويوجد رجاء للكنائس ويوجد رجاء للبلاد ، ويوجد رجاء للعالم كله .","* * *","لنا رجاء فى افتقاد الرب للبشرية فى كل وقت . هذا الرجاء لا يضعف أبداً عند المؤمنين مهما بدا الأمر صعباً وكيف ذلك ؟","* * *",{h:"لقد كان هناك رجاء ليونان النبى وهو فى بطن الحوت . هل إنسان يكون فى جوف الحوت ويكون له رجاء ؟"},"ولكن يونان ركع على ركبتيه وصل وهو فى جوف الحوت . وقال للرب « أعود فأرى هيكل قدسك » . كان له رجاء ، وقد تحقق .","وكان هناك رجاء حتى للثلاثة فتية وهم فى أتون النار ، ولدانيال وهو فى جب الأسود .","* * *",{h:"وكان هناك رجاء حتى للعاقر التى لم تلد ، التى قال لها الرب فى سفر اشعياء"},"« ترنمى أيتها العاقر ، ووسعى خيامك ، لأن نسلك سيرثون أمماً ويعمرون مدناً خربة » (اش ٥٤) .","كان هناك رجاء أعطاه لنا الرب فى رمز الذين قاموا من بين الأموات .","حتى لعازر الذى قالت عنه مرثا أخته مرة أنه قد أنتن (يو ١١) قدم لنا الرب رجاء فى أن يقوم من الأموات .","* * *","وهناك رجاء قدمه الرب فى شفاء الأمراض المستعصية ... فى إعطاء البصر للعميان ، والصحة للجذع ، والعرج والمشلولين ، وكل ذى عاهة ، وصاحب اليد اليابسة ، حتى"],12:["الإنسان الذى قضى ثمانى وثلاثين سنة إلى جوار البركة لا يجد من يلقيه فيها ، كان له رجاء أن يأتى له المسيح ويقول له « قم احمل سريرك وامش » (يو ٥) .","مهما كان الأمر مستعصياً ، ومهما كان الأمر صعباً ، ومهما بدا للناس معقداً ، هناك رجاء يقدمه الله .","ولعل الرب أعطانا مثالاً جميلاً فى هذا حينما قال « غير المستطاع عند الله » بل صدقونى هناك آية أعمق من هذه جداً ، وهى قول الكتاب « كل شىء مستطاع للمؤمن » .","* * *",{h:"عبارة « كل شىء مستطاع » (مر ٩ : ٢٣) تعطينا رجاء لا حدود له ."},"وهكذا يقول بولس الرسول فى الرجاء « استطيع كل شىء فى المسيح الذى يقوينى » (فى ٤ : ١٣) . عبارة كل شىء هى مدى أوسع جداً يعطينا فكرة أنه لا حدود للرجاء ، مادام لا حدود لقدرة الله ولمحبته .","إذاً لا حدود للرجاء فى المسيحية .","والإنسان المسيحى يجد اختباراً لفضيلة الرجاء فيه ، حينما يقع فى ضيقة أو فى تجارب متنوعة ، أو فى آلام صعبة ، أو فى مشاكل تبدو لا حلول لها ، يعرف بالرجاء أن الرب عنده حلول كثيرة ، وأن الرب لابد أن يأتى مهما بدا أمام الناس أنه قد تأخر .","* * *","صدقونى أننى فى بعض الأحيان كنت أعاتب أبى ومعلمى القديس داود النبى ، حينما كان يقول للرب « اسرع ولا تبطىء » .","لأن الرب يا اخوتى ليس عنده اسراع ولا ابطاء . الله يعمل ، ويعمل فى كل حين ، وهو لا يتأخر مهما ظن التلاميذ أنه قد مر الهزيع الرابع من الليل ولم يأت بعد . الرب لابد سيأتى ، إذا كان عندنا إيمان ، نؤمن أن الله لابد سيعمل وسيعمل بقوة ، وسيعمل فى الوقت المناسب .","أما عبارة التأخير ، فهى تحمل مفهوماً نسبياً عند البشر ، يظنون أنه قد تأخر ، ولكن"],13:["مواعيد الله هى هى ، تحددها حكمته ، وتحددها رؤيته الصادقة للأمور على حقيقتها .","فالله يعمل باستمرار ، وإن ظننا فى وقت من الأوقات أنه قد تأخر ، يقول لنا المرنم فى المزمور « انتظر الرب ، تقو ليتشدد قلبك ، وانتظر الرب » (مز ٢٧ : ١٤) .","* * *","وهنا نعرف معنى الرجاء على حقيقته ...",{h:"إن الإنسان يرجو الرب وينتظر الرب ، ليس فى قلق ، ولا فى ضجر ، ولا فى تذمر ، ولا فى شك ."},"ولكن ينتظر الرب ، وقد تشدد قلبه ، هو قوى القلب فى الداخل ، قوى بالإيمان أن الرب يعمل ، لا أقول أن الرب سيعمل ، فهذا مستوى ضعيف . وإنما أقول أن الإنسان يكون عنده رجاء أن الرب يعمل فعلاً .","أنت لا تؤمن أن الله سيعمل فى المستقبل ، وإنما ينبغى أن تؤمن أن الله يعمل حالياً . ولذلك يكون عندك رجاء ، فيما لا تراه من عمل الله ، ولكن توقن تماماً وتثق أن الله يعمل . إن الطائرة قد تبدو لمن يستخدمها لأول مرة أنها واقفة فى الجو ، بينما تكون فى سرعة أكثر من ثمانمائة كيلومتراً فى الساعة ، ولكنها تبدو واقفة ! وبعض المراوح الشديدة الحركة تبدو متوقفة ، وهى تكون فى أقوى درجة من السرعة ، وكذلك الكثير من الأجهزة .","* * *",{h:"الله يعمل ، أنت لا تراه يعمل لكن تؤمن بذلك ، ويكون لك رجاء بنتيجة عمله التى سترأها بعد حين ."},"فى الضيقات ... الإنسان الذى يرجو الله ينفعه قول المزمور « إن يحاربنى جيش فلن يخاف قلبى ، وإن قام على قتال ففى هذا أنا مطمئن » .","ولماذا هو مطمئن ؟ لأنه يرجو عمل الله فيه ، ويرى كما كان أليشع يرى ، أن هناك جيوش الرب تحارب حول المدينة « وأن الذين معنا أكثر من الذين علينا » (٢مل ٦ : ١٦) ."],14:["ويقول مع المرنم « نجت أنفسنا مثل العصفور من فخ الصيادين ، الفخ انكسر ونحن نجونا » (مز ١٢٤) .","* * *",{h:"الإنسان الذى عنده رجاء ، لا ينظر إلى الضيقات ، إنما ينظر إلى الله الذى ينتصر على الضيقات . الذى قال « أنا قد غلبت العالم » ويظل فيه هذا الرجاء إلى آخر نسمة ، فى كل حين ، فى كل حال ، فى كل موقف ، الرجاء لا يفارقه ."},"وهذا الرجاء يعطى الإنسان سلاماً فى القلب ، طمأنينة فى الداخل ، فرحاً قلبياً على أساس ، ولهذا يقول الرسول فى الاصحاح الثانى عشر من رسالته إلى رومية « فرحين فى الرجاء » (رو ١٢) .","* * *",{h:"الرجاء بأن الله لا يعسر أمر عليه وأنه قادر على كل شىء ، الرجاء فى محبة الله وفى مواعيد الله ، الرجاء فى الله الذى قال « لا أهملك ولا أتركك » الله الذى قال « ها أنا معكم كل الأيام وإلى انقضاء الدهر » الذى قال « نقشتكم على كفى » الذى قال « إن أبواب الجحيم لن تقوى عليها .. الرجاء فى الله الذى عمل فى القديم ، والذى يعمل كل حين ، الذى نقول له مثلما قالوا مثلما قالوا مثلها قم أيها الرب الإله وليتبدد جميع أعدائك ، وليهرب من قدام وجهك كل مبغضى اسمك القدوس » ."},"الله الذى غلب العالم ، نرجوه أن يغلب العالم أيضاً مرة أخرى ، يغلب الالحاد الذى فى العالم يغلب الاباحية والمادية ، ويغلب الحقد والكراهية التى فى العالم ، ويغلب الانقسام والتفكك الذى فى العالم ويغلب العنف واستخدامه الذى فى العالم .","* * *","هذا هو الإله الذى نرجوه ، الذى يعيد الأرض إلى صورتها الأولى . وأيضاً الله الذى يقف إلى جوار أولاده باستمرار ، الذى رآه يوحنا فى رؤياه وهو « فى وسط المناثر السبع ، وفى يمينه ملائكة الكنائس السبع » (رؤ ١ : ٢٠) .","فالله مايزال وسط أولاده ، وفى يمينه رعاة الكنائس وقادتها ، وهو يقول لنا أغنيته الجميلة « لا يخطف أحد من يد أبى شيئاً » (يو ١ : ٢٩) .","* * *"],15:["لنا رجاء فى الله الذى قال عنه يوحنا الحبيب فى رؤياه :","« أبصرت وإذا باب مفتوح فى السماء » (رؤ ٤ : ١) .","فالإنسان الذى يعيش فى الرجاء ، باستمرار ينظر باباً مفتوحاً فى السماء ويرى الله واقفاً فى هذا الباب يقول إنه يفتح ولا أحد يغلق » (رؤ ٣ : ٧) .","* * *",{h:"الله الذى يسعى لخلاصنا ، دون أن نسعى نحن ، والذى يحبنا أكثر مما نحب أنفسنا ، والذى يعرف الخير لنا ، أكثر مما نعرف الخير لأنفسنا الله ضابط الكل الذى يقود الكون كله والذى حياة العالم كله فى يديه . هو يدبر الأمور حسب حكمته التى لا تحد ، نحن نرجو هذا الإله ، ونحن نغنى مع الرسول قائلين :"},"* * *",{h:"« كل الأشياء تعمل معاً للخير للذين يحبون الله » (رو ٨ : ٢٨) . ونقصد الخير بالمقاييس الإلهية وليس الخير بمفاهيمنا البشرية . الله هذا صانع الخيرات ، هو الذى نرجوه . وهو الذى نعلق كل رجائنا عليه . وهو الذى نقول له فى بعض صلوات القداس الإلهى « يا رجاء من ليس له رجاء . معين من ليس له معين » . ونقول فى المزمور « الاتكال على الرب خير من الاتكال على البشر ، الرجاء بالرب خير من الرجاء بالرؤساء » (مز ١١٨) ."},"* * *",{h:"الرجاء فى مواعيد الله الصادقة والرجاء فى الحياة الأبدية الجميلة ، فى القيامة السعيدة ، الرجاء الذى تعلقه لا فى أمور العالم ، وإنما فى ذلك الوطن السماوى ، « المدينة التى لها الأساسات التى صانعها وبارئها الرب » (عب ١١) ."},"الإيمان فى حياة أخرى جديدة لا تعرف خطية ، ولا تعرف إثماً ، الإيمان فى التجديد العجيب الذى ننأله فى السماء ، حيث ترجع إلينا الصورة الإلهية الأولى ، وفى وضع لا يخطىء فيما بعد ، الرجاء فى الحرية التى ننالها من الرب ، بحيث تكون حرية تفعل الخير فقط ، ولا تعود تعرف الخطية بعد ، الإيمان بملكوت الله الذى نعيش فيه فى ذلك الأبد ، ونعد أنفسنا له من الآن ."],16:["هذا هو الرجاء الحقيقى الذى نرجو فيه ما لا يرى ، لأن الأشياء التى ترى تدخل فى العيان ، وليس الرجاء . إنما نحن نرجو ما ننتظره بالصبر ، وليس ما نراه كما يقول الرسول « هذا الرجاء المفروض أن ندعو الجميع إليه » .","* * *",{h:"المفروض أن تقول لكل أحد : إن كل باب مغلق له ألف مفتاح ، والله يستطيع أن يفتح جميع أبواب المغلقة ."},"ونقول له إن كل ظلمة لابد بعدها نور ، وكل مشكلة لها حل أو عشرات الحلول وكل ضيقة لها إله هو إلهنا الصالح الذى يخرج من الجافى حلاوة ، ومن الآكل أكلاً . والذى يحول كل الأمور إلى الخير ، كل الأمور التى تمر بنا فى حياتنا إن كانت خيراً ستصل إلينا خير وإن كان شراً فالله صانع الخيرات يحول الشر إلى خير .","* * *",{h:"لذلك نحن نعيش فى الرجاء فرحين باستمرار . السلام يملأ قلوبنا ، لأننا لا نعتمد على ذواتنا ولا على وسائط عالمية ، إنما نعتمد على الله الذى يعمل كل خير ."},"فى هذا الرجاء أحب أن نعيش جميعاً ، ككنيسة ترجو ملكوت الله وتنتظره ، وترجو عمل الله فيها فى كل حين ، ونؤمن بعمله ، وكعالم واسع الأرجاء فى كل قاراته ، يرجو من الله أن يسود السلام فى كل مكان ويسود الخير فى كل مكان ، ويرجع الحب إلى قلوب الناس جميعاً ، فيرتبطون به ، ويعيشون به وكما قال المسيح « بهذا يعرف الناس أنكم تلاميذى إن كان لكم حب بعضكم نحو بعض » .","هذا الرجاء إن لم يكن فينا فلنطلبه كعطية مجانية من الله ، الذى يملأ القلوب بسلامه وبرجائه . له المجد الدائم من الآن وإلى الأبد آمين ...","* * *",{h:"حياة الرجاء يلزمها الثقة"},"حياة الرجاء يلزمها الثقة فى الله ، والثقة فى مواعيده ، وفى عمله وفى محبته لك وللكل ، وفى حكمة تدبيره ."],17:["لكى يمتلىء قلبك بالرجاء ، ينبغى أن تثق بأن الله يحبك أكثر مما تحب نفسك ، وأنه يعرف ما هو الخير لك أكثر مما تعرف أنت بما لا يقاس . وأن كل تدابير الله من جهتك هى فى عمق الحكمة والخير ، مهما بدت لك غير ذلك من خلال الشك ...","* * *",{h:"ولا بد أن تعلم أنك فى يد الله وحده ، ولست فى أيدى الناس ، ولا فى أيدى التجارب والأحداث ، ولا فى أيدى الشياطين ..."},"أنت فى يد الله وحده . والله قد نقشك على كفه (إش ٤٩ : ١٦) . وقد يظلل عليك بجناحيه (مز ٩٠) ويحرسك الليل والنهار ، ويحفظ دخولك وخروجك (مز ١٢٠) . ومن محبته لك ، دعاك ابناً له (١يو ٣ : ١) . وهو الراعى الذى يرعاك فلا يعوزك شىء (مز ٢٣ : ١) . نحن كلنا شعبه وغنم رعيته . ولا يمكن لله كراع صالح أن يغفل عن غنمه . ولا يمكن له كأب أن يغفل عن أولاده .","* * *","أما إن كانت لديك مشكلة ، فيريحك جداً أن تنتظر الرب . ولا بد أنه سينقذك منها . فهذه نصيحة مباركة يقدمها لنا أحد مزامير صلاة باكر ، يقول فيها المرتل :",{h:"« انتظر الرب . تقو وليتشدد قلبك ، وانتظر الرب » (مز ٢٦ [٢٧]) ."},"والنصيحة التى يقدمها لنا هذا المزمور ، ليس مجرد أن ننتظر الرب ، وإنما أن ننتظره فى قوة ، ونحن متشددون فى الداخل ...","لا ننتظر الرب فى ضيقة ، أو فى ضجر وتلمر واحتجاج : لماذا لم يعمل الرب حتى الآن ؟ أين عمله ؟ أين محبته ؟ !. ولا ننتظر ونحن نشك فى عمل الله ، أو نشك فى قيمة الصلاة وفاعليتها ! ! ولا ننتظر الرب فى ضعف داخلى ، وفى انهيار ، وقد فقدنا معنوياتنا ! ! كلا ، فكل هذه المشاعر ضد فضيلة الرجاء ... فالإنسان المضطرب أو اليائس أو الخائف أو المنهار ، يدل على أنه فاقد الرجاء ... لأن الذى ينتظر الرب فى رجاء ، إنما يمنحه الرجاء قوة . وكما قال إشعياء النبى :",{h:"« وأما منتظرو الرب ، فيجددون قوة . يرفعون أجنحة كالنسور . يركضون ولا يتعبون . يمشون ولا يعيون » (إش ٤٠ : ٣١) ."}],18:["فما معنى عبارة « يجددون قوة » ؟ معناها أنه كلما حاربهم الشيطان بالقلق أو بالضعف والاضطراب ، تتجدد القوة فيهم من تذكرهم لمواعيد الله الصادقة ، وصفاته الإلهية المحبوبة باعتباره الأب والراعى والحافظ والساتر والمعين ... الله الحنون ، المحب ، صانع الخيرات ، الذى لا يغفل ولا ينام ... فكلما يتذكرون صفة من هذه الصفات تتجدد القوة فيهم ، ويرفعون أجنحة كالنسور .",{h:"إن منتظر الرب يثق ثقة لا تحد بمحبة الله الفائقة للبشر ، وبحكمة الله التى هى فوق ادراكنا البشرى ..."},"* * *","يثق أن الله يعطينا باستمرار دون أن نطلب ، وقبل أن نطلب . فكم بالحرى إن طلبنا ... وهو يثق أيضاً أن الله يعطينا ما ينفعنا ، وليس حرفية ما نطلبه . لأنه ربما تكون بعض طلباتنا غير نافعة لنا ... وهنا تظهر حكمة الله فى محبته ...","لذلك فى حياة الرجاء ، لا بد أن تثق بحكمة الله فى تدبيره لحياتك",{h:"لا تطلب وتصرّ . إنما اطلب وقل : لتكن مشيئتك ..."},"وحينما تقول : « لتكن مشيئتك » ليكن ذلك بفرح ، بغير ألم ولا حزن .","* * *","هناك أمور كثيرة لا تدريها . وهى معروفة ومكشوفة أمام الله .","ربما الذى تطلبه ، لا يكون مناسباً لك ولا نافعاً لك . وربما الوقت الذى تحدده ، يعرف الله تماماً أنه غير صالح ، ويرى أن تأجيل الاستجابة أفضل ... لذلك تواضع ، واترك لحكمة الله أن تتصرف . وانتظر الرب فى ثقة ...",{h:"أليس من المخجل أننا نثق بذكائنا وفطنتنا أكثر مما نثق بالله !"},"إننا نضع حلولاً للأمور ، واثقين أنها أفضل الحلول ، أو أنها الوحيدة النافعة . وربما يكون فى ذهن الله حلّ آخر لم يخطر لنا على بال ، هو أفضل بما لا يقاس من كل تفكيرنا . ليتنا إذن نثق بالله ... وننتظر حله فى رجاء .","* * *"],19:[{h:"أمور تساعد على الثقة"},"وكما نثق بمحبة الله وحكمته ، نثق أيضاً بمواعيده المليئة بالرجاء ...","نثق بوعده الصادق « ها أنا معكم كل الأيام وإلى انقضاء الدهر » (متى ٢٨ : ٢٠) . نثق بقوله « لا تخف لانى معك » (تك ٢٦ : ٢٤) « لا أهملك ولا أتركك . تشدد وتشجع » « لا يقف إنسان فى وجهك كل أيام حياتك » (يش ١ : ٥ ، ٦) « تشدد وتشجع . لا ترهب ولا ترتعب ، لأن الرب إلهك معك حيثما تذهب » (يش ١ : ٩) « لا تخف أيها القطيع الصغير » (لو ١٢ : ٣٢) « ... أنا معك ، ولا يقع بك أحد ليؤذيك » (أع ١٨ : ١٠) « يحاربونك ولا يقدرون عليك ، لأنى أنا معك ـ يقول الرب ـ لأنقذك » (أر ١ : ١٩) .","* * *",{h:"وما أكثر عبارات الرجاء التى تحفل بها المزامير ..."},"ليتك تجمع هذه الآيات وتقرأها أو تتذكرها كلما كنت فى حاجة إلى الرجاء فى حياتك . يكفى أن تسترجع مثلاً مزمور ٩٠ (٩١) أو ١٢٠ (١٢١) حيث يقول لك الوحى الإلهى : « يسقط عن يسارك ألوف ، وعن يمينك ربوات . وأما أنت فلا يقتربون إليك . بل بعينيك تتأمل ، وبمجازاة الخطاة تبصر » « لأنه يوصى ملائكته بك ليحفظوك فى سائر طرقك ... » « تطأ الأفعى وملك الحيات ، وتسحق الأسد والتنين ، لأنه علىّ اتكل انجيه . أستره لأنه عرف اسمى » (مز ٩٠) « لا يسلم رجلك للزلل ... الرب يحفظك » « الرب يحفظك من كل سوء . الرب يحفظ نفسك . الرب يحفظ دخولك وخروجك » (مز ١٢٠) .","كلها آيات تبعث الرجاء فى النفس ، وتقوى القلب فى الداخل","* * *",{h:"ويزيد الرجاء فيك أيضاً ، تذكرك معاملات الله لقديسيه ..."},"إن تذكرت كل هذا ، يمتلىء قلبك بالرجاء ، وتنتظر الرب فى ثقة ."],20:[{h:"الفصل الثانى"},{h:"كل الأشياء تعمل معاً للخير (رو ٨ : ٢٨)"},"من محاضرة القيت فى الكاتدرائية يوم الجمعة ٧٦/٢/٢٠ ."],21:["كثير من الناس تمر عليهم التجارب والضيقات ، فتعصرهم عصراً ، ويقعون فى الكآبة الشديدة ، وربما فى اليأس . وهؤلاء يريحهم قول الكتاب :",{h:"« كل الأشياء تعمل معاً للخير ، للذين يحبون الرب » (رو ٨ : ٢٨) ."},"والكتاب المقدس حافل بقصص كثيرة معزية فى هذا المجال :",{h:"قصة يوسف الصديق"},"إنسان يقسو عليه اخوته ، ويلقونه فى بئر ، ثم يبيعونه كعبد لتجار من الاسماعيليين . وبعد أن يخلص لسيده كل الاخلاص ، وينجح فى عمله جداً ، تلفق ضده تهمة رديئة من امرأة سيده ، ويلقى فى السجن . وتطول به الأيام فى سجنه ...","ولكن كل هذه الأمور ، كانت تعمل للخير .","فلولا التهمة التى أوصلته إلى السجن ، ما كان خبره يصل إلى فرعون ، فيجعله وزيره الأول ، والثانى فى المملكة . وطبعاً لولا قسوة اخوته ، ما كان قد بيع إلى بيت فوطيفار . ولولا أن امرأة فوطيفار كانت خاطئة ، ما كانت تشتهيه ، ثم تلفق له التهمة التى أوصلته إلى السجن . ولولا سجنه ما كان قد تعرف على رئيس سقاة فرعون الذى أخبر فرعون بقدرته على تفسير الأحلام ، فاستدعاه فرعون . وخرج من السجن إلى المملكة (تك ٣٩ ـ ٤١) .","* * *","وبدون كل هذا ، ما كان اخوته قد تابوا ، وبكوا ، واعترفوا بخطيئتهم ، وعادت المحبة إلى الأسرة ، ونجوا من المجاعة ، واجتمعوا كلهم فى مصر ...",{h:"المشكلة أن الناس تحصرهم المشكلة ، ولا يكون لهم الرجاء فى أنها ستؤول إلى الخير ."}],22:["يقفون عند البداية التى تبدو سيئة أو مؤلمة ، ولا يتابعون العمل الإلهى ، الذى يحوّل الشر إلى خير ، والذى يخرج من الجافى حلاوة (قض ١٤ : ١٤) .","لاشك أن قصة يوسف الصديق ، هى درس فى الرجاء ، وفى أن كل الأشياء تعمل معاً للخير .","نتدرج إلى نقطة أخرى تبدو غريبة وعجيبة ، وهى :",{h:"خطيـة آدم"},"إنها خطية ، جرت على العالم ما لا يحصى من الكوارث . وبها دخلت الخطية إلى العالم ، وبالخطية الموت (رو ٥ : ١٢) .","ومع ذلك ، فإن الله الذى يخرج من الجافى حلاوة ، استطاع أن يجعل كل الأمور تعمل معاً للخير .","وكنتيجة لذلك عرفنا عملياً محبة الله لنا (يو ٣ : ١٦) . وبركات الكفارة والفداء .","ولو كان آدم لم يخطىء ، لبقى فى الفردوس . فى جنة يأكل فيها ويشرب ، ويعيش مع الحيوانات والطيور والأسماك ... أما الآن ، فقد صار لنا الملكوت بكل ما يحمل من بركات غير مرئية ، فيها ما لم تره عين ، وما لم تسمع به أذن ، وما لا يخطر على قلب بشر » (١كو ٢ : ٩) .. ولنا فيه عشرة الملائكة القديسين ...","وهذا يذكرنا بنقطة أخرى عجيبة وهى :",{h:"الموت"},"كل الناس يكرهون الموت ، ويرونه سبباً للحزن ! ويلبسون لأجله السواد ، ويقابلونه بالدموع والبكاء ... ولكنه أيضاً من الأمور التى تعمل للخير ..."],23:[{h:"فالموت هو الطريق إلى حياة أفضل ، وإلى مستوى أعلى ستؤول إليه البشرية ..."},"حيث فى القيامة ، ستقوم بأجساد نورانية روحانية ، نقام فى مجد بأجساد سماوية يمكنها أن ترث الملكوت (١كو ١٥) ... ولولا الموت لبقينا فى هذا الجسد المادى ... أليس الموت أيضاً يعمل معاً للخير ؟",{h:"فلنتأمل قصة القديس الأنبا أنطونيوس ، وموت أبيه ."},"كان موت أبيه درساً عميقاً له فى فناء الحياة الدنيوية وبطلانها . ولقد نظر الشاب أنطونيوس إلى أبيه الميت ، وقال له « أين هى عظمتك وسلطانك ؟ ! لقد خرجت من الدنيا على الرغم منك . ولكنى سأخرج منها بارادتى ، قبل أن يخرجونى مثلك كارهاً » ... وكانت بداية الحياة الرهبانية ...",{h:"الأمراض"},"المرض آفة يحاربها الناس . ويهربون منها إلى الطب والدواء .. ومع ذلك فإن الأمراض « تعمل معاً للخير ، للذين يحبون الرب » (رو ٨ : ٢٨) ...",{h:"أمراض كثيرة قادت إلى التوبة ، وفعلت ما لم تفعله أعمق العظات ..."},"وبخاصة الأمراض الخطيرة والمؤلمة .. كم قد أدخلت كثيرين فى عهود مع الله ، وفى نذور قدموها إلى الله ، وفى حياة جديدة مع الله ، أو أدخلتهم فى توبة واستعداد للموت ... وهكذا كانت تعمل معاً للخير .","* * *",{h:"وأمراض قادت الناس إلى الصلاة وإلى الصوم ."},"وإلى زيارة الأماكن المقدسة ، والتشفع بالملائكة والقديسين ، وإلى إقامة القداسات ، والقيام بأعمال الرحمة نحو الفقراء والمساكين .","وهكذا كما استفاد المريض نفسه اقتراباً إلى الله ، استفاد أيضاً أقار به ومحبوه فوائد روحية عديدة ..."],24:["بل الأمراض كانت نافعة للقديسين ، لإشعارهم بضعفهم ومنع المجد الباطل عنهم .","وفى ذلك يقول القديس بولس الرسول « ولكى لا ارتفع بفرط الإعلانات ، أعطيت شوكة فى الجسد ، ملاك الشيطان ليلطمنى لئلا أرتفع » (٢كو ١٢ : ٧) .","وقد صلى بولس ثلاث مرات ، ليشفيه الله من ذلك المرض . ولكن الله قال له « تكفيك نعمتى » . واستبقى مع بولس هذه الشوكة التى فى الجسد ، لأنه ـ تبارك اسمه ـ كان يعرف كم تعمل مع قديسه للخير ، وكم تجلب له من اتضاع قلب ...",{h:"وقصة القديس بولس مع المرض ، تذكرنا بيعقوب أبى الآباء ."},"لقد صارع مع الله وغلب (تك ٣٢ : ٢٨) ، ونال البركة . ومع ذلك ضرب الله حق فخذه فانخلع . وظل يخمع على فخذه (تك ٣٢ : ٢٧ ، ٣١) . وبقى هذا المرض معه ، كعطية من الله ، يعمل معه للخير ، ويهبه الاتضاع إذ يشعر بضعفه ، لئلا يرتفع قلبه بسبب أنه نال البركة ، وأنه صارع مع الله وغلب ...",{h:"تجربة أيوب"},"لعل إنساناً يسأل : لماذا هذه التجربة تحل على إنسان قديس ، شهد له الله مرتين ، بأنه « رجل كامل ومستقيم ، وليس مثله فى الأرض » (أى ١ : ٨) (أى ٢ : ٣) ...","والحقيقة أن هذه التجربة كانت للخير من عدة نواح :",{h:"* كانت التجربة لخير أيوب ، أوصلته إلى الاتضاع ."},"كان محارباً بشىء من المجد الباطل ... كان باراً ، ويعرف عن نفسه أنه بار . ولهذا قال « لبست البر فكسانى . كجبة وعمامة كان عدلى » (أى ٢٩ : ٩) . وقيل عنه إنه « كان باراً فى عينى نفسه » (أى ٣٢ : ١) ... فكانت التجربة لازمة له ، لتعمل معه للخير ، توصله إلى انسحاق القلب ، وإلى معرفة الله . ولما وصل إلى عبارة « أندم فى التراب والرماد » (أى ٤٢ : ٦) ... رفع الله عنه التجربة ."],25:[{h:"* وكانت التجربة نافعة لأصحاب أيوب الثلاثة :"},"ذلك لأنهم كانوا « معزين متعبين » (أى ١٦ : ٢) . وقد استذنبوا أيوب وأساءوا إليه (أى ٣٢ : ٣) . وحتى من جهة الله ، لم يتكلموا عنه بالصواب (أى ٤٢ : ٨) . فكانت التجربة لازمة لهم ، لتصحيح مفاهيمهم الروحية . وقد قادتهم إلى التوبة « واصعدوا محرقات لأجل أنفسهم » (أى ٤٢ : ٧) .","* * *",{h:"* وكانت التجربة نافعة للعالم كله ."},"تلقى بها العالم درساً فى الصبر ، كما قال القديس يعقوب الرسول « خذوا يا اخوتى مثالاً لاحتمال المشقات والأناة ... ها نحن نطوّب الصابرين . قد سمعتم بصبر أيوب ، ورأيتم عاقبة الرب .. » (يع ٥ : ١٠ ، ١١) .","* * *",{h:"* وحتى تجربة أيوب ، من الناحيتين العائلية والمادية ، كانت نافعة له ."},"فقد « زاد الرب على كل ما كان لأيوب ضعفاً ... وبارك الرب آخرة أيوب أكثر من أولاه » (أى ٤٢ : ١٠ ، ١٢) . أعطاه الرب ضعف ما كان له من الخيرات المادية . ووهبه الرب بنين وبنات « ولم توجد نساء جيلات ، كبنات أيوب فى كل الأرض » (أى ٤٢ : ١٥) . ووهب الرب أيوب عمراً طويلاً ، « فعاش بعد التجربة ١٤٠ سنة ، ورأى بنيه وبنى بنيه إلى أربعة أجيال » ...","وهكذا كانت التجربة لخيره ، لما احتملها .","* * *",{h:"وكانت تجربة أيوب خجلاً للشيطان ."},"أو كانت هزيمة جديدة له ، لأن الشيطان قد يخجل من أخطائه . لذلك نقول كانت هذه التجربة سبب خزى له . فتعبير « خزى » أكثر موافقة للمعنى ...","وهكذا كانت تجربة تعمل معاً للخير لكل الأطراف ...","* * *"],26:[{h:"التجارب عموماً"},"يخاف البعض من التجارب ، وقد يضطرب لها . بينما يقول الرسول :",{h:"« احسبوه كل فرح يا اخوتى ، حينما تقعون فى تجارب متنوعة » (يع ١ : ٢) ."},"المسألة تحتاج إلى ثقة فى عمل الله معنا أثناء التجربة ، وكيف يجعلها تؤول إلى خيرنا . وهنا نرى القديس يعقوب الرسول ، لا يدعونا فقط إلى الاحتمال والصبر ، وإنما بالأكثر يدعونا إلى الفرح بالتجارب .","وهكذا ندخل فى حياة الفرح الدائم . فى النعمة نفرح ، وفى التجربة أيضاً نفرح . ونقول :",{h:"المر الذى يختاره الرب لى ، خير من الشهد الذى اختاره لنفسى ..."},"نقول كل طرقك يارب ، بحكمة قد صنعتها ... كله للخير ...","* * *",{h:"هيرودس أراد أن يقتل المسيح وهو طفل ، فصار هذا خير لمصر لما جاءها المسيح ."},"بارك الرب أرض مصر ، وصارت لنا مقادس فيها . وسقطت كثير من الأصنام (اش ١٩ : ١ ـ ٢٢) وكانوا حينما يطردون العائلة المقدسة من بلد بسبب سقوط الأصنام ، تذهب إلى بلد مصرى آخر . فكثرت البلاد التى تقدست بزيارة العائلة المقدسة لمصرنا ، وصار ذلك تمهيداً لانتشار الإيمان المسيحى فيها ...","بتذكرنا لكل هذا ، نسعد بكل ما يحدث لنا ، مؤمنين أنه :",{h:"إن لم يكن الأمر خيراً فى ذاته فلابد سيكون خيراً فى نتيجته"},"* * *"],27:["خذوا كمثال : متاعب داود من شاول الملك .","لقد طارده من مدينة إلى مدينة ، ومن برية إلى أخرى . وعاش بسببه هارباً فى البرارى والقفار ، يترصده الموت فى كل خطوة . ولكن كل ذلك التعب أعده لتحمل مسئوليات المُلك فيما بعد . إذ نضج داود سناً وشخصية . وصار جبار بأس ، كثير الاحتمال .","يعرف كيف ينتظر الرب بإيمان و يؤمن بتدخله .",{h:"والضيقات التى احتملها ، صارت نبعاً لمزاميره ."},"يغنيها على العود والقيثار والمزمار . وصارت ينبوعاً لتأملات روحية وصلوات عميقة ، تصليها الأجيال من بعده . وترى فيها كيف يختلط الطلب بالشكر بالإيمان ... وأعطانا اسلوباً نصل به ونحن فى وقت الألم والضيقة . وصار داود رجل صلاة ، صقلته التجارب ، وصاحب خبره بالعشرة مع الله .","ولو عاش داود مدللاً ، ترى ماذا كانت شخصيته ستكون ؟ !","* * *","الضيقات لو لم تنته إلى خير على الأرض ، فعلى الأقل ستعد لنا أكاليل يهبها لنا فى ذلك اليوم الديان العادل .","* * *",{h:"إن الضيقات هى مدرسة للصلاة ."},"ربما حياة التنعم تبعدنا عن الله . أما حياة الألم فإنها تقربنا إليه . فتصير صلواتنا أعمق وأكثر ، وتصير أصوامنا أكثر روحانية . كما نقترب إلى الله بالتوبة والمصالحة معه ، فنرجع إليه .","إن الضيقة التى وقع فيها اخوة يوسف ، جعلتهم يتذكرون خطيئتهم . وقالوا بعضهم لبعض : حقاً إننا مذنبون إلى أخينا ، الذى رأينا ضيقة نفسه لما استرحمنا ولم نسمع له . لذلك جاءت علينا هذه الضيقة ... فهوذا دمه يُطلب (منا) » (تك ٤٢ : ٢١ ، ٢٢) .","* * *"],28:[{h:"حتى سقوط الناس فى الخطية ، كان يؤول بالتوبة إلى خير ."},"عاش أوغسطينوس فى الخطية زمناً طويلاً ، بكت عليه فيه أمه القديسة مونيكا ... ثم تاب أوغسطينوس ، وكان من نتائج حياته الأولى كتابه الرائع عن اعترافاته ، وهو كنز روحى ، وسبب منفعة روحية للملايين ، يعرفنا كيف يعترف الإنسان علناً ، ويعترف حتى بخطاياه وهو طفل أو رضيع ...","* * *",{h:"وبالمثل يمكن أن نتحدث عن خطية داود النبى ."},"كيف أوصلته الخطية إلى حالة عجيبة من انسحاق النفس ، قال فيها « ابلل فى كل ليلة سريرى . بدموعى ابل فراشى » (مز ٥٠) . وكيف اعترف إلى الرب قائلاً « لك وحدك أخطأت ، والشر قدامك صنعت ... قلباً نقياً اخلق فىّ يا الله وروحاً مستقيماً جدده فى أحشائى » ... إلى آخر ما حواه المزمور الخمسون ، مزمور التوبة ، وما حوته باقى مزاميره من مشاعر الانسحاق ...","كان ملكاً عظيماً ، محترماً ومبجلاً من الكل . ولكن الخطية أذلته ، فقال :",{h:"« خير لى يارب أنك أذللتنى ، حتى أتعلم وصاياك » (مز ١١٩) ."},"وحينما أهانه شمعى بن جيرا إهانة مؤلمة ، وهو هارب من أبشالوم ، لم يسمح لأنصاره أن ينتقموا من هذا الإنسان ، بل قال فى اتضاع « دعوه يسب . لأن الرب قال له : سب داود ... لعل الرب ينظر إلى مذلتى » (٢صم ١٦ : ١٠) .","* * *",{h:"وبالمثل ما استفاده خاطىء كورنثوس من خطيئته وعقوبته ."},"كم أوجد فيه ذلك من الحزن والبكاء ، حتى أن القديس بولس الرسول فى رسالته الثانية إلى أهل كورنثوس ، أمرهم أن يمكنوا له المحبة « لئلا يبتلع مثل هذا من الحزن المفرط » (٢كو ٢ : ٧) ... وكان درساً لغيره ، ودرساً للمدينة كلها فى أن « يعزلوا الخبيث من وسطهم » (١كو ٥ : ١٣) .","* * *"],29:[{h:"سقوط إنسان فى خطية ، تدعوه إلى الشفقة على الذين يسقطون ."},"لأنه قد أدرك بالخبرة ، قوة حروب الشياطين ، وسهولة السقوط فى الخطية التى « طرحت كثيرين جرحى ، وكل قتلاها أقوياء » (أم ٧ : ٢٦) . ولذلك يقول القديس بولس الرسول « اذكروا المقيدين كأنكم مقيدون معهم ، والمذلين كأنكم أنتم أيضاً فى الجسد » (عب ١٣ : ٣) .","* * *",{h:"والسقوط أيضاً يكشف للإنسان ذاته وضعفه ."},"وهذا يؤول إلى الخير ، إذ يجعله يكون أكثر حرصاً وتدقيقاً فى المستقبل ، ويبعد عن التهاون . كما أن اكتشاف ضعفه يعطيه فرصة للرد على كل فكر كبرياء أو افتخار يحارب به فيما بعد .","* * *",{h:"لذلك عيشوا باستمرار فى بشاشة وفرح ."},"« افرحوا فى الرب كل حين » (فى ٤ : ٤) .","فى كل ما يحدث لكم قولوا : إننا تحت رعاية الله محب البشر ، الله الذى يحبنا أكثر مما نحب أنفسنا ، والذى يعرف خيرنا أكثر مما نعرفه ... الله الذى يسخر جميع الأمور لكى تعمل من أجل خيرنا ... الذى جعل قوانين الطبيعة أيضاً تعمل معاً للخير ، والذى خلق الحيوانات والطيور والنباتات أيضاً لأجل خيرنا . وخلق الهواء والشمس والقمر والنجوم من أجلنا ... كلها تعمل معاً للخير ، من أجل راحتنا وسعادتنا .","* * *",{h:"فلنشكر الله الذى جعل كل الأشياء تعمل معاً للخير ، لأجلنا ."},"الله صانع الخيرات ، الذى قيل عن ملائكته « أليسوا جميعاً أرواحاً خادمة ، مرسلة للخدمة لأجل العتيدين أن يرثوا الخلاص » (عب ١ : ١٤) . ولأجلنا أيضاً عين الرب رتباً فى الكنيسة « أعطى البعض أن يكونوا رسلاً ، والبعض أنبياء ، والبعض مبشرين ، والبعض رعاة ومعلمين . لأجل تكميل القديسين ، لعمل الخدمة ، لبنيان جسد المسيح » (أف ٤ : ١١ ، ١٢) .","* * *"],30:[{h:"عش سعيداً مهما حدث لك . قل : كله للخير ."},"بهذا يكون إنسان الله خالياً من كل الأمراض النفسية . خالياً من الكآبة ، والاضطراب ، والحزن السىء ، والتعقيد ، واليأس ... بل باستمرار يملك السلام على قلبه ... السلام القائم على الإيمان بالله وعمله ...","* * *","ولكن كل ذلك على شرط واضح فى الآية ، وهو « كل الأشياء تعمل معاً للخير ، للذين يحبون الرب » (رو ٨ : ٢٨) .",{h:"إذن الشرط هو : أن تكون ممن يحبون الرب ."},"لأن هناك أناساً لا تعمل الضيقات معهم للخير : بل ربما الضيقة تسبب له ألواناً من التذمر والتعب والتجديف واليأس .","هناك أناس لا يحبون الرب المحبة التى تجعلهم يثقون به وبمواعيده وبتدخله وبحلوله . ليس لديهم الإيمان الكافى ، لذلك تعصرهم الضيقة ، وتجعل نفوسهم متأزمة معقدة ، تعيش فى رعب المشكلة ، وليس فى حلها .","* * *"],31:[{h:"كلمات فى الرجاء"},"ليتنا بدلاً من أن ننظر إلى الحاضر المتعب الذى أمامنا ، ننظر بعين الرجاء إلى المستقبل المبهج الذى فى يد الله .","* * *","كل مشكلة تبدو معقدة أمامنا ، لها عند الله حلول كثيرة .","وكل باب مغلق ، له فى يد الله مفتاح بل مفاتيح عديدة ...","هو الذى يفتح ولا أحد يغلق (رؤ ٣ : ٧) .","* * *","الرجاء يمنع الخوف ، ومنع القلق والاضطراب ، ويبعث الاطمئنان .","بل أننا نكون « فرحين فى الرجاء » (رو ١٢ : ١٢) .","* * *","لا ننظر إلى المتاعب مجردة ، بدون عمل الله ، الذى يقدر أن يحول الشر إلى خير ...","* * *","الله قادر أن يحول كل مجريات الأمور ، فى اتجاه مشيئته .","* * *","الذى لا يستطيعه الضعف البشرى ، تقدر عليه قوة الله .","والذى لا تستطيعه حكمة الناس ، تقدر عليه حكمة الله .","* * *","ثق أنك لست وحدك . أنت محاط بمعونة إلهية .","وقوات سمائية تحيط بك ، وقديسون يشفعون فيك ."],32:[{h:"الفصل الثالث"},{h:"تعالوا إلىّ يا جميع المتعبين والثقيلى الأحمال وأنا أريحكم (متى ١١ : ٢٨)"},"من محاضرة القيت فى الكاتدرائية يوم الأربعاء ٨٦/١٠/١٥ ."],33:["كل إنسان فى الدنيا له متاعبه الخاصة ، سواء كانت متاعب ظاهرة للآخرين ، أو مكتومة فى القلب ، سواء كانت متاعب روحية ، أو متاعب نفسية ، أو متاعب جسدية ، أو متاعب عائلية أو اجتماعية .",{h:"والسيد المسيح قد جاء من أجل التعابى ."},"جاء « يطلب ويخلص ما قد هلك » (متى ١٨ : ١١) . جاء ليخلص العالم من خطيئته كما قال اشعياء النبى « كلنا كغنم ضللنا . ملنا كل واحد إلى طريقه . والرب وضع عليه إثم جميعنا » (اش ٥٣ : ٦) وأيضاً جاء المسيح ليخلص العالم من آلامه ومتاعبه ، ولذا قال نفس النبى « لكن أحزاننا حملها ، وأوجاعنا تحملها » (اش ٥٣ : ٤) . وهو أيضاً قال « تعالوا إلىّ يا جميع المتعبين والثقيلى الأحمال ، وأنا أريحكم » (متى ١١ : ٢٨) .",{h:"لماذا قال « يا ثقيلى الأحمال ؟ » ربما لأن الذى حمله خفيف يحتمل ويسكت . أما الذى حمله ثقيل ، فليس أمامه إلا أن يقول : يارب ..."},"المفروض أن نلجأ إلى الرب ، سواء كان الحمل ثقيلاً أو خفيفاً . ولكن على الأقل إذا كان الإنسان مضغوطاً جداً من ثقل أحماله ، فلن يجد أمامه سوى وعد الرب بأن يريحه .",{h:"تعالوا ... وأنا أريحكم . إنها دعوة ووعد ."},"دعوة من الله ، ووعد إلى عالم تعبان ، مثقل بمشاكل من كل نوع : مشاكل الانشقاقات والحروب ، ومشاكل الإسكان والتموين ، ومشاكل الزواج والطلاق ، ومشاكل التطرف والإرهاب ، ومشاكل الفساد والادمان . وفى كل هذه المشاكل ، يقول الرب تعالوا إلىّ يا جميع المتعبين ... وأنا أريحكم .","* * *"],34:[{h:"وهنا نجد صفة جميلة من صفات الرب ، وهو أنه مريح ."},"مريح التعابى والثقيلى الأحمال ، كثيرون فى متاعبهم يجلسون مع آخرين فيزيدونهم تعباً على تعبهم .","وقد يلجأون إلى البعض ، فلا يجدون منهم سوى الاهمال واللامبالاة . لكن المسيح المريح ، كل من يلجأ إليه يستريح . إنه دائماً يعطى . يعطى الناس راحة وهدوءاً وعزاءً ، وسلاماً وطمأنينة فى الداخل . ويرفع عن الناس أثقالهم ، ويحملها بدلاً عنهم ، ويريحهم . وهكذا يفعل من لهم صورة الله ...",{h:"قال الرب : أدعنى فى يوم الضيق ، أنقذك فتمجدنى (مز ٥٠ : ١٥) ."},"البعض إذا أصابته ضيقة ، يظل يغلى بالألم والحزن داخل نفسه . أفكاره تتعبه ، ونفسيته تتعبه ، وربما اليأس يتعبه . وربما لا يجد أمامه سوى الشكوى أو التذمر أو البكاء . وفى كل ذلك لا يفكر أن يلجأ إلى الله ، ولا أن يضع أمامه قول المزمور :",{h:"« إلق على الرب همك . وهو يعولك » (مز ٥٥ : ٢٢) ."},"تعال إذن وكلم الرب عن متاعبك بكل صراحة ، سواء كانت تتعبك معاملة الآخرين أو ضغوطهم . أو ظلمهم أو قسوتهم ... أو كانت تتعبك شكوك أو أفكار ، أو خطايا ، أو عادات مسيطرة عليك ، وتأكد أن الرب يعرف متاعبك أكثر مما تعرفها أنت ويريد أن يخلصك منها جميعاً . فاطلبه فى رجاء وثقة ، واضعاً أمامك قول المزمور :",{h:"« يستجيب لك الرب فى يوم شدتك . ينصرك إسم إله يعقوب » (مز ٢٠ : ١) ."},"وثق أن الكنيسة أيضاً تصلى من أجلك ، حينما تقول فى آخر صلاة الشكر « كل حسد وكل تجربة ، وكل فعل الشيطان ، ومؤامرة الناس الأشرار ، وقيام الأعداء الخفيين والظاهرين اتزعها عنا وعن سائر شعبك » ... كذلك تذكر كل متاعبك فى صلوات القداس الإلهى .","* * *",{h:"تأكد أيضاً أن الضيقات ليست لوناً من التخلى ."},"فالله سمح أن رسله وقديسيه تصيبهم الشدائد ، ولكنه كان واقفاً إلى جوارهم"],35:["يريحهم . وهكذا قال القديس بولس الرسول عن نفسه وعن زملائه فى الخدمة « مكتئبين فى كل شىء ، لكن غير متضايقين . متحيرين لكن غير يائسين ، مضطهدين لكن غير متروكين ... » (٢كو ٤ : ٨ ، ٩) .",{h:"نعم ، ما أكثر متاعب الناس ... والمسيح مستعد أن يريحهم جميعاً ."},"هناك شخص يتعبه الآخرون . وهناك من تتعبه نفسه . كإنسان مغلوب من شهواته ، أو مغلوب من طباعه ، أو من عاداته . ويريد أن ينتصر على نفسه ولا يستطيع ... هذا يستند على قول الرب « تعالوا إلىّ يا جميع المتعبين ... وأنا أريحكم » .",{h:"وهناك إنسان تتعبه الخطية ولا يستطيع فكاكاً منها ..."},"كلما يتوب ، يرجع فيخطىء مرة أخرى . ومهما اعترف بخطية ، يعود إليها ويكرر اعترافاته . يضع لنفسه تداريب روحية ، ولكنه لا يثبت فيها . يحاول أن يغصب نفسه على حياة البر ، ومع ذلك فلا يزال يحيا فى الخطية . خطيته هى منذ سنوات ، وطبعه الردىء هو هو ، ولا تحسن ! إنه مغلوب وساقط . تكاد الخطية أن تصبح طبيعة له . وقد لجأ إلى الآباء والمرشدين الروحيين ، وإلى القراءات وأقوال الآباء القديسين وسيرهم ، ولا فائدة . هذا الإنسان ليس أمامه سوى قول الرب : « تعالوا إلىّ يا جميع المتعبين والثقيلى الأحمال وأنا أريحكم » .","* * *",{h:"فشل الالتجاء إلى غير الله"},"لماذا تجعل الرب آخر من تلجأ إليه . ابدأ به حتى تصل ولا تضل . هوذا الرب يعاتبنا قائلاً :",{h:"« تركونى أنا ينبوع المياه الحية . وحفروا لأنفسهم آباراً ، آباراً مشققة لا تضبط ماء » (ار ٢ : ١٣) ."},"نعم ، كثيرون يلجأون إلى الآباء المشققة ، سواء من جهة الآخرين أو أنفسهم ."],36:["يقع أحدهم فى مشكلة . فيحاول أن يحلها بذكائه الخاص وتفكيره ، بحيله وتدبيره . أو يلجأ إلى الآخرين لكى يسندوه فى مشكلته . ولا ينتفع من كل ذلك شيئاً ، لأنه لم يلق همه على الله وحده وهو يعوله . لم يطلب المسيح لكى يريحه . إنه يحاول الاعتماد على الذراع البشرى ! ويتجاهل قول الرب « تعالوا إلىّ » ... لذلك يفشل ويبقى فى مشاكله بلا حل .","آخاب الملك اشتهى شهوة . اشتهى حقل نابوت اليزرعيلى . ولم يلجأ إلى الله ، بل لجأ إلى إيزابل ، فضيعته . أسند رأسه المتعبة على إيزابل فضاع .",{h:"كذلك شمشون أسند رأسه المتعبة على دليلة ، فضاع !"},"ولم يحدث أن أحداً منهما وجد حلاً ... كذلك اليهود لما لجأوا إلى فرعون ، لكى يخفف عنهم تعبهم ، لم يخففه ، بل أزاد أثقالهم ، قائلاً لهم : « متكاسلون أنتم متكاسلون » (خر ٥ : ١٧) . ولما لجأ الشعب إلى رحبعام ليخفف عنهم نير سليمان أبيه ، أجابهم « أبى أدبكم بالسياط ، وأنا أؤدبكم بالعقارب » (١مل ١٢ : ١٤) .",{h:"إن الذراع البشرى ليس هو الذى ينقذ الإنسان . إنما الذى ينقذه هو الله ."},"لذلك إرفع بصرك إلى الله وقل له : « كل حمل سألقيه عليك ، ولا أعود أفكر فيه ثانية ، أنت الذى تحله ، لأنك أنت حلال المشاكل وليس غيرك . وكلما ألجأ إلى غيرك تزداد مشاكلى وتتعقد ... »","* * *",{h:"عجيب أن البعض يحاول أن يحل مشاكله بخطايا !"},"هناك من يحاول أن يحل المشكلة بالكذب ، وأحياناً يقول إنه كذب أبيض ! أو قد يلجأ إلى المكر وإلى الدهاء ... بل قد يحاول فى بعض الأوقات أن يحل مشكلته بالعنف . أو قد يهرب من مشكلته بتعاطى الخمر أو المخدرات لكى ينساها ، أو قد يلجأ إلى المسكنات والمنومات ، أو إلى التدخين . وكل ذلك لا يحل مشكلته ، بل يضيف إليها مشكلة أخرى وأسوأ من ذلك من يلجأ إلى السحرة والعرافين والدجالين .","* * *"],37:[{h:"والبعض قد يحاول حل مشكلته بالوهم وأحلام اليقظة ."},"فيجلس ويتخيل أنه قد صار وصار ... وإذ لا يعجبه الواقع ، يحاول على الأقل أن يتلذذ بالخيال ! ويقول لنفسه : إن لم أنل النجاح ، فعل الأقل أحلم به ! وإن استيقظت من أحلامى ، أنام مرة أخرى لأحلم بها ... ! ولكن أحلام اليقظة لا تحل مشاكله التى تظل باقية . إنما يحلها قول الرب « تعالوا إلىّ وأنا أريحكم » .","* * *",{h:"الله هو حلال المشاكل"},"هناك أشخاص لم يكن لهم حل سوى الله . مثال ذلك : الثلاثة فتية ، حينما ألقوا فى أتون النار . ويونان النبى حينما كان فى جوف الحوت . ودانيال النبى حينما ألقوه فى جب الأسود . حقاً ، من كان ينقذ كل هؤلاء سوى الله وحده ؟ ! الذى أرسل ملاكه فسد أفواه الأسود (دا ٦ : ٢٢) ، وأمر الحوت فقذف يونان إلى البر (يون ٢ : ١٠) . ولم يسمح للنار أن تؤذى الفتية .",{h:"كذلك تدخلت يد الله فى المشكلة الأريوسية ..."},"لقد قامت الكنيسة كلها على أريوس المهرطوق . حرمه المجمع المسكونى ، ورد عليه القديس أثناسيوس . ولكنه استمر يشكك الناس فى الإيمان ، ويلجأ إلى سلطة الأمبراطور حمايته فأمر بإرجاعه . وألتفت الرب إلى الكنيسة قائلاً : « تعالوا إلىّ وأنا أريحكم » . وأقيمت الصلوات ، فانسكبت أحشاء أريوس ، ومات ...",{h:"كذلك فعل الله مع جيش سنحاريب ، ومع فرسان فرعون ."},"حزقيا الملك مزق ثيابه وتغطى بمسح ، ودخل بيت الرب ، ملقياً همه عليه . فخرج ملاك الرب وضرب من جيش أشور ١٨٥ ألفاً (٢مل ١٩ : ١ ، ٣٥) . وأغرق الرب فرعون وفرسانه فى البحر الأحمر . ذلك لأن موسى النبى قال للشعب « قفوا وانظروا خلاص الرب ... الرب يقاتل عنكم وأنتم تصمتون » (خر ١٤ : ١٣ ، ١٤) .","* * *"],38:["حقاً : حينما تفشل جميع الحلول ، يبدو حل الله واضحاً . والرب يقاتل عنكم وأنتم تصمتون .","إنه أمين فى قوله « أنا أريحكم » . ما أجمل الترتيلة التى تقول « لما أكون تعبان ، أروح لين غيرك » ... بنفس الوضع أراح الرب الكنيسة من ديوقلديانوس الذى سفك دماء آلاف الشهداء ، بل دماء مدن بأسرها ، كشهداء أخميم وشهداء إسنا . وأراحنا الله من ديوقلديانوس ، وجاء قسطنطين برسوم ميلان للتسامح الدينى ... وأراح الله الكنيسة من اضطهاد شاول الطرسوسى لها . وحوله بنعمته إلى أقوى كارز بالمسيحية . فصار بولس .","ولا ننسى أيضاً كيف أراح الله داود النبى من شاول الملك الذى كان يطارده من برية إلى أخرى ...","* * *",{h:"إن حلول الله هى أقوى الحلول وانجح الحلول . فعلينا أن نلجأ إليها ونتمسك بها ."},"يعقوب أبو الآباء ، كان خائفاً من أخيه عيسو ، وعاجزاً عن ملاقاته ، ولكنه عندما تمسك بالرب وقال له « لا أتركك حتى تباركنى » (تك ٣٢ : ٢٦) ، « نجنى من يد أخى ، من يد عيسو ، لأنى خائف منه أن يأتى ويضربنى ، الأم مع البنين » (تك ٣٢ : ١١) ... حينئذ ركض عيسو للقائه وعانقه ووقع على عنقه وقبله باكياً (تك ٣٣ : ٤) .",{h:"وأنت إن استطعت أن تغلب فى صراعك مع الله ـ كيعقوب ـ لابد سيريحك من كل متاعبك ."},"لقد تعب سمعان بطرس الليل كله ولم يصطد شيئاً . ولكنه لما تلاقى مع الرب ، وعلى كلمته ألقى الشبكة ، حينئذ اصطاد سمكاً كثيراً ، حتى كادت الشبكة تتخرق (لو ٥ : ٤ ـ ٦) .","والمرأة الخاطئة حينما أمسكت بقدمى المسيح وبللتهما بدموعها ، أمكنها أن تتخلص من خطاياها ، وتنال المغفرة . وما كان ممكناً لها ذلك ، لولا ذهابها إليه .",{h:"المهم أن نأتى إلى الله . ولكن كيف نأتى ؟ ."}],39:[{h:"كيف نأتى إلى الله ؟"},{h:"١ ـ نأتى بقلب منسحق ، مثلما أتى الإبن الضال :"},"إنه كان فى الكورة البعيدة يعيش فى تعب . ثم فكر أن يأتى إلى أبيه ليستريح . فأتى إليه بقلب منسحق يقول : « أخطأت إلى السموات وقدامك ، ولست مستحقاً أن أدعى لك إبناً » (لو ١٥ : ٢١) . وبهذا الانسحاق قبله أبوه ، وأقام له وليمة فرح ، وألبسه الحلة الأولى ، وجعل خاتماً فى يده ... بينما أخوه الأكبر خسر الموقف ، لأنه رفض أن يأتى ، وتكلم مع أبيه بكبرياء قلب .",{h:"لا تأت إلى الله متكبراً ، تقول له : لماذا تتركنى وتضطهدنى ."},"ولا تنسب إلى الله كل اسباب مشاكلك ، غير معتقد أنك أنت السبب ، بل تنسب السبب إلى تخلى الله عنك ! ! إنما تعال إليه منسحقاً ، لكى تصطلح معه . وكما قال أحد الآباء :",{h:"اصطلح مع الله ، تصطلح معك السماء والأرض ."},"إذن لا تأتِ إليه فقط لكى يريحك من أتعابك ويحل لك مشاكلك ، إنما تعال أولاً لكى تصطلح معه . فربما يكون السبب الأصل فى مشاكلك ، أنك فى خصومة مع الله ، وأن طرقك لا ترضيه ... ويقول لك الله : أنا مستعد أن أريحك ، إنما المهم أن تترك الطريق الخاطىء الذى تسير فيه . وكما يقول :",{h:"ارجعوا إلىّ ، ارجع إليكم ، قال رب الجنود (ملا ٣ : ٧) ."},"* * *",{h:"٢ ـ إذن تعال إليه تائباً ، لكى تصطلح معه ."},"وحينما تصطلح مع الله . تجد الدنيا كلها قد اصطلحت معك . و يعطيك الرب سلاماً وراحة فى قلبك . يعطيك هدوءاً داخلياً ، وثقة وطمأنينة . وغالباً ما يكون سبب تعب الإنسان ، هو شىء فى داخله يتعبه . وهنا يعجبنى قول القديس يوحنا ذهبى الفم :"],40:[{h:"لا يستطيع أحد أن يضر إنساناً ، ما لم يضر هذا الإنسان نفسه ."},"فمن الجائز أن يكون سبب متاعبك ، هو أنك تضر نفسك ، فإذا ما اصطلحت مع الله وأتيت إليه تائباً ، ستتخلص من ضررك لنفسك ، وتكون راحتك سهلة وممكنة .","* * *",{h:"٣ ـ كذلك ينبغى أن تأتى إلى الله ، بالإيمان ، وبالصلاة ."},"كثيرون يأتون إلى الله ، ولكن ليس عندهم إيمان أن الله سيحل مشاكلهم ! ويصلون وهم لا يحسون أن الصلاة ستكون لها نتيجة . وهكذا يستمرون فى تعبهم بسبب عدم إيمانهم ، وبسبب فقدانهم للرجاء والثقة بالله .","لقد قال السيد المسيح للمرأة الخاطئة التائبة « إيمانك خلصك ، فاذهبى بسلام » (لو ٧ : ٥٠) . وقال للأبرص الذى شفى « قم وامض ... إيمانك خلصك » (لو ١٧ : ١٩) . وقال للأعمى المستعطى فى أريحا « أبصر . إيمانك قد شفاك » (لو ١٨ : ٤٢) ، وقال للأعميين « بحسب إيمانكما ، ليكن لكما » (متى ٩ : ٢٩) . لذلك تعال إليه بإيمان ، واثقاً أنه سيريحك ، وحينئذ ستستريح ...","* * *",{h:"٤ ـ تعال إليه أيضاً ، وأنت تحمل نيره عليك ."},"فهو الذى قال « احملوا نيرى عليكم ، وتعلموا منى فإنى وديع ومتواضع القلب ، فتجدوا راحة لنفوسكم » (متى ١١ : ٢٩) . إذن احمل صليبك واتبعه . وحينما تأتى إليه فى مشاكلك ، لا تأت متذمراً متضجراً ، بل تعال فى حياة التسليم ، خاضعاً لمشيئته ، متذكراً قول الرسول :",{h:"« واحسبوه كل فرح يا أخوتى ، حينما تقعون فى تجارب متنوعة » (يع ١ : ٢) ."},"بهذا لا يضغط عليك التعب ، لأن قلبك سليم من الداخل . لم تستطع المتاعب التى فى الخارج أن تتعب القلب من الداخل ، لأنه محصن بالإيمان وبحياة التسليم ، ولأنه يحمل نير الرب بفرح . والقلب فى الداخل مملوء بالسلام والطمأنينة وبالفرح ، حتى فى وسط الضيقات ..."],41:["فإن لم يكن لك هذا الشعور ، اطلبه من الله .","وهو الذى يهبك السلام ، لأنه هو الذى قال « سلامى أترك لكم ، سلامى أنا أعطيكم » (يو ١٤ : ٢٧) . إن من ثمار الروح « محبة وفرح وسلام » (غل ٥ : ٢٢) . فإن كانت لك ثمار الروح هذه ، ستحيا دائماً مستريحاً .",{h:"٥ ـ ادخل إذن فى شركة الروح القدس ، ولتكن لك ثمار الروح ، وتعال إلى الله هكذا ، تجد راحة لنفسك ."}],42:[{h:"الفصل الرابع"},{h:"سعى الله لخلاصنا"},"« يريد جميع الناس يخلصون وإلى معرفة الحق يقبلون » (١تى ٢ : ٤)"],43:["قد يفقد الإنسان رجاءه فى الخلاص ، لأن أعداءه قد اعتزوا أكثر منه ، ولا قدرة له على مقاومتهم ، سواء فى ذلك أكانوا أعداءه الروحيين ، أو مضايقيه فى هذا العالم . وهو خلال ذلك يصرخ « إن الغرباء قد قاموا علىّ ، والأقوياء طلبوا نفسى ، ولم يسبقوا أن يجعلوا الله أمامهم » (مز ٥٣) « ضاع المهرب منى ، وليس من يسأل عن نفسى » (مز ١٤١) .","أو قد يفقد خاطىء رجاءه فى التوبة ، لأنه لا يقدر على الوصول إليها ، أو بالأكثر لا يريدها .. !","ولكننا نقول لكل واحد من هؤلاء وأمثالهم :",{h:"لا تفقد رجاءك . فإن الله يهتم بخلاصك أكثر مما تهتم أنت .. بل هو الذى يسعى لخلاصك . وهذا هو اسلوب الله منذ البدء .."},"* * *","بدأت قصة هذا الخلاص منذ أيام أبوينا الأولين آدم وحواء . لقد سقط الاثنان فى الخطية ، واستحقا حكم الموت . وكان الخلاص لازماً لهما جداً . ومع ذلك نرى أن الله نفسه هو الذى سعى لكى يخلصهما ...",{h:"لا آدم طلب الخلاص ، ولا حواء ، بل هربا كلاهما من وجه الله ، واختفيا خلف الأشجار .. !"},"ما كان الهروب وسيلة عملية تؤدى إلى الخلاص . ولكن الخلاص لم يكن يشغلهما فى ذلك الحين . وكل ما كان يشغلهما هو الخوف والخجل . ما سمعنا قط أن آدم قال لله : يارب اغفر ، يارب سامح . أخطأت إليك ، فامح ذنبى ... ولا حواء قالت شيئاً من هذا ... ولعل هذه الألفاظ لم تكن فى قاموسهما الروحى فى ذلك الحين ...","وفيما هما لا يبحثان عن خلاص نفسيهما ، كان الله يبحث عنهما .."],44:["كان ينادى فى الجنة « يا آدم ، أين أنت ؟ » (تك ٣ : ٩) . كان الله هو الذى يفتش عن آدم وحواء ، وهو الذى يفتح الموضوع ، ويستدرجهما إلى الكلام ، ويشرح لهما ما وقعا فيه من خطأ ، وما يستحقانه من عقوبة . ثم يقدم لهما أول وعد بالخلاص ، وهو أن نسل المرأة سوف يسحق رأس الحية (تك ٣ : ١٥) .","* * *",{h:"صدقونى ، لو أن الله ترك الإنسان إلى حريته وحده ، أو إلى قدرته وحده ... ما خلص أحد على الإطلاق ... !"},"ولكن الله هو الذى يسعى وراء خلاص الكل ... كما أعطانا مثلاً عن سعيه وراء الخروف الضال ، ووراء الدرهم المفقود (لو ١٥) .","* * *","كان الخروف سائراً فى ضلاله ، لا يدرى أين هو ، وربما لا يدرى ما هو فيه . وفيما هو كذلك كان الراعى الصالح مهتماً بخلاصه . الراعى هو الذى اكتشف ضياع هذا الخروف ، وهو الذى بحث عنه وفتش ، وجرى وراءه فى الجبال والوديان إلى أن وجده . ولعلها كانت مفاجأة له ، حينما وجد راعيه أمامه ، يأخذه فى حنان ، ويحمله على منكبيه فرحاً . حقاً ما أجمل قول الوحى الإلهى عن الرب كراع :",{h:"« أنا أرعى غنمى وأربضها ـ يقول السيد الرب ـ وأطلب الضال ، واسترد المطرود ، وأجبر الكسير ، وأعصب الجريح ... » (حز ٣٤ : ١٥ ، ١٦) ."},"هو الذى يطلب ويسترد ، وهو الذى يجبر ويعصب . العمل هو عمله ، وليس عملنا نحن ... أليس هذا أمراً يبعث الرجاء فى النفس ؟","* * *",{h:"وفى مثال الدرهم المفقود ، نرى نفس الوضع ، وبأسلوب أعمق :"},"الدرهم لا يملك حياة ، ولا عقلاً ولا فكراً ولا إرادة .. ولا يدرى إلى أين هو قد تدحرج ، وأين استقر به الأمر . وأيضاً لا يعرف كيف يرجع إلى كيس صاحبه أو جيبه ..."],45:[{h:"وقد كان الدرهم المفقود رمزاً إلى كثيرين من نوعه ..."},"كان رمزاً لكثيرين ممن لا حياة لهم ولا إرادة ... وكان رمزاً أيضاً للضآلة ... فلو أن الأرملة كانت فقدت مائة جنيه ذهباً ، لكان من المعقول أن تبحث عنها وتفتش ... أما مجرد درهم واحد ينال منها كل ذلك الاهتمام ، فهو أمر يدعو إلى التأمل ، ويضع أمامنا عمقاً فى الرجاء وهو :",{h:"إن الله يبحث عن خلاصك ، مهما بدا قدرك ضئيلاً !"},{h:"لقد ضرب الله لنا مثل الدرهم لنعرف قيمة النفس عنده ."},"لأنه قد يسأل بعضهم ما قيمة هذا الدرهم الضئيل ، حتى يصير هذا البحث الجاد عنه ، وهذا الفرح وهذه الوليمة عند العثور عليه ؟ ! إن كل هذا رمز لاهتمام الرب بالنفس الواحدة ، مهما كانت تبدو ضئيلة الشأن . ويعبر المثل عن سعى الله لخلاصنا حتى لو لم نسع نحن ، وفرحه بخلاصنا وفرح الملائكة أيضاً .","ألست أنت عند الله أفضل من درهم واحد مفقود ؟ !","* * *","ثق أن نفسك ثمينة فى نظرة الله إليها ، مهما كانت تبدو ضئيلة فى نظر الناس ، أو فى نظرك أنت ... مثل المرأة السامرية التى سعى الرب لخلاصها ، وهى محتقرة فى نظر الناس ... ومثل زكا العشار الذى ذهب الرب إلى بيته ، وهو فى نظر الكل رجل خاطىء لا يستحق (لو ١٩ : ٧) .","* * *",{h:"حقاً ، إن الرب يسعى لخلاصنا ، ويفرح بذلك جداً .."},"كما أخذ الخروف الضال ، و « حمله على منكبيه فرحاً » (لو ١٥ : ٥) ، وكما قال إنه « يكون فرح فى السماء بخاطىء واحد يتوب » (لو ١٥ : ٧) ، وكما فرح برجوع الابن الضال ، وذبح له العجل المسمن ، وكما فرح بالعثور على الدرهم المفقود (لو ١٥ : ٢٣ ، ٩) . إنه يسعى لخلاصنا أكثر مما نسعى نحن ، ويفرح بخلاصنا أكثر مما نفرح نحن . ويفتش عنا بكل اهتمام ، أكثر مما نفتش نحن عن أبديتنا . وما أجمل ما قاله الرسول عنه إنه :"],46:[{h:"« يريد أن الجميع يخلصون ، وإلى معرفة الحق يقبلون » (١تى ٢ : ٤) ."},"وقيل عنه أيضاً إنه لا يشاء موت الخاطىء ، بل أن يرجع ويحيا (حز ١٨ : ٢٣) . ونقول عنه فى آخر كل صلاة من صلوات الأجبية : « الداعى الكل إلى الخلاص من أجل الموعد بالخيرات المنتظرة » ...","* * *",{h:"إن عمل الله ليس فقط أن يفرح بتسبيح السارافيم ، أو بنقاوة الملائكة ، أو بكرازة الرعاة ، أو بجهاد القديسين ، إنما هو يفرح بخاطىء واحد يتوب أكثر من تسعة وتسعين براً لا يحتاجون إلى توبة (لو ١٥ : ٧) ."},{h:"يطلب ما قد هلك ... !"},"لا تفقد الرجاء إذن مهما ضللت ، لأن هناك درجة أبشع كثيراً من الضلال قد جاء الرب لخلاصها ، كما قال عن نفسه إنه :",{h:"« جاء يطلب ويخلص ما قد هلك » (لو ١٩ : ١٠) ."},"يخلص مَنْ ؟ ليس مجرد الضعيف أو الخاطىء أو المتوانى أو المريض ... وإنما « ما قد هلك » ... ! ليس فقط مَنْ هو فى طريق الهلاك ، إنما ما قد هلك ! ! ... أى رجاء أعظم من هذا أن الرب « جاء يطلب ويخلص ما قد هلك » ... ولم يقل « يخلص الطالبين ... » إنما هو الذى يطلب ... الذى يسعى الخلاص كل أحد ...",{h:"إذن حتى الذى هلك ، مازال له رجاء فى الخلاص !"},"نعم بلا شك . إن المسيح قد جاء ليخلص هذا الهالك وأمثاله . جاء يخلص الموتى بالخطايا (أف ٢ : ٥) .","لا يقل أحد إذن ، مهما حدث منه ، ومهما حدث له : أنا انتهيت ، أنا ضعت . وليست هناك فائدة منى ، ولا وسيلة لخلاصى ... ! اطمأن فحتى إن كنت قد هلكت فعلاً ، فاعلم ان باب الخلاص لا يزال مفتوحاً أمامك ، والرب قد جاء يطلب ويخلص ما قد هلك ..."],47:[{h:"وهب الله رجاء للمجدلية التى كان عليها سبعة شياطين ."},"وعندما قام من الأموات ، يقول مرقس الإنجيلى إنه « ظهر أولاً لمريم المجدلية التى كان قد أخرج منها سبعة شياطين » (مر ١٦ : ٩) . ولما أراد أن يبشر رسله القديسين بقيامته ، اختار هذه بالذات لكى تبشرهم ! ! ونحن لا ندرى هل كان عليها سبعة شياطين فقط أم رقم سبعة هنا له معنى رمزى يدل على عدد كبير من الشياطين ! !","ولكن ماضى المجدلية قد نُسى ، وقد أصبحت مبشرة للرسل ! يا للعجب ! أليس هناك رجاء لك من خلال قصة هذه المرأة العجيبة ؟ !","* * *",{h:"حقاً انظروا لا تحتقروا أحد هؤلاء الصغار (متى ١٨ : ١٠) ."},"سواء الصغار فى سنهم ، أو فى روحياتهم ، أو فى نوعيتهم ، أو أصحاب الماضى الطويل الاثيم . لا تحتقروا أحداً . ولا تصغر نفس أحد إن كان واحداً من هؤلاء ، ولا يفقد رجاءه .",{h:"صدقونى ، إن الله فى اليوم الأخير سيرتبنا ترتيباً آخر غير الذى نحن عليه الآن ..."},"ترتيبنا فى العالم الحاضر هو حسب السن أو المركز أو الدرجة ، أو المواهب والقدرات ... أما فى الأبدية فسيكون حسب القلب الذى يعرفه الله . وربما كثير من الصغار هنا ، ومن المزدرى وغير الموجود ، يسبقون أصحاب الدرجات والمواهب ، وأصحاب المناصب والرئاسات . فلا تحتقروا إذن أحد هؤلاء الصغار .","* * *",{h:"ولما أراد الله خلاص اريحا ، اختار راحاب الزانية (يش ٢) ."},"ودخلت راحاب فى شعب الله ، كما دخلت فى سلسلة الأنساب (متى ١) وصارت قديسة ، ونسى لها ماضيها . وصارت صورة حية للرجاء لكل من يتذكرها .","ولعلك تسأل : ما معنى اهتمام الله بامرأة زانية ، وبأخرى كان عليها سبعة شياطين ؟ ! أقول لك إنه نفس اهتمامه بالأشياء الصغيرة ، بالمزدرى وغير الموجود (١كو ١ : ٢٨) ."],48:[{h:"إن قصة (المدوسة بدمها) فى سفر حزقيال ، تعطى رجاء للكل ..."},"قال عنها الكتاب إنها كانت عريانة وعارية ، ومطروحة على الحقل بكراهة نفسها ، وانها كانت مدوسة بدمها ... فهل تركها الله هكذا ؟ كلا ، إنه يقول لها وهى فى هذه الحالة السيئة :",{h:"« مررت بكِ ورأيتكِ ، وإذا زمنكِ زمن الحب » ."},"أى حب يارب هذه المكروهة ، العارية من كل فضيلة ، المطروحة على الحقل ؟ ! نعم ، إن الله أحبنا ونحن خطاة ، ولهذا بذل نفسه عنا ، ومات لأجلنا ، البار من أجل الأثمة . وماذا عن هذه الاثيمة الخاطئة ؟ يقول لها « مررت بكِ » ، وليست هى التى ذهبت إليه . وماذا أيضاً ؟ يقول :",{h:"« فبسطت ذيلى عليكِ ، وسترت عورتكِ » . غطى الخطية ولم يحتقر صاحبتها ..."},"* * *",{h:"« ودخلت معكِ فى عهد ، يقول السيد الرب ، صرتِ لى » ..."},"وفى هذا العهد ، منحها الرب الكثير من نعمه الروحية . يقول :",{h:"« فحممتكِ بالماء » يعنى المعمودية ، حيث غسلها من كل خطاياها ."},{h:"« ومسحتكِ بالزيت » يعنى الميرون ، فنالت المسحة المقدسة ، مسحة الروح القدس . « وألبستكِ مطرزة ، وكسوتكِ براً » أى البر الجديد الذى نالته ."},"وماذا أيضاً ؟ يقول : « وجلتِ جداً جداً ، فصلحتِ لمملكة » أى للملكوت .",{h:"« وخرج لكِ إسم فى الأمم لجمالكِ ، لأنه كان كاملاً ببهائى الذى طرحته عليكِ ، يقول السيد الرب » (حز ١٦ : ١٤) ."},"عجيب حقاً هو الله الحنون هذا ، الذى يطرح بهاءه على هذه الدوسة بدمها ، المكروهة ، فتصير كاملة الجمال ، وتصلح لمملكة ، وتدخل فى عهد مع الله ، وتنال من كل نعمه ، بل يقول لها : « وتاج جمال على رأسكِ » (حز ١٦ : ١٢) .","أليس كل هذا يعطينا درساً عجيباً فى الرجاء ... ؟"],49:[{h:"ليس المهم ما نحن فيه ، إنما ما يصيرنا الرب إليه ..."},"وفى قصة هذه الخاطئة ، التى ترمز لأورشليم كلها ، كان الرب يعمل كل شىء . ولو تركها لنفسها لضاعت ، واستمرت فى عبادة الأصنام . ولكن مناخس الرب كانت تحرك الضمير باستمرار وتقوده إلى التوبة . ولعل هذا الأمر يذكرنا أيضاً بقصة شاول الطرسوسى .",{h:"مثال شاول الطرسوسى"},{h:"هل شاول الطرسوسى بحث عن المسيح ، أم بحث المسيح عنه ؟"},"كان شاول « مجدفاً ومضطهداً للكنيسة ومفترياً » كما قال عن نفسه (١تى ١ : ١٣) وكان « يسطو على الكنيسة ، وهو يدخل البيوت ويجر رجالاً ونساء ويسلمهم إلى السجن » (أع ٨ : ٣) . ولكن الله كان يفكر فى خلاص شاول ، وفى استخدام مواهبه للخير ، فظهر له فى طريق دمشق ، ودعاه .",{h:"إن شاول لم يطلب الإيمان . وفى يوم لقائه بالرب ، لم يكن شاول يرتب لهذا اللقاء ولم يفكر فيه ، ولا طرأ على ذهنه .."},"ولكن الله هو الذى سعى إلى شاول ، وطلبه وخلصه ودعاه .","إن فى تحول شاول الطرسوسى مضطهد الكنيسة إلى أعظم رسول فى المسيحية ، وتعبه لأجل الكلمة ، هو درس عظيم فى الرجاء أمام كل مَنْ هم بعيدين عن الرب .","لعل مثله اريانوس والى أنصنا ، أكثر ولاة مصر عنفاً فى قتل الشهداء وتعذيبهم ، وكيف أمكن أن يتحول هو نفسه إلى شهيد ... بعمل الرب فيه ولأجله ..","فى سعى الله لخلاصنا ، نذكر أيضاً قصة عذراء النشيد .","* * *"],50:[{h:"مثال عذراء النشيد"},"كانت نائمة ومسترخية ، وقد تعطرت وتطيبت ، خلعت ثيابها ، وغسلت رجليها ، ونامت . وصوت حبيبها يسعى إليها من بعيد ، « ظافراً على الجبال ، قافزاً على التلال ، يقول لها : « قومى يا حبيبتى وجميلتى وتعالى » (نش ٢ : ١٠) . بل هو يقف على بابها يقرع : « افتحى لى يا أختى ، يا حبيبتى يا حمامتى يا كاملتى ، لأن رأسى قد امتلأ من الطل ، وقصصى من ندى الليل » (نش ٥ : ٢) ... أى سعى من الرب أكثر من هذا ، وأى انتظار فى الحاح على طلب النفس ، أكثر من رأسه تمتلىء من ندى الليل . إنه درس فى الرجاء لكل نفس نائمة ، لا تطلب الله ، بل تهتم بذاتها وراحتها ... !",{h:"الله هو الواقف على الباب ، وهو الذى يقرع ... !"},"وهو الذى يقول فى كل حين « هأنذا واقف على الباب وأقرع . إن سمع أحد صوتى وفتح الباب ، أدخل إليه وأتعشى معه وهو معى » (رؤ ٣ : ١٠) . إن الله الطيب الذى لم يتركنا حتى فى تكاسلنا واهمالنا وبعدنا عنه فى حياة التراخى واللامبالاة ، وإنما بلغ من فرط محبته انه :",{h:"سعى حتى إلى العشارين والخطاة ، وجلس على موائدهم ، ليجذبهم إليه !"},"إنه يسعى إلى كل هؤلاء ، وينزل إليهم لكى يرفعهم إليه ، ويقول إن هؤلاء أيضاً أبناء لإبراهيم (لو ١٩ : ٩) . بل إن من أجل الآيات فى هذا المجال ، هى قوله عن نفسه إنه : « جاء يطلب ويخلص ما قد هلك » (لو ١٩ : ١٠) ...","* * *",{h:"وسعى الله لخلاصنا ، ترمز إليه قصة الخليقة :"},"تحكى لنا الآيات الأولى من سفر التكوين أن « الأرض كانت خربة وخالية » وكانت مغمورة بالمياه « وعلى وجه الغمر ظلمة » (تك ١ : ٢) . صورة كئيبة بلا شك . ولكن الله لم يترك الأرض الخربة هكذا ، وإنما « كان روح الله يرف على وجه"],51:["المياه » . ثم قال الله ليكن نور ، فكان نور .. وبدأ الله ينظم هذه الأرض ، ومنحها حياة وجمالاً ، ويخلق فيها الأشجار والأزهار والأطيار ، ووضع قوانين الفلك بما فيه من شمس وقمر ، ونجوم وكواكب .. ثم خلق الإنسان . وصارت الأرض جميلة وعامرة بالحياة ..",{h:"وفى كل هذا يعطى الرب رجاء لكل أرض خربة تغمرها المياه .."},"لا تيأس مهما وصلت المياه إلى نفسك ، فروح الله يرف على وجه المياه . ولا تيأس مهما غمرتك القلمة ، فلا بد سيأتى الوقت الذى يقول فيه الله : ليكن نور ...",{h:"لذلك ليكن لك رجاء مادام الله يسعى بنفسه لخلاصك ."},"* * *",{h:"إن البشرية عاجزة عن تخليص نفسها . وما لا تستطيع أن تفعله من أجل خلاصها ، يعمله الرب من أجلها .."},"أليست هذه هى قصة التجسد والفداء فى صميم مفهومها اللاهوتى : الله بنفسه يسعى لخلاص البشر ، ويقدم لهم الكفارة والفداء . أو ليس هو أيضاً الذى أرسل الأنبياء والرسل لهذا الغرض ، لكى ينادوا داعين الجميع : « اصطلحوا مع الله » (٢كو ٥ : ٢٠) . ومن أجل هذا أيضاً أرسل لنا الوحى الإلهى فى الكتب المقدسة القادرة أن تحكمنا للخلاص (٢تى ٣ : ١٥) .",{h:"زيارات النعمة للجميع"},"إن (زيارات النعمة) تمر على بيوت الجميع ، ولم تغفل أحداً ، بل كل خاطىء كان له نصيب منها ... !","قيل عنه إنه كان « يجول يصنع خيراً » (أع ١٠ : ٣٨) يفتش عن النفوس الضائعة ، مهما عاندت ، ومهما قاومت ، ومهما هربت منه ... ! يظل وراءها حتى يرجعها إليه ، مهما كانت حالتها تدعو إلى اليأس . وهنا نقول قاعدة هامة وهى :"],52:[{h:"إن الله لا ييأس مطلقاً من خلاص الناس ، مهما يئسوا هم ..."},"الله دائماً يعمل ، ويعمل مع الكل . ليس فقط مع المريض روحياً ، وإنما حتى مع الميت الذى قد أنتن (يو ١١ : ٣٩) ، حتى مع اللص فى آخر ساعات حياته على الأرض (لو ٢٣ : ٤٣) ، حتى مع رئيس العشارين ، زكا ... ! ومع السامرية التى عاشت مع خمسة (أزواج) ! ! (يو ٤ : ١٨) .",{h:"وهو يبحث عن هذه المرأة الضائعة ، ويجذبها إلى التوبة ..."},"هو الذى ذهب إلى البئر حيث تستقى . وهو الذى دبر القابلة بحكمته ، ورتب موعد اللقاء .. وهو الذى جرّ الحديث معها ، وكلمها عن الماء الحى ، وهو الذى فتح الموضوع وشجعها على الاعتراف بخطاياها الصعبة حتى لا تخرج ، وقبل منها مجرد الموافقة ولم يبال فى كل ذلك بأن اليهود لا يعاملون السامريين » ، ولا بأن تلاميذه « كانوا يتعجبون من أنه يتكلم مع إمرأة » (يو ٤ : ٩ ، ٢٧) .","* * *","حقاً كما قال القديس يوحنا ذهبى الفم عن محبة الله :",{h:"إن الله يجول ملتمساً سبباً لخلاصنا ، ولو دمعة تسكبها ... يأخذها الله ـ قبل أن يخطفها شيطان المجد الباطل ـ ويجعلها سبباً لخلاصك ... حقاً انه لا يوجد أحن من قلب الله علينا ... أحن منا على أنفسنا ! إنه هو الذى قال : « بسطت يدىّ طول النهار إلى شعب معاند ومقاوم » (رو ١٠ : ٢١ ؛ إش ٦٥ : ٢) حتى إلى هذا الشعب المتمرد السائر وراء أفكاره ، بسط الله يده ، طالباً خلاصه ... ! ولعل هذا يذكرنا بمثل الزارع ."},"* * *","لقد قبل الرب دموع المرأة الخاطئة ، وقال لها مغفورة لكِ خطاياكِ . وقال للمتكئين إن خطاياها الكثيرة قد غفرت لها لأنها أحبت كثيراً . وشرح كيف أنها كانت أفضل من الفريسى ...",{h:"هذه الدموع أمام الله محت كل الماضى الاثيم الذى للمرأة ."},"لم يذكر لها كل خطاياها القديمة ، أمام هذا الإنسحاق الحاضر . حقاً ما أجمل قول الرب عن خطايانا « لا أعود أذكرها » ."],53:[{h:"مثال الزارع"},{h:"الله شبه نفسه بزارع يلقى بذاره فى كل أرض ..."},"لقد ألقى بذاره على الأرض الجيدة فى كل مستوياتها ، التى تنتج ثلاثين كالتى تنتج ستين كالتى تنتج مائة . الكل سعى الرب لتزويده بعمل نعمته ، بتوصيل كلمة الخلاص إليه ... ولكن ماذا عن الأرض المتحجرة ، والأرض المحاطة بالأشواك ؟ كل منها أيضاً زارته النعمة . ولكن « مَنْ له اذنان للسمع فليسمع » (متى ١٣ : ٩) ...",{h:"الله يسعى خلاص الكل . لا يمنع كلمته المحبية عن أحد ..."},"حتى الطريق ، وصلته بذار من الرب ، وكذلك الأرض التى لم يكن لها عمق . فإن كان الله قد عمل فى كل هؤلاء ... فليكن لك رجاء ان الله سيعمل فيك أنت أيضاً ، لكى تثمر . وإن لم تثمر ، هو « ينقب حولك ويضع زبلاً » (لو ١٣ : ٨) ..","هنا ونقول : ما أجمل تلك العبارات المعزية التى نصليها فى القداس الغريغورى « لم تدعنى معوزاً شيئاً من أعمال كرامتك . ربطتنى بكل الأدوية المؤدية إلى الحياة » ...","* * *",{h:"لولا طيبة الله ، ما كان يلقى بذاره حتى وسط الأشواك ..."},"لو أن واحداً منا فى نفس الموقف ، لقال لتلك الأرض : « اتزعى الشوك منك ، لكى ألقى بذارى فيك » ... ولكن الله لم يفعل هكذا ... حقاً إن بعض الأراضى استطاع الشوك أن يخنق زرعها . ولكن الله قادر أن ينقى الشوك من كل أرض . هو نفسه ينظفها « ينقب حولها » ، لأن كثيراً من الأنفس لا تستطيع أن تنزع الشوك من حولها ، وإنما هى تصرخ مع كلمة الوحى قائلة للرب :",{h:"« توبنى فأتوب . لأنك أنت الرب إلهى » (أر ٣١ : ١٨) ."},"وتقول أيضاً مع المرتل : « اغسلنى فأبيض أكثر من الثلج ، انضح علىّ بزوفاك فأطهر » (مز ٥٠) . أنت يارب الذى تغسلنى ، وأنت الذى تطهرنى . وأنا أقول مع ذلك الأبرص « يا سيد ، إن أردت ، تقدر أن تطهرنى » (متى ٨ : ٢) . فيجيب الرب ـ كما قال لذاك ـ أريد فاطهر ..."],54:[{h:"الله يصالحنا معه"},"الله يريد أن يصالحنا ويصلحنا ، بكل الوسائل الممكنة ...","من أجل ذلك أرسل الله الرسل والأنبياء والوحى الإلهى ... ولماذا أرسل كل هؤلاء ؟ يجيب القديس بولس الرسول قائلاً : « الله الذى صالحنا لنفسه بيسوع المسيح ، وأعطانا خدمة المصالحة ... إذن نسعى كسفراء عن المسيح ، كأن الله يعظ بنا . نطلب عن المسيح : تصالحوا مع الله » (٢كو ٥ : ١٨ ، ٢٠) .","* * *",{h:"الله الحنون صالحنا لنفسه ، ولم يحسب لنا خطايانا ..."},"وفى ذلك يقول بولس الرسول أيضاً : « إن الله كان فى المسيح مصالحاً العالم لنفسه ، غير حاسب لهم خطاياهم » (٢كو ٥ : ١٩) . وكما نقول عنه فى خاتمة كل صلاة : « الداعى الكل إلى الخلاص من أجل الموعد بالخيرات المنتظرة » ...","* * *",{h:"والله فى صلحه معنا وفى غفرانه ، يقدّر ضعف طبيعتنا ..."},"يقول المرتل فى المزمور : « كبعد المشرق عن المغرب ، أبعد عنا معاصينا . كما يترأف الأب على البنين ، يترأف الرب على خائفيه » ولماذا ؟ « لأنه يعرف جبلتنا ، يذكر أنتا تراب نحن » (مز ١٠٣ : ١٢ ـ ١٤) ... الله ينزل إلى هذا التراب ، ويقيم صلحاً معنا ، واضعاً فى اعتباره ضعف طبيعتنا .","* * *",{h:"صدقونى ، انه يفعل هذا حتى مع الهاربين منه ... !"},"ذكرنا قبلاً ، كيف سعى الله إلى آدم وهو هارب منه ومختبىء خلف الأشجار (تك ٣ : ٨) . ونضيف مثالاً آخر فى قصة يونان النبى ."],55:[{h:"قصة يونان النبى"},{h:"كان يونان النبى هارباً من الله . وسعى الله لخلاصه ..."},"لم يرفضه الله لأنه هرب منه إلى ترشيش ، مخالفاً أمره فى الذهاب إلى نينوى . ولم يرفضه فى ثانى مرة ، حينما تابت نينوى ورحمها الله ، فاغتاظ يونان ! وإنما عمل الله على مصالحة يونان واقناعه بالصواب الذى اغتاظ منه يونان حتى الموت ! ! (يون ٤ : ٣ ، ٤) . انظر حنو الله على يونان فى حزنه الذى لم يكن يتفق مع مشيئة الله . يقول الكتاب : « فأعد الرب الإله بقطينة ، فارتفعت فوق يونان ، لتكون ظلاً على رأسه لكى يخلصه من غمه » (يون ٤ : ٦) .","* * *","إن سفر يونان يعطينا مثلاً جميلاً عن سعى الله لخلاص البشر :","ما كان أهل نينوى يفكرون فى خلاص أنفسهم .","وما كان بحارة السفينة التى ركبها يونان يسعون إلى خلاصهم .","ولا يونان شعر أنه أخطأ وطلب الخلاص لنفسه !","ولكن الله بنفسه سعى لخلاص كل هؤلاء ، وخلصهم ...","الله هو الذى بدأ . والمبادرة أتت منه . ثم أتت استجابتهم هم لعمله الإلهى ، مباشرة من بحارة السفينة وأهل نينوى ، وبعد اقتناع وبعد وقت من جانب يونان النبى ...","* * *",{h:"اجتذب الله أهل السفينة إليه بخطة بارعة ..."},"بالأمواج التى لطمت السفينة حتى كادت تنكسر ، وبالخوف الذى أصاب البحارة حتى صرخ كل واحد إلى إلهه ، وليس إلى الله الواحد ، ثم بعمل الله فى القرعة التى ألقوها ، وأيضاً باعتراف يونان . ثم يهدوه البحر بعد القاء يونان . ونجحت الخطة الإلهية مع البحارة « فخاف الرجال من الرب خوفاً عظيماً ، وذبحوا"],56:["ذبيحة للرب ، ونذروا نذوراً » (يون ١ : ١٦) .","وكان البحارة قد استخدموا أولاً طرقهم البشرية ، فلم تنجح « إذ طرحوا الامتعة التى فى السفينة ليخففوا عنهم » ولكن « البحر كان يزداد هيجاناً » كذلك فإنهم « جدفوا ليرجعوا السفينة إلى البر فلم يستطيعوا » ولو استطاعوا ما خلصوا إيمانياً . ولكن الله تدخل بطريقته التى أمكنه أن تخلصهم من البحر وتخلصهم من جهة الإيمان . ونجحت خطة الله فى خلاصهم ...","* * *",{h:"واجتذب الرب أهل نينوى ، بالانذار الإلهى ، ومناداة يونان ."},"وما كان أهل نينوى قادرين على خلاص أنفسهم إذ كانوا الميين بعيدين عن الإيمان ، كما انهم كانوا جهلة « لا يعرفون بينهم من شمالهم » (يون ٤ : ١١) . ولكن انذار الله لهم بأن المدينة ستنقلب وتهلك ، اتى بشماره ، فخافوا وتابوا وصاموا . « ورجعوا عن طريقهم الرديئة ، وقبل الله توبتهم » ...","* * *",{h:"وبقى يونان . وخلّصه الله أيضاً ، على دفعتين ..."},"فى المرة الأولى سعى الله لتخليص يونان من عواقب مخالفته وهروبه . واستخدم لذلك الخطر الذى تهدده فى البحر . والذى قابله يونان أولاً بلامبالاة . وكان نائماً حتى فى الوقت الذى صل فيه كل البحارة الاميون ، لدرجة أن رئيس النوتية وبخه قائلاً : « ما لك نائماً ، قم اصرخ إلى إلهك ، عسى أن يفتكر الإله فينا فلا نهلك » (يون ١ : ٦) . ثم أكمل الله خطته الإلهية بأنه « أعد حوتاً عظيماً فابتلع يونان » .","* * *",{h:"وخلص يونان من عصيانه ، وبقى أن يتخلص من محبته لكرامته ."},"وفعل الله ذلك بالشمس التى ضربت رأس يونان فذبل ، واليقطينة التى ظللت عليه ، والدودة التى أكلت اليقطينة ، ثم تفاهم الله معه .","وهكذا استطاع الله أن يخلص يونان ، كما خلص نينوى وأهل السفينة ."],57:["وكان عند هؤلاء جميعاً استجابة لعمل الله فيهم وعمله من أجلهم . ولعل هذا يقودنا إلى نقطة وهى :",{h:"الشركة مع الله"},{h:"الله يعمل لأجلك ، يسعى لخلاصك ، فعليك أن تستجيب ."},"تشترك فى العمل معه . لا تقاوم عمل الروح كما فعل اليهود وآباؤهم (أع ٧ : ٥١) . ولا تفعل أيضاً مثلما فعلت عذراء النشيد ، التى رفضت أن تفتح لحبيبها . فكانت النتيجة أنه ـ بعد طول انتظار ـ « تحول وعبر » . فقالت العروس « نفسى خرجت عندما ادبر . طلبته فما وجدته . دعوته فما أجابنى » (نش ٥ : ٦) .","* * *","شعب موسى ، كان عاجزاً عن أن يخلص نفسه من عبودية فرعون . والله هو الذى سعى إلى خلاصه وخلصه . وكما قال موسى : « الرب يقاتل عنكم وأنتم تصمتون » (خر ١٤ : ١٤) .","ولكن المهم هو أن هذا الشعب استجاب لعمل الله وسار وراءه ، ودخل فى البحر الأحمر حينما شقه الله أمامه .","* * *",{h:"واحترس أن تفعل كما فعل اغريباس وفيلكس والشاب الغنى"},"اغريباس الملك اتته دعوة الله للخلاص . زارته النعمة وتأثر . وقال لبولس الرسول « بقليل تقنعنى أن أصير مسيحياً » (أع ٢٦ : ٢٨) . ومع ذلك لم يخط خطوة إيجابية من جهته ، وانصرف ، ولم يصر مسيحياً .","وفيلكس الوالى زارته النعمة حينما تكلم القديس عن البر والتعفف والدينونة ، فارتعد فيلكس . ولكنه أجّل الموضوع وقال لبولس : « إذهب الآن . ومتى حصل لى وقت استدعيك » (أع ٢٤ : ٢٥) . وهكذا لم يشترك مع عمل الروح ، وجعل الفرصة تفلت من يده !"],58:["وكذلك الشاب الغنى ، كانت له الفرصة أن يسمع كلمة الخلاص من فم المسيح ، ولكنه سمح لشهوة المال أن تقهره « ومضى حزيناً لأنه كان ذا أموال كثيرة » (متى ١٩ : ٢٢) .","* * *","إذن الله يسعى لخلاصك . يبدأ العمل لأجلك . ولكن عليك أنت أن تستجيب أوتشترك معه أو تخضع لعمله . ولقد صدق القديس أوغسطينوس حينما قال :",{h:"[ الله الذى خلقك بدونك ، لا يشاء أن يخلصك بدونك ] ..."},"إذن لا بد أن تشترك فى العمل معه : الروح القدس يعمل فيك ، وأنت تستجيب لعمل الروح . لا تطفىء الروح (١تس ٥ : ١٩) ولا تحزن الروح (أف ٤ : ٣٠) . ولا تقاوم الروح (أع ٧ : ٥١) . وإنما تدخل فى شركة الروح ، بأن تعمل معه . لأن الله لا يريد أن يرغمك على محبته . واعرف أن طول أناة الله ، إنما لكى تقتادك إلى التوبة (رو ٢ : ٤) . فلا تعتمد على طول أناته وعلى محبته وصبره وسعيه إليك ، لكى لا تصل إلى اللامبالاة والتهاون . وهوذا الكتاب يقول : « إن سمعتم صوته ، فلا تقسوا قلوبكم » (عب ٣ : ١٥) .",{h:"بأنواع وطرق شتى"},{h:"إن الله له طرق كثيرة فى اقتياد الناس إلى الخلاص ..."},"البعض يدعوهم إليه . والبعض يتركهم إلى حين ، إلى أن يلهب قلوبهم بالحب والاشتياق إليه . والبعض يجذبهم بالتجارب والضيقات ، مثلما قاد يونان إلى الطاعة بحوت ابتلعه ، واجتذب أهل السفينة إلى الإيمان بإثارة البحر عليهم ثم تهدئته ، والبعض يقودهم بمجرد الانذار مثلما فعل مع أهل نينوى .",{h:"أتشكو من التجارب والضيقات ؟ ربما سيخلصك الرب بالضيقات !"},"ربما أنت من النوع الذى لا يصلح معه سوى هذا الأسلوب ، أو يكون هذا الأسلوب أكثر سرعة فى اجتذابك إلى الله ."],59:["فإن أتتك التجارب ، لا تتضايق . لعلها لخيرك .",{h:"خذ الخير الذى فى التجارب ، ولا تركز على ما فيها من ألم ."},"إن الله لا يحب أن يستخدم العنف معك . ولكن إذا كان هذا العنف ـ فى حدود احتمالك ـ نافعاً لك روحياً ، فلا مانع منه إلى حين ...","ونفس الوضع نقوله من جهة المدة . الله يحددها حسب الصالح ... هناك طعام لا يحتمل سوى ربع ساعة على النار لكى ينضج ، بينما طعام آخر قد يحتاج انضاجه إلى ساعتين أو أكثر ...",{h:"فلا تفقد رجاءك لطول المدة . إن ذلك لخيرك ..."},"* * *",{h:"أما ان كنت ضعيفاً ولا تقدر ، فالله قادر أن يعينك ."},"إن سعى الله لخلاصنا ، ليس معناه أن نأخذ موقفاً سلبياً على طول الخط ، وعمل النعمة لا يساعد على الكسل . فأمامنا قول الرب : « كم مرة أردت ... ولم تريدوا ... » (متى ٢٣ : ٣٧) . قل له : « توبنى فأتوب » « أرددنى فاخلص » ولكن سلّم إرادتك له . وثق انه سيعمل فيك ، وسيقويك ... وسيقودك فى موكب نصرته ، بالطريقة التى تناسب طبيعتك . وعند الله طرق كثيرة ...","* * *",{h:"وإن كان جهدك قليلاً ، كن أميناً فى هذا القليل ."},"إن صاحب الوزنتين سرّ به الله ، وأعطاه نفس الطوبى التى نالها صاحب الخمس وزنات (متى ٢٥ : ٢٣ ، ٢١) . وقال له كما قال لذاك : « ادخل إلى فرح سيدك » . إن الله لا يطالبك بأكثر من جهدك ، ولا يطالبك بأكثر مما يحتمله ضعف طبيعتك . المهم أن تكون أميناً فى القليل الذى عندك .",{h:"وإن كنت لا تملك فى روحياتك حتى القليل ، الله قادر أن يعطيك . وإن كنت غير قادر على الأمانة فى القليل ، قل له اعطنى يارب القدرة والأمانة من عندك ."},"إن الله الذى نفخ فى التراب ، وجعله نفساً حية ، قادر أن ينفخ فيك ، ويجعلك روحاً حية فى ملكوته ...","* * *"],60:[{h:"الفصل الخامس"},{h:"اهتمام الله بالأشياء الصغيرة"},"« انظروا لا تحتقروا أحد هؤلاء الصغار » (متى ١٨ : ١٠)","القيت هذه المحاضرة فى الكاتدرائية الكبرى مساء الجمعة ١٨ / ٨ / ١٩٧٨ ."],61:["كثيراً ما ينظر البعض إلى حياة القديسين ، وإلى القمم العالية التى وصلوا إليها فى حياة الروح ، وإلى عمق الصلة التى عاشوا فيها مع الله ...",{h:"وهنا يشعر الإنسان بصغر نفس ويتساءل : هل يمكن أن أكون مقبولاً أمام الله ، وأنا فى هذا المستوى الضعيف ، وليس لى شىء على الاطلاق مما وصل إليه القديسون ؟ !"},"هل يمكن أن يقبل الله حياتى البسيطة الصغيرة التافهة ... التى إذا قيست بسير القديسين تكون لا شىء .. ؟ !","هنا وأريد أن أحدثكم عن الله ، الذى هو إله الصغار ... الله الذى اهتم بالأشياء الصغيرة جداً ، وجعل لها قيمة كبيرة قدامه ... والذى قيل عنه لتعزيتنا :",{h:"« المقيم المسكين من التراب ، والرافع البائس من المزبلة ، لكى يجلس مع رؤساء شعبه » (مز ١١٣ : ٧ ، ٨) ."},"الله الذى اختار أناساً صغاراً لم تكن لهم قيمة عند الناس ، ولكن الله كان يعرف قيمتهم ، أو هو جعل لهم قيمة . وامتدت يد الله فرفعتهم .","* * *",{h:"١ ـ اختيار الصغار فى السن .."},"وهكذا قال داود عن نفسه : « صغيراً كنت فى اخوتى ، ومحتقراً كنت عند بنى امى » . كان كذلك عند اخوته . ولكن ماذا فعل الله ؟","أخذ داود الصغير من بين الغنم ، وجعله مسيحاً للرب"],62:["عندما دخل صموئيل النبى ليمسح ملكاً من بيت يسى البيتلحمى ، عرض عليه يسى ابناءه الكبار السمان ... عرض عليه اليآب الطويل القامة الحسن المنظر ، فقال الرب قد رفضته . ثم عرض عليه ابيناداب وشمه وباقى السبعة ، فكان النبى يقول عن كل منهم « وهذا أيضاً لم يختره الرب » (١صم ١٦ : ٥ ـ ١٠) ... وأخيراً قال يسى :",{h:"« بقى بعد الصغير . وهوذا يرعى الغنم » (١صم ١٦ : ١١) ."},"نعم هذا الصغير الذى احتقره أبوه ، وتركه مع الغنم دون أن يسمح له بحضور الحفل الذى يشرفه النبى العظيم صموئيل ... هذا الصغير هو الذى اختاره الرب ليكون له مسيحاً ... !","وحلّ روح الرب على داود الصغير من ذلك اليوم فصاعداً ، وصار رجل المزامير ، رجل المزمار والقيثارة والعشرة الأوتار ، وواحداً من أشهر أنبياء العهد القديم . حقاً إن الله لا ينظر إلى الأعمار ولا إلى المنظر الخارجى . وكثيراً ما اختار الصغار .","* * *",{h:"وكما اختار الله داود الصغير ، اختار أيضاً يوسف الصديق صغير اخوته ."},"وجعله ملكاً عليهم جميعاً ، وعلى غيرهم . وأتى اخوته إليه ، وسجدوا عند قدميه وهو صغيرهم .. ! كما جعله أيضاً أباً لفرعون وسيداً لكل بيته ، ومتسلطاً على كل أرض مصر » (تك ٤٥ : ٨) .","* * *",{h:"واختار أيضاً أرمياء النبى الصغير الذى قال : « لا أعرف أن أتكلم لأنى ولد » (أر ١ : ٦) ."},"وقال له الرب : « قبلما صورتك فى البطن عرفتك . وقبلما خرجت من الرحم قدستك . جعلتك نبياً للشعوب ... ها قد جعلتك فى فمك . انظر . قد وكلتك اليوم على الشعوب والممالك ... ها قد جعلتك اليوم مدينة حصينة ، وعمود حديد ، وأسوار نحاس على كل الأرض ، لملوك يهوذا ولرؤسائها ولكهنتها ولشعب الأرض » (أر ١ : ٤ ، ٥ ، ٩ ، ١٠ ، ١٨) .","* * *"],63:[{h:"نجد أن أحب التلاميذ إلى المسيح كان يوحنا أصغرهم سناً ..."},"وهو الذى جعله الرب أحد الأعمدة الثلاثة فى رسله (غل ٢ : ٩) . وأطال عمره أكثر من جميعهم ، وكشف له رؤى السماء ، وجعله كاتب الإنجيل الملوء باللاهوتيات .","ولعل من الصغار الذين أكرمهم الرب القديس مرقس الرسول الذى كتب أول الأناجيل . وكان شاباً صغيراً حدثاً فى فترة كرازة السيد المسيح على الأرض ، وبدأ حياته خادماً مع القديس بولس والقديس بطرس .","وبولس الرسول اختار شاباً صغيراً ليخدم معه ، هو تيموثاوس الذى صار أسقفاً لأفسس ، وقال له : « لا يستهن أحد بحداثتك » (١تى ٤ : ١٢) .","* * *",{h:"ومن الصغار الذين اختارهم الرب القديس العظيم الأنبا بيشوى ."},"اختاره الملاك من بين اخوته ليكون نذيراً للرب ، وكان اتحفهم جسماً ، واضعفهم وأصغرهم . وعرضت أمه على الملاك أن يختار أحد أخوته الأقوياء ليخدم الرب بقوة . ولكن هذا الصغير النحيف الضعيف كان هو الذى اختاره الرب ليكون « الرجل الكامل حبيب المسيح الذى غسل قدمىّ مخلصنا الصالح » ...","لا تقل أنا صغير . فعجيب هو الرب فى اختياره للصغار ..",{h:"القديس أثناسيوس الرسولى كان شاباً صغيراً فى مجمع نيقية ."},"وكان فى هذا المجمع المسكونى العظيم ٣١٨ من أشهر الآباء الأساقفة فى العالم المسيحى . ومن حيث الرتبة كان أثناسيوس مجرد شماس . ومع ذلك وضعه الله فى القمة . واعطاه القوة فى الانتصار على أريوس وفى دحض بدعته ، وفى صياغة قانون الإيمان المسيحى .","وصار هذا الشماس الصغير أعظم اللاهوتيين فى تاريخ الكنيسة ...","وفى تاريخ الرهبنة ، من أشهر الصغار العظام القديس تادرس تلميذ الأنبا باخوميوس ، والقديس يوحنا القصير ، والأنبا ميصائيل السائح ."],64:["لقد سمح أن يكون الشاب الصغير تادرس هو المرشد الروحى فى كل أديرة القديس باخوميوس الكبير ، بل هو الذى أسس كثيراً من هذه الأديرة ، وعين المسئولين فيها ... كذلك اختار الرب شاباً صغيراً آخر ليكون المرشد الروحى فى برية شيهيت ، ذلك هو القديس يوحنا القصير ، الذى قيل عنه أن الأسقيط كله كان معلقاً بأصبعه . وكان الرهبان يجلسون حوله ويستفيدون من تعليمه ... وكان شاباً حدثاً ، ولكن له نعمة أكثر من الشيوخ ! والقديس ميصائيل صار من الآباء السواح وعمره حوالى ١٧ عاماً .","وأول دير فى برية شيهيت « دير البراموس » ، تسمى باسم قديسين شابين ، هما : مكسيموس ودوماديوس ... ومن أشهر السواح القديس الأنبا ميصائيل الذى وصل إلى درجة السياحة وهو فى حوالى السابعة عشر من عمره ...","* * *",{h:"إن الله حينما شاء هزيمة جليات ، هزمه بفتى صغير ."},"فتى لا يعرف أن يلبس ملابس الحرب ، لأنه لم يتعود عليها (١صم ١٧ : ٣٨ ، ٣٩) ، بل استخدم خمس حصوات ملساء من البرية . وهذا الصغير مسحه الرب ملكاً ، دون أخوته السبعة الكبار ، وهكذا غنى داود أغنيته المشهورة « صغيراً كنت فى اخوتى ، ومحتقراً عند بنى أمى ... أخوتى كبار وسمان ... ولكن الله لم يسر بهم » ...","* * *",{h:"« انظروا لا تحتقروا أحد هؤلاء الأصاغر » (متى ١٨ : ١٠) ."},"اهتمام الرب بالأطفال واضح جداً فى الكتاب المقدس ، فهو الذى أقام طفلاً وسط تلاميذه وقال لهم « إن لم ترجعوا وتصيروا مثل الأولاد ، فلن تدخلوا ملكوت الله » (لو ١٨ : ١٦ ، ١٧) . وقال أيضاً « أحمدك أيها الآب ... لأنك أخفيت هذه عن الحكماء والفهماء وأعلنتها للأطفال » (متى ١١ : ٢٥) . وقال « من أعثر أحد هؤلاء الصغار المؤمنين بى ، فخير له أن يعلق فى عنقه حجر الرحى ويغرق فى لجة البحر » (متى ١٨ : ٦) . اعرف باستمرار أن « الحرب للرب » (١صم ١٧ : ٤٧) ، و « ليس للرب مانع أن يخلص بالكثير أو بالقليل » (١صم ١٤ : ٦) .","* * *"],65:[{h:"ما أعظم المواهب الروحية والذهنية والفنية التى وهبها الله للصغار ."},"ما أكثر مواهبه التى وهبها للأطفال والفتيان . داود النبى مثلاً : وهبه الله موهبة الشعر والموسيقى . فكان رجل القيثار والمزمار والعشرة الأوتار ، وهو بعد حدث صغير ، وكان يحسن الضرب على العود ، ويستطيع أن يبعد الروح النجس عن شاول الملك (١صم ١٦ : ٢٣) . وفوق كل ذلك كان رجل حرب وجبار بأس ، وهو بعد فتى صغير ...","* * *",{h:"والقديس الأنبا شنوده رئيس المتوحدين وهبه الله نضوجاً روحياً وهو طفل صغير ."},"فكان يمارس الزهد والصوم والصلاة وهو حدث صغير ... إنها موهبة إلهية تدل على اهتمام الله بالصغار . وهكذا كان أيضاً القديس مرقس المتوحد يصوم إلى الساعة التاسعة وهو طفل .","* * *",{h:"والقديس تكلا هيمانوت وهبه الله صنع المعجزات وهو طفل ."},"إنها ليست أمراً موروثاً ، وإنما هى هبة إلهية ، ومواهب الله ليست قاصرة على الكبار ، وإنما الصغار أيضاً يتمتعون بها . وما أكثرها فى حياة القديسين الذين بدأوا حياتهم صغاراً ، لأن نعمة الله شاءت أن تعمل فيهم فى هذه السن المبكرة ، كما عملت فى ارمياء الذى لم يكن يعرف أن يتكلم لأنه ولد ، وكما عملت فى صموئيل الطفل ، وفى سليمان وهو فتى صغير .","* * *",{h:"ونفس النضوج الروحى كان فى السيدة العذراء وهى طفلة ."},"العمق فى الصلاة ، وفى التأمل ، وفى دراسة الكتاب ... كل ذلك وهى طفلة صغيرة يتيمة تتربى فى الهيكل ... وتسبحتها المشهورة (لو ١ : ٤٦ ـ ٥٥) تدل على مدى حفظها للمزامير وآيات الكتاب ... كل ذلك وهى صغيرة السن . ولكنها نعمة الله العاملة فى هذه الممتلئة نعمة ، التى اختارها الله صغيرة ، ولكن مملوءة بمواهبه ."],66:[{h:"لعل يوحنا المعمدان كان أيضاً أحد الأطفال الموهوبين ."},"والتفسير الوحيد لذلك هو قول الملاك المبشر عنه « ومن بطن أمه يمتلىء من الروح القدس » (لو ١ : ١٥) ... وهكذا كان الروح القدس يعمل فيه وهو بعد فى بطن أمه . لذلك استطاع أن يرتكض وهو جنين فى بطن أمه لما سمعت سلام العذراء ، بل أنه ارتكض بابتهاج ، وهو جنين (لو ١ : ٤١ ـ ٤٤) .","* * *",{h:"إن النضوج المبكر للأطفال الموهوبين ، ليس له تفسير إلا موهبة الله الغنية التى تنسكب على الأطفال بغنى لا يعبر عنه ."},"المهم أن المواهب التى يعطيها الله للأطفال ، تعطيك رجاء ، وتحملك تكرر العبارة التى قالها رب المجد : « أحمدك أيها الآب ... لأنك أخفيت هذه عن الحكماء والفهماء وأعلنتها للأطفال » (متى ١١ : ٢٥) ، « لأنه هكذا صارت المسرة أمامك » .","* * *",{h:"ماذا نقول عن النضوج المبكر لاثناسيوس وطفولته العجيبة ؟"},"ليس شيئاً سوى موهبة الله التى يمنحها للأطفال بغنى مذهل ، قد تحار فيه العقول البشرية ، وتعللها بأسباب شتى . ولكنها تستريح من حيرتها إن وضعت أمامها عبارتين ، هما : « موهبة الله » و « محبة الله للأطفال » .","هو القديس أثناسيوس الذى لقبوه بالرسولى ، وهو أصغر من جلس على كرسى مارمرقس ، وهو أعظم من جلس على هذا الكرسى ، وكان بطلاً عظيماً من أبطال الإيمان ، وهو بعد شاب . وصار بطريركاً وهو فى حوالى الثلاثين . ووضع كتباً عظيمة مثل « تجسد الكلمة » و « الرسالة إلى الوثنيين » وهو شاب صغير .","* * *",{h:"إننا نسعد جداً ، ونمتلىء بالرجاء ، حينما نعرف أن نضوج الأطفال المبكر سببه موهبة الله ومحبته ."},"فالله الذى كان مع هؤلاء الأطفال وأعطاهم بغنى من مواهبه ، هو أيضاً قادر أن يعطينا . المهم أن نتضع ونصير مثل الأطفال حسب وصيته ، ونقف أمامه فارغين","* * *"],67:["نكتفى بهذه الأمثلة عن الصغار فى السن ، ونتكلم عن :","* * *",{h:"٢ ـ الصغار فى العدد"},"لقد اختار الله الصغار فى العدد ، لكى يبارك أو يصنع بهؤلاء الصغار عجباً ...",{h:"اختار الله الخمس خبزات والسمكتين ليصنع معجزة عظيمة ."},"إنه لم يحتقر هذه الكمية الصغيرة ، إنما باركها ، واطعم بها خمسة آلاف من الرجال . وحتى هذا القدر الضئيل كان يحمله غلام صغير (يو ٦ : ٩) . وفى معجزة اشباع الأربعة آلاف من سبعة أرغفة كان معهم « قليل من صغار السمك » (مر ٨ : ٧) . وبهذا القليل ، وبهذه الصغار ، أشبع الرب تلك الآلاف من الناس ..",{h:"واختار الله هذه القلة الضئيلة ، ليعطى رجاء لكل قلة ضئيلة ."},"إن الله يبارك القليل فيصير كثيراً . إن العدد ليس هو المهم ، إنما الأهمية كلها هى فى البركة التى فى هذا العدد . وبهذه البركة يصنع الله عجباً .","ففى خدمتك لا تيأس من قلة مواهبك . وقل له « استخدمنى لاطعامهم كأنني من صغار السمك » .","* * *","انظروا فى مثل الزارع : ماذا قال الرب عن الزرع الذى كان فى الأرض الجيدة ؟ لقد قال :",{h:"« فأعطى ثمراً : بعض مئة ، وآخر ستين ، وآخر ثلاثين » (متى ١٣ : ٨) ."},"نحن نعقل يارب أن الزرع الذى يعطى مئة هو زرع جيد . ولكن هل يقال كذلك عن الذى يعطى ستين ؟ وهل يسمى جيداً من يعطى ثلاثين ؟ ! وهل هذا الانتاج الضئيل هو مقبول عند الله ؟","ولعل الرب يجيب : مادامت الأرض أعطت ثمراً ، إذن فهى أرض جيدة ، حتى إن أعطت ثلاثين ..."],68:["لذلك لا ييأس ولا يفقد الرجاء ، أصحاب الثلاثين . إن الله يقبل هذا القليل منهم ، مادام هذا هو جهدهم . ويبارك الرب هذا الجهد كأنه شىء كثير . انظروا ماذا نقول فى أوشية القرابين :",{h:"أصحاب الكثير وأصحاب القليل . والذين يريدون أن يقدموا وليس لهم ."},"مجرد هذه الرغبة ، حتى من غير عطاء ، هى شىء مقبول عند الله ، الذى لا يحتقر الشىء القليل . عجيب هو الرب فى أحكامه ، وفى قبوله للقليل . يذكرنى هذا بقول أحد القديسين :",{h:"العنقود وإن كانت فيه حبة واحدة ، لا تزال فيه بركة ."},"ونفس هذا المعنى كرره اشعياء النبى (اش ٦٥ : ٨) .","إن الله يعمل فى القليل ، لكى لا نفتخر نحن بقوتنا ، ونظن أننا ننتصر بالكثرة وليس بقوة الله ، فيكسرنا هذا الفكر .","* * *",{h:"وهذا واضح من قصة الحرب التى دخلها جدعون بعدد قليل ..."},"كان جدعون قد جمع من الشعب جيشاً كبيراً من اثنين وثلاثين ألفاً ليحارب المديانيين . ولكن الرب قال له : « هذا الشعب كثير علىّ لأدفع المديانيين بيدهم ، لئلا يفتخر إسرائيل علىّ قائلاً : يدى خلصتنى » (قض ٧ : ٢) . وظل الرب يغربل هذا العدد الكبير حتى وصل إلى ثلاثمائة جندى فقط .","وبارك الله فى هذا العدد القليل ، فانتصر على جيش المديانيين الذى كان منتشراً كالجراد على الأرض . وماذا أيضاً :","* * *",{h:"لما أراد الرب الكرازة بالإنجيل اختار لذلك اثنى عشر رسولاً فقط .."},"واستطاع هؤلاء ـ على الرغم من قلتهم ـ أن يكرزوا بالإنجيل للخليقة كلها (مر ١٦ : ١٥) ـ وإلى أقطار المسكونة بلغت أقوالهم .","فلا تقل مطلقاً نحن قلة . فإن الله يبارك القليل فيصير كثيراً ."],69:["من ثمانية أنفس فقط فى الفلك ، أعاد الله تكوين البشرية من جديد . ولم يختر لغرضه سوى هذا العدد الضئيل ...",{h:"ومن ابن واحد هو اسحق ، استطاع الله أن يأتى بنسل مثل نجوم السماء ورمل البحر فى الكثرة ..."},"وكما تحدثنا عن اهتمام الله بالصغير فى السن ، وبالقليل فى العدد ، ومباركته هذا وذاك ، ننتقل إلى نقطة أخرى وهى :","* * *",{h:"٣ ـ الاهتمام بالقليل فى النوعية"},{h:"لما شاء الله أن يهزم جليات الجبار ، هزمه بحصاة ملساء فى مقلاع صبى صغير هو داود ."},"فلا تفقد أنت رجاءك ، ولا تقل مواهبى قليلة ، وأنا صغير ، ضئيل الشأن ، لست على مستوى قوة مَنْ يغضبوننى . فلتكن حصاة صغيرة فى مقلاع الرب . وليعمل الرب بك عملاً ، مهما كان جهدك قليلاً .",{h:"لأن « الحرب للرب » (١صم ١٧ : ٤٧) . و « ليس لدى الرب مانع عن أن يخلص بالكثير أو بالقليل » (١صم ١٤ : ٦) ."},"* * *","أنظر كيف نشر الله ملكوته على الأرض ... إنه لم يختر لذلك جماعة من الفلاسفة أو العلماء أو الجبابرة ، بل اختار مجموعة من الصيادين البسطاء ، وعمل فيهم وبهم ... وكما قال الرسول :",{h:"« اختار الله جهال العالم ليخزى الحكماء . واختار الله ضعفاء العالم ليخزى الأقوياء . واختار الله أدنياء العالم والمزدرى وغير الموجود ، ليبطل الموجود ، لكى لا يفتخر كل ذى جسد أمامه » (١كو ١ : ٢٧ ـ ٢٩) ."}],70:["ونحن نقف أمام هذه العبارة مبهورين .. ! قد تعبر فى فهمنا كلمة الجهال والضعفاء ... لكن ماذا عن المزدرى وغير الموجود ؟ ! ... ما هذا العجب ؟ كيف يمكن للرب أن يختار المزدرى وغير الموجود ؟ !","لا شك إن هذه العبارة تحيى الرجاء فى نفس كل إنسان ، مهما كان ضعيفاً ، ومهما كان بلا مواهب وبلا امكانيات وبلا قدرات من كل ناحية ...","لذلك إن حوربت باليأس قل له : اعتبرنى يارب ضمن المزدرى وغير الموجود ، ولا تحرمنى من العمل معك ... ليكن لى كيان قدامك ، مع أننى فى نظر نفسى ـ وربما فى نظر الناس ـ مزدرى وغير موجود ...",{h:"ربما يظن البعض أن السيد المسيح لو كان قد جاء فى أيامنا ، لكان يختار أصحاب الشهادات العالية جداً واساتذة البحوث !"},"كلا ، صدقونى ، لأنه لا يحب أن يفتخر كل ذى جسد أمامه ، ولئلا تنسب البشارة إلى العقل البشرى وليس إلى عمل الروح القدس . فلو كان المسيح جاء فى أيامنا ، ما كنت استغرب أن يختار بعضاً من البسطاء كما فعل من قبل ، أو مجموعة من عمال التراحيل ...",{h:"فليس مصدر القوة هو الإنسان وإنما روح الله العامل فيه ."},"والله يحب أن يستخدم الصغار ، لكى لا يفتخروا ، ولكى لا ييأس أحد من عمل الله فيه . فلا يفشل أحد ، ولا تصغر نفس إنسان ما .",{h:"الله نشر الكرازة باثنى عشر رجلاً ، وما كانوا أصحاب مواهب ."},"بل كانت غالبيتهم من الصيادين ، إنما المهم هو عمل الله فيهم . والثالث عشر الذى هو بولس ، لم يعتمد على الثقافة والمواهب ، بل قال لأهل كورنثوس « وأنا لما أتيت إليكم أيها الأخوة ، أتيت ليس بسمو الكلام أو الحكمة » (١كو ٢ : ١) . لماذا ؟ يقول « ليس بحكمة كلام ، لئلا يتعطل صليب المسيح » (١كو ١ : ١٧) ، لئلا تحسب المسيحية فلسفة ، أو ينسب نجاح الكرازة إلى الحكمة وليس إلى عمل النعمة .","* * *"],71:[{h:"إن باب الملكوت مفتوح للكل ، وكذلك باب الخدمة ..."},"ليس فقط للذين يقولون إنهم وصلوا إلى الملء ، ويتكلمون بألسنة ! ! ولهم المواهب ، ويرتعشون فى الصلاة ..! بل إن باب الملكوت مفتوح أيضاً أمام المبتدىء ، الحديث فى العمل الروحى ، الذى لا يعرف أن يتكلم لأنه ولد (أر ١ : ٦) .",{h:"فلا يظن أحد أنه إن لم يصعد إلى القمة فى الروحيات ، فهو لم يصل بعد إلى الله !"},"ولا تحتقروا أمثال هؤلاء الذين لم يصلوا إلى القمم . ولا تصغر نفوس هؤلاء ، فإن الله يعمل فى الكل ، ويستخدم حتى « القليل من صغار السمك » ...","وما أجمل العبارة المعزية التى قالها القديس يوحنا المعمدان :",{h:"إن الله قادر أن يقيم من هذه الحجارة أولاداً لابراهيم (لو ٣ : ٩) ."},"وإلى مَنْ ترمز الحجارة ؟ إلى صم بكم لا يتحدثون ، بلا حركة وبلا حياة ... هؤلاء ، الرب قادر أن يقيم منهم أولاداً لابراهيم .","إذن لا تفقد رجاءك مطلقاً ، مهما كنت بلا حياة . فأنت ولا شك أفضل من حجارة كثيرة ...","* * *","أمامنا مثل آخر واضح فى ميلاد المسيح يدل على اهتمام الله بالصغار :",{h:"لقد وُلد فى مزود بقر ، وليس فى قصر ضخم . وولد فى قرية صغيرة هى بيت لحم ، وليس فى المدينة العظمى أورشليم ."},"واستطاع أن يحوّل المزود إلى مزار عالمى ومقدس من المقدسات الكبرى . أما بيت لحم فقال لها : من الآن قصاعداً « لست الصغرى بين رؤساء يهوذا » (متى ٢ : ٦) . رفعها فوق بلاد كثيرة ، ومنحها قيمة ميلاده فيها .","ولعل هذا يذكرنا بدعوة الرب لجدعون ، الذى شعر بصغر نفس ، لفضالة أصله وبلده ، فقال :"],72:[{h:"ها عشيرتى هى الذلى فى منسى ، وأنا الأصغر فى بيت أبى (قض ٦ : ١٥)"},"ولكن الرب كان يبحث عن هذا الأصغر ، ليظهر مجد الله فيه .","لذلك لا تفقد رجاءك إن كنت صغيراً . إن كنت مزوداً ، أو قرية صغيرة ، أو كنت الأصغر فى بيت أبيك ، أو إن كانت عشيرتك هى الذلىّ بين باقى العشائر ... ! إن الله قادر أن يعمل فيك ، ويرفع شأنك فتصير شيئاً آخر ما كنت تفكر فيه ...",{h:"إنه موقف يشجع الضعفاء والمساكين ، الصغار والأذلاء ..."},"* * *","انظروا فى اختيار موسى النبى ، تروا موقفاً عجيباً ... كان موسى « ثقيل الفم واللسان ... وليس صاحب كلام لا من اليوم ولا أمساً ، ولا قبلاً من أمس » (خر ٤ : ١٠) .",{h:"ومع ذلك اختار الله هذا الثقيل الفم واللسان ليكون كليم الله .."},"لم ينزع منه هذا النقص ، وإنما أرسل له هارون أخاه ، لكى « يكون له فماً » وقال الله لموسى : « وأنا أكون مع فمك ، واعلمك ما تتكلم به » (خر ٤ : ١٦ ، ١٢) . وبهذا الإنسان الثقيل الفم واللسان ، أذل الله فرعون ...",{h:"إن قلة المواهب لا تعوق عمل الله ، ولا تدعو الإنسان أن يفقد الرجاء فى القدرة على القيام بالمسئوليات ... فباستمرار ثق بالله الذى قيل إنه « يعطى المعيى قدرة ، ولعديم القوة يكثر شدة » (اش ٤٠ : ٢٩) ."},"* * *",{h:"إن الله يستخدم الصغار والضعفاء . وهنا نسأل سؤالاً : عندما قاد الله يونان النبى إلى التوبة والصلح معه ، بماذا هداه ؟"},"استخدم الله فى هداية يونان : الدودة ، واليقطينة ، والريح والموج ، وأشعة الشمس . فكانت كل منها تؤدى رسالة إلهية ... (يون ١ ، ٤) ."],73:["اليقطينة التى بنت ليلة كانت ، وبنت ليلة هلكت ، استخدمها الله فى تحقيق مقاصده ، وكذلك الدودة التى لا قيمة لها عند أحد !","قل له : احسبنى يارب دودة ، احسبنى بقطينة ، احسبنى موجة ، احسبنى شعاعاً . فلأكن أى شىء مهما كان تافهاً فى ملكوتك ، ولكن يصنع مشيئتك .","وإن كنت دودة لا تفقد رجاءك ... وإن كنت يقطينة ، لا تصغر نفسك . سيأتى وقت تعطى فيه درساً لنبى كيونان ، ويكتب إسمك فى كتاب الله ... !","* * *",{h:"٤ ـ اهتمام الله بالأشياء الصغيرة"},{h:"اهتم الله بالأطفال ، وتحدث عنهم بكل حب وتقدير .."},"كان يحتضنهم ويعطف عليهم ويقول « دعوا الأولاد يأتون إلىّ ولا تمنعوهم ، لأن لمثل هؤلاء ملكوت السموات » (متى ١٩ : ١٤) .","وأخذ ولداً وأقامه فى الوسط ، وقال لتلاميذه « إن لم ترجعوا وتصيروا مثل الأولاد ، فلن تدخلوا ملكوت السموات . فمن وضع نفسه مثل هذا الولد ، فهو الأعظم فى ملكوت السموات . ومن قبل ولداً واحداً مثل هذا بإسمى فقد قبلنى » (متى ١٨ : ٢ ـ ٥) .",{h:"واهتم بنفسية هؤلاء الصغار ، والبعد عن إعثارهم ، فقال :"},"مَنْ أعثر أحد هؤلاء الصغار المؤمنين بى ، فخير له أن يعلق فى عنقه حجر الرحى ، ويغرق فى لجة البحر » (متى ١٨ : ٦) .","إن الله يهتم بالصغار من كل نوع ، سواء فى سنهم ، أو فى روحياتهم ، أو نوعيتهم عموماً ، أو فى ضآلتهم وضعفهم . رعايته تشمل الكل .","* * *"],74:[{h:"لقد اهتم حتى بالقصبة المرضوضة وبالفتيلة المدخنة .."},"فقيل عنه فى الإنجيل « قصبة مرضوضة لا يقصف ، وفتيلة مدخنة لا يطفىء » (متى ١٢ : ٢٠) . إنه يعطى رجاء لكليهما . فالقصبة المرضوضة قد تربط وقد تعصب . والفتيلة المدخنة قد يرسل لها ريحاً فتشملها .",{h:"والشجرة التى لم تعطِ ثمراً ، أعطاها رجاء وفرصة أخرى ."},"فلما امتدت الفأس لتوضع على رأس هذه الشجرة ، قال فى حنوه « اتركها هذه السنة أيضاً ، حتى انقب حولها وأضع زبلاً . فإن صنعت ثمراً ، وإلا ففيما بعد تقطعها » (لو ١٣ : ٧ ـ ٩) . إنه لم يقطع الرجاء حتى بهذه التى استمرت ثلاث سنوات بلا ثمر .","* * *",{h:"وهو يعطى قيمة حتى للنملة الصغيرة ، ويقدمها درساً للبشر ..."},"فيقول : « اذهب إلى النملة أيها الكسلان . تأمل طرقها وكن حكيماً ... » ونحن نقول : ما هى هذه النملة يارب حتى تخلصها ، وتمنحها هذه الطبيعة النشطة ، وتضرب بها المثل فيما وهبتها إياه من نشاط ومهارة وقدرة ... ؟ ! وكأن الله يجيبنا ويقول :",{h:"لا تظنوا انى فقط خالق التنانين ، وإنما أيضاً خلقت الحشرات والهوام وأرعى هذه وتلك .. وأهتم حتى بالعصافير التى يباع اثنان منها بفلس واحد . وأعطى طعاماً لفراخ الغربان التى تدعونى (مز ١٤٧ : ٩) . عجيب هو الرب الذى يخلق هذه الأشياء الصغيرة ويهتم بها . بل يهتم بالدودة التى تسعى تحت حجر ، وبالزنبقة التى يُلبسها أفضل من سليمان فى كل مجده (متى ٦ : ٢٩) ."},"* * *",{h:"إنه يضرب لنا مثلاً للإيمان وللملكوت السموات بحبة الخردل التى هى أصغر جميع البذور ."},"فيقول يشبه ملكوت السموات حبة خردل أخذها إنسان وزرعها فى حقله ، وهى أصغر جميع البذور . ولكن متى نمت فهى أكبر البقول ، وتصير شجرة ، حتى إن طيور"],75:["السماء تأتى وتتآوى فى أغصانها » (متى ١٣ : ٣١ ـ ٣٢) .","ويقول أيضاً « الحق أقول لكم لو كان لكم إيمان مثل حبة الخردل ، لكنتم تقولون لهذا الجبل انتقل من هنا إلى هناك فينتقل . ولا يكون شىء غير ممكن لكم » (متى ١٧ : ٢٠) .",{h:"إذن لا تفقد رجاءك ولو كان إيمانك صغيراً كحبة الخردل ."},"إنه يمكن أن ينمو ويصير شجرة تتآوى إليها الطيور . والله يقبل هذا الإيمان ويباركه . وأيضاً ...","* * *",{h:"فى الإيمان والملكوت يضرب مثلاً بخميرة صغيرة تخمر العجين كله ."},"فيقول : « يشبه ملكوت السموات خميرة أخذتها إمرأة ووضعتها فى ثلاثة أكيال دقيق حتى اختمر الجميع » (متى ١٣ : ٣٣) . وقد تذكر بولس الرسول هذا المثل فقال لأهل غلاطية : « خميرة صغيرة تخمر العجين كله » (غل ٥ : ٩) .","إذن لا تفقد رجاءك مهما كان إيمانك قليلاً ، ومهما كان عملك ضئيلاً ، فالله يقبل القليل ويباركه ليصير كثيراً .","* * *",{h:"إن الرب قد أعطى فى ملكوته رجاء حتى للعرج والجدع ..."},"فقال لعبده بعد أن أعد الوليمة العظيمة « اخرج عاجلاً إلى شوارع المدينة وأزقتها ، وادخل إلى هنا المساكين والجدع والعرج والعمى » (لو ١٤ : ٢١) .","بل قال أيضاً كوصية : « إذا صنعت ضيافة فادع المساكين الجدع العرج العمى . فيكون لك الطوبى إذ ليس لهم حتى يكافئوك » (لو ١٣ : ١٣) . فإن حوربت بفقد الرجاء ، تذكر هؤلاء الذين ليس لهم ، والذين قبلهم الرب بدون مقابل ...","* * *","هنا ونذكر ملاحظة هامة فى معجزة الخمس خبزات والسمكتين :",{h:"إن الله اهتم بالكسر ، فأمر بجمعها ، وحملها الرسل ـ"}],76:["لعلك تقول ليتنى كنت خبزة فى يد الرب ، يباركها ويطعم بها الألوف ، وهكذا يمكننى أن أصلح لشىء فى الخدمة ! أقول لك : حتى لو لم تكن خبزة ، وكنت مجرد كسرة ملقاة على الأرض لم تجد من يأكلها ... ستسمع قول الرب « اجمعوا الكسر » وسيأتى وقت تستطيع فيه أن تشبع الآخرين .","إذن إن كانت أعمالك الروحية ضعيفة ، قل له فى اتضاع : ادخلنى يارب مع المساكين والجدع والعرج والعمى إلى ملكوتك . وكما اهتممت بجمع الكسر فى معجزة الخمس خبزات والسمكتين ، اعتبرنى أنا أيضاً من هذه الكسر ، ليأخذنى رسلك معهم فى سلالهم ويقفقهم . أنا يارب من هذه الكسر . اجعنى فى سلتك المباركة .","* * *",{h:"لا تظن انه يجب أن تصعد إلى أعلى ، لكى تقابل الله ."},"بل إنك كلما شعرت أنك لا شىء ، ولا استحقاق لك على الاطلاق ، وهبط قلبك إلى أسفل ، فهناك تلتقى بالله .","وهكذا كلما نزلت إلى أسفل صعدت إلى أعلى .",{h:"حقاً إن الإنسان يصعد فى هبوطه ، ويهبط فى صعوده .."},"وقد قال الرب فى ذلك « كل مَنْ يرفع نفسه يتضع . ومَنْ يضع نفسه يرتفع » (لو ١٣ : ١١) .","* * *",{h:"لقد ضرب لنا ثلاثة أمثلة فى اهتمامه بالصغار فى الاصحاح الخاص بقبوله للتائبين وبحثه عنهم (لو ١٥) ."},"رجوع الإبن الضال بانسحاق قلب ، قابله الرب بفرح كبير ، ومكافآت عديدة ... ثم ماذا عن الخروف الضال ؟ من ذا الذى يستطيع أن ينظر إلى حظيرة فيها مائة خروف فيلمح أنها مجرد ٩٩ ، ويبحث عن الواحد الناقص إلى أن يحمله على منكبيه فرحاً ، بل من ذا الذى يهتم بدرهم واحد مفقود ، ويظل يبحث عنه حتى يجده ، ويفرح بوجوده . ألا يعطيك هذا رجاء فى عمل الله من أجلك ! هو يبحث عنك ، إن لم تبحث أنت عنه ..."],77:[{h:"ومن اهتمام الله بالصغار ، اهتمامه بقرية بيت لحم الصغيرة ."},"هذه التى قال لها الوحى الإلهى « وأنت يا بيت لحم ... لست الصغرى بين رؤساء يهوذا ، لتكونى قدساً ومكاناً للميلاد المجيد ... »",{h:"ومن اهتمامه بالصغار ، اختياره لئة المكروهة الضعيفة العينين (تك ٢٩ : ١٧ ، ٣٣) ."},"ليئة هذه التى كانت صغيرة القدر والمكانة بالنسبة إلى أختها راحيل ، هى التى اختارها الرب لتكون أماً ليهوذا سبط الملوك ، وأماً للاوى سبط الكهنوت ، وجدة للمسيح ، فأتى من نسلها ولم يأت من نسل راحيل ...","* * *","بل اختار الرب راحاب الزانية وكذلك ثامار ضمن سلسلة الأنساب ، واختار راعوث الموآبية ضمن سلسلة الأنساب أيضاً (متى ١ : ٣ ، ٥) ... بل اختار مريم المجدلية التى كان عليها سبعة شياطين لتكون مبشرة للرسل (مر ١٦ : ٩ ، ١٠) . بل أنه اختار التراب ليجعل منه صورته ومثاله . فلا تيأس إذن من عمل الله معك واختياره لك ...","* * *",{h:"إنه « المقيم المسكين من التراب ، والرافع البائس من المزبلة ، ليجلسه مع رؤساء شعبه » (مز ١١٢) ."},"إذن الله قادر أن يقيمك مهما كانت حالتك ، بل يرفعك أيضاً لتجلس مع رؤساء شعبه أليس هو الذى لا يحتقر قصبة مرضوضة ، ولا فتيلة مدخنة ، يأمر بتشجيع صغار النفوس ، وأن نسند الضعفاء ونتأنى على الجميع » (اتس ٥ : ١٥) . بل ما أجل قول الكتاب « قوموا الأيادى المسترخية والركب المخلعة » (عب ١٢ : ١٢) ، حتى إن كنت من هذا النوع ، سوف لا يهملك الله ، بل سيرسل لك من يقومك ...","* * *",{h:"بل خذ مثال اهتمامه بالعصفور ، كرمز لاهتمامه بك ."},"إنه يقول « أليس عصفوران يباعان بفلس ، وواحد منهما لا يسقط على الأرض"],78:["بدون أبيكم » (متى ١٠ : ٢٩) فالذى يهتم بالعصفور لا شك يهتم بك أيضاً . ولذلك يقول بعدها مباشرة « وأما أنتم فحتى شعور رؤوسكم جميعها محصاة . فلا تخافوا ، أنتم أفضل من عصافير كثيرة » (متى ١٠ : ٣٠) .","ويعجب الرب بالعصافير فى إيمانها بأن الله يقوتها ويقول فى ذلك « انظروا إلى طيور السماء . إنها لا تزرع ولا تحصد ولا تجمع إلى مخازن . وأبوكم السماوى يقوتها » (متى ٦ : ٢٦) . وهكذا يذكرها ويضرب بها مثلاً لنا ، هى « وفراخ الغربان التى تدعوه » (مز ١٤٧ : ٩) .",{h:"إنه يهتم بالدودة التى تسعى تحت حجر ، ويعطيها طعامها ..."},"كم بالأولى أنت ، يعطيك طعام الروح ، وطعام الجسد أيضاً . أليس الإنسان أفضل من ديدان كثيرة ؟ ! الدودة الصغيرة استخدمها الله ليعطى درساً ليونان النبى ، حينما أعدها الله لتضرب اليقطينة (يون ٤ : ٧) . حسن أن هذه الدودة ذكرت فى الكتاب المقدس ، وهى تؤدى رسالة تقول إلى توبة نبى .","* * *",{h:"٥ ـ الله يهتم بالعمل الصغير"},{h:"إنه لا ينسى كأس الماء البارد الذى تقدمه لعطشان ."},"وقد قال فى ذلك : « مَنْ سقى أحد هؤلاء الصغار كأس ماء بارد فقط باسم تلميذ ، فالحق أقول لكم إنه لا يضيع أجره » (متى ١٠ : ٤٢ ، مر ٩ : ٤١) .","مجرد كأس ماء بارد ، لم تتعب فيه ، ولم يكلفك شيئاً ، هذا لا يضيع أجره . إذن لا تيأس إن كانت أعمالك صغيرة .","* * *",{h:"هناك أعمال أنت تعملها وتنساها لضآلتها . والله لا ينساها . حتى إن كانت فى نظرك بلا قيمة ، هى عند الله لها قيمتها ، ويكافئك عليها فى اليوم الأخير . وحسن انك نسيتها لتأخذ أجرها كاملاً هناك ."}],79:[{h:"لقد مدح الرب ملكة التيمن لمجرد أنها زارت سليمان ."},"وقال : « ملكة التيمن ستقوم فى (يوم) الدين مع هذا الجيل وتدينه ، لأنها أتت من أقاصى الأرض لتسمع حكمة سليمان . وهوذا أعظم من سليمان ههنا » (متى ١٢ : ٤٢) . وبنفس الوضع مدح أرملة صرفة صيدا لأنها استضافت إيليا النبى فى وقت المجاعة (لو ٤ : ٢٥ ، ٢٦) .","* * *",{h:"ولم ينس الرب زيارة نيقوديموس ، مع أنها كانت ليلاً وبخوف ..."},"وسمح أن تسجل هذه الزيارة فى الإنجيل (يو ٣) . وهذا الإيمان الخائف المتخفى الذى كان لنيقوديموس ، باركه الرب ونماه حتى سمح له أن يكفنه . وصار نيقوديموس من مشاهير المسيحيين فيما بعد ، وصار جندياً صالحاً فى ميدان الخدمة ...",{h:"ولم ينس الرب لزكا مجرد صعوده على الجميزة ليراه ."},"ربما لم يحس زكا أن هذا عمل كبير يكافأ عليه من الرب . ولكن الله الذى يهتم بكل عمل مهما كان صغيراً ، وقف ونادى زكا ، ودخل بيته . وقال له : « اليوم حدث خلاص لأهل هذا البيت إذ هو أيضاً ابن لابراهيم » (لو ١٩ : ٩) .","هل كان يخطر على بال زكا أن الرب سيقدر صعوده إلى الجميزة كل هذا التقدير ؟ ! أم هو الرب الذى يهتم بالعمل مهما كان صغيراً .","* * *",{h:"إنه لم ينس مطلقاً عبارة انضاع تلفظت بها المرأة الكنعانية ."},"وطوبها قائلاً لها « عظيم هو إيمانك . ليكن لك كما تريدين وشفى إبنتها فى تلك الساعة » (متى ١٥ : ٢٨) كذلك لم ينس لشعبه مجرد خروجهم وراءه فى البرية (أر ٢ : ٢) ، مع أنهم كانوا فى البرية متذمرين وقساة القلوب . قال لشعبه :",{h:"« قد ذكرت لك ... ذهابك ورائى فى البرية » (أر ٢ : ٢) ."},"قال هذا على الرغم من أخطاء هذا الشعب فى البرية ، وعلى الرغم من تذمره وجحوده .. ولكن مجرد خروجه وراء الرب ليعبده فى البرية لم ينسه الرب"],80:["وقال لتلاميذه : « أنتم الذين ثبتم معى فى تجاربى » (لو ٢٢ : ٢٨) .","مع أن ثباتهم كان ضعيفاً ، هؤلاء الذين لم يستطيعوا أن يسهروا معه ساعة واحدة (متى ٢٦ : ٤٠) والبعض منهم خاف وهرب ... ساعة القبض عليه ، وبطرس انكره ثلاث مرات ، ولم يقف معه عند الصليب سوى واحد فقط هو يوحنا ، إلا أن مجرد سيرهم وراءه وتمسكهم به كمعلم لهم ، كل هذا الذى كان فى نظرهم شيئاً بسيطاً لم ينسه الرب مطلقاً . وبنفس الاسلوب","* * *",{h:"وامتدح الرب الذين جاءوا فى الساعة الحادية عشرة ."},"مع أنهم جاءوا فى آخر النهار ، ولم يعملوا سوى ساعة واحدة . ولكنه مع ذلك قبل منهم هذه الساعة ، وأعطاهم أجرة كالباقين . ولم يرفض هذه الساعة ، بل امتدحها . على الأقل تدل على أنهم مشمرون وقادرون على العمل .","* * *",{h:"وكما قبل القليل من هؤلاء ، قبل أيضاً فلسى الأرملة ."},"ومدحها ، وقال إنها أعطت أكثر من الجميع ، لأنها أعطت من أعوازها (مر ١٢ : ٤٤) . وقد يكون الفلسان شيئاً تافهاً . ولكن الاعطاء من العوز هو شىء كبير جداً عند الله أياً كانت الكمية المعطاة .",{h:"لذلك إن صليت مجرد دقائق من أعوازك ، يقبلها الله ..."},"إن ضاق بك الوقت جداً ، ولم تجد ـ مرغماً ـ سوى لحظات ترفع فيها قلبك إلى الله ، فلا تصغر نفسك ، ولا تفقد رجاءك إذ لم تستطع أن تصل كما ينبغى ! كلا ، إن الله يفحص القلب ويعرف ظروفك ، وهل الأمر عن اهمال أو لا مبالاة أم أنك تعطى من أعوازك فى الوقت .","* * *",{h:"كانت صلاة العشار قصيرة ، جملة واحدة ، وقبلها الله ..."},"وخرج هذا العشار مبرراً دون الفريسى (لو ١٨ : ٩ ـ ١٤) لأنه كان يصلى من"],81:["قلبه ، وبانسحاق ، ولا يجرؤ أن يرفع نظره إلى فوق . فكانت الجملة الواحدة التى قالها ، هى عند الله كثيرة الثمن جداً وغالية عليه . ولم يطالبه الله ببرنامج روحى طويل فوق مستواه ، كما يفعل القديسون . بل اكتفى الرب بانسحاق العشار .","كذلك فإن الله قبل من اللص اليمين توبة قدمها فى آخر ساعات حياته (لو ٢٣ : ٤٣) ورضى من السامرية بما اعتبره اعترافاً ، مع أنها لم تشرح كل شىء ... (يو ٤) . وطوب وكيل الظلم ـ على الرغم من أخطائه ـ لمجرد اهتمامه بمستقبله (لو ١٦ : ٨) .","* * *",{h:"لا تيأس إن كان عملك الروحى ضعيفاً وثمرك قليلاً ."},"لا تقل « لا فائدة . أنا لم أعمل شيئاً » وتيأس بسبب ذلك . واعلم أن الله لا ينسى أى عمل بسيط ، ربما تكون أنت قد عملته ونسيته . إنه لم ينس لملكة التيمن أنها سافرت لتسمع حكمة سليمان . وبسبب هذا العمل الذى يبدو بسيطاً ، قال إنها ستقوم فى يوم الدين وتدين ذلك الجيل (متى ١٢ : ٤٢) .","* * *","انظر فى اهتمام الرب بالعمل الصغير ، قول القديس ذهبى الفم :",{h:"إن الله يجول طالباً سبباً لخلاصك ، ولو دمعة واحدة ..."},"حقاً إن الرب يرضى بالقليل مادام بروح طيبة ، ومادام الإنسان أعجز من أن يفعل أكثر . ويأخذ الرب هذا القليل وينميه ويجعله كثيراً . فلا تيأس ، ولا تجعل الشيطان يحاربك قائلاً : ماذا فعلت ؟ ! هوذا الله يطلب منك الكمال (متى ٥ : ٤٨) !",{h:"نعم إن الله يطلب الكمال ، ولكنه لا يطلب منك أكثر مما تقدر عليه ."},"إنه يضع فى حسابه لك : امكانياتك وظروفك . وهو يقبل منك التدرج ... المهم أن تكون سائراً فى الطريق ، وليس أن تكون وصلت إلى نهايته . وهو يعطيك فرصة ويطيل أناته عليك ، لكى يقودك إلى التوبة .",{h:"ولكن طول أناة الله لا تجعلنا نتهاون ونتكاسل !"},"وثمرنا القليل لا يعنى أن نرضى به ونكتفى ! كلا ، وإنما نجاهد وننمو ، ولكن فى رجاء ، غير يائسين ، بل طالبين من الله أن يقوى ضعفنا ، ويمنحنا النعمة والمعونة لكى نعمل فى كل حين ما يرضيه ..."],82:[{h:"الفصل السادس"},{h:"الله حنون عطوف"}],83:["فى الإنسان قسوة ، أما الله ففيه حنو ورفق ، ولذلك عندما خُير داود النبى بين ثلاث عقوبات قال عبارته الشهيرة « أقع فى يد الله ، ولا أقع فى يد إنسان ، لأن مراحم الله واسعة » (٢صم ٢٤ : ١٤) وهكذا نرى أن أيوب الصديق لما وقع فى أيدى أصحابه الثلاثة ، اشبعوه مذمة واتهاماً ، حتى قال لهم « حتى متى تعذبون نفسى وتسحقوننى بالكلام ؟ ! هذه عشر مرات اخزيتمونى » (أى ١٩ : ٢ ، ٣) أما الله فهو رؤوف ومتحنن ، ومن أمثلة تحننه .","* * *",{h:"أعطانا وصايا فى مستوى احتمالنا"},"تدرج معنا تدرجاً كبيراً من وصايا العهد القديم إلى كمال العهد الجديد . وقد لام الكتبة والفريسيين لأنهم يحملون الناس أثقالاً عسرة الحمل ، وهم لا يريدون أن يحركوها باصابعهم وقال لهم إنهم فى ذلك قد اغلقوا أبواب الملكوت ، فما دخلوا ولا جعلوا الداخلين يدخلون (متى ٢٣ : ٤ ، ١٣) .","وهكذا نرى تلاميذ الرب فى أول مجمع لهم فى أورشليم الخاص بقبول الأمم ، يقولون « لا يثقل على الراجعين إلى الله من الأمم ، بل يرسل إليهم أن يمتنعوا عن نجاسات الأصنام والزنى والمخنوق والدم » (أع ١٥ : ١٩ ، ٢٠) والقديس بولس الرسول يقول لأهل كورنثوس :",{h:"« سقيتكم لبناً لا طعاماً ، لأنكم لم تكونوا بعد تستطيعون » (١كو ٣ : ٢) ."},"ومن رأفة الله وعطفه ، أنه حينما يعطى وصية ، يعطى معها قوة لتنفيذها ، فترافقنا نعمته لكيما نستطيع ويعطينا روحه القدوس ليعمل فينا ، لكى نستطيع أن نعمل .","والله فى رأفته يتراءف على خليقته كلها ، ليس الإنسان فحسب ، بل حتى الحيوان والطبيعة ."],84:[{h:"حنو الله ورأفته على الحيوان"},"إن الله الذى منح الإنسان راحة فى السبت ، اعطى ذلك للحيوان أيضاً ، فقال « وأما اليوم السابع فسبت للرب إلهك ... لا تعمل فيه عملاً ما ، أنت وابنك وابنتك وعبدك وأمتك ، وثورك وحمارك وكل بهائمك » (تث ٥ : ١٤) .","* * *",{h:"ولم يهتم فقط براحة الحيوان بل براحة الأرض أيضاً ."},"فقال : ست سنين تزرع أرضك وتجمع غلتها ... وأما فى السابعة فتريحها وتتركها » (خر ٢٣ : ١٠ ، ١١ ؛ لا ٢٥ : ٣ ـ ٥) . وعلى الرغم من التشديد فى حفظ السبت ، وعدم العمل فيه ، قال الرب « من منكم يسقط حماره أو ثوره فى بئر ، ولا ينشله حالاً فى يوم السبت ؟ ! » (لو ١٤ : ٥) وقال أيضاً « من منكم له خروف واحد . فإن سقط هذا فى السبت فى حفرة ، أفما يمسكه ويقيمه ؟ ! » (متى ١٢ : ١) وقال كذلك لمن لامه على ابراء المرأة المنحنية فى يوم السبت ، « يا مرائى ، ألا يحل كل واحد منكم فى السبت ثوره أو حماره من المذود ويمضى به ويسقيه » (لو ١٣ : ١٥) .",{h:"هكذا جعل انقاذ أو إطعام ثور أو حمار أو خروف استثناء واجباً من وصية عدم العمل فى السبت ."},"ومن شفقته على الحيوان أيضاً قال « لا تطبخ جدياً بلبن أمه » (خر ٢٣ : ١٩ ؛ تث ١٤ : ٢١) وقال أيضاً « لا تكم ثوراً دراساً » (١كو ٩ : ٩) . وحتى الآن الثور أثناء الدراسة لا يكمم ، بل يمد فمه ويأكل كيفما يشاء ، ومن اهتمام الله بالعطف على الحيوان ، قال أيضاً :",{h:"« لا تحرث على ثور وحمار معاً » (تث ٢٢ : ١٠) ."},"ذلك لأنهما ليسا بقوة واحدة فإن اسرع الثور سيرهق الحمار والله يشفق على هذا الحمار من الارهاق . وهكذا عندما دخل السيد المسيح إلى أورشليم ركب على أتان وجحش إبن أتان (متى ٢١ : ٥) حتى يريحهما فى الطريق ، إذ يستبدلهما ، فيركب"],85:["على الواحد ويريح الآخر وظهرت شفقة الرب على الحيوان باشفاقه على حمار بلعام وتوبيخه بلعام على ضرب حماره ظلماً » (عد ٢٢ : ٣٢) .","* * *",{h:"وظهرت شفقة الرب حتى على العصافير : يحميها ويقيتها ."},"وهكذا يقول « أليس عصفوران يباعان بفلس ، وواحد منهما لا يسقط على الأرض بدون أبيكم ؟ » (متى ١٠ : ٢٩) أى بدون سماح منه لا يسقط عصفور ... ويقول أيضاً « انظروا إلى طيور السماء ، إنها لا تزرع ولا تحصد ولا تجمع إلى مخازن ، وأبوكم السماوى يقوتها » (متى ٦ : ٢٦) وليست هى فقط ، بل يقول المزمور :",{h:"« يعطى البهائم طعامها ، وفراخ الغربان التى تدعوه » (مز ١٤٧ : ٩) ."},"حتى فراخ الغربان يارب ؟ ! نعم . فالغربان أيضاً ذكرها الكتاب ، وكانت لها رسالة ! إيليا النبى فى وقت المجاعة ، كانت الغربان تأتيه بطعام (١مل ١٧ : ٤ ـ ٦) وهكذا كان يحدث مع الأنبا بولا السائح ، وكما اهتم الرب بالطيور ، والعصافير والبهائم « اهتم أيضاً بالخروف الضال وبحث عنه حتى وجده » (لو ١٥) .",{h:"واهتم الله بالحيوانات وبالطيور فى فلك أبينا نوح !"},"ادخلها جميعها فى الفلك ، ولم يهمل أحداً منها حتى الحشرات والهوام ، استبقى لها حياة لتعيش ، وكان أبونا نوح يقدم لها الطعام كل يوم ... إن فى ذلك لعجباً ... أقصد هذا العطف العجيب .","* * *",{h:"وكما يشفق الله على الحيوان فيمنحه حماية من الطبيعة ومن الافتراس ."},"الدب القطبى ، أو الثعلب القطبى ، يعيش الواحد منهما فى جو بارد جداً ، لذلك يمنحه الله فراء ثميناً لتدفئته ، تشتهيه النساء الثريات ، وتدفع فى شرائه ثمناً وفيراً ، أما حيوانات البلاد الحارة فلا تحتاج إلى فراء فيعفيها الرب منه ... ولأن الجمل يعيش فى الصحراء ، لذلك يعطيه الله قوة عجيبة يتحمل بها العطش والجوع ، ويعطى نفس القوة على الاحتمال للنخلة فى الصحراء .","* * *"],86:[{h:"وكما يعطى الحيوانات المفترسة مخالب وأنياب لتعيش كذلك يعطى الحيوانات الضعيفة وسيلة للهرب ."},"الأسد أقوى من الغزال ، يستطيع أن يفترسه . ولكن الرب يعطى الغزال قوة عجيبة فى الجرى ، يمكنه أن يهرب من الأسد ، كذلك الكلب يستطيع أن يفترس القط . ولكن الرب يعطى القط القدرة التى يمكنه بها القفز على الأشجار والجدران فينجو من الكلب ... وبنفس الطريقة يعطى العصافير خاصية الطيران فتنجو ، كما يعطى الفأر القدرة على الحفر والاختباء ، فينجو ... ما أعجب شفقة الله .","* * *","أنظروا جمال الصوت الذى يعطيه الرب للبلابل وللطيور المفردة ... انظروا جمال الشكل الذى يعطيه الرب للطاووس ، بل للفراشة ، أنظروا جمال الرائحة التى يعطيها الرب للورود والفل والياسمين ، والأزهار العطرة . تأملوا القدرات العجيبة التى يعطيها الله للنحلة فى صنع بيوتها بهندسة دقيقة ، وفى صنع الشهد من الرحيق ، بل فى صنع غذاء الملكات ، كل ذلك الذى يأخذه البشر منها طعاماً ودواء ... بل تأملوا النملة فى نشاطها وحركتها الدائبة ... إن الله يعطى خليقته ما يكون أمثولة أمام الإنسان يشتهى أن يحاكيها .",{h:"وإن كان هذا عطف الله على مخلوقاته ، فكم بالأولى على الإنسان ."},{h:"حنو الله الفائق على الإنسان"},{h:"يكفى أن الله أوجده بطبيعة ممتازة : له عقل وروح وارادة ."},"له العقل الذى استطاع أن يصل إلى الاختراع ، ويصنع الأقمار الصناعية وسفن الفضاء ويصل إلى القمر ، ويمشى فى الجو فى مناطق انعدام الوزن ... وأعطاه الارادة الحرة التى يمكنه بها أن يفعل ما يشاء ... وأعطاه الذكاء لكى يفهم ... ولم يشأ الله أن ينزع الذكاء حتى من الأشرار الذين يعصونه ... وفوق المواهب الطبيعية ، أعطى الله"],87:["لبعض البشر مواهب فائقة للطبيعة وقدرة على صنع المعجزات ، بقوة منه ... ما أعجب ما قيل إن الإنسان خلق على صورة الله ومثاله (تك ١) .","* * *",{h:"ومنح الله للإنسان الخلود والحياة الأبدية ."},"منحه أن تكون له حياة دائمة فى ملكوته بعد قيامة الجسد من الموت ، ووعده بالنعيم الأبدى فى عشرة الله وملائكته ، فى أورشليم السمائية « مسكن الله مع الناس » (رؤ ٢١ : ٣) . وقال للأبرار « حيث أكون أنا ، تكونون أنتم أيضاً » (يو ١٣ : ٤) بل وعد الذين يحبونه بأن يتمتعوا بحياة عجيبة فى الأبدية ، يكفى أنها قيل عنها « ما لم تره عين ، ولم تسمع به أذن ، ولم يخطر على بال إنسان ، ما أعده الله للذين يحبونه » (١كو ٢ : ٩) .","* * *",{h:"ومن محبة الله للبشر أنه دعاهم ابناءه :"},"وفى هذا يقول القديس يوحنا الرسول « انظروا أية محبة أعطانا الآب ، أن ندعى أولاد الله » (١يو ٣ : ١) . وأعطانا أن نصل له قائلين « أبانا الذى فى السموات » (متى ٦) بل أنه يقول « لا أعود أسميكم عبيداً ... بل سميتكم أحباء » (يو ١٥ : ١٥) .",{h:"وهكذا جعل الله الرابطة التى تربطنا به هى رابطة الحب ."},"وقيل إنه « أحب خاصته الذين فى العالم ، أحبهم حتى المنتهى » (يو ١٣ : ١) . وشبه هذا الحب بمحبة الآب لبنيه ، وهكذا قال داود النبى فى المزمور : « كما يترأف الآب على البنين ، يترأف الرب على خائفيه » (مز ١٠٣ : ١٣) بل وصل الحب إلى أن لقبنا الله بعروس له ، ووصف حبه لنا بطريقة رمزية فى سفر نشيد الأناشيد .","* * *",{h:"ووصلت محبة الله للإنسان إلى حد البذل والفداء ..."},"« هكذا أحب الله العالم حتى بذل إبنه الوحيد ، لكى لا يهلك كل من يؤمن به ، بل تكون له الحياة الأبدية » (يو ٣ : ١٦) وقال السيد المسيح « أنتم أحبائى إن فعلتم"],88:["ما أوصيتكم به » ، « ليس لأحد حب أعظم من هذا ، أن يضع أحد نفسه لأجل أحبائه » (يو ١٥ : ١٤ ، ١٣) وبسبب هذا الحب والبذل والفداء ، كان التجسد واخلاء الذات (فى ٢ : ٧) وقيل عنه فى فدائه لنا « كلنا كغنم ضللنا ، ملنا كل واحد إلى طريقه . والرب وضع عليه إثم جميعنا » (اش ٥٣ : ٦) .","* * *",{h:"ومن محبة الله لنا ... أعطانا طريق التوبة لمغفرة الخطايا ."},"فلم يمسكنا فى خطايانا ليعاقبنا عليها ، إنما فتح لنا طريقاً للخلاص بالتوبة . وقيل فى الكتاب : « إن الله أعطى الأمم أيضاً التوبة للحياة » (أع ١١ : ١٨) بل قال أيضاً : « هكذا يكون فرح فى السماء بخاطىء واحد يتوب أكثر من تسعة وتسعين باراً لا يحتاجون إلى توبة ... إن الله يتوبنا فنتوب » (ار ٣١ : ١٨) بل « يقودنا فى موكب نصرته » (٢كو ٢ : ١٤) .","* * *",{h:"ومن عطف الله على الإنسان أنه منحه الوحى الإلهى ."},"وهكذا « كلم الله الآباء بالأنبياء بأنواع وطرق شتى » (عب ١ : ١) ومنح البشرية وصاياه وتكلم مع موسى النبى فماً لأذن كما تكلم أيضاً مع ابراهيم ... وأعطانا الله الشريعة المكتوبة « تكلم بها أناس الله القديسون مسوقين من الروح القدس » (٢بط ١ : ٢١) . وهكذا علمنا الرب طرقه ، وفهمنا سبله وأنار بصائرنا حتى لا نضل الطريق .","* * *",{h:"بل جعل الله روحه فينا ... وجعلنا مسكناً لروحه القدوس ."},"وفى هذا يقول القديس بولس الرسول « أما تعلمون أنكم هيكل الله ، وروح الله يسكن فيكم » (١كو ٣ : ١٦) . وبحلول روح الله على الناس وفى الناس صار روح الله يعمل فيهم ، وصارت لهم ثمار الروح (غل ١٥ : ٢٢ ، ٢٣) وصارت لهم أيضاً مواهب الروح المتعددة (١كو ١٢) والدخول فى شركة الروح القدس (٢كو ١٣ : ١٤) بل صاروا « شركاء الطبيعة الإلهية » (٢بط ١ : ٤) أى يشتركون معها فى عمل"],89:["الخلاص ... شركاء فى العمل ، وليس فى الجوهر أو الطبيعة طبعاً .","* * *",{h:"ومن عطف الله على الإنسان أن منحه البركة والنعمة ."},"وبركات الله لا تحصى ، أما نعمته فهى موضوع طويل ، قد احدثكم عنه باستفاضة فيما بعد . وبدأت بركة الله للإنسان منذ أن خلقه ، وتتابعت البركة على الآباء والأبرار ، بل قيل لأبينا ابراهيم « أباركك ... وتكون بركة » (تك ١٢ : ٢) وهكذا سمعنا عن البركة التى منحها الآباء لأبنائهم ...","* * *",{h:"ومن عطف الله على الإنسان الحفظ والتدبير وخدمة الملائكة ."},"جميل ومعز ما قيل عن الملائكة « أليسوا جميعهم أرواحاً خادمة مرسلة للخدمة لأجل العتيدين أن يرثوا الخلاص » (عب ١ : ١٤) وعمل الملائكة فى انقاذ البشر وفى تبشيرهم لا يدخل تحت حصر ... ومن عطف الله علينا أننا « سنصير كملائكة الله فى السماء » (متى ٢٢ : ٣٠) وتسمى بعض البشر ملائكة (رؤ ٢ ، ٣) مثل يوحنا المعمدان (مر ١ : ٢) وما أجمل ما يقال عن الملاك الحارس .","* * *",{h:"ومن عطف الله أنه معنا فى التجارب ."},"لا يجربنا فوق ما نطيق ، ويعطى مع التجربة الاحتمال ، ويعطى منها المنفذ ، واكاليل وبركات المهم أن نقابل محبة الله وعطفه ، بمحبة ، ولا يقودنا عطفه إلى اللامبالاة ."],90:[{h:"الفصل السابع"},{h:"أحفظك حيثما تذهب وأردك إلى هذه الأرض (تك ٢٨ : ١٥)"},"القيت هذه المحاضرة فى الكاتدرائية الكبرى بالقاهرة مساء الجمعة ٣/٦/١٩٧٧ ."],91:["أريد أن أقرأ لكم عبارة قالها الرب لأبينا يعقوب أبى الآباء ، ونأخذها مجالاً لتأملنا ... قال له الرب :",{h:"« وها أنا معك ، وأحفظك حيثما تذهب » . « وأردك إلى هذه الأرض » . « لأنى لا أتركك ، حتى أفعل ما كلمتك به » (تك ٢٨ : ١٥) ."},"* * *",{h:"١ ـ مَنْ ردهم الرب إلى أرضهم ؟"},"يعقوب أبو الآباء ، كان خارجاً من بيت أبيه ، خائفاً من أخيه عيسو . وكان سائراً فى الطريق ، ولا يعرف ماذا ينتظره . كل ما كان يعرفه ، أنه وضع أمامه نصيحة أمه رفقة التى قالت له : « هوذا عيسو أخوك متسلٍ من جهتك بأنه يقتلك ... قم اهرب إلى أخى لابان إلى حاران ، وأقم عنده أياماً قليلة ، حتى يرتد سخط أخيك ، حتى يرتد غضب أخيك عنك ... » (تك ٢٧ : ٤٣ ـ ٤٥) .","وفيما هو هارب من أخيه المزمع أن يقتله ، طمأنه الرب بقوله : « ها أنا معك ، وأحفظك حيثما تذهب ، وأردك إلى هذه الأرض » .",{h:"إنه حنو من الحفظ الإلهى ."},"إلهنا الحنون الطيب ، يرافق إنساناً فى هربه ، ليحفظه حيثما يذهب ، ويكون معه ، ويرده إلى أرضه .","ويظهر حنو الله وحفظه فى هذه القصة ، مما يأتى :",{h:"كان عمل الله رجاء مقدماً لإنسان ضعيف عاجز :"},"* فأبونا يعقوب ما كان قادراً أن يحمى نفسه . * وكان أضعف من عيسو بكثير ، وعدوه كان قادراً على قتله . * وما كان يعقوب قادراً أن يحفظ نفسه فى الطريق ، ولا أن يرجع بقوته إلى تلك الأرض ... وهنا تدخل الله ، إله الضعفاء ، ليحفظ ويحمى ويرد ...",{h:"هناك عمل إلهى فى حياة كل إنسان .."},"عمل إلهى مصحوب بمواعيد ، تعطى رجاء للنفس المتعبة ...","ونحاول أن نتتبع أمثلة لهذا العمل الإلهى ، وهذا الحفظ الإلهى ، كما يبدو فى قصص الكتاب المقدس .","* * *"],92:["* حينما اُخذ شعب الله مسبياً إلى بابل وإلى آشور ، وكانوا هناك مستعبدين ، أسرى حرب ، عاجزين عن حماية أنفسهم ... وقد ملكتهم الكآبة ، وعلقوا قيثاراتهم على أشجار الصفصاف ، وردوا قول المزمور : « على أنهار بابل هناك جلسنا ، فبكينا حينما تذكرنا صهيون » (مز ١٣٦ : ١) .","هنا تدخل الله ، وهمس فى أذن الشعب بكلمة رجاء ، قال له فيها : « ها أنا معك . وأحفظك حيثما تذهب ، وأردك إلى هذه الأرض » ... وقد كان :",{h:"عادوا من السبى ، وبنوا أسوار أورشليم المهدمة ، وأصلحوا أبوابها المحروقة بالنار ، وردهم الرب إلى تلك الأرض .."},"وقد شرح نحميا فى فرح عظيم هذا الرجوع ، وعمل الله معه فيه . وكما نفذ الله وعده لفرد واحد هو يعقوب ، نفذ أيضاً نفس الوعد لشعب بأكمله ...","* * *",{h:"* هناك شخص آخر ، كانت حالته أسوأ .. هو أبونا آدم :"},"أخطأ أبونا آدم وكسر الوصية . وطرده الرب من الجنة . وقال له بالتعب تأكل من الأرض كل أيامك . ووضع الرب الكاروبيم بلهيب سيف متقلب لحماية شجرة الحياة ، حتى لا يأكل منها آدم ولا حواء . وأغلقت أبواب الفردوس أمامهما (تك ٣) ... وماذا بعد ... ؟"],93:["وسط كل هذا التعب ، ومع هذه العقوبة وهذا الطرد ، كان نفس الوعد الإلهى مقدماً لأبينا آدم « ها أنا معك ، وأحفظك حيثما تذهب ، وأردك إلى هذه الأرض » ...","ومتى رده الرب إلى الفردوس ؟ ... كان ذلك بعد أكثر من خمسة آلاف سنة ؟ ... ليكن ..",{h:"إن وعد الله قائم ، مهما طالت الأيام عليه .."},"لقد مرت آلاف السنوات ، انقضت واختفت . ولكن لم تمر أبداً ولم تختف عن نظر أحد من الآباء ، تلك العبارة المعزية « ها أنا معك ... وأردك إلى هذه الأرض » .",{h:"ورقدوا جميعهم على رجاء ..."},"يرتل كل منهم عبارة المزمور « وأنا أؤمن أنى أعاين خيرات الرب فى أرض الأحياء . انتظر الرب .. » (مز ٢٧ : ١٣) .","إن عقوبة الله لم تستمر ... الله لا يغضب إلى الأبد ، ولا يحقد إلى الدهر (مز ١٠٣ : ٩) . لقد طرد آدم لأنه أخطأ . ولكنه مع الطرد ، أعطاه الوعد بالخلاص ...","وعندما شُمر ربنا يسوع المسيح على الصليب ، وحمل جميع خطايانا ، ودفع الثمن كاملاً للعدل الإلهى ، ماذا حدث ؟",{h:"فتح الرب أبواب الفردوس ، ورد آدم إلى تلك الأرض"},"ورد معه جميع بنيه ، الذين رقدوا على رجاء ، وكذلك اللص اليمين الذى مات على رجاء الوعد الإلهى « اليوم تكون معى فى الفردوس » . ونحن نسبح الرب ونقول له :",{h:"صادقة يارب هى مواعيدك . وحقيقى كل رجاء تقدمه ."},"حينما تقول لأحد « أردك إلى هذه الأرض » فلا بد أن ترده فعلاً .","يعقوب أبو الآباء ، مرت عشرون سنة ، ورددته إلى أرضه . والشعب المسبى ، مرت سبعون سنة ورددته إلى أرضه . وأبونا آدم مرت أكثر من ٥٠٠٠ سنة ورددته إلى الفردوس .",{h:"مواعيد الله لا بد أن تنفذ . لا يهم بعد عشرين سنة ، أو سبعين ، أو خمسة آلاف ..."}],94:["المهم أن يحقق الله وعده ، فى الموعد الذى يحدده وفى محبة وقوة ، يرد تلك النفس التى وعدها وهنا تظهر قوة العمل الإلهى فى حياة الفرد ، أو الجماعة .","ونلاحظ ملاحظتين فى هذه الأمثلة الثلاثة التى ذكرناها .",{h:"هذه الأمثلة الثلاثة تدور حول نفوس كانت عاجزة ، وأيضاً خاطئة ..."},"لا شك أن أبانا يعقوب كان عاجزاً عن رد نفسه إلى أرضه . وكذلك الشعب فى السبى . وأيضاً آدم كان فى عجز مطلق عن رد نفسه إلى الفردوس ...","وهذه الأمثلة الثلاثة ، تدور حول نفوس قد أخطأت إلى الرب ، وبالتالى ما كانت مستحقة لوعوده ...","آدم معروفة خطيئته أو خطاياه العديدة (١) .","ويعقوب خدع أباه الضرير ، وأخذ البركة بالغش والاحتيال ، كما سبق أن أخذ البكورية من أخيه باستغلال اعياء أخيه فى جوعه .","وشعب إسرائيل كان قد وقع فى عبادة الأصنام ، مع خطايا أخرى كثيرة جداً أغضب بها الرب ، حتى دفعه إلى أيدى أعدائه .","* * *",{h:"ولكن الله لا يعطى مواعيده وحفظه للأبرار فقط .."},"حتى الخطاة أيضاً ، لا يسقطهم الرب من رعايته وحفظه ..","ولو كان الخطاة محرومين من عناية الله ، ما خلص أحد ..","ولكن الرب جاء ليطلب ويخلص ما قد هلك ... وقد أعلن أن المرضى هم الذين يحتاجون إلى طبيب ، وليس الأصحاء . وأنه جاء ليدعو الخطاة ـ وليس الأبرار ـ إلى التوبة .",{h:"ما أكثر وعود الرب للخطاة ، يردهم إلى تلك الأرض .."},"(١) انظر كتابنا آدم وحواء ."],95:["حتى فى سقوط الإنسان وفى خطيئته ، يقول له الرب : أنا معك ، وأردك إلى هذه الأرض ، أرض الأحياء .","الخروف الضال الذى خرج من الحظيرة وتاه ، ولم يعرف كيف يعيد نفسه إلى حظيرته ، قال له الرب أيضاً : لا تخف ، أنا معك ، واحفظك حيثما تذهب ، واردك إلى هذه الأرض » . وفعلاً حمله على منكبيه فرحاً ، وأعاده إلى حيث كان .","والدرهم المفقود أيضاً ، ما كان بقدرته أن يرجع إلى جيب صاحبه أو صندوقه . ولكن الرب كان معه ، وحفظه ، ورده إلى تلك الأرض .","* * *",{h:"ولنا مثل آخر ، فى قصة يونان النبى :"},"يونان بخطيئته القى فى البحر ، وبخطيئته ابتلعه الحوت .. وظل فى بطن الحوت . من الذى يقدر أن يخرجه ؟ !","ولكنه فى بطن الحوت ، صلى إلى الرب ، لكى يعود فيرى هيكل قدسه . ونظر الله إليه ، وهو فى جوف الحوت ، وقال له : لا تخف . ها أنا معك ، وأردك إلى تلك الأرض ... وقد كان ..","* * *",{h:"عجيب هو الله . كل شىء مستطاع عنده ..."},"حتى ما يبدو مستحيلاً أو غير مستطاع ، عند الناس ..","* هل كان يجول فى ذهن الثلاثة فتية ، وهم يلقون فى أتون النار ، أنهم سيعودون مرة أخرى إلى بيوتهم ؟ !","ولكن فى وسط النار ، كان الرب يهمس فى أذن كل واحد منهم « أنا معك ... وأردك إلى هذه الأرض » .","* ودانيال أيضاً ، وهو فى جب الأسود ، ملقى فى وسط الأسود الجائعة ، يقول له الرب نفس العبارة ...","وفعلاً ، أخرج الله دانيال سالماً من الجب"],96:["وأخرج الثلاثة فتية من أتون النار كما سبق وأخرج يونان من جوف الحوت وردهم جميعاً ...","حقاً عجيب هو الرب ! عجيب فى محبته ، وفى حفظه ، وعجيب فى عمله الإلهى ! عجيب فى كل مرة قال فيها لأحد أحبائه : أنا معك ، وأردك إلى هذه الأرض .","* * *",{h:"٢ ـ مَنْ ردهم إلى أرض الأحياء بالتوبة"},"* على أن هذه العبارة ، يمكن أن تؤخذ بطريقة روحية أخرى . ولنبدأ ببطرس الرسول كمثال .","إنه بعد أن أنكر السيد المسيح ، بكى بكاء مراً ، إذ شعر أنه قد انفصل عن الرب وعن محبته . وانفصل عن باقى الرسل ، وعن الخدمة وكل العمل الرعوى ...","ولا شك أنه قد رنت فى أذنيه عبارة الرب « من أنكرنى قدام الناس ، ينكر قدام ملائكة الله » (لو ١٢ : ٩) .","ولكن الرب عزاه بنفس العبارة ، التى سبق فعزى بها أبانا يعقوب « أنا معك ... وأردك ... » . ولكن كيف رده الرب ، ومتى ؟ حينما ظهر له ، وقال له فى حنو « ارع غنمى . وارع خرافى » (يو ٢١ : ١٥) ... وحينئذ شعر بطرس أن الرب قد رده إلى جماعة الرسل ..","* * *",{h:"* وداود النبى ، حينما زنى وقتل ، وسقط من ذلك العلو العظيم الذى كان فيه . ولعله كانت فى فكره عبارة أوريجانوس [ أيها البرج العالى ، كيف سقطت ؟ ! ] ."},"وبكى داود بكاء شديد مستمراً ، وفى كل ليلة كان يبلل فراشه بدموعه ، ولكن إلهنا الحنون الطيب ، لم يتركه وحيداً فى أحزانه ، بل قال له : « أنا معك ، وأردك إلى تلك الأرض » ..",{h:"أردك إلى أرض التوبة والنقاوة ، والمصالحة مع الله ."}],97:["واستطاع الرب أن يرد داود ، وأن يغسله فيبيض أكثر من الثلج ، وأن يرد له بهجة خلاصه (مز ٥١ : ١٢) .","* * *",{h:"وبنفس الوضع رد الرب شمشون بعد سقوطه .."},"ولعله بنفس الوضع أيضاً رد سليمان بن داود ، الذى قال له عنه : « إن تعوج أؤدبه ... ولكن رحمتى لا تنزع منه ، كما نزعتها من شاول » (٢صم ٧ : ١٤ ، ١٥) .",{h:"لقد مر وقت على داود ، ظن أنه لا خلاص له .."},"وهكذا صرخ إلى الرب قائلاً : « يارب لماذا كثر الذين يحزنوننى ؟ كثيرون قاموا علىّ . كثيرون يقولون لنفسى : ليس له خلاص بإلهه » (مز ٣) .","وسط هذه الأفكار التى يزرعها الشياطين ، تبدو وعود الرب مملوءة رجاء « أنا معك ، وأردك إلى هذه الأرض » ...","* * *",{h:"هذه العبارة هى أقوى سلاح فى التوبة والرجوع .."},"فمشكلة كثيرين أنهم يظنون بأنهم سيعودون إلى الله ، بقوة إرادتهم ، و بعزيمتهم ، وبصدق عزمهم على الرجوع ، دون أن يضعوا العامل الإلهى فى قصة عودتهم إلى الله !!","كلا ، صدقونى ... فلو كان الإنسان الخاطىء هو الذى يعيد نفسه إلى الله ، ما عاد أحد ...","إنما الإنسان يصرخ إلى الله : توبنى يارب فأتوب ، خلصنى فأخلص (أر ١٧ : ١٤) . والسيد المسيح يقول فى وضوح « بدونى لا تقدرون أن تعملوا شيئاً » (يو ١٥ : ٥) .","إن النفس الميالة إلى الخطية ، وكذلك الإرادة الضعيفة ، وحروب الشياطين ، والمعطلات الروحية ... كل هذه تصد الإنسان ، وتحاول منعه عن الرجوع إلى الله . ولكن نعمة الله تقف أمام هذه المعطلات . وصوت الرب يقول فى حنو للخاطىء : « لا تخف . أنا معك . أحفظك ... وأردك إلى تلك الأرض » ."],98:[{h:"أنا أردك إلى تلك الأرض ، مهما بعدت أنت وضللت ..."},"ومهما كان يبدو لك أو لغيرك ، أن الخلاص بعيد عنك أو مستحيل ، أو أن التوبة غير ممكنة ...",{h:"أنا معك ، عندما يحاربك الشيطان باليأس ..."},"حينما يحاربك عدو الخير ، ويقول لك : إن الخطية لم تعد مجرد عادة عندك ، بل صارت طبيعة فيك . ولن تقدر على تركها . لقد صارت ملتصقة بك . أكثر من التصاق جلدك بلحمك . وصارت تسرى فيك ، أكثر من سريان دمك فى عروقك ... ! !","لا تخف منه ومن أفكاره ، بل قل له فى ثقة :",{h:"أنا لن أرجع إلى الله وحدى ، أو بقوتى ..."},"هو الله الذى سيردنى إليه ، الله الذى قال :","« أنا معك . وأحفظك . وأردك إلى تلك الأرض » .","مادام الله هو الذى يردنى ، إذن فغير المستطاع عند الناس ، هو مستطاع عند الله (مر ١٠ : ٢٧) .",{h:"إن الله يقول لنا فى وعوده :"},"« أعطيكم قلباً جديداً ، وأجعل روحاً جديدة فى داخلكم . وانزع قلب الحجر من لحمكم ، وأعطيكم قلب لحم . وأجعل روحى فى داخلكم . وأجعلكم تسلكون فى طرقى وتحفظون احكامى » (حز ٣٦ : ٢٦ ، ٢٧) .","ويقول أيضاً « هلم نتحاجج ـ يقول الرب ـ إن كانت خطاياكم كالقرمز ، تبيض كالثلج » (إش ١ : ١٨) .","إنه الرب الذى يعمل العمل كله ، ويردنا إليه ...","* * *",{h:"* بأنواع وطرق شتى ، يردنا الرب إلى أرضه :"},"بالحب والحنان ، يردنا الرب إلى تلك الأرض ...","وإلاّ ... فبالشدة والعقوبة يردنا ، أو بالتجارب والضيقات ."],99:["أو بالتعليم والارشاد ... أو بصبره علينا وطول أناته .","بأية الطرق ... بالوسيلة المناسبة لكل نفس على حدة ...","المهم ، أنه يخلص على كل حال قوماً . لأنه يريد أن الجميع يخلصون ، وإلى معرفة الحق يقبلون (١تى ٢ : ٤) . وهو لا يسر بموت الخاطىء ، بل بالحرى أن يرجع ويحيا (حز ٣٣ : ١١) .",{h:"إنه الرب الراعى الشفوق ، الذى يحافظ على غنمه .."},"هو الذى يحنن عليك قلوب الناس ..","وهو الذى من أجلك يربط الشيطان ، فلا يستطيع أن يؤذيك .","هو الذى يحوط حولك من كل ناحية ، فتغنى وتقول :","سبحى الرب يا أورشليم ، سبحى إلهك يا صهيون لأنه قوى مغاليق أبوابك ، وبارك بنيك فيك الذى جعل تخومك فى سلام ، وملأك من شحم الحنطة .","الله هو الذى يقوى مغاليق أبوابك ، ويجعل تخومك فى سلام .",{h:"ضع أمامك باستمرار ، عمل الله فى حياتك ، وليس عملك أنت ."},"ما هو عمل الله فى حياتك ؟ ماذا عن يد الله معك ، عين الله التى صنعت قوة ، التى تمسك بك وتسندك ...","ماذا يفعل الروح القدس من أجلك ؟ وماذا تعمل قوة الله ونعمة ربنا يسوع المسيح من أجلك ؟ ...","ماذا تفعل تشفعات الملائكة وصلوات القديسين من أجلك ؟",{h:"أما عملك أنت ، فله المكان الثانى ، أو المكان الأخير .."},"أما المكان الأول ، والمكانة الأولى ، فلعمل الله ، ولوعد الله القائل : أنا معك . أحفظك ، وأردك إلى تلك الأرض .","* * *",{h:"* ياليت هذا الوعد الإلهى ، يكون ثابتاً فى ذاكرتنا :"},"نضعه أمامنا باستمرار ، فنتعزى ونتقوى ..."],100:["كلما تيأس وتظن أنه لا خلاص ، أو أنه لا فائدة من كل جهادك ، تذكر هذه العبارة الإلهية .",{h:"كلما يضغط عليك الشيطان ، ويقول أنت فى قبضتى !"},"أو يقول لك : لن أتركك ، لقد وقعت فى يدى !","قل له : ما هى قبضتك ؟ وما هى قوتك ؟ ! أين شوكتك يا موت ، أين غلبتك يا هاوية ؟ ! (١كو ١٥ : ٥٥) .","هناك الوعد الإلهى « أنا معك ، وأحفظك حيثما تذهب » .",{h:"حسن يارب قولك . ولكن ماذا عن عيسو أخى ؟"},"عيسو الشديد القاسى الذى يتهددنى ، الذى قال فى غضبه « أقوم واقتل يعقوب أخى » ؟ يرد الرب ويقول :","« لا تخف . أنا معك . أحفظك حيثما تذهب » .","مبارك أنت يارب ، ومبارك هو حنوك . ليكن لى كقولك .","* * *",{h:"ولتكن قوياً من الداخل ، مهما أطبقت حولك الضيقات .."},"مهما تآمر عليك الأشرار ، وماجت حولك المياه الكثيرة ...","مهما تفكرت الشعوب بالباطل ، وتآمر الرؤساء معاً على الرب وعلى مسيحه ، قائلين : لنقطع اغلالهما ، ولنطرح عنا نيرهما .","لا تلتفت إلى كل هذا ، بل ضع أمامك الوعد الإلهى : أنا معك ، واحفظك حيثما تذهب ...",{h:"حقاً ، مادمت أنت يارب معى ، فالدنيا بأسرها كلا شىء قدامى .."},"هذه الدنيا كلها ، كقبض الريح ، كالهباء ، بكل ما فيها من مؤامرات الناس الأشرار ، وكل الهياج ، وصوت المياه الكثيرة ...","بما فيها من مكر لابان خالى ، الذى غير اجرتى عشر مرات (تك ٣١ : ٧) ، وأعطانى ليئة بدلاً من راحيل (تك ٢٩) .."]}},hope_life2:{id:"hope_life2",title:"حياة الرجاء (الجزء الثاني)",author:"قداسة البابا شنوده الثالث",url:"https://drive.google.com/file/d/1Kvvwvn9ubgxOQG9650mIGIsDigMMAJkD/view",file:"حياة الرجاء (الجزء الثاني)",pageOffset:99,review:{status:"needs-review",note:"نُقل الجزء الثاني (ص١٠٠ إلى ص١٨٩ المطبوعة، أي ص١ إلى ص٩٠ بترقيم الملف) بقراءة الصفحات الممسوحة بالنظر؛ حُذفت صفحات قائمة مؤلفات البابا والفهرس والغلاف. الرقم المطبوع = ترقيم الملف + ٩٩. صفحة ٢١ لوحة بلا نص (موضوعة ملاحظة بين قوسين). يحتاج مطابقة نهائية مع الأصل، وبعض الصفحات باهتة الحبر."},chapters:[{title:"تتمة الفصل السابع: أحفظك حيثما تذهب",from:1,to:3},{title:"الفصل الثامن: دون أن نطلب",from:4,to:21},{title:"الفصل التاسع: الله يعمل معنا",from:22,to:29},{title:"الفصل العاشر: انتظر الرب",from:30,to:41},{title:"الفصل الحادي عشر: شجعوا صغار النفوس",from:42,to:51},{title:"الفصل الثاني عشر: الله الذي يبدأ",from:52,to:61},{title:"الفصل الثالث عشر: نهاية أمر خير من بدايته",from:62,to:67},{title:"الفصل الرابع عشر: تستطيع كل شيء",from:68,to:77},{title:"الفصل الخامس عشر: أبصرت بابًا مفتوحًا في السماء",from:78,to:90}],transcribed:[1,90],pages:{1:["مادام وعدك يارب قائماً أمامى ، فلن أخاف البحر الأحمر إن اعترض سبيلى . أنت قادر أن تشقه ، وتمهد لى طريقاً فى داخله ، وتقول لى : امش فيه ، وأنا معك ، أحفظك حيثما تذهب ...","حتى إن وقف أمامى جليات الجبار ، وعيرنى طول النهار ، وهددنى برمحه الذى مثل نول النساجين ، وبسيفه وقوته وشماته .. أقول له : أنت تأتينى بسيف ورمح ، ولكن الحرب للرب . فأنا لذلك آتيك ومعى الوعد الإلهى القائل : أنا معك ، احفظك حيثما تذهب ...","* * *",{h:"لهذا كله ، كان أولاد الله دائماً فرحين ومطمئنين ."},"عاشوا بقلب مطمئن فى جهادهم الروحى ، وفى كل الحروب الروحية . ولم يتعبوا من حروب الشياطين ، ومن صراعهم مع أجناد الشر ، وقوات هذا العالم المظلم . بل تركوا العالم يضطرب حولهم كما يشاء ، وتمسكوا بالوعد الإلهى المليء رجاء وعزاء .","وأنت كذلك فى كل حروبك الروحية ، وفى كل ضيقاتك ومشاكلك ، لا تنظر إلى القوى الخارجية التى تحاربك ، ولا تفكر مَنْ سيقابلك فى الطريق و يعترضك . بل ركز فكرك ومشاعرك فى وعود الله ، التى تشجعك وتسندك وتعزيك .",{h:"كم أنت حنون يا إلهى وطيب ..."},"وكم هى معزية ، وعودك التى ترافق أولادك طوال مسيرتهم فى غربة هذه الحياة ... كم أنت تعمل ، وقوتك الحافظة تعمل ...","مفرحة هى أقوالك ، التى تشجع بها أولادك ...","لقد كثر الأعداء حول داود النبى ، حتى قال ذات مرة : « أكثر من شعر رأسى ، الذين يبغضوننى بلا سبب » (مز ٦٩ : ٤) . ومع ذلك نراه فى كل ضيقاته ، ومع كثرة أعدائه ، ينسى كل هذا ، ويقول للرب : « ناموسك هو درسى » « شهاداتك هى تلاوتى » (مز ١١٩) .","أية شهادات يا داود ، تعزيك فى كل ضيقاتك ؟"],2:["يجيب : إنها كثيرة جداً ، ولكن تكفينى منها واحدة ، وهى قول الرب : « أنا معك ، واحفظك حيثما تذهب ، وأردك إلى هذه الأرض » .","لست أريد سوى هذه العبارة . ومادمت معى أيها الرب الإله ، ومادامت وعودك فى فكرى ، فلن أخاف شراً ، حتى إن سرت فى وادى ظل الموت ، لأنك أنت معى (مز ٢٣) .","ستجدنى كلى شجاعة ، وإيمان ، ورجاء ، بوعدك الإلهى ...","حقاً يارب انك عجيب . وحسن قولك لمنوح والد شمشون .",{h:"« لماذا تسأل عن اسمى ، وهو عجيب » (قض ١٣ : ١٨) ."},"إنه منظر عجيب حقاً ، أن نرى أولاد الله سائرين فى طريق الحياة ، ونرى الله ممسكاً بيد كلٍ منهم ، يقول له وهو يشجعه : ها أنا معك ، واحفظك حيثما تذهب ...","* * *",{h:"إن قوة المسيحية ، فى أنها لا تعتمد على بشرية أو إنسانية أو ذاتية ، إنما تعتمد على الوعد الإلهى : أنا معك ، وأحفظك .."},"احفظك من الشياطين ، ومن الناس الأشرار","واحفظك من نفسك ...","احفظك من كل سوء . احفظ نفسك . احفظ دخولك وخروجك (مز ١٢١) . ويسقط عن يسارك ألوف ، وعن يمينك ربوات . وأما أنت فلا يقتربون إليك (مز ٩١) « لا تخشى من خوف الليل ، ولا من سهم يطير فى النهار ، ولا من أمر يسلك فى الظلمة » (مز ٩١) .","وإن سرت فى وادى ظل الموت ، لا تخاف شراً .","لماذا ؟","لأنى أنا معك ـ بعد الموت ـ أحفظك حيثما تذهب ـ وأردك إلى هذه الأرض ...","هنا ونتأمل :","* * *"],3:[{h:"٣ ـ أردكم إلى الأرض الجديدة"},"إننا من عند الله خرجنا . نفخة قدسية خرجنا من فمه الإلهى ، ودخلنا فى هذا التراب ، وعشنا فيه زمناً .","وجودنا فى التراب ، هو فترة غربة ، يصرخ فيها المرتل قائلاً فى المزمور : « ويل لى ، فإن غربتى قد طالت علىّ » (مز ١٢٠) .","وفيما نحن نعيش فى هذا التراب ، ونتعب من هذا الجسد الترابى ، نصرخ مع القديس بولس الرسول : « مَنْ ينقذنى من جسد هذا الموت » (رو ٧ : ٢٤) ، حينئذ يقول الله لكل منا « ها أنا معك ، واحفظك حيثما تذهب ، وأردك إلى هذه الأرض » .",{h:"وما هى هذه الأرض ؟"},"يقول القديس يوحنا الرائى : « أبصرت وإذا سماء جديدة وأرضاً جديدة . لأن السماء الأولى والأرض الأولى قد مضتا ، والبحر لا يوجد فيما بعد » (رؤ ٢١ : ١) .","وينظر الإنسان مبهوراً إلى هذه الأرض الجديدة ، التى بارئها وصانعها الرب (عب ١١ : ١٠) ... الأرض المقدسة ، التى لا توجد فيها خطية ولا موت . ولا تحتاج إلى شمس ولا إلى قمر ليضيئا فيها ، لأن مجد الرب ينيرها (رؤ ٢١ : ٢٣) .",{h:"ويشير الله إلى هذه الأرض ويقول :"},"« ها أنا معك ، واحفظك حيثما تذهب ، واردك إلى هذه الأرض » ليكن إسم الرب مباركاً ، من الآن وإلى الأبد ، آمين .","* * *"],4:[{h:"الفصل الثامن"},{h:"دون أن نطلب"},"« لأن أباكم السماوى يعلم أنكم تحتاجون إلى هذه كلها » (متى ٦ : ٣٢)","القيت هذه المحاضرة فى الكاتدرائية الكبرى بالقاهرة مساء الجمعة ١٩٨٠/١١/١٤ ."],5:[{h:"١ ـ دون أن نطلب"},"لعل أحدكم يقول : كيف يكون لى رجاء ، وأنا لا أصلى ، ولا أطلب من الله نعمة ولا قوة ولا ملكوت الله وبره ؟ هل مثلى يكون له خلاص ؟ !","نعم ، إن الخلاص للكل . وإن كنت أنت لا تطلب خلاصك ، فإن السيد الرب قد قيل عنه إنه : « جاء لكى يطلب ويخلص ما قد هلك » (لو ١٩ : ١٠) . إنه يسعى لخلاصك أكثر مما تسعى أنت إليه . وهو فى كل مجال يعطينا دون أن نطلب .",{h:"إنه شىء مفرح أن يعطينا الله ما نطلب . ولكن عمق الفرح يظهر فى أنه يعطينا دون أن نطلب ..."},"هنا عمق المحبة الإلهية نحو البشر . بل هنا أبوة الله الحانية ، التى تدرك تماماً ما نحتاجه وما يلزمنا ، فيعطينا من فيض محبته ، وليس لمجرد استجابته لصلواتنا . وسأحاول يا أخوتى أن أثبت لكم هذه الحقيقة بأمثلة عديدة ، حتى يكون لكم عمق الرجاء فى عمل الله لأجلكم .","* * *",{h:"طبيعة الله الذى يعطى دون أن نطلب ، ظهرت واضحة منذ البدء ، من أول قصة الخليقة ، بل فى عملية الخلق ذاتها ."},"إنه منحنا الوجود دون أن نطلب . ومنح الوجود لكل الكائنات التى خلقها العاقلة والجامدة ، التى لها حياة والتى ليس لها ، طبعاً دون أن تطلب . لقد خلقها كلها من العدم . والعدم ليس له كيان لكى يطلب .","* * *"],6:[{h:"وخلقنا الله على صورته ومثاله دون أن نطلب ..."},"حتى على فرض المستحيل ، لو كانت لنا الإمكانية أن نطلب الصورة التى نُخلق عليها ، ما كنا نطلب أن نُخلق على صورة الله ومثاله ، كما شاء الله وتحنن (تك ١ : ٢٦ ، ٢٧) .","* * *",{h:"ودون أن نطلب خلق الله لنا هذه الطبيعة وسلطنا عليها ."},"أعدّ لنا كل شىء قبل أن نكون . بسط لنا السماء سقفاً ، ومهد لنا الأرض كى نمشى عليها . وكما قال القديس غريغوريوس فى قداسه : « لم تدعنى معوزاً شيئاً من أعمال كرامتك ... من أجلى لجمت البحر . من أجلى اخضعت طبيعة الحيوان » ... ومن أجلنا خلق الله الأشجار والأثمار ، والعشب والبقول ، والأزهار والأطيار . ومن أجلنا خلق النور ، ووضع قوانين الفلك ... كل ذلك دون أن نطلب ...","ولم يكتف بهذا وإنما قال لنا فى حنوه « اثمروا واكثروا واملأوا الأرض ، واخضعوها . وتسلطوا على سمك البحر ، وعلى طير السماء ، وعلى كل حيوان يدب على الأرض » (تك ١ : ٢٨) .","* * *",{h:"وخلق الله حواء لآدم دون أن يطلب ..."},"كان يعلم أن آدم لا يجد له معيناً نظيره ، مثلما نجد باقى الكائنات (تك ٢ : ٢٠) . فخلق له حواء . وهكذا أمكن أن تنمو البشرية وتملأ الأرض وتعمرها ، وكل ذلك دون أن نطلب .","* * *",{h:"إن هذه هى طريقة الله كأب محب وكراع صالح ..."},"إنه لا ينتظر من أولاده ومن رعيته ومن خليقته أن يطلبوا فيعطيهم . بل هو من تلقاء ذاته يعرف ما يحتاجون إليه ، فيعطيهم دون أن يطلبوا ...","* * *",{h:"حقاً ماذا يدركه الطفل الصغير من احتياجاته حتى يطلبها ؟ !"}],7:["ولكن أباه يعلم ويفهم ماذا يحتاج إليه ابنه ، فيعطيه دون أن يطلب . هكذا نحن مع أبينا السماوى . إنه أدرى بما نحتاج إليه . وهو كأب حنون يدبر احتياج كل إنسان ، ويدبر احتياجات الأمم والشعوب والجماعات . ولا ينتظر من كل هؤلاء حتى يطلبوا ... وربما لا يطلبون ما يفيدهم وما يفيد غيرهم معهم ! !","* * *",{h:"إن كان الكاهن العادى يفتقد رعيته ، ويوفى احتياجاتها دون أن تطلب ، فكم بالأولى الله رئيس الكهنة الأعظم وراعى الرعاة ؟ !"},"* * *","نعم كم بالأولى الله : « راعى نفوسنا وأسقفها » (١بط ٢ : ٢٥) الذى قال فى حنوه « أنا أرعى غنمى وأربضها ـ يقول السيد الرب ـ وأطلب الضال ، واسترد المطرود ، وأجبر الكسير ، وأعصب الجريح » (حز ٣٤ : ١٥ ، ١٦) .",{h:"إنه يرعى شعبه ، لأن هذا هو عمله ، وهذا هو حبه ."},"ولا ينظر أن ينبهه أحد إلى هذا . إنما نحن نطلب ، لأن هذا الطلب يشعرنا ببنوتنا لله ، ويعمق الدالة بيننا وبينه ، ويعطينا فرحاً داخلياً حينما تستجاب طلبتنا . ولهذا قال الرب لتلاميذه :","« إلى الآن لم تطلبوا شيئاً باسمى . اطلبوا تأخذوا ليكون فرحكم كاملاً » (يو ١٦ : ٢٤) .","* * *",{h:"فرح الاستجابة أو فرح الدالة ، هو الذى يجعلنا نطلب ."},"ولكن الله يمنحنا كل شىء ، حتى دون أن نطلب .","وفى الكتاب المقدس توجد أمثلة عديدة ، تثبت لنا هذه الحقيقة ، فلنحاول أن نتأمل بعضها حتى يكون لنا من ذلك عزاء ، وحتى يكون لنا رجاء باستمرار فى الله الذى يعمل من أجل سعادتنا كأب وراع وخالق ...","* * *",{h:"لوط : أنقذه الله مرتين دون أن يطلب ..."},"مرة حينما سبى مع أهل سادوم فى حرب أربعة ملوك مع خمسة ملوك التى وردت"],8:["فى (تك ١٤) . ودون أن يطلب لوط ، حرك الله قلب إبرآم عمه فجمع رجاله المدربين ، وأنقذه من السبى ، كما أنقذ أهله والمدينة كلها .","والمرة الثانية حينما قرر الله حرق سادوم . ودون أن يطلب لوط أرسل الله له ملاكين ، فأخذاه هو وأسرته بقوة ، وكانا يدفعانه إلى الخارج دفعاً وهو متوان (تك ١٩ : ١٦) . وذلك لشفقة الرب عليه ورغبته الإلهية فى انقاذه .","* * *","إن الله لا ينتظر حتى يصرخ الإنسان إليه ، وإنما ...",{h:"« من أجل شقاء المساكين وتنهد البائسين ، الآن أقوم ـ يقول الرب ـ أصنع الخلاص علانية » (مز ١١) ."},"لم يقل « من أجل صلواتهم وطلباتهم » ، وإنما من أجل حالتهم التى رآها ، من أجل شقائهم وتنهدهم ، يقوم الرب ويصنع الخلاص ، سواء طلبوا أو لم يطلبوا ...","وهكذا فى كل مرة يرى فيها الله مذلة شعبه (خر ٣ : ٧) ، يرسل لهم مخلصاً يخلصهم ، كما فعل أيام موسى ، وأيام جدعون (قض ٦) .","وأنقذ إسحق من الذبح ، فى اللحظة الأخيرة ، والسكين فوق رقبته ، دون أن يطلب (تك ٢٢) ...","* * *",{h:"والله يشبع كل حى من رضاه ، دون أن يطلب ..."},"يرسل المطر والشمس ، ويعطى الطعام لكل ذى جسد ، حتى للملحدين الذين لا يطلبون منه شيئاً . ويعطى جمالاً لزنابق الحقل . إنه يمنح الكل من أجل جوده هو وخيريته ، وليس بسبب استحقاق الناس ولا بسبب طلبهم ..","ونذكر فى هذا المجال بعض النعم العظيمة التى منحها الله :",{h:"٢ ـ نعم الله العظيمة"},"خذوا مثالاً لذلك حبل السيدة العذراء بالله الكلمة ."],9:["هل تظنون أن العذراء كانت تطلب هذا الأمر ؟ ! محال طبعاً ! وما كان حتى يخطر بذهنها ، بل قد تعجبت له وقالت للملاك : « كيف يكون لى هذا ؟ ! ... » (لو ١ : ٣٤) . ولكن الرب منحها هذه النعمة العظيمة ، والقدير صنع بها عظائم (لو ١ : ٤٩) دون أن تطلب ...","* * *",{h:"وعملية الفداء والخلاص على الصليب ، هل طلبها الإنسان ؟ !"},"إن أول وعد بالخلاص إنما منحه الله للإنسان دون أن يطلب ، حينما قال إن نسل المرأة يسحق رأس الحية (تك ٣ : ١٥) . والخلاص بهذا الشكل ، ما كان يفكر أو يحلم به أحد .","هل كان أحد يفكر أن الله يتجسد من أجلنا ، ويخلى ذاته ، ويتألم ويموت على الصليب ؟ ! إن بطرس الرسول لما سمع هذا الكلام من المسيح « ابتدأ ينتهره قائلاً حاشاك يارب » (متى ١٦ : ٢٢) . إذن هذا الأمر ما كان يطلبه أحد . ولكن الله منحنا هذا الخلاص دون أن نطلب ...","* * *",{h:"وتظهر نعمة الله العظيمة فى رفع إيليا وأخنوخ إلى السماء ."},"هل كان أخنوخ يحلم أو يفكر فى أن يكون أول إنسان يرفعه الله إلى السماء ويأخذه إليه ؟ ! (تك ٥ : ٢٤) . أو هل طلب إيليا أن يرفعه الله فى مركبة نارية إلى السماء ؟ ! (٢مل ٢ : ١١) . إنها نعم لا تخطر على بال ، ولذلك من المحال أن يطلبها إنسان . بل يعطيها الله لمن يشاء من أولاده دون أن يطلب ...","* * *",{h:"ونفس الكلام نقوله أيضاً عن النعيم الأبدى ."},"هذا الذى يقول عنه الكتاب : « ما لم تره عين ، ولم تسمع به أذن ، ولم يخطر على بال إنسان ، ما أعده الله للذين يحبونه » (١كو ٢ : ٩) . وطبعاً من المستحيل أن يطلب أحد ما لم يخطر على بال إنسان .","إننا قد نطلب نعيماً . ولكن هذه الصورة بالذات ، هى شىء فوق ما نطلب ، كل ما فيه من تفاصيل لم ترها عين ولم تسمع بها أذن ، ننالها دون أن نطلب ..."],10:[{h:"أكان بولس الرسول يطلب أن يصعد إلى السماء الثالثة ... !"},"هذه التى رأى نفسه فيها ، أفى الجسد ليس يعلم ، أم خارج الجسد ليس يعلم ... أو كان يطلب أن يسمع هناك كلمات لا يُنطق بها ، ولا يسوغ لإنسان أن يتكلم بها ... ؟ ! من يطلب هذا ؟ ! لا أحد طبعاً .","ولكن الله فى كل اعلاناته للبشر ، يعطى دون أن نطلب ...",{h:"٣ ـ الرؤى والظهورات"},"كلها ، قد منحها الله للناس دون أن يطلبوا ...",{h:"أكان أبونا يعقوب يطلب أن يرى سلماً واصلة بين السماء والأرض ؟ !"},"أو كان يطلب أن يرى ملائكة الله صاعدة ونازلة على هذا السلّم ، وصوت الله يناديه ، ويمنحه الطمأنينة والهدوء (تك ٢٨ : ١٢ ـ ١٥) ... كل ذلك بعد أن خدع أباه وأخذ منه البركة بمكر ...",{h:"أليس أن هذه الرؤيا جاءت ليعقوب دون أن يطلب ؟ !"},"* * *",{h:"وبنفس الوضع الرؤيا التى رآها القديس يوحنا فى بطمس"},"إنه لم يطلب مطلقاً فى منفاه أن يرى المسيح ، « ووجهه كالشمس وهى تضىء فى قوتها ، وعيناه كلهيب نار » بل أن يوحنا لم يحتمل هذا المنظر وسقط على الأرض كميت (رؤ ١ : ١٢ ـ ١٧) . وهو لم يطلب أن يرى السماء مفتوحة ، ويرى عرش الله ، والأربعة والعشرين كاهناً ، والأربعة حيوانات غير المتجسدين ، والملائكة السبعة أصحاب الأبواق ، وأصحاب الجامات ، وكل ما هو عتيد أن يكون ...","وكيف يطلب شيئاً من هذا ، وهو لا يعلمه .",{h:"ونفس الكلام ينطبق على رؤى دانيال ، ورؤى حزقيال ، وباقى الرؤى ، وكل الأحلام المقدسة ، وكل النبوءات أيضاً ."}],11:["كل ذلك كشف إلهى ، أو اعلان إلهى ، لا يعقل أن يطلبه أحد ، لأنه طبعاً لا يعرفه ولا يدور بذهنه ...","* * *",{h:"أحلام يوسف الصديق عن مستقبل حياته ، ما كانت تدور بذهنه ."},"ما كان يجول بذهنه ـ وهو صغير اخوته ـ أن يأتى إليه اخوته و يسجدوا له ، وكذلك أبواه . لذلك فالحلم الخاص بسجود الشمس والقمر والأحد عشر كوكباً له ، ما كان يطلبه . ولا الحلم الخاص بسجود حزم اخوته لحزمته (تك ٣٧) . إنها رئاسة يمنحه الله اياها ، ويعلنه بها ، دون أن يطلب .",{h:"ونفس الكلام نقوله عن موهبة يوسف فى تفسير الأحلام ."},"ونقول هذا عن كل موهبة أخرى يمنحها الله لإنسان . مثل موهبة الموسيقى والمزامير التى وهبها الله لداود دون أن يطلب ، ومثل موهبة القوة التى وهبها لشمشون دون أن يطلب . ومثل موهبة الجمال التى وهبها ليوسف (تك ٣٩ : ٦) ولموسى (أع ٧ : ٢٠) ولداود (١صم ١٦ : ١٥) .","* * *",{h:"والأحلام المقدسة هى موهبة أخرى من الله لأسباب روحية ."},"بعضها للمعرفة ، والبعض للإنقاذ ، أو للتعزية ، أو للبشارة ...","حلم ليوسف النجار لينقذه والعائلة من سيف هيرودس (متى ٢ : ١٣) . وحلم آخر للمجوس (متى ٢ : ١٢) . وأحلام لفرعون مصر لكى يستعد للمجاعة المقبلة (تك ٤١ : ١٧ ـ ٣٦) . وحلم لايمالك لانقاذ سارة زوجة إبراهيم (تك ٢٠ : ٣) وحلم لسليمان ليمنحه الرب بركة (١مل ٣ : ٥) . وحلم لنبوخذنصر فسره له دانيال لكى يتضع ويتوب (دا ٤ : ٤ ـ ٢٧) . وأحلام البشارة كثيرة مثل الحلم الذى ظهر ليوسف النجار يبشره بميلاد المسيح .",{h:"كل هذه الأحلام منحها الله لأصحابها دون أن يطلبوا ..."},"وقد قدم الله الرؤى والأحلام كموهبة من روحه القدوس ، مثلها مثل النبوة"],12:["وحينما قال فى سفر يوئيل النبى : « اسكب روحى على كل بشر ، فيتنبأ بنوكم وبناتكم ، ويحلم شيوخكم أحلاماً ، ويرى شبابكم رؤى » (يوء ٢ : ٢٨) وتكررت هذه العبارة فى سفر أعمال الرسل (أع ٢ : ١٧) .","* * *",{h:"النبوءات أيضاً منحها الله للأنبياء دون أن يطلبوا ..."},"ومنحنا أيضاً هذه النبوءات لفائدتنا دون أن نطلب . وكل الذين أرسلهم الرب كأنبياء ، ما كانوا يفكرون أنهم سيصيرون هكذا . وإنما فى لحظة لا يعرفها أحد نسمع مثلاً أنه « كانت كلمة الرب إلى أرمياء النبى » (دا ٩ : ٢) أو صارت كلمة الرب لحزقيال (حز ٣ : ١٦) أو « صارت كلمة الرب إلى صفنيا » (صف ١ : ١) ... كل ذلك دون أن يطلب واحد منهم ...",{h:"واضح أن الرب يكلم البشر متى يشاء ، دون أن يطلبوا ..."},"إنه يقدم الحلم أو الرؤيا أو النبوءة أو الموهبة ، دون أن نطلب ، وربما فى وقت لا نتوقعه على الاطلاق .","وإن كان هذا بصفة عامة ، فبالأكثر مواهب العهد الجديد ..",{h:"٤ ـ مواهب العهد الجديد"},"إنها مواهب ما كان يحلم بها أحد ، وليس فقط أن يطلبها . ولعل فى مقدمة كل هذه المواهب :","التبرير ، والتجديد ، والتقديس . وكل ما ننأله فى المعمودية المقدسة . وكما قال بولس الرسول : « الذين دعاهم ، فهؤلاء بررهم أيضاً . والذين بررهم فهؤلاء مجدهم أيضاً » (رو ٨ : ٣٠) . بل أننا نقف مذهولين أمام قول هذا الرسول :","« لأنكم جميعكم الذين اعتمدتم للمسيح ، قد لبستم المسيح » (غل ٣ : ٢٧) ."],13:["وقوله أيضاً إننا أعضاء جسد المسيح « ألستم تعلمون أن أجسادكم هى أعضاء جسد المسيح » (١كو ٦ : ١٥) . مَنْ ذا الذى يطلب ، أو كان يفكر أن يطلب ، أن يكون جسده هو أعضاء المسيح ، أو أن يلبس المسيح ؟ ! ولكن الله يهبنا دون أن نطلب .","* * *",{h:"بل مَنْ كان يطلب أن يكون جسده هو هيكل الروح القدس ؟ !"},"ولكن هوذا الرسول يؤكد لنا هذه الحقيقة (١كو ٦ : ١٩) ويكررها أيضاً قائلاً : « أما تعلمون أنكم هيكل الله ، وروح الله يسكن فيكم » (١كو ٣ : ١٦) .","إنها حقاً هبة مقدسة معطاة لنا من الله ، دون أن نطلب ...","كذلك أعطانا أن نكون شركاء الروح القدس (١كو ١٣ : ١٤) وشركاء الطبيعة الإلهية (٢كو ١ : ٤) فى العمل .. كل ذلك دون أن نطلب .","* * *",{h:"وموهبة أخرى اعطينا إياها أن نصير أولاد الله ."},"انظروا أية محبة أعطانا الآب ، حتى ندعى أولاد الله » (١يو ٣ : ١) . بل أن ندعى أيضاً اخوة المسيح . واصبح هو لا يستحى أن يدعونا أخوة (عب ٢ : ١١ ، ١٢) .","وهناك موهبة أخرى عظيمة جداً اعطينا إياها فى العهد الجديد وهى :","* * *",{h:"اعطينا أيضاً سر الأفخارستيا ، دون أن نطلب ..."},"فى ساعة لم يكن يتوقعها التلاميذ ، وهبهم المسيح سر الافخارستيا (متى ٢٦ : ٢٦ ـ ٢٨) . أعطانا أن نأكل جسده ونشرب دمه (يو ٦ : ٥٤ ـ ٥٦) لكى نثبت فيه ، وتكون لنا فيه حياة .","أكنا نتخيل أن نطلب طلباً كهذا . ولكنها منحة مجانية فوجئنا بها ، كسائر نعم الله التى يهبها حسب عمق جوده ، دون أن نطلب ."],14:[{h:"٥ ـ كرم الله فى عطاياه"},"اقصى ما كانت تطلبه القديسة اليصابات ، أن يكون لها ابن . ولعلها نسيت هذه الطلبة بعد أن شاخت ، بل أن زوجها زكريا الكاهن استصعب هذا الأمر حينما بشره به الملاك ولم يصدقه (لو ١ : ١٨) كأن أوان طلبه قد فات .",{h:"ولكن الرب وهب زكريا واليصابات ، أعظم من ولدته النساء ."},"وهبهما هذا الأمر العظيم دون أن يطلباه . وهبهما الملاك الذى يهىء الطريق قدامه (مر ١ : ٢) . وهبهما إنساناً يكون عظيماً أمام الرب ، ومن بطن أمه يمتلىء من الروح القدس ، ويتقدم أمام الله بروح إيليا وقوته (لو ١ : ١٥ ـ ١٧) . وهبهما إنساناً قال عنه المسيح إنه « أعظم من نبى » وأنه « لم يقم بين المولودين من النساء أعظم من يوحنا المعمدان » (متى ١١ : ٩ ـ ١١) .","كل هذا ما كانت تطلبه اليصابات ، ولا طلبه زكريا ..","* * *","إنه عظم كرم الله الذى يعطى بسخاء فوق ما نطلب ... مهما طلبنا ستكون طلباتنا أقل بكثير من مستوى جود الله وكرمه ، الذى يعطى بسخاء .","كل ما تطلبه العاقر أن يكون لها ولد . ولكن الرب يقول لها فى سفر إشعياء النبى : « اوسعى مكان خيمتك ، ولتبسط شقق مساكنك ... لأنكِ تمتدين إلى اليمين وإلى اليسار . ويرث نسلكِ أمماً ، ويعمر مدناً خربة » (إش ٥٤ : ١ ـ ٣) . كل هذا يعطيه لها دون أن تطلب .",{h:"ألعل هذا يشير إلى كنيسة الأمم العاقر التى لم تطلبه ؟ !"},"أو ألعل هذا يشير إلى أية أقلية ضئيلة ، أو إلى أية نفس خالية من الفضائل ، عاقراً من جهة عمل الروح فيها ...","* * *"],15:[{h:"ومثال آخر تلك الخاطئة المدوسة بدمها فى سفر حزقيال ."},"لعل كل ما كانت تطلبه أن يغسلها الرب فتطهر ، مجرد أن تتوب ويقبل توبتها . أما الرب الحنون الكريم فى عطاياه فيقبل لها : « حليتكِ بالحلى ... ووضعت تاج جمال على رأسكِ ... وجلتِ جداً جداً فصلحتِ لمملكة . وخرج لك اسم فى الأمم لجمالكِ ، لأنه كان كاملاً ببهائى الذى جعلته عليكِ ، يقول السيد الرب » (حز ١٦ : ١١ ـ ١٤) .",{h:"إنها درس فى الرجاء . التى لم تنتظر شيئاً ، نالت كل شىء ..."},"إن الله لا يستحى من بنوتنا له ، إن وجد نفوسنا مطروحة على الحقل ، مدوسة بدمها ، عارية ومكروهة (حز ١٦ : ٥ ، ٦) . بل انه يغسلنا ويطهرنا ، وينزع عنا عارنا ، فنصير له ، ويطرح علينا بهاءه ... ويضع تاج جمال على رؤوسنا ... حقاً ما أعظم الرجاء بالرب .","* * *","إن الله لا يعطى بمكيال ، بل يسكب سكباً ، بسخاء ، إنه يفتح لنا كوى السماء ، ويفيض علينا بركة لا توسع (ملا ٣ : ١٠) حتى نقول له : كفانا كفانا ... كل هذا دون أن نطلب ...",{h:"إنه لا يغسل الخاطىء فقط ، بل يجعله أبيض من الثلج ..."},"لم يسمح فقط بقبول الابن الضال ، بل اغدق عليه من كرمه وحنوه ، حتى جعل خاتماً فى اصبعه ، وألبسوه الحلة الأولى ، وذبحوا له العجل المسمن ، وأقاموا فرحاً برجوعه (لو ١٥ : ٢٢ ، ٢٣) . أكان هذا الابن يطلب شيئاً من هذا كله ، وهو الذى فكر أن يقول لأبيه : « إجعلنى كأحد أجرائك » (لو ١٥ : ١٩) . ولكن أباه أعطاه كل هذا ، دون أن يطلب ، وفى وقت كان يستحى فيه أن يطلب شيئاً ...","* * *",{h:"إن الله لا يعطى من أجل طلباتنا أو استحقاقاتنا ..."},"إنما يعطى من أجل جوده وكرمه ، ومن أجل احتياجاتنا ."],16:["طبعه هكذا : كريم وحنون وطيب . وطبعه هذا يغرس فى قلوبنا الرجاء مهما كان حالنا ، ومهما كنا غير مستحقين لشىء .","وقصص الكتاب لا تنتهى فى هذا المجال ، إنما نحن نذكر منها هنا مجرد مثال أو بعضاً من مثال ...","* * *",{h:"يوسف الصديق كل ما كان يطلبه أن يخرج من السجن ... ولكن الله جعله الوزير الأول فى مصر والثانى فى المملكة ..."},"أكان يوسف يطلب هذا أو يحلم به ، كلا بلا شك . ولكن الله الحنون يعطى دائماً دون أن نطلب .","وقصة يوسف تبعث الرجاء فى كل قلب ... هذا الذى ساءت حالته إلى أبعد حد ، وبيع كعبد ، والقى فى السجن ، وطالت به المدة فى سجنه ، ولاحقته تهمة هو برىء منها ... ومع ذلك أصلح له الله كل أموره ، وأعطاه ما لم يخطر له على بال ...","* * *",{h:"ويظهر كرم الله وعطاياه فى مواعيده العجيبة ."},"هذا الذى قال : « ها أنا معكم كل الأيام وإلى انقضاء الدهر » (متى ٢٨ : ٢٠) « حيثما اجتمع إثنان أو ثلاثة باسمى ، فهناك أكون فى وسطهم » (متى ١٨ : ٢٠) . إنه يعطينا هذه الوعود المعزية كلها دون أن نطلب .","ونظهر محبة الله لنا أيضاً فى دعوته الإلهية .",{h:"٦ ـ فى الدعوة الإلهية"},"كل تلاميذ المسيح أعطاهم شرف الرسولية ، دون أن يطلبوا ..","أكان يطلب هذا بطرس واندراوس وهما مشغولان بالصيد والشباك ؟ ! أكان يطلب هذا متى وهو فى مكان الجباية ؟ ! ... وهكذا كل الباقين . والرب قد وضح هذا"],17:["الأمر حينما قال لتلاميذه : « لستم أنتم اخترتمونى ، بل أنا اخترتكم ، وأقمتكم لتذهبوا وتأتوا بثمر ، ويدوم ثمركم » (يو ١٥ : ١٦) .","* * *",{h:"وكذلك أيضاً الأنبياء ، نالوا جميعهم النبوة ، دون أن يطلبوا .."},"داود ، وهو صبى صغير يرعى الغنيمات القليلات فى البرية ، أكان يفكر أو يطلب أن يصير مسيح الرب ، وأن يختاره الرب دون أخوته الكبار ودون كل الشعب ليصير نبياً له .. أم اختاره الله دون أن يطلب ؟ !","وكذلك أرمياء الصغير الذى قال : « لا أعرف أن أتكلم لأنى ولد » أكان يحلم أن يصير نبياً للشعوب ، أو كان يطلب هذا . أم أن الله دعاه دون أن يطلب ؟ !","وهكذا إبراهيم أبو الآباء ، الله هو الذى دعاه (تك ١٢ : ١) .","وبالمثل كل الأنبياء ، الذين انطبق عليهم قول الكتاب : « الذين سبق فعرفهم ، سبق فعينهم ... والذين سبق فعينهم ، فهؤلاء دعاهم أيضاً » (رو ٨ : ٢٩ ، ٣٠) هو الله الذى اختار كل هؤلاء دون أن يطلبوا ...","* * *",{h:"ومثال واضح جداً هو شاول الطرسوسى الذى كان يضطهد الكنيسة ."},"أكان شاول يفكر أن يصير رسولاً من رسل المسيح ؟ ! مستحيل . بل إنه كان يقاوم المسيحية بافراط . ومع ذلك نقرأ أن السيد المسيح ظهر له فى طريق دمشق ، ودعاه دون أن يطلب ، واختاره رسولاً للأمم . ونسمع الروح القدس يقول للرسل : « افرزوا لى برنابا وشاول للعمل الذى دعوتهما إليه » (أع ١٣ : ٢) .","* * *",{h:"وبالمثل ، هل كانت راعوث تفكر أن تكون جدة للمسيح ؟ !"},"قطعاً ما كان يخطر لها هذا ببال ، وهى إمرأة أممية غريبة الجنس ! ولكن الله « يدعو الأشياء غير الموجودة كأنها موجودة » (رو ٤ : ١٧) . ألا يعطى هذا الرجاء للناس ؟ !","* * *"],18:[{h:"وأكثر من هذا راحاب . أكانت تطلب أن تصير جدة للمسيح ؟ !"},"لعل اقصى ما كانت تطلبه الأمان لنفسها ولأهلها فى وقت اقتحام أريحا . أما أن تصير ضمن شعب الله ، فقد كان هذا كثيراً عليها جداً . ولكن أن تصير جدة للمسيح ، فهذا لم تطلبه اطلاقاً ، بل لم يخطر على بالها ، ولم تحلم به . ولكن الله الحنون يعطى دون أن نطلب . يحتاج الأمر أن نؤمن بمحبة الله وكرمه واهتمامه بنا",{h:"٧ ـ العطاء والإيمان"},"القديسون لإيمانهم بأن الله يعطى دون أن نطلب ، كانوا يخجلون أن يطلبوا شيئاً . طلبتهم الوحيدة كانت هى الله نفسه ...","ولهذا يقول داود النبى فى صلاته : « طلبت وجهك ، ولوجهك يارب التمس . لا تحجب وجهك عنى » (مز ٢٦) . ويقول فى نفس المزمور « واحدة طلبت من الرب وإياها التمس ، أن أسكن فى بيت الرب كل أيام حياتى ، لكى أنظر نعيم الرب وأتفرس فى هيكله » (مز ٢٦) . أما باقى الأمور فهى بسيطة ، يقضيها لنا الرب دون أن نطلب . أليس هذا هو ما قاله لنا السيد الرب :",{h:"« اطلبوا أولاً ملكوت الله وبره . وهذه كلها تزاد لكم » (متى ٦ : ٣٣) ."},"لم يقل : « وهذه تطلبوها بعد ذلك » وإنما قال : هذه تزاد لكم . أى يعطيها الله لكم دون أن تطلبوا","ولهذا أيضاً كانت كل طلباتنا فى الصلاة الربية ، هى صلوات روحية تتعلق بملكوت الله وبره . والباقى يزاد لنا من الله دون أن نطلب . هو يعلم أننا نحتاج إلى هذه كلها ، فيعطيها لنا من عنده كأب شفوق يعرف احتياجات أولاده ، دون أن يجشمهم الالحاح عليه فى طلبها ..","* * *",{h:"ومع ذلك ، أعطى الله الضعفاء أن يطلبوا ما يشاءون .."},"اطلبوا تجدوا (متى ٧ : ٧) فتفرح قلوبكم بالله الذى يعطى ، ويزداد إيمانكم"],19:["به . وكلما تعمق إيمانكم فى أن الله يعطى كل شىء ، حينئذ سوف لا تطلبون سوى الله وحده ، وملكوته وبره ... « اطلبوا تأخذوا ، لكى يكون فرحكم كاملاً » (يو ١٦ : ٢٤) . وكل طلبة يسمعها الله منكم ، يتقبلها بحنو ، كما من أفواه أطفاله الصغار .","عجيب هو إلهنا الحنون ، المعطى ، والمستجيب لطلبة أولاده .","* * *",{h:"إن الذى يؤمن بالله وعطائه ، ينام فى حضن الله ويستريح .."},"و يكون واثقاً ان الله يدبر له كل شىء ... كما كان بطرس نائماً فى السجن مطمئناً إلى عمل الله من أجله . وكان نومه ثقيلاً لدرجة أن الملاك الذى انقذه ، لكزه أولاً وأيقظه (أع ١٢ : ٧) بينما كان هيرودس مزمعاً أن يقتله (أع ١٢ : ٤) . ومع ذلك نام ، واثقاً أن الله مستيقظ وساهر على خلاصه . ولهذا أيضاً نسمع داود النبى يقول فى المزمور :",{h:"« الرب يرعانى ، فلا يعوزنى شىء » (مز ٢٣ : ١)"},"ومادام لا يعوزه شىء ، إذن فهو لا يطلب ، لأن الله لم يتركه معوزاً شيئاً يطلبه . ولهذا نقول نحن أيضاً فى القداس الغريغورى : « لم تدعنى معوزاً شيئاً من أعمال كرامتك » .","* * *","فإن قال لك الله ماذا تطلب ، أتراك تجيب قائلاً :",{h:"وهل تركت لى شيئاً أطلبه ؟ ! إننى لو قضيت عمرى كله شاكراً ، فلن يكفى . لذلك ان رأيتنى يارب احتاج شيئاً ، اعطنى إياه ."},"إنك اغرقتنى بعطاياك ، وأعطيتنى فوق ما أطلب . ولم تدعنى معوزاً شيئاً ... كما إنك أدرى بما ينقصنى ، إن كان هناك شىء ينقصنى .","عملى الوحيد هو أن أشكر وأن أسبحك على كرمك ، لا أن أطلب ..","* * *","ولعل البعض يسأل : ماذا إذن عن الضيقات ؟ نقول :"],20:[{h:"إن أولاد الله المؤمنين برعايته وعطاياه ، لا ينزعجون ولا يقلقون . ويرون أنه مادام الأمر فى يد الله ، فهذا يكفى ..."},"هذا يكفى لاطمئنانهم وسلامهم . لأنه لا يوجد أحب من الله لهم ، ولا يوجد من هو أكثر عناية منه بهم . ومادام الله قد تسلّم كل أمورهم ، لم يعد لهم شىء يقولونه أو طلب يطلبونه .","* * *",{h:"يكفى للإنسان أن يطلب محبة الله ، لأنه يريد قلوبنا ."},"هو لا يرغمنا على محبته . يريدنا أن نحبه برضانا . وإن احوجتنا المحبة نطلبها منه . وهو يسكبها فى قلوبنا بالروح القدس . إنه لا يرهبنا بلاهوته ، بل يجذبنا بمحبته . ويريدنا أن نبادله حباً بحب ، لذلك يقول : « يا ابنى اعطنى قلبك » (أم ٢٣)",{h:"والذى تملك محبة الله على قلبه ، لا يشتهى فى العالم شيئاً ليطلبه ."},"بل هو يقول للرب : « معك لا أريد شيئاً على الأرض » (مز ٢٣ : ٢٥) ويقول مع القديس بولس الرسول : « خسرت كل الأشياء وأنا أحسبها نفاية ، لكى أربح المسيح وأوجد فيه » (فى ٣ : ٨ ، ٩) .","* * *",{h:"هذا هو طلبك الوحيد : الله ومحبته وملكوته وبره ، وكفى"},"وكل الأمور الأخرى ، يمتلىء قلبك بالرجاء أن الله سيحلها دون أن تطلب . هو يعلم ما تحتاجه ، له المجد فى محبته ورعايته .","* * *"],21:["(صفحة صورة بلا نص في الملف: لوحة تصوّر امرأة تتشبث بالصليب)"],22:[{h:"الفصل التاسع"},{h:"الله يعمل معنا"}],23:[{h:"هناك أسباب جوهرية ... تجعل عمل الله معنا ضرورة :"},"منها قول الرب « ما أضيق الباب وأكرب الطريق الذى يؤدى إلى الحياة ... وقليلون هم الذين يجدونه » (متى ٧ : ١٤) ، فإن كان الأمر هكذا ، فإن العدل الإلهى يقتضى أن توجد معونة إلهية ، يمكننا بها أن نجتاز الباب الضيق . ولهذا يقول الرب :",{h:"« بدونى لا تقدرون أن تفعلوا شيئاً » (يو ١٥ : ٥) :"},"مادام الأمر هكذا ، إذن لابد أن يكون الله معنا فى كل عمل نعمله ، وإلا فإننا سنقف عاجزين تماماً فى كل ما نكافح فيه ارادتنا سواء فى الجهاد ضد الخطية ، أو فى خدمتنا للملكوت ، أو فى اكتساب أية فضيلة .",{h:"وبخاصة لأننا مطالبون بالقداسة ومطالبون أيضاً بالكمال ..."},"إذ يقول الكتاب « نظير القدوس الذى دعاكم ، كونوا أنتم أيضاً قديسين فى كل سيرة لأنه مكتوب : كونوا قديسين لأنى أنا قدوس » (١بط ١ : ١٥ ، ١٦) نحن لسنا مطالبين بالقداسة فقط ، بل أيضاً بالكمال فى هذه القداسة ... وذلك حسب قول الرب « كونوا أنتم كاملين ، كما أن أباكم الذى فى السموات هو كامل » (متى ٥ : ٤٨) ولكى نصل إلى القداسة والكمال ، لابد بالضرورة أن معونة إلهية تحملنا فى الطريق .","* * *",{h:"يضاف إلى هذا أن عدونا قوى ... وحيله كثيرة وماكرة ."},"قال عنه الكتاب « ابليس عدوكم مثل أسد زائر ... فقاوموه راسخين فى الإيمان » (١بط ٥ : ٨ ، ٩) . ترى بأى إيمان نقاومه ؟ بالإيمان أن الله هو الذى يغلبه فى حربه معنا ... كما قيل فى سفر أيوب ، « الله يغلبه لا الإنسان » (أى ٣٢ : ١٣) . نعم ، إننا لا نستطيع بغير عمل الله معنا أن نغلب تلك الخطية التى قيل عنها إنها « طرحت كثيرين جرحى ، وكل قتلاها أقوياء » (أم ٧ : ٢٦) الضرورة إذن تلزم وجود معونة إلهية ."],24:[{h:"لأنه بالإضافة إلى قوة عدونا طبيعتنا أيضاً ضعيفة ."},"وهكذا فإن داود النبى فى حديثه عن عظم مغفرة الله ، يقول « لأنه يعرف جبلتنا ، يذكر أننا تراب نحن » (مز ١٠٣ : ١٤) . ويقول فى كثير من مزاميره « ارحمنى يارب فإنى ضعيف » (مز ٦ : ٢) . هذا الضعف الذى بسببه تحدث الكتاب عن أخطاء الأنبياء ... فإن كان هؤلاء العظام قد اخطأوا ، فماذا يحدث لنا ، إن لم تسندنا معونة الله ... وهى لابد تفعل ، حسب قول الرسول :",{h:"« حيث كثرت الخطية ، ازدادت النعمة جداً » (رو ٥ : ٢٠) ."},"نعم تزداد النعمة ، لكى تنقذنا من هذه الخطية ... وهكذا يصرخ داود النبى إلى الرب و يقول « وأنت يارب عرفت سبلى ... فى الطريق التى اسلك ، اخفوا لى فخاً ... تأملت عن اليمين وأبصرت ، فلم يكن من يعرفنى . ضاع المهرب منى ، وليس من يسأل عن نفسى ... فصرخت إليك يارب وقلت أنت هو رجائى وحظى فى أرض الأحياء ... نجنى من الذين يضطهدوننى لأنهم قد اعتزوا أكثر منى » (مز ١٤١) واحمنى من قوتهم ، ومن ضعفى .","* * *",{h:"ومن ضعف الطبيعة البشرية : الجهل والشهوة وعدم الإرادة ."},"أحياناً يجهل الإنسان الطريق إلى الله ، يجهل الوسيلة التى بها يخلص . لهذا يقول المرتل فى المزمور « علمنى يارب طرقك ... فهمنى سبلك » (مز ١١٩) « علمنى يارب الطريق التى اسلك فيها ... علمنى أن أصنع مشيئتك » (مز ١٤٣) ويتغنى بارشاد الرب فيقول : « الرب صالح ومستقيم ... لذلك يرشد الذين يخطئون فى الطريق ... يعلم الودعاء طرقه » (مز ٢٥) إذن لابد أن يتدخل الله ، ليرشد الإنسان فى الطريق .",{h:"والإنسان قد يعرف ... ومع ذلك إرادته لا تساعده ."},"إما أنه لا يريد الخير ، بسبب محبته للخطية ، وإما أنه يريد ولا يستطيع ... وهكذا يقول القديس بولس الرسول « إنى أعلم أنه ليس ساكناً فىّ ـ أى فى جسدى ـ شىء صالح . لأن الإرادة حاضرة عندى ، وأما أن أفعل الحسنى فلست أجد ، لأنى لست أفعل الصالح الذى أريده ، بل الشر الذى لست أريده فإياه أفعل .. لست بعد أفعله أنا ، بل الخطية الساكنة فىّ » (رو ٧ : ١٨ ـ ٢٠) ."],25:[{h:"لذلك ، فإن الله ـ بنعمته ـ يعمل فى الإنسان ."},"وهكذا فإن القديس بولس الرسول ينسب كل ما يعمله إلى نعمة الله العاملة فيه ، فيقول « ولكن لا أنا ، بل نعمة الله التى معى » ... « ولكن بنعمة الله أنا ما أنا ... » (١كو ١٥ : ١٠) . ويرسل إلى تلميذه تيموثاوس ليقول له « فتقو أنت يا ابنى بالنعمة » (٢تى ٢ : ١٠) ...",{h:"ولأهمية النعمة ... فإن الآباء الرسل يبدأون بها رسائلهم ."},"هكذا فى رسائل القديس بولس تتكرر فى مقدمتها عبارة « نعمة لكم وسلام » (رو ١ : ٧ ؛ ١كو ١ : ٣ ؛ ٢كو ١ : ٣ ؛ غل ١ : ٣ ؛ أف ١ : ٢ ؛ فى ١ : ٢) ... والقديس بطرس الرسول فى بدء رسالتيه يقول « ليكثر لكم النعمة والسلام » (١بط ١ : ١ ؛ ٢بط ١ : ٢) ، والقديس يوحنا يقول للسبع الكنائس فى مقدمة سفر الرؤيا « نعمة لكم وسلام » (رؤ ١ : ٤) .","ويميز النعمة التى نلناها فى العهد الجديد بقوله « لأن الناموس بموسى أعطى ... وأما النعمة والحق ، فبيسوع المسيح صارا » (يو ١ : ١٧) .",{h:"هذه النعمة هى قوة من الله تعمل معنا وفينا ."},"وهى أيضاً التى كانت تعمل فى آبائنا الرسل ، حتى أمكنهم أن يقوموا برسالتهم ، ويشهدوا للرب ، « وبقوة عظيمة كانوا يؤدون الشهادة ... ونعمة عظيمة كانت على جميعهم » (أع ٤ : ٣٣) والقديسة الطاهرة العذراء مريم ، حياها الملاك بعبارة ، « سلام لك أيتها الممتلئة نعمة الرب معك » (لو ١ : ٢٨) .","* * *",{h:"الله يعمل فينا بنعمته ... وبشركة روحه القدوس ."},"فالروح القدس يشترك معنا فى العمل ، ويعطينا قوة ... ولذلك قال السيد المسيح لتلاميذه القديسين « ولكنكم ستنالون قوة متى حل الروح القدس عليكم ، وحينئذ تكونون لى شهوداً » (أع ١ : ٨) .","وبهذا كانت « شركة الروح القدس » بركة توهب للمؤمنين إذ يقول القديس"],26:["بولس الرسول فى آخر رسالته الثانية إلى أهل كورنثوس « نعمة ربنا يسوع المسيح ، ومحبة الله ، وشركة الروح القدس مع جميعكم » (٢كو ١٣ : ١٤) ، وهذه هى البركة التى تمنحها الكنيسة لأولادها فى آخر كل اجتماع .","* * *","وبالإضافة إلى شركة الروح القدس ، يقول لنا السيد المسيح :",{h:"« ها أنا معكم كل الأيام وإلى انقضاء الدهر » (متى ٢٨ : ٢٠) ."},"إنه وعد عظيم يمنحنا رجاء أن يكون الرب معنا كل الأيام . ويقول أيضاً « حيثما اجتمع إثنان أو ثلاثة بإسمى فهناك أكون فى وسطهم » (متى ١٨ : ٢٠) . وقد صور لنا سفر الرؤيا السيد الرب فى وسط الكنائس السبع ورعاة هذه الكنائس عن يمينه (رؤ ١ : ١٣ ؛ ١٦ ؛ ٢٠) . إنه معنا ، يعمل فينا ، ويعمل بنا ، ويعمل معنا ... هذا عن الإبن ، وماذا عن الآب ؟ يقول السيد الرب :",{h:"« أبى يعمل حتى الآن ، وأنا أيضاً أعمل » (يو ٥ : ١٧) ."},"إن عمل الله لم ينته بالخلق ، حينما استراح الله فى اليوم السابع ! فالله يعمل باستمرار يرى كل شىء ويرقب ، كضابط للكل ... وهو يعمل فى رعاية هذه البشرية ، ويسند ويساعد ويعين ويحفظ ... وقد قيل عن الآباء الرسل « فخرجوا ، وكرزوا فى كل مكان . والرب يعمل معهم ، ويثبت الكلام بالآيات التابعة » (مر ١٦ : ٢٠) . وقال داود النبى عن عمل الرب « ما أعظم أعمالك يارب ... كلها بحكمة صنعت » (مز ١٠٤ : ٢٤) .","* * *",{h:"الثالوث القدوس إذن يعمل معنا ، وتعمل معنا ملائكته ."},"قال الرسول عن الملائكة ، أليسوا جميعاً أرواحاً خادمة مرسلة للخدمة لأجل العتيدين أن يرثوا الخلاص » (عب ١ : ١٤) ملاك من السارافيم طار بسرعة وأخذ جمرة من على المذبح ومسح بها شفتى اشعياء النبى لما سمعه يقول « ويل لى قد هلكت ، لأنى إنسان نجس الشفتين » (اش ٦ : ٥ ـ ٧) وملاك آخر وقف يدافع عن يهوشع الكاهن لما رأى الشيطان وقال له « لينتهرك الرب يا شيطان لينتهرك الرب » (زك ٣ : ٢) ."],27:["ويعوزنى الوقت إن تحدثت عن عمل الملائكة من أجل البشر بأمر من الرب : مثل قول دانيال النبى « إلهى ارسل ملاكه فسد أفواه الأسود » (دا ٦ : ٢٢) ، ومثل انقاذ الملاك لبطرس من السجن (أع ١٢) ومثل قول الكتاب « ملاك الرب حال حول خائفيه وينجيهم » (مز ٣٤ : ٧) . ومثل قول الكتاب عن عمل الله من أجلنا فى ضيقاتنا « فى كل ضيقهم تضايق وملاك حضرته خلصهم » (أش ٦٣ : ٩) .","* * *",{h:"الله يعمل لأجلنا فى كل ضيقاتنا وتجاربنا ..."},"إنه يقول لكل منا « لا أهملك ولا أتركك ، تشدد وتشجع . لا ترهب ولا ترتعب لأن الرب إلهك معك حيثما تذهب » (يش ١ : ٥ ، ٩) . وقال لارمياء النبى « لا تخف من وجوههم لأنى أنا معك لانقذك » (ار ١ : ٨) . وقال للقديس بولس الرسول « لا تخف ، بل تكلم ولا تسكت ، لأنى أنا معك . ولا يقع بك أحد ليؤذيك » (أع ١٨ : ٩ ، ١٠) .","* * *",{h:"حتى فى الكلام ، الله يكون معنا ، ليتكلم على ألسنتنا ."},"إنه يقول لنا « لا تهتموا كيف أو بما تتكلمون ، لأنكم تعطون فى تلك الساعة ما تتكلمون به لأن لستم أنتم المتكلمين ، بل روح أبيكم الذى يتكلم فيكم » (متى ١٠ : ١٩ ، ٢٠) . وبولس الرسول يطلب صلاة أهل أفسس لكى يعطى له كلام عند افتتاح فمه (أف ٦ : ١٩) ، وداود النبى يقول « افتح يارب شفتى ، لكى يخبر فمى بتسبحتك » (مز ٥٠) وارمياء النبى قال له الرب « ها قد جعلت كلامى فى فمك » (ار ١ : ٩) .","* * *","ومن جهة التوبة ، الله هو الذى يعمل فينا لنتوب ، لذلك يقول الكتاب :",{h:"« توبنى فأتوب ، لأنك أنت الرب إلهى » (ار ٣١ : ١٨) ."},"روح الله هو الذى يبكتنا على خطية (يو ١٦ : ٨) وهو الذى يرشدنا إلى طريق البر . والمرنم يقول عن عمل الرب فى التوبة « انضح على بزوفاك ، فاطهر ، واغسلنى"],28:["فأبيض أكثر من الثلج » (مز ٥٠) . ونحن نصلى فى قداساتنا ونقول « طهر نفوسنا وأجسادنا وأرواحنا » والله هو الذى منحنا فى المعمودية غسيل الميلاد الثانى (تى ٣ : ٥) . ووعدنا فى سفر اشعياء بهذا التطهير (اش ١ : ١٨) ، وكذلك فى سفر حزقيال (حز ٣٦ : ٢٥) ومن العبارات التى تستحق شيئاً من التأمل قول المرتل فى المزمور :",{h:"« قلباً نقياً اخلق فىّ يا الله وروحاً مستقيماً جدده فى أحشائى » (مز ٥٠) ."},"إذن فوجود هذا القلب النقى هو من عمل الله ، يخلقه خلقاً من لا شىء ، ويجدد الروح ... ويقول الرب فى سفر حزقيال « وأعطيكم قلباً جديداً ، واجعل روحاً جديداً فى داخلكم ... واجعل روحى فى داخلكم ... واجعلكم تسلكون فى فرائضى ، وتحفظون احكامى وتعملون بها » (حز ٣٦ : ٢٦ ، ٢٧) واضح أنه عمل الرب فينا .","* * *",{h:"« إنه الله الذى يريد أن الجميع يخلصون والى معرفة الحق يقبلون » (١تى ٢ : ٤) ."},"وهو لا يريد فقط ، وإنما يريد ويعمل على خلاصنا . هو الذى دبر طريقة الفداء والكفارة ... وهو الذى اخلى ذاته وتجسد ... هو الذى أحب « أحب العالم حتى بذل إبنه الوحيد ، لكى لا يهلك كل من يؤمن به ، بل تكون له الحياة الأبدية » (يو ٣ : ١٤) .","* * *",{h:"هو الذى أعطى الرسل المصالحة ... ليصالحونا معه ."},"وفى ذلك يقول القديس بولس الرسول « ... الله الذى صالحنا لنفسه بيسوع المسيح وأعطانا خدمة المصالحة ... إذن نسعى كسفراء عن المسيح ، كأن الله يعظ بنا ... نطلب عن المسيح : تصالحوا مع الله » (٢كو ٥ : ١٨ ، ١٩) .","* * *",{h:"هو الذى قال : أنا واقف على الباب وأقرع (رؤ ٣ : ٢٠) ."},"إنه يقرع على باب كل نفس ويبحث عن خلاص على كل نفس ، كما بحث عن"],29:["الخروف الضال والدرهم المفقود (لو ١٥) وهو من أجل هذا الخلاص أرسل الأنبياء والرسل ، والرعاة والمعلمين ، وأرسل لنا كلامه بالوحى الإلهى .",{h:"الله أيضاً يعمل لأجلنا بالحفظ الإلهى ..."},"وبهذا يتغنى المرتل فيقول فى المزمور « لولا أن الرب كان معنا حين قام الناس علينا ، لابتلعونا ونحن أحياء ... مبارك الرب الذى لم يسلمنا لأسنانهم ... نجت أنفسنا مثل العصفور من الصيادين » (مز ١٢٣) ، وداود النبى يقول لجليات « الحرب للرب ، وهو يدفعكم ليدنا » (١صم ١٧ : ٤٧) . وموسى النبى قال للشعب « قفوا وانظروا خلاص الرب ... الرب يقاتل عنكم وأنتم تصمتون » (خر ١٤ : ١٣ ، ١٤) .",{h:"إن الشيطان يريد أن يوقعنا فى اليأس ... بأن ينسينا عمل الله من أجلنا ."},"ومن السهل أن نرد عليه . إن قال لنا إن طريق الرب صعبة نقول له يكفى أن الله معنا فى الطريق ... وهو يجعل الصعب سهلاً ... وإن قال لواحد منا أن نفسك لا تريد التوبة ، نقول له : يكفى أن الله يريدها لنا وهو لاشك سيقودنا إليها ... وإن أخافنا من الأعداء الكثيرين نقول له : إن الذين معنا أكثر من الذين علينا .","* * *",{h:"إن الله يعمل لأجلنا . ولكن يجب علينا الاستجابة له ... والشركة معه ."},"وفى هذا يقول الرسول ، « إن سمعتم صوته ، فلا تقسوا قلوبكم » (عب ٣ : ٨) الله يعمل ... ولكن ينبغى أن نشترك معه فى العمل ... هو يرسل روحه القدوس لأجل تقويتنا ، وارشادنا . ولكن ينبغى لنا أن ندخل فى شركة الروح القدس .",{h:"وبهذا يكون الخلاص هو نتيجة عمل الله فينا ... ومعه قبولنا لهذا العمل ... واشتراكنا مع الروح فى وسائط النعمة ."},"وكل ذلك يبعث الرجاء فى النفس . ولكن ...","لعل إنساناً يقول إننى طلبت من الله كثيراً وهو لم يستجب ! ومازلت فى ضيقة ، والله لم يتدخل ! فأين الرجاء إذن ؟ لمثل هذا الإنسان ، قال المرتل فى المزمور :",{h:"« انتظر الرب . تقو وليتشدد قلبك ، وانتظر الرب » (مز ٢٧) ."},"* * *"],30:[{h:"الفصل العاشر"},{h:"انتظر الرب"},"عن محاضرتين ألقيتا فى الكاتدرائية الكبرى بدير الأنبا رويس بالقاهرة . أحدهما مساء الجمعة ١٩٧٦/١٢/١٠م / والثانية مساء الجمعة ١٩٨٠/٥/٢م"],31:["لا شك أن الله يعمل ، ويعمل فى هدوء ، من أجل كل مخلوقاته ، كراع صالح للجميع ، يريد الخير للكل .",{h:"غير أن البعض إذا تعبوا ، أو إذا ظنوا أن الله قد تأخر عليهم ، يخيل إليهم أنه لا يعمل ! !"},"يظنون هذا خلال مشاكلهم ، بينما يكون الله فى عمق العمل من أجلهم ، وهم لا يعملون . أو أن هؤلاء يعوزهم أن ينتظروا ليروا عمل الرب ، أو ليروا نتيجة عمله على وجه أصح ... ليروا بالعيان ما كان يجب أن يصدقوه بالإيمان ...","« انتظر الرب . تقو وليتشدد قلبك ، وانتظر الرب » (مز ٢٦ ، ٢٧) .","* * *",{h:"نوعية الانتظار"},"الذى ينتظر فى رجاء ، إنما ينتظر الرب بقلب مملوء بالإيمان وبالثقة . فى غير شك ، وبغير قلق ولا اضطراب ولا تضايق . ينتظر وهو مؤمن أن الرب لابد سيتدخل ، ولابد سيعمل ، وأن الأمور لابد تنتهى إلى خير ، حسب قول الكتاب :",{h:"« كل الأشياء تعمل معاً للخير ، للذين يحبون الله » (رو ٨ : ٢٨) ."},"وهكذا يصف لنا الكتاب الرجاء العظيم لمنتظرى الرب فيقول « وأما منتظرو الرب فيجددون قوة . يرفعون أجنحة كالنسور . يركضون ولا يتعبون ويمشون ولا يعيون » (اش ٤٠ : ٣١) ... القوة التى هزتها الضيقة ، تتجدد بالرجاء ، بانتظار الرب . كما قيل فى المزمور « يجدد مثل النسر شبابك . إذن ينبغى أن الإنسان ينتظر الله ، بقلب قوى متشدد ، بإيمان واثق ."],32:["واثق أن الله لابد سيعمل . وسيظهر عمله واضحاً وقوياً . والله يعمل فى الوقت المناسب ، وبالطريقة المناسبة ، النافعة .","ليس من اللائق أن نفرض على الله وقتاً معيناً أو اسلوباً خاصاً . فقد قال الرب « ليس لكم أن تعرفوا الأزمنة والأوقات التى جعلها الآب فى سلطانه وحده » (أع ١ : ٧) . يكفى أن تترك مشكلتك فى يد الله وتنساها هناك ، وأنت واثق أن الله سيحلها ... أما متى ؟ فهذا ليس لك أن تفحصه . يكفى أنها ستحل بيد الله ، فى الحين الحسن . وما عليك إلا أن تنتظر الرب .","* * *",{h:"ثلاثة أمور يرتكز عليها انتظارك"},{h:"١ ـ رجاؤك فى انتظار الله يرتكز على إيمانك بمحبة الله لك ."},"الله الذى يحبك ، أكثر مما تحب أنت نفسك . والذى يعمل من أجلك الخير ، أكثر مما تستطيع أن تعمل أنت من أجل نفسك . الله الذى يريد أن الجميع يخلصون ، وإلى معرفة الحق يقبلون » (١تى ٢ : ٤) . الله الذى نقشك على كفه ، وحفظك فى يمينه الحصينة ، والذى يقول لك « لا أهملك ولا أتركك » (يش ١ : ٥) .","* * *",{h:"ب ـ رجاؤك أيضاً فى انتظار الرب ، يرتكز على إيمانك بحكمته :"},"حكمته غير المحدودة ، التى هى فوق مستوى تفكيرك ، وفوق مستوى تفكير غيرك . الحكمة التى تعرف ما هو الخير لأنها ترى كل شىء ، وتبصر مالا تبصره أنت . هذه الحكمة التى أدركها أيوب الصديق أخيراً ، فقال « قد نطقت بما لم أفهم . بعجائب فوقى لم أعرفها » (أى ٤٢ : ٣) .","تأكد إذن أن الله يدبر أمورك بحكمة ، سواء فهمتها أم لم تفهمها ... سلم قلبك لحكمته وانتظر ...","* * *"],33:[{h:"ج ـ رجاؤك أيضاً فى انتظار الرب ، يرتكز على إيمانك بمواعيده :"},"مواعيده التى قال فيها « ها أنا معكم كل الأيام وإلى انقضاء الدهر » (متى ٢٨ : ٢٠) . إن نسيت الأم رضيعها أنا لا أنساكم (اش ٤٩ : ١٥) « نقشتكم على كفى » (اش ٤٩ : ١٦) . « تشدد وتشجع لا ترهب ولا ترتعب . لأن الرب إلهك معك حيثما تذهب » (يش ١ : ٩) « لا يقف إنسان فى وجهك كل أيام حياتك » (يش ١ : ٥) « أنا معك ولا يقع بك أحد ليؤذيك » (اع ١٨ : ١٠) .",{h:"لا تلجأ إلى الطرق البشرية"},"الذى ييأس من انتظار الرب ، قد يلجأ إلى الطرق البشرية . يعتمد على الذكاء أو المكر والدهاء . كما فعلت رفقة ، عندما ظنت أن الوقت قد فلت ، وسوف تضيع البركة التى وعد بها ليعقوب (تك ٢٥ : ٢٣) ، فلجأت إلى طريق بشرى ، خدع فيه يعقوب أباه القديس اسحق (تك ٢٧) .","وأيضاً أبونا ابراهيم لما يئس من انتظار الرب ، لجأ إلى الطرق البشرية ، فأخذ هاجر لتلد له ثم عاد ابراهيم وأخذ قطورة (تك ٢٥ : ١) . وكانت طرقاً مرفوضة من الرب .","* * *",{h:"والبعض حينما ييأس من انتظار الرب ، قد يلجأ إلى السحرة والعرافين ، وإلى طرق بشرية كاللجوء إلى استشارة الموتى ! !"},"الأمر الذى اعتبره الرب من رجس الأمم . وقال فى ذلك « ... لا تتعلم أن تفعل مثل رجس تلك الأمم . لا يوجد فيك من يجيز إبنه أو إبنته فى النار ، ولا من يعرف عرافة ، ولا عائف ، ولا متفائل ، ولا ساحر . ولا من يرقى رقية ، ولا من يسأل جاناً ولا تابعة ، ولا من يستشير الموتى . لأن كل من يفعل ذلك مكروه عند الرب » (تث ١٨ : ٩ ـ ١٢) كلها طرق بشرية مرفوضة من الله . وبعضها طرق شيطانية .","ومثل ذلك من يلجأ إلى التنويم المغناطيسى ، وما يعرف بالسلة . ومن يؤمن"],34:["بالعمل وإبطاله ، ومن يلجأ إلى من يقرأ الفنجان ، ومن يقرأ الكف ، ومن « يضرب الرمل » ومن « يعرف البخت » ، وأمثال هذه الطرق ...","إن الله يريدك أن تكون تحت قيادته : تأخذ معرفتك منه . وكثيراً ما تغنى داود النبى بأن خلاصه من عند الرب أو أن الرب نفسه قد صار له خلاصاً . والعجيب أن بعض الذين يلجأون إلى هذه الأمور يريحون ضمائرهم الثائرة عليهم أو ضمائر الناس الساخطة عليهم ، بأن هذه الأمور تدخل تحت نطاق العلم ، وأن الكنيسة لا يجوز لها أن تقاوم العلم ! !","* * *",{h:"فى الكتاب المقدس يقول الرب إن استشارة الموتى هى من رجس الأمم ، وأنها مكروهة عند الرب ، فيقول البعض إنها علم ، ولا يجوز للكنيسة أن تقف ضد العلم ! !"},"حتى إن كان علماً ، فهو رجس ومكروه عند الرب .","والعجيب أن السحر نفسه ، الذى هاجمه الكتاب . وقال الرب « لا تدع ساحرة تعيش » (خر ٢٢ : ١٨) . وقال إن خارج الملكوت « ... السحرة وعبدة الأوثان ... نصيبهم فى البحيرة المتقدة بالنار والكبريت » (رؤ ٢١ : ٨) ... السحر يرى البعض أن هناك نوعاً مقبولاً يسمونه « السحر الأبيض » ولم أقرأ فى الكتاب اطلاقاً عبارة « السحر الأبيض » ! !","* * *",{h:"أما أنت فلا تلجأ إلى أمثال هذه الطرق ، إنما الجأ إلى الله وانتظره . ومهما تأخر لا تلجأ إلى السحر واشباهه ."},"إنها تعبير إما عن فشل و يأس أو هى دليل عمل على اللجوء إلى غير الله . أو هى ضيق فى القلب لا يستطيع أن ينتظر الرب . أو هى استهانة بأمر الله الصريح الوارد فى (تث ١٨) . لقد ضرب الرب شاول الملك وأماته لأنه لجأ إلى مثل هذا الطريق ... (١صم ٢٨) . أما أنت فاستمع لأمر الرب الصريح . ولا تلجأ إلى طرق خاطئة كهذه مهما ظننت أنه قد تأخر عليك ."],35:["ولكن لعل إنساناً يسأل : إلى متى أنتظر الرب ؟ ...",{h:"إلى متى ننتظر ؟"},"يقول المرتل فى المزمور « صبرت نفسى للرب . صبرت نفسى لناموسك انتظرت نفسى الرب من محرس الصبح حتى الليل » (مز ١٢٩) ويضيف بعدها « لأن الرحمة من عند الرب ، وعظيم هو خلاصه » ... وربما عبارة « من محرس الصبح حتى الليل » ـ فى معناها الرمزى ـ تعنى العمر كله ، أو تعنى الوقت كله .. أو عبارة « حتى الليل » قد تعنى : حتى الظلمة ، حتى عمق اشتداد المشكلة ...","ننتظر الرب ، ونحن متأكدون تماماً أنه لا بد سيجىء ، ويصنع خلاصاً . أما متى يجىء ؟ أصباحاً ، أم ظهراً ، أم فى نصف الليل ، أم فى الهزيع الرابع ؟ لسنا ندرى ...","* * *",{h:"لا نعرف متى يجىء . ولكن ما يسعدنا حقاً ، أنه لا بد سيجىء .."},"الوقت أو الميعاد ، نتركه لحكمته الإلهية . ولكن نفرح بانتظار مجيئه ، حسب وعده الصادق « لا أتركم يتامى . إنى آتى إليكم » (يو ١٤ : ١٨) . « سأراكم أيضاً فتفرح قلوبكم . ولا ينزع أحد فرحكم منكم » (يو ١٦ : ٢٢) . إن الصليب قد يحمل ألماً . والقيامة معها فرح الرجاء ...",{h:"وكل صليب لا بد بعده قيامة . والوعد بالقيامة يحمل الرجاء ..."},"لذلك كن واثقاً ، ولا تيأس . وانتظر الرب فى عمق السلام الداخلى . وكلما احاطت بك ضيقة ، قل : إننى اسمع صوت حبيبى « هوذا آتٍ ، ظافراً على الجبال ، قافزاً على التلال » (نش ٢ : ٨) .","* * *","وإن صادفتك مشكلة ، لا تجعلها تتعبك كما يحدث لفاقدى الرجاء . بل قل فى ثقة : إن الله لا بد سيحلها . وإن لم تحل فى هذه الأيام ، ستحل فى الأسابيع المقبلة . وإن لم تحل فى هذه الأسابيع ، ستحل فى الشهور المقبلة ، أو فى السنوات المقبلة . انها"],36:["لا بد ستحل ، مهما مرّ الوقت عليها . أنا واثق يارب فى تدخلك . واثق فى حكمتك وفى عملك ، وأنك لن تتخلى .. لذلك مهما مر الوقت ، نحن لا نحزن ، كما قال الرسول :",{h:"« لا تحزنوا كالباقين الذين لا رجاء لهم » (١تس ٤ : ١٣) ."},"إن ثقتنا بعمل الله ، لا تسمح أبداً للحزن أن يدخل إلى قلوبنا . فلنثق به إذن . عجيب اننا نثق أحياناً بالطرق البشرية ، وبالوسائط العالمية ، ونثق بالآخرين ، ونثق بأنفسنا ، بذكائنا وفهمنا وقدراتنا .. أما الله ، فكثيراً ما تهتز ثقتنا ونحن ننتظره ! ! فلماذا ؟ ألعله (التأخير) فى الاستجابة هو الذى يجعلنا نشك أو نحزن .","* * *","إذن فلنبحث موضوع التأخير هذا لنفهمه جيداً ... وكمقدمة له نقول : إن الله يعمل ، مهما بدا لنا أنه قد تأخر علينا ...",{h:"مهما بدا أنه تأخر"},"الله لا يتأخر مطلقاً . عبارة « تأخر » هنا لها معنى نسبى ، بالنسبة إليك ! وكذلك عبارة « لا تبطىء » (مز ٦٩) . أى لا تجعلنى أشعر أنك قد أبطأت علىّ وتأخرت !",{h:"إن الله يعمل بطريقة هادئة متزنة ، قد نحسبها نحن بطئاً ."},"كل أعمال الله تكون فى وقتها المناسب . لا سرعة فيها ولا تأخير . وتوقيتها محسوب بحكمة إلهية عجيبة ، بكل دقة .","* * *",{h:"لقد وعد الله آدم وحواء بالخلاص ... ومرت آلاف السنوات ..."},"قال لهما إن نسل المرأة سوف يسحق رأس الحية . ومرت آلاف السنوات ، والحية لا تزال رافعة رأسها فى شموخ ! وبدا أن نسل المرأة فى انهيار مستمر ... حتى ان الله اغرق العالم بالطوفان ، وأحرق سادوم بالنار ، وأمر الأرض أن تفتح فاها لتبتلع قورح"],37:["وداثان وابيرام ... وبقى وعد الله قائماً ...",{h:"هلك هذا النسل . ولو ! ! لنا رجاء فى نسل آتٍ للخلاص .."},"كان الرجاء معلقاً فى أولاد نوح . أفسد أغلبهم ؟ ! يبقى الرجاء فى أولاد إبراهيم . أفسد أغلبهم ؟ يبقى الرجاء فى أولاد يعقوب ... لابد سيحقق الله وعده بالخلاص .. ومهما انتظر سمعان الشيخ طويلاً ـ وهو يحمل المسيح ـ لابد سيأتى عليه الوقت الذى يقول فيه « الآن يارب تطلق عبدك بسلام ، لأن عينىّ قد أبصرتا خلاصك » (لو ٢ : ٢٩ ، ٣٠) . حتى المرأة السامرية ـ على الرغم من كثرة خطاياها ـ لم يفارقها مطلقاً هذا الرجاء فى مجىء المسيح ، لذلك قالت : « أنا أعلم أن مسيا ، الذى يقال له المسيح ، يأتى ... » (يو ٤ : ٢٥) .",{h:"وكثيرون رقدوا قبل أن يبصروا الخلاص . ولكن رقدوا على رجاء .."},"وفى ذلك يقول معلمنا القديس بولس الرسول : « فى الإيمان مات هؤلاء اجمعون ، وهم لم ينالوا المواعيد . بل من بعيد نظروها ، وحيوها وأقروا بأنهم غرباء ونزلاء على الأرض » (عب ١١ : ١٣) . هؤلاء رتلوا مع المزمور « لأنك لن تترك نفسى فى الجحيم ، ولن تدع قدوسك يرى فساداً » (مز ١٦ : ١٠) . وفى كل ذلك سنسأل سؤالاً هاماً وهو :","* * *",{h:"هل حقاً تأخر الله فى تنفيذ وعده بخلاص العالم ؟"},"كلا ، إنه لم يتأخر الوقت على الرغم من مرور آلاف السنين . بل انه كان يعد البشرية لاستقبال هذا الخلاص ... يعدهم بالنبوات وبالرموز وبالتوبة وبالإيمان . كم من الذبائح والمحرقات قدموها ، حتى صارت عقيدة الكفارة والفداء راسخة فى أذهانهم ، وصارت المغفرة بالدم أمراً سهلاً مقبولاً ... وانتظر الرب حتى أصبح الإيمان ممكناً ، حتى وسط الأمم . وانتظر الرب حتى يوجد المعمدان الذى يعد الطريق قدامه ، وحتى توجد العذراء الطاهرة التى تكون اناء للتجسد ، والتى تقدر على احتمال ذلك المجد العظيم ."],38:[{h:"إذن لم تكن مرحلة تأخير ، إنما مرحلة إعداد تقوى الرجاء .."},"ونفذ الله وعده الذى لم ينسه مطلقاً خلال آلاف السنين ، بل كان يمهد له ... وأخيراً استطاع نسل المرأة أن يسحق رأس الحية (تك ٣ : ١٥) . وتم فعلاً ما قاله لابينا إبراهيم : « بنسلك تتبارك جميع قبائل الأرض » (تك ٢٢ : ١٨ ؛ أع ٣ : ٢٥) .","لقد خلصهم « فى ملء الزمان » (غل ٤ : ٤)","* * *",{h:"مفهومنا الخاطىء للتأخير"},"نحن نقول انتظر الرب . فهل ننتظر الرب حتى يبدأ العمل ، واثقاً أنه سوف يعمل ؟ كلا . فهذه تعبيرات مقدمة للمستوى البشرى فى الفهم . فما الحقيقة إذن ؟",{h:"انتظر الرب واثقاً ، ليس أنه سيعمل ، بل واثقاً أنه يعمل فعلاً ، وربما قبل أن نطلب منه نحن ."},"ربما كنيسة محتاجة إلى كاهن يرعاها ، وتطلب من الرب هذا ، ويبدو أن الرب قد تأخر عليها عامين أو ثلاثة ، حتى أرسل لها الكاهن المطلوب ... ! بينما تكون الحقيقة أن الله كان يعد لها هذا الكاهن منذ ثلاثين أو أربعين عاماً مضت ، قبل أن تطلب ... يعده بروحيات معينة ، وبعلم ومعرفة وحكمة وتداريب ، ويعده ربما بتجارب وضيقات ، وبخبرات روحية ، تجعله الشخص النافع والمناسب لهذه الكنيسة ... ونحن الذين لا نرى ولا نعرف اعدادات الله ، ونظنه قد تأخر ! !","* * *",{h:"أسباب وحكمة ما نظنه تأخيراً"},{h:"١ ـ ربما يكون مجالاً لتعميق صلواتك وروحياتك ."},"هذا (التأخير) يجعلنا نصلى ، ونتضرع وندوام اللجاجة بقوة ومن عمق القلب ،"],39:["ومن عمق الاحتياج ، وربما نضيف إلى الصلاة صوماً ، وتذللاً أمام الله ، ونذراً . مثال ذلك حنة أم صموئيل : لما كانت عاقراً ، وقد تأخر عليها الانجاب وكانت ضرتها تغيظها ، يقول الكتاب إنها « صلت إلى الرب ، وبكت بكاءً ، ونذرت نذراً » (١صم ١ : ٩ ـ ١٢) وتعهدت بأن الابن الذى يعطيها الرب إياه يكون نذيراً للرب يخدمه كل أيام حياته . وهكذا استفادت من هذا (التأخير) . أو قل أن الرب وجد أن الوقت المناسب لمنحها نسلاً ، هو الوقت الذى تصل فيه إلى هذه الحالة الروحية ، بدون تأخير .","* * *",{h:"٢ ـ ربما يكون السبب أن الرب يعد طريقاً أفضل :"},"لو استجاب الرب ليوسف الصديق منذ أول إلقائه فى السجن ، ربما كان مصيره أن يخرج ليخدم فوطيفار أو سيداً آخر ، أو فى أية وظيفة مماثلة ولكن (التأخير) لم يكن تأخيراً ، وإنما انتظاراً للحلم الذى يحلمه فرعون ، ويفشل فى معرفة تفسيره ، ويكون رئيس سقاته معه ، فيخبره بيوسف ، ويفسر يوسف الحلم بحكمة ويصير الوزير الأول لمصر وأباً لفرعون إذن ما بدا تأخيراً ، كان إعداداً لوضع أفضل .","* * *",{h:"٣ ـ وربما يكون السبب هو اختبار إيماننا :"},"هل نتضايق حينما لا تستجاب صلواتنا فى ذات الوقت ؟ هل نتذمر ؟ هل نلجأ إلى غيره ؟ هل يشكو للكل ؟ هل نجدف عليه ؟ أم أننا نصبر فى إيمان وفى رجاء وثقة ؟ ... إنه اختبار من الله لإيماننا ، اختبار منا لأنفسنا . حتى إن وجدنا فى أنفسنا ضعفاً ، نعالجه .","* * *",{h:"٤ ـ وربما يكون السبب هو أن نحصل على انسحاق القلب :"},"إن استجابة كل صلاة فى وقتها ، ربما تؤدى بنا إلى الافتخار والمجد الباطل . بينما هذا (التأخير) قد يوصلنا إلى التواضع والانسحاق ، فندرك أننا لسنا شيئاً ...","* * *"],40:[{h:"٥ ـ وقد يكون السبب هو أن نصطلح مع الله :"},"فإن (تأخر) علينا فى الاستجابة ، قد نراجع أنفسنا ، هل نحن أخطأنا إلى الرب ، فلم يستجب بسبب خطايانا ؟ وهنا نتذكر قول الرب « ارجعوا إلىّ فأرجع إليكم » (ملا ٣ : ٧) يقودنا هذا الأمر إلى التوبة . ويكون وصولنا إلى التوبة هو الموعد المناسب الذى حدده الله ، بلا تأخير .","* * *",{h:"٦ ـ ربما يكون السبب هو أن ما ننالُه بسرعة ، لا نشعر بقيمته :"},"وقد لا نشكر عليه ، فإن (تأخرت) الاستجابة ، يزداد تعلقنا بالمطالبة وشعورنا بقيمة تحقيقها . فإذا ما استجيبت بعد حين ، يزداد شكرنا لله ولا ننسى احسانه إلينا . وهذا يعمق ارتباطنا به ، كذلك نحرص على ما ننالُه منه فلا نفقده بسرعة ...","* * *",{h:"٧ ـ وربما يصبر الله علينا فى الضيقة ، لننال بركاتها :"},"إن استجاب لنا الله فى التو واللحظة ، ورفع عنا الضيقة ، فلا يمكن أن ننال البركات التى ننالها كلما طالت مدة الضيقة ، واحتملنا وصبرنا ونأخذ بسبب ذلك أكاليل ، بل نأخذ خبرات روحية أيضاً .","ونأخذ فضيلة الصبر والتسليم وانتظار الرب .","* * *",{h:"٨ ـ وقد يكون السبب فيما نظنه تأخيراً ، هو أن الله يعد لنا بديلاً أفضل مما نطلبه :"},{h:"ذلك لأن الله يعطينا دائماً ما ينفعنا وما يناسبنا ، وليس مجرد الذى نطلبه ."},"إن الله لايستجيب حرفية صلواتنا ، بل روحها . هو يعرف احتياجاتنا أكثر مما نعرف نحن . وهو يعرف الصالح لنا أكثر مما نعرف نحن . ويكفى أن نقول له إننا نريد ، وهو يختار بحكمته ما يراه نافعاً لنا ، وما يراه مطابقاً لمشيئته المقدسة المملوءة حكمة .","* * *"],41:[{h:"٩ ـ ربما شعورنا أن الله قد تأخر علينا ، هو تعبير عن عدم اجادتنا لعبارة « لتكن مشيئتك » ."},"إننا نقولها فى الصلاة . ولكننا غالباً لا ندخل إلى عمقها ، ولا ندركها ولا نعنيها . فإن تأخرت استجابة ما نطلب ، علينا أن نقول له : نحن يارب لا نفرض عليك مشيئتنا ، إنما نصارحك بما فى داخلنا من رغبات ومن طلبات . فإن وجدتها نافعة ، حققها فى الوقت الذى تختاره . وإلا فلتكن مشيئتك ، بكل رضى قلوبنا ...",{h:"إنه تدريب على حياة التسليم ، المبنية على الثقة بتدابير الله ."},"المهم أن ننتظر الرب ، بقلب مملوء بالسلام والاطمئنان ، شاعرين أن قضيتنا قد استقرت فى يد الله الأمينة وفى قلب الله الحنون . وهذا يكفى ...","(صفحة رسم بلا نص: صورة طفل يصلي ينظر إلى المسيح وملائكة وشمعة)"],42:[{h:"الفصل الحادى عشر"},{h:"شجعوا صغار النفوس اسندوا الضعفاء (١تس ٥ : ١٤)"},"عن محاضرتين القيتا بالكاتدرائية يومى الجمعة ٧٦/١٠/٢٢ ، ١٩٨٠/١٠/٣٠م ."],43:[{h:"الله العطوف"},"حقاً إن الله يحب أن يكون الإنسان قوياً فى شخصيته ، قوياً فى حياته الروحية ، قوياً فى احتماله ، فى خدمته ، فى فهمه ، فى كل شىء .",{h:"ولكنه مع ذلك هو إله الضعفاء أيضاً ."},"يسندهم فى ضعفهم ، يشجعهم ويقويهم ، ولا يتركهم ... بل عن مثل هؤلاء ، قال السيد المسيح « روح السيد الرب علىّ . لأن الرب مسحنى لأبشر المساكين ، أرسلنى لأعصب منكسرى القلب ، لأنادى للمسبيين بالعتق ، وللمأسورين بالاطلاق ... لأعزى كل النائحين ... لأعطيهم جمالاً عوضاً عن الرماد ، ودهن فرح عوضاً عن النوح ، ورداء تسبيح عوضاً عن الروح اليائسة » (أش ٦١ : ١ ـ ٣) .","* * *","نعم إنه يسند هؤلاء اليائسين ، والمنكسرين والنائحين . ونقول عنه :",{h:"معين من ليس له معين ، ورجاء من ليس له رجاء ."},"عزاء صغيرى النفوس ، ميناء الذين فى العاصف . أى أنه ميناء السلامة ، للذين فى سفن تتقاذفها الأمواج والعواصف ... كما حدث للتلاميذ ، فى يوم ريح شديدة ، وكانت سفينتهم فى وسط البحر معذبة من الأمواج . فأبصروه قادماً إليهم ماشياً على الماء . وقال لهم « أنا هو ، لا تخافوا » ... وسكنت الريح (مت ١٤ : ٢٤ ـ ٣٢) .","* * *","حقاً إنه معين من ليس له معين ، وكمثال ذلك :"],44:[{h:"شفاؤه مريض بيت حسدا ، الذى ليس له إنسان يلقيه فى البركة ..."},"حينما تقف وحيداً ، وليس لك إنسان يهتم بك ، ستجد الله حتماً إلى جوارك ... حينما تهرب من عيسو الجبار الذى يريد أن يقتلك ، حينئذ سترى سلماً بين السماء والأرض ، وصوت الله يطمئنك قائلاً « ها أنا معك ، واحفظك حيثما تذهب .. » (تك ٢٨ : ١٥) . حينما يطاردك فرعون حتى إلى البحر ، وتصغر نفسك ، سيشق لك الله فى البحر طريقاً ...","لا تصغر نفسك أمام الشدائد . وإن صغرت ، اسمع قول الرسول :",{h:"« شجعوا صغار النفوس ، اسندوا الضعفاء » (١تس ٥ : ١٤) ."},"* * *","كذلك أنت ، إن رأيت إنساناً حائراً يائساً منهاراً ، لا تستصغره . وإن رأيته ساقطاً ، لا تحتقره ، بل أسنده ، وقل له كلمة ترفع معنوياته . اعطه كلمة رجاء . افتح له طاقة من نور تضىء له الطريق .","يا أخى إن كنت على قمة الجبل ، فلا تحتقر الذين على السفح أو فى الوادى ، أو حتى الذين فى المستنقع ... وإن أعطاك الرب نعمة ووصلت ، فلا تنظر إلى الناس من فوق ، ولا تحتقر الذين لم يصلوا . أو حتى اليائسين وصغار النفوس . بل تذكر قول الرب :",{h:"« انظروا . لا تحتقروا أحد هؤلاء الصغار » (مت ١٨ : ١٠) ."},"مهما وصلت إليه حالتهم ، فالله قادر أن يقيمهم ، كما أقام من قبل أوغسطينوس وبيلاجية وموسى الأسود .... حتى إن كان شجرة غير مثمرة ، وعلى وشك أن تقطع ، فإن الكرام الحنون يشاء أن يتركها هذه السنة أيضاً ، وينقب حولها ويضع زبلاً ، فربما تأتى بثمر فيما بعد (لو ١٣ : ٦ ـ ٩) ... إنه إلهنا الطيب الذى قيل عنه :",{h:"قصبة مرضوضة لا يقصف ، وفتيلة مدخنة لا يطفىء (مت ١٢ : ٢٠) ."},"ربما يعصب القصبة المرضوضة فتستقيم ، وينفخ فى الفتيلة المدخنة فتشتعل ..."],45:["إن الله يعطى فرصة لكل أحد . لأنه لا يشاء موت الخاطىء ، بل أن يرجع ويحيا (حز ١٨ : ٢٣ ، ٣٢) ... وطالما الإنسان على قيد الحياة ، لا تزال أمامه فرصة للتوبة ، ولا يفقد الرجاء . فاللص اليمين آمن وعاد إلى الله ، وهو فى الساعات الأخيرة من حياته على الأرض ... لقد كان هو أيضاً قصبة مرضوضة .","* * *","عبارة جميلة معزية قالها ربنا يسوع المسيح وهى :",{h:"ما جئت لأدين العالم ، بل لأخلص العالم (يو ١٢ : ٤٧) ."},"ليست فى فمى كلمة دينونة ، بل كلمة حب ، كلمة خلاص ومغفرة ... بل الدينونة التى عليكم أنتم ، سأحلها أنا بدلاً منكم ، وأعوها عنكم بدمى ... حقاً يارب فمك حلاوة وكله مشتهيات (نش ٥ : ١٦) . تقول ما جئت لأدين ، بينما الدينونة كلها للابن ! (يو ٥ : ٢٢) .","* * *",{h:"أمثلة"},{h:"إن البشرية الضعيفة المسكينة الساقطة ، سندها الله بالأنبياء ."},"حتى عندما رفضوه . أتى ليجتذبهم إليه ... عندما تركوه ، وحفروا لهم آباراً مشققة لا تضبط ماء (أر ٢ : ١٣) ، لم يتركهم بل حدثهم عن ينبوع المياه الحية ... ولما عبدوا العجل الذهبى ، وقالوا هذه آلهتك يا اسرائيل التى أصعدتك من أرض مصر (خر ٣٢ : ٤) ... لم يفنهم الرب ، بل رجع عن حو غضبه ، وقبل شفاعة موسى النبى فيهم ... ولا يزال الرب يصبر ويحتمل ، ويقيم الساقطين ويحل المربوطين (مز ١٤٥) .","* * *",{h:"فى صغر نفسك قد تيأس من خلاصك ! ولكن الله لا يأس مطلقاً من اجتذابك إليه ."},"لقد جاء يطلب ويخلص ما قد هلك (لو ١٩ : ١٠) . سعى وراء العشارين"],46:["والخطاة وجلس على موائدهم . وقال « ما جئت لأدعو أبراراً بل خطاة إلى التوبة » « لا يحتاج الأصحاء إلى طبيب بل المرضى » (لو ٥ : ٣١ ، ٣٢) .... مدح العشار الذى لم يجرؤ أن يرفع عينيه إلى فوق ، وقد وقف من بعيد ... وفضله على الفريسى ، وخرج من عنده مبرراً (لو ١٨ : ١٣ ، ١٤) .","* * *",{h:"حتى المرأة الخاطئة المضبوطة فى ذات الفعل ."},"المرأة الغارقة فى الخزى وصغر النفس ، التى اجتمع حولها الكتبة والفريسيون ليرجموها ... أنقذها الرب من هؤلاء ، وقال لها « ولا أنا أدينك . اذهبى ولا تخطئى أيضاً » (يو ٨ : ٣ ـ ١١) .","وكذلك الخاطئة التى بللت قدميه بدموعها ، ومسحتهما بشعر رأسها ، رفع معنوياتها ، وفضلها على الفريسى ، وقال إن خطاياها الكثيرة قد غفرت لها (لو ٧ : ٣٧ ـ ٤٧) .","* * *","من أجل معرفة داود النبى ، بحنان الله الذى يشجع صغار النفوس ، قال له فى توبته :",{h:"اغسلنى ، فأبيض أكثر من الثلج (مز ٥٠) ."},"وعبارة « أكثر من الثلج » توضح مدى غنى حنان الله على الخطاة ، حتى قال عنه المرتل فى مزموره الجميل المعزى « باركى يا نفسى الرب ، ولا تنسى كل حسناته .. » قال : « كما يتراءف الاب على البنين ، يتراءف الرب على خائفيه » « لم يصنع معنا حسب خطايانا ، ولم يجازنا حسب آثامنا . لأنه مثل ارتفاع السموات فوق الأرض ، قويت رحمته على خائفيه . كبعد المشرق عن المغرب ، ابعد عنا معاصينا ... لأنه يعرف جبلتنا يذكر أننا تراب نحن » (مز ١٠٣ : ١٠ ـ ١٤) .","* * *"],47:["إن الله ليس فقط يغفر لنا خطايانا ، بل يقول :",{h:"« ولا أذكر خطيتهم بعد » (أر ٣١ : ٣٤) ."},"يقول عن الخاطىء التائب « كل معاصيه التى فعلها لا تذكر عليه » (حز ١٨ : ٢٢) « كل خطيته التى أخطأ بها لا تذكر عليه » (حز ٣٣ : ١٦) . ويقول بولس الرسول عن عمل الفداء « إن الله كان فى المسيح مصالحاً العالم لنفسه ، غير حاسب لهم خطاياهم » (٢كو ٥ : ١٩) . ويقول المرتل فى المزمور « طوبى للذى غفر إثمه وسترت خطيته . طوبى لرجل لا يحسب له الرب خطية » (مز ٣٢ : ١ ، ٢) . ويكرر القديس بولس الرسول هذه الآية فى رسالته إلى رومية (رو ٤ : ٨) .",{h:"فالذى يصيبه صغر نفس بسبب خطاياه ، فليتذكر أنها لا تحسب عليه فى توبته ."},"الله يمحوها فى التوبة ، ولا يعود يذكرها « إن كانت خطاياكم كالقرمز ، تبيض كالثلج » (اش ١ : ١٨) . بل أكثر من الثلج (مز ٥٠) .","* * *",{h:"ولنأخذ مثالاً لبطرس الرسول الذى انكر المسيح :"},"بل أنه أخذ « يلعن ويحلف أنى لا أعرف هذا الرجل الذى تقولون عنه » (مر ١٤ : ٧١) (مت ٢٦ : ٧٤) . ونسى قوله للسيد « وإن شك فيك الجميع ، فأنا لا أشك » « ولو أضطررت أن أموت معك لا أنكرك » (مر ١٤ : ٢٩ ، ٣١) (مت ٢٦ : ٣٣ ، ٣٥) ... وهوذا الآن وقد أنكره ثلاث مرات ... لذلك وقع فى صغر النفس ، وبكى بكاءً مراً (مت ٢٦ : ٧٥) .",{h:"ولكن الرب لم يترك تلميذه بطرس لصغر النفس ، بل شجعه بأساليب كثيرة ."},"فبعد القيامة قال للمريمات « اذهبن وقلن لتلاميذه ولبطرس أنه يسبقكم إلى الجليل هناك ترونه » (مر ١٦ : ٧) . ولم يدمج بطرس وسط التلاميذ ، لأنه كان محتاجاً إلى اهتمام خاص ليرفع نفسيته بعد إنكاره ... ولما ظهر السيد المسيح لسبعة من تلاميذه عند"],48:["بحر طبرية ، قال لبطرس « أتحبنى أكثر من هؤلاء ؟ ارع غنمى ... ارع خرافى ... » (يو ٢١ : ١٥ ـ ١٧) . ليظهر له أنه لم يسقط من درجته الرسولية بإنكاره له ... بل إن بولس الرسول يقول عن ظهورات الرب بعد قيامته ، أنه ظهر لصفا ثم للاثنى عشر (١كو ١٥ : ٥) .","* * *",{h:"وبالمثل فعل الرب مع توما فى شكه ."},"كانت نفسه أصغر من أن تؤمن دون أن ترى ... كل التلاميذ آمنوا ، ما عداه . فلم يتركه الرب إلى شكه وصغر نفسه ، بل ظهر له وأراه جروحه . وقال له « هات يدك وضعها فى جنبى . ولا تكن غير مؤمن بل مؤمناً » فآمن توما وقال « ربى وإلهى » (يو ٢٠ : ٢٧ ، ٢٨) .","* * *",{h:"لننظر معاملة الرب لموسى الثقيل الفم واللسان (خر ٤ : ١٠) ."},"كان موسى يعرف عن نفسه هذا الضعف ، وأنه لا يصلح بسببه . وقد قال للرب « لست أنا صاحب كلام ، منذ أمس ولا أول من أمس ، ولا من حين كلمت عبدك » (خر ٤ : ١٠) . وقال له أيضاً « ها أنا أغلف الشفتين ، فكيف يسمع لى فرعون » (خر ٦ : ٣٠) . ولكن الله شجعه ، ولم يتركه لصغر النفس .",{h:"بل إن هذا الأغلف الشفتين صار كليم الرب ."},"وقال له « اذهب الآن ، وأنا أكون مع فمك ، وأعلمك ما تتكلم به » . وها هو هارون أخوك « تكلمه وتضع الكلمات فى فمه . وأنا أكون مع فمك ومع فمه . وأعلمكما ماذا تصنعان ... هو يكون لك فماً ، وأنت تكون له إلهاً » (خر ٤ : ١٢ ـ ١٦) .","* * *",{h:"كذلك شجع الله صغار السن ، والخائفين من المسئولية :"}],49:["لما قال له أرميا « إنى لا أعرف أن أتكلم لأنى ولد » قال له الرب « لا تقل إنى ولد ... لا تخف من وجوههم ، لأنى أنا معك لأنقذك يقول الرب » ومد الرب يده ولمس فم ارميا وقال له « ها قد جعلت كلامى فى فمك . انظر . قد وكلتك هذا اليوم على الشعوب وعلى الممالك ، لتقلع وتهدم ، وتهلك وتنقض ، وتبنى وتغرس » (أر ١ : ٦ ـ ١٠) .","ثم شجعه بالأكثر وقال له « هأنذا قد جعلتك اليوم مدينة محصنة وعمود حديد وأسوار نحاس على كل الأرض ... فيحار بونك ولا يقدرون عليك ، لأنى أنا معك يقول الرب لانقذك » (أر ١ : ١٨ ، ١٩) .",{h:"وبنفس الوضع شجع الرب يشوع بعد موت موسى ."},"لم يكن سهلاً على يشوع أن يملأ المكان الكبير الذى كان يشغله موسى النبى العظيم ، لذلك كان صغيراً فى عينى نفسه . ولكن الرب شجعه قائلاً :","« لا يقف إنسان فى وجهك كل أيامك . كما كنت مع موسى ، أكون معك . لا أهملك ولا أتركك . تشدد وتشجع ... أما أمرتك . تشدد وتشجع . لا ترهب ولا ترتعب ، لأن الرب إلهك معك حيثما تذهب » (يش ١ : ٥ ـ ٩) ..","* * *",{h:"قصة عن القديس الأنبا ايسيديروس قس القلالى :"},"قيل عنه فى البستان : إن أى أخ كان يفشل الآباء فى اصلاحه و يطردونه ، كان الأنبا ايسيديروس يأخذه ، ويطيل أناته عليه حتى يخلص . ولذلك فإن الأنبا موسى ، حينما جاء إلى الدير ، وكان منظره مخيفاً ، حولوه إلى القديس ايسيديروس . كان الأنبا موسى فى أول توبته ، حله ثقيل . وفى إحدى الليالى جاء إلى أبيه الأنبا ايسيديروس احدى عشرة مرة . فلما نصحه بالذهاب إلى قلايته ، أجاب : « لا أستطيع يا معلم » لأن الأفكار كانت تضغط عليه بشدة .","وأطال القديس أناته عليه ، حتى تحول موسى الأسود إلى قديس ."],50:[{h:"نصائح"},"حاولوا دائماً أن ترفعوا من نفسية الناس ومعنوياتهم « أسندوا الضعفاء » إن رأيتم إنساناً يبكيه الكثيرون ، وينتقدونه ، ويتهكمون عليه ، وهو ذليل أمامهم : حاولوا أن تحتضنوه ، وتقولوا فيه إن أمكنكم كلمة طيبة ... تأكدوا أنه لن ينسى هذا الموقف النبيل منكم كل أيام حياته ...","إن هذه رسالة القلوب الكبيرة ، المحبة الحنونة ، نحو صغار النفوس .","* * *",{h:"إن وجدت إنساناً مربوطاً بالخطية ، فلا تعيره ، بل فكه من رباطاته ."},"لا تكن مثل رجل رأى شاباً يصارع الغرق فى البحر . فظل يوبخه ويقول له : يا ابنى ، مادمت لا تتقن العوم ، فلماذا تنزل إلى البحر ؟ ! فقال له الشاب : انقذنى يا سيدى من الغرق ، ثم وبخنى بعد ذلك كما تشاء .. !","هكذا أنت لا تعيّر أحداً بفشله . بل اعطه رجاء فى النجاح .","* * *",{h:"لا تقل : نصحت كثيراً ولا فائدة . بل أطل أناتك ."},"هوذا الرسول يقول « ... اسندوا الضعفاء . تأنوا على الجميع » (١تس ٥ : ١٤) . إن الانتصار على خطية متأصلة ، يحتاج إلى وقت وإلى صبر . فأصبر على الضعفاء ، ريثما تفتقدهم النعمة وتنجيهم . واذكر أنك أيضاً تحت الآلام مثلهم . ضع أمامك قول الرسول « اذكروا المقيدين كأنكم مقيدون معهم ، والمذلين كأنكم أيضاً فى الجسد » (عب ١٣ : ٣) ...","* * *","تذكر ان الذين ثبطوا همة الشعب ، لم يسمح لهم الله بدخول أرض الموعد ."],51:["أولئك الذين قالوا « لا نقدر أن نصعد إلى الشعب لأنهم أشد منا .... قد رأينا هناك الجبابرة بنى عناق ... فكنا فى أعيننا كالجراد » (عد ١٣ : ٣١ ، ٣٣) ... ولم يدخل الأرض سوى يشوع بن نون ، وكالب بن يفنه ، الذى قال فى رجاء « إننا نصعد ونمتلكها ، لأننا قادرون عليها » (عد ١٣ : ٣٠) ...","* * *",{h:"ابحث عن النقط البيضاء فى حياة الإنسان الخاطىء أو الضعيف . اظهرها وامتدحها ."},"فهكذا فعل السيد المسيح مع المرأة السامرية ، على الرغم من خطاياها . قال لها « حسناً قلت ليس لى زوج ... » « هذا قلتِ بالصدق » (يو ٤ : ١٧ ، ١٨) . ووسط هذا المديح شجعها على الاعتراف . وربح نفسها للتوبة ...","* * *","هناك إنسان تشجعه بكلمة طيبة ، وآخر بقدوة صالحة ، أو بذكر قصص وآيات ، أو بتهوين الأمر عليه ، أو بالتحدث عن نعمة الله وعملها ... كذلك بالتغاضى عن كثير من أخطائه . لأن التوبيخ على كل خطأ قد يوقع فى اليأس ."],52:[{h:"الفصل الثانى عشر"},{h:"الله الذى يبدأ"},"من محاضرتين : الأولى فى ٧٧/٦/١٠ ، والثانية فى ٨٨/٢/٣ ."],53:["هناك أسلوبان فى حياة التوبة ، وفى العلاقة بين الله والإنسان :",{h:"١ ـ أن يأتى الإنسان إلى الله ، فيقبله الله ..."},"وذلك حسب وعد الله الصادق « من يقبل إلىّ ، لا أخرجه خارجاً » (يو ٦ : ٣٧) . وهذا هو الذى حدث للابن الضال : شعر بسوء حالته ، وقال أقوم واذهب إلى أبى . وفعلاً ذهب إليه ، فقبله أبوه فرحاً (لو ١٥ : ١٧ ـ ٢٤) . ويطلب الله منا هذه التوبة وهذا الرجوع إليه ، فيقول « ارجعوا إلىّ فأرجع إليكم » (ملا ٣ : ٧) .",{h:"٢ ـ الأسلوب الثانى : أن يبدأ الله العلاقة مع الإنسان ."},"هو الذى يذهب إليه . يسعى إلى خلاصه ، كما سعى وراء الخروف الضال حتى وجده وحمله على منكبيه فرحاً (لو ١٥ : ٤ ، ٥) ، وعن هذه المبادرة الإلهية ، يقول « أنا واقف على الباب أقرع . من يفتح لى ، ادخل واتعشى معه ، وهو معى » (رؤ ٣ : ٢٠) .","ونود فى هذا الفصل ، أن نركز على بدء الله بالعمل معنا .","* * *",{h:"الإنسان قد لا يبدأ مع الله ، لأسباب عديدة :"},"* ربما لأنه مغلوب من شهواته .","تضغط عليه الشهوة من داخل قلبه ، أو تحاربه بشدة من الخارج ، وتؤثر عليه وتأسره . بحيث أصبح يحب الخطية ، ولا يريد أن يبرأ منها (يو ٥ : ٦) . فماذا يفعل مثل هذا الإنسان ؟ هل ييأس ويفقد الرجاء ؟ أم أن الله يبدأ العمل معه : يفتقده ، ويقرع على بابه ، ويجتذبه إليه ؟ يقيناً إن هذا يحدث .","* * *","* وربما الإنسان لا يبدأ ، لأنه مشغول عن الله بأمور كثيرة :"],54:["وهذه المشغوليات لا تترك له وقتاً يتفرغ فيه لله ... كما قال الرب لمرثا : « أنت تهتمين وتضطربين لأجل أمور كثيرة ، ولكن الحاجة إلى واحد » (لو ١٠ : ٤١ ، ٤٢) ... إنسان ليس لديه وقت لله ... ليس لديه وقت للصلاة ، ولا للقراءة والتأمل ، ولا للخدمة ... يحتاج إلى يد قوية ، تنتزعه من كل هذا ...","* * *","* وربما الإنسان لا يبدأ ، بسبب الجهل . لا يعرف كيف يبدأ .","مثل أهل نينوى الذين قيل عنهم إنهم « لا يعرفون يمينهم من شمالهم » (يون ٤ : ١١) . فبدأ الله معهم ، وأرسل إليهم يونان النبى ليهديهم إليه . ومثل شاول الطرسوسى ، الذى كان بجهل يضطهد الكنيسة (١تى ١ : ١٣) . فكان لابد أن يظهر له المسيح ويجتذبه إليه . وأيضاً حينما تأثر بهذا الظهور وآمن ، قال « ماذا تريد يارب أن أفعل ؟ » (أع ٩ : ٦) .","عبارة « ماذا أفعل ؟ » قالها أيضاً الشاب الغنى (مت ١٩ : ١٦) . وقالها أيضاً اليهود فى يوم الخمسين (أع ٢ : ٣٧) . ويقولها كثيرون ...","* * *","* وربما الإنسان لا يبدأ ، بسبب الضعف .","فهو يقول « الشر الذى لست أريده إياه أفعل » « الإرادة حاضرة عندى ، وأما أن أفعل الحسنى فلست أجد » « أرى ناموساً آخر فى أعضائى ، يحارب ناموس ذهنى ، ويسبينى إلى ناموس الخطية » « ويحى أنا الإنسان الشقى ، من ينقذنى من جسد هذا الموت » (رو ٧ : ١٨ ـ ٢٤) .","إذن لابد أن يبادر الله ، و ينقذ مثل هذا الإنسان ...","* * *","وهنا لعل إنساناً يسأل :",{h:"إذا لم استطع أنا أن أبدأ ، هل الله مستعد أن يبدأ معى ؟"},"نعم يا أخى ، هو مستعد أن يبدأ . بل هذا هو أسلوبه باستمرار . والكتاب"],55:["المقدس مزدحم بأمثلة كثيرة ، فيها كان الله هو الذى يبدأ ، منذ خلق الإنسان ، وقبل خلقه أيضاً . ولنحاول أن نتأمل كل هذا معاً ...","* * *","هناك حقيقة ثابتة ، يسجلها الكتاب المقدس ، وهى :",{h:"علاقة الله بالإنسان ، الله هو الذى بدأها ..."},"* بدأت العلاقة بأن الله خلق الإنسان . وطبعاً لو لم يخلقه ما كانت هناك علاقة . وأضاف الله إلى هذا ، أنه خلقه على صورته ومثاله كشبهه ، ومنحه الروح الذى به ينشىء علاقة معه ...","* وإلى جوار الخلق : لما سقط الإنسان ، الله هو الذى بدأ العلاقة .","لم يبدأ الإنسان بالسعى إلى الله ليعترف بخطيته ويطلب المغفرة والمصالحة ، بل العكس لقد هرب من الله ، واختبأ وراء الشجر . فذهب الله إليه ، وكلمه ، وشجعه على الاعتراف . ووعده بالخلاص ، حينما قال إن نسل المرأة يسحق رأس الحية (تك ٣) .","وكأن الله كان يقول لآدم : هل أنت خائف منى يا آدم ؟ لا تخف ، أنا سأصالحك . هل أنت مرتعب من الخطية ونتائجها ؟ لا تخف . أنا سأغفر لك . سأعد لك طريق الخلاص ...","* ولاشك أن الله هو الذى بدأ بإعداد هذا الخلاص العجيب .","هو الذى علّم البشرية عقيدة الفداء والكفارة ، وموت نفس بريئة طاهرة عن نفس خاطئة مستحقة للموت . وهو الذى وضع للإنسان شرائع الذبائح والمحرقات ، وقواعد النجاسة والتطهير . وهو الذى أعطانا التوبة للحياة (أع ١١ : ١٨) .","* والله هو الذى بدأ بالوحى ، وأرسل إلينا الأنبياء .","كل ذلك لتعليمنا وارشادنا ، وتوصيل كلمته إلينا . وهو الذى أعطى هؤلاء الرسل « خدمة المصالحة » (٢كو ٥ : ١٨) . حتى أن القديس بولس الرسول قال « نسعى كسفراء عن المسيح ، كأن الله يعظ بنا . نطلب عن المسيح : تصالحوا مع الله » (٢كو ٥ : ٢٠) . إذن الله هو الذى يبدأ عملية المصالحة ، ويرسل رسله لتمهيدها ."],56:["* هو الذى تجسد ، ونزل إلينا ، ليفدينا ويخلصنا .","وما كنا نحن نعرف شيئاً عن التجسد والفداء ، وما كنا نطلبه . ولكن الله أظهر محبته لنا ، بهذا الخلاص العجيب « هكذا أحب الله العالم ، حتى بذل إبنه الوحيد ، لكى لا يهلك كل من يؤمن به ، بل تكون له الحياة الأبدية » (يو ٣ : ١٦) .","* * *",{h:"وفى علاقته بالإنسان ، الله هو الذى بدأ بالدعوة ."},"سواء بالنسبة إلى النبوة ، أو الرسولية ، أو الكهنوت ...","الله هو الذى دعا أبانا نوح ، وكلّفه بصنع الفلك ، والدخول فيه ، ليخلص هو وأسرته ، ولكى يستبقى الله حياة على الأرض (تك ٦ ـ ٨) . وكان الفلك فى الماء ، رمزاً إلى المعمودية « الذى فيه خلص قليلون ، أى ثمانى أنفس بالماء . الذى مثاله يخلصنا نحن الآن ، أى المعمودية » (١بط ٣ : ٢٠ ، ٢١) .",{h:"وكما دعا الله نوحاً ، دعا أبانا ابراهيم ، ليكون له شعباً يسير فى طريق الخلاص ."},"ابرآم لم يبدأ هذه العلاقة ، إنما بدأها الله معه . دعاه ليتبعه فى الأرض التى يريه إياها ، وباركه . وقال له « تتبارك فيك جميع قبائل الأرض » (تك ١٢ : ١ ـ ٣) . وأيضاً « تتبارك فى نسلك جميع أمم الأرض » (تك ٢٢ : ١٨) .","ونفس الوعد أعطاه الرب لأبينا يعقوب ، فقال له « ويتبارك فيه وفى نسلك جميع قبائل الأرض » (تك ٢٨ : ١٤) .",{h:"الله هو الذى بدأ ، فمنح البركة ."},"منح البركة منذ البدء لأبوينا الأولين آدم وحواء (تك ١ : ٢٨) . وكرر نفس البركة لأبينا نوح وبنيه (تك ٩ : ١) . ومنح البركة لأبينا ابراهيم (تك ١٢ : ١٢) (تك ٢٢ : ١٧ ، ١٨) . ولأبينا اسحق (تك ٢٦ : ٢٤) ، ولأبينا يعقوب (تك ٢٨ : ١٤) .","وكانت أعظم بركة ، أن ينتهى من نسلهم المسيح ، وبه تتبارك جميع قبائل الأرض ، بالخلاص الذى يقدمه للعالم ."],57:["فالخلاص هو المحبة العظمى ، الذى بدأ الله بها ، وأكملها من أجل محبته للإنسان ، لأنه :",{h:"« يريد أن الجميع يخلصون ، وإلى معرفة الحق يقبلون » (١تى ٢ : ٤) ."},"* * *",{h:"ومن أجل هذا الخلاص دعا الأنبياء والرسل :"},"* دعا موسى النبى ، حينما كلمه من العليقة (خر ٣ : ٤) ، وذلك لكى يرسله لخلاص الشعب ، وما كان موسى مفكراً وقتذاك فى هذه الدعوة ، ولا فى السعى لتخليص الشعب ، بل اعتذر عن ذلك أكثر من مرة (خر ٤ : ١٠ ، ١٣) .","* ودعا الله أناساً من بطون أمهاتهم .","كما قال لأرمياء الطفل « قبلما صورتك فى البطن عرفتك ، وقبلما خرجت من الرحم قدستك . جعلتك نبياً للشعوب » (أر ١ : ٥) . وكذلك يوحنا المعمدان ، الذى قال عنه الملاك « ومن بطن أمه يمتلىء من الروح القدس » (لو ١ : ١٥) . ومثل أبينا يعقوب (رو ٩ : ١ ـ ١٣) (تك ٢٥ : ٢٣) .","ومعلمنا القديس بولس الرسول قال عن دعوته « لما سرّ الله الذى أفرزنى من بطن أمى ، ودعانى بنعمته ... » (غل ١ : ١٥) . ثم لما حل الوقت المناسب ، كان الله أيضاً هو الذى بدأ ، فقابله فى طريق دمشق ، وظهر له بنور مبهر ودعاه (أع ٩) .","* * *","* وجميع رسل السيد المسيح ، هو الذى دعاهم ، بل قال لهم :",{h:"« لستم أنتم اخترتمونى ، بل أنا اخترتكم ... » (يو ١٥ : ١٦) ."},"وأكمل قائلاً « وأقمتكم لتذهبوا وتأتوا بثمر ويدوم ثمركم » . وكما اختار الرسل الاثنى عشر (مت ١٠ : ١) ، كذلك اختار السبعين أيضاً (لو ١٠ : ١) .","ما فكر بطرس واندراوس أن يتبعا المسيح ، وهما مشغولان بشباكهما . وما فكر متى أن يكون أحد تلاميذ المسيح ، وهو موظف فى مكان الجباية ، وهكذا بالنسبة إلى الباقين ... ولكن الرب هو الذى بدأ بتكوين علاقة ودعا كل هؤلاء ...","« الذين سبق فعرفهم ، سبق فعينهم ... وهؤلاء دعاهم أيضاً » (رو ٨ : ٢٩ ، ٣٠) ."],58:["هو الذى يناديك من حيث لا تعلم ، وحيث لا تتوقع ، ويقول لك « هلم ورائى » . وهو الذى يقودك فى الطريق ، ويمنحك القوة ... المهم أن يكون قلبك مستعداً .","* * *",{h:"إن ظهورات الرب لتلاميذه بعد القيامة ، تعطينا فكرة جميلة عن الله الذى يبدأ ..."},"* فى تلك الفترة ، كان السيد هو الذى يذهب إلى تلاميذه ، وما كانوا هم الذين يأتون إليه . ولعل من الأشياء الجميلة التى تستدعى التأمل : أنه ظهر لهم وهم جلوس فى العلية ، والأبواب مغلقة (يو ٢٠ : ١٩) .",{h:"هل جربت وقتاً ، كانت فيه أبوابك مغلقة ، ثم اخترقها المسيح ليتحدث إليك ؟ !"},"معقول ومقبول ، أن يتحدث المسيح إلينا ، حينما تكون أبوابنا مفتوحة له (رؤ ٣ : ٢٠) . أما أن يدخل و يظهر و يتحدث إلينا ، والأب بواب مغلقة ، فهذا هو الأمر العجيب الذى يناسب محبته .","على أنه بالنسبة إلى الرسل ، كانت أبوابهم مغلقة بسبب الخوف ، لا بسبب الرفض ...","* وظهر السيد لتلاميذه أيضاً ، وهم منهمكون فى أمور مادية :","الأصحاح الأخير من إنجيل يوحنا ، يشرح لنا كيف ظهر السيد المسيح لسبعة من تلاميذه كانوا يصيدون السمك ، ومنهم بطرس ويوحنا ... فقد حدث أنهم رجعوا إلى صيد السمك (يو ٢١ : ٣) . ومع ذلك ظهر لهم الرب أثناء الصيد . وفى ذلك يقول القديس أغسطينوس « إن المسيح ظهر لبطرس ، ليس وهو منهمك فى صيد النفوس . إنما ظهر له المسيح ، وهو منهمك فى صيد السمك ... » .","لعل فى ذلك تعزية لنا ، أن الرب مستعد أن يظهر لنا ، ليس فقط ونحن فى عمل روحى ، بل حتى ونحن فى العمل المادى أيضاً ... هو الذى يبدأ : يظهر ، ويبدأ الحديث ، لصالحنا .","* وظهر أيضاً لتلميذين ، وهما لا يعرفانه ...","إنهما تلميذا عمواس . ظهر لهما وهما لا يعرفانه . بل لما سألهما عن موضوع حديثهما ، أجاباه « هل أنت متغرب وحدك فى أورشليم ، ولم تعلم الأمور التى حدثت فى تلك الأيام » ..."],59:["وبدأ المسيح من موسى ومن جميع الأنبياء ، يفسر لهما الأمور المختصة به فى جميع الكتب (لو ٢٤ : ١٨ ـ ٢٧) ... وأخيراً انفتحت أعينهما وعرفاه (لو ٢٤ : ٣١) .","إن كنت بعد لم تعرفه ، هو مستعد أن يظهر لك ، ويكشف لك ذاته ، ويفسر لك الأمور المختصة به ... ويجعل قلبك ملتهباً فيك ، وهو يوضح لك الكتب (لو ٢٤ : ٣٣) . هو الذى يبدأ ...","* * *",{h:"حتى فى التوبة ، غالباً ما يبدأ الله عمله فينا . وكل ما يطلبه أن نتجاوب معه ."},"هو الذى بدأ فأعطانا الضمير ، وأعطانا التمييز . وأيضاً روحه القدوس يبكتنا على خطية (يو ١٦ : ٨) ... كل ذلك لكى يدفعنا إلى التوبة .","وإن كنا متراخين ، يرسل لنا كلمة تحثنا ، عظة مؤثرة ، كتاباً نافعاً .",{h:"وتتابعنا زيارات النعمة ، تدفعنا إلى التوبة ."},"وربما يسمح الله لنا بمرض أو ألم ، ليجعلنا نفيق من غفلتنا ، أو يسمح بحادث معين يكون له تأثيره . أو يتكلم فى قلوبنا خلال تأثرنا بوفاة أحد أحبائنا . وهكذا إلى سائر الوسائل التى نشعر فيها أن الله ينخس قلوبنا لنتوب . إنما المهم أن نتجاوب ، ولا نرفس مناخس (أع ٩ : ٥) .","أترانا نستطيع أن نصل إلى التوبة ، بمجرد مجهودنا الخاص ؟ كلا ، فالرب يقول :",{h:"بدونى لا تقدرون أن تعملوا شيئاً (يو ١٥ : ٥) ."},"لنا رجاء إذن أنه يعمل فينا لأجل خلاصنا . حتى إن كنا لا نريد ، نرجو أن يمنحنا هذه الإرادة . ألم يقل القديس بولس الرسول « ... لأن الله هو العامل فيكم أن تريدوا وأن تعملوا لأجل المسرة » (فى ٢ : ١٣) لذلك « تمموا خلاصكم بخوف ورعدة » ...","* * *",{h:"داود النبى أخطأ ، وما كان يشعر بخطورة خطيئته :"}],60:["وظلت خطية تقودة إلى أخرى ، وهو يتمادى ولا يشعر بما هو فيه ، إلى أن أرسل الله إليه ناثان النبى ، فضرب له مثلاً شعر به بعمق جرمه ... ومن هنا بدأت معه قصة التوبة والدموع والندم ، والتى سجلها فى كثير من مزاميره . وكان الله هو البادىء ليقوده إلى انسحاق النفس ...",{h:"مثال آخر هو لوط فى أرض سادوم ."},"لقد اختار لوط الأرض المعشبة ، مع بيئتها الخاطئة العثرة ، وسكن فى سادوم وتفادى فزوّج بناته من أهلها . ويقول القديس بطرس فى رسالته الثانية عن عمل الرب معه « وأنقذ لوطاً البار مغلوباً من سيرة الأردياء فى الدعارة . إذ كان البار بالنظر والسمع ـ هو ساكن بينهم ـ يعذب يوماً فيوماً نفسه البارة بالأفعال الأثيمة » (٢بط ٢ : ٧ ، ٨) .","أوقع الله أهل سادوم فى السبى ، ولم يأخذ لوط درساً . وبعد أن أنقذه ابرآم ، عاد مرة أخرى إلى سادوم . ولما أراد الله حرق المدينة أرسل ملاكين يعجلان لوطاً للخروج منها « ولما توانى أمسك الملاكان بيده وبيد امرأته وبيد ابنتيه ، لشفقة الرب عليه ، وأخرجاه ووضعاه خارج المدينة ... » (تك ١٩ : ١٦) .","ثق أن الله مستعد أن يعمل معك كما عمل مع لوط ، ويخرجك من أرض الخطية فعليك أن تستسلم لقيادته ، ولا تنظر إلى الوراء كما فعلت امرأة لوط ...","* * *",{h:"صلّ إذن وقل : اعمل يارب معى . ولا تنتظر حتى أبدأ أنا ، فربما لا أبدأ !"},"ابدأ معى كما فعلت مع هؤلاء وغيرهم . خذنى من سادوم اخرجنى منها ، بواسطة ملائكتك القديسين . وليظل يدوى فى أذنى صوتك الحنون « اهرب لحياتك . ولا تقف فى كل الدائرة .... لئلا تهلك » (تك ١٩ : ١٧) .","أما نحن فليتنا نغنى مع المرتل « نجت أنفسنا مثل العصفور من فخ الصيادين . الفخ انكسر ونحن نجونا . عوننا من عند الرب » (مز ١٢٣) .",{h:"أنت يارب الذى كسرت الفخ . إذ لا يستطيع عصفور أن يكسر فخ الصيادين ..."}],61:["هل كانت مريم القبطية تفكر فى التوبة ؟ ! كلا ، بل كانت ماضية لارتكاب مزيد من الخطايا . ثم تدخل الله فى حياتها ، وحدثت معجزة منه أيقظتها ودفعتها إلى التوبة . واستمر عمل الله معها حتى تحولت إلى ناسكة سائحة ...","وبالمثل تدخل الله فى حياة أوغسطينوس وبيلاجية وسارة ، وحوّل دفة الحياة إلى طريقه هو . وكان هو البادىء ...","* * *",{h:"حتى فى الخدمة ، هو الذى يدعو ويرسل ، ويمنح قوة من روحه القدوس لنعمل بها ، بل قد يعد لنا كل شىء ويقول لنا :"},"« أنا أرسلتكم لتحصدوا ما لم تتعبوا فيه » (يو ٤ : ٣٨) .","« آخرون تعبوا ، وأنتم دخلتم على تعبهم » ... كل شىء يعده لنا . حتى الكلمة : هو يمنحنا كلمة عند افتتاح فمنا (أف ٦ : ١٩) . وهو الذى يعطى التأثير للسامعين لكى يعملوا بما سمعوه ... فإن كان أحد يخاف الخدمة ، فليذكر دائماً عمل الله فيها ...","* * *",{h:"حتى الأبدية ، الله هو الذى يبدأ فيقول عن نصيبنا فيها :"},{h:"« أنا ماض لأعد لكم مكاناً ... » (يو ١٤ : ٢) ."},"مباركة هى محبتك يارب . ليتك تعد لنا هذا المكان . حتى تأتى وتأخذنا إليك . وحيثما تكون أنت ، نكون نحن أيضاً (يو ١٤ : ٣) ."],62:[{h:"الفصل الثالث عشر"},{h:"نهاية أمر خير من بدايته"}],63:["فى قصة القيامة نرى كيف أن تعب التلاميذ وخوفهم فى يوم الجلجثة والصلب ، قد انتهى بفرحهم واطمئنانهم فى يوم القيامة .","ولعل هذا يذكرنا بآية هامة وردت فى سفر الجامعة :",{h:"« نهاية أمر خير من بدايته » (جا ٧ : ٨) ."},"طبعاً على شرط أن تكون نهاية طيبة ...","والنهاية الطيبة تجعل الإنسان ينسى كل تعبه ، ولا يذكر سوى هذه النهاية المفرحة التى تعزيه . تماماً كما أن قيامة السيد المسيح محت من مشاعر التلاميذ كل ما قاسوه فى يوم الصلب .","* * *",{h:"وهكذا نرى الناس دائماً يبحثون عن النهاية ، ويهتمون بها ."},"وذلك فى كل نواحى الحياة : تروى قصة ، أو تشاهد رواية ، وكل ما يهمك هو كيف انتهت القصة أو الرواية ... قضية ، أو خلاف بين زوجين ، أو حادث فى الطريق ... المهم كيف انتهى ؟ ... وقد يشرح لك الراوى تفاصيل ما حدث ، ولكنك تسأل فى لهفة : والنهاية ؟ ... نفس الوضع فى أية مباراة ، أو أية منافسة ، أو أية حرب بين دولتين ، أو أى حوار أو تفاوض ... السؤال المهم هو : وماذا كانت النهاية أو النتيجة ...","* * *","حتى فى الحياة الروحية : الأهمية كلها هى فى النهاية ... ولذلك فإن القديس بولس الرسول يقول عن رجال الله :",{h:"انظروا إلى نهاية سيرتهم ، فتمثلوا بإيمانهم (عب ١٣ : ٧) ."},"إنه نفس الوضع الذى تذكره الكنيسة فى أعياد القديسين ... قليل هم الذين"],64:["تعيد الكنيسة لميلادهم : كالعذراء (أول بشنس) والمعمدان (٣٠ بؤونة) والأنبا شنوده رئيس المتوحدين (٧ بشنس) . ولكن كل أعياد القديسين تقريباً هى فى أيام نياحتهم أو أيام استشهادهم ، فى نهاية سيرتهم ، حيث اكملوا جهادهم بسلام .",{h:"لأن هناك أشخاصاً بدأوا بداية طيبة ، وانتهوا بنهاية سيئة ."},"من أمثلة أولئك ديماس تلميذ بولس الرسول ، الذى كان يذكره ضمن أعمدة الكنيسة مع القديسين مرقس ولوقا واسترخس . ولكنه قال عنه أخيراً « ديماس تركنى لأنه أحب العالم الحاضر » (٢تى ٤ : ١٠) . وقال أيضاً عن أمثال ديماس هذا « ... كثيرين ممن كنت اذكرهم لكم مراراً ، والآن أذكرهم أيضاً باكياً ، وهم أعداء صليب المسيح ، الذين نهايتهم الهلاك ... ومجدهم فى خزيهم » (فى ٣ : ١٨ ، ١٩) .",{h:"عجيب عن هؤلاء ، أن نهايتهم الهلاك ! إذن المهم هو النهاية ."},"لأن كثيرين بدأوا بالروح ، وكملوا بالجسد ، مثل أهل غلاطية ...","وسليمان الحكيم ، بدأ بحكمة فائقة ، وانتهى بالأصنام (١مل ١١) ... نرجو أن تكون له نهاية أخرى فاضلة ، وهى زهده الذى ورد فى سفر الجامعة دليلاً على توبته . وهنا نقول « نهاية أمر خير من بدايته » أو هكذا قال الوحى الإلهى على فم سليمان ...","* * *",{h:"قصص نهايات طيبة"},"ويحكى لنا الكتاب قصص نهايات طيبة ، نذكر من بينها :",{h:"١ ـ قصة يوسف الصديق ، التى بدأت بخيانة اخوته وقسوتهم ، وبيعهم له كعبد ، واشتغاله خادماً فى بيت فوطيفار ، ثم تلفيق تهمة له ، والقائه فى السجن ."},"ولكن المهم هو النهاية ، التى صار فيها أباً لفرعون (تك ٤٥ : ٨) والمتسلط على كل أرض مصر ، وفرحته بلقاء أبيه واخوته الذين بكوا بين يديه طالبين المغفرة . حقاً إن نهاية أمر خير من بدايته :"],65:[{h:"٢ ـ نفس الوضع نقوله عن دانيال والثلاثة فتية :"},"دانيال الذى القى فى جب الأسود . ولكن انتهى الأمر بأن الله أرسل ملاكه فسد أفواه الأسود (دا ٦ : ٢٢) . والثلاثة فتية ألقوهم فى أتون النار ، ولكن انتهى الأمر بأن رأوهم وسط النار بلا أذى ، وقد سار معهم رابع شبيه بابن الآلهة (دا ٣ : ٥) .","وانتهى الأمر فى القصتين بعبادة الإله الحق ، وتمجيده فى كل المملكة أكثر من كل آلهة الأمم . حقاً إن نهاية أمر خير من بدايته .","* * *",{h:"٣ ـ ونفس الكلام نقوله عن أيوب الصديق الذى تعرض لتجربة قد تفوق احتمال البشر ، وفقد أولاده وماله وصحته وكرامته ... وبلغت التجربة ذروتها . ولكن ماذا كانت النهاية ؟"},"يقول الكتاب « ورد الرب سبى أيوب . وزاد الرب على كل ما كان لأيوب ضعفاً ... وبارك الرب آخرة أيوب أكثر من أولاه ... وعاش أيوب بعد هذا مائة وأربعين سنة . ورأى بنيه وبنى بنيه إلى أربعة أجيال ... » (أى ٤٢ : ١٠ ـ ١٧) ... حقاً إن نهاية أمر خير من بدايته .","* * *","ويعوزنى الوقت إن تحدثت عن النهايات الطيبة التى ذكرها الكتاب فى تقديم اسحق محرقة ، وفى بناء نحميا لأسوار أورشليم بعد أن تهدمت واحرقت أسوار المدينة بالنار (نح ١) ، وكيف نصره الله أخيراً . كذلك قصة المسبيين فى بابل ، وكيف عادوا أخيراً ، بعد أن بكوا على أنهار بابل ، وعلقوا قيثاراتهم على الصفاف ، وقالوا كيف نسبح الرب فى أرض غريبة (مز ١٣٦) كلها نهايات طيبة ، نقول فيها « نهاية أمر خير من بدايته » .","* * *",{h:"نفس الوضع نقوله أيضاً فى كل قصص التائبين ."},"كلما نذكر حياة القديس أوغسطينوس ، وكيف بدأ حياة مستهترة ماجنة ، وكذلك القديس موسى الأسود ، وكيف بدأ قاتلاً قاسياً . والقديسة مريم القبطية ، والقديسة بيلاجية ، والقديسة سارة ، وكيف بدأن بحياة الزنا ، وانتهت حياتهن كقديسات عظيمات . ألسنا نقول عن حياة كل من هؤلاء التائبين والتائبات « نهاية أمر خير من بدايته » ..."],66:[{h:"إذن على كل واحد أن يبحث فى كل أمر : كيف تكون النهاية ؟"},"كل طريق تسلك فيه اسأل نفسك : ما نهاية هذا الطريق ؟ وكذلك فكر بنفس التفكير فى كل مشروع تبدؤه ، وكل علاقة تكونها مع آخرين ...","شاب مثلاً يحب فتاة ليست من دينه ، عليه أن يفكر ماذا تكون نهاية هذه العلاقة ؟ ما مصيرها وما مصيره ؟ ! إنسان يختلف مع زوجته ، ويحتدم الخلاف بينهما ، بلا صلح ، فليفكر أيضاً : ماذا ستكون نهاية هذا الخلاف ، وإلى أين يقوده ؟ ! شاب يبدأ التدخين ، ولو بسيجارة واحدة مجاراة لزملائه ، أو تجربة لطعم التدخين ، عليه أن يفكر كثيراً : ما نهاية هذا الأمر .",{h:"وبنفس الطريقة فى كل ممارسة يمكن أن تتحول إلى عادة :"},"يسأل الإنسان نفسه : وما نهاية هذه الممارسة ؟","بل كل لفظة يقولها ، وكل غضب يشتعل فى داخله ، فليسأل نفسه : وما النهاية ؟ وماذا ستكون ردود الفعل وتصرفات الطرف الآخر ؟ وإلى أين ينتهى به الغضب ؟ وإلى أين تنتهى به الكلمة غير المنضبطة .","* * *","ذلك أيضاً فى كل مشكلة تحل بك ، لا تيأس ولا تضطرب ، بل قل لنفسك « نهاية أمر خير من بدايته » .","قل لنفسك « مصيرها تنتهى » ... هذا الموضوع لابد ستكون له نهاية . والنهاية فى يد الله . والله رؤوف وحنون . وبلا شك « نهاية الأمر ستكون خيراً من بدايته » ...","وهذا اللون من التفكير ، لا يكون فقط بالنسبة إلى مشاكلك أنت وحدك ، وإنما أيضاً بالنسبة إلى كل مشكلة أو ضيقة تحل بمعارفك واصدقائك ، بل وبالكنيسة نفسها ...","* * *",{h:"لعل فكر الشهداء والمعترفين أيضاً كانت تدور به هذه الآية :"},"ما نهاية العذاب والموت ؟ أليس هو الوصول إلى العالم الآخر ؟ إلى الفردوس ، إلى الأكاليل ، إلى النعيم الأبدى فى نهاية الأمر كله . وهذا بلاشك أفضل جداً . إذن أين"],67:["شوكتك يا موت ؟ لقد زالت . ونهاية الأمر خير من بدايته ...","الأبدية بلاشك هى نهاية أفضل ...","العالم الآخر هو عالم أفضل ، حيث « ما لم تره عين ، ولم تسمع به أذن ، ولم يخطر على بال إنسان ، ما أعده الرب لمحبى إسمه القدوس » (١كو ٢ : ٩) ... والجسد الروحانى السماوى الذى نعيش به بعد القيامة (١كو ١٥ : ٤٤ ـ ٤٩) لاشك إنه أفضل من جسدنا المادى هذا ... وفى الأبدية عشرتنا مع الله وملائكته وقديسيه ، هى أفضل بما لا يقاس من عشرة هذا العالم الحاضر . ووجودنا فى عالم كله خير ، هو أفضل من وجودنا هنا ، حيث يوجد الخير والشر ، وحيث يعيش الزوان إلى جوار الحنطة ...",{h:"إذن الأبدية أفضل . فلماذا نخافها ؟ ولماذا لا نستعد لها ."},"* * *","ولعلنا فى الضيقات نذكر العتاب الذى قدمه أرمياء النبى لرب المجد قائلاً له « أبر أنت يارب من أن أخاصمك . ولكن اكلمك من جهة أحكامك : لماذا تنجح طريق الأشرار ؟ اطمئن كل الغادرين غدراً ؟ ! » (ار ١٢ : ١) .","ويجيب القديس أغسطينوس عن هذا السؤال بالنظر إلى النهاية : فيقول إن الأشرار كالدخان ، يرتفع دائماً إلى فوق . وفيما يرتفع وتتسع رقعته يتبدد . بينما النار تبقى اسفل ، ولكنها ثابتة وقوية .","لذلك فعل الإنسان أن يهتم بالنهاية قبل كل شىء ، مهما كان بدء الأمر فيه تعب أو ضيق ...",{h:"نهاية طيبة مع بداية متعبة"},"الحياة الروحية ، تبدأ بالباب الضيق والطريق الكرب (متى ٧ : ١٣ ، ١٤) . ولكن هذا الضيق يؤدى إلى النعيم الأبدى بينما « واسع الباب ، ورحب الطريق ، الذى يؤدى إلى الهلاك » ... ولذلك ما أجمل قول المرتل :",{h:"« الذين يزرعون بالدموع ، يحصدون بالابتهاج » (مز ١٢٥) ."}],68:[{h:"الفصل الرابع عشر"},{h:"تستطيع كل شىء ولا يعسر عليك أمر (أى ٤٢ : ٢)"},"ألقيت فى الكاتدرائية الكبرى بالقاهرة مساء الجمعة ١٩٧٦/٩/٢٤م ."],69:["إن أعمال الله عجيبة ، تدل على قوته الفائقة للعقل ... يقف أمامها الإنسان متذهلاً ، لا يملك إلا أن يردد عبارة قالها من قبل القديس أيوب الصديق :",{h:"« علمت أنك تستطيع كل شىء ولا يعسر عليك أمر » (أى ٤٢ : ٢) ."},"إننا نقرأ فى الكتاب المقدس عجباً ... من قصص المعونة ، وقصص التوبة وتغيير الحياة ، ومن قصص الإيمان أيضاً ... حتى ليقف الإنسان متذهلاً ، يقول من أعماقه : من كان يظن ، أن مثل هذا سيحدث ؟ ...",{h:"من كان يظن ؟"},"خذوا كمثال الطفل موسى ...",{h:"الطفل موسى"},"طفل صغير ، ولد فى عصر مظلم ، وكان محكوماً عليه بالموت قبل أن يولد ، وقد أخفاه أبواه خوفاً لمدة ثلاثة أشهر ، وإذ لم يستطيعا اخفاءه أكثر ، وضعاه فى سفط (سبت) ، وألقياه عند حافة النهر ، فى المياه ....",{h:"من كان يظن أن هذا الطفل المحكوم عليه بالموت ، والملقى فى الماء ، يصير نبى الله العظيم ، وكليم الله ... ؟ !"},"يصير موسى النبى ، الذى نسبت الشريعة إلى اسمه ، فيقال شريعة موسى ، وناموس موسى ... بل يصير رجل المعجزات والآيات ، الذى شق البحر الأحمر بعصاه ، وضرب الصخرة فتفجرت ماء ، وأنزل من السماء المن والسلوى .. !","من كان يظن أن هذا المحكوم عليه بالموت من فرعون ، يعيش أربعين سنة فى قصر فرعون ، كأحد الأمراء ، ويدعى ابن ابنة فرعون ... ويصبح فيما بعد القوة الجبارة التى يعمل لها فرعون ألف حساب ..."],70:["يصير الإنسان الذى يصرخ أمامه فرعون ويقول أخطأت (خر ٩ : ٢٧) ، ويضرع إليه أكثر من مرة أن يصلى من أجله ، ليرفع الرب عنه الضربات .","من كان يظن أن الطفل الصغير الملقى فى الماء ، يصبح مصيره هكذا ؟ ولكنها يد الله حينما تتدخل فى الأحداث ، وتدبر مصائر الناس ... إنه الله الذى قال له أيوب الصديق « علمت أنك تستطيع كل شىء ، ولا يعسر عليك أمر » .",{h:"قصة الطفل موسى تعطينا درساً فى الرجاء ، أن الله يستطيع أن يحول الضعف إلى قوة ، ويغير المصائر حسبما يشاء ..."},"حقاً إن الله يستطيع أن يعمل أعمالاً عجيبة لا تخطر على بال .","إننا ننظر إلى الحاضر فقط . وقد نرى فيه أموراً صعبة معقدة ، تجلب الحزن أو اليأس . أو قد نرى مخاطر ليس من السهل الخروج منها ... بينما يكون المستقبل ، الذى يمسكه الرب فى يده ، هو غير الذى نراه فى الحاضر ، غيره تماماً ، وربما عكسه تماماً .",{h:"ليتنا بدلاً من أن ننظر إلى الحاضر المتعب الذى أمامنا ، ننظر بالرجاء إلى المستقبل المبهج الذى فى يد الله ..."},{h:"الأرض الخربة"},"* هذا الرجاء وضعه الله أمامنا ، منذ الآيات الأولى التى تتحدث عن قصة الخليقة ، حيث يقول الوحى الإلهى :",{h:"« كانت الأرض خربة وخالية ، وعلى وجه الغمر ظلمة » (تك ١ : ٢) ."},"إنها صورة كئيبة للطبيعة من أول القصة . ولكن ليس من الصالح أن نقف عند حدود هذه الصورة ، فالقصة لم تتم فصولها ...","فمع وجود هذه الصورة الكئيبة ، كان هناك ما يبعث الرجاء ... كانت هناك عبارة « وروح الله يرف على وجه المياه » وماذا أيضاً ؟ « وقال الرب ليكن نور ، فكان نور ، ورأى الله النور أنه حسن » (تك ١) ."],71:[{h:"وهكذا فتحت أمام الصورة الكئيبة المظلمة نافذة من نور ."},"وإذا كل شىء قد تغير .. وبدأت يد الله تعمل : تنظم هذه الطبيعة ، وتنسقها ، وتخلق فيها الحياة ، وتضع لها النظم ، وتلبسها ثوباً من الجمال والبهاء ، وينظر الله إلى كل ما عمله ، فإذا هو حسن جداً ...","من كان يظن أن الطبيعة الخربة ، الخاوية ، المغمورة بالمياه ، المغطاة بالظلمة ، تتحول إلى هذا الجمال الذى نعيش فيه : الأشجار والأزهار والأثمار ، والبحار والأنهار ، والطيور والفراشات ذات الألوان ، وجمال السماء والقمر والنجوم ، والجبال والتلال والبحيرات ، جمال يتغنى به الشعراء ، ويبدع فى رسمه الفنانون .",{h:"إن قصة الطبيعة فى نشأتها ، فيها رمز ، وفيها رجاء ."},"إنها رمز لكل حياة خربة وخالية ومظلمة ، وتنتظر فى رجاء قول الرب « ليكن نور » ... تنتظر يد الله فى الأيام الستة ... حتى تتكامل صورتها ، وتنتهى إلى عبارة « حسن جداً » ...","فلا تقف يا أخى عند عبارة « خربة وخالية » وتكتئب .. إنما تطلع إلى المستقبل فى رجاء ، وانتظر الرب ... وفى كل يوم يمر عليك . كلما يقول الوحى الإلهى « وكان مساء وكان صباح » ، اهتف من كل قلبك « يا جميع الأمم صفقوا بأيديكم . هللوا لله بصوت الابتهاج » (مز ٤٦ : ١) ، قد علمت يارب أنك تستطيع كل شىء ، ولا يعسر عليك أمر ...",{h:"الله قادر أن يغير كل شىء ... إلى أفضل ، وإلى العكس ."},{h:"وليس المهم عنده البدايات ، إنما ما تنتهى إليه الأمور ."},{h:"العاقر"},"من الآيات الجميلة فى الرجاء ، نشيد العاقر فى سفر اشعياء :","« ترنمى أيتها العاقر التى لم تلد . أشيدى بالترنم . لأن بنى المستوحشة (التى ليس"],72:["لها زوج) أكثر من بنى ذات البعل ... أوسعى مكان خيمتك ، ولتبسط شقق مساكنك ... لأنك تمتدين إلى اليمين وإلى اليسار . ويرث نسلك أمماً ، ويعمر مدناً خربة . لا تخافى لأنك لا تخزين » (اش ٥٤ : ١ ـ ٤) .",{h:"هناك إذن رجاء للعاقر ، ليس فقط أن تلد ، إنما بالأكثر أن يرث نسلها مدناً ."},"هذه العاقر ترمز إلى الأمم الذين كانوا غرباء عن الله ، مستوحشين .","وترمز إلى كل نفس خاطئة بعيدة عن شركة الروح وثمار الروح . هذه لم يعطها الرب مجرد رجاء أن يكون لها نسل وثمر ... إنما قال لها بالأكثر « وسعى خيامك .. ممتدين يميناً ويساراً » .",{h:"ليس فقط يكون لك صبر ورجاء ، إنما ترنمى ."},"افرحى بالرجاء . ليس بعقمك ، إنما بالوعد الذى سيتحقق .","حقاً يارب أنك تستطيع كل شىء ، ولا يعسر عليك أمر .",{h:"قصص معونة"},"* من كان يظن أن داود الطفل سينتصر على جليات الجبار ؟",{h:"ولكن داود كان عنده الرجاء ، الذى به قال لجليات : اليوم يحبسك الرب فى يدى .. » (١صم ١٧ : ٤٦) ."},"ولولا هذا الرجاء ما تقدم داود فى ثقة لمحاربته . ولم يخف مطلقاً ، بينما كان الجيش كله خائفاً .","* * *",{h:"وبالرجاء دخل مارمرقس كارزاً فى مصر ."},"لم يكن له فيها شعب ولا كنيسة . وكانت هناك العبادات الفرعونية ، واليونانية ، والرومانية ، والديانة اليهودية ، والفلسفة الوثنية ، ومدرسة الاسكندرية . وسيف الدولة"],73:["الرومانية الحاكمة ، ودسائس اليهود ...","من كان يظن أن مرقس الشاب ، ينتصر على كل المعوقات ، وينشر الإيمان فى كل مصر ؟ حقاً إن الله يستطيع كل شىء ، ولا يعسر عليه أمر . ويعجبنى هنا قول الكتاب :",{h:"من أنت أيها الجبل العظيم ؟ أمام زربابل تصير سهلاً (زك ٤ : ٧) ."},"* * *",{h:"حقاً ، إننا بالرجاء نرى كل شىء سهلاً ."},"بالرجاء ، نرى طريقاً مفتوحاً لنا داخل البحر . ونسمع قول موسى النبى : الرب يقاتل عنكم وأنتم تصمتون (خر ١٤ : ١٤) .","بالرجاء نثق أن عصا اليشع ، إن وضعت على الغلام سيقوم .","بالرجاء نثق أننا سندخل الأرض ، حتى إن تهنا فى البرية أربعين عاماً .","بالرجاء صلى يونان وهو فى بطن الحوت . كان له رجاء أنه سيخرج و يعود يرى هيكل الله مرة أخرى (يون ٢ : ٤) .","* * *",{h:"بالرجاء بطرس لم ييأس بعد إنكاره ."},"كان له رجاء أن الرب سيغفر ، ويقبله كما كان رسولاً ...","حقاً من كان يظن أن هذا الذى خاف ، وانكر الرب أمام جارية ، سيمكنه أن يقف أمام رؤساء الكهنة ، ويقول لهم فى شجاعة « ينبغى أن يطاع الله أكثر من الناس » (أع ٥ : ٢٩) . ويحتمل من أجل الرب ، ويكرز ويموت شهيداً .","* * *",{h:"إن قصص كرازة الرسل ـ يعطينا دروساً فى الرجاء ."},"اختار الله جهال العالم ليخزى بهم الحكماء (١كو ١ : ٢٧) .","وهذه الفئة القليلة الضئيلة ، استطاعت أن تقف أمام جبروت الدولة الرومانية ودسائس اليهود . والذين لا قول لهم ولا كلام ، إلى أقطار المسكونة بلغت أقوالهم (مز ١٩ : ٣ ، ٤) . وفى حوالى ٣٤ عاماً ، استطاعوا أن ينشروا المسيحية فى كل الشرق"],74:["الأوسط ، ومصر ، وتركيا ، واليونان ، وروما ، وبقاع كثيرة فى أوروبا وآسيا وأفريقيا ...","ألا يعطينا هذا رجاء فى عمل الله فينا لأجل ملكوته .","* * *",{h:"من كان يظن أن نحميا الأسير ، يأخذ معونة يعيد بها بناء سور أورشليم ؟"},"ولكن الله لا يعسر عليه أى أمر .","حتى إن ألقى دانيال فى جب الأسود ، يمكن أن يرسل الله ملاكه فيسد أفواه الأسود (دا ٦ : ٢٢) ... حتى إن ألقى الفتية فى أتون النار ، لا يصيبهم ضرر ، و يتمشى الرب معهم وسط النار (دا ٣ : ٢٥) ... حتى إن ألقى يوسف فى السجن ، يخرج منه للحكم .","* * *",{h:"من كان يظن أن شاول الطرسوسى مضطهد الكنيسة ، يتحول إلى أكبر كارز بالمسيحية ، ويتعب أكثر من جميع الرسل (١كو ١٥ : ١٠) ."},"ومن كان يظن أن أريانوس والى أنصنا ، أقسى ولاة ديوقلديانوس وأعنفهم فى تعذيب الشهداء ، يؤمن أخيراً و يصير شهيداً ... وكذلك لونجينوس الجندى الذى طعن المسيح بالحربة ....","علمت يارب أنك تستطيع كل شىء ، ولا يعسر عليك أمر ....",{h:"حقاً ، إنه من أعظم معجزات الرب ، قدرته على تغيير النفوس ."},"* * *",{h:"إن قصص التوبة تعطينا رجاء عجيباً . وهى كثيرة جداً ."},"من كان يظن أن مريم المجدلية التى أخرج الرب منها سبعة شياطين (لو ٨ : ٢) ، تصير مبشرة للرسل بالقيامة ؟","من كان يظن أن مريم القبطية الزانية تصير من السواح ؟ ونفس الأسلوب نتحدث به عن أوغسطينوس وموسى الأسود وغيرهما .","* * *"],75:[{h:"كل شىء مستطاع"},"كون أن الله يستطيع كل شىء (مت ١٩ : ٢٦) ، هذا أمر طبيعى ...","ولكن هوذا بولس الرسول يقول « استطيع كل شىء فى المسيح الذى يقوينى » (فى ٤ : ١٣) . ولكن أكبر آية تدعو إلى الرجاء هى :",{h:"« كل شىء مستطاع للمؤمن » (مر ٩ : ٢٣) ."},"بهذا الرجاء ننال قوة ننتصر بها فى حياتنا .","أما الشيطان فطريقته أن يدفع الناس إلى اليأس ، وإلى الخوف ، والتردد ، والشعور بالضعف والعجز ، لكى يشل حركتهم ... ويشدهم بثقل الصليب ، ويخيفهم من الباب الضيق والطريق الكرب ، حتى ما يستطيعون التقدم خطوة واحدة . أما أنت فقل مع بولس الرسول :",{h:"استطيع كل شىء فى المسيح الذى يقوينى ."},"الذى حوّل الطرسوسى يستطيع أن يحولنى . والذى منح التوبة لاوغسطينوس يمكنه أن يتوبنى . والذى أعان داود على جليات يمكنه أن يعيننى . والذى قبل المزدرى وغير الموجود يقبلنى .",{h:"الرجاء يعطى قوة على العمل ، وعدم التفكير فى الفشل ."},"إننا لا نعترف بالفشل إطلاقاً ، مادامت يد الله معنا .","كل شىء يدعو لليأس ، نضع أمامه قوة الله غير المحدودة ، وتدخل الله بكل محبته لتغيير الأمور إلى أفضل ..",{h:"ما أكثر قول الله : لا تخف . لا تخافوا ..."},"إنه لم يسمح لموسى أن يخاف من ملاقاة فرعون (خر ٤) . ولم يسمح لأرميا أن يخاف لصغر سنه . وقال ليشوع بن نون بعد موت موسى النبى « لا يقف إنسان فى وجهك كل أيام حياتك ... لا أهملك ولا أتركك . تشدد وتشجع ... لا ترهب ولا"],76:["ترتعب ، لأن الرب إلهك معك » (يش ١ : ٥ ، ٩) ... إن إيمانك بعمل الله معك يعطيك رجاء ثم انظر إلى هذا الوعد العجيب جداً ، فى قول الرب :",{h:"« من يؤمن بى ، فالأعمال التى أنا أعملها ، يعملها هو أيضاً ، ويعمل أعظم منها » (يو ١٤ : ١٢) ."},"من نحن يارب أمام هذا الوعد ؟ إنه أكبر منا . ولكن عجيبة هى محبتك ووعودك . ولكننا نؤمن بمحبتك وبكرمك فى العطاء ، وتدخلك للمعونة ونؤمن أيضاً بأن الحرب للرب (١صم ١٧ : ٤٧) ، والله ليس لديه مانع أن يخلص بالكثير أو بالقليل (١صم ١٤ : ٦) .",{h:"الله قادر أن يغلب بجيش يشوع . وقادر أيضاً أن يغلب بحصاة داود ."},"مهما كنت ضعيفاً أو صغيراً ، الله قادر أن يعمل بك وفيك ، كما عمل فى ارميا الطفل ، وداود الصبى . واستخدم صموئيل الطفل ليبكت به عالى الكاهن العظيم (١صم ٣ : ١٠ ـ ١٨) .","مادامت الحرب للرب ، اعتمد عليه اذن ، وليكن رجاؤك فيه ، مهما وقفت ضدك خطية أو شهوة ، تجربة أو مشكلة . ومهما وقف ضدك الناس الأشرار .","وتذكر قصص رجال الله ، الذين تقووا من ضعف (عب ١١ : ٣٣ ، ٣٤) وصاروا اشداء فى الحرب ، وقهروا ممالك ...",{h:"هؤلاء هم جبابرة ، الذين لا يخافون ."},"لا تضعف . لا تهزك التجارب ولا الضيقات ، ولا الخطايا ولا الشهوات ، ولا الأعداء . كن كالبيت المبنى على الصخر ، الذى لم تقو عليه الأمطار ولا الرياح (مت ٧ : ٢٥) . كن كالجنادل التى فى مجرى النيل ، ثابتة لا تقوى عليها المياه .",{h:"ضع أمامك بعض الآيات التى تعزيك وتقويك ."},"« إن سرت فى وادى ظل الموت ، لا أخاف شراً لأنك أنت معى » (مز ٢٣ : ٤)"],77:["« إن يحاربنى جيش فلن يخاف قلبى . وإن قام علىّ قتال ، ففى هذا أنا مطمئن » (مز ٢٧ : ٣) « مراراً كثيرة حاربونى منذ صباى ، وأنهم لم يقدروا علىّ ... الرب صديق هو يقطع أعناق الخطاة » (مز ١٢٩ : ٢ ، ٤) . « الفخ انكسر ونحن نجونا . عوننا من عند الرب ... » (مز ١٢٤ : ٧ ، ٨) « دفعت لأسقط والرب عضدنى . قوتى من عند الرب » (مز ١١٧) .",{h:"تذكر سير القديسين الذين لم يخافوا مطلقاً ، ولم يفشلوا ..."},"(صفحة نصف نص ونصف رسم: رجل حزين جالس عند منضدة وشيطان صغير خلف شجرة)"],78:[{h:"الفصل الخامس عشر"},{h:"أبصرت باباً مفتوحاً فى السماء"}],79:["قال هذه العبارة وهو فى منفاه فى جزيرة بطمس ، وفى سفر الرؤيا الذى يقول فى أوله « أنا يوحنا أخوكم وشريككم فى الضيقة ، وفى ملكوت يسوع المسيح وصبره ... » (رؤ ١ : ٩) .","وعلى الرغم من أنه كان بعيداً عن كل التعزيات والمعونات البشرية ، إلا أن التعزيات الإلهية لم تبتعد عنه . فرأى السيد فى تلك الجزيرة ، وتسلم منه رسائل . ثم يقول بعد تلك الرؤيا :","« بعد هذا أبصرت ، وإذا باب مفتوح فى السماء ... وإذا عرش موضوع فى السماء ... » (رؤ ٤ : ١ ، ٢) . إنها تعزية عجيبة لهذا الرسول العظيم ، وهو فى ضيقته وفى منفاه ، تذكرنا بقول الرب لملاك كنيسة فيلادلفيا :",{h:"هأنذا قد جعلت أمامك باباً مفتوحاً ، ولا يستطيع أحد أن يغلقه » (رؤ ٣ : ٨) ."},"إنها كلمة من الله الذى يفتح ولا أحد يغلق ، ويغلق ولا أحد يفتح » (رؤ ٣ : ٧) .","كلمة عزاء ، كلما نتذكرها نمتلىء بالرجاء ، ونجد فرحاً بهذا الباب المفتوح فى السماء .","* * *",{h:"حقاً حينما تنغلق جميع الأبواب ، يبقى باب الله مفتوحاً ، ولا يستطيع أحد أن يغلقه ..."},"وهكذا يطمئن الإنسان مهما كانت جميع الأبواب مغلقة فى وجهه . فالله الحنون المحب بمكنه أن يفتح ، ولا أحد يغلق ... من أجل هذا يعيش أولاد الله فى فرح كامل ، لا تهتز ثقتهم بأية ظروف خارجية ضاغطة ..."],80:["ويقدم لنا الكتاب مثال داود النبى ، وهو مطارد من شاول الملك :","شاول بكل سلطانه ، وكل قسوته ، وكل حيله ، وكل كراهيته لداود ، كان يطارده من برية إلى أخرى ، ومن مغارة إلى أخرى ، يريد قتله ، ويحيك حوله المؤامرات . ومع ذلك حفظ الرب داود ، وبقى حياً . ومات شاول الملك دون أن يؤذيه .",{h:"وكذلك لم يقدر على إيذائه أبشالوم بكل خيانته ..."},"ذلك لأن الله كان قد جعل أمام داود باباً مفتوحاً ، دخل منه إلى المجد ، متذكراً خبراته الكثيرة فى قيام الأعداء ضده ، حتى أنه قال ذات مرة « يارب لماذا كثر الذين يحزنوننى ... كثيرون قاموا علىّ . كثيرون يقولون لنفسى : ليس له خلاص بإلهه » (مز ٣) . بل أنه قال : « أكثر من شعر رأسى ، الذين يبغضوننى بلا سبب » (مز ٦٩ : ٤) .","ونحن نسأل « وماذا فعلت أمام كل أولئك يا داود ؟ وهل حطموا حياتك ؟ ! » يجيب « الرب هو ناصرى . مجدى ورافع رأسى . بصوتى إلى الرب صرخت ، فاستجاب لى من جبل قدسه » (مز ٣) « نظرت ، وإذا باب مفتوح فى السماء » .","هؤلاء الكثيرون الذين قاموا على داود ، لم يستطيعوا أن يغلقوا هذا الباب المفتوح أمامه من الرب . ألست تستطيع أن تخرج من هذه القصة بقاعدة روحية وهى :","* * *",{h:"إن حياتك هى فى يد الله . وليست فى أيدى الناس ..."},"لقد قال عيسو « أقوم وأقتل يعقوب أخى » (تك ٢٧ : ٤١) . ولكنه لم يستطع لأن يعقوب أبصر ، وإذا باب مفتوح فى السماء . وقد رأى سلماً بين الأرض والسماء ، وملائكة الله صاعدة ونازلة عليها (تك ٢٨ : ١٢) . من أجل هذا حدث أنه فى رجوعه « ركض عيسو للقائه ، وعانقه ، ووقع على عنقه وقبله ، وبكيا » (تك ٣٣ : ٤) .",{h:"حقاً إن الله يستطيع أن يغير المواقف ، ويغير القلوب ."},"وكما قال الكتاب « إذا ارضت الرب طرق إنسان ، جعل أعداءه أيضاً يسالمونه »"],81:["(أم ١٦ : ٧) . وحتى إن لم يسالموه ، فلن يقدروا عليه ، كما قال الرب لأرمياء النبى « يحاربونك ولا يقدرون عليك ، لأنى أنا معك ، لأنقذك » (أر ١ : ١٩) .",{h:"ما أكثر الذين قاموا على رسل المسيح وتلاميذه !"},"قام ضدهم الكتبة والفريسيون والصدوقيون ، وكهنة اليهود ورؤساء كهنتهم وشيوخ الشعب ، وولاة الرومان وحكامهم ... وألقوهم فى السجون ، وجلدوهم . ولكن الله كان قد جعل أمامهم باباً مفتوحاً ، فانتشرت الكرازة فى كل مكان . و « الذين ليس لهم صوت ولا كلام ، إلى أقطار المسكونة بلغت أقوالهم » (مز ١٩ : ٣ ، ٤) ، حتى « الذين تشتتوا ، جالوا مبشرين بالكلمة » (أع ٨ : ٤) .","كانت كل الأبواب مغلقة أمامهم . ولكن باب الله كان مفتوحاً . وهذا يكفى . لذلك نصيحتى أقولها لكل إنسان تواجهه متاعب وضيقات وتعقيدات .","* * *",{h:"لا تنظر إلى الأبواب المغلقة ، إنما أنظر إلى المفتاح الذى فى يد الله ."},"إنه يستطيع أن « يفتح ولا أحد يغلق » . هو القادر على كل شىء ، وهو الذى يحبك ويحب لك الخير . كل الذين يقومون ضدك ، قوتهم محدودة كبشر . حتى الشيطان أيضاً ، قوته محدودة كمخلوق . أما الله فغير محدود ، وقوته غير محدودة .",{h:"لذلك فإن الله غير المحدود ، قال لبولس الرسول « تكفيك نعمتى » (٢كو ١٢ : ٩) ."},"إنها نعمة الله القادرة أن تفتح لك فى البحر طريقاً (خر ١٤) وتفجر لك من الصخرة ماء (خر ١٧ : ٦) ، وتهدم أمامك جبالاً . كما قال الرب عن معونته لعبده زربابل « من أنت أيها الجبل العظيم . أمام زربابل تصير سهلاً » (زك ٤ : ٧) .","* * *",{h:"يعوزنا الوقت إن تحدثنا عن قصص القديسين مع باب الله المفتوح :"},"هل أتحدث عن القديس أثناسيوس الرسول ، الذى قيل له « العالم كله ضدك يا أثناسيوس » ومع ذلك وقف ضد العالم المرطوقى وانتصر ، لأن الرب جعل أمامه باباً مفتوحاً ."],82:["أم أتحدث عن نحميا ، الذى فتح الله له باباً عجيباً ، فإذا بملك أممى يزوده بكل الامكانيات ليعيد بناء أورشليم ، ويتحول من إنسان فى السبى ، إلى حاكم فى مدينة الله ...","أم أتحدث عن لعازر الدمشقى ، وكيف أرشده الرب إلى رفقة . ليختارها زوجة لأسحق إبن سيده ، بارشاد إلهى عجيب ! ! حتى قال « لا تعوقونى والرب قد انجح طريقى » (تك ٢٤ : ٥٦) .","* * *",{h:"كذلك ما أكثر الأبواب المفتوحة للتوبة ..."},"من كان يظن أنه سينفتح باب للتوبة أمام مريم القبطية التى أعثرت المئات وأسقطتهم . ولكن الله فتح أمامها باباً بمعجزة ، لمست فيها يد الرب وتابت ...","ومن كان يظن أنه سينفتح باب أمام أوغسطينوس وبيلاجية وموسى الأسود ، بعد أن وصلت حال كل منهم إلى وضع سىء للغاية فى البعد عن الله ...",{h:"وهكذا أيضاً شاول الطرسوسى مضطهد الكنيسة ."},"من كان يظن أنه سيتحول إلى رسول وإناء مختار للرب ، هذا الذى كان ينفث تهديداً ، ويجر رجالاً ونساءً إلى السجن (أع ٩ : ١ ، ٢) . وإذا باب فى السماء ينفتح أمامه وهو فى الطريق إلى دمشق ، برؤيا عجيبة ، كلمه فيها الرب ، فآمن وتحول إلى العكس ، وتعب أكثر من جميع الرسل ، ونال اكليل الشهادة ...",{h:"كذلك الأمم فتح لهم الله باباً للتوبة والقبول ..."},"وكانوا معتبرين غرباء ، أجانب عن رعوية الله ، فصاروا هم الزيتونة الجديدة التى طعمت فى الزيتونة العتيقة . وأصبحت الغالبية العظمى من المؤمنين تابعة من هؤلاء الأمم ، وانفتح الباب بمعجزة أمام كرنيليوس (أع ١٠) ثم أمام الكل (أع ١٥) .","* * *",{h:"ماذا أقول عن أمثلة عجيبة امتدحها الكتاب :"},"أرملة صرفة صيدا التى أطعمت إيليا ، والمرأة الكنعانية التى شفى السيد المسيح"],83:["إبنتها ، وراحاب الزانية ، وراعوث ، وملكة سبأ التى جاءت من أقاصى الأرض لتسمع حكمة سليمان ... كل أولئك اللاتى تسجلت أسماؤهن فى التاريخ ، وطوبهن الكتاب ، لمجرد أن الله جعل أمام كل واحدة باباً مفتوحاً .",{h:"بل ماذا أقول عن يونان النبى الذى ابتلعه حوت ؟ !"},"من كان يظن أن مثل هذا يمكنه أن يخرج من جوف الحوت ، ويحيا ، ويبشر نينوى ، وتؤمن على يديه ؟ ! ولكن الحل الوحيد أن الله قد جعل أمامه باباً مفتوحاً ، ففتح الحوت فاه ، وألقاه إلى البر ، ليؤدى رسالته ! ! حقاً كما يقول الكتاب :",{h:"« غير المستطاع عند الناس ، مستطاع عند الله » (لو ١٨ : ٢٧) ."},"إن الله قادر على كل شىء . وإن اعتمدت عليه تحيا فى رجاء ثابت لا يتزعزع . هو قادر أن يفتح الأبواب المغلقة ، ويحل كل المشاكل المعقدة . بيده كل المفاتيح ، « يفتح ولا أحد يغلق » وهناك مثل عجيب لباب مغلق فتحه الله :",{h:"لقد فتح الرب باب الفردوس بعد آلاف السنين ..."},"وهكذا أدخل فيه آدم وحواء ، بعد أن طردا قديماً من الجنة ، وأدخل فيه كل الراقدين على الرجاء ، وجعل هذا الباب مفتوحاً أيضاً أمام اللص اليمين ، وأمام جميع التائبين ، لكى يصيروا جميعاً فرحين فى الرجاء (رو ١٢ : ١٢) .","* * *",{h:"لكل هذا ، اطلب من الرب أن يفتح أمامك الأبواب :"},"قبل أن تخرج من بيتك كل يوم ، اطلب من الرب أن يفتح أمامك كل القلوب ، وكل الآذان ، وأن يفتح أمامك أبواب الرزق وأبواب الخير . وما أجمل تلك الصلاة التى يصليها الآب الكاهن أمام الهيكل و يقول :",{h:"« أجعل باب بيتك مفتوحاً أمامنا فى كل زمان ... »"},"و يقول أيضاً « لا تغلق باب بيتك فى وجوهنا » .","بل فى كل يوم يصلى كل منا ويقول « افتح يارب شفتى ، فيخبر فمى"],84:["بتسبحتك » (مز ٥٠) . ذلك لأننا لا نضمن إن فتحنا أفواهنا من ذواتنا ، أى كلام سنقوله ؟ وهل سيكون مرضياً أمام الله أم لا يكون ؟ وماذا ستكون نتائجه ؟ ...","ولعل من الصلوات العجيبة التى صلاها أليشع النبى لأجل تلميذه جيحزى هى قوله :",{h:"« افتح يارب عينى الغلام فيرى » ... (٢مل ٦ : ١٧) ."},"فيرى أن الذين معنا أكثر من الذين علينا ، فيطمئن ، ويؤمن . نعم نحن لنا عيون ولكنها لا تبصر ، وآذان ولكنها لا تسمع ... ونحتاج أن يفتح الرب عيوننا وآذاننا وقلوبنا أيضاً .. ألسنا نقول فى صلواتنا « اكشف عن عينى فأرى عجائب من ناموسك » (مز ١١٩) .","وبعد ، أترانا قلنا كل ما يفتحه الله أمامنا ؟ كلا ، بلاشك ... فالموضوع أطول من أن يسعه مقال ، عن الله الذى قال :",{h:"افتح لكم كوى السماء ، وأفيض عليكم بركة ، حتى لا توسع » ."},"* * *",{h:"باب الله مفتوح أمامنا على الدوام ، مهما أغلقت باقى الأبواب ."},"يقول لنا كما قال لملاك كنيسة فيلادلفيا « هأنذا قد جعلت أمامك باباً مفتوحاً ، ولا يستطيع أحد أن يغلقه » (رؤ ٣ : ٨) . هذا هو قلب الله الحنون ، الذى ازال الحجاب الحاجز ، وفتح الطريق إلى قدس الأقداس ، وفتح باب الفردوس أمام آدم وبنيه .","* * *",{h:"إنها عبارة معزية ، نتذكرها فى بدء العام الجديد ."},"مهما ضاقت الدنيا أمامك ، ومهما تعقدت السبل ، وأغلق الناس قلوبهم وأحشاءهم ، ودعوت وليس من مجيب ، وبحثت وليس من صديق ، حينئذ تتعزى بقول القديس يوحنا الحبيب ، « نظرت وإذا باب مفتوح فى السماء » .",{h:"يقولها لكل من فى ضيقة ، ولكل خاطىء أتعبته الخطية ."}],85:["لكل خاطىء سيطرت الخطية عليه ... حاول أن يتخلص منها مراراً ولم يستطع ، وكاد ييأس ... طرق باب التداريب الروحية ، وكل جهاد شخصى . وطرق أبواب الصوم وضبط النفس ... ولم يجد طريق التوبة مفتوحاً أمامه ... حينئذ يرفع هذا الخاطىء نظره إلى فوق ، ويقول « رأيت باباً مفتوحاً فى السماء » ، « عونى من عند الرب الذى صنع السماء والأرض » (مز ١٢١ : ٢) .","* * *",{h:"المهم فى مشاكلنا أن نرفع نظرنا إلى فوق ، إلى السماء لكى نرى الباب المفتوح ، فنتعزى ..."},"مشكلتنا أننا فى كل ضيقاتنا ، نتجه إلى المعونة الأرضية ! نتجه إلى ذكائنا وحيلنا ، وإلى الذراع البشرى فى مساعدة الناس لنا . نتجه إلى الظروف والامكانيات . وبسبب هذا نقع فى الحيرة والقلق والاضطراب . ولكن كل هذا يزول ، ونطمئن ، إن رفعنا نظرنا إلى فوق ، لنرى الباب المفتوح فى السماء ، كما فعل القديس يوحنا الحبيب ، شريكنا فى الضيقة ...","* * *",{h:"لاحظوا أنه رأى هذا الباب المفتوح ، دون أن يطلب ."},"لم ينفتح هذا الباب بصلواته ، إنما هو باب مفتوح بطبيعته مفتوح بالحب الإلهى ...","لم يقل يوحنا « افتح لى باباً فى السماء ، لأرى عرشك وجندك » . إنما أراه الله كل هذا من حنانه ، لكى يعرف أن عطايا الله إنما تنبع من محبته ومن أنعامه ... حقاً إنه يقول بالنسبة إلى التعابى « اقرعوا يفتح لكم » . لكنه يقول للذين يجيئون فى الإيمان « وكل هذه تزدادونها » (متى ٦ : ٣٣) . تأتيكم بدون طلب ، من الآب السماوى الذى يحب أولاده و يعرف احتياجاتهم ...","* * *",{h:"هذا الباب يفتحه الله ، ولا يستطيع أحد أن يغلقه ."},"حسب وعده الأمين ... ذلك لأنه « يفتح ولا أحد يغلق » (رؤ ٣ : ٧) . فإن فتح"],86:["أمامك باباً ، تجد كل أمورك ميسرة ، « لا يقف أحد فى وجهك » (يش ١ : ٥) . « ولا يقع بك أحد ليؤذيك » (أع ١٨ : ١٠) . وأبواب الجحيم لن تقوى عليك (متى ١٦ : ١٨) .","إذن لا تضيع وقتك منقباً فى الأرض ، تحفر لك آباراً مشققة لا تضبط ماء (ار ٢ : ١٣) . إنما يكفى أن تضمن المعونة الإلهية ، تضمن الباب السماوى المفتوح ، وحينئذ يصير لك كل شىء ...","* * *",{h:"هذا الباب المفتوح رآه يوحنا وهو فى ضيقة منفياً فى جزيرة بطمس ، ومضطهداً لأجل الكلمة ."},"فى وقت لم يكن يجد فيه على الأرض حناناً ولا عدلاً ، ولم يجد من البشر معونة ولا سنداً ... حينما بدا أن كل إنسان قد تخلى عنه ، أو عجز عن معونته ، فترك إلى أعدائه يحكمون عليه ... فى هذا الوقت الذى أغلقت فيه أبواب الأرض ، نظر وإذا باب مفتوح فى السماء ، وسمع صوتاً يقول له « اصعد إلى ههنا فأريك ... » وأراه عرش الله فى الرؤيا ، وقوات السماء ...",{h:"عجيب هو الله حقاً فى عمق عطاياه ، الله المقيم المسكين من التراب (مز ١١٣ : ٧) ."},"ولعل القديس يوحنا كان يقول للرب : من أنا يارب الذى تصنع معى كل هذا ، أنا البائس الملقى فى هذه الجزيرة النائية ، أنا غير المستحق أن أرى عرش الأمبراطور تراجان ، كيف استحق أن أرى عرش ملك الملوك ورب الأرباب ؟ ! نعم تعال يا يوحنا واصعد لترى هذا العرش ، لكى تعرف أن كل أباطرة الأرض هم حفنة من تراب ... ! ويقف أمامنا سؤال :",{h:"كيف صعد يوحنا إلى السماء ، ليرى هذه الرؤيا ؟"},"هنا تقف اللغة عاجزة ... نعم كيف صعد ؟ أنا لست بمستطيع أن أجيب ... أفضل أجابة هى أن أقول : لا أعرف ... لست أجد ألفاظاً فى اللغة العربية ، ولا فى أية لغة أخرى تستطيع أن تعبر عن هذا المعنى ... لذلك اكتفى بأن أتركه إلى تأملاتكم الخاصة ."],87:["« اصعد إلى هنا » . هذا أمر . كيف نفذه يوحنا ؟ أو كيف نفذ فى يوحنا ؟ كيف صعد إلى السماء ؟ وكيف دخل من هذا الباب المفتوح ؟ وكيف رأى ؟ بالعين أم بالروح أم بعين روحية ؟ وكيف ؟ ... المهم أن الله حول ضيقته إلى فرح ، وجهله إلى معرفة ، ونفيه إلى ترقية وإنعام ، وأعطانا عربوناً لحياة أخرى ستكون بعد القيامة ، ومنحنا نحن رجاء فى تلك الحياة ...",{h:"كل هذا حدث ليوحنا ، وهو فى المنفى ..."},"لم تحدث هذه الرؤيا وهو فى أورشليم ، مدينة الملك العظيم ، ولا وهو فى الهيكل ولا حتى فى قدس الأقداس ، ولا إلى جوار تابوت العهد ليس فى كل تلك الأماكن العظيمة والمقدسة ، حيث ينتظر الإنسان أن يرى رؤى ... إنما فى الضيقة ، وفى النفى ...","* * *",{h:"حقاً ، إن ملكوت الله لا يأتى بمراقبة (لو ١٧ : ٢٠) ."},"إننا لا نعرف متى ولا أين يفتقدنا الله بنعمته ، بعمل روحه القدوس . لا نعرف متى تفتح السماء أبوابها ؟ ومتى يأتينا الصوت كبوق ، أو كريح عاصف ، أو كصوت مياه كثيرة ... ؟ إنه لا يأتى بانتظارنا أو توقعنا ، أو مراقبتنا ... لسنا نعرف متى يأتى الرب لمعونتنا ، ومتى يعلن لنا .",{h:"المهم أن نكون مستعدين لعمل الروح فينا ..."},{h:"نفتح نحن قلوبنا ، فيفتح لنا الرب باباً فى السماء ."},"نصعد بأرواحنا إلى السماء ، بينما أجسادنا لا تزال على الأرض ، حينئذ يصعدنا الرب إلى السماء ، حتى لوبقينا ظاهرياً على الأرض ... « فى الجسد أم خارج الجسد ؟ لست أعلم . الله وحده يعلم » (٢كو ١٢ : ٣) . هنا ونقول أن رؤيا يوحنا تحمل لنا أعظم رجاء مفرح ، وهو :","* * *",{h:"أن أبواب السماء صارت مفتوحة . وقد رآها القديس اسطفانوس الشماس من قبل :"}],88:["وذلك حينما حنق عليه اليهود ليقتلوه . يقول الكتاب : « أما هو فشخص إلى السماء ، وهو ممتلىء من الروح القدس . فرأى مجد الله والرب يسوع عن يمين الله ، فقال : ها أنا انظر السموات مفتوحة ، وابن الإنسان قائماً عن يمين الله » (أع ٧ : ٥٥ ، ٥٦) .",{h:"هذه السماء المفتوحة أمامنا هى أملنا الكبير الذى نسعى إليه لكى نرى فيها مجد الله ونبصر الرب يسوع ."},"رآها اسطفانوس أول الشمامسة ، ورآها يوحنا الحبيب ، مفتوحة . وأبصرا شيئاً من المجد العتيد ، كعربون للملكوت الأبدى ... والعجيب أن كلاً منهما قد رآها وهو فى ألم واضطهاد ، مرذولاً من الناس ، أحدهما فى وقت رجمه ، والآخر أثناء نفيه ... وذلك لكى نفهم أن طريق هذه السماء هو الصليب ، وأنه « بضيقات كثيرة ينبغى أن ندخل ملكوت الله » (أع ١٤ : ٢٢) .","* * *",{h:"وقبل اسطفانوس ويوحنا ، أبصر السماء حزقيال النبى :"},"رأى عرش الله محمولاً على الكاروبيم (حز ١) . ورأى هذا المنظر حينما كان ضمن المسبيين ، عند نهر خابور . وقال فى ذلك « كان ... وأنا بين المسبيين عند نهر خابور . أن السموات انفتحت . فرأيت رؤى الله ... » وشرح ما رآه ، ... ثم قال « هذا منظر شبه مجد الرب . ولما رأيته خررت على وجهى وسمعت صوت متكلم ... » (حز ١ : ٢٨) . عجيب أن يرى هذه الرؤيا وهو فى السبى ... كيوحنا فى النفى .",{h:"بنفس الوضع رأى دانيال النبى شبه المنظر وهو فى السبى :"},"رأى إبن الإنسان وهو على سحاب السماء ، أمام الآب ، وقد أعطى سلطاناً ومجداً وملكوتاً ، لتتعبد له كل الشعوب والأمم والألسنة . سلطانه سلطان أبدى ما لن يزول ، وملكوته ما لا ينقرض (دا ٧ : ١٣ ، ١٤) . ورأى رؤى أخرى ، وأرسل له الله الملاك جبرائيل ليفسرها له (دا ٨ : ١٦) .",{h:"كل هذه الرؤى ، رآها انبياء وقديسون فى ضيقاتهم ."},"سماء الله وعرشه رآها يوحنا فى النفى ، اسطفانوس قبل رجمه . وحزقيال ودانيال"],89:["وهما فى السبى . ولاشك أن هذه المناظر التى يسمح الله لقديسيه أن يروها أثناء ضيقاتهم لأجل إسمه ، إنما هى لون من العزاء الإلهى أثناء الآلام ...","* * *",{h:"وأنتم أيها الأخوة ، هل رأيتم هذه السموات المفتوحة ؟ أم أن لكم عيوناً ولكنها لا تبصر ؟"},"وإن كان كذلك ، فمتى تنقشع تلك الغشاوة عن أعيننا ، حتى نرى ما يمكن أن يراه الروحانيون ... كاشخاص فى الجسد ، نحن لا نرى ، ولكن متى صرنا فى الروح ، مثلما كان يوحنا « فى الروح فى يوم الرب » (رؤ ١ : ١٠) ، حينئذ سنرى .",{h:"طالما عيوننا مشغولة بالجسد وبالمادة وبالعالم ، ومغلقة بالهيولانيات ، فلا يمكن أن ترى الروحيات ."},"السماء المفتوحة رآها القديسون فى ضيقاتهم ، أما المترفون الذين يعيشون فى المتعة والفرح واللذة ، فإنهم لا يشعرون بالحاجة إلى باب مفتوح فى السماء ! وإن طلبوا من الله ، فسيقولون : افتح لنا أبواباً على الأرض ، فالسماء لم يأت موعدها بعد ... افتح لنا أبواب الكنوز والرزق والترقيات . هؤلاء المترفون ، أخشى أنهم فى السماء أيضاً سيسمعون تلك العبارة المخيفة « الحق أقول لكم إنكم قد استوفيتم أجركم » (متى ٦ : ٥) .",{h:"ومثل المترفين ، كذلك لا يطلب المنشغلون باباً فى السماء ."},"إن كل تفكيرهم مركز فى العالم وفى الأرضيات . ليس لديهم وقت ولا رغبة لكى يرفعوا نظرهم إلى فوق . مثالهم ذلك الغنى الغبى ، الذى قال « أهدم مخازنى ، وأبنى أعظم منها ، وأجمع هناك جميع غلاتى وخيراتى ، وأقول لنفسى : يا نفسى لك خيرات كثيرة موضوعة لسنين عديدة . فاستريحى وكلى واشربى وافرحى » (لو ١٢ : ١٨ ، ١٩) .","* * *",{h:"إذن علينا أن نرتفع فوق الأرضيات ، لنرى الباب السماوى المفتوح ..."}],90:[{h:"مثال ذلك : فلك نوح الذى تغرب عن العالم ، وارتفع فوق المياه التى غطت كل شىء . وفتح أبونا نوح فيه طاقة ، تشبه الباب المفتوح فى السماء . وخرجت من الطاقة حمامة جاءت بغصن زيتون ، رمزاً للسلام الإلهى فى الأرض الجديدة التى باركها الرب ..."},"إن لم تستطع أن ترتفع فوق الأرضيات بصفة دائمة ، فليكن ذلك على الأقل فى فترات ، كيوم الرب .","لقد منحك الرب هذا اليوم ، ليكون لك معه ، تنحل فيه من الأرضيات ، لكى ترتبط بالواحد الذى هو الله : تفكر فيه ، تكلمه ، تستمع إلى صوته فى قلبك ، وقد تطهر ذهنك ـ ولو مؤقتاً ـ من كل ما هو مادى ... حينئذ ستبصر الباب ."]}},judge_others:{id:"judge_others",title:"إدانة الآخرين",author:"قداسة البابا شنوده الثالث",url:"https://drive.google.com/file/d/1IInEEiWJJLOTlmYuP5l4jrSQP0fhyBlI/view",file:"إدانة_الآخرين.pdf",pageOffset:0,review:{status:"needs-review",note:"نُقل الكتاب (سلسلة الحروب الروحية ٤، الطبعة الثانية ١٩٩٠) بقراءة صفحات الكتاب الممسوحة بالنظر، من «قصة هذا الكتاب» إلى آخر الفصل الخامس (ص٥ إلى ص٩٣ بترقيم الملف = ترقيم الكتاب المطبوع)، دون الفهرس. صفحة ٦ في ملف المصدر مكررة من صفحة ٦٦ فأُشير إلى ذلك. بعض فقرات حواف الصفحات الباهتة (كفقرة أسفل ص٥٨) قُرئت بأفضل ما تيسر وتحتاج مطابقة نهائية مع الأصل."},chapters:[{title:"قصة هذا الكتاب",from:5,to:6},{title:"الفصل الأول: الإدانة غير الخاطئة",from:7,to:32},{title:"الفصل الثاني: أنواع إدانة الآخرين",from:33,to:48},{title:"الفصل الثالث: الإدانة خطية مركبة",from:49,to:64},{title:"الفصل الرابع: أقوال الآباء في الإدانة",from:65,to:78},{title:"الفصل الخامس: علاج الإدانة",from:79,to:93}],transcribed:[5,93],pages:{5:[{h:"قصة هذا الكتاب"},"أصل هذا الكتاب يرجع إلى محاضرتين ألقيتهما سنة ١٩٦٥ فى القاعة المرقسية بدير الأنبا رويس بالقاهرة عن إدانة الآخرين وأقوال الآباء فيها .","وتحدثت فى هذا الموضوع أيضاً فى محاضرتين أخريين ألقيتهما فى الكاندرائية المرقسية الكبرى فى ٦٩/٣/٢١ ، ٦٩/٣/٢٨ .","ثم تعرضت لهذا الموضوع مرة أخرى ، خلال هذا العام (١٩٨٧) ، وأنا فى مجال تفسير وشرح العظة على الجبل ، فى (متى ٧ : ١ ـ ٥) . كما ألقيت محاضرتين عن الإدانة فى الكنيسة المرقسية الكبرى بالإسكندرية فى يونيو ١٩٨٧ .","ومن هذا المزيج كله ، خرج هذا الكتاب الذى بين يديك .","أقدمه لك باعتباره الجزء الرابع من (سلسلة الحروب الروحية) . وقد صدر الجزء الثالث منذ شهرين عن (الغضب) .","وإن شاء الله حينما يصدر الجزء الثانى من كتاب (تأملات فى العظة على الجبل) سنعرض لهذه النقطة باختصار . ومن يريد التوسع ، فليرجع إلى هذا الكتاب ."],6:["(تكررت هنا في ملف المصدر الممسوح الصفحة المطبوعة رقم ٦٦، وهي واردة في موضعها الأصلي في الفصل الرابع من هذا الكتاب.)"],7:[{h:"الفصل الأول"},{h:"الإدانة غير الخاطئة"},"١ ـ المسئولية والرعاية .","٢ ـ التمييز الطبيعى .","٣ ـ مفهوم وصايا كتابية .","٤ ـ إدانة الهرطقات والبدع .","٥ ـ النصح والهداية والتوبيخ .","٦ ـ النقد .","٧ ـ إدانة النفس .","من يبرىء المذنب .","شروط الإدانة غير الخاطئة .","لا تحكموا قبل الوقت .","الحكم بالحق ."],8:["هناك حالات كثيرة تجوز فيها الإدانة ، ولا تكون خطية ، نذكر منها :",{h:"١ ـ المسئولية والرعاية"},{h:"تجوز الإدانة حينما تصدر من مسئول أو صاحب سلطان"},"هناك أشخاص أقامهم الله بسلطان على غيرهم . من حقهم أن يدينوا من هم تحت سلطانهم ، ولا تنطبق عليهم الآية التى تقول « لا تدينوا لكى لا تدانوا » ..",{h:"وهؤلاء ليس من حقهم فقط أن يدينوا ، بل من واجبهم ..."},{h:"بحيث أنهم يخطئون إن لم يدينوا من هم تحت سلطانهم ."},"من أمثلة هؤلاء : الأب والأم . وقد ائتمن الله الآباء والأمهات على تربية أولادهم . ومن حقهم أن يوبخوا أبناءهم على أخطائهم . وأن يقولوا للإبن « إن تصرفك هذا خاطىء ، وينبغى أن تتركه » . وإن لم يتركه قد يأخذ منهم عقوبة .",{h:"لاشك إنها إدانة ، ولكنها ليست خطية إدانة ."},"لأنها صادرة من شخص صرح له الله أن يدين ، بل أمره بذلك ، كجزء من تربيته لإبنه . بل إن الأب الذى يقصر فى تربية إبنه ، ويهمل فى تنشئته وتوجيهه ، ولا يدينه ويوبخه على أخطائه ، هذا الأب يعاقبه الله ...",{h:"ومثال ذلك العقوبة التى أوقعها الله على عالى الكاهن ."},"كان أولاده يخطئون ... وسمع عالى الكاهن بذلك ، وأدانهم ، ولكن ليس بحزم ! قال لهم : « لماذا تعملون مثل هذه الأمور ؟ لأنى أسمع بأموركم الخبيثة من جميع هذا الشعب . لا يابنىّ ، لأنه ليس حسناً الخبر الذى اسمع ... » « ولم يسمعوا لصوت أبيهم » (١صم ٢ : ٢٢ ـ ٢٥) .","وغضب الرب لأن عالى الكاهن تراخى فى إدانة أولاده ، فقال « هوذا أنا فاعل أمراً فى إسرائيل ، كل من سمع به تطن أذناه . فى ذلك اليوم أقيم على عالى كل ما تكلمت به على بيته ... وقد أخبرته بأنى أقضى على بيته إلى الأبد ، من أجل الشر الذى"],9:["يعلم أن بنيه قد أوجبوا به اللعنة على أنفسهم ، ولم يردعهم » (١صم ٣ : ١١ ـ ١٤) .",{h:"إذن الإدانة هنا واجب ملزم ، من يقصر فيه يعرض نفسه للعقوبة ."},"ليس فقط أن يدين الأب أولاده إن أخطأوا . بل أكثر من هذا أن « يردعهم » . أى أن يمنعهم ـ بسلطان ـ من ارتكاب الخطأ ، ومن الأستمرار فيه ...","وما أكثر الوصايا التى أعطاها الله للآباء والأمهات لتأديب أولادهم . ومعها وصايا أخرى للأبناء أن يطيعوا آباءهم فى الرب ، لأن هذا حق (أف ٦ : ١) .",{h:"وما نقوله عن الأب الجسدى ، نقوله أيضاً عن الأب الروحى ، وعن الراعى عموماً ..."},"ومن هنا أعطى الله للآباء الكهنة ، وللرعاة ، وللأنبياء ، واجباً هو إنذار الخطاة وإدانتهم . فقال « يا ابن آدم ، قد جعلتك رقيباً ... فاسمع الكلمة من فمى ، وانذرهم من قبلى . إذا قلتُ للشرير موتاً تموت ، وما أنذرته أنت ، ولا تكلمت إنذاراً للشرير من طريقه الرديئة لإحيائه ، فهذا الشرير يموت بإثمه ، أما دمه فمن يدك اطلبه » (حز ٣ : ١٧ ، ١٨) .","إذن إنذار الخطاء وتوبيخهم وردعهم وإدانتهم طرقهم للشرير ، ليست مجرد حق للآباء والرعاة ، بل كل ذلك واجب عليهم ، يدانون إن لم يقوموا به . ولكنهم يخلصون من الدينونة ، إن هم أدانوا هؤلاء الخطاة ، وأنذروهم من جهة نتيجة شر أعمالهم . وهكذا يكمل الرب وصيته فيقول « وإن أنت أنذرت الشرير ، ولم يرجع عن شره ، ولا عن طريقه الرديئة ، فإنه يموت بإثمه . أما أنت فقد نجيت نفسك » (حز ٣ : ١٩) .",{h:"ونفس الكلام نقوله عن المدرس مع تلاميذه ، ورئيس العمال مع مرؤوسيه ، وأيضاً عن القاضى بالنسبة إلى المتهمين ."},"كل هؤلاء لهم الحق أن يدينوا من هم تحت سلطانهم ، فى نطاق اختصاصاتهم لا يتعدونها ، وفى حدود الواجب المناط بهم ، وفى مجال عملهم ومسئوليتهم . وفى الالتزام بالحق والعدل ."],10:["فإن قال المدرس لتلميذه إنه مهمل فى أداء واجباته الدراسية ، وإن قال رئيس العمل لأحد عماله إنه غير أمين فى عمله . وإن قال القاضى إن هذا المتهم مذنب ، لا يكون أحد من هؤلاء قد خالف وصية « لا تدينوا لكى لا تدانوا » .",{h:"وإن سمع قول الرسول « من أنت يا من تدين غيرك » (يع ٤ : ١٢) ، يجيب « أنا المسئول عنه وعن عمله » ."},"إنه يدين ، وبسلطان . وفى عمله إدانة ، ولكنها ليست خطية إدانة . لأن الإدانة هنا من حقه ، بل هى من واجبه .","وإن قصر واحد من كل هذه الفئات فى إدانة من هم تحت سلطانه ، يرتبك العمل ، ويفسد المجتمع ، وتسود اللامبالاة",{h:"لذلك إن اجتمع كونسلتو أطباء لفحص مريض ، وتشاوروا فى تشخيص مرضه ."},"فقال أحدهم إنه يشكو من كذا ، وقال آخر إنه مريض بكذا ، وقال ثالث إنه مصاب بكذا .. فهنا القصد التوصل إلى شفاء المريض ، وليس القصد هو إساءة سمعته أو التشنيع به .. ولعل مما يشبه هذا تماماً ما ورد فى (نسكيات باسيليوس) :",{h:"سئل القديس باسيليوس الكبير عن الإدانة ، فقال :"},"إذا كان المقامون على الأخوة يبحثون حالة أخ فى المجمع ، وتعرضوا لأخطائه وماذا يُعمل لأجل تقويمه ، ولأجل سلامة المجمع من نتائج هذه الأخطاء ، فلا تكون هذه خطية إدانة ... بشرط أن يفحصوا اخطاءه « فى خوف الله » .",{h:"وهذا الحق فى الإدانة ، أعطاه الرب للكنيسة :"},"فكما أعطاها سلطاناً أن تحل ، أعطاها أيضاً سلطاناً أن تربط (متى ١٨ : ١٨) . وأعطاها أن تفصل فى الخصومات . ومن لم يسمع لها فيما تحكم به ، يكون كالوثنى والعشار (متى ١٨ : ١٧) . فإن قالت الكنيسة لشخص إنه مخطىء ، لا تكون قد وقعت فى خطية إدانة ، بل تكون قد أدانته بحق وبسلطان .","يوحنا المعمدان أدان الخطاة ووبخهم (متى ٣ : ٧) . وبولس وبخ كثيرين منهم « الغلاطيون الأغبياء » (غل ٣ : ١) . وأمر تلميذه تيموثاوس الأسقف أن يوبخ"],11:["وينتهر ويعظ (٢تى ٤ : ٢) . وقال له أيضاً « الذين يخطئون ، وبخهم أمام الجميع ، لكى يكون عند الباقين خوف » (١تى ٥ : ٢٠) .","بولس الرسول أدان خاطىء كورنثوس (١كو ٥) ، ووبخ أهل كورنثوس على أنهم لم يعزلوا الخبيث من بينهم (١كو ٥ : ١٣) . وبطرس الرسول أدان حنانيا وسفيرا وحكم عليهما ، بعد أن وصفهما بالكذب ، وبالاتفاق على تجربة روح الرب (أع ٥ : ٣ ـ ٩) .",{h:"ولعلك تقول « أنا لست رسولاً ولا نبياً » ... لك حق . إذن اعمل فى حدود السلطان الذى وُهب لك من الله ، إن كنت صاحب سلطان ."},"اعمل فى حدود مسئوليتك ، مهما كانت ضيقة ... على أن يكون ذلك بأسلوب روحى ، كما سنشرح فيما سيأتى ...",{h:"٢ ـ التمييز الطبيعى"},{h:"أحياناً تكون الإدانة شيئاً طبيعياً ، مجرد تمييز للخطأ أو الشر ."},"فأنت مثلاً إن سمعت إنساناً يشتم ، لا تستطيع أن تمنع نفسك من إدراك أن هذه شتيمة . وبالمثل إن رأيت رجلاً فى ثورة غضب وقد فقد أعصابه ، وهكذا إن رأيت إمرأة فى ملابس متبرجة غير لائقة .","وبالمثل إذا سمعت إنساناً يحلف بأقسام مغلظة ، أو سمعت إنساناً يغنى أغانى عالمية ، أو يقول فكاهات رديئة جداً من الناحية الأخلاقية ، هل استطيع أن أمنع نفسى من إدانة ما أسمعه ؟! هناك إذن إدانة تلقائية بحكم الضمير ...","ينبغى أن نفهم الروحيات بطريقة سليمة بعيدة عن الوسوسة .",{h:"فعدم الإدانة ليس معناه أن أفقد الحكم الطبيعى على الأمور ."},"فقد وهب الله للإنسان ضميراً يميز به بين الخير والشر . وليس من صالح الإنسان أن يفقد التمييز ."],12:["إنه نور طبيعى يستطيع به أن يحكم على أعماله ، كما يحكم به على أعمال غيره ، مع فارق سنذكره فيما بعد ... وإن فقد الإنسان هذا التمييز سوف تختل أمامه القيم والمبادىء ، ولا يدرى ما يجب أن يكون ، وما لا يجب ...","وهكذا قال السيد الرب مرتين فى العظة على الجبل :",{h:"« من ثمارهم تعرفونهم » (متى ٧ : ١٦ ، ٢٠) ."},"وشرح ذلك فقال « هل يجتنون من الشوك عنباً ، أو من الحسك تيناً ؟! هكذا كل شجرة جيدة تصنع ثماراً جيدة . وأما الشجرة الردية فتصنع أثماراً ردية . لا تقدر شجرة جيدة أن تصنع أثماراً ردية . ولا شجرة ردية أن تصنع أثماراً جيدة . إذن من ثمارهم تعرفونهم » (متى ٧ : ١٦ ـ ٢٠) .","فهل إذا رأينا الشوك فعرفنا أنه شوك ، وإن رأينا الثمر الردىء فعرفنا أنه ثمر ردىء ، أنكون آثمين واقعين فى إدانة الآخرين ؟! كلا بلا شك ...",{h:"يقول القديس أوغسطينوس فى تفسير هذه الآية (متى ٧ : ٧) ."},"هناك شجرة تعطى ثماراً ردية ، وشجرة تعطى ثماراً جيدة . ولا يمكن أبداً لإنسان أن يخدع نفسه ، ويقول عن الردىء إنه جيد ، ولا عن الجيد إنه ردىء . فمما لاشك فيه أن بعض الأمور واضحة جداً ، لا نستطيع أن نخدع أنفسنا فيها ...","ولعله من أجل هذا التمييز قال القديس بولس الرسول :",{h:"خطايا بعض الناس واضحة تتقدم إلى القضاء (١تى ٥ : ٢٤) ."},"هذه الخطايا الواضحة لا ذنب لك إن أدركتها : من الطبيعى أنك سوف تشعر أن هناك خطأ يتقدم إلى القضاء . وفى نطاق هذا المستوى لا تكون قد أخطأت . إنما توجد ملاحظة لابد أن نقدرها وهى :",{h:"هناك فرق بين إدانة العمل وإدانة الشخص :"},"فإن رأيت شخصاً سكراناً يتطوح فى الطريق ، لا تستطيع أن تمنع نفسك من أن هذا خطأ . العمل خطأ ، أو الحادث أمامك خطأ . ولكن الشخص نفسه لا تستطيع أن"],13:["تدينه ، إلا إذا عرفت ظروفه ... ربما هناك من خدعه وأسكره . ربما شرب عن طريق الخطأ . وربما العكس . من يدرى ؟!",{h:"إذن التمييز شىء ، والحكم على الشخص شىء آخر ."},"كونى أسمع الشتيمة فأعرف أنها شتيمة ، هذا تمييز .",{h:"أما أن اسمعها ، فأقيم فى ذهنى محكمة لصاحبها ، وأقول إنه كذا وكذا ، ويستحق ... فهنا يصبح الأمر إدانة ، لأنه انتقل من تمييز العمل والحكم التلقائى للضمير ، إلى الحكم على الشخص نفسه ."},"وإذا أخذت قصة هذا الإنسان موضوعاً لحكاياتى وأحاديثى مع الناس ، لا أقول حينئذ إنه مجرد تمييز طبيعى ، أو حكم تلقائى من الضمير . بل هنا أكون قد تطورت من إدانة الشخص إلى التشهير به . ولاشك أن كلاً منهما خطيئة .",{h:"ومن جهة الخطايا الواضحة ، توجد أمور تبدو واضحة ، وهى على عكس ذلك ..."},"فإن رأيت شخصاً فى الصوم يشرب كوباً من اللبن ، وقلت : هذا الإنسان محب للأكل وكاسر للصوم ولاشك أن هذه خطية واضحة تقدمه إلى القضاء !! (١تى ٥ : ٤) ... فربما تكون مخطئاً فى حكمك . وقد يكون هذا الشخص مريضاً بقرحة فى المعدة أو مرض آخر ، ويحتاج إلى اللبن كدواء . وقد وافق على أوامر الأطباء متغصباً من أجل صحته ... ولا يمكن أن يحكم عليه بأنه محب للطعام وكاسر للصوم ...",{h:"وقد علّق القديس على موضوع الأكل هذا ، فقال :"},"إن كل أنواع الطعام البشرى يمكن أن تؤخذ بنية صالحة ... وبدون شهوة وبدون تمييز . وتذكر فى ذلك قول القديس بولس الرسول :",{h:"لا يزدرِ من يأكل بمن لا يأكل . ولا يدن من لا يأكل من يأكل ، لأن الله قبله » (رو ١٤ : ٣) ."},"ويكمل القديس بولس الرسول كلامه فيقول « من أنت الذى تدين عبد غيرك ؟! هو لمولاه يثبت أو يسقط . ولكنه سيثبت ، لأن الله قادر أن يثبته » (رو ١٤ : ٤) ."],14:["أمثال هذه الأمور ليس من حق إنسان أن يحكم فيها . وهى ليست من الخطايا الواضحة التى تتقدم إلى القضاء . الخطايا الواضحة هى مثل الزنى والسرقة والإعتداء وأنواع النجاسات .",{h:"أما الأمور التى تتوقف على النية والقصد ، فليس من حقنا أن نحكم عليها . الله وحده هو العارف بالنيات ."},"الله وحده هو فاحص القلوب ، وهو الذى يعرف القصد والدافع . ويستطيع أن يحكم إن كان هذا العمل صالحاً أم طالحاً ، مما لا تتوفر لنا معرفته .","نقطة أخرى نضيفها إلى عنصر التمييز وهى :",{h:"٣ ـ مفهوم وصايا كتابية"},"وصايا وآيات تحمل الإدانة :","فهناك وصية فى الكتاب تقول لك « لا تستصحب غضوباً ، ومع رجل ساخط لا تجىء » (أم ٢٢ : ٢٤) . فكيف يمكن أن تنفذ الوصية وتبعد عن صحبة الغضوبين ، إلا لو أدركت أن هذا الإنسان بالذات هو رجل غضوب ؟! فهل هذه إدانة ؟ كلا ، بل هى لون من التمييز ، تماماً كما تميز حفرة حتى لا تقع فيها .","ومثله قول الكتاب « المعاشرات الردية تفسد الأخلاق الجيدة » (١كو ١٥ : ٢٣) . فكيف تبعد عن هذه المعاشرات ، إلا لو عرفت تماماً إنها ردية ؟ فهل هذه المعرفة إدانة ؟ كلا ، طبعاً ...","وبنفس المنطق نتكلم عن الوصية التى يحملها المزمور الأول « طوبى للرجل الذى لم يسلك فى مشورة الأشرار ، وفى طريق الخطاة لم يقف ، وفى مجلس المستهزئين لم يجلس » .","كيف يبعد عن هؤلاء الأشرار والخطاة والمستهزئين ، إن لم يعرف أنهم كذلك ؟ فهل هذه المعرفة خطية إدانة ؟"],15:["كلا ، بلا شك . مادام الأمر قد اقتصر على المعرفة والبعد . وحتى لو تدرج الأمر إلى نصح أصدقائك ومعارفك وأقربائك وتلاميذك فى البعد عن هؤلاء لا نكون أيضاً قد أخطأت .",{h:"أتتركهم يسقطون فى حفرة وتقول « لا أريد أن أدين الحفرة » ؟!"},"هوذا الرسول يقول « نوصيكم أيها الأخوة باسم ربنا يسوع المسيح أن تتجنبوا كل أخ يسلك بلا ترتيب ، وليس حسب التعليم الذى أخذه منا » (٢تس ٣ : ٦) . فكيف تتجنب مثل هذا الأخ ، إلا لو عرفت تماماً أنه « يسلك بلا ترتيب » . فهل هذه المعرفة خطية إدانة ؟! كلا ، لأن خطايا بعض الناس واضحة .",{h:"وبالمثل الوصايا الخاصة بالبعد عن العثرات :"},"من المفروض أن يبعد عن العثرات كل إنسان روحى . ولكى يبعد عنها ، لابد أن يعرف أنها عثرات . وليست فى هذه المعرفة خطية إدانة . بل إن السيد المسيح يقول « إن كانت عينك اليمنى تعثرك ، فاقلعها والقها عنك ... » (متى ٥ : ٢٩) .","إن يوسف الصديق قد تعرض لإحدى هذه العثرات ، فقال",{h:"كيف أصنع هذا الشر العظيم وأخطىء إلى الله ؟! (تك ٣٩ : ٩) ."},"وهنا نرى أن يوسف قد أدان هذا العمل ، ووصفه بأنه شر عظيم وأنه خطأ نحو الله . ومع ذلك لم يدن المرأة الثانية ، ولم يصفها بأية عبارة جارحة .","إذن إدانة العمل من حقنا . وهو نوع من التمييز الطبيعى لا خطأ فيه ، ولا داعى للتعرض للأشخاص .","والوصايا الخاصة بالبعد عن العثرات مع إدانتها ، ليست هى خاصة بالسلوكيات فقط ، إنما أيضاً هناك العثرات الخاصة بالإيمان والتعليم والعقيدة وهذا يقودنا إلى نقطة هامة وهى ."],16:[{h:"٤ ـ إدانة الهرطقات والبدع"},"يقول القديس يوحنا الرسول ، وهو من أشهر الرسل بالمحبة : « إن كان أحد يأتيكم ولا يجىء بهذا التعليم ، فلا تقبلوه فى البيت ولا تقولوا له سلام . لأن من يسلم عليه يشترك فى أعماله الشريرة » (٢يو ١٠ ، ١١) .","فهل الذى يرفض المبتدعين ولا يقبلهم ولا يسلم عليهم ، يكون قد وقع فى خطية إدانة ؟ محال أن يكون هذا . بل إنه يقع فى خطية إن كان يسلم عليهم ...","والسيد المسيح يقول « لا تعطوا القدس للكلاب ، ولا تلقوا دررکم قدام الخنازير ، لئلا تدوسها بأرجلها وتلتفت فتمزقكم » (متى ٧ : ٦) . فكيف نفعل هكذا ، إن لم نعرف أنهم كذلك . وهذه المعرفة ليست خطية ، لأنه بدونها لا يتم تنفيذ الوصية . وبالمثل أيضاً يقول الرب :",{h:"« احترزوا من الأنبياء الكذبة ، الذين يأتونكم بثياب الحملان ، ولكنهم من داخل ذئاب خاطفة » (متى ٧ : ١٥) ."},"فالاحتراس من الكذبة ـ وإن كان يحمل إدانة لهم ولكذبهم ـ إلا أنه ليس خطية إدانة ، لأن الإنسان الروحى ينبغى أن يكون حريصاً ، مميزاً للأرواح حسب وصية الرسول (١يو ٤ : ١) . فالاحتراس من الأشرار ليس خطية . ومعرفة أنهم يأتون بثياب الحملان وهم ذئاب خاطفة ، ليس فيه خطأ ، بل فيه حكمة .",{h:"ليست الروحيات أن تسير مغمض العينين ، حتى لا تبصر ولا تدرك حيل الذئاب الخاطفة !"},"فالكتاب يقول « الحكيم عيناه فى رأسه ، والجاهل يسلك فى الظلام » (جا ٢ : ١٤) . فهل السلوك فى الظلام فضيلة ؟ كلا . نحن لا نريدك أن تلعن الظلام . إنما يكفى أن تميزه ، وتبعد عنه ، وتسلك فى النور . وقد وضح السيد المسيح أن التمييز بين النور والظلمة أمر سهل ، فقال « من ثمارهم تعرفونهم » (متى ٧ : ١٦) ."],17:["نقطة أخرى نقولها فى « الإدانة غير المخطئة » وهى :",{h:"٥ ـ النصح والهداية والتوبيخ"},"يقول الرسول « إن ضلّ أحد بينكم عن الحق ، فردّه آخر ، فليعلم أن من ردّ خاطئاً عن ضلال طريقه ، يخلص نفساً من الموت ، ويستر كثرة من الخطايا » (يع ٥ : ١٩ ، ٢٠) . فهل معرفتك أن أحداً قد ضلّ عن الحق ، هى إدانة له ؟ كلا طبعاً ، مادمت تريد رده عن ضلال طريقه ، ولست تقصد التشهير به ...",{h:"ونحن لا نهدى الخطاة ، إلا إذا عرفنا أنهم خطاة ."},"تماماً مثلما يعرف الطبيب نوع المريض ، لكى يصف طريقة علاجه . هكذا إذا درسنا الأخطاء التى يقاسى منها فرد أو مجموعة ، أو حتى كنيسة بأسرها ، لا نكون قد وقعنا فى خطية إدانة ، مادام الهدف هو الإصلاح وليس الإساءة إلى سمعة الغير ...","والآيات الخاصة بالنصح وهداية الآخرين كثيرة جداً ... والنصح والهداية قد يحملان التوبيخ أحياناً . ولا يحمل هذا التوبيخ خطية إدانة . وفى هذا يقول الكتاب :",{h:"« لا تشتركوا فى أعمال الظلمة غير المثمرة ، بل بالحرى وبخوها » (أف ٥ : ١١) ."},"فليست معرفتنا أنها أعمال ظلمة خطية إدانة ، كما أن توبيخ هذه الأعمال غير المثمرة ليس هو أيضاً خطية إدانة . بل أن تبكيتنا لهذه الأعمال هو فضيلة ، لأنه تنفيذ للوصية .","بل أن تبكيتنا لهذه الأعمال هو فضيلة ، لأنه تنفيذ للوصية . على أننا نرجو أن نرجع إلى هذه النقطة فيما بعد ، لنعرف الكيفية السليمة لتنفيذ هذه الوصية .",{h:"وتدخل فى مجال هذا التبكيت ، ما يلزم لأعمال الرعاية ."},"حسبما قال القديس بولس الرسول لتلميذه تيموثاوس الأسقف « وبخ ، انتهر ، عظ ، بكل أناة وتعليم » (٢تى ٤ : ٢) ."],18:[{h:"وإن كانت الإدانة فى أسلوب النصح والتوبيخ ، ينبغى أن يعرف الإنسان كيف تكون :"},"ومثال ذلك أبيجايل التى وبخت داود النبى ، ومنعته من اتيان الدماء والانتقام لنفسه ، بأسلوب كله حكمة ، بدأته بالخضوع وبالمديح ، ثم مست المشكلة بطريقة غير جارحة ، لم تخدش بها شعور داود . بل صارحته ولكن فى أدب وفى تواضع ... (١صم ٢٥) .","فى كل نصيحتها له ، كانت تقول « ياسيدى » وتقول عن نفسها « أمتك » « جاريتك » ... بدأت لقاءها معه بأن قدمت له ما كان يطلبه من الأطعمة ، وسجدت له وأعتذرت عن خطأ زوجها ، وقالت « علىّ أنا يا سيدى هذا الذنب ، ودع أمتك تتكلم فى أذنيك ، واسمع كلام أمتك » .","والعطايا التى قدمتها له لم تجرحه بها ، بل قالت « والآن هذه البركة التى أتت بها جاريتك إلى سيدى ، فلتعط للغلمان السائرين وراء سيدى ، واصفح عن ذنب أمتك » .",{h:"وبعد كل هذا المديح وأسلوب الإتضاع مست أبيجايل خطأ داود ، مقدمة له بمديح آخر ، فقالت :"},"« سيدى يحارب حروب الرب ، ولم يوجد فيك شرّ كل أيامك » « لتكن نفس سيدى محزومة فى حزمة الحياة مع الرب إلهك ... » . وهنا دخلت فى توبيخه على نقطة الضعف فقالت « ويكون عندما يصنع الرب لسيدى حسب كل ما تكلم به من الخير من أجلك ، ويقيمك رئيساً على إسرائيل ، أنه لا تكون لك هذه مصدمة ومعثرة قلب لسيدى ، أنك قد سفكت دماً عفواً ، أو أن سيدى قد انتقم لنفسه » .","نبهته إلى أنه مقدم على الإنتقام لنفسه ، وعلى سفك دم بلا سبب يستدعى ذلك ، ونصحته بالإبتعاد عن هذا ، حتى لا يصبح هذا الأمر معثرة قلب له فيما بعد ...",{h:"وهذا النصح المؤدب ، والتوبيخ الضمنى ، قبله منها داود وشكرها عليه ..."},"وقال لها « ... مبارك عقلك ، ومباركة أنت ، لأنك منعتنى اليوم عن اتيان الدماء وانتقام يدى لنفسى » (١صم ٢٥ : ٣٣) . وتقبل منها عطيتها ، وصرفها"],19:["بسلام ، ورفع وجهها ولم يقم بإيذاء زوجها الخطىء إليه ، مستمعاً لنصيحتها .","حقاً ، ما أجمل النصح ، إن كان بلياقة وأدب . وهنا يسرنا أن نضع قواعد للنصح والتبكيت :",{h:"١ ـ قد يكون من حقك أو من واجبك أن تنصح أو توبخ . ولكن ليكن هذا النصح بأدب وباتضاع وبمحبة ."},{h:"إن التوبيخ بروح الكبرياء والتعالى و أو بأسلوب الاحتقار والاستصغار ، لا يمكن أن يكون مقبولاً . أما إذا نصحت إنساناً أو وبخته وأنت تقول له :"},"« أنت تعرف يا (فلان) مقدار محبتى لك ، ومقدار حرصى على سمعتك . لذلك أنا غير مستريح اطلاقاً لتصرفك (الفلانى) . وأشعر أنه سيضرك ويسىء إليك ، وربما يتخذه أعداؤك فرصة ليقولوا عنك إنك .. وإنك .. لذلك ابعد عن هذا الأمر ، وحاول أن تصحح ما فعلته بكذا وكذا ... » .","هذا الكلام مقبول . بعكس إنسان آخر يقابل شخصاً فيقول له « كيف تفعل كذا ؟ كيف سمح لك ضميرك ؟ هل هذه تصرفات إنسان عاقل ؟! هل هذه تصرفات إنسان يحترم نفسه ؟! إنك كذا وكذا وكذا » ويصب عليه سيلاً من الألفاظ الجارحة تشعره أنه أمام عدو ... !",{h:"لذلك إن كلمت إنساناً من أجل خلاص نفسه ، فغضب ولم يقبل منك ، راجع نفسك : ربما نصيحتك له كانت خالية من المحبة أو من الاتضاع ."},"ومن الجائز أن نفس النصيحة يقدمها له خادم آخر ، ولكن بأسلوب مقبول يستريح له ويشكره عليه . لذلك حسناً قال الكتاب « رابح النفوس حكيم » (أم ١١ : ٣٠) .","لذلك إن قلنا إنه من أبواب الإدانة غير الخاطئة : النصح والهداية ... إنما نقصد النصح الحكيم ، المملوء حباً واتضاعاً ... ولا نقصد كل نصح مهما كان أسلوبه ...",{h:"فحسب نوعية الأسلوب يصير النصح خطأ أو صواباً ."}],20:["وحسب نوعية الأسلوب ، يدخل النصح والتوبيخ فى نطاق الإدانة الخاطئة ، أو فى نطاق الإدانة غير الخاطئة .","إنك تستطيع أن تدرك تماماً إن كان الذى يوبخك هو مشفق عليك ، أم هو يحتقرك ويزدريك . روحه فى الحديث ، ولهجته ، وألفاظه ومشاعره ، هى التى تترك فى نفسك أثراً ، ربما أكثر من موضوعية التوبيخ ...",{h:"٢ ـ كذلك ينبغى أن يكون التبكيت بحق ، وليس ظلماً :"},"ولعلنا نذكر مثلاً للتبكيت الظالم ، موقف عالى الكاهن من حنة زوجة القانة . كانت عاقراً لا تنجب . وكان لضرتها فننة أولاد ، فكانت تلك تغيظها . وذهبت حنة إلى هيكل الرب ، وسكبت نفسها أمامه . كانت تصلى وهى مرة النفس ، وقد بكت بكاء ، ونذرت نذراً إن أعطاها الرب نسلاً أن تقدمه نذيراً للرب يخدمه كل أيام حياته . كانت تكلم الرب فى قلبها ، وصوتها لم يُسمع ، وشفتاها فقط تتحركان ، حتى أن عالى الكاهن ظنها سكرى ، ووجد من واجبه أن يوبخها !! فقال لها « حتى متى تسكرين ؟ انزعى خمرك عنك » (١صم ١ : ٩ ـ ١٤) .",{h:"إنه كاهن ، وله سلطان ، وهو إنسان مسئول ، ومن حقه أن يوبخ وأن يدين . ولكنه فى هذا الموقف كان مخطئاً ."},"لم يكن يوبخ عن حق . بل كان ظالماً فى إدانته ، ظالماً فى حكمه عليها ، قاسياً وجارحاً فى أسلوبه . ومع أن حنة أجابته فى أدب شديد يليق باحترام كهنوته . ولكنه مع ذلك كان مخطئاً . ومع أنه دعا لها بالخير ، إلا أنه لم يعتذر لها عن سابق كلامه ...",{h:"لذلك يجب أن يسبق التوبيخ ، الفحص والتدقيق ."},"ولا يجوز أن يوزع إنسان توبيخاته عفواً أو بدون أن يتأكد من صحة الخطأ ... ! إنما إن وثق تماماً أن ما يزمع أن يبكت عليه هو من « أعمال الظلمة غير المثمرة » حينئذ تنطبق وصية « ... بل بالحرى بكتوها » .",{h:"٣ ـ كذلك لا يجوز التبكيت لنفس مرة معذبة ."}],21:["لقد وقع فى هذه الخطية أصحاب أيوب الثلاثة ، وجرحوه أكثر من مرة ، وهو مرّ النفس ، حتى أثاروه باتهاماتهم وتوبيخاتهم ـ وكانت ظلماً ـ فقال لهم أيوب « حتى متى تعذبون نفسى وتسحقوننى بالكلام ؟ هذه عشر مرات أخزيتمونى . لم تخجلوا أن تحكرونى » « تراءفوا تراءفوا أنتم علىّ يا أصحابى ، لأن يد القدير قد مستنى » (أى ١٩ : ٢ ، ٣ ، ٢١) . وقال لهم عبارته المؤثرة « أنا أيضاً استطيع أن أتكلم مثلكم ، لو كانت أنفسكم مكان نفسى . وأن أسرد عليكم أقوالاً » (أى ١٦ : ٤) .",{h:"الإنسان المرّ النفس يحتاج إلى كلمة تعزية ، وليس إلى كلمة توبيخ ونصائح وإدانة !"},"فإن وجدت إنساناً مرّ النفس ، مهما كان مخطئاً ، لا نسمح لنفسك أن توبخه ، لئلا يبدو توبيخك لوناً من الشماتة . قل له كلمة طيبة ، كلمة تعزية . فالتوبيخ ليس الآن وقته ، وهو حالياً لا يحتمله . يكفيه ما هو فيه . واسمع قول الحكيم « لكل شىء زمان ، ولكل أمر تحت السماوات وقت » (جا ٣ : ١) . وهنا نقول الملاحظة التالية :",{h:"٤ ـ النصح والتوبيخ لا يصلحان إلا فى وقتهما المناسب :"},"وهنا تخطر على بالى قصة طريفة وهى : قيل إن صبياً نزل إلى البحر يستحم . وكان المكان خطراً فيه دوامات جذبت الطفل ، فكاد يغرق مصباح يطلب النجدة . فمر عليه رجل ورآه فى هذه الحال . فقال له « ياولد ... كيف تجرؤ أن تستحم فى البحر ، وأنت لا تتقن السباحة ؟ وكيف بلغ بك الجهل أن تستحم فى هذه المنطقة الخطرة ؟ وكيف ... ؟ فقال له الصبى « أنقذنى يا سيدى الآن . ثم وبخنى بعد ذلك ... » .",{h:"حقاً تمر أوقات على الخطاة ، يحتاجون فيها إلى من ينقذهم ، وليس إلى من يوبخهم ..."},"إن للتوبيخ وقتاً ، ربما لا يكون الأول فى الترتيب . قد تبدأ أولاً بالحب وبالمعونة . وبكل عوامل الانقاذ ، وتؤجل التوبيخ إلى حين آخر . وقد يكون الخاطىء فى حالة من الندم الشديد ، وقد بكّت نفسه بتبكيت مرّ شديد ، لا يحتاج فيه إلى مزيد ."],22:["تأمل الآب الحنون فى قصة الإبن الضال . إنه لم يبكت هذا الإبن بعبارة واحدة ، بل رآه من بعيد فتحنن وركض ووقع على عنقه وقبّله ، وألبسه الحلة الأولى ، وذبح له العجل المسمن ... (لو ١٥ : ١٧ ـ ٢٣) ... كان ذلك وقت فرح ، ولم يكن وقت تبكيت ...",{h:"إن النصح والتبكيت قد يدخلان فى نطاق الإدانة غير الخاطئة ، ولكن بشروط ..."},"هى ما ذكرناه ... وبغير ذلك قد يتغير الأمر ، ويتحول التبكيت إلى جرح وإهانة وإدانة ، وربما يأتى بنتائج عكسية .","نقطة أخرى نقولها فى شروط النصح والتبكيت وهى :",{h:"٥ ـ أحياناً يصلح تبكيت الخاطىء ، إن كان ذلك « فيما بينك وبينه وحدكما » (متى ١٨ : ١٥) ."},"حيث لا يتعرض للخجل أمام الناس ، وحيث لا تنكشف أخطاؤه أمام الآخرين . وحيث يستطيع أن يعترف بالخطأ . ويعتذر عنه ، ويقبل التبكيت عليه ، إذ لا يراه أحد ، فلا يراق ماء وجهه أمام الآخرين ، ولا ينفضح أمام الناس . هذا هو النصح فيما بينك وبينه ، والتبكيت المستور ، والمقبول .",{h:"أما إن قمت بتبكيته أمام الناس ، فقد يضطر أن ينكر ، أو يدافع عن نفسه ، أو يكابر !"},"حتى لو فعلت ذلك بمحبة واتضاع . ولكن إنكشافه أمام الآخرين قد يضطره أن يحمى سمعته بالدفاع الباطل ، وربما بالكذب ... وتكون أنت قد أعثرته ، ودفعته إلى كل ذلك ، لأنك فضحته علناً ، وخدشت حياءه ، وجرحت كرامته ...",{h:"وقد لا يخجل ، بل يتبجح ويقول « نعم قد فعلت » ."},"ليس فى انسحاق قلب ، وإنما فى تحدٍ وفى مقاومة . وفى اصرار على أن لا يبدو ضعيفاً أمام الناس !"],23:["أما الذين قال عنهم الرسل « وبخهم أمام الجميع لكى يكون عند الباقين خوف » (١تى ٥ : ٢٠) فهؤلاء هم الذين خطيتهم معروفة للكل ، وأصبح الأمر يتعلق بسلامة الكنيسة كلها وحفظ قيمها وروحياتها ... وصار الهدف هو « لكى يكون عند الباقين خوف » ... مثال ذلك أناس وقفوا فى وسط الكنيسة يحدثون ضوضاء وهياجاً ويتكلمون بما لا يليق ، بغير مبالاة ، فهؤلاء يحتاجون إلى توبيخ عام ، وليس فيما بينك وبينهم .",{h:"٦ ـ النقد"},"قد يكون عمل الإنسان أنه ناقد فى أية صحيفة من الصحف : ناقد روائى ، أو ناقد أدبى ، أو ناقد مسرحى ، أو ناقد رياضى ...",{h:"فهل يترك عمله كناقد على اعتبار أنه يوقعه فى الإدانة ؟ وما الفرق بين النقد والإدانة ؟"},"كلا ، لا يترك عمله . إنما يسلك فيه بطريقة سليمة وبأسلوب روحى ، مبنية على أسس علمية . ولا يكون أسلوبه هو الهدم والتجريح . وهناك فروق بين النقد والإدانة .",{h:"الفرق الأساسى بين النقد والإدانة ، هو أن النقد يلتزم الموضوعية . أما الإدانة فكثيراً ما تمس النواحى الشخصية ."},"النقد يتناول الموضوع ويحلله ، ويقوم بعملية تقييم عادلة ، يذكر ما فيه من المحاسن ومن العيوب على السواء . وقد يذكر أسباب النجاح وأسباب الفشل فى كل النواحى . وإن كانت هناك مساوىء ، يقترح الوضع السليم الذى كان يجب اتباعه .",{h:"إذن النقد هو عملية تقييم . وكثيراً ما يلزم التقييم فى كل حياتنا الإجتماعية والكنسية ، بل وفى كل أنشطتنا ."}],24:["والهدف من هذا التقييم هو الوصول إلى الأفضل ، باجتناب العيوب ، وتحسين مستوى النجاح ورفع درجته . ولذلك كثيراً ما يجلس الإنسان لتقييم أعماله . ويعرف هذا باسم (النقد الذاتى) ، ويُعرف فى الروحيات باسم (محاسبة النفس) .","والنقد علم ، له قواعده وأصوله وأسلوبه . بل له حدوده أيضاً التى لا يتعداها ، والتى إن خرج عنها لا يكون نقداً ، أو لا يكون نقداً سليماً .",{h:"والنقد الذى لا يذكر سوى المساوىء ، هو لون من الهجوم . ولا يكون صاحبه منصفاً ."},"لذلك هناك أنواع ودرجات من النقد ، منها النقد الهادىء الرزين ذو الأسلوب العفّ . وهو النقد السليم المقبول . ومنها النقد اللاذع ، والنقد الجارح . وكل ناقد يختلف فى أسلوبه عن الآخر ، ويختلف فى اختيار الألفاظ التى يستخدمها ... والناقد المنصف يتخير الألفاظ كما بميزان دقيق جداً . فإن كنت ناقداً ، انظر من أى نوع أنت ... ؟",{h:"كن موضوعياً ومنصفاً ، ولا تكن قاسياً فى نقدك ."},"ربما ناقد أدبى أو علمى ينقد كتاباً ، فيكون نقده تكملة لازمة لهذا الكتاب ، تحتاج إليها معلوماته . وربما ناقد ينقد كتاباً ، فيكون نقده مديحاً خالصاً ، إن كان الكتاب يستحق ذلك .",{h:"كذلك النقد يحتاج إلى دراسة واعية ."},"يحتاج إلى معرفة واسعة جداً بالموضوع الذى ينقده ، كما يحتاج إلى معرفة بفن النقد وأصوله وليس كل إنسان يرقى إلى مرتبة الناقد ، أو يدعى لنفسه هذه الصفة . وليس كل ناقد يحترمه المجتمع ويثق به كناقد ...",{h:"والناقد المنصف يستفيد من نقده القراء ، ويستفيد الشخص صاحب موضوع النقد . ويكون نقده للبنيان ، مقدماً فيه علماً وأدباً وفناً ..."},"يقول الرب فى سفر اشعياء النبى « ويل للقائلين للشر خيراً ، وللخير شراً . الجاعلين الظلام نوراً ، والنور ظلاماً . الجاعلين المر حلواً ، والحلو مراً » (أش ٥ : ٢٠) ."],25:[{h:"هل إذا طلبت فى مجال الشهادة فى محكمة : اتراك تستطيع أن تقع فى شهادة زور لكى تبرىء مذنباً ؟!"},"وهل إذا قلت الحق ، اتراك تقع فى خطية إدانة ؟! حاشا . بل أنك بتبرئة المذنب تقع فى خطية كذب . كذلك فى معاملاتك الخاصة .","إن لم تستطع أن تقول الحق ، فعلى الأقل اصمت ، فهذا أفضل من تبرئة المذنب ، تبرئة تخدع بها السامعين .","لعل من أبرز أنواع الإدانة غير الخاطئة :",{h:"٧ ـ إدانة النفس"},"إنها فضيلة ، توصل إلى الاتضاع ، وإلى التوبة والنقاوة ، وإلى امتصاص الرغبة فى الإدانة بطريقة سليمة . وقد قال القديس مكاريوس الكبير « احكم يا أخى على نفسك قبل أن يحكموا عليك » .","قال القديس الأنبا أنطونيوس « إن دنا أنفسنا ، رضى الديان عنا » . كذلك إن الذى يدين نفسه ، ويوبخ ذاتها لكى يقومها ، هذا لا يجد دافعاً داخلياً لإدانة غيره ، لأنه يشعر أنه مخطىء مثل ذلك وربما أكثر .",{h:"وإدانة النفس ، تحمى الإنسان من إدانته لغيره ."},"قال القديس الأنبا موسى عن انشغال الإنسان بخطاياه ، إنشغالاً لا يسمح له أن يتفرغ للحديث عن خطايا غيره :",{h:"من من الناس يكون عنده ميت فلا يبكى عليه ، وإنما يتركه ليبكى على ميت عند جيرانه ؟!"},"نحب فى موضوع الإدانة أن نورد ملاحظة أخيرة وهى :"],26:[{h:"من يبرىء المذنب"},"يحدث عند البعض أحياناً ، أنهم يبرئون كل أحد ـ مهما كان مخطئاً ـ حتى لا يقعوا فى خطية الإدانة . وأمثال هؤلاء ، عليهم أن يسمعوا قول الكتاب :",{h:"« مبرىء المذنب ، ومذنب البرىء ، كلاهما مكرهة الرب » (أم ١٧ : ١٥) ."},"ذلك لأن كليهما بعيد عن الحق ، ويتكلم بالباطل . ونلاحظ هنا أنه وضع عبارة (مبرىء المذنب) أولاً .","فلا تظن أنك تكون ذا قلب شفوق إن كنت تبرّىء المذنب . فالذنب هو ذنب . والخطأ هو خطأ . قد تدافع عن المذنب من حيث أنه فعل الذنب عن جهل ، أو عن ضعف ، أو عن خوف ، أو بسبب ظروف ضاغطة تخفف بهذا من ذنبه . ولكن لا تستطيع أن تبرئه ، أو تدعى أنه لم يخطىء ... !",{h:"بل يحدث أحياناً أن مبرىء المذنب يثير السامعين ."},"ويجعلهم يدينونه هو فى دفاعه عن الباطل ، ويدينون المذنب بأكثر شدة حتى يوازنوا مع ما قيل فى تبرئته . وهكذا تأتى هذه التبرئة بعكس المقصود منها .",{h:"كما أن تبرئة المذنب تساعد على الاستهتار ."},"سواء من جهة هذا المذنب ، الذى لا يشعر بتأنيب الضمير بسبب محاولة تبرئته ، فيستمر فى أخطائه ، أو من جهة استهتار من يقلدونه ، شاعرين أنهم سيجدون من يعمل على تبرئتهم .","وقد سئل القديس باسيليوس الكبير هذا السؤال .",{h:"ما هى دينونة الذين يحامون عن المخطىء ويدافعون عنه ؟"},"قال أظن أنها دينونة ثقيلة ، أكثر من دينونة الذى يعثر غيره ، كما وردت فى الإنجيل (متى ١٨ : ٢٩ ، ٣٠) ."],27:[{h:"لأن الذى يدافع عن المخطىء ، يمنع المخطىء من أن يتوب ."},"ويجعله بهذا يستمر فى خطيته ، ويعلّم غيره شرّه .","وهذا حق ، لأنه إن كان هذا الذى يدافع يقول : ماذا فعل (فلان) ؟ لا يوجد خطأ فى كل ما فعله ... فهو بهذا الكلام يشجع غيره أن يفعل مثله مادام الفعل غير مدان .","هنا ويواجهنا سؤال لابد من الإجابة عليه ، وهو :",{h:"لماذا إذن ينصحنا القديسون أن ندافع عن المخطئين ؟"},"للإجابة على هذا السؤال ينبغى أن نعرف تماماً ما هى نوعية الدفاع ؟ ليس معنى الدفاع أن نقلب الموازين الروحية ، ونقول عن الخطأ إنه صواب . كلا بلاشك . فقد قال الكتاب : ويل لمن يقول عن المرّ أنه حلو (أش ٥ : ٢٠) .",{h:"وإنما الدفاع هنا ينصب على الظروف المحيطة ، وليس على كنه العمل ذاته ."},"كأن ندافع بسبب أن الحرب كانت ثقيلة عليهم ، مع ضعف الطبيعة البشرية ، كما نقول فى أوشية الراقدين « إذ لبسوا جسداً ، وسكنوا فى هذا العالم » وإنه « ليس أحد بلا خطية ، وإن كانت حياته يوماً واحداً على الأرض » أو نعتذر عنهم بمكر الشيطان المحارب وخديعته وكثرة حيله .",{h:"أو ندافع بأنهم فعلوا ذلك جهلاً ...."},"كما قال السيد المسيح عن صالبيه « لأنهم لا يدرون ماذا يفعلون » (لو ٢٣ : ٣٤) . وقال القديس بولس الرسول « لأنهم لو عرفوا ، لما صلبوا رب المجد » (١كو ٢ : ٨) .","أو نقول إنه كان فى حالة إثارة ، بحيث لم يستطع أن يملك نفسه ، أو كان واقعاً تحت إغراء أو ضغوط أو عثرة ...","ولكن لا يمكننا أن ننفى الخطأ ، أو ندعى أنه ليس خطأ . بل نحدث فقط عن"],28:["الظروف المحيطة . تماماً كالمحامى الذى ينفى التهمة ، أو الركن المادى منها ، ويتحدث فقط عن الركن الأدبى أو الحالة النفسية أو العقلية للمتهم .","ولا يكون القصد سوى التخفيف من وقع الخطأ بدافع الرحمة ، وليس انكار وجود الخطأ ، كأن يقول إنسان مثلاً « كلنا تحت الزلل » أو « كلنا معرضون للخطأ » . أو كما دافع بعضهم عن خطأ نُسب إلى شخص كبير ، فقال : هذه هى الطبيعة البشرية . والكتاب يحكى عن نبى عظيم جداً مثل إيليا فيقول :",{h:"« إيليا كان إنساناً تحت الآلام مثلنا » (يع ٥ : ١٧) ."},"مع إنه صلى صلاة أن لا تمطر السماء ثلاث سنين وستة أشهر فلم تمطر ، ثم صلى بعدها فأعطت السماء مطراً (يع ٥ : ١٧ ، ١٨) .",{h:"ويقع فى محاولة تبرئة المذنب من يتملق الكبار !"},"محاولاً أن يبرىء أخطاءهم مهما كانت جسيمة ، بأسلوب بعيد عن الحق . وبسبب هذا التملق ، يسقط كثير من الكبار فى أخطاء ويستمرون فيها ، ولا تبكتهم ضمائرهم ، بل قد يفتخرون بما وقعوا فيه من أخطاء !! ويدفعهم من يبرئهم إلى العزة بالإثم وإلى سياسات خاطئة ، ويشترك معهم فى أعمالهم الشريرة .","إن كان الذين يصمتون على الخطأ ، ولا يخرجون الخبيث من وسطهم ، يدانون كما دان بولس الرسول أهل كورنثوس . فماذا نقول إذن عن الذين يحامون عن الخطأ ويدافعون عنه ويبررونه ؟ لاشك أن هؤلاء دينونتهم أعظم ."],29:[{h:"شروط الإدانة غير الخاطئة"},{h:"١ ـ أن تصدر من شخص مسئول :"},"وقد شرحنا هذا الأمر من قبل . ويبقى أمامك فى كل مرة تدين فيها غيرك : أن تسأل نفسك قائلاً « من أقامنى قاضياً » (لو ١٢ : ١٤) أو من أقامنى معلماً ؟ فإن وجدت أنك فى موضع المسئولية فعلاً ، فلا مانع ...",{h:"٢ ـ الإدانة تقوم على أساس من المعرفة :"},"إن الله هو « ديان الأرض كلها » (تك ١٨ : ٢٥) ، لأنه بالإضافة إلى سلطانه الإلهى ، يوجد عدل فى دينونته لأنها قائمة على أساس من المعرفة الشاملة الأكيدة ، فهو العارف بكل شىء ، وهو الفاحص القلوب ، والقارىء الأفكار ، ويعلم ما يجول فى مشاعر الإنسان ونياته ، ويعرف الخفيات والظاهرات .",{h:"وقضاة الأرض يبنون عدلهم فى أحكامهم على أساس من التحقيقات ،"},"توصلهم إلى ما يمكن الوصول إليه من المعرفة : تحقيقات فى مراكز الشرطة والنيابة والمحكمة ، مع فحص الأدلة ، وسماع الشهود ومناقشتهم ، وإعطاء فرصة كاملة للدفاع وللرد على أدلة الأتهام .",{h:"أما أنت ، فما هى معرفتك حتى تحكم ؟!"},"ألا يحدث أن يدين الإنسان غيره عن طريق السماع والشائعات أحياناً ، وعن طريق الظن فى أحيان أخرى ، وبدون سماع دفاعه عن نفسه فى كل الحالات تقريباً !! ودون معرفة بظروفه ، وقصده ، وأسباب ما حدث منه ...",{h:"وربما لو اتيح لنا أن نعرف الحقيقة كاملة ، لندمنا على أحكامنا واعتذرنا عنها !"}],30:["من أجل هذا لا يجوز لك أن تدين إنساناً فى تصرف ما ، بدون أن تبحث وتفحص وتحقق وتعطيه فرصة أن يجيب عن نفسه . وليس من اللائق أن تلقى أحكامك بسرعة ، وتحكم على شخص قبل أن يحكم الله عليه ... وما أصدق قول الرسول :",{h:"« لا تحكموا فى شىء قبل الوقت » (١كو ٤ : ٥) ."},"ويتابع الرسول كلامه فيقول « حتى يأتى الرب الذى سينير خفايا الظلام ، ويظهر آراء القلوب . وحينئذ يكون المدح لكل واحد من الله » .",{h:"لا تحكموا قبل الوقت"},"قال القديس أوغسطينوس فى تفسير هذه الآية (١كو ٤ : ٥) :","هناك خطايا واضحة قال عنها الرسول « خطايا بعض الناس واضحة تتقدم إلى القضاء » (١تى ٥ : ٢٤) . هذه الخطايا الواضحة إذا صدر عنها حكم ، لا يكون حكماً متسرعاً . ولكن هناك أموراً أخرى غير واضحة ، سيعلنها الله حينما يكشف ما فى القلوب وينير خفايا الظلام (١كو ٤ : ٥) . عن هذه الأمور قال الكتاب « لا تحكموا قبل الوقت » .","لأن تصرفاً معيناً قد يبدو لنا أنه خطأ . ولكن حينما يكشف الله نيات القلوب يظهر أنه تصرف سليم . والعكس صحيح : تصرف يبدو سليماً ، وحينما يكشف الله نيات القلوب يظهر أنه خطأ . فلا تحكموا إذن قبل الوقت فى هذه الأمور التى نيتها غير واضحة ، والتى ستبقى مخفاه ، إلى أن يعلنها الله .",{h:"إذن حكمنا هو فى الأمور الواضحة . أما غير الواضحة فنتركها لله ، إلى أن يعلنها ."},{h:"٣ ـ لا يجوز أن تحكم على أحد وأنت مثله ، أو أسوأ :"},"وهذا واضح من قول السيد المسيح للذين طلبوا رجم المرأة المضبوطة فى ذات الفعل . فمع أن الخطيئة كانت واضحة وفاضحة وثابتة ، إلا أنه قال لهم « من كان منكم"],31:["بلا خطية ، فليرمها أولاً بحجر » (يو ٨ : ٧) . فانصرفوا جميعاً وتركوها لأن الكل خطاة . والمثل يقول « من كان بيته من زجاج ، لا يقذف الناس بالحجارة » .",{h:"لذلك فالإنسان المتواضع لا يدين أحداً ..."},"إنه ينصت فى انسحاق قلب إلى قول السيد المسيح « لماذا تنظر القذى الذى فى عين أخيك . وأما الخشبة التى فى عينك فلا تفطن لها ؟! ... يا مرائى اخرج أولاً الخشبة من عينك . وحينئذ تبصر جيداً أن تخرج القذى من عين أخيك » (متى ٧ : ٣ ـ ٥) .",{h:"والمتضع إذا اضطر أن يدين ، يفعل ذلك باتضاع ."},"لا بعجرفة ، ولا بكبرياء ، ولا باحتقار وازدراء لغيره . ويكون موضوعياً ، فلا يجرح أحساس غيره ولا يخجله . وكما قال الرسول « أيها الأخوة إن إنسبق إنسان ، فأخذ فى زلة ، فاصلحوا أنتم الروحانيين مثل هذا بروح الوداعة ، ناظراً إلى نفسك لئلا تجرب أنت أيضاً . احملوا بعضكم أثقال بعض » (غل ٦ : ١ ، ٢) .",{h:"٤ ـ لا تكون الإدانة بحقد ولا بغيظ ولا بكراهية :"},"حتى إن كان الذى يدين ، يفعل ذلك بسلطان وعن معرفة ، إلا أن ادانته إذا ما اختلطت بالكراهية والحقد تصبح إدانة خاطئة . لأن « المحبة لا تفرح بالإثم ، بل تفرح بالحق » (١كو ١٣ : ٦) .",{h:"الحكم بالحق"},"سئل القديس باسيليوس الكبير عن معنى قول الرب « لا تدينوا لكى لا تدانوا » (متى ٧ : ١) ، فأجاب : قال الرب فى موضع آخر :",{h:"« لا تنظر إلى الوجوه ... العدل العدل تتبع لكى تحيا » (تث ١٦ : ١٩ ، ٢٠) ."},"« لا تنظر إلى الوجوه » أو « لا تأخذ بالوجوه » معناها « لا تحابِ » . إياك والمحاباة ، بل أحكم بالعدل والحق . وهنا قال القديس :"],32:["إن الله لم يمنعنا عن الإدانة جملةً ، بل أمرنا أن ندين بالحق ، فى الوقت المناسب وعن عمل دون عمل .","فالأشياء التى لم يحدّ الكتاب لها حداً ، بل وضعها تحت سلطان الإنسان مثل الأكل والشرب وغير ذلك ، قال الرسول فيها « لماذا تدين أخاك ... ؟ » (رو ١٤ : ١٠) وأيضاً « لا نحاكم بعضنا بعضاً » (رو ١٤ : ١٣) .",{h:"« أما الأمور التى لا ترضى الله ... فقد لام الذين لا يدينون عليها »"},"يقصد لام المجموعة كلها The whole community ، لأنه كان ينبغى عليها أن تدين الشخص المخطىء . وذكرهم بقول الكتاب « اعزلوا الخبيث من وسطكم » (١كو ٥ : ١٣) . فربما من أجل خطية إنسان واحد ، يحل غضب الله على المجموعة كلها .",{h:"والمجموعة مسئولة عن أن تنظف نفسها ، وتعزل الخبيث من وسطها ، لئلا يحل غضب الله على الكل بسبب خطية واحد ."},"لقد كادت السفينة كلها أن تغرق بسبب خطية واحد هو يونان ، بينما باقى ركابها ما كان لهم ذنب . وأيام يشوع بن يونان ، غضب الله على المجموعة كلها بسبب خطية واحد هو عخان بن كرمى (يش ٧) .","فمن الحق أن تدين الشر الذى فيها ، وتخرجه خارجاً ، لئلا تهلك كلها بسببه .",{h:"ولكن هذه الخطوة تحتاج إلى حكمة ."},"قال القديس باسيليوس إن هناك بعض الأمور التى ينطبق عليها قول الكتاب :",{h:"غيرة بيتك أكلتنى ، لأن اعداءك نسوا وصاياك » (مز ١١٩) ."},"إنها غيرة لله . ولابد للإنسان أن يفرق بين ما إذا كان الدافع للإدانة هو الغيرة المقدسة ، أم أن الدافع هو حقد شخصى ، أو كراهية شخصية ، أو شماتة بإنسان مخطىء . فإن كانت هى الغيرة المقدسة ـ وليس تكون الإدانة مقبولة ـ ولكن ...",{h:"هذه الغيرة ينبغى أن تكون حسب المعرفة (رو ١٠ : ٢) ."}],33:[{h:"الفصل الثانى"},{h:"أنواع إدانة الآخرين"},"الإدانة بالفكر","الإدانة باللسان","الاغتياب","النميمة","الإدانة","التشهير","الإدانة بالمطبوعات والتسجيلات الصوتية","الإدانة بالسماع","كلام يسهل الإدانة","أنواع أخرى من الإدانة"],34:["إدانة الآخرين ليس لها أسلوب واحد ، ولا تكون بالكلام وباللسان فقط ، إنما قد تبدأ أولاً بالفكر ، أو تحدث عن طريق السماع . أو قد تكون مجرد شعور فى القلب ، يتطور من حال إلى حال . وربما تصدر عن طريق الملامح والحركات .","وقد تحدث الإدانة بطريق غير مباشر ، وقد تأخذ صوراً مختلفة ، وتصل إلى درجات خطيرة ، كلما ارتبطت بمشاعر أخرى .","وسنحاول أن نتناول كل هذه الأنواع والدرجات بالتفصيل ..",{h:"الإدانة بالفكر"},"الإدانة بالفكر ، ربما تكون أخف ألوان الإدانة ، لأنها قاصرة على الشخص الذى يدين ، ولم تنتشر فى الخارج .","ولكن خطورتها أنها نقطة البدء ، وانها المصدر لكل الأنواع الأخرى من الإدانة . لذلك يجب الانتصار عليها قبل أن تتطور ، وقبل أن تسىء إلى آخرين ، وتنتقل من درجة إلى أخرى .",{h:"على أن الإدانة بالفكر قد تكون أولاً مجرد حرب روحية ."},"وقد ينتصر عليها الإنسان ويطردها من ذهنه ، قبل أن تصبح خطية . أما إذا ترك فكر الإدانة داخله ، وبدأ يقتنع به ، ثم خلطه أيضاً بمشاعره ، فحينئذ لا تكون الإدانة مجرد حرب ، لأنها لاقت قبولاً فى الداخل .",{h:"وقد لا يكتفى الإنسان بالرضى بفكر الإدانة ، وإنما يضيف عليه تصورات وتخيلات من عنده ، لتكبيره وتجسيمه ."}],35:["ويحدث هذا كثيراً ، إن كان لا يحب الشخص الذى يدينه ، أو إن كان يكرهه أو يحقد عليه ... وحينئذ لا يكتفى بأن يجعل فكر الإدانة يستقر ويستمر ... ولا يكتفى بالتفكير فى أخطاء الشخص التى أمامه ، إنما يخترع فى ذهنه قصصاً يمكن أن تحدث مع هذا الإنسان : كأن يقع فى أخطاء أخرى ، وينكشف فيها أمام الناس ، أو أن يضبطوه فى كذا وكذا ، وينفضح ، أو يُحاكم .",{h:"وهكذا يكون الفكر مجرد شاشة يعرض عليها القلب ما فى داخله من مشاعر خاطئة وتصورات بشعة ."},"المفروض أن توقف فكر الإدانة بمجرد أن يخطر على ذهنك . ولكنك إن وصلت إلى هذا الحد ، فإن الأمر معك لا يقتصر على علاج الإدانة ، وإنما بالأكثر معالجة أسبابها ، والتخلص مما فى القلب من مشاعر خاطئة ...",{h:"والإدانة بالفكر تتبادل الموقع مع الإدانة بالقلب :"},"فالفكر حينما يدين إنساناً ، يوصل مشاعر خاصة بهذه الإدانة إلى القلب . والقلب إذا وجدت فيه أمثال هذه المشاعر ، يصدر أفكاراً إلى العقل . وهكذا يغذى كل منهما الآخر .",{h:"الإدانة باللسان"},{h:"خطورتها أن الإدانة تخرج من فكر أو لسان صاحبها ، لكى تصب فى آذان وأفكار ومشاعر آخرين ."},"إن الإنسان الذى يدين بالفكر ، إن تاب عن خطيته ينتهى الأمر عند هذا الحد . أما الذى يدين بلسانه ويسمعه غيره ويتأثر به ، فإن تاب لا تكون إدانته قد انتهت ، لأنها لا تزال موجودة فى فكر غيره وفى معرفته .","وما يدرينا إلى كم شخص قد وصل هذا الكلام .","على أن الإدانة باللسان ، هى أيضاً متعددة الأنواع ، منها :"],36:[{h:"الاغتياب"},"ومعناها أن إنساناً يتكلم بالسوء على غيره فى غيبته . وربما لا يجرؤ أن يقول شيئاً من هذا فى حضرته . وقد يحرص كل الحرص أن يظل كلامه مستوراً لا يصل إطلاقاً إلى هذا الشخص . ومن أمثلة (الغيبة) ما يقال عن الرؤساء والكبار . وعلى رأى المثل « الملك من هيبته ، يُشتم فى غيبته » ...",{h:"ومن أضرار الاغتياب أن الشخص الذى يُساء إليه سراً ليست لديه الفرصة للدفاع عن نفسه ، لأنه لا يعرف !"},"فإن كان الذين يسمعون ، من النوع الذى يصدق كل ما يسمعه ، ففى هذه الحالة تسوء سمعته ، وهو لا يدرى ، ودون أن تكون أمامه لشرح الحقيقة ، وتوضيح الأمور وشرحها وتبرير ما يُنسب إليه .",{h:"والغيبة تدل على أن صاحبها تنقصه الشجاعة والجرأة ..."},"بل قد تدل على أنه يتصف بالرياء والنفاق ، إن كان يقول كلاماً عكس هذا فى حضرة من يسىء إليه باغتيابه ...",{h:"النميمة"},"وهى مسك سيرة الناس ، والتحدث عن اخطائهم ، أو نسبة أخطاء إليهم . والنميمة مرض منتشر بين الكثيرين . فإذ لا يجدون شيئاً نافعاً يتحدثون فيه ، يجعلون أخبار الناس مادة مفضلة لأحاديثهم ، وبخاصة ما تحمله هذه الأخبار من انتقادات وتحليل للمواقف ، وشرح الأخطاء والنقائص .",{h:"ولذلك فمن ضمن أسباب النميمة الفراغ ."}],37:["فالإنسان المشغول باستمرار ، لا يجد وقتاً يتحدث فيه عن أخبار الناس واخطائهم . والسيدة العاملة قد تكون أقل وقوعاً فى هذه الخطية من السيدات الجالسات فى البيوت ، ولا حديث لهن إلا عن أخبار الجيران . والتلميذ فى أيام الامتحانات ، وهو منشغل بدروسه ومراجعتها ، لا يجد وقتاً يجلس فيه مع زميل يتحدثان فى مساوىء الآخرين . وإذا فتح له هذا الموضوع لا يجد دافعاً داخلياً للاسترسال فيه ...",{h:"لذلك اشغل نفسك ، حتى لا تقع فى الإدانة والنميمة ."},{h:"وأيضاً من أسباب النميمة معاشرة النمامين ."},"لأنهم يفتحون لك أمثال هذه الموضوعات . وإن فتحتها أنت ، يشجعونك على الاسترسال فيها . ومع هؤلاء النمامين ، تشعر أن مسك سيرة الناس شىء عادى ، لا غرابة فيه . بل تشعر أنه مجال للتسلية ، وربما تجد فيه متعة إن كان مختلطاً بروح المرح ، فتستمر دون أن يستيقظ ضميرك ، ودون حرج ...",{h:"الإدانة"},"ومعناها من جهة اللغة الحكم على الغير بأنه مذنب ...","ولكن الآباء فى بستان الرهبان يفرقون بين النميمة والإدانة ، فى أن النميمة قد تحمل الحديث عن خطأ معين قد حدث ، بينما الإدانة تحمل الحكم على أخطاء ثابتة فى الشخصية .",{h:"وهناك يوجد فرق بين الإدانة الجزئية ، والإدانة الكلية ."},"فمثلاً يوجد فرق بين قولك إن فلاناً قد كذب ، فى موقف معين ، وبين قولك إنه شخص كذاب ، أى أن الكذب جزء من عناصر شخصيته . وبالمثل يوجد فرق بين قولك إنه قد جبن أو خاف فى إحدى المناسبات ، وبين قولك بصفة عامة إنه جبان ، أى أن الجبن من مكونات شخصيته ..."],38:[{h:"كذلك هناك فرق بين الإدانة الفردية والإدانة الجماعية ."},"فهناك إنسان قد يقع فى إدانة شخص ما ، وإنسان آخر قد يتطور به الأمر إلى إدانة مجموعة معينة ، أو مدينة بأسرها ، أو شعب كامل . وقد يدين البشرية فى نواح معينة .","مثال ذلك يقول لك : المدينة الفلانية تشتهر بالبخل ، أو الشعب الفلانى يتصف بالبرود ، أو الشعب الفلانى يتصف بالتهور . وهكذا يسم الشعب كله بصفة واحدة ..",{h:"والمعروف أنه قد يوجد فى أسرة واحدة أخان أو شقيقان ، كل منهما له طبع مخالف للآخر ."},"قايين طبعه غير هابيل ، وهما شقيقان ، وكذلك طبع يعقوب يختلف عن طبع عيسو وهما توأمان . وبالمثل سليمان غير ابشالوم ، وهما شقيقان ... وهكذا فى الأسرة الواحدة طباع متنوعة . فلا نستطيع أن نحكم على طباع شخص بصفات أقربائه .","إن كان الأمر هكذا ، فما معنى الحكم على مدينة أو شعب بحكم واحد وربما يكون المقصود هو الصفة الغالبة . ومع ذلك فقد لا توجد هذه الصفة عند البعض .",{h:"وقد يتأثر إنسان بحادث معين وقع له مع شخص ما ، لكى يصدر حكماً على هذا الشخص يشمل حياته وصفاته كلها ."},"بينما كل شخص قد تمر عليه فى حياته فترة ضعف ، أو فتور ، أو فترة يكون فيها تحت ضغطات معينة ، أو فى حالة نفسية مؤقتة نتيجة لأسباب خاصة ... ولا يمكن أن تعبر تصرفاته فى مثل هذه الفترة عن الصورة الثابتة لشخصيته ... ولكن ويل له من حكم من رآه فى تلك الفترة ، أو فى أحد مواقفها بالذات .",{h:"ومن أمثلة الإدانة العامة : إدانة اليهود للأمم ."},"وإدانتهم أيضاً للسامريين ، وإدانتهم لكل من يتعامل مع هؤلاء وأولئك . وهكذا تعجبت المرأة السامرية من حديث السيد المسيح معها ، بينما « اليهود لا يعاملون السامريين » (يو ٤ : ٩) تعنى هنا الشعب كله ، وليس شخصاً واحداً بالذات . وهكذا نرى أن الإدانة تطورت إلى المقاطعة ، ولم تعد مجرد كلام إدانة ."],39:[{h:"ومن أمثلة الإدانة العامة أيضاً : إدانة الفريسيين للعشارين ."},"ربما كانت الصفة الغالبة فى العشارين هى الظلم ، ولكن ليس شرطاً أن يتصف بها كل عشار . فقد يوجد عشار تائب ... ونلاحظ من عمق إدانة الفريسيين للعشارين ، أن الفريسى وقف يدين العشار حتى أثناء صلاته . فأشار إلى العشار المنسحق القلب وقال « أشكرك يارب ، لأننى لست مثل سائر الناس الظالمين الخاطفين الزناة ، ولا مثل هذا العشار ... » (لو ١٨ : ١١) .","نوع آخر من أنواع الإدانة هو :",{h:"التشهير"},{h:"ومعناه أن يجعل أخطاءه مشهورة عند الآخرين ."},"والذى يقع فى التشهير ، لا يبالى بأن يحدث كل أحد عن أخطاء من يسىء إليه ، فينشر تلك الأخطاء ، أو ما يرى أنه أخطاء ، فى أوسع نطاق ممكن ، بلا حرص إطلاقاً على مشاعر وسمعة الشخص الذى يتحدث عنه ...",{h:"وتزداد خطية التشهير بشاعة ، على قدر اتساعها وانتشارها ."},"ولا تقتصر على الأشخاص الذين يتحدث معهم هذا الذى يدين غيره ، وإنما تمتد أيضاً إلى الذين ينقل إليهم سامعوه نفس الكلام ونفس الإساءات ... وما أدرانا ربما كل منهم يضيف شيئاً من عنده ، من استنتاجاته أو مفهومه الخاص . ويصبح الأمر معروفاً لدى عدد كبير جداً يصعب إحصاؤه ...",{h:"وربما المخطىء يتوب ، ولكن الشهرة الردية تظل تتبعه وتتعبه ."},"بل ربما هذه الشهرة الردية تكون عائقاً أمامه فى التوبة ... هذا إذا كان مخطئاً بالحقيقة ... لأنه فى أحيان كثيرة لا يكون التشهير مبنياً على أساس من الحق والصدق والعدل .",{h:"ربما يبنى التشهير على شائعات أو إدعاءات ."}],40:["وما أسهل أن يحدث هذا من جانب الحاقدين أو الحاسدين أو الظالمين أو أصحاب الأغراض ... !","إن آخاب الملك عندما أراد أن يستولى على حقل نابوت اليزرعيلى ، دبرت إيزابل زوجته مؤامرة للإيقاع بنابوت ، بأن يشاع عنه أنه جدف على الله ، وأرسلت رسائل إلى شيوخ وأشراف مدينته بذلك ، ونادوا بصوم ، واجلسوا نابوت فى رأس الشعب ، وشهروا به تشهيراً انتهى إلى رجمه ... وكان بريئاً ... (١مل ٢١) .","ولعل تشهيراً ظالماً مثل هذا حدث ليوسف الصديق ، انتهى إلى سجنه . بل أن تشهيراً ظالماً آخر أشاعه الكتبة والفريسيون ضد السيد المسيح نفسه ، انتهى إلى صلبه ...",{h:"وإن كانت كل هذه الأمثلة ثبتت براءتها ، فإن تشهيرات أخرى قد لا تنال فرصة لإثبات براءتها ..."},"ومن خطية الإدانة بالتشهير ، ما يسمونه فى مواد القانون باسم « القذف العلنى » . وأحياناً لا يكون هذا التشهير باللسان ، وإنما عن طريق الصحافة مثلاً ، حيث تقوم حملة صحفية عنيفة ضد شخص ما ، أو ضد هيئة معينة ، أو بلد من البلاد ، وتؤدى هذه الحملة إلى سوء سمعة واسعة النطاق ، أو إلى فضيحة عالمية . وبعض هذه الحملات انتهت إلى سقوط رئيس دولة ، أو سقوط وزارة ، أو إقالة وزير ... فكم بالأُولى يكون تأثيرها على شخص لا يملك دفاعاً عن نفسه ؟","وهذا يقودنا إلى نوع آخر من الإدانة وهو :",{h:"الإدانة بالمطبوعات والتسجيلات الصوتية"},{h:"وهذه تكون أكثر خطراً ، لأنها أوسع انتشاراً ."},"فقد لا تكون الإدانة باللسان ، وإنما عن طريق منشور مطبوع تُوزع منه نسخ بعشرات الآلاف وتنتشر ، أو تكون عن طريق كتاب مطبوع أو نبذة . أو تكون هذه الإدانة فى"],41:["مقال ينشر فى الصحف ويسىء إلى إنسان أو إلى مجموعة من الناس . أو صورة أُخذت بطريقة ما ، وتُطبع وتنشر بقصد الإساءة .","ويشبه هذا النوع ، خطابات يرسلها شخص إلى آخرين ، تحوى أخباراً فيها إساءة إلى إنسان ما ، وفيها إدانة له . والقصد بها هو التشهير .",{h:"ويدخل فى الإدانة باللسان : التسجيلات الصوتية ."},"فهى لسان مستمر فى الكلام ، كلما شئنا له أن ينطق . وهذا النوع أكثر ثباتاً وأنتشاراً من كلمة يقولها شخص فى وقت ما ، دون تكرار لها . وهو أيضاً من الوثائق المحفوظة التى يمكن أستخدامها فى أى وقت ، ويمكن أن تطبع منها نسخ عديدة تساعد على أنتشار ما يراد سماعه .",{h:"وتكون الإدانة باللسان صعبة ، إن صدرت من فم كاهن ."},"لأن الناس يميلون بطبيعتهم إلى تصديق الآباء الكهنة وعدم الشك فى أقوالهم . فيأخذون مثل هذه الإدانة كحكم كنسى ثابت . كما يصبح من الصعب على من أصابته هذه الإدانة أن يدافع عن نفسه ، ويشكك فى قول الكاهن .",{h:"وصعوبتها أيضاً أن كل إنسان ينتظر من الكاهن أن يستر عليه ، لا أن يعلن أخطاءه .."},"ينتظر أن يسمع منه كلمة بركة لا كلمة دينونة ، كما قال السيد المسيح للمرأة الخاطئة « ولا أنا أدينك . اذهبى ولا تخطئى أيضاً » (يو ٨ : ١١) . وكما قال أيضاً :",{h:"« لم آتِ لأدين العالم ، بل لأخلص العالم » (يو ١٢ : ٤٧) ."},"ولكن يستثنى من هذه القاعدة من جهة الرعاة والكهنة ، الإدانة اللازمة لسلام الكنيسة . كإدانة الهراطقة والمبتدعين ، والذين هم خطر على الجماعة . وكذلك الخارجين عن نظام الكنيسة . كما قال القديس بولس لتلميذه تيموثاوس الأسقف « الذين يخطئون ، وبخهم أمام الجميع ، لكى يكون عند الباقين خوف » (١تى ٥ : ٢٠) . ومن أجل حفظ النظام العام فى الكنيسة ، كانت إدانة بطرس الرسول لحنانيا وسفيرا (أع ٥) ."],42:[{h:"الإدانة بالسماع"},{h:"يقول الآباء إن السامع شريك للمتكلم ، لأنه قد أعطاه فرصة ليتكلم ويقول ما عنده ."},"وقد نصح الآباء بعدم السماع . فقال القديس موسى « لا تمشِ مع النمام ... ولا تصدق كلام نميمة فى أى إنسان » .",{h:"والسامع هنا يكسر وصية البعد عن المعثرات ."},"لأنه فى سماع كلام الإدانة أو النميمة عثرة . والمفروض أن تبتعد عن العثرات . فإن سمعت كلام أشخاص يمسكون سيرة الناس ، على الأقل تشوه سمعك وفكرك وقلبك . وإذا صدقت ما تسمعه ، بدون فحص ، فقد تتغير علاقتك بالآخرين . والسماع يولّد لك إدانة بالفكر ...","* وقال الأنبا موسى أيضاً :",{h:"« أياك أن تسمع بسقطة أحد أخونك ، لئلا تكون قد دنته خفية »"},"هذا إذا صدقت ما سمعته عنه . أما إن لم تصدقه ، فعلى الأقل تكون قد دنت من يتكلم عنه . وفى كلا الموقفين تصير واقعاً فى الإدانة .","وربما الشخص الذى سمعت عنه سوءاً ، لا تدينه الآن ، وترفض قبول ما سمعته عنه . ولكن الأخبار والأفكار تتركز فى عقلك الباطن ، لكى تظهر بعد حين ...","* وقال القديس الأنبا إشعياء :","« إن سمعت أخاً يدين آخر ... فلا تستح منه أو توافقه ... لئلا يغضب الله .. بل قل باتضاع : اغفر لى يا أخى ، فإنى إنسان شقى ... وهذه الأمور التى تذكرها أنا منغمس فيها ، ولا احتمل ذكرها » ."],43:["وطبعاً ليس المقصود أن تقول هذا الكلام حرفياً ، إنما :",{h:"يكفى أن تهرب من السماع بأية وسيلة تناسبك ."},"يمكن أن تغير مجرى الحديث إلى موضوع آخر ، أو تسأل اسئلة تنقله إلى جهة أخرى ، أو أن تختم الكلام بعبارة « نصلى من أجله ومن أجل أنفسنا ، ليرحمنا الرب جميعاً » ...","أو أن تقول « هذه السقطات التى اسمع عنها تدل على أن الشيطان نشيط وقوى . حقاً ما أعجب حيل الشياطين .. » . وتحول الحديث إلى حيل الشياطين .","* قال الأنبا اشعياء أيضاً « لا تقبل أن تسمع عن خطايا أخيك أو أن تلومه » ...","* وهذه النصيحة نجدها أيضاً فى المزمور ٥١ .","حيث يقول « يارب من يسكن فى مسكنك ، أو من يصعد إلى جبل قدسك ، إلا السالك بلا عيب ، الفاعل البر ، الذى يتكلم بالحق فى قلبه ... ولا يصنع بقريبه سوءاً ، ولا يقبل عاراً على جيرانه » .","أى لا يقبل أن يسمع عنهم كلمة سوء . يرفض أن يسمع .","فالمفروض فيك إذن : أنك لا تتكلم بكلام نميمة أو إدانة ضد إنسان ، ولا تسمع مثل هذا الكلام .","* وهكذا يقول القديس مار أوغريس :",{h:"الذى يسمع بالردىء ، شريك للذى يتكلم بالردىء . وهما متعاونان معاً فى إهلاك قلبيهما ..."},"ولعله يقصد الذى يكون راضياً بهذا السماع ، ومعطياً فرصة للمتكلم به أن يقول وأن يزيد . أما الرافض السماع ، فحتى إن كان موجوداً بجسده ، فإنه لا يحب أن يصغى بأذنيه ، ولا يعطى سمعه للكلام ، بل يشغل ذهنه بأمور أخرى . ولا يقبل ما يسمعه . ولا يعاود التفكير فيه ، ولا يعطيه عمقاً فى داخله .","* يكمل القديس مار أوغريس حديثه فيقول :"],44:[{h:"« فسد أذنيك الآن عن قول الذين يقعون فى غيرهم ، لئلا تأثم معهم وتعود ذاتك الأعراض الشريرة » ."},"« تأثم معهم » لأنك رضيت أن تجلس فى مجلس من هذا النوع ، ورضيت أن تضيع وقتك ، وتفقد نقاوة فكرك ، عن طريق هذا السماع . كما أنه لو استمر بك الأمر فى أمثال هذه المجالس ، سوف تتعود هذا الأسلوب من الأحاديث . وربما تتطور من السماع إلى الاشتراك فى الكلام .","* أما مار اسحق ، فإنه يشبه الإدانة بالنار ، ويقول :",{h:"« اعلم أنه إن برزت منك نار واحرقت آخرين ، فإنه الله يطالبك بأنفس المحترقين » ."},"هذا إذا كنت أنت المتكلم . واستطعت أن تتلف بساطة الآخرين ونقاوتهم بما تقوله من كلام سىء عن أخوتهم . وهكذا تكون قد أعثرتهم ، يطالبك الله بأنفسهم ... ولكن ماذا إذا لم تكن أنت المتكلم بل السامع ؟ يقول مار اسحق :",{h:"« وإن كنت باهذا ما ألقيت ناراً ، ولكن وافقت راميها ، وارضاك فعله ، فأنت تشترك معه فى الدينونة » ."},"وانصافاً للحق ، لعلنا هنا نقسم السامعين إلى أنواع :","أ ـ نوع يسمع الكلام الردىء وهو متضايق ، ويريد أن يبتعد ، ولكنه غير مستطيع خجلاً أو أدباً .","ب ـ نوع يسمع كلام الإدانة ، ويستطيع أن يهرب من الكلام وسماعه ، أو من المكان كله ...","ج ـ نوع يسمع ، وينصت جيداً ، ويناقش الكلام فى داخله بعقل وحكمة وفحص ، ويقبل ما يمكن قبوله ، ويرفض الباقى ، كمجرد أخبار ، دون أن يحكم فى داخله على أحد ، منتظراً مجالاً أوسع للفحص والتحقيق .","د ـ نوع يسمع كلام الإدانة ويقبله ويتأثر به ، ويتغير به فكره وقلبه ، ويظل صامتاً ."],45:["هـ ـ نوع يسمع كلام الإدانة ، ويتجاوب معه بفكره ، ويشترك فيه . وهنا يخطىء بالسماع وبالكلام وبالفكر أيضاً .","و ـ وهناك نوع آخر أصعب من كل هؤلاء تحت عنوان",{h:"كلام يسهل الإدانة"},"قد لا يتلفظ إنسان بكلمة إدانة . ولكنه يسأل اسئلة ، أو يقول كلاماً يسهل الإدانة ، عن قصد وعن رغبة .",{h:"أى أنه لا يدين بلسانه ، ولكنه يفتح الباب للإدانة .."},"ربما يكون سمع بأن شخصاً ما قد وقع فى خطية معينة ، أو على وشك أن تدور حوله فضيحة ما ... فيسأل « أين فلان ؟ ما هى أخباره . لم أره من مدة ، وأحب أن أطمئن عليه » ... من يستطيع أن يقول أن هذه كلمات إدانة .. ولكن :",{h:"المهم ليس فى الكلام الذى يقوله ، إنما فى الرد الذى يتوقعه ."},"لأن سامعه ما أن يتلقى هذا السؤال ، حتى يفتح ملف ذلك الشخص المراد أن يُساء إليه ، ويحكى حكايات كلها إدانة وسوء سمعه ، ويُخاض فى سيرة هذا الإنسان وفيما ينسب إليه من اتهامات ... ويكون صاحب السؤال هو السبب فى كل هذا ، يحمل مسئولية الإدانة ...",{h:"وقد يتظاهر بالدفاع عنه ، بطريقة تعمق الإتهام وتوضحه :"},"فيقول مثلاً « من غير المعقول أن يحدث كل هذا من هذا الأخ . أنا لا استطيع مطلقاً أن أصدق » . وبهذا الكلام الذى يبدو فى ظاهره دفاعاً ، يفتح الباب أمام الأدلة والإثبات التى تؤكد كل ما ينسب إليه ... وتنتهى الجلسة بإدانة هذا الأخ إدانة تدعمها الأحداث والبراهين . وسبب كل هذا الاسئلة التى قدمها هذا الزميل فتح باب السيرة ، وفتح أبواباً للتفاصيل .",{h:"وهكذا وقع فى خطية إدانة ، تصحبها غالباً رياء ..."}],46:["فهو يتظاهر أمام الناس أنه لم يخطىء إلى ذلك الشخص ، بل كان يدافع عنه ، بينما كان قصده غير هذا ... وما أسهل أن يقول « من يستطيع أن يمسك علىّ خطأ قلته فى سمعة هذا الأخ ؟! .",{h:"بالأضافة إلى خطية العثرة ، كان يخطىء ، ويحمّل غيره المسئولية"},"وما أسهل أن يذهب إلى أب اعترافه ويقول له « صدقنى يا أبى لم أقل كلمة إساءة واحدة . الإساءات صدرت ضده من فلان ، وأنا كنت أدافع وأقول إن ذلك الكلام غير معقول !",{h:"ليس من الضرورة أن تكون خطية الإدانة مكشوفة ومباشرة ."},"من السهل أن يقع الإنسان فيها بطريقة غير مكشوفة ، وبطريقة غير مباشرة . بأن يشجع غيره على الخطأ ، أو يفتح له باب الخطأ . ويقف هو من بعيد يتفرج ويسمع ، بوجه كله (براءة) ، محتجاً على ما يقال احتجاجاً يساعد على المزيد ... إنه مجرد سأل سؤالاً ...",{h:"وقد لا يكون السؤال عن شخص ، وإنما عن موضوع ."},"والكلام يجر بعضه بعضاً إلى أن يصل إلى الشخص . وهناك موضوعات من المعروف جيداً من هم الأشخاص المرتبطون بها ، والذين يحملون المسئولية .","من أجل هذا يقول الآباء القديسون :",{h:"« لا تقل كلاماً يسهل اللائمة ... »"},"فإن كنت أنت حقاً شخصاً بعيداً عن الإدانة . فحتى إن فتح غيرك الموضوع ـ وليس أنت ـ ووجدت أن مجرى الحديث سينتهى إلى مسك سيرة إنسان ، حاول أن تغير مجراه إلى اتجاه آخر ."],47:[{h:"أنواع أخرى من الإدانة"},{h:"قد تأتى الإدانة أحياناً عن طريق الإحراج وكشف الآخرين ."},"فربما لا تقول لإنسان إنه جاهل ، ولكنك توجه إليه بضعة اسئلة منتقاه ، تعرف مقدماً أنه لا يستطيع الإجابة عنها أو هى فوق مستواه . وبهذا تحرجه وتكشف جهله أمام الآخرين . ويكون قصدك هو هذا . وتكون قد وقعت فى خطية الإدانة ، دون أن تلفظ كلمة واحدة من كلمات الإدانة . ولكن الإدانة هى فى نيتك وفى قصدك ، وقد وصلت إليها بأسئلتك .",{h:"كذلك قد تسأله عن بعض خصوصيات تحرجه وتدينه !"},"مثل : أين كنت فى اليوم الفلانى وفى اليوم الفلانى ؟ ومن الذى قابلته ؟ وماذا قلت له ؟ وماذا أعطاك ؟ وتبدو الأسئلة خالية من ألفاظ الإدانة . ولكن الإدانة كامنة فى أجابتها ، أو فيما تثيره هذه الأسئلة من شكوك فى أذهان الحاضرين ... إذ يقولون .. ولو فى ذهنهم ـ لابد أن فى الأمر شيئاً محرجاً ...",{h:"وقد تكون الإدانة فى أسلوب الشكوى :"},"لأنه لا يوجد أحد يشكو إلا من أخطاء الغير إليه . فالشكوى تحمل أتهامه بهذا الخطأ . وكلما انتشرت هذه الشكوى أمام كثيرين ، تزداد سمعة الرجل سوءاً ، كإنسان يسىء إلى غيره أو يظلمه أو يهينه ...",{h:"وقد تكون الإدانة عن طريق الملامح وليس اللسان ."},"مثال ذلك أن يسألك أحدهم عن شخص معين ، فتلوى شفتيك فى احتقار وازدراء ، أو تلوح بيدك بطريقة يفهم منها هذا المعنى ، أو تنظر نظرة خاصة ذات معنى ، أو تومىء بإيماءة لها نفس المعنى ... كل ذلك دون أن تنطق بكلمة إدانة واحدة . ولكن الملامح والإشارات تعبر تماماً عما تقصده ، دون أن تتكلم ."],48:["والإدانة قد تصل إلى درجة التحقير والتعيير .","وهذا لون آخر من الإدانة ، ارتبطت به خطايا أخرى ، وأصبح له عمق خاصر يجعله أخطر من غيره من جهة المشاعر ...","إنه نوع يهين ويجرح ، ولا يبالى بإنسانية من يدينه !",{h:"إن الذى يحتقر غيره ويزدريه لسقوطه ، هذا خطيته أصعب ممن يغتاب أو ينم أو يدين ."},"اعلم أن الشخص الذى تحتقره وتزدريه ، لسقوطه فى الخطية أو لضعفه ، أنت من نفس طبيعته القابلة للسقوط ، ويمكن أن تقع فيما وقع فيه ...","أتستطيع أن تدين شخصاً ، أغتصب اللصوص بيته وسرقوه ؟! أم أنت تشفق عليه ، تخاف لئلا يحدث لك مثل الذى حدث له ؟ هكذا الخاطىء هو فى وضع شبيه بهذا .",{h:"قال القديس الأنبا إشعياء :"},"الذى يلوم أخاه ... أو يحتقره ... أو يشى به قدام آخرين ... هو إنسان قد صار بعيداً عن الرحمة ."],49:[{h:"الفصل الثالث"},{h:"الإدانة خطية مركبة"},"إساءة إلى كثيرين :","١ ـ إساءة إلى الله","٢ ـ إساءة إلى الذى يدين","٣ ـ خطية ضد المُساء إليه","٤ ـ الإساءة إلى السامعين","٥ ـ إساءة إلى آخرين لا تعرفهم","الإدانة خطية مركبة :","١ ـ عدم المحبة","٢ ـ القسوة","٣ ـ الظلم","٤ ـ الكذب","٥ ـ عدم الاتضاع","٦ ـ اعثار الآخرين","٧ ـ الإهانة والتحقير","٨ ـ عدم اللياقة","٩ ـ الحكم على النيات","١٠ ـ الرياء"],50:["كما تحدثنا عن الغضب (النرفزة) ، وقلنا إنه خطية مركبة ، كذلك نقول عن خطية إدانة الآخرين ، إنها غالباً ما تكون مجموعة خطايا مجتمعة ومركبة معاً تحت هذا الإسم . ونبدأ فنقول إنها :",{h:"أساءة إلى كثيرين"},"فهى تحمل إساءة إلى الله ، وإلى الشخص الذى يدين غيره ، وإلى المُساء إليه ، وإلى السامع ، وإلى كل من تصلهم هذه الإدانة ولو بطريقة غير مباشرة ... فكيف ؟",{h:"١ ـ إساءة إلى الله"},"الإدانة هى عمل من أعمال الله ، لأن الله هو الديان (مز ٥٠ : ٦) ، وهو « ديان الأرض كلها » (تك ١٨ : ٢٥) . وهو الوحيد الذى يستطيع أن يدين بعدل مطلق ، لأنه فاحص القلوب والأفكار ، ويعرف النيات والمقاصد ، كما يعرف الخفيات والظاهرات ، وعلى علم بكل الملابسات والظروف المحيطة . وهو يعرف كل هذا معرفة يقينية لاشك فيها .",{h:"لذلك فالذى يدين غيره بغير حق ، إنما يأخذ حق الله واختصاصاته ، كما يمارس عملاً ليس فى حدود قدراته ."},"وهو بهذا يدين إنساناً قبل أن يدينه الله ، وقبل أن يأتى يوم الدينونة الرهيب ، فهو يحكم إذن قبل الوقت . كما أنه يدين عبداً لمولاه حق التصرف فيه . ومولاه هو الله .","يستثنى من هذا ، الذين منحهم الله حق الإدانة ، فقد قيل عن الحاكم مثلاً إنه « لا يحمل السيف عبثاً ، إذ هو خادم الله منتقم من الذى يفعل الشر » (رو ١٣ :"],51:["٤) . وكذلك من اقيموا من الله للرعاية مثل الوالدين والآباء الروحيين ، وكل من هو فى مسئولية ..",{h:"كذلك فإن الذى يقع فى خطية الإدانة ، إنما يكسر وصية الله الذى قال « لا تدينوا لكى لا تدانوا » (متى ٧ : ١) . فهو إذن يخالف الله ، ويكون بهذا قد أخطأ إليه ، بالعصيان . وبالاضافة إلى هذا فإن خطية الإدانة :"},{h:"٢ ـ إساءة إلى الذى يدين"},{h:"والذى يدين غيره ، ترتفع عنه النعمة والمعونة ، فيسقط ."},"وذلك لكى تسحق نفسه فى هذا السقوط ، فلا يعود ويدين غيره . ولكى يشعر أنه معرض أن يسقط فيما سقط فيه أخوه ، لولا أن النعمة تسنده . فبقاؤه قائماً فى الوقت الذى سقط فيه غيره ، ليس دليلاً على قوّته الذاتية ، إنما هو راجع إلى عمل النعمة . فلا يتكبر ويدين أخاه ، لكيلا ترتفع عنه النعمة فيسقط .","فإنه بهذه الإدانة يوقع نفسه فى الحكم ، إذ أن الرب قد قال « لا تدينوا لكى لا تدانوا . لأنه بالدينونة التى بها تدينون تدانون . وبالكيل الذى به تكيلون يكال لكم » (متى ٧ : ١ ، ٢) .",{h:"إذن فالذى يدين غيره ، يعرض نفسه للدينونة ."},"وبنفس الكيل ، ليس أقل . بل ورد فى الإنجيل لعلمنا مرقس الرسول « يكال لكم ويزاد » (مر ٤ : ٢٤) . فالذى يقسو مثلاً فى إدانته لغيره ، إنما يعرض نفسه لنفس القسوة وأزيد . وقد يتعرض لهذا الحكم هنا على الأرض كما هناك فى السماء . مثال ذلك العبد الذى عامل بالقسوة رفيقه المدين له ، إذ قيل عنه فى الإنجيل « فدعاه حينئذ سيده وقال له : أيها العبد الشرير ، كل ذلك الدين تركته لك لأنك طلبت منى . أفما كان ينبغى أنك أيضاً ترحم العبد رفيقك كما رحمتك أنا . وغضب سيده وسلمه للمعذبين » (متى ١٨ : ٣٢ ـ ٣٤) .","قال أخ لشيخ « لماذا يا أبى شيطان الزنى يحاربنى بقسوة حتى أننى أسقط » . فأجابه الشيخ « ذلك لأنك تدين أخاك ، فتفارقك النعمة ، فتشعر بقسوة الحرب"],52:["وتسقط » . ولعل الإنسان لأول وهلة يعجب قائلاً « وما علاقة الإدانة بالزنى ؟ » حقاً لا توجد علاقة مباشرة . ولكن هى هذه النتيجة : مفارقة النعمة لمن يدين غيره ...",{h:"إذن لا تدن غيرك ، ليس لمجرد الشفقة عليه ، وإنما أيضاً إشفاقاً على نفسك ."},"إشفاقاً على نفسك من نتائج الإدانة بالنسبة إليك أنت . سواء تعرضك لتخلى النعمة هنا ، أو تعرضك للدينونة هناك ، أو مقاساتك من مرارة الخطية التى دنت أخاك عليها . كما حدث فى قصة ذلك الشيخ الذى قسا فى حكمة على شاب سقط فى الخطية ، فشككه حتى أخذ طريقه إلى العالم . وحينئذ سمح الله أن تقع نفس الحرب على هذا الشيخ ليقاسى فى شيخوخته ما لم يجربه فى شبابه .",{h:"كذلك الذى يدين غيره ، قد يعامله الناس بالمثل ."},"كما قيل فى المثل « من غربل الناس نخلوه » . فكثيراً ما يحدث للذى يعيب غيره ، أن يُرد عليه بالمثل . وكما كشف ضعفات غيره ، يكشف هذا الغير ضعفاته مدافعاً بأن الكل تحت الضعف : الذى يدين كالذى يدان منه .",{h:"إذن أنت إن دِنت غيرك ، تتعرض لكشف ضعفاتك ."},"إما أن يكشفها من تسىء إليه ، أو يكشفها أصدقاؤه واحباؤه وكل الدافعين عنه . أو تنكشف ضعفاتك بأى سبب ، بسماح من الله ، حتى لا تعود تجلس فى منصة القضاء تدين غيرك ، كأنك بلا عيب . انظر ماذا قال الرب للذين دانوا المرأة الخاطئة المضبوطة فى ذات الفعل .. قال لهم .",{h:"« من كان منكم بلا خطية ، فليرمها أولاً بحجر » (يو ٨ : ٧) ."},"وورد فى معاملة الرب لأولئك القساة الديانين أنه « انحنى إلى أسفل ، وكان يكتب على الأرض » وقيل فى التفسير إنه كان يكتب لكل واحد منهم خطيته ، لذلك ورد بعدها « وأما هم فلما سمعوا ، وكانت ضمائرهم تبكتهم ، خرجوا واحداً فواحداً مبتدئين من الشيوخ إلى الآخرين » (يو ٨ : ٨ ، ٩) . لذلك لما سمعوا عبارة « من كان منكم بلا خطية فليقذفها أولاً بحجر » . وكأن الرب يقول لهم :"],53:[{h:"بدلاً من أن تنظروا إلى خطية المرأة ، انظروا إلى خطاياكم ."},"مع أن المرأة كانت خاطئة فعلاً ، وهم لم يظلموها ولم يدّعوا عليها إدعاءات باطلة لأنها « أمسكت فى الخطية » أُمسكت وهى تزنى فى ذات الفعل . ولكن السيد المسيح أراد لهؤلاء أن ينظروا إلى خطاياهم ، وليس إلى خطية غيرهم .",{h:"الله هو وحده الديان ، أيضاً لأنه هو وحده القدوس (رؤ ١٥ : ٤) ."},"أما باقى البشر ، فينطبق عليهم المثل القائل « من كان بيته من زجاج ، فلا يقذف الناس بالحجارة » . ليتك تذكر نفسك بهذا المثل ، حتى لا يتهشم بيتك ...",{h:"ارحم إذن مادمت محتاجاً إلى الرحمة ."},{h:"واستر على غيرك ، مادمت محتاجاً إلى الستر ."},"وبالكيل الذى تريد أن يكال به لك ، يمكنك أن تكيل لغيرك . أتريد ستراً ، إذن استر . أتريد أن خطاياك تظل مخفاة لا يعرف بها أحد ، إذن اعمل المثل ، واترك خطايا غيرك مستورة لا يعلم بها أحد ...",{h:"٣ ـ خطية ضد المُساء إليه"},"إنها إساءة لسمعته التى تلوكها الألسن وتصبح مضغة فى الأفواه . وهى حط لكرامته ، بينما يقول الكتاب « مقدمين بعضكم بعضاً فى الكرامة » (رو ١٢ : ١٠) .",{h:"وفيها الحديث عن أخطائه ، دون إعطائه فرصة للدفاع عن نفسه ."},"أو لتوضيح موقفه ، أو لشرح الأسباب التى دعته إلى التصرف هكذا ... وربما يكون كل ما يقال عنه شائعات لا صحة لها ...",{h:"وبفرض أنه أخطأ ، لماذا لا تستر عليه ؟"},"وقد قيل عن القديس مقاريوس الكبير أنه صار كملاك على الأرض ، لأنه كان يستر خطايا الآخرين ، ولا يذيع أخطاءهم فتفضح أمام الناس . فإن كنت أنت لم"],54:["تستطع أن تستر على غيرك وتخفى فضائحه . فعلى الأقل لا تكن سبباً لنشرها بالأكثر فى محيط أوسع ، بالحديث عنها والحوار فيها ...",{h:"كذلك بنشرك لخطايا الغير ، إنما تعرقل طريق توبته ..."},"فالإنسان الذى لم ينفضح أمره ، يمكنه أن يتوب إذا أراد ، بعكس الذى تلاحقه سمعته وأخطاؤه حيثما تذهب ... قد يجد صعوبة فى أن يغير مسلكه ! وفى أن يصير إنساناً جديداً .",{h:"وربما الحديث عن خطايا غيره يفقده ثقة الناس فيه ..."},"وهكذا لا يستطيع أن يستعيد مكانته فى المجتمع ، ولا أن يكوّن علاقات طيبة مع الشرفاء والخيرين ، ويصبح التعامل معه موضع شك بسبب ما قيل عنه ...","وعلى رأى القديس يوحنا ذهبى الفم :",{h:"« إن كنت لا تستطيع أن تسد فم من يتكلم على أخيه بالسوء ، فعلى الأقل لا تتكلم أنت ."},"وأنت فى خطية الإدانة لا تسىء فقط إلى الله وإلى نفسك وإلى المُساء إليه ، وإنما أنت أيضاً تتسبب فى :",{h:"٤ ـ الإساءة إلى السامعين"},"ما ذنب السامع إن كنت تسبب له عثرة ؟","وأنت تعرف ما قاله الرب عن صانعى العثرات : « ويل لمن تأتى بواسطته العثرات . خير له لو طوق عنقه بحجر رحى وطرح فى البحر ، من أن يعثر أحد هؤلاء الصغار » (لو ١٧ : ١ ، ٢) .",{h:"ماذنب السامع فى أن تفقده بساطته وتسبب له أفكاراً ؟!"},"وهكذا تغير صورة الآخرين فى ذهنه . وقد تثبت عنده هذه الفكرة التى غرستها فيه من جهة الغير ، وقد تؤثر على علاقته به ومعاملته له ، دون أن يدرى ذاك سبباً"],55:["لكل هذا !! لماذا هذا الإتلاف ؟!","ولهذا قال الآباء : إن الذى يتكلم بالسوء على غيره ، يهلك أنفس سامعيه ، ونفسه أيضاً لا تفلت ...","وربما ـ دون أن تدرى ـ تحمل إدانتك لغيرك إساءة أخرى .",{h:"٥ ـ إساءة إلى آخرين لا تعرفهم"},"فكلام الإدانة الذى قلته ، ربما لا يصل إلى سامعيك فقط ، وإنما قد تتناقله الألسن فينتشر وسط كثيرين لا تعرفهم ، وهؤلاء أيضاً بالمثل : تسبب لهم عثرة ، وتفقدهم بساطتهم ، وتتغير علاقاتهم مع المُساء إليه ... وتتسع الدائرة ...",{h:"إن كلمة الإدانة التى تقولها ليست عاقراً ، فقد تلد بنين وبنات ، وقد ينتشر نسلها فى أماكن متعددة ، وقد يأتى بنسل آخر من استنتاجات وأقاويل وإضافات وفهم خاطىء ."},{h:"وقد لا تلد كلاماً فقط ، وإنما أيضاً مشاعر وخلافات ."},"وأنت فى كل ذلك ، تحاول أن تحصر نطاق خطيتك فلا تستطيع ، وتحاول أن تحصى عدد الذين أعثرتهم فلا تقدر ... إنهم إسماء تعرفها ، واسماء لا تعرفها ...",{h:"وإدانتك لغيرك قد تلد عند البعض إدانة لك ."},"لماذا يتكلم عن غيره بهذا الأسلوب ؟ ولماذا يمسك سيرة غيره ؟ ولماذا ينتقد هذا الإنسان أو ذاك ؟ وما الدافع وراء كل هذا ؟ وهل كلامه حق أم مخترع ؟ وهل يتكلم عنا نحن أيضاً بنفس الأسلوب ؟ وهل يمكن أن نسلم من لسانه أم سوف يأتى دورنا ؟ وهكذا تتحول من مسىء إلى غيرك إلى مُساء إليه .",{h:"فالذين يسمعونك أو يصل إليهم كلامك : بعضهم سيصدّق ما يسمعه ، والبعض لا يصدق ."},"فالذين يصدقونك سوف تسوء سمعة ذلك الشخص فى نظرهم . والذين لا يصدقونك ستسوء فى نظرهم سمعتك أنت . وفى كلا الحالين خسارة لك ولهم ..."],56:[{h:"الإدانة خطية مركبة"},"ليست الإدانة فى جميع حالاتها حكماً بريئاً عادلاً ، من شخص له سلطان أن يدين ... وإنما قد تكون خطية حينما تصبح مجرد مسك سيرة ، وإساءة إلى السمعة . وقد ترتبط بخطايا أخرى . وربما تكون لها خلفيات وأسباب .",{h:"وقد تكون أسباب الإدانة خطايا أبشع من الإدانة ذاتها ."},"فإدانة الآخرين لا تنشأ من فراغ ، ولابد من دوافع ، أو عوامل مساعدة ، علينا أن نعرفها ونتتبعها ونعالجها ... باحثين عن الخطايا المرتبطة بالإدانة . وقد لا تكون كلها مرتبطة بكل خطية إدانة ، وإنما بعض منها مرتبط بمناسبة أو بشخص ، والبعض بمناسبة أخرى وبشخص آخر . فما هى هذه الخطايا ؟ إنها :",{h:"١ ـ عدم المحبة"},"يقول الكتاب « المحبة تستر كثرة من الخطايا » (١بط ٤ : ٨) .","ولعل القديس بطرس أقتبس هذه الآية من سفر الأمثال ، إذ ورد فيه « البغضة تهيج خصومات . والمحبة تستر كل الذنوب » (أم ١٠ : ١٢) . وكما يقول المثل السائر « حبيبك يبلع لك الظلط ، وعدوك يتمنى لك الغلط » .",{h:"إن كنت تحب إنساناً ، فسوف لا تدينه ، بل ستدافع عنه ."},"وكما قيل فى المزمور عن الرجل البار إنه « لا يقبل عاراً على جيرانه » (مز ١٥ : ٣) . فكم بالأولى يصنع مع أحبائه واصدقائه وأقاربه ...","الإنسان عادة يدين واحداً من اثنين :"],57:["فإما أنه يدين شخصاً لا يعرفه ، أو شخصاً عادياً لا ترتبطه به محبة ولا كراهية ، ولا تهمه سمعته فى شىء إن ساءت أو ارتفعت فى نظر الناس ... وطبعاً هذا الإتجاه هو ضد مبدأ المحبة من نحو الكل . إذ ينبغى أن تكون سمعة الناس ـ أياً كانوا ـ عزيزة فى أعيننا ، فهم بشر وأخوة ، حتى إن كنا لا نعرفهم ، ولا نقابلهم بلا مبالاة ...",{h:"وإما أن تكون الإدانة مصحوبة بخطية حقد وكراهية نحو شخص يبغضه القلب ، كما كان النوع السابق مصحوباً بخطية اللامبالاة ..."},"والحقد أو الغيظ أو البغضة من الخطايا الصعبة التى ينبغى أن ينقى الإنسان قلبه منها . يقول القديس يوحنا الحبيب « كل من يبغض أخاه ، فهو قاتل نفس » (١يو ٣ : ١٥) . ويقول أيضاً « وأما من يبغض أخاه ، فهو فى الظلمة ، وفى الظلمة يسلك ، ولا يعلم أين يمضى ، لأن الظلمة أعمت عينيه » (١يو ٢ : ١١) .",{h:"البغضة قد تكون أم الإدانة ، وهى أكثر شراً من إبنتها ."},"إنها تلد الإدانة ، وتغذيها من شرها ، وتصحبها طوال الطريق . وبها تصبح خطية الإدانة مركبة [ بغضة + إدانة ] ، أو لامبالاة بمشاعر الآخرين وسمعتهم تلد عنها خطية إدانة . أما المحبة فهى بعيدة عن كل هذا .",{h:"فكم بالأولى إذا وصلت البغضة إلى حد الغيظ والحقد ؟!"},"وهنا تكون التركيبة قد ازدادت تعقيداً . فالبغضة ولدت غيظاً وحقداً . وهذان انجبا الإدانة . وبقيت البغضة تغذى الثلاثة !","والإدانة التى سببها البغضة ، إنما تخرج من قلب مسموم معكر . وحتى لهجة الصوت فيها ، أو ألفاظ التعبير ، تحمل فى طياتها ما فى القلب من حقد .","وهذا يذكرنا بخطية أخرى قد تصحب الإدانة وهى :"],58:[{h:"٢ ـ القسوة"},"هناك إدانات لا تصحبها قسوة ، مثل الإدانة التى هى مجرد ثرثرة أحاديث حول مسك سيرة الناس . وهذه قد تكون بأسلوب عادى ، وربما معه بعض التهكم والتفكه لتسلية الجلسة (!!) كما يظن هؤلاء ...",{h:"ولكن هناك إدانات معها قسوة فى الحكم أو فى الألفاظ ."},"مثل قسوة الكتبة والفريسيين الذى أتوا بالمرأة الخاطئة ، بعد فضحها أمام الناس . ولم يكتفوا بما سببوه لها من عار ، وإنما أرادوا أن ينفذوا فيها حكم الرجم حسب الشريعة (يو ٨ : ٥) .",{h:"ومثالها قسوة الذين أدانوا السيد المسيح بحكم الموت ."},"واصروا على ذلك صائحين « اصلبه اصلبه » « دمه علينا وعلى أولادنا » (متى ٢٧ : ٢٣ ، ٢٥) (مر ١٥ : ١٣ ، ١٤) ، إلى جوار ما صحب هذه الإدانة من جلد ولطم وبصاق وأنواع استهزاء أخرى صادرة من قلوب قاسية .",{h:"وقد تكون القسوة فى استخدام ألفاظ جارحة ."},"أو وصف الشخص المدان بأوصاف رديئة جداً ، وتهم تمس شرفه أو شخصيته أو عقليته . ولعل من الإدانة الجارحة كلمة « يا أحمق » الذى قال الرب إن عقوبتها نار جهنم (متى ٥ : ٢٢) . وما أكثر الكلمات والعبارات التى يستخدمها الناس بنفس معنى كلمة (أحمق) ...",{h:"وقد تكون القسوة فى أسلوب الشدة والعنف الذى يستخدمه أحدهم فى الإدانة :"},"حيث يدين غيره بغضب شديد وعصبية ظاهرة ، وربما فى ثورة وهو ساخط كل السخط على تصرفات هذا الأخ التى يصفها بأعنف الكلمات ، مما يدل على قسوة شديدة داخل القلب ."],59:[{h:"وقد تبدو القسوة فى عدم التماس أى عذر للذى يدينه ."},"وكذلك فى عدم تقدير ظروفه النفسية أو الصحية أو الاجتماعية ، وما أحاط بتصرفه من ملابسات وأسباب . بل يصدر الحكم فى أسلوب قاطع وهو يقول « مهما كانت الأسباب » ...",{h:"وقد تظهر القسوة فى عقوبة شديدة يصدرها على من يدينه"},"وينفذها إن كان صاحب سلطان . أو يقترحها إن كان لا دخل له بالموضوع . ويقول فى عنف : هذا الشخص يستحق كذا وكذا من الاحكام ... ولو كنت أنا المسئول لفعلت به كذا وكذا .. !","وغير البغضة والقسوة قد ترتبط الإدانة بخطية أخرى هى :",{h:"٣ ـ الظلم"},"ليست كل إدانة عادلة . فهناك إدانات فيها ظلم :",{h:"كأن يدين الشخص غيره لمجرد السماع ، أو عن طريق الشائعات ."},"وقد يكون ما سمعه غير صحيح . وقد تكون الشائعات مغرضة ، أو خارجة من مصدر حاقد يريد التشهير . وربما يكون كل ما قيل عن هذا الإنسان مجرد اختراعات ، ولكنها انتشرت نتيجة تداول الكلام . وليس كل ما ينتشر يكون صحيحاً . ولا يصح الحكم على أساسه .",{h:"وربما يكون الظلم ناتجاً عن عدم التأكد وعدم التحقيق ."},"والمفروض أن المتهم برىء إلى أن تثبت الجريمة عليه . والمفروض فى كل ما نسمعه عن أحد ، أننا لا نصدقه بسرعة وبدون فحص ، وبدون اعطائه فرصة ليجيب عن نفسه .","وقد ادين يوسف الصديق عن جريمة هو برىء منها كل البراءة ، واتهمته زوجة سيده ظلماً . ومع ذلك ألقى فى السجن وقد حمى عليه غضب سيده دون أن يتحقق"],60:["من صحة التهمة . وربما امتلأت المنطقة بكلام سوء عن يوسف نتيجة لما قالته الزوجة الشريرة . ولعله خلال السنوات التى قضاها فى السجن كانت تلاحقه الإدانة الظالمة والسمعة الردية .",{h:"وقد يكون الظلم عن جهل كما فعل فوطيفار بيوسف . وقد يكون بمعرفة وبنية سيئة كما فعلت زوجة فوطيفار بهذا البرىء ."},"وسواء كان الظلم عن جهل أو عن قصد سىء ، فهو ظلم يلصق الإدانة بإنسان برىء . والظلم المقصود يقودنا إلى خطية أخرى قد ترتبط بخطية الإدانة وهى :",{h:"٤ ـ الكذب"},{h:"وهذا الكذب قد يكون كاملاً ، أو عن طريق المبالغة ."},"والكذب الكامل هنا ، يقصد به أن شخصاً يخترع كلاماً ضد آخر للإساءة إلى سمعته ، وهو يعرف تماماً أن ما يقوله عنه هو محض افتراء . وطبعاً لا يفعل هذا إلا لو كان قد دفعه إلى الكذب شعور من الكراهية أو رغبة فى الإنتقام أو لون من الحسد . وهنا تكون خطية الإدانة مركبة من عديد من الخطايا .",{h:"وقد تصحب الإدانة بكذب جزئى هو نوع من تضخيم الواقع بأسلوب مسىء ."},"فقد يقع إنسان فى خطأ دينى عن عدم فهم ، فيقدمه آخر للسامعين على اعتبار أنه هرطقة أو فضيحة أو عار ، ويضخم من قيمة الخطأ كما لو كان كفراً ... ويفعل ذلك إما بسبب الرغبة فى الإساءة ، أو لأنه بطبيعته مبالغ فى كل ما يتكلم عنه من أمور ...",{h:"وربما يكون الكذب من اختراع المتكلم الذى يدين ، أو يكون نقلاً عن آخرين ..."},"وفى الحالتين كلتيهما ـ اختراع الكذب أو نقله ـ يكون الشخص المُساء إليه واقعاً تحت ظلم وهو برىء . والمفروض فى ناقل الكذب أن يتحرى جيداً فى تقبل"],61:["الخبر ، وفى توصيله لآخرين ، وقد لا يكون من حقه هذا التوصيل ...","ننتقل إلى خطية أخرى ترتبط بالإدانة وهى :",{h:"٥ ـ عدم الاتضاع"},{h:"دائماً الذى يدين غيره ، يكون ناسياً خطاياه الخاصة ."},"ولو افتكر خطاياه ، ما كان يفكر فى خطايا أخيه ، أو يتحدث عنها أو يعايره بها ! ولذلك فإن الكتبة والفريسيين لما كانوا ناسين خطاياهم أثناء إدانتهم للمرأة المضبوطة فى ذات الفعل ، ذكرهم الرب بهذه الخطايا ، فلما بكتتهم ضمائرهم عليها ، تركوا إدانة الخاطئة وانصرفوا (يو ٨ : ٩ ـ ١١) .",{h:"فى عدم الاتضاع ، يظن الإنسان نفسه أفضل من غيره ، فيدين هذا الغير ."},"ولذلك فإن الفريسى المتكبر أدان العشار فى الهيكل ، لما رأى فى نفسه أنه ليس من الناس الظالمين الخاطفين الزناة ، ولا مثل هذا العشار ، ولما تذكر بره وصومه وعشوره (لو ١٨ : ١١ ، ١٢) . أما العشار فكان منشغلاً بإدانة نفسه أمام الله ، فلم يدن غيره .",{h:"تزيد الإدانة بواسطة الكبرياء ، إذا ما قارن الإنسان نفسه بمن هو أقل منه ."},"لذلك فإنه يدين هذا الذى هو أقل ، كما أدان الفريسى العشار . أما المتواضع الذى يرى أنه أقل من الكل ، فلا يدين غيره . كذلك بالكبرياء يظن أنه لا يمكن أن يسقط فيما سقط فيه هذا المدان . أما المتواضع فلا يعتبر أنه أقوى من أية خطية ، بل يتذكر أن الخطية « طرحت كثيرين جرحى ، وكل قتلاها أقوياء » (أم ٧ : ٢٦) لذل فهو لا يدين غيره .",{h:"بل بالكبرياء يمكن أن الإنسان يدين من هو أكبر منه :"}],62:["كما حدث أن مريم وهارون وقعا فى إدانة أخيهما موسى النبى العظيم حينما تزوج إمرأة كوشية . فكانت النتيجة ولذلك وبخهما الله ، وشرح لهما كيف أنهما أقل من موسى بكثير ، حتى يعودا إلى اتضاعهما ، ويعرفا قدر هذا العظيم الذى يدينانه . وضرب الله مريم بالبرص ، فأخرجوها خارج المحلة سبعة أيام كنجسة ، حتى تتعلم الاتضاع فلا تدين من هو أكبر منها (عد ١٢ : ١٥) .","وكان سبب وقوع مريم وهرون فى الإدانة هو عدم الاتضاع ، إذ قالا « هل كلّم الرب موسى وحده ؟ ألم يكلمنا نحن أيضاً » (عد ١٢ : ٢) . فكلمهما الرب بتوبيخ ليعرفا قدرهما تماماً ...","فى إدانة الآخرين خطية أخرى وهى :",{h:"٦ ـ اعثار الآخرين"},"ونقصد هنا طبعاً الإدانة باللسان ، لأن الإدانة بالفكر أو القلب لا تعثر أحداً .",{h:"أما الإدانة باللسان ، فتعثر السامع ، وتوقعه مع المتكلم فى نفس الخطية ."},"ويكون المتكلم الذى أدان غيره قد تسبب فى سقطة أخيه ، ويحاسبه الله على هذه العثرة . وبقدر ما يزداد عدد الذين تعرضوا للعثرة ، تكبر خطية الإدانة جداً ...","خطية أخرى ترتبط بخطية الإدانة وهى :",{h:"٧ ـ الإهانة والتحقير"},{h:"الإدانة هى بلا شك إقلال من شأن الشخص المدان ."},"لأنها تحكى عيوبه أو نقائصه ، خطاياه أو أخطاءه . وهى على درجات فى شدتها . وقد تصل أحياناً إلى الإهانة والشتيمة ، أو إلى التعيير والتحقير . وقد ينظر فيها الذين يدينون نظرة استصغار أو احتقار إلى من يدينه ، مشعراً إياه بضآلة قدره ، أو مبكتاً إياه بإزدراء ، أو جاعلاً الآخرين يستصغرونه أو يفقدون احترامهم له .",{h:"وقد يجرحه بكشف أسراره وخصوصياته أمام الناس ."}],63:["ويحكى ما يعرفه عنه من أمور مشينة . وقد يزداد الأمر خطورة بأن يشعر السامعين أن هذا الشخص لا فائدة فيه ، ولا اصلاح له ، كأن قد حكم عليه بالضياع !","وهذه النقطة ترتبط بها نقطة أخرى وهى :",{h:"٨ ـ عدم اللياقة"},{h:"إذا قد يتحدث بعيوب الشخص أمام أعدائه فيشمتون به ."},"أو يزداد هجومهم عليه ، إذ قد قدمت لهم مادة جديدة يحاربونه بها ، وما أكثر ما يسببه له هذا الأمر متاعب واشكالات .","أو قد يدينه أمام مرءوسيه ، أو ابنائه ، أو أمام من هم أصغر منه ، فتضيع هيبته أمامهم ، ويفقد مركزه .","وكل هذه وأمثالها أمور غير لائقة ، تضاف إلى خطية الإدانة ، فتجعل حجمها أكبر ومسئوليتها أزيد .","وقد تختلط فى كل ذلك بعدم الحكمة ، أو عدم التقدير ، أو عدم مراعاة شعور الآخرين . نقطة أخرى تحدث أحياناً وهى :",{h:"٩ ـ الحكم على النيات"},"قد يصل الأمر بإنسان إلى أنه يدين نيات غيره ومقاصده ، فيقول : هذا الإنسان نيته سيئة ، وهو يقصد كذا وكذا من الشرور .. !",{h:"بينما معرفة النيات والمقاصد هى من شأن الله وحده ."},"ولكن الإمتداد فى الإدانة جعله يدين النيات . وربما يقول إنه يفعل ذلك عن طريق الخبرة ، أو عن طريق الاستنتاج . ولكن لاشك أنه لا شىء من كل هذا"],64:["مؤكد وما أسهل أن تكون كل استنتاجاته خاطئة ، وفيها ظلم ، وادعاء بمعرفة هو فيها « يرتئى فوق ما ينبغى » (رو ١٢ : ٣) .",{h:"الحكم على النيات ، حتى لو صح ، هو خطأ روحى ."},"فكم يكون إذن من يدين مشاعر القلب ، ومن يدين أفكار الناس ، وهو لا يمكن أن يعرف المشاعر والأفكار ، إلا عن طريق الظنون : وليست الظنون صادقة باستمرار ...",{h:"بل يوجد من يدين حياة إنسان بالجملة ، وطبيعته وخلقه ... وربما يدين مصيره أيضاً ..."},"قال أحد الشيوخ (فى بستان الرهبان) :","إن كان لا يعرف ما فى الإنسان إلا روح الإنسان الذى فيه (١كو ٢ : ١١) ، وإذا كنا نعرف أن كثيرين قد تابوا ، دون أن نعلم نحن بتوبتهم ، وإذ قد يتفق أن يتوب إنسان فى آخر حياته ، ويقبل الله كاللص ، فسبيلنا إذن أن لا ندين أحداً ... فالديان هو الله وحده ، فكيف يجرؤ أحد أن يتدخل فيما هو خاص بالله ؟!","آخر خطية اتحدث عنها كخطية مرتبطة بالإدانة هى :",{h:"١٠ ـ الرياء"},"الشخص الذى يدين غيره على خطأ ، وهو يرتكب نفس الخطأ أو ما هو أسوأ ، يصفه السيد المسيح بالرياء .","فيقول له « لماذا تنظر القذى الذى فى عين أخيك ، وأما الخشبة التى فى عينك فلا تفطن لها ؟! ... يا مرائى ، أخرج أولاً الخشبة من عينك ، وحينئذ تبصر جيداً أن تخرج القذى الذى فى عين أخيك (متى ٧ : ٣ ـ ٥) .",{h:"إذن من الرياء أن ندين الناس على أشياء نحن نقع فيها خفية ."},"أو نحن نقع فى أمور أخرى ، ربما تكون أكثر خطأ منها ."],65:[{h:"الفصل الرابع"},{h:"أقوال الآباء فى الإدانة"}],66:[{h:"قال القديس دوروثيئوس :"},{h:"« الحكم على خليقة الله ، يليق بالله ذاته لا بنا »"},"« لأنه هو وحده العارف بسّر كل إنسان وعلانيته . وله وحده إصدار الحكم فى كل أمر ، وعلى كل شخص » .","« الله وحده له الحق فى أن يبرر أو يدين ، لأنه يعرف طبع كل إنسان وقوته » .","وهو أيضاً يعرف ميوله ومواهبه وتركيبه البدنى ومقدراته .","لذلك فإن الله عندما يدين ، يدين بالعدل .","ولهذا قال الرسول لمن يتطاول على عمل الله هذا : « من أنت أيها الإنسان ، يا من تدين عبد غيرك ؟ عبد هو لسيده ، يثبت أو يسقط . ولكنه سيثبت لأن الله قادر أن يقيمه » (رو ١٤ : ٤) .","* * *",{h:"وقال القديس دوروثيئوس أيضاً :"},{h:"« إن سم الإدانة أحياناً يخرج من إنسان ، لكى يصب فى آخرين » ."},"نلاحظ أنه وصف الإدانة بسمّ ، أى إنها تميت من تصل إليه . وكأنه بهذا يشبه الذى يدين غيره بحية تنفث سمها ...","* * *",{h:"قال القديس مارأوغريس :"},"« لا تميز الذين سقطوا (من الذين لم يسقطوا) . ولا تترك فكر الكبرياء يقنعك بأن تكون ديّاناً » . وهنا القديس يربط بين الإدانة والكبرياء ."],67:[{h:"قال القديس الأنبا إشعياء :"},"« إذا أبصرت إنساناً قد أخطأ ، فلا تحتقره ، ولا تزدرِ به ، لئلا تقع فى أيدى أعدائك » .","حقاً ، ماذا تريد أنت من وراء هذه الإدانة ؟ هل تريد أن هذا الشخص يكرهه الناس ؟ أم تريد أن الله يهلكه ، ويجازيه بحسب أعماله الردية ؟ أمامنا قصة من البستان تلقى ضوءاً على هذا الأمر ...","* * *",{h:"قصة من البستان :"},"قيل إن راهباً كان مقصراً فى عبادته ومتهاوناً ... فلما جاءته ساعة الوفاة ، اجتمع الرهبان حوله ، لكى يروا كيف سيقابل الموت ... فوجدوه فرحاً !!","فقال له أحد الشيوخ « تشدد أيها الأخ باسم المسيح وقل لنا ما الذى يفرحك ؟ »","فأجابه ذلك الأخ : إننى رأيت أناساً مقبلين لأخذ نفسى ، ورأيت صك خطاياى . وقالوا لى « هذه خطاياك » . فقلت « خطاياى أنا أعرفها ولا انكرها . ولكننى منذ ترهبت ، وأنا لم أدن إنساناً . وأريد أن تنفذ فىّ الآية التى تقول « لا تدينوا لكى لا تدانوا » . فكيف أُدان ، وأنا لم أدن أحداً ؟ ! » . ولما قلت هذا تمزق صك خطاياى .","هذا الراهب لم يكن يعيش فى الخطية ، إنما كان مهملاً فى عبادته . ولكنه كان طيب القلب ، لا يغضب على أحد ، ولا يدين أحداً ، ولا يتكلم بالشر على إنسان . كان متضع القلب .",{h:"واستطاع باتضاعه وعدم إدانته لغيره ، أن يخلص ..."},"بالدقة فى تنفيذ هذه الوصية ، أمكن أن ينجو من الدينونة التى كان يمكن أن تحل به بسبب تهاونه ."],68:[{h:"وقال القديس ايرايس :"},{h:"إنه جيد أن يأكل الإنسان لحماً ، ويشرب خمراً »"},{h:"« ولا يأكل لحوم الأخوة ويشرب دماءهم بالوقيعة »"},"لقد شبه الإدانة بعملية افتراس للآخرين ، افتراس لسمعتهم وكرامتهم . وقال إنه خير للإنسان أن يكون مفطراً ولا يدين غيره ، من أن يصوم ويأكل لحوم الناس بإدانتهم . وأكل لحوم الناس ابشع من أكل اللحم العادى ...","* * *",{h:"وقال القديس الأنبا مسرا :"},"« إن التعقل (التعفف) الذى هو أفضل من إمساك البطن ... والذى يجب أن تجذب إليه نفسك ، ألا تأكل لحم إنسان ولا تشرب دمه بالوقيعة »","إنه نفس تعبير القديس إيرايس ...","ونفس التعبير يردده أيضاً مار اسحق اسقف نينوى","* * *",{h:"قال مار اسحق :"},"« إن الذى يصوّم نفسه عن الأكل والشرب ، بينما يأكل لحوم الناس بالوقيعة ، فصومه باطل » .","* * *",{h:"وقال القديس ايرايس أيضاً :"},"« كما أن الحية لما كلمت حواء ، أخرجتها من الجنة ... كذلك يشبهها ذلك الذى يقع بقريبه »",{h:"« ذلك لأنه يهلك أنفس سامعيه ، ونفسه كذلك لن تفلت ... كما تفلت الحية نفسها من اللعنة » ."},"أى أنه يضيّع نفسه ، ويضيّع غيره معه ."],69:[{h:"أما مار اسحق أسقف نينوى :"},"فيرى أن الذى يدين غيره ، هو شخص فى المستوى النفسانى ، وليس فى المستوى الروحانى ، لذلك يدين الكل ، لأن فى قلبه شجرة معرفة الخير والشر ، يفحص بها أعمال الناس هل هى خير من شر . وهكذا يقول مار اسحق :",{h:"« النفسانى هو قاض للأبرار والخطاة ، وديّان للأحياء والأموات . ومنصوبة فى قلبه شجرة معرفة الخير والشر ، التى مُنع رأس جنسنا آدم من أن يدنو منها أو يذوقها لئلا يموت » . هذا تغتذى معرفته منها فى كل وقت » ."},"إنه إنسان شغوف بحبة القضاه . وكل الذين يقابلهم يضعهم فى ميزان معرفة الخير والشر ، ليس الأحياء فقط بل الأموات أيضاً ...","* وبنفس الوضع يتكلم مارأوغريس ، فيقول :",{h:"« لا تتكلم بالشر على الذى مات ، لئلا تكون ديّاناً للأموات أيضاً » ..."},"لأن الذى يفعل هذا يأخذ مكانة السيد المسيح الذى قال عنه إنه يأتى « ليدين الأحياء والأموات » .","حقاً ، كم يحدث أن إدانتنا لا تقتصر على الأحياء فقط ، بل كثيراً ما ندين الأموات أيضاً ، الذين ربما يكونون قد تابوا قبل موتهم ومحا الله خطاياهم ، ولم يعد يذكرها حسب وعده القائل « لأنى اصفح عن إثمهم ، ولا أذكر خطيتهم بعد » (أر ٣١ : ٣٤) .",{h:"الله لا يذكر تلك الخطايا ، ونحن نذكرها !!"},"حقاً إن فى ذلك لعجباً ... ذاكرة الإنسان أحياناً تتعبه وتتعب غيره . وكذلك لسانة ، يتعبه ويتعب غيره ...","يضع الإنسان نفسه رقيباً على أعمال الكل ! بعين نقادة ، وفكر لا يهدأ ، ولسان يستطيع أن يجرح .","بينما القديسون منعوا الإدانة ، مهما كانت الأسباب ."],70:[{h:"قال القديس الأنبا أنطونيوس :"},"لا تعير أحداً مهما كانت الأسباب . ولا تفترِ على أخيك ، ولو رأيته عاجزاً عن إتمام جميع الفرائض .","* * *",{h:"وقال القديس الأنبا باخوميوس :"},"« لا تحتقر أحداً من الناس ، ولا تدنه ، ولو رأيته ساقطاً فى الخطية » .","* * *","ولعل تعليم الإنجيل يؤكد لنا هذه القاعدة ، وذلك فى :",{h:"قصة المرأة المضبوطة فى الفعل :"},"إن الذين ضبطوها وأتوا بها إلى الرب للحكم عليها بالرجم ، لم يدّعوا عليها ظلماً ، ولم ينسبوا إليها ما لم تفعله ، فقد كانت فعلاً ساقطة فى الخطية . ومع ذلك منعهم السيد من إدانتها ، وحول تفكيرهم إلى خطاياهم هم ، قائلاً « من كان منكم بلا خطية ، فليرمها أولاً بحجر » (يو ٨ : ٧) .",{h:"وأعطانا درساً أن لا ندين أحداً ، حتى لو رأيناه ساقطاً فى الخطية ."},"نحن أيضاً ساقطون فى خطايا كثيرة ... ولا يجوز لمريض أن يعيّر مريضاً آخر بمرضه ، وكلاهما تحت الألم . إنما الأفضل ستر الناس وليس كشف عيوبهم ، فنحن أيضاً لنا عيوب ...","* * *",{h:"قال القديس يوحنا ذهبى الفم :"},"« إن كنت لا تستطيع أن تستر أخاك ... وأن تأخذ خطيته وتنسبها إلى نفسك ، وأن تموت عنه ، فعلى الأقل ... لا تدنه » ... وقال ذهبى الفم أيضاً :",{h:"« إن كنت لا تستطيع أن تسكت فم الذى يتكلم بالشر على أخيك ، فعلى الأقل لا تفتح فمك أنت بالشر عليه » ."}],71:["أى أن الوضع الأمثل هو أن تمنع السمعة الردية من أن تصل من الآخرين إلى أخيك . فإن لم تستطع ، فعلى الأقل لا تشاركهم فى إدانته . وبالأحرى لا تبدأ أنت حديث الإدانة ...","* * *",{h:"قال القديس بولس السينائى :"},{h:"« تنهد على قريبك إذا أخطأ ، كما تتنهد على نفسك ، لأننا كلنا تحت الزلل » ."},"ذلك لأنك بهذا تعامله بترفق المحبة ، وليس بقسوة الحكم . إنه أخوك وقريبك مهما سقط . إن الآب السماوى قال فى رجوع إبنه الضال « إبنى هذا كان ميتاً فعاش ، وكان ضالاً فوُجد » (لو ١٥ : ٢٤) . وهكذا دعاه إبنه على الرغم من الموت ومن الضلال فكم بالأكثر تعامل أخاك ... على أننا نلاحظ ملاحظة هامة فى هذه القصة وهى :",{h:"الآب السماوى غفر لهذا الإبن ، وأخوه لم يغفر !!"},"بل رفض أن يدخل ، ورفض أن يشترك فى الفرحة بعودته ، وأدانه مع الآب قائلاً « إبنك هذا الذى أكل معيشتك مع الزوانى » (لو ١٥ : ٣٠) .","عجيب هو الرب فى محبته وعطفه ... هو الذى يغفر ، مع أن له كل الحق . ونحن الذين ندين ، ولا حق لنا !","* * *",{h:"قال القديس انسطاسيوس :"},"« لا تكن دياناً لأخيك ، لتؤهل أنت للغفران . لأن الرب يقول : لا تدينوا لكى لا تدانوا » .","نعم بكيل المغفرة والرحمة الذى نكيل به للآخرين ، يكال لنا فى يوم الدينونة","إن عدم الإدانة عامل مساعد على نوال المغفرة . لكن يشترط طبعاً الإيمان والتوبة ..."],72:[{h:"قال مار اسحق :"},"« احذر من أن تكون جالساً وتفكر فى أخيك بالشر ، فإن هذا يقلع جميع بنيان برج الفضيلة من قلبك ... حتى إن كنت قد وصلت إلى حد الكمال » ...","ويعلل مار اسحق هذا بقوله « ذلك لأن الهذيذ فى الأفكار الردية يقسى القلب » ...",{h:"ويقول أيضاً : غطّ على أخيك الخاطىء ، وقوّه من غير أن تشمئز منه ، لكيما تحملك رحمة سيد الكل » ."},"أى أن الرحمة التى نقابل بها الخطاة ، تؤهلنا لأن ننال رحمة من الله ، عملاً بقول الرب : « بالكيل الذى به تكيلون ، يكال لكم ويزاد » (مر ٤ : ٢٤) .",{h:"وقال مار اسحق أيضاً :"},"اسند الضعفاء وصغيرى القلوب والنفوس بكلمة ... فتسندك اليمين التى تحمل الكل ... كن شريكاً للموجوعين بقلوبهم ، بصلاتك الحزينة وبتتهد قلبك ... لكيما ينفتح لسؤالك ينبوع الرحمة » .","وقال أيضاً : « لا تمقت الخاطىء ، لأننا كلنا خطاة آثمون . وإن تحركت عليه من أجل الله ، فابكِ عليه ، وصلّ من أجل نفسه » .","وهكذا يضع الآباء الرحمة فى موضع الإدانة .","ويأمرون بالصلاة من أجل الخاطىء بدلاً من اساءة سمعته .","وليس هذا من أجله فقط ، بل أيضاً من أجل أنفسنا .",{h:"حتى لا ندان بسبب إدانتنا ، بل على العكس يعاملنا الله بالرحمة بسبب رحمتنا وفى هذه النقطة اتفقت أقوال القديسين :"},"* * *"],73:[{h:"قال القديس الأنبا أنطونيوس :"},{h:"« لا تدن غيرك لئلا تقع فى أيدى اعدائك » ."},"« وتفعل الخطايا القديمة التى تركتها » .","أن أن الله إذا رآك قاسى القلب فى أحكامك على الناس ، يسمح أحياناً أن تجرب بقسوة الحروب التى يعانونها من أعدائهم الشياطين . حتى إذا ما سقطت ، تعود وتشفق على غيرك ، ولا تدين ...",{h:"وقال أيضاً : إياك أن تعيب أحداً من الناس ، لئلا يبغض الله صلاتك » ."},"حقاً ، ما أصعب هاتين النتيجتين اللتين تنتجان عن إدانة الآخرين حسب تعليم أبينا القديس الأنبا أنطونيوس :","أ ـ أن تسلم لأيدى أعدائك ، وتفعل الخطايا القديمة .","ب ـ أن يبغض الله صلاتك .","ولماذا يبغضها ؟ لأنها ليست صادرة من قلب محب .","ونفس هذا التعليم نسمعه من القديس الأنبا إشعياء المتوحد :","* * *",{h:"وقال القديس دوروثيئوس :"},"من دان فى قلبه ، وتحدث بسيرته على لسانه ، تتخلى عنه المعونة الإلهية ، فيسقط فيما دان أخاه عليه » .","* * *",{h:"وقال القديس مقاريوس الكبير :"},"« احفظوا ألسنتكم ، وذلك بأن لا تقولوا على أخوتكم شراً ... لأن الذى يقول على أخيه شراً ، يغضب الله الساكن فيه » .","« وما يفعله كل واحد برفيقه ، فبالله يفعله » ."],74:[{h:"قصة من البستان :"},"فى إحدى المرات أتى الأب اسحق القس التبايسى إلى مجمع الشركة ، وأدان أحد الأخوة على فعل أتاه . فلما عاد إلى قلايته فى البرية ، أتاه ملاك الرب ووقف أمام باب القلاية ، وقال له : إن الله ارسلنى إليك لكى أسألك :",{h:"« أين تريد أن نلقى بنفس هذا الأخ ؟ »"},"وحينئذ أحس الأب اسحق بالخطأ الذى ارتكبه ... أنه لا يريد طبعاً أن تلقى نفس ذلك الأخ إلى الهلاك ! فتاب لوقته وقال للملاك « أخطأت ، فليغفر لى الرب بصلاتك » . فقال له الملاك « قد غفر الله لك ولكن عليك أن تحفظ نفسك ، ولا تدن إنساناً قبل أن يدينه الله » .","* * *",{h:"قال القديس الأنبا بيمن :"},"« قد تجد إنساناً يُظن به أنه صامت . لكن فكره يدين آخرين . فمن كانت هذه صفته ، فهو أبداً يتكلم » .","ويقصد القديس أن الإدانة ليست باللسان فقط ، إنما بالفكر أيضاً . وصمت اللسان وامتناعه عن كلام الإدانة ، لا يمنع أنه واقع فيها بالفكر .",{h:"ومع ذلك فالإدانة بالفكر أقل دينونة من الإدانة باللسان ."},"وذلك لأمرين : أولهما أنك بسقطة الفكر لا تعثر سامعين .","وثانيهما أنك لا تسىء إلى سمعه غيرك . فسقطة فكرك قاصرة عليك وحدك ، وليس لها نتائج خارجك ، إلا إذا تطورت ووصلت إلى اللسان .","* * *",{h:"وقال أحد الآباء :"},"إن رأيت شخصاً يخطىء اليوم ، فلا تتكلم باكر فى إدانته ، لأنك لا تعرف ، ربما رجع فى هذه الليلة ، وبكى على خطيته وتاب ، ومحاها له الله ..."],75:[{h:"وقال القديس مقاريوس الكبير :"},"لا تضعوا فى ذهنكم ، ولا تقبلوا فى فكركم أن إنساناً ما شرير . لأن بطرس الرسول يقول « قد أرانى الله أن لا أقول عن إنسان ما أنه دنس أو نجس » (أع ١٠ : ٢٨) .","* * *",{h:"قال القديس مارافرام :"},{h:"إن التلذذ بعيوب الآخرين ، يدل على أننا ممتلئون ببغضه ."},"وقال كذلك « من يشمت بسقطة أخيه ، يسقط هى أيضاً سقطة مثلها » . وقال « لا تترفع على أخيك فى ذهنك ، لأنك لا تعلم ماذا سيحدث فى اليوم المقبل . فمن الجائز أنه يتوب وتسقط أنت » .","وقال مارافرام أيضاً : إن الذى يسب رفيقه له صفتان : الوقيعة والبغضة » « ومثل هذا يعتبر فاقداً للتحنن وعادماً الرحمة » .",{h:"وقال : لا تكن دياناً لغيرك ، لأن كل واحد منا سيعطى اجابة عن أعماله . وأنت سوف لا تعطى أجابة عن أعمال غيرك » ."},"* * *",{h:"وقال القديس سمعان العمودى :"},"إن وجدت واحداً من أخوتك قد مال قليلاً ، فلا تقطع رجاءه . لأن الكتاب يقول « عزوا بعضكم بعضاً » (١تس ٤ : ١٨) . « المنتظر منك أن تقيم الإنسان الساقط ، لا أن تقضى عليه » .","وقال القديس سمعان العمودى أيضاً « إن كنت تدين أخاك ، فماذا تقول لك عن نفسك .","* * *",{h:"قال القديس الأنبا بيمن :"},"إذا دنا أنفسنا ، لا يبقى لنا وقت ندين فيه آخرين ."],76:[{h:"قال مار اسحق :"},"« لا تدن غيرك ، لئلا تُمتحن بما أُمتحنوا به »","أى لكى لا تقع فى نفس الحرب الروحية الصعبة التى تعرضوا لها . وهكذا توقع نفسك فى التجارب .","وقال أيضاً « اذكر أنك من الطبيعة الأرض ، مشترك معهم فى جسد آدم ، وفى نير هذه الطبيعة » .",{h:"وقال مار اسحق أيضاً :"},"« الإنسان البعيد عن ذكر الله ، هو المهتم بقول السوء على أخيه » .","أى أن الإنسان إذا كان منشغلاً بالصلاة والتأمل ، وقراءة الكتاب ، والمداومة على ذكر الله فى قلبه ، لا يبقى لديه وقت يتفرغ فيه لذكر أخطاء الناس . أما الإنسان المقصر فى عبادته ، فإن الفراغ يساعده على كلام الإدانة .","* * *",{h:"قال القديس يوحنا القصير :"},{h:"كن حزيناً على الذين هلكوا . وكن رحيماً على الذين سقطوا ."},"لعله يشبه هذا بما قاله القديس بولس الرسول فى رسالته إلى العبرانيين « اذكروا المقيدين ، كأنكم مقيدون معهم . واذكروا المذلين ، كأنكم أنتم أيضاً فى الجسد » (عب ١٣ : ٣) .",{h:"نعم ، ليس المفروض أن ندين الساقطين ، بل أن نقيمهم ."},"وفى ذلك يقول الكتاب « شددوا الأيادى المسترخية ، والركب المرتعشة ثبتوها » (أش ٣٥ : ٣) . وأيضاً يقول الرسول « شجعوا صغار النفوس . اسندوا الضعفاء . تأنوا على الجميع » (١تس ٥ : ١٤) .",{h:"قال « اسندوا الضعفاء » ولم يقل أن تدينوهم أو تحقروهم أو تشهروا بهم أمام الآخرين ."}],77:[{h:"وقال مار اسحق :"},"« الذى ينظر الخشبة التى فى عينه ، لا يتفرغ لأن ينظر القذى الذى فى عين أخيه » . وقال أيضاً :",{h:"« الذى يعتنى بأن يقوم فى ذاته المناقص التى تظهر له فى الآخرين الذين هو سالك بينهم ، هذا قد وجد مرآة روحية داخل نفسه » ."},"أى أننا عندما نرى خطأ ما يرتكبه البعض ، نفحص أنفسنا جيداً ، ربما نرى هذا الخطأ فينا ، فنعالج فى أنفسنا ما نرى غيرنا يدانون عليه .","وهذا المعنى نفسه ردده القديس مارأوغريس .","* * *",{h:"قال القديس مارأوغريس :"},"« الذى يفحص نقائص الآخرين ، هو لم يفحص بعد أعماله الخاصة بحرص . لأنه لو فحص نفسه جيداً ، لوجد أن العيب الموجود عند الناس ، هو موجود عنده أيضاً » .","وهذا المعنى ليس فقط لمار اسحق ومارأوغريس ، وإنما :","* * *",{h:"قال الأنبا ميلوس :"},"« إذا نظرنا فى أمور أنفسنا ، ندين آخرين . لأن أموراً كثيرة هى فينا ، ونحن نلوم بها غيرنا » .","* * *",{h:"وقال أحد الآباء :"},"إن الله هو الديان . وقد أعطى الدينونة كلها للإبن (يو ٥ : ٢٢) . ومع ذلك قد أجّل تلك الدينونة إلى اليوم الأخير الذى يأتى فيه فى مجده ليدين الأحياء والأموات . فلماذا تتعجل الأمر ، وتبدأ أنت فى الدينونة من الآن ."],78:[{h:"وقال القديس مقاريوس الكبير :"},"« احفظوا ذواتكم من كلام النميمة والوقيعة ، لكى تكون قلوبكم طاهرة . لأن الأذن التى تسمع النميمة ، لا تستطيع أن تحفظ طهارة القلب بدون دنس » .","أى اجعل أذنك نظيفة ، لكى يصير قلبك نظيفاً ، لأن الأذن توصل إلى القلب .",{h:"فإن كان الذى يسمع فى خطر ، فكم بالأكثر الذى يتكلم ؟ وكم بالأكثر الذى ينقل الكلام الردىء ."},"وماذا عن الذى يسىء العلاقات بين الناس بما ينقله من كلام ؟ لاشك أنه يكون بعيداً عن الله ، لأن الكتاب يقول « طوبى لصانعى السلام ، لأنهم يدعون أبناء الله » (متى ٥ : ٩) . فالذى لا يصنع سلاماً ، بل يصنع خصومة ، ليس هو إبناً لله .","* * *",{h:"سئل القديس يوحنا الأسيوطى :"},"هل الذى يدين الشر هو الذى يبغضه ؟","فأجاب : كلا لأن كل الناس تقول إنها تبغض الشر . وإنما أعمالك هى التى تثبت أنك تكره الشر .","* * *",{h:"وقال القديس أوغسطينوس :"},"إن الإنسان الذى استطاع أن يروض الوحوش ، لم يستطع أن يروض لسانه (كما قال معلمنا يعقوب ٣ : ٨) .","من ذا الذى لا يخاف من قول الرب : من قال لأخيه يا أحمق ، يكون مستحقاً لنار جهنم » .","* * *"],79:[{h:"الفصل الخامس"},{h:"علاج الإدانة"},"تعوّد احترام الناس .","معالجة مشكلة الفراغ .","البعد عن سماع الإدانة .","الاتضاع ولوم النفس .","حجة اصلاح الآخرين .","تداريب أخرى كثيرة ."],80:[{h:"تعوّد احترام الناس"},"إن عرفنا أسباب الإدانة ، يمكن أن نعرف علاجها . وأول سبب هو أن الإنسان يبيح لنفسه أن يخوض فى سمعة الآخرين ، ويجرح بهذا كرامتهم .",{h:"إذن عليك أن تتعود إكرام الناس ومحبتهم ، سواء فى حضورهم أو غيبتهم ."},"عوّد نفسك عدم الإساءة إلى أحد ، سواء فى الحديث معه ، أو فى الحديث عنه . إن كانت لديك كلمة طيبة ، قلها . وإلا ، فالأصلح أن تصمت ... تعود عدم إهانة أحد ، وعدم الحديث عنه بالسوء . ولا تضع أحداً على ميزان النقد ، ولا تشرّح شخصيات الناس . وفى هذه الحالة لن تدين أحداً .",{h:"إن الشخص الذى تعود احترام الغير ، لا يمكن أن يدين الغير ."},"فى الحياة الاجتماعية يلقبون هذا الشخص بأنه « إنسان مهذّب » . يكلم كل أحد بلياقة وباحترام وبأسلوب لطيف . ولا يعرف العيب طريقاً إلى لسانه . فلسانه لم يتعود أن يهين أحداً ، ولا أن يتكلم على أحد كلمة سوء ، وبالتالى لا يدين أحداً .","انظر ماذا يقول القديس يعقوب الرسول عن هذه النقطة بالذات فى حديث عن أخطاء اللسان :",{h:"« به نبارك الله الآب . وبه نلعن الناس الذين قد تكوّنوا على شبه الله » (يع ٣ : ٩) ."},"فاعتبر أن خطية الإدانة لعنة ، وإنها لعنة ضد أناس خُلقوا على صورة الله وشبهه ومثاله (تك ١ : ٢٦ ، ٢٧) . وتابع الرسول كلامه معاتباً فقال « من الفم الواحد ، تخرج بركة ولعنة ! لا يصلح يا أخوتى أن تكون الأمور هكذا » (يع ٣ : ١٠) ."],81:["إن كان الرب يقول « باركوا لاعنيكم » (متى ٥ : ٤٤) ، فهل نحن نلعن أخوتنا ؟!","وهوذا الكتاب يقول « باركوا ، ولا تلعنوا » (رو ١٢ : ١٤) .","ليكن فمك إذن نقياً ، وليكن لسانك طاهراً عفيفاً ، تخرج منه كلمات البركة ، ولا تخرج منه كلمة إدانة : شتيمة كانت أم لعنة أم إهانة ...",{h:"تدرب أنك لا تتكلم إلا عن فضائل الناس بقدر استطاعتك ."},"ركز على النقط البيضاء التى فى حياتهم ، واترك الباقى . حاول أن تتناساه . أما الأشخاص الذين اسودت صورتهم فى ذهنك جداً ، وصاروا مثل « اسكندر النحاس » عند بولس الرسول (٢تى ٤ : ١٤) ، فالأفضل أنك لا تأتى بسيرتهم على لسانك ، أقول أيضاً « على قدر طاقتك » ... إلى أن يصلح الله أمرهم ، إن أمكن ذلك ، وحينئذ ستتغير صورتهم فى فكرك ..",{h:"يستثنى من هذا أعداء الكنيسة وأعداء الإيمان ."},"أولئك الذين ينبغى أن تحذر الكنيسة منهم ، وتشرح أخطاءهم اللاهوتية حتى لا يقع أحد فيها . وعن مثل هؤلاء قال السيد الرب « احترسوا من الأنبياء الكذبة » (متى ٧ : ١٥) وأيضاً « احذروا من الناس » (متى ١٠ : ١٧) .",{h:"معالجة مشكلة الفراغ"},{h:"فى كثير من الأحيان ، إذ لا يجد الناس موضوعاً يتحدثون فيه ، يكون حديثهم عن أخبار الناس وأخطائهم وفضائحهم وسقطاتهم ."},"وهكذا تكون سيرة الناس هى الموضوع الأساسى للحديث فى البيوت ، وفى النوادى والمقاهى ، وفى كثير من الجلسات حيثما وجدت .","ليس لأنهم يريدون أن يدينوا غيرهم ، وإنما لأنهم لا يجدون موضوعاً آخر ـ غير أخبار الناس ـ يتحدثون فيه ."],82:[{h:"وقد يدينون رؤساء دول لمجرد قراءة أخبار تسهم فى الجرائد ، دون معرفة مدى صحة هذه الأخبار !"},"أو يدينون شخصاً ذكرت الجرائد أنه قد قبض عليه فى حادث معين . وربما تذكر الجرائد بعد شهور أن القضاء قد براه ، بعد تحقيق ما قد نُسب إليه . ولكن هذا الإنسان تكون سمعته قد وصلت إلى التراب خلال تلك الشهور . وربما يكون البعض قد قرأ خبر القبض عليه ، ولا يكون قد قرأ خبر الحكم ببراءته ...",{h:"ليت الناس يجدون مواضيع دسمة ومفيدة يشغلون بها وقت فراغهم ."},"يقيناً إن وجدوا هذا ، لا يكون أمامهم مجال لشغل وقتهم بمسك سيرة الناس .","انظروا إلى طلاب الكليات والمعاهد والمدارس ، فى أيام امتحاناتهم ، وهم مشغولون بالمذاكرة والمراجعة والاستعداد للامتحان ، أتراهم لديهم وقت للحكايات ، أو لتقليد المدرسين والتندر عليهم ، أو للحديث عن أخبار زملائهم وأخطائهم وفضائحهم ؟ كلا بلاشك ، لأنهم مشغولون ...",{h:"كذلك المرأة العاملة ليس لديها وقت كاف ، للجلوس مع جاراتها والحديث عن أخبار باقى الجيران ..."},"مع ما تحمل أمثال هذه الأخبار من التعرض لبعض الأخطاء وإدانتها . وإن وجدت وقتاً لهذا ، يكون ـ بالمقارنة ـ أقل بكثير جداً من زميلتها التى لا تعمل ، وأمامها فراغ طويل المدى لا تعرف كيف تقضيه ، واحتمال الوقوع فى مسك سيرة الناس ، محتمل أمامها جداً ووارد ...",{h:"ولكننا نقول إن الفراغ هو نصف السبب والنصف الثانى هو كيفية قضاء الوقت فى هذا الفراغ ."},"فقد يستغل أحدهم الفراغ فى قراءة مفيدة ، ينتفع بها ، وينفع بها غيره فى أحاديثه معهم . والبعض قد يستغل الفراغ فى عمل اليد ، أو فى التدريب على مهنة أو مهارة معينة ، أو يستغل فراغه فى خدمة الآخرين . أو فى زيارة مريض ، أو فى تعزية حزين ، أو فى مساعدة محتاج ."],83:[{h:"وفى الاجتماع مع الناس ، ما أحوج الكل إلى موضوع نافع يتحدثون فيه ."},"ويمكن هذا ، إن قصد أحدهم هذا الأمر ، واستطاع أن يدير الحديث فى موضوع نافع ، يكون قد درسه ، وأصبح مستعداً للكلام فيه ، والإجابة عن كل سؤال يدور حوله . وإدارة دفة الحوار بطريقة تفيد الكل . وذلك قبل أن يبدأ غيره فيطرح سيرة توقع الكل فى الإدانة ...",{h:"ويمكن أن يحدث هذا أيضاً فى محيط الأسرة ."},"بطريقة بسيطة وتلقائية ، لا تشعر أحداً بأنه أمام مدرس أو محاضر ... وذلك بطرح موضوع علمى ، أو دينى ، أو قصة أو خبر نافع ، أو اكتشاف مفيد ، أو ملخص لباب قرأه فى أحد كتب الثقافة أو كتب التاريخ ، أو أمر جديد ممتع من أمور المعرفة ، أو بعض التسليات والألغاز حول الكتاب المقدس أو سير القديسين .",{h:"إن الجلسة العائلية تحتاج إلى استعداد ، وكذلك جلسات الأصحاب ..."},"أما ترك تلك الجلسات فى فراغ ، فإنه يقود إلى أمثال هذه الإدانات ، أو إلى الثرثرة الفارغة التى هى مضيعة للوقت ، أو الحديث فى أى منازعات قد تتحول إلى صياح وشجار . ذلك لأنه لا يوجد موضوع نافع يتحدثون فيه ، أو لا يوجد من يتولى دفة الحوار بمهارة .",{h:"ألا ترون أن السبب ليس مجرد فراغ فى الوقت ، وإنما فى الفكر أيضاً ..."},"ونعود إلى السؤال مرة أخرى : لماذا تمتلىء البيوت والنوادى والجلسات بمسك سيرة الناس ؟ ونجيب :",{h:"لأنهم فى فراغ ، لا يجدون موضوعاً آخر يتحدثون فيه ."},{h:"عدم السماع"},"حاول بقدر امكانك ، أن لا تسمع ما يقال عن أخطاء الآخرين ."],84:["ابعد عن المجالس التى تعرف أنها ستدور حول هذه الموضوعات وأمثالها . وإن اضطررت للجلوس ، فلا تجعل ذهنك مركزاً فيما تسمعه ، بل حاول أن تشغل نفسك بشىء آخر ، أو حاول أن تغير مجرى الحديث .",{h:"وما تسمعه عن أخطاء الناس ، لا تصدقه كله ."},"ربما الراوى الذى روى الحديث لم يراع الدقة ، أو ربما أن الخبر قد تناقل من شخص إلى آخر ، حتى وصل أخيراً بطريقة مختلفة عن الواقع . وربما أن الطرف الآخر له رد على كل هذا الذى يقال . ونحن لا نستطيع أن نحكم على أمر من جانب واحد . وقل لنفسك أيضاً :",{h:"حتى إن كان كل ما قيل صدقاً ، ما شأنى أنا به ؟"},"استخدم هذه العبارة « أنا مالى خلينى فى حالى » .","اخبار الناس ليست من اختصاصى ، ولا أنا مسئول عنها أمام الله والناس ، وهذا الذى سمعته ، كأننى لم اسمعه ولا علمت به .",{h:"وهكذا لا تعاود التفكير فيما تسمعه من إدانات ."},"لأن التفكير يثبت الإدانة فى ذهنك ، وربما يتطور الأمر معك . فليكن ما سمعته إذن لا يعدو أن يكون كلاماً عابراً ، لا تعطه عمقاً فى داخلك . ولا تتحدث فيه مع آخرين ، ولا تنقله إلى أحد ، حتى لا يكبر حجمه ...",{h:"وحاول أن تصلى من أجل الشخص المدان ، ليستر الله عليه ."},"اطلب له المغفرة ، واطلب له الرحمة ، واسأل الله أن يصلحه . ولكن أياك أن تحتقره أو أن تدينه .","قال القديس الأنبا موسى الأسود « إياك أن تسمع بسقطة أحد أخوتك لئلا تكون قد دنته خفية .","* * *"],85:[{h:"حجة إصلاح الآخرين"},"إن اتاك فكر أنك إنما تدين لأجل اصلاح الآخرين ، وبدافع من الغيرة المقدسة ، حينئذ قل لنفسك :",{h:"ليس من أجل إصلاح الآخرين ، أنا أخسر نفسى !"},"وقل أيضاً : هل أنا الذى أقيم نفسى مصلحاً للآخرين ؟ أم إننى مكلف بذلك رسمياً أمام الله ، بحيث يتعبنى ضميرى إن لم أفعل ؟ ثم هل وصلت أنا إلى المستوى الذى أصلح فيه غيرى ؟","وإن كنت قد اؤتمنت فعلاً على وكالة (١كو ٩ : ١٧) ، فلتضع أمامك هذه القاعدة الروحية الهامة :",{h:"الذى يريد أن يصلح الآخرين ، ينبغى أن يصلحهم بطريقة صالحة ."},"ويأتى ذلك بالحب ، وبالاتضاع ، وبالكلمة اللطيفة الهادئة ، وعدم جرح شعور أحد فيما تريد صلاحه . وأيضاً عدم كشف عيوبه أمام الناس .",{h:"ولا يمكن أن تصلح أحداً بتعييره أو مسك سيرته ."},"وفى هذا الأمر ما أجمل قول الرب « فيما بينك وبينه وحدكما » (متى ١٨ : ١٥) . ويقول القديس يوحنا ذهبى الفم فى تأملاته حول هذه الآية « اسمعوا ما يقوله المسيح ... وبخه فيما بينك وبينه ، ولم يقل بينك وبين كل المدينة ، ولا بين كل الشعب ... إنه توبيخ فى السر ، لكى يكون الاصلاح سهلاً » .",{h:"والله يفعل معك مثل هذا ، فى السر أيضاً :"},"فهو حينما يريد أن يبكتك على خطيئتك ويقودك إلى التوبة ، يفعل هذا فى سرّ من الأسرار الكنسية ، فيما بينك وبين كاهنه سراً ، وليس فى اعتراف علنى ..."],86:[{h:"وفى الدفاع عن الحق واصلاح الآخرين أذكر قول بولس الرسول :"},"« أيها الأخوة إن إنسبق إنسان ، فأخذ فى زلة ، فاصلحوا أنتم الروحانيين مثل هذا بروح الوداعة ، ناظراً إلى نفسك لئلا تجرب أنت أيضاً » (غل ٦ : ١) .","وأيضاً قول القديس يعقوب الرسول « من هو حكيم وعالم بينكم ، فلير أعماله بالتصرف الحسن فى وداعة الحكمة . ولكن إن كانت لكم غيرة مرة وتحزب فى قلوبكم ، فلا تفتخروا وتكذبوا على الحق . ليست هذه الحكمة نازلة من فوق ... » (يع ٣ : ١٣ ـ ١٥) .","نقطة أخرى وهى : عليك أن تختبر نفسك جيداً :",{h:"أحقاً أنت تدين من أجل اصلاح الآخرين ؟"},"هل دوافعك هى مجرد غيرة مقدسة خالصة ، غير مختلطة بمشاعر أخرى :","أم أن الدافع الحقيقى هو عدم محبة هذا الشخص ، وحقد مستتر ، أو شماته بإنسان مخطىء ، أو محاولة اظهار أنك تعرف أكثر ، وأنك بالمقارنة أفضل ، وأنك فى موقف المعلم والمؤدب والقائد ... ! اختبر نفسك جيداً .","وإن كنت فى غيرتك تدعى أنك تأخذ حق الله من الناس ،",{h:"فهل أخذت أولاً حق الله من نفسك ؟"},"هل بدأت باصلاح نفسك ، قبل أن تقوم باصلاح غيرك ؟ هل أصبحت « تبصر جيداً » (متى ٧ : ٥) بحيث تستطيع اخراج القذى من عين أخيك ، دون أن تتلف عينه ؟ على أنه فى موضوع اصلاح الآخرين ، نحب أن نضع أمامك :",{h:"مثل الزوان والحنطة"},"لقد جاء الخدام إلى الرب يسألونه هل يذهبون فيخلعون الزوان من الحقل ، فأجابهم « لا ، لئلا تقلعوا الحنطة مع الزوان وأنتم تجمعونه . دعوهما ينميان كلاهما معاً إلى يوم الحصاد » (متى ١٣ : ٢٨ ـ ٣٠) ."],87:[{h:"إن الله لا يريدنا أن نضيع جهودنا فى خلع الزوان ، بقدر ما يريدنا أن ننمو كحنطة ."},"حتى إذا جاء يوم الحصاد ، نجد سنابلنا مملوءة بثلاثين وستين ومائة ، فتمتلىء أهراؤه قمحاً ...","كثيرون شغلوا أنفسهم بجمع الزوان ، باسم الغيرة المقدسة والاصلاح . وبسبب هذا امتلأوا غضباً وعصبية وصياحاً . وملأوا الجو بالإدانة والانتهار وتوبيخ الآخرين ، والحديث عن أخطاء الكنيسة والجمعيات والخدام والكهنة ، بألفاظ كلها قسوة ، وخالية من الاحترام ومن الأسلوب اللائق المهذب .","ونظر الناس إلى هؤلاء (المصلحين) وصورتهم العصبية وأساليبهم المهينة ، وقالوا : إنها تذكرنا تماماً بصورة الزوان .",{h:"نعم ، أخشى عليك فى جمع الزوان ، أن تصير أنت نفسك زواناً !"},"إذ تفقد وداعتك واتضاعك ، وتتعلم الشتيمة والإهانة ، ومسك السيرة ، والتعالى على الناس ... كما تتعود قسوة القلب فى احكامك ، بل قد تكره البعض وتعاديهم . وتثور وتضج ... عجباً اتراك من أجل الرب فى كل تلك الخطايا ؟!","نعم احترس ، لئلا فيما تخلع الزوان من الناس ، تخلع أيضاً الحنطة التى فيك : تخلع هدوءك ، وسلامك القلبى ، ودمائة خلقك . وتخلع أيضاً ثمار الروح التى عندك « المحبة والفرح والسلام والوداعة واللطف والتعفف » (غل ٥ : ٢٢) .",{h:"ومع فقدك كل هذا تجد أنك لم تصلح أحداً !"},"وإنك لاكسبت سماء ولا أرضاً ، ولاكسبت قيادة الناس ، إلى الملكوت ، ولا كسبت هدوءك وعلاقتك مع الناس على هذه الأرض . لاكسبت الناس ، ولا ربحت نفسك ... لأن اصلاح الناس لا يأتى عن طريق الإدانة والتشهير ...",{h:"يقول القديس أوغسطينوس :"},"« إننا عندما نغتاظ من الأشرار ، فلسنا بعد سوى بشر . وعلينا أن نصغى إلى قول الرسول : من يظن أنه قائم ، فلينظر لئلا يسقط (١كو ١٠ : ١٢) »"],88:["فلنكن نحن حنطة ، ولا نضيع أوقاتنا فى جمع الزوان . وإذا أردنا أن نجمع زواناً ، فلنجمع الزوان الذى فينا . لنجمع الخطية التى فينا ونخرجها خارجاً .",{h:"لئلا فيما نحاول اصلاح غيرنا ، ننسى اصلاح أنفسنا ."},{h:"عجيب أن كل أحد أصبح يقيم نفسه مسئولاً عن الناس !"},"يفكر فى الناس وأعمالهم ، وما ينبغى أن يصدر على أعمال الناس من أحكام ! أما نفسه فهى آخر ما يفكر فيه !","صدقونى إنها حرب من الشيطان أن يشغلنا عن أنفسنا ، بالتفكير فى خطايا الناس ، وأن يشغلنا عن التوبة ، بالتفكير فى أعمال الناس .",{h:"إن الله فى اليوم الأخير سوف لا يحاكمك على خطايا غيرك . إنما سيحاكمك عن أخطائك وحدك ."},{h:"الاتضاع وإدانة النفس"},"يمكن معالجة خطية إدانة الآخرين ، عن طريق إدانة النفس ..","* وقد شرح القديس مارأوغريس كيف أن كلاً منهما ضد الأخرى ، فقال :",{h:"« إن دنا أنفسنا ، وحكمنا على أنفسنا أننا أشرار ، يبدو الناس أمامنا أطهاراً وملائكة . وإذا دنا الناس وحكمنا عليهم بأنهم أشرار ، نبدو نحن أمام أنفسنا أننا ملائكة وقديسين » ."},"* فى إحدى المرات مدح بعض الأخوة شخصاً أمام القديس الأنبا بيمن ، وقالوا فى سياق الحديث إنه يكره الأعمال الشريرة . فسألهم عن معنى عبارة « يكره الأعمال الشريرة » . فلما ارتبكوا فى الإجابة ، قال لهم : « كراهية الأعمال الشريرة هى كراهية الأعمال الشريرة التى نعملها نحن ، وليست الأعمال التى يعملها الناس » ."],89:["* قال القديس الأنبا باخوميوس « إن الإدانة تأتى من تعظم القلب . أما المتضع ، فإنه يعتبر كل الناس أفضل منه » .","وقال القديس باخوميوس :","« احفظ نفسك من ذلك الفكر الذى يجلب عليك تزكية ذاتك وازدراء أخيك ، لأنه مغبوط جداً قدام الله ذلك الإنسان الذى يكرم غيره ويرذل نفسه »","لذلك كلما يأتيك فكر إدانة لأحد ، تذكر خطاياك . وقل : هذا الإنسان أبر منى ، لأنى فعلت كذا وكذا . ولا يمكن أن يكون هو قد وصل إلى هذه السقطات التى وقعت فيها أنا .","إنك إذا لم تفكر فى عيوبك ، فسوف تقع فى عيوب غيرك .","* لذلك يقول مار إشعياء : إن تركت الاهتمام بخطاياك ولم تنشغل بها ، وقعت فى خطايا غيرك .","* سأل أحد الأخوة شيخاً من شيوخ الرهبنة « ما هو السبب فى أنى أدين الأخوة دائماً ؟ » . فأجابه الشيخ : لأنك لو عرفت نفسك ، لما تفرغت لغيرك . لأن الذى يهتم باخراج الخشبة من عينه ، لا يتفرغ لاخراج القذى من عين أخيه .",{h:"ولهذا إن فكرت أن تدين إنساناً ، قل لنفسك « أنا أيضاً خاطىء » ."},{h:"« إن فحصت نفسى جيداً ، ووجدت إننى بلا خطية ، فلأقذفه بهذا الحجر ... »"},"* فى إحدى المرات طردوا أخاً من المجمع ، وأخرجوه خارجاً . فسأل القديس بيساريون عن السبب ، فقيل له بسبب الخطية التى وقع فيها . فقام القديس بيساريون وخرج هو أيضاً خارج المجمع ، وهو يقول : « وأنا أيضاً رجل خاطىء » .","* ومعروفة قصة القديس موسى الأسود ، الذى دعى إلى المجمع لمحاكمة أخ أخطأ . فحضر وهو يحمل على ظهره كيساً مثقوباً ومملوءاً بالرمل . فسألوه لماذا فعل هكذا ؟ فقال « هذه خطاياى وراء ظهرى تجرى ، وقد جئت لأدين أخى على خطيئته !! » ...","* أخ سأل الأنبا بيمن قائلاً « كيف استطيع أن لا أقع فى الناس ؟ »"],90:["فأجابه : إذا لام الإنسان نفسه ، فحينئذ يكون أخوه عنده أكرم وأعظم . أما إذا نظر إلى نفسه بأعجاب ، يكون أخوه فى نظره خاطئاً ومداناً .","* قال مار اسحق : « مغبوط هو الإنسان الذى يكرم أخاه ، ويدين نفسه . ومغبوط هو الذى يرى فى عيوب الآخرين سقطات نفسه » .","أى أنه كلما يرى عيباً فى الآخرين ، يبحث داخل نفسه ، فسيجد أن هذا العيب فيها . فليلم نفسه بدلاً من أن يدين غيره ...","وإذا رأى الناس يوبخون شخصاً على خطأ معين ، يقول لذاته « هذا القلم على خدك يا ارسانى » .","* * *",{h:"تدريب لمعالجة الإدانة"},{h:"١ ـ درب نفسك على معالجة خطايا اللسان جملةً ..."},"فستجد أنك قد تخلصت من خطية الإدانة ضمناً . اسلك فى بعض تداريب الصمت . أو فى تدريب عدم التدخل فيما لا يعنيك ، ولاشك أن خطية الإدانة ستكون ضمن تدخلك فى شئون غيرك .","هذا التدريب سوف يساعدك على مقاومة (الإدانة باللسان) . وسيكون خطوة فى مقاومة الإدانة بالفكر أيضاً بمرور الوقت ، لأنه سيغرس فى قلبك البعد عن الإدانة .","* * *",{h:"٢ ـ تذكر قول الرب « اذكر من أين سقطت وتب » (رؤ ٢ : ٥)"},"وذلك بأن تجلس فيما بينك وبين نفسك ، وتعرف من هم الأشخاص الذين تدينهم باستمرار ؟ وما هى الموضوعات التى توقعك فى الإدانة ؟ وما هى الجلسات أو الشخصيات التى تكون عثرة لك . ثم تحترس من جهة هذه المصادر التى تتسبب لك فى إدانة الآخرين ."],91:[{h:"٣ ـ يمكن معالجة الإدانة بالمحبة :"},"فإن كنت قد فقدتها بالنسبة إلى البعض ، أو فقدت بعضها ، فحاول بقدر إمكانك أن تسترجع ما فقدته . لأن الكتاب يقول عن المحبة إنها « لا تقبّح » « ولا تظن السوء ، ولا تفرح بالإثم » (١كو ١٣ : ٥ ، ٦) ، وبالتالى لا تدين","وتأكد من أن الإدانة تزيد العلاقات سوءاً فبدلاً من أن تسترجع المحبة القديمة ، قد تزداد الهوة عمقاً بينك وبين الذى تدينه ، وبخاصة إذا كان هناك من يوصلون الكلام ، ومن يزيدون عليه . وحتى بدون هؤلاء ، أمام ضميرك وقلبك لن ترتاح ...","* * *",{h:"٤ ـ تذكر اضرار الإدانة عليك :"},"وما قاله القديسون من أنه بالدينونة قد تفارقك النعمة والمعونة الإلهية ، وهكذا تتعرض للسقوط . وكذلك ما قاله السيد الرب إنه بالكيل الذى به تكيلون ، يكال لكم ويزاد » . كذلك ما توقعك فيه الإدانة من خطايا أخرى تصاحبها .",{h:"قال القديس بفنوتيوس :"},"احذر أن تقول كلمة ردية على أخيك ، لكى لا يمنعك الله من أرض الميعاد ، وتحرم من أكل ثمرتها ... كما جرى مع شعب اسرائيل بالنسبة إلى موسى ابيهم ويشوع وكالب أخويهم » .",{h:"وقال شيخ :"},"« إن خطية الوقيعة من شأنها أن لا تترك صاحبها يحضر قدام الله ، لأنه مكتوب « إنى كنت اطرد من يغتاب قريبه سراً » (مز ١٠١ : ٥)",{h:"وابتعد عن الإدانة خوفاً من السقوط ، وخوفاً من العقوبة ."},"ولا مانع من أن تضع فى ذهنك بعض آيات الكتاب الخاصة بالإدانة : تحفظها وتردد ها ، وتتأملها بين الحين والآخر .","* * *"],92:[{h:"٥ ـ تدرب أنك لا تظن السوء بالناس ، ولا تحكم حكماً سريعاً ."},"فقد يكون الظن السىء فيه ظلم ، وكذلك الحكم السريع . ولذلك لا تحكم على أحد دون فحص ، وبسرعة . بل تعوّد التروى والتأنى فى أحكامك عموماً ، سواء ما لك حق فيه ، وما ليس لك فيه حق .",{h:"واحترس من أن تلبس نظارة سوداء ، تنظر بها إلى الناس ."},"* * *",{h:"٦ ـ تعود الشفقة على الناس فى أحكامك :"},"حاول أن تأخذ الجانب الذى يتراءف ، وليس الذى يقسو . وفكر فى قلبك ، ربما تجد عذراً يخفف من الحكم . وفى اشفاقك صلّ من أجل المذنب ، فالصلاة تزيد مشاعر الشفقة ، كما أن الشفقة تدفعك إلى الصلاة .","* * *",{h:"٧ ـ ولا تكون الإدانة حسب الظاهر :"},"فربما تجد رجلاً يبكى أمام كنيسة أو جمعية ويطلب مالاً لأنه لا يجد طعاماً لنفسه وأولاده ، ومع ذلك لا يعطيه أحد . فتقول « ما أقسى هؤلاء الناس الذين لا يرحمون جائعاً !! بينما لو سألت لعلمت أنه يأخذ كثيراً ، ربما أكثر من حاجته ، ولا يكتفى . ويقوم بمثل هذا الموقف الباكى المستغيث لمجرد الاحراج والضغط أمام الناس ، لأخذ المزيد بدون استحقاق !","* * *",{h:"٨ ـ درّب نفسك أن تحتمل من يسيئون إليك :"},"فأحياناً عدم احتمالك لهم ، يجعلك تتبرم بهم ، وتشكوهم ، وتتحدث عن أخطائهم أمام كل أحد ، وتدينهم بمقدار ما أنت متضايق منهم .","أعرف أننا لا نعيش فى عالم كله مثالية . بل توجد أخطاء . وإن ثار قلبنا على كل خطأ ، وانتقلت الثورة إلى ألسنتنا ، فأخذت تدين وتنشر أخطاء الناس ، وتهدد"],93:["وتعاقب ... لاشك أننا أنفسنا لن نستريح ، كما أننا لا نريح أحداً .",{h:"كثير من أخطاء الناس ، تحتاج منا أن نجوز مقابلها ، ونمررها بالصبر والاحتمال كأن لم نتحدث ، دون أن ندين أصحابها ..."},"* * *",{h:"٩ ـ احترس من إدانة شخص على عيب خَلْقى لا ذنب له فيه :"},"أو تجعله مجالاً للهزأة والاستهتار والتهكم بسبب شكله ، أو عقله ، أو تشويهه ، أو قصره ، أو سمنته الزائدة ، أو ما شابه ذلك . لأنه ليس من العدل أن يحكم على إنسان بسبب شىء هو خارج ارادته .","* * *",{h:"١٠ ـ كن حريصاً جداً فى الإدانة بطريق العتاب :"},"لأنه وإن كان الله قد صرح بالعتاب (متى ١٨ : ١٥) ، إلا أنه ليس كل إنسان يحتمل العتاب . وكم من عتاب أتى بنتائج سيئة جداً . ولذلك قال الكتاب « من يوبخ مستهزئاً يكسب لنفسه هواناً ، ومن ينذر شريراً يكسب عيباً . لا توبخ مستهزئاً ، لئلا يبغضك . وبخ حكيماً فيحبك » (أم ٩ : ٧ ، ٨) .","* * *",{h:"ـ ختاماً : لا تجعل خطية الإدانة تصبح طبعاً من طباعك :"},"فهناك فرق بين الإدانة العابرة . والإدانة التى تصير منهج حياة ، أو صفة ملازمة لإنسان . حيثما يوجد يدين ويحكم ويتناول سير الناس بالنقد والتحليل ، بسبب وبدون سبب !!","* * *"]}},shukr_life:{id:"shukr_life",title:"حياة الشكر",author:"قداسة البابا شنوده الثالث",url:"https://drive.google.com/file/d/1jpgfORhVhisGktXRc0sGCWjOCxGdPDCO/view",file:"حياة_الشكر.pdf",pageOffset:5,review:{status:"needs-review",note:"نُقل الكتاب (من مقدمة الناشر إلى الخاتمة، ص٣ إلى ص٢٦ بترقيم الملف) بقراءة الصفحات الممسوحة بالنظر؛ الأصل مطبوع بالآلة الكاتبة بلا همزات فأُثبتت الهمزات والتشكيل الإملائي المعتاد، وبعض الكلمات في حواف الصفحات المضببة قُرئت بأفضل ما تيسر وتحتاج مطابقة نهائية مع الأصل."},chapters:[{title:"مقدمة الناشر",from:3,to:3},{title:"حياة الشكر والإيمان",from:4,to:12},{title:"الإرادة البشرية والتدبير الإلهي وعشر بركات للشكر",from:13,to:22},{title:"حياة الشكر تستلزم الاتضاع والخاتمة",from:23,to:26}],transcribed:[3,26],pages:{3:[{h:"مقدمة"},"تحوى هذه النبذة إحدى محاضرات قداسة البابا المعظم الأنبا شنودة الثالث التى ألقاها ـ وأربعاً أخرى غيرها ـ بالمؤتمر الأول لخدام التربية الكنسية بالإسكندرية عام ١٩٦٨ بكنيسة القديس مارمينا بالمندرة ـ وكان قداسته عندئذ أسقفاً للتعليم ـ وقد سبق لمكتبة كنيسة السيدة العذراء بمحرم بك أن طبعت المحاضرات الخمس المذكورة طبعة أولى عام ١٩٧١ ـ وهو أول عام لتبوا قداسته السدة الرسولية .","ولقد نفذت الطبعة الأولى لتلك المحاضرات وإزاء الإلحاح فى طلبها رأينا أن نقوم بإعادة طبعها واحدة بعد الأخرى وها نحن نقدم الطبعة الثانية لهذه المحاضرة عن",{h:"حياة الشكر"},"راجين الرب أن يجعلها لخير القراء ولبركة حياتهم وشركتهم فى الرب . ببركة صلوات قداسة البابا المعظم الأنبا شنودة الثالث أطال الله حياته ورئاسته للكنيسة سنين عديدة وأزمنة سالمة مديدة ـ آمين .","الكنيســــة"],4:[{h:"حياة الشكر والإيمان :"},"إن حياة الشكر مرتبطة بأمور أخرى تسبقها وتندمج معها ... فحياة الشكر تلزمها حياة الإيمان ، الإيمان بالله فى صفات معينة بدونها لا يمكن أن نصل إلى حياة الشكر ... فلابد أن تؤمن أولاً أن الله صانع للخيرات ، وثانياً أنه محب البشر . فالله لابد أن يصنع خيراً ـ لا يستطيع أن يصنع إلا الخير ـ وهو باستمرار يصنع خيراً معك ومع باقى الناس . ولابد أن تؤمن ثالثاً أن الله قادر على كل شىء ـ هو يحبك ويريد أن يصنع معك خيراً ، وهو قادر على صنع الخير ... هذه الصفات الثلاث تجعلك تثق بأن الله يصنع دائماً خيراً .","وهنا تقابلنا مشكلة وهى أن الله مع أنه يصنع الخير ، إلا أنه أعطى حرية للناس ، والناس قد يصنعون شراً ... فربما يأتيك الشر من الناس فاعلى الإثم وليس من الله . وهنا لابد أن تؤمن رابعاً أنه توجد صفة أخرى لله تضعها إلى جوار هذا فتستريح وهى صفة الله كضابط الكل ،"],5:["يرقب كل أحد ... فالحرية التى أعطاها للناس لا تعنى أنه تخلى عن إدارته للكون ، وترك كل إنسان يفعل ما يريد . إنما الله يعطى الحرية ويرقب ويقود ويلاحظ كل شىء ، ويغير ما يحتاج إلى تغيير ، ويمنع ما يراه ضاراً ... هو ضابط الكل . هذه الصفة تريحك من جهة حرية الناس وحرية الشياطين وأيضاً حريتك الشخصية ... لأن الشر الذى يأتيك ربما يكون صادراً عن حرية الناس الأشرار أو عن حريتك الشخصية التى بها تضر ذاتك ، أو عن محاربة الشياطين ... والله ضابط الكل يتدخل فى كل هذه الأمور وينفذ مشيئته الصالحة الطوباوية . فالله لا يمنح الحرية مطلقة ... وإلا هلك العالم . حتى الشياطين الأشرار الذين هم بطبيعتهم الملائكية الروحية لهم قوة تفوق الطبيعة ، إلا أنهم ليسوا أحراراً فيما يعملون ... ففى قصة أيوب مثلاً نلاحظ أن الشيطان كانت حريته محدودة . كان يقترح أموراً ، والله يسمح له أو لا يسمح ، ويضع له حدوداً وقيوداً معينة ... قال له أولاً هوذا كل ما لأيوب فى يدك ، وإنما إليه لا تمد يدك (أى ١ : ١٢) . وفى المرة الثانية سمح له أن يمد يده إلى جسد أيوب دون عقله أو نفسه ... حتى الشيطان ، يحدد له الله عمله ويقيده ولا يترك له الحرية المطلقة ... فلهذا اطمئن ، لأن الله صانع الخيرات ، محب البشر ، ضابط الكل ، يرعاك ويهتم بك ولا يسمح أن يأتيك ما يضرك ، وإن آمنت بهذا لابد أن تشكره على عنايته ."],6:[{h:"الشر وصانع الخيرات"},"وهل نشكر الله على الشرور التى يسمح بها ؟ ... طبعاً نشكره . نحن نشكر الله على كل حال ومن أجل كل حال وفى كل حال . أشكر الله الذى يستطيع أن يحول الشر إلى خير ... بعين الإيمان انظر إلى هذه المتاعب فى ضوء تدخل الله وتحويله لها إلى الخير ... وإليك المثل :","يوسف الصديق : فعل به إخوته شراً ، باعوه كعبد ... ولكن الله الذى يخرج من الجافى حلاوة ، استطاع أن يحول هذا الشر إلى خير . لذلك قال يوسف لإخوته أخيراً « أنتم قصدتم بى شراً والله قصد به خيراً » (تك ٥٠ : ٢٠) . إمرأة فوطيفار الشريرة أرادت بيوسف شراً ، ودفعت له تهمة كاذبة ألقت به فى السجن ... ومع ذلك فالله حول هذا الشر إلى خير بالنسبة ليوسف شخصياً ولأرض مصر والعالم كله ... ! لأن يوسف كان سبب بركة لمصر فى المجاعة وللعالم المحيط بها الذى انتفع من تدبير يوسف لها . فلو آمنت بالله أنه يحول الشر إلى خير ستعيش فى حياة شكر كامل ، على كل ما يحل بك . لذلك لا تتعب أبداً ... إن كان الذى يحدث لك خيراً فى ذاته ، فسيصلك هذا الخير . وإن كان شراً ، فإن ضابط الكل سيقابله فى الطريق ويحوله إلى خير ليصلك خيراً ."],7:[{h:"الصبر وحياة الشكر"},"إننا بحياة الإيمان نرتاح ونشكر الله على كل أعماله الصالحة معنا . وإلى جوار هذا لابد أن تكون صبوراً وطويل الأناة ... لأن هناك أعمالاً تتحول إلى خير فى مدى زمن طويل يحتاج منك صبراً . ففى قصة يوسف الصديق : بيعه كعبد لم يتحول إلى خير فى نفس السنة . القاؤه فى السجن لم يتحول إلى خير فى نفس السنة ... ولكن بالمدى الزمنى وبمرور الوقت رأينا الخير الذى نتج عن ذلك . فعليك أن تكون طويل الأناة واثقاً فى حكمة الله ورحمته وتدخله فى الوقت المناسب بالطريقة المناسبة .",{h:"الأهواء الشخصية وحياة الشكر"},"من الأمور المهمة فى شعور الإنسان بالخير وبالشر وما يترتب عليه من شكر أو تذمر ، رغباتنا الداخلية ونوع تقييمنا للأمور ... كتب القديس يوحنا ذهبى الفم مقالاً جميلاً عنوانه « لا يستطيع أحد أن يضر أحداً إلا إذا أضر الإنسان نفسه » ... بدون فهم هذا الموضوع لا تستطيع الوصول إلى حياة الشكر . ما الذى يستطيع إنسان ـ أو حتى شيطان ـ أن يضرك به ... ؟ لو كنت أنت إنساناً قديساً ، صالحاً ، باراً ، تحب الله ... سيكون لك هدف واحد فقط هو الإلتصاق بالله ورغبتك هى فقط فى"],8:["ملكوت السموات . وهذا لا يستطيع أحد أن يضرك فيه . أما إذا جمعت لنفسك أهدافاً ورغبات أخرى أضفتها إلى الله ... فهذه هى التى تضرك . قلبك من الداخل ـ المحب لهذه الرغبات ـ هو الذى يضرك وليس الناس . قد يستطيع أحد أن يأخذ منك مالاً ، فإذا كنت لا تهتم بالمال فى كثرته أو قلته فلا تضر . قد يستطيع أحد أن يزج بك فى السجن ، فإذا كنت لا تهتم إلا بحرية ضميرك وفكرك وقلبك فى علاقتك مع الله ، ولا تهتم بالمكان الذى تعيش فيه ولا بالحالة الأرضية ، عند ذلك سوف لا تشعر بضرر . فبولس الرسول كان فى أعماق السجن وكان يرتل بفرح ... ماذا يصنع بك الناس من الخارج ؟ أيقتلونك ؟ وماذا يضرك هذا إن كان لا هدف لك سوى الحياة مع المسيح ؟! ... الشهداء عذبوا وقتلوا ، ولم يشعروا أنهم قد أصيبوا بضرر ، لأن الضرر الوحيد هو الإنفصال عن الله وهذا يتعلق بالقلب من الداخل وليس بالناس ... يوسف الصديق صار عبداً ولم يتعب ، لأن الحرية لم تكن هى هدفه ، وكذلك السجن لم يفصله عن الله ... الضرر الوحيد هو انفصالك عن الله ، وهو لا يأتى إلا بانحراف إرادتك الشخصية نحو الشر ، وتكون أنت الذى آذيت نفسك وليس إنسان آخر ."],9:[{h:"التجارب وحياة الشكر"},"قد يفقد الناس حياة الشكر عندما يقعون فى أحزان ومتاعب متنوعة . أما رجال الله القديسون الذين لا تتعبهم كل هذه الأمور ، ولا يتعبهم إلا الإنفصال عن الله ، فكل ضيقات العالم لا تتعبهم . هم يعيشون فى شكر دائم فى كل حال ، فى الفقر وفى الغنى ، فى السعة وفى الضيق ، فى المرض وفى الصحة ، فى الموت وفى الحياة ... دائماً يشكرون لأن الهدف الوحيد وهو الإلتصاق بالله ، لم يفقدوه فى كل هذه الحالات . لذلك هم فرحون متهللون شاكرون . لو ضاع منى كل شىء وبقى لى الله وحده ، فماذا معى كل شىء ، لأن الله هو الكل فى الكل ، فما الذى يحزننى ؟ ... يقول بولس الرسول « لذلك أسر بالضعفات » (٢كو ١٢ : ١٠) ... لماذا ؟ لأن الضيقات تقربنى إلى الله أكثر ، وتجلب لى أكاليل أكثر ... فما الذى يحزننى ؟ أشكر الله على كل حال ... فى الصحة وفى المرض ... ولماذا أشكر الله فى المرض ؟ لأنه ليس شراً فى ذاته « لعازر المسكين المذكور فى قصة « الغنى ولعازر » كان مثقلاً بالأمراض ، وكانت عنده قروح كثيرة والكلاب تلحس هذه القروح ... لكن هذا كله لم يكن شراً فى ذاته ولم يفصله عن الله ، بل على العكس كان للفائدة . فعندما اتكأ فى"],10:["أحضان إبراهيم ، قدم عنه تقريراً أنه « استوفى بلاياه على الأرض لذلك هو يتعزى » (لو ١٦ : ٢٥) . هكذا فلتشكر الله فى المرض لأنك قد تستوفى به البلايا وتأخذ نصيب لعازر المسكين ."],11:[{h:"لا نعلم ما نصلى لأجله"},"قال القديس باسيليوس الكبير « وإن كنت مريضاً لا تطلب من الله صحة ، لأنك لا تعرف ما هو المفيد لك ـ الصحة أم المرض ؟ » . طبعاً نحن بضعفنا البشرى نطلب الصحة لكننا لا نعرف روحياً ما هو المفيد ... ربما يتعبنى المرض على الأرض لكنه يضمن لى ملكوت السموات إذا كان استغلالى له حسناً . من المعروف عن المهاتما غاندى أنه كان يكره الطب والمستشفيات ـ لا نريد مناقشة الرأى كله وإنما نعرض فقط وجهة نظر غاندى فى المستشفيات . إنها تعطى الإنسان صحة جسدية ربما يغضب بها الله ... وربما ينهمك بها فى الإثم ويخسر الله ! . ولذلك كان غاندى يهتم بالعلاج الروحى والنفسى أكثر من العلاج الجسدى . ما معنى أن شاباً مريضاً يعطى صحة يستغلها فى الزنى والفسق ! . ما معنى أن إنساناً شريراً يعطى صحة يستغلها فى الظلم والسرقة والفساد ! ... هل كانت هذه الصحة للفائدة أم للضرر ؟ فالمهم إذن الصحة الروحية . حكى فى بستان الرهبان عن أحد الرجال الأثرياء النبلاء أن كانت له ابنة وحيدة مريضة مشرفة على الموت ، فطلب من أحد القديسين أن يصلى من أجلها لتشفى . فحاول القديس أن يعتذر بشتى الطرق ، ولكن الرجل ألح عليه ، فصلى القديس وعاشت"],12:["الفتاة . إلا أنها سلكت فى سيرة شريرة أضاعت بها كرامة أبيها ، لدرجة أنه عاد إلى القديس وقال له « صلّ لكى يأخذ الله الفتاة » ... فأجابه « أنت طلبت مشيئتك الخاصة » نحن لا نعرف يا إخوتى ما هو المفيد لنا ... ومع ذلك كثيراً ما نطلب الصحة ، ولا يكون طلبنا هذا خاطئاً ، ولكن لو تمسكنا به نخطىء . بولس الرسول أعطى شوكة فى الجسد لئلا يرتفع من فرط الإعلانات . وقد طلب إلى الله أن يفارقه هذا المرض إذ قال : « إلى الله تضرعت ثلاث مرات أن يفارقنى » (٢كو ١٢ : ٨) . ولكنه لم يستجب !! رفض الله صلاة بولس الرسول قائلاً : « تكفيك نعمتى » (٢كو ١٢ : ٩) . فالمرض كان صالحاً له ."],13:[{h:"الإرادة البشرية والتدبير الإلهى"},"إن مشكلتنا فى حياة الشكر هى أننا نريد أن ندبر أمورنا بعقليتنا وطريقتنا الخاصة ـ فإذا لم تمط طلباتنا نغضب . وقد لا نغضب ولكن أيضاً لا نشكر وهناك فرق بين إنسان شاكر وبين إنسان غاضب . فإذا شكرنا الله فمعنى ذلك أننا نرى الخير فى كل عمل الرب معنا .","وإذا كان الله يقول فى كتابه المقدس : من يعرف أن يعمل حسناً ولا يعمل فذلك خطية له (يع ٤ : ١٧) فبالحرى ـ يعمل هو الخير إذ باستطاعته أن يعمل ـ وبالضرورة لابد أن أؤمن بأن الله يصنع خيراً معى وهو فعلاً يصنع ذلك .","ولماذا إذن تتتابنى أتعاب ـ كل ذلك بسبب إرادتى أنا المنحرفة . لأن الله يصنع دائماً معى خيراً ، لكنه لا يرى من الخير أنه يسلبنى هذه الإرادة التى بها أضر نفسى أحياناً . أما هو فينبغى أن أشكره فى كل حين ... إن كانت حالتى سيئة ، فكان ممكناً أن تكون أسوأ لو تخلت عنى نعمة الله . الله يصنع معى خيراً ، ولكننى لا أصنع خيراً مع نفسى ، فينبغى أن أشكر الله وألوم نفسى ... ولنطرق بعض نواحى تفصيلية ."],14:[{h:"لماذا أشكر الله ... ؟!"},"لعل من أجمل القطع الروحية التى سمعتها وقرأتها فى حياتى فى نواحى الشكر هى القطعة الموجودة فى القداس الغريغورى « قدوس قدوس أنت أيها الرب وقدوس فى كل شىء » وأولها التى يبدأ فيها الكاهن نيابة عن الشعب فى شكر الله على كل شىء إذ يقول ... « خلقتنى إنساناً كمحب البشر ولم تكن أنت محتاجاً إلى عبوديتى بل أنا المحتاج إلى ربوبيتك . من أجل تعطفاتك الجزيلة كونتنى إذ لم أكن . أقمت السماء لى سقفاً وثبت لى الأرض لأمشى عليها . من أجلى لجمت البحر . من أجلى أظهرت طبيعة الحيوان . أخضعت كل شىء تحت قدمى . لم تدعنى معوزاً شيئاً من أعمال كرامتك ... الخ » .","ومن هذه القطعة نستطيع أن نتأمل بركات :","١ ـ أشكر الله لأنه خلقك : من منا يشكر الله لأنه خلقه وأنعم عليه بالوجود ؟ توجد أشياء كثيرة ننساها ، ليتنا نتذكرها ... هل تشكر الله لأنه أوجدك ؟ كان ممكناً ألا تخلق على الأرض . الله لم يكن مطالباً بأن يزيد العالم واحداً ! . كان ممكناً أن تكون والدتك عاقراً ولا تلد بنين ، وكثير من النساء عواقر . إن مجرد ولادتك نعمة عظيمة من الله إذ"],15:["يقول فى المزمور : « البنون ميراث من الرب » وكان ممكناً ألا يعطى والدك هذا الميراث ، أو أن ينجبا إخوتك فقط ولا ينجباك أنت بالذات .","٢ ـ أشكر الله لأنه خلقك فى اليوم السادس : الله قبل أن يخلقك صنع من أجلك أشياء كثيرة ... نحن نشكر الله ليس لأنه خلقنا فقط ، بل أيضاً لأنه خلقنا فى اليوم السادس ... لماذا لأنه أعد كل شىء لراحتنا قبل أن يخلقنا . لذلك نقول فى القداس « أقمت السماء لى سقفاً وثبت لى الأرض لأمشى عليها . من أجلى لجمت البحر ! من أجلى أظهرت طبيعة الحيوان ، أخضعت كل شىء تحت قدمى » فالله أعد كل شىء قبل أن يخلق الإنسان : خلق السماء وزينها بالشمس والقمر والكواكب وخلق النور ، خلق الأرض والنبات والحيوان ... خلق الإنسان بعد أن أعد له كل نواحى الراحة ، وبعد أن ضبط القوانين الطبيعية سواء قوانين الفلك والسماء أو القوانين الأرضية من جهة الأمطار والرياح والحرارة والرطوبة ... الخ . بعد أن دبر كل شىء خلق الإنسان ... أشكر الله من أجل المواهب الإنسانية التى أعطاك إياها ... الذكاء والعقل والنطق والمشاعر والحواس ... من أجل كل الأشياء الطبيعية التى كثيراً ما ننساها عندما نشكر الله ."],16:["٣ ـ أشكره لأنه خلقك مسيحياً : أشكر الله أيضاً لأنه جعلك تولد مسيحياً لأن كثيرين يشتهون هذا الإيمان ولا يجدونه . بل ويتعبون من أجله كثيراً ، ولا يستطيعون الوصول إليه ، إذ تقف أمامهم كثير من المشاكل العقائدية والمتاعب والمشاكل الاجتماعية وغير الاجتماعية ... أما أنت فوجدت فى هذا الإيمان وفى هذه العقيدة ...!! أشكر الله على هذا .","٤ ـ أشكره لأنه وهبك الصحة والحواس وجميع الأعضاء : أشكر الله أيضاً على الصحة التى أنت فيها ، من منا يشكر الله لأنه يبصر ؟ لكن إذا تعبت عيناك وبدأت تعالجهما ، تبدأ فى الشعور بنعمة البصر التى لم تشكر الله عليها من قبل . أنا لا أبدأ أشكر الله على رجلى التى أسير بهما حسناً إلا بعد أن تبدأ فى التعب وابتدىء أحتاج إلى عصا استند إليها ...!! أنت لم تشكر الله لأن معدتك تهضم الطعام جيداً ، ولكن إذا حدث لها تعب أو نقص فى العصارات ! أو أصبت بقرحة فى المعدة ... حينذاك تبدأ تشعر أنك كنت فى نعمة لم تشكر عليها ...! صدق الحكيم فى قوله « الصحة تاج فوق رؤوس الأصحاء لا يعرفه إلا المرضى » نحن لا نحس قيمة الشىء الذى عندنا إلا عندما"],17:["نفقده ، فنندم لأننا لم نشكر عليه ... كثير من الناس يشتهون الوضع الذى أنت فيه ولا يجدونه . فاشكر الرب .","٥ ـ أشكره لأنه يعطيك فرصة الحياة من أجل التوبة : أشكر الله لأنك لازلت فى الحياة ... قال أحد الكتاب كلمة تستحق التسجيل « إن ملايين الملايين من الذين فى الجحيم يشتهون ساعة من حياتك أنت على الأرض » ... على الأقل يتوبون فيها ، يقدمون له اعترافاً وانسحاقاً ويكسبون ملكوت السموات ... أما أنت فعندك حياة طويلة لا تشكر عليها . ولو حلت بك سكتة قلبية تقول يا رب دقيقة واحدة فقط أشكرك عليها ، دقيقة واحدة أتوب فيها ... لا توجد . ضاعت الفرصة وعندما تذهب إلى الجحيم تقول لو كان اعطانى الله دقيقة أقول فيها عبارة المشار ... ولو أقول عبارة اللص اليمين ... ولو أقدم توبته ...!! ملايين الملايين من الذين فى الجحيم يشتهون دقيقة واحدة من عمرك ، ولا يجدون . لو أن الله أخذ منك الروح الآن ، ألا تشتهى هذه الدقائق ، وتتمنى لو أعطاك الله نصف ساعة فقط ! وتقول أعترف فيها بكل شىء بالتفصيل حتى بالذى أخجل منه ، حتى بما لا يقال ، حتى بما يقف على لسانى ... أقوله بدون حرج وآخذ عنه حلاً ... لو أعطانى الله نصف ساعة أتصالح فيها مع من أخاصمهم ، وأعتذر لهم ، وأقدم لهم مائة مطانية ( سجود ) تحت أرجلهم ، حتى لو كانوا هم المخطئين ..."],18:["نصف ساعة يا رب ... لا يوجد ـ أغلق الباب . لماذا إذا لا تشكر الله على الحياة التى لك ؟ ... وعلى هذه الساعات التى مازالت لك فى العمر وتستطيع أن تعمل فيها الكثير ، وتضمن ملكوت السموات ، وتتوب وتحيا حياة روحية ؟ ... ألا تشكر الله إلا إذا نزل لك كنز من السماء ...؟! وما أدراك ـ ربما إذا نزل لك كنز من السماء يكون سبباً فى هلاكك وتفقد الملكوت بسببه .","٦ ـ أشكره لأنه يهيىء لك الحياة فى بيئة مسيحية : هناك أشياء كثيرة تستحق الشكر ، لا نشكر الله عليها . من منكم يشكر الله لأنه موجود الآن فى الكنيسة ؟ كثير من الشبان فى هذه اللحظة فى أماكن اللهو المختلفة وفى خطايا كثيرة ، وأنتم موجودون فى الكنيسة . فمن منكم يشكر الله ؟ لمجرد وجوده حتى لو كان لا يفهم الكلام أو لا ينسجم منه ... أشكر الله على هذا . من منا يشكر الله لأنه أوجد له بيئة مسيحية صالحة من أبوين مباركين لم يمنعاه عن طريق الرب ؟ وهيأ له بيئة مسيحية من خدام فى الكنيسة يعتنون به حتى وصل إلى هذا الوضع من المعرفة الروحية والسلوك الروحى ؟ ... توجد أشياء كثيرة تستلزم الشكر ونحن لا نشكر عليها ."],19:["٧ ـ أشكره لأنه يرعى كل أمور حياتك : يوجد أيضاً عنصر آخر هو إحسانات الله إليك ... الإحسانات الشخصية فى حياتك عموماً وفى حياة أحبائك . كم مرة طلبت من الله طلباً واستجاب ؟ فى ضيقات انتقذك منها ، فى امتحانات أنجحك فيها ، فى مشاكل وفى قضايا كانت نتيجتها فى صالحك ، فى أمراض شفاك منها ، فى ضيقات انتقذك منها ، فى خطايا لم تكتشف أمام الناس ... أريد أن أذكر كم بمثل بسيط ... فى سنة ١٩٤٧ كان مرض الكوليرا منتشراً وكان يحصد بالآلاف . وأغلقت كثير من المدن خوفاً من نقل العدوى وكان الرعب حالاً فى البلاد ... دخلت مرة إحدى هذه المدن المغلقة بتصريح بعد التطعيم ضد الكوليرا طبعاً ، ولم أسمع أحداً يضحك ، ولا يبتسم ، ولم يكن يسمع صوت راديو ولا أغانى ... وكانت المدينة حزينة مكتئبة . وكثيرون صلوا وقالوا « يارب لو أنقذتنى من الكوليرا سأبنى مثل مارجرجس ، مثل الملاك ميخائيل ، مثل الأنبا أنطونيوس أب الآباء » ... وأنقذنا الله من الكوليرا وعشنا إلى الآن ، من منا يشكر الله لأنه نجا من الكوليرا ؟ راحت ونسيت وضاعت ... ومن هذا كثير .","نحن ننسى إحسانات الله ـ وعندما ننساها يقل شكرنا وأيضاً تقل محبتنا . لأنك إذا تذكرت جميل أحد عليك ،"],20:["تحبه . وعندما تنسى هذا الجميل تفقد المحبة . لذلك من التداريب الجميلة أن يجلس الإنسان إلى نفسه وبعد إحسانات الله إليه ... خذ ورقة طويلة واجلس أكتب إحسانات الله إليك منذ ولادتك إلى الآن ، وإحساناته إلى أحبائك ، وعدد الصلوات التى استجيبت فى حياتك ، والخيرات التى أتتك بدون صلوات ـ من الله رأساً ... عدها كلها ، ثم قف واشكر الله على كل أمر واحد فواحد .","٨ ـ أشكره من أجل الفداء العظيم : يوجد أمر أعظم من هذا كله بكثير ولا يقاس إلى جواره آخر ويحتاج إلى شكر ، الليل والنهار ... وهو الخلاص العظيم الذى قدم إلينا على الصليب ... من منا يشكر المسيح لأنه صلب من أجلنا ... ؟ لأنه تجسد من أجلنا وسكب دمه من أجلنا ... ؟ إن حكم الموت الذى وقع على البشرية ، ما كان ممكناً لأحد أن يخلص منه بدون تجسد الإبن وبدون صلبه وموته ... فالإنسان أخطأ إلى الله ... وكانت خطيته غير محدودة لأنها موجهة ضد الله غير محدود ، وعقوبتها غير محدودة . إن قدمت من أجلها كفارة ، فلابد أن تكون كفارة غير محدودة . ولا يوجد غير محدود إلا الله ... فكان لابد أن يتجسد الله وأن يموت عنا ـ والله دفع هذا الثمن ...! لو فرضنا أن الله لم يدفع هذا الثمن ، فماذا تكون النتيجة ؟ كلنا إلى الهلاك الأبدى . ولكن المسيح أنقذنا جميعاً ... من"],21:["منا كل يوم وكل ليلة يذكر صليب المسيح ويشكره لأنه دفع الثمن نيابة عنا ؟ بدون هذا الثمن ماكان ممكناً أن تنفع الأعمال الصالحة ولا التوبة ولا أى شىء ... الله فينا نحن خطاة ، فيما نحن محكوم علينا بالموت ، مات المسيح من أجلنا ونحن فجار . أعطانا خلاصاً لا نستحقه ولم نبذل فيه جهداً ... خلاصاً مجانياً على الصليب « متبررين مجاناً بالنعمة ... » من منا يشكر المسيح على هذا ؟ لقد وضعت لنا الكنيسة أن نذكر هذا الأمر فى مناسبات عديدة حتى لا ننساه ... فى كل سنة تقيم لنا أسبوع الآلام ، أسبوع البصخة ويوم الجمعة العظيمة بذكرياته الجميلة المؤثرة حتى لا ننسى الصليب . فهل يكفى هذا التذكار السنوى ؟ لا يكفى ، لأننا ننسى ... ماذا تعمل الكنيسة ؟ جعلت كل يوم جمعة فى الأسبوع صوماً لنتذكر فيه صليب المسيح لئلا ننسى ... فهل يكفى هذا التذكار الأسبوعى ؟ لا يكفى أيضاً . جعلت لنا الكنيسة صلاة الساعة السادسة من كل نهار وفيها نقول « يا من فى اليوم السادس وفى الساعة السادسة سمرت على الصليب من أجل الخطية ... الخ » لابد أن نتذكر هذا الصليب كل يوم لكى نمتلىء بحياة الشكر ، وفى كل يوم نشكر الله لأنه أعطانا خلاصاً هذا مقداره ... وإلا نكون غير شاعرين بهذا الخير ولم نفهمه ..."],22:["٩ ـ أشكره من أجل عطيته السماوية : من منا يشكر الله لأنه أعطانا هذا الكتاب المقدس ؟ أليست هذه نعمة تستحق الشكر ... !! العالم عاش فى ظلمة الوثنية زمناً طويلاً لم توجد فيه كلمة خلاص واحدة ـ والله أرسل لنا الأنبياء وأرسل لنا الرسل وعلمونا وأفهمونا وتركوا لنا هذه الذخيرة العظيمة ... فى صلاة القداس الغريغورى يقول الكاهن « أعطيتنى علم معرفتك . » ويقول أيضاً « أرسلت لى الناموس عوناً ... » نحن نشكر الله من أجل أنبيائه ومن أجل رسله ومن أجل كتابه المقدس ومن أجل هذا التعاليم . لو عاش الإنسان حياة الشكر ، يشكر الله على كل شىء .","١٠ ـ وأخيراً شكر بلا حدود ... فإنا لا أستطيع مطلقاً أن أحصى إحسانات الله ... أو أن أحصرها ، أو أن أعطيك قائمة بها . إنما ذكرت فقط بعض الأمور الجوهرية التى تنير لنا السبيل . أما أنت لو عشت حياة الشكر ، تستطيع أن تشكر الله عن كل نفس تتنسمه ، على كل خطوة تخطوها ، على التوبة ، على قيامك من سقطتك ، على جميع مواهبه لك ، على روحه القدوس الذى يعمل فيك ، على نعمته التى تفتقدك كلما تسقط وكلما تخطىء ، وتفتقدك فى حالة قوتك لكى تزيدك قوة وتنميك ... تشكر الله على كل حال ومن أجل كل حال ."],23:[{h:"حياة الشكر تستلزم الإتضاع"},"ولكى تشكر جيداً تحتاج فى حياة الشكر إلى الإتضاع والإنسحاق . فالشخص المتضع يشعر أنه لا يستحق شيئاً ... لذلك هو يشكر على كل شىء . لو اعتبرت أنك تستحق أشياء كثيرة ، لأوصلك هذا إلى حياة التذمر والضجر ... لماذا ؟ من أجل الكبرياء وليس من أجل الضيقات الخارجية ! الإنسان فى كبريائه يشعر أنه يستحق أشياء كثيرة ، يستحق حياة أفضل ، فيتذمر على ما هو فيه ... لو كان متضعاً ، لشعر أنه لا يستحق شيئاً ، فكل ما يعطى له من الله مهما كان قليلاً يشكر عليه ، لأنه لا يستحقه . الرجل الفقير الذى تعطيه قرشاً يشكرك عليه لأنه شاعر أنه لا يستحق . ليس له عليك شىء ... فكل ما تعطى له ـ حتى كسرة خبز ـ يشكرك عليها ... فلو كان لك هذا الشعور ـ تقول يارب ليس لى عليك شىء ولا أطالبك بشىء ـ كل شىء من عندك حسن . القليل حسن لأنى لا أستحقه ، والكثير حسن لأنى لا أستحق حتى القليل . فتعيش فى شكر دائم .","يقول القديس مار اسحق عبارة خطيرة ... « الشخص الذى لا يشكر على القليل كاذب هو أن تالَ أنه يشكر على الكثير . الذى لا يشكر على الدرهم ، لا يستطيع أن يشكر"],24:["على الألف دينار » . الشكر عنده غير موجود ... الذى لا يملك الشكر فى طبيعته ، يتذمر لو أعطيته ألف دينار ، ويقول غيرى عنده مليون دينار . تقول له أنت أصبحت وزيراً ، يقول ولماذا لا أصير رئيس وزراء ...! لا يوجد شكر بالمرة . من الذى يشكر ؟ ... الشخص المتضع الذى يشعر أنه لا يستحق شيئاً على الإطلاق . فكل ما يعطى له من الله يشكر عليه . والمتضع لا يشعر فقط أنه لا يستحق شيئاً من الخير ـ بل أكثر من هذا يشعر أنه يستحق عقوبات كثيرة وتأديبات عنيفة ... ولو أعطيت له جميع البلايا يشكر ، ويقول أنا أستحق بلايا أكثر من هذه لأنى إنسان خاطىء . إنها لرأفة عظيمة من الله أن يعطينى هذه فقط ... مثال لذلك أن مجرماً ارتكب جرائم مرعبة ، وحكم عليه القاضى بالأشغال الشاقة المؤبدة ، فصرخ فى المحكمة وقال له أشكرك ... ! لماذا ؟ « لأنى أستحق الإعدام ! يا لك من قاض رحيم وحنون ... إن هذا المجرم شاعر بخطيئته ، ويعرف أن جريمته تستحق الإعدام . إنه يذهب إلى المحامى أيضاً ويشد على يده فى حرارة ، ويقول له « أشكرك يا أستاذ على المجهود الكبير الذى بذلته من أجلى ، وجعلتنى أصل إلى الأشغال الشاقة المؤبدة ... كانت رأسى فى المشنقة وأنت أنقذتنى ...! » هكذا يكون الإنسان المتضع : كلما"],25:["تأتيه بلية ، يقول أشكرك يارب . أشكرك لأنك حنون جداً وتعطينى عقوبات خفيفة للغاية ... يا لشفقتك العجيبة ... ! حقاً يارب ، إن يدك علىّ لا عصاك .","قد تعترض وتقول : نفرض أن الله أعطى له ضيقة لا تحتمل ، مرضاً من الأمراض المؤلمة التى لا تحتمل ، فكيف يشكر الله ولا توجد ضيقة أعظم من هذه ؟ إنه يجيب « لا ـ هناك توجد البحيرة المتقدة بالنار والكبريت . فإن كنت آخذ عذابات على الأرض لا تحتمل ، فهذا أفضل من العذاب الأبدى الذى لا يحتمل » ... فالإنسان المتضع هو الإنسان الشاكر ."],26:[{h:"خاتمـة"},"إن حياة الشكر تحتاج إذن إلى إيمان بالله ، وإلى الغرض الواحد ، أعنى ألا يكون للإنسان هدف سوى محبة الله فقط والإلتصاق به ، لذلك لا يهتم بأى شىء آخر بل يشكر على كل شىء . وحياة الشكر تحتاج إلى ذاكرة لا تنسى إحسانات الله ، وتحتاج إلى اتضاع وإلى محبة . لو كانت بينك وبين الله محبة ، تشكره على كل شىء ، تشعر أن كل شىء هو من يده المملوءة حناناً ومن قلبه المملوء محبة ... فتبقى سعيداً به . حياة الشكر تصل بالإنسان إلى حياة السلام والفرح ، ولا شىء ينزع فرحه منه .","ولله المجد دائماً أبدياً آمين ..."]}},wars_demons:{id:"wars_demons",title:"حروب الشياطين",author:"قداسة البابا شنوده الثالث",url:"https://drive.google.com/file/d/1rEOeeeiVHXZtaT12cQtKr6STTb5JmAJR/view",file:"حروب_الشياطين.pdf",pageOffset:1,review:{status:"needs-review",note:"نُقل الكتاب كله (من ص٨ إلى ص١١٨ بالترقيم المطبوع، أي المتن بفصوله الخمسة بلا الغلاف والفهرس) بقراءة صفحات الكتاب الممسوحة بالنظر وبنفس إملاء الطباعة (بما فيها أخطاؤها الطباعية)؛ يحتاج مطابقة نهائية مع الأصل. عناوين الفصول الرابع والخامس قُرئت من صفحات عنوان مطبوعة بخط مزخرف."},chapters:[{title:"الفصل الأول: طبيعة حروب الشياطين",from:7,to:13},{title:"الفصل الثاني: صفات الشيطان في حروبه",from:14,to:31},{title:"الفصل الثالث: حيل الشيطان",from:32,to:89},{title:"الفصل الرابع: كيفية الإنتصار على حروب الشياطين",from:90,to:113},{title:"الفصل الخامس: فوائد الحروب الروحية",from:114,to:117}],transcribed:[7,117],pages:{7:["الحروب الروحية سمح بها الله لفائدتنا ... ووراءها أكاليل . وعلى رأى أحد القديسين الذى قال :",{h:"لا يكلل إلا الذى انتصر . ولا ينتصر إلا الذى حارب ."},"فهى من جهة الله إختبار لحرية إرادتنا ، وإعطاؤنا الفرصة التى نستحق بها خيرات الملكوت ، إذا انتصرنا... أما من جهة الشيطان ، فمن طبيعته أن يقاوم ملكوت الله ، ويحارب الساعين إليه . وهو يحارب الله فى شخص أولاده . ويشتكى عليهم كما حدث فى قصة أيوب الصديق (أى ١ ، ٢) . وهو يحسد السالكين فى حياة البر ، لكى لا ينالوا البركة الإلهية التى حُرم هو منها .",{h:"وحروب الشياطين هى ضد الكل ، لم ينجُ منها أحد ."},"ونحن حينما نتكلم عن هذه الحروب ، إنما نقصد الحرب التى يثيرها الشيطان وكل جنوده وأعوانه .","منذ أيام آدم وحواء وإبنها قايين ، والشيطان قائم يحارب ، يحاول بكل جهده أن يلقى البشرية تحت حكم الموت الأبدى . وقد أسقط أنبياء ورسلاً ، وأشخاصاً حلّ عليهم روح الرب مثل داود وشمشون اللذين تابا ، ومثل شاول الملك الذى رفضه الرب ، وفارقه روح الله « وبغته روح ردىء من قبل الرب » (١صم ١٦ : ١٤) .",{h:"فلا تظنوا أن حروب الشياطين هى للمبتدئين فقط أو للخطاة ."},"كلا ، فهو يحارب الكل ، مهما كانوا نامين فى النعمة ، بل يحارب هؤلاء بالأكثر . لذلك على كل إنسان أن يحترس ، وأن لا يظن بأنه قد ارتفع فوق مستوى حروب معينة . ولنتذكر أن معلمنا داود النبى حورب بخطية زنا وسقط فيها ، مع أنه كان قد حلّ عليه روح الرب وصار مسيحاً له... إن الشيطان يريد أية فريسة .","وقد وصفه القديس بطرس الرسول بعبارة خطيرة قال فيها :","« إبليس خصمكم كأسد زائر ، يجول ملتمساً من يبتلعه هو » (١بط ٥ : ٨) ."],8:["وهو دائم الجولان لصيد فرائسه . ولما سأله الرب (فى قصة أيوب) « من أين جئت ؟ » أجاب فى صراحة « من الجولان فى الأرض ومن التمشى فيها » (أى ١ : ٧ ، ٢ : ٢) . وطبعاً الغرض من هذا الجولان هو البحث عن أية فريسة يسقطها...",{h:"والشيطان لا ييأس ، مهما كان الذى يحاربه قوياً ."},"بل قيل عن الخطية إنها « طرحت كثيرين جرحى ، وكل قتلاها أقوياء » (أم ٧ : ٢٦) . والشيطان لم يتورع عن محاربة حتى رسل المسيح الإثنى عشر. وقد قال الرب فى ذلك للقديس بطرس الرسول « هوذا الشيطان طلبكم لكى يغربلكم كالحنطة . ولكنى طلبت من أجلك لكى لا يفنى إيمانك » (لو ٢٢ : ٣١ ، ٣٢) . ولنتذكر أن إيليا النبى العظيم الذى أصعده الله إلى السماء ، قال عنه القديس يعقوب الرسول « إيليا كان إنساناً تحت الآلام مثلنا » (يع ٥ : ١٧) .","بل إن الشيطان تجرأ أن يجرب السيد المسيح نفسه .","فقدم له ثلاث تجارب على الجبل (متى ٤) . ولم يثنه عن ذلك كل الذى كان يعرفه عن المسيح . ولم تثنه الإعلانات الإلهية التى سبقت ذلك وقت العماد (متى ٣ : ١٣ - ١٧) . بل حاربه طوال الأربعين يوماً (مر ١ : ١٣ ، لو ٤ : ٢) .","وقيل عن السيد المسيح إنه « كان مجرباً فى كل شىء مثلنا ، بلا خطية » (عب ٤ : ١٥) . وإنه « فيما هو قد تألم مجرباً يقدر أن يعين المجربين » (عب ٢ : ١٨) .","حقاً إن تجارب المسيح من الشيطان عزاء لنا فى كل تجاربنا... إن حلّت بك تجربة فلا تتضايق ، إن المسيح قد جرب من قبلك ، وكما انتصر المسيح سوف تنتصر أنت أيضاً .",{h:"إن حروب الشياطين موجهة ضد الله نفسه وضد ملكوته ، وضد هياكله المقدسة التى هى نحن ."},"فهو يريد أن يقاوم هذا الملكوت بكافة الطرق . ويفرح إن أمكنه أن يسقط « حتى المختارين أيضاً » (متى ٢٤ : ٢٤) .","وإن كانت ملائكة السماء تفرح بخاطىء واحد يتوب (لو ١٥ : ١٠) ، فلا شك أن الشياطين تفرح ببار واحد إذا سقط ، بل تفرح بسقوط أى أحد يخضع لهم .","والقديس بولس الرسول ، يشرح هذه الحروب الروحية فيقول :"],9:["« إلبسوا سلاح الله الكامل ، لكى تقدروا أن تثبتوا ضد مكايد إبليس . فإن مصارعتنا ليست مع دم ولحم ، بل مع الرؤساء مع السلاطين ... مع أجناد الشر الروحية فى السماويات ... » (أف ٦ : ١١ ، ١٢) .","وشرح كيف أن هذه الحروب الروحية تحتاج إلى أسلحة روحية لمقاومتها ، ذكرها الرسول فى نفس الأصحاح بالتفصيل... ولابد لها من معونة الله ، الذى قال « بدونى لا تقدرون أن تفعلوا شيئاً » (يو ١٥ : ٥) . وفى هذه الحرب الروحية ما أجمل أن نتذكر قول داود النبى « الحرب للرب » (١صم ١٧ : ٤٧) .",{h:"والحروب الروحية حروب دائمة . قد تتنوع ، ولكن لا تنتهى ."},"طالما أنت فى الجسد ، فأنت معرض لهذه الحروب ، التى تظل معك حتى الموت . ولذلك قال القديس بطرس الرسول « سيروا زمان غربتكم بخوف » (١بط ١ : ١٧) . ولا يقصد بالخوف ، الرعب من الشياطين... إنما الخوف الذى يدعو إلى الحرص والتدقيق .","بالنسبة إلى الفرد ، الحرب تستمر حتى الموت . وبالنسبة إلى العالم ، تستمر مدى الدهر ، إلى نهاية العالم . حتى أن الشيطان حينما يُحل من سجنه ، يخرج ليضل الأمم (رؤ ٢٠ : ٧ ، ٨) . وفى نهاية الأيام سيكون هناك ارتداد عن الإيمان (١تى ٤ : ١) ، « وستأتى أزمنة صعبة » (٢تى ٣ : ١) . وقبل مجىء المسيح سيكون الإرتداد العام (٢تس ٢ : ٣) . وسيبذل الشيطان كل جهده ، وسينزل إلى الأرض « وبه غضب عظيم ، عالماً أن له زماناً قليلاً بعد » (رؤ ١٢ : ١٢) .",{h:"والحرب الدائمة التى للشيطان قد تشتد فى الأوقات المقدسة ."},"فالشيطان يتضايق جداً ، حينما نبدأ فى أى عمل روحى . ويسعى بكل الحيل لئلا تفلت الفريسة من يده . فنحن نبدأ العمل الروحى ، ويبدأ هو معنا حروبه وحيله ومعطلاته الكثيرة .",{h:"فنحن نبدأ العمل الروحى ، وهو يبدأ المقاومة ."},"لأنه لا يستريح لأية صلة لنا مع الله . يظن أن هذه تهدد ملكه بالضياع . ومن العبارات الجميلة فى بستان الرهبان : إنه عندما يدق جرس الصلاة فى نصف الليل ، فإنه لا يوقظ الرهبان فقط للصلاة و إنما أيضاً يوقظ الشياطين لكى يحاربوا الرهبان"],10:["ويمنعوهم عن الصلاة... ولذلك قال القديس مارأوغريس :",{h:"إذا بدأت الصلاة الطاهرة ، فاستعد لكل ما يأتى عليك ."},"إننا إذا بدأنا فى الوسائط الروحية أياً كانت ، سواء فى عمل الصلاة ، أو التأمل ، أو التسبيح ، أو القراءات الروحية ، أو المطانيات... فإن الشيطان لا يقف مكتوف اليدين أو متفرجاً ، إنما يعمل هو أيضاً عمله ، وله أنواع حروب يحارب بها . وما أصدق قول الكتاب فى سفر يشوع بن سيراخ :",{h:"يا إبنى ، إن تقدمت لخدمة ربك ، فهيىء نفسك لجميع التجارب ."},"وهذه الآية نقولها ضمن فصل نتلوه فى سيامة الراهب الجديد . كما إنها إحدى قراءات الساعة الثالثة من يوم الثلاثاء من البصخة المقدسة . فالذين يستعدون لقتال الشيطان ، من الطبيعى أن يستعد الشيطان أيضاً لقتالهم . لذلك لا تتعجبوا للحروب التى تصاحب العمل الروحى... وحذار أن تجعلكم هذه الحروب تتراجعون... بل اثبتوا فى قوة ، مهما نالكم من تعب ، متذكرين قول القديس بولس الرسول « كونوا راسخين ، غير متزعزعين ، مكثرين فى عمل الرب كل حين ، عالمين أن تعبكم ليس باطلاً فى الرب » (١كو ١٥ : ٥٨) .",{h:"نحن نبدأ الجهاد ، وهو يبدأ الحرب . نبدأ الروحيات ، فيبدأ المقاومة ."},"الشيطان مثلاً يتضايق من الصوم ، لأنك فيه تريد أن تقمع جسدك وتستعبده (١كو ٩ : ٢٧) ، لكى ترتفع روحك وتلتقى بالله... والشيطان لا يقبل هذا . كما أنه يتضايق من الصوم الكبير بصفة خاصة ، لأن الناس يسلكون فيه بنسك شديد ، كما أن هذا الصوم يذكّر الشيطان بصوم السيد المسيح وكيف قهر الشيطان فيه (متى ٤) . لذلك يجاهد الشيطان أن يعرقل هذا الصوم ، أو أن يثير فيه مشاكل ، حتى ينشغل الناس بالمشاكل ، ويتركوا العمل الروحى .","ولهذا فالبعض يربطون بين هذا الصوم ، والمشاكل والتجارب .",{h:"ولا شك أن العمل الروحى يثير حسد الشياطين ..."},"إن الشيطان يحسد الإنسان الروحى على صلته بالله ، التى حُرم هو منها . ويحسده لأنه هو إنسان ترابى مرتبط بجسد ، يحاول أن يجعل روحه تسمو وتعلو ، بينما الشيطان وهو روح (متى ١٢ : ٤٥) بعيد عن الله ، وروحه روح نجسة (مر ١ : ٢٧) !","ومنذ البدء حسد الشيطان أبوينا آدم وحواء وأوقعها فى الخطية وفى حكم الموت ."],11:["وهكذا نقول فى صلوات القداس الإلهى « والموت الذى دخل إلى العالم بحسد إبليس » .",{h:"والشيطان لا يحسد إلا الناجحين فى عملهم الروحى ."},"يحسد المقتربين إلى الله ، والذين لهم دالة عنده . ويحسد التائبين فى حرارة التوبة ، والعابدين وهم فى عمق الصلة . ويحسد المتضعين والودعاء والأنقياء . ويحارب كل هؤلاء . أما الخاضعون له وللخطية ، والفاترون فى حياتهم الروحية . فلماذا يحاربهم ؟! يكفيهم ما هم فيه . أو إنه يضعهم تحت المراقبة ، أو يورطهم فى حالة أسوأ .",{h:"وهنا نذكر بعض أنواع من الحروب الروحية ."},"ونذكر هنا ثلاثة أنواع رئيسية وهى :","أ ـ حالة إنسان يحاربه الشيطان حرباً خفيفة أو ثقيلة .","ب ـ إنسان تحاربه شهواته من داخل . ربما الشيطان قد وضع نقطة البدء ، ثم ترك هذه الفريسة المسكينة يحاربها فسادها الداخلى ، أو تحاربها عاداتها المتوطنة فيها ، المسيطرة عليها . هناك إنسان يحارب من جسده ومن غرائزه ، وآخر يحارب من نفسه أو من فكره .","ج ـ أما الحالة الثالثة فهى لإنسان يحاربه إخوة كذبة ، أو أناس أشرار ، أو بيئة شريرة تحيط به ، ويمكن أن نسميهم جميعاً « أعوان الشياطين » و « كل جنده » ...","ولهذا تعلمنا الكنيسة أن نصلى فى آخر صلاة الشكر ونقول : كل حسد ، وكل تجربة ، وكل فعل الشيطان ، ومؤامرة الناس الأشرار ، وقيام الأعداء الخفيين والظاهرين... إنزعها عنا وعن سائر شعبك... » .",{h:"وهناك نوع يمكن أن نسميه إمتحاناً أو إختباراً ، وليس حرباً ."},"وكمثال لهذا يقول الكتاب « وحدث ... أن الله إمتحن إبراهيم . وقال له ... خذ إبنك وحيدك الذى تحبه إسحق ... وأصعده ... محرقة ... » (تك ٢٢ : ١ ، ٢) . وهنا لم يكن الله يحارب أبانا إبراهيم ، حاشا... بل كان يمتحن قلبه ليرى عمق محبته له وعمق طاعته... ونجح أبونا إبراهيم فى هذا الإختبار...",{h:"القديس والخاطىء كلاهما معرضان للحرب . ولكن ما الفرق بينها ؟"}],12:["الفرق الأساسى هو أن القديس له حرب من الخارج فقط . أما داخله فإنه نقى ، لا يتفق مع الحرب الخارجية بل يرفضها ويقاوم بكل قوته لكى ينتصر عليها .","أما عن الخاطىء أو الشرير فقد تكون الحرب بالنسبة إليه مزدوجة ، من الخارج ومن الداخل معاً . تحاربه إغراءات الشيطان من الخارج ، وتحاربه شهواته من داخل قلبه وفكره . لذلك هو يستسلم لحرب الشيطان ، ويفتح له أبوابه الداخلية . ويقبل أفكاره ومقترحاته مرحباً بها . وإن قاوم ـ لبقية ضمير فيه ـ فإنها تكون مقاومة هزيلة لا تستمر طويلاً ، ولا تكون جادة فى صد أفكار العدو الخارجى .","وحروب القديسين تظهر فيها قوتهم وانتصارهم . أما الخطاة فينهزمون ...",{h:"وقد يسمح الله أحياناً بانهزام القديسين ، مؤقتاً ، لفائدتهم ..."},"فالإنسان المنتصر على طول الخط ، ربما تحاربه الكبرياء ، ويظن فى نفسه أنه شىء !! لذلك سمح الله أحياناً أن ينهزم القديسون ، لكى تنسحق قلوبهم من الداخل ، ويعيشوا فى اتضاع . ولكى يعرفوا قوة العدو وقسوته فى الحروب ، فيشفقوا على أخوتهم المحاربين . وكما قال القديس بولس الرسول :",{h:"« أذكروا المقيدين كأنكم مقيدون معهم . و ( اذكروا ) المذلين كأنكم أنتم أيضاً فى الجسد » (عب ١٣ : ٣) ."},"إن الإنسان الذى لم يجرب بحروب الشياطين ، ربما يدين الذين يسقطون أو يحتقرهم ، بعكس الذى قاسى وتعب ، فإنه يحن عليهم ويشفق ، ويصلى لأجل خلاصهم . وكما قال الرسول « عالمين أن نفس هذه الآلام تجرى على أخوتكم الذين فى العالم » (١بط ٥ : ٩) ... حقاً ما أرهب قول الكتاب فى سفر الرؤيا عن الوحش :",{h:"« وأعطى أن يصنع حرباً مع القديسين ويغلبهم » (رؤ ١٣ : ٧) ."},"بل ما أرهب أيضاً ما قيل بعد ذلك « وأعطى سلطاناً على كل قبيلة ولسان وأمة . فسيسجد له جميع الساكنين على الأرض... » (رؤ ١٣ : ٧ ، ٨) . ولكن لئلا ييأس البعض من ذلك ، ذكر أن هؤلاء الساجدين هم : الذين ليست أسماؤهم مكتوبة منذ تأسيس العالم فى سفر الحياة... أى أبناء الهلاك... ومع ذلك هم عدد كبير بلا شك يدل على عنف حرب الشيطان وجنوده... ومما يعزينا فى ذلك أيضاً ، أن الوحش هو والشيطان مُطرحان فى بحيرة النار والكبريت (رؤ ٢٠ : ١٠)..."],13:[{h:"ولكننا ذكرنا كل هذا ، لكى يكون لدينا حرص ."},"مادام عدونا بهذه الوحشية ، فلنستمع إذن إلى قول الرسول « أنظروا كيف تسلكون بتدقيق ، لا كجهلاء بل كحكماء ، مفتدين الوقت لأن الأيام شريرة » (أف ٥ : ١٥ ، ١٦) . إنتصارات الشيطان لا تدفعنا إلى الخوف ، بل إلى الحرص والتدقيق . وأيضاً تدفعنا إلى عدم الإعتماد على أنفسنا ، وإنما :",{h:"فى حروبنا نلتصق بالرب ، لأن من عنده المعونة والنصرة ."},"هو الذى يحارب الشيطان فينا ، وهو الذى يغلب العالم فينا . أليس هو القائل « ثقوا ، أنا قد غلبت العالم » (يو ١٥ : ٣٣) . نعم غلب العالم فى حرب الشيطان معه . ويغلب العالم الآن وكل أوان ، فى حربه معنا . وكذلك :",{h:"« شكراً لله ، الذى يقودنا فى موكب نصرته » (٢كو ٢ : ١٤) ."},"إنه انتصر على الشيطان فى طبيعتنا البشرية . فقدّس هذه الطبيعة وباركها ، وأعطاها روح النصرة . وهكذا نقول له فى القداس الغريغورى « باركت طبيعتى فيك » ... لقد انتصر الشيطان من قبل ، على هذه الطبيعة البشرية . ولكن السيد المسيح أعاد إلى هذه الطبيعة البشرية صورتها الإلهية ، وهيبتها فى نظر الشياطين ، حينما هزم الشيطان فيها .",{h:"فلم يعد الشيطان يرى أن هذه الطبيعة هى لعبته ، ينتصر عليها متى يشاء... وإذ انهزم أمامها ، بدأ يخشاها..."},"وبهذا أيضاً أنقذنا من روح الفشل ، وأعطانا قوة من عنده فى حروب الشياطين لنا . وأصبح لنا الرجاء كل حين ، أن المسيح يغلب الشيطان فينا ، حينما « يحل المسيح بالإيمان فى قلوبنا » (أف ٣ : ١٧) .","وبسبب هذا نحن لا نتضايق من حروب الشياطين ، مادامت يد الرب تكون معنا فيها ، ويحارب عنا وينصرنا...",{h:"الله لا يمنع عنا حروب الشياطين ، إنما ينصرنا فيها ."},"هو الذى يحارب عنا ، وهو الذى يغلب الشياطين . وبعد ذلك يكللنا ، لأننا سلمناه إرادتنا أثناء حربه عنا ضد الشياطين .","هذه مقدمة بسيطة ننتقل بعدها إلى الحديث عن الشيطان وحيله..."],14:[{h:"الفصل الثانى"},{h:"صفات الشيطان فى حروبه"}],15:[{h:"ينبغى أن نعرف صفات عدونا ، وأسلوبه فى القتال ، لنعرف كيف نحاربه ."},"فما هى صفات الشيطان ؟ وكيف يحارب ؟ وهل له أسلوب ثابت ، أم أنه يتغير فى أساليبه حسب تغير الحالة ؟ هذا ما نريد أن نفحصه ، حتى نستطيع أن نواجهه . وكما قال بولس الرسول « لئلا يطمع فينا الشيطان . لأننا لا نجهل أفكاره » (٢كو ٢ : ١١) .","ونستطيع أن نعرف مما رواه لنا الكتاب عن الشيطان أنه :",{h:"١ ـ صاحب قتال لا يهدأ"},"صار عمله منذ سقوطه هو المقاتلة والمحاربة . فهو دائماً مقاتل fighter حتى قبل إسقاطه لأبوينا الأولين آدم وحواء ، إستطاع أن يُسقط مجموعات من ملائكة السماء ، تبعوه وصاروا من جنده من طغمات كثيرة .",{h:"ومن ذلك الحين أصبحت هوايته إسقاط الآخرين ."},"صار يقاتل الكل . وكما أسقط طغمات ملائكية من الكاروبيم والسلاطين والرؤساء والقوات... كذلك رأيناه يقاتل أنبياء الله ورسله ومسحاءه ، ويقاتل المتوحدين والسواح والرهبان وكل محبى الله ، وكل من يسمع أنه فى خير ، أو فى برّ .","وقد سمى المعاند والمقاوم ، لأنه دائماً يقاوم ملكوت الله و يعاند مشيئته . كما سمى أيضاً التنين ، والحية القديمة ، وإبليس ، والشيطان (رؤ ١٢ : ٩) ، وقبل الصليب كان يسمى رئيس هذا العالم (يو ١٤ : ٣٠) .",{h:"وهو فى قتاله لا يهدأ مطلقاً ولا يملّ ولا يستريح ."},"دائماً « يجول كأسد يزأر » (١بط ٥ : ٨) . وقد قال للرب مرتين فى قصة أيوب إنه مشغول « بالجولان فى الأرض والتمشى فيها » (أى ١ : ٧ ، ٢ : ٢) . إنه ساهر"],16:["باستمرار يرقب حالة ضحاياه ، ويلقى بذاره فى كل مكان . وحيثما يزرع الرب حنطة ، يأتى هو « ويزرع زواناً وسط الحنطة ، فيما الناس نيام » (متى ١٣ : ٢٥) .",{h:"وليس البشر فقط ، بل حتى الملائكة يحاربهم ."},"فقد وقف ضد الملاك ميخائيل يحاججه من جهة جسد موسى النبى (يه ٩) . ووقف ضد أحد الأرباب الذى عمل على أن ينقذ منه يهوشع الكاهن (زك ٣ : ١ ، ٢) . كذلك وقف واحداً وعشرين يوماً ضد الملاك الذى أرسله الرب لدانيال النبى ، لولا تدخل رئيس الملائكة ميخائيل لإعانته (دا ١٠ : ١٢ ، ١٣) . بل ما أعجب قول الإعلان الإلهى فى سفر الرؤيا :","وحدثت حرب فى السماء : ميخائيل وملائكته حاربوا التنين ... وملائكته (رؤ ١٢ : ٧) . إنه يحارب فى الأرض وفى السماء ، مع أن كل حروبه تنتهى أخيراً إلى هلاكه وهزيمته ولكنه لا يستطيع أن يبطل الحرب ، لأنها صارت جزءاً من طبيعته .","ومن صفات الشيطان أيضاً أنه قوى .",{h:"٢ ـ قوى"},"لأنه أحد الملائكة « المقتدرين قوة » حسبما وصفهم المرتل (مز ١٠٣ : ٢٠) .",{h:"هو كملاك فقد طهارته ، لكن لم يفقد طبيعته القوية ."},"لذلك وصفه الرسول بأنه « أسد زائر » (١بط ٥ : ٨) . وهكذا نراه فى سفر أيوب إستطاع أن « يضرب به بقرح ردىء من باطن قدمه إلى هامته » (أى ٢ : ٧) ، كما إستطاع أن يثير ريحاً شديدة صدمت زوايا بيت أيوب ، فسقط على الغلمان فماتوا (أى ١ : ١٩)... وهناك دلائل روحية كثيرة على قوته ، منها :",{h:"إنه استطاع أن يضل العالم كله أيام الطوفان ."},"ولم تنجُ من ضلاله سوى أسرة واحدة هى أسرة أبينا نوح (تك ٦) . ورأى الله أن الحل الوحيد لتطهير الأرض من الفساد ، هو إبادة كل نفس حية على وجه الأرض .",{h:"ونفس الوضع نقوله عن مدينة سادوم ."},"فلم يجد الله فيها عشرة من الأبرار ، حتى يرحم المدينة من أجل العشرة (تك ١٨ : ٣٢) . ولم يوجد فيها سوى أسرة لوط فقط (أربعة أشخاص) . هلكت من بينهم إمرأة"],17:["لوط خارج المدينة . وأخطأت البنتان بعد خروجها من سادوم . ولوط نفسه قيل عنه حينما كان فى سادوم إنه « كان بالنظر والسمع ـ وهو ساكن بينهم ـ يعذب يوماً فيوماً نفسه البارة بالأفعال الأثيمة » (٢بط ٢ : ٨) .",{h:"وقوة الشيطان تظهر فى إلقائه العالم كله فى الوثنية ."},"كيف استطاع أن يلقى العالم كله فى الوثنية فى العهد القديم ، ماعدا شعباً واحداً ؟! هذا أمر خطير . بل حتى هذا الشعب الواحد وقع فى عبادة الأصنام هو أيضاً ، حينما كان موسى النبى على الجبل ، إذ صنعوا لأنفسهم عجلاً ذهبياً ، وقدموا له الذبائح . وقالوا « هذه آلهتك يا إسرائيل التى أصعدتك من أرض مصر » (خر ٣٢ : ١ ـ ٦) .","وفى أيام إيليا النبى فى عهد آخاب الملك ، كان فى شعب الله ٤٥٠ نبياً للبعل ، و ٤٠٠ نبياً للسوارى أى ثمانمائة وخمسون نبياً كاذباً كانوا يأكلون على مائدة الملكة إيزابل (١مل ١٨ : ١٩) . وحدث أن كثيراً من ملوك يهوذا وإسرائيل وقعوا فى عبادة الأصنام « وجعلوا إسرائيل يخطىء » كما تروى لنا أسفار الملوك وأخبار الأيام .",{h:"ومن قوة الشيطان إسقاطه لسليمان الحكيم فى عبادة الأصنام ."},"سليمان أحكم أهل الأرض ، الذى أخذ الحكمة من الله نفسه (١مل ٣ : ١٢) ، الذى تراءى له الله مرتين (١مل ٣ : ٥ ، ٩ : ٢) . يقول عنه الكتاب « وكان فى زمان شيخوخة سليمان ، أن نساءه أملن قلبه وراء آلهة أخرى ... فذهب سليمان وراء عشتاروت إلهة الصيدونيين وملكوم رجس العمونيين » (١مل ١١ : ٤ ـ ٨) .","حقاً إنها لمأساة عجيبة وخطيرة ، ترينا مدى قوة الشيطان .",{h:"ومن دلائل قوة الشيطان ما سيفعله فى آخر الأيام ."},"وذلك عندما « يُحل من سجنه » ، ويخرج ليضل الأمم الذين فى أربع زوايا الأرض (رؤ ٢٠ : ٧) . بل يضل لو أمكن المختارين أيضاً عن طريق من يرسلهم من مسحاء كذبة وأنبياء كذبة ، يعطون آيات عظيمة وعجائب (متى ٢٤ : ٢٤) . ومن خطورة عمله العنيف فى تلك الفترة الصعبة قول الرب عنها :",{h:"ولو لم تقصّر تلك الأيام ، لم يخلص جسد » (متى ٢٤ : ٢٢) ، « ولكن لأجل المختارين تقصر تلك الأيام » . وفى تلك الأيام سيرسل الشيطان أيضاً من عنده ضد"}],18:["المسيح ، إنسان الخطية المقاوم والمرتفع على كل ما يدعى إلهاً « الذى مجيئه بعمل الشيطان ، بكل قوة و بآيات وعجائب كاذبة ، وبكل خديعة الإثم فى الهالكين » (٢تس ٢ : ٩ ، ١٠) .",{h:"ومن نتائج قوة الشيطان هذه ، يحدث الإرتداد العام ."},"وذلك قبيل مجىء المسيح (٢تس ٢ : ٣) . ولكن نشكر الله الذى سيقصر تلك الأيام الصعبة . وسيبيد هذا الأثيم (ضد المسيح) بنفخة فه ، ويبطله بظهور مجيئه (٢تس ٢ : ٨) ... إلى هذا الحد وصلت قوة الشيطان .",{h:"ومن أمثلة قوة الشيطان أيضاً :"},"إنه استطاع أن يتكلم على فم رسول عظيم كبطرس ، فانتهره الرب قائلاً « إذهب عنى يا شيطان . أنت معثرة لى » (متى ١٦ : ٢٢ ، ٢٣) .","ومن أمثلة ذلك أيضاً أنه غربل الإثنى عشر رسولاً . وقد طلب الرب من أجل بطرس لكى لا يفنى إيمانه (لو ٢٢ : ٢١ ، ٣٢) .","ومن أمثلة قوته أنه أسقط جبابرة مثل داود وشمشون ، وأهلك نبياً كبلعام ، وضيع تلميذاً من تلاميذ بولس كديماس ... « وكل قتلاه أقوياء » (أم ٧ : ٢٦) . حقاً كما قال داود النبى « كيف سقط الجبابرة ، و بادت آلات الحرب » (٢صم ١ : ٢٧) .",{h:"ومن أمثلة قوته أيضاً صرعه لأناس كثيرين ."},"هؤلاء الذين احتاجوا أن يخرج الشيطان منهم ، وقيل إنه كانت عليهم أرواح نجسة . وعنهم قال الرب لتلاميذه « إخرجوا شياطين » (متى ١٠ : ٨) . وكان على واحد من المرضى فرقة من الشياطين « لجئون » (مر ٥ : ٩) ، « ولم يقدر أحد أن يذلله » . وبعض هذه الشياطين لم يقدر تلاميذ الرب وقتذاك على إخراجها . فقال لهم الرب « هذا الجنس لا يمكن أن يخرج بشىء إلا بالصلاة والصوم » (مر ٩ : ٢٩) .",{h:"ولعله بسبب قوة الشيطان ، قيده الله ألف سنة ."},"« وطرحه فى الهاوية ، وأغلق عليه وختم عليه ، لكى لا يضل الأمم فى ما بعد ، حتى تتم الألف سنة . وبعد ذلك لا بد أن يُحلّ زماناً يسيراً » (رؤ ٢٠ : ٢ ، ٣) .",{h:"ولكن ليس معنى الحديث عن قوة الشيطان ، أن تخافوا منه !! كلا ."}],19:[{h:"فإن كان الشيطان قوياً ، فالله أقوى منه ..."},"وليس فقط أن الله أخضعه لنا ، بل إن كثيراً من الآباء قد غلبوه ، وكان يخاف منهم . وسنتحدث عن هذه النقطة فى حينها بمشيئة الرب .","نقطة أخرى مهمة فى صفات الشيطان كمحارب لنا ، وهى أنه :",{h:"٣ ـ خبير بالحروب وبنا"},"تصوروا الشيطان يحارب الإنسان منذ أكثر من سبعة آلاف سنة ، منذ آدم ... أية خبرة تكون له فى حربه مع البشرية . لا شك أنه أقدر مخلوق على فهم النفس البشرية وطريقة محاربتها . لقد درس النفس البشرية جيداً ، ويعرف نواحى القوة والضعف فيها . و يعرف الأسلوب الذى يمكنه أن يحاربها به .",{h:"أكبر عالم نفسانى ، وأكبر محلل نفسانى ، هو الشيطان ..."},"علم النفس عنده ، ليس مجرد نظريات ، إنما هو خبرات ، على المستوى العملى والعلمى أيضاً ، وبنطاق واسع جداً ، شمل البشرية كلها . لذلك هو يعرف متى يحارب ، وكيف يحارب ؟ ومتى ينتظر ؟ ومن أى الأبواب يدخل إلى الفكر أو إلى القلب ... ؟","من صفات الشيطان الأخرى التى تظهر فى حروبه أنه :",{h:"٤ ـ ذكى وصاحب حيلة"},"لقب الشيطان بأنه « الحية القديمة » (رؤ ٢٠ : ٢ ، ١٢ : ٩) . وقال الكتاب عن الحية إنها كانت « أحيل حيوانات البرية » (تك ٣ : ١) . إنه ذكى وحكيم فى الشر . وقد قال الكتاب « كونوا حكماء كالحيات » (متى ١٠ : ١٦) . وحكمة الشيطان كلها خبث ومكر وحيلة ...","ومن مظاهر ذكاء الشيطان أنه قد يغير خطته وأساليبه لتوافق الظروف . ومن حيله الصعبة : الكذب والخداع والأضاليل ، يسبكها بطريقة ذكية لا يشعر بها الإنسان المحارب ، أو أنه يقدم الخطية فى أسلوب فضيلة ... الخ . ما أكثر حيل الشيطان . إننا سنفرد"],20:["لها فصلاً خاصاً فى هذا الكتاب ، قد يكون الفصل الأساسى فيه .","ومن الصفات البارزة فى حروب الشيطان أنه :",{h:"٥ ـ كذاب"},"لقد كذب على أبوينا آدم وحواء حينما قال لها « لن تموتا » وكذلك فى قوله لها « تصيران مثل الله ... » (تك ٣ : ٤ ، ٥) . وصفة كذاب بارزة فى الشيطان ، لذلك قال عنه السيد الرب إنه « كذاب وأبو الكذاب » (يو ٨ : ٤٤) . قال هذا لكى لا نصدق كل ما يقوله الشيطان ، ولا ننخدع به . وليس الكذب عند الشيطان هو فقط ما يقوله من كلمات ، وإنما هناك ما هو أخطر بكثير من كل هذا :",{h:"هناك من يرسلهم من أنبياء كذبة ومسحاء كذبة ..."},"ولقد حذرنا الرب من كل هؤلاء ، فقال « إن قال لكم أحد هوذا المسيح هنا أو هناك فلا تصدقوا . لأنه سيقوم مسحاء كذبة وأنبياء كذبة ، و يعطون آيات عظيمة وعجائب حتى يضلوا لو أمكن المختارين أيضاً » (متى ٢٤ : ٢٣ ، ٢٤) . وطبعاً سيمطون تلك الآيات والعجائب من الشيطان ، كما قيل عن المقاوم ضد المسيح « الذى مجيئه بعمل الشيطان بكل قوة وبآيات وعجائب كاذبة » (٢تس ٢ : ٩) .",{h:"ومن أمثلة ذلك تكلم الشيطان من أفواه الأنبياء الكذبة :"},"قوله عن إغواء آخاب الملك ليهلك « أنا أغويه ... وأكون روح كذب فى أفواه جميع أنبيائه » (١مل ٢٢ : ٢٢) . فكما أن الروح القدس هو الناطق فى أفواه الأنبياء القديسين ، كذلك الشيطان هو الناطق فى أفواه الأنبياء الكذبة .",{h:"كذلك يعلن الشيطان كذبه فى الأحلام والرؤى الكاذبة ..."},"وما أكثر الحروب التى تعرض لها الآباء الرهبان ، ووردت فى بستان الرهبان ، عن هذه الأحلام والرؤى الكاذبة . ومن أمثلتها ظهور الشيطان لأب راهب وقوله له « أنا الملاك غبر يال ، أرسلنى الرب إليك » فأجابه الراهب فى اتضاع « إننى إنسان خاطىء ، لا أستحق أن يظهر لى ملاك . فلعلك أرسلت إلى غيرى وأخطأت الطريق » . وظهر كذب الشيطان ، فمضى واختفى عنه ."],21:["أو كمثال آخر قصة الشيطان الذى ظهر لراهب وقال له « أنا المسيح ، فاسجد لى » . فقال الراهب فى قلبه « أنا فى كل يوم أسجد لسيدى المسيح . فلماذا يطلب هذا منى السجود » . وهكذا كشف حيلة وكذب الشيطان ، وانتهره فمضى .","وما أكثر الأحلام الكاذبة التى يضل بها الناس ظانين أنها من الله ! وقد قال القديس بولس الرسول عن الرؤى الكاذبة التى من الشيطان :","« لأن الشيطان نفسه يغيّر شكله إلى شبه ملاك نور » (٢كو ١١ : ١٤) .","وفى قصة الأنبا غاليون السائح ظهرت له الشياطين بهيئة آباء سواح يريدون ضمه إليهم . ولم يكتشف أنهم شياطين ، إلا بعد أن أتاهوه فى البرية ، ثم سخروا به وتركوه هازئين به ، إلا أن رحمة الرب أدركته من أجل نسكه ، و ببساطة قلبه ، وماضى تعبه ...",{h:"وكذب الشيطان يظهر أيضاً فى أقوال السحرة والعرافين وأمثالهم ."},"ولذلك أوصى الرب قائلاً « لا تتعلم أن تفعل مثل رجس أولئك الأمم . لا يوجد فيك من يجيز إبنه أو إبنته فى النار ، ولا من يعرف عرافه ... ولا ساحر ، ولا من يرق رقية ، ولا من يسأل جاناً أو تابعة ، ولا من يستشير الموتى . لأن كل من يفعل ذلك مكروه عند الرب . و بسبب هذه الأرجاس ، الرب إلهك طاردهم من أمامك » (تث ١٨ : ٩ ـ ١٢) . ولعل هذه الآية تكشف لنا شيئاً آخر هو :",{h:"كذب الشيطان فى استشارة الموتى ، أو فى ( تحضير الأرواح ) ."},"فقد ينطق فى أمثال هذه الجلسات ، مدعياً أنه روح فلان من الناس . ويقول للحاضرين بعض معلومات تخدعهم مما يعرفه عن أخبار ذلك الشخص أو أسرته . فإذا صدقوه ، يبدأ بالتدريج يقول لهم ما يضلهم ... وكل هذا من كذب وادعاء الشيطان ليضل الناس ...",{h:"ولعل من كذبه أيضاً ، ما يقوله على أفواه المنجمين ومدعى معرفة الغيب ..."},"سواء عن طريق التنجيم ، أو قراءة الكف ، أو ضرب الرمل ، أو قراءة فنجان القهوة ، أو معرفة البخت والطالع بأنواع وطرق شتى ...","وواضح لاهوتياً أنه لا يعرف الغيب سوى الله وحده . فمن يدعى معرفة الغيب ، لا يكون صادقاً فيما يدعيه ..."],22:[{h:"وإغراءات الشيطان كلها ألوان من الكذب ..."},"حيث يصور للإنسان سعادة تأتيه من وراء الخطية ، سواء فى لذة أو سلطة أو مكسب أو جاه أو مجد ... وبعد أن يسقط الشخص يجد أن كل إغراءات الشيطان هى سراب زائل ، وأنها أشياء زائفة ، كما صور لحواء وآدم أنها سيصيران مثل الله ... وكما صور لسليمان أنه سيسعد بكثرة ألوان المتعة والترف التى تحيط به ، فوجد أن الكل باطل وقبض الريح (جا ٢) .","ولكن هذا أسلوب الشيطان دائماً ، يزخرف طريق الخطية ، و يضفى عليه أوصافاً من الجمال تغرى من يسقط فى حبائله . وتكون كل زخارفه أكاذيب يخفى بها بشاعة الخطية ونتائجها السيئة ...",{h:"أيضاً أحلام اليقظة التى يقدمها لضحاياه ، كلها أكاذيب ..."},"ولكنه يقدمها لهم كنوع من اللذة تخدرهم عن العمل الإيجابى النافع ، فيعيشون بهذه الأحلام فى خيال غير واقعى ، يبنون قصوراً من رمال ، وأمجاداً وأفراحاً ومتعاً . ثم يستيقظون فلا يجدون شيئاً . و يكون الشيطان بهذا الكذب قد أضاع وقتهم ، وعطلهم عن العمل المجدى ، وأراحهم راحة كاذبة .",{h:"ومن أكاذيب الشيطان إيهامه المنتحر أن الموت سيريحه من متاعبه ."},"و يظل يركز على هذه النقطة : إنه لا فائدة من هذه الحياة ، ولا حل لمشاكله . والحل الوحيد هو الموت ، حيث يتخلص من كل تعبه و يستريح . وإذ يصدقه المنتحر و يقتل نفسه ، لا يجد هذه الراحة ، بل يجد نفسه فى الجحيم ، فى تعب وألم لا نجاة منه ، ولا تقاس به كل متاعب الدنيا . و يجد أن الموت ليس هو نهاية لحياته المتعبة ، بل هو بداية لحياة أكثر تعباً . و يكون الشيطان بهذا الكذب قد خدعه وضلله وأضاعه ...",{h:"ونقريباً غالبية الخطايا ، يضع الشيطان وراءها أكذوبة من أكاذيبه ."},"فهو يوحى للسارق بأن لا أحد سوف يرى أو يكتشف سرقته ، وكذلك يوحى للمهرب وللمرتشى وللغشاش . والشيطان فى كل هذا يكذب ، لأنه حتى إن لم ير البشر ، فالله يرى وكل شىء مكشوف أمامه . وهو يوحى للقاتل بأن المقتول يستحق القتل ، وحياته خطأ يجب تصحيحه ، أو أن القتل غسل للعار الذى يلوث شرفه ، أو أن قتله يريح نفس قريب له قد مات ..."],23:["بل لعل الإلحاد هو أكبر أكذوبة قدمها الشيطان للبشرية . وقد كذب على الوجوديين حينما صور لهم أن وجود الله يعطل وجودهم ، كما كذب على الماركسيين إذ صور لهم أن الله يعيش فى برج عالٍ ولا يهتم بالمجتمع الإنسانى ، بل يترك فيه الظالم يظلم ، والغنى يستعبد الفقير... !!","من صفات الشيطان أيضاً فى حروبه أنه :",{h:"٦ ـ لحوح"},"أى أنه كثير الإلحاح جداً ، لا يملّ . وربما الفكر الواحد يظل يعرضه مرات ومرات . ومهما رفضه الناس ، يستمر أيضاً فى عرضه .",{h:"ربما من كثرة الضغط المستمر والإلحاح ، يستسلم الإنسان له ويخضع ."},"لقد قيل فى بستان الرهبان إن الشيطان ظل يحارب راهباً بخطية واحدة مدى خمسين عاماً ، لا يهدأ ، ولا ييأس ، ولا يملّ ...","وحتى فى حربه مع السيد المسيح ، لم يهدأ بعد فشله فى التجربة الأولى والثانية والثالثة . ولما انتهره الرب ومضى قال القديس لوقا الإنجيلى عن ذلك « ولما أكمل إبليس كل تجربة ، فارقه إلى حين » (لو ٤ : ١٣) . وعبارة « إلى حين » تعنى أنه رجع إلى تجربته مرة أخرى أو مراراً عديدة .",{h:"الشيطان لا ييأس من الفشل أبداً ، ولا يخجل ، بل يعود !"},"لما فشل فى التجربة الأولى مع أيوب ، رجع مرة أخرى يطلب تجربته بأسلوب أصعب ... ولما فشل مع السيد المسيح فى كل التجارب ، أتاه وهو على الصليب يقول له « إن كنت إبن الله ، إنزل من على الصليب » (متى ٢٧ : ٤٠) .",{h:"والشيطان فى إلحاحه على إسقاط الناس لا يعترف بعقبات ."},"لا يهمه أن آدم وحواء خلقا على صورة الله ومثاله (تك ١) .","ولا يهمه أن داود مسيح الرب ، ولا أن سليمان هو أحكم أهل الأرض كلها ، ولا أن بطرس رسول متحمس جداً للمسيح . ولا يهمه أن يهوشع هو الكاهن العظيم (زك ٣) ، ولا أن هارون هو رئيس الكهنة (خر ٣٢) . ولا أن شمشون هو نذير الرب « وأن روح الرب"],24:["يحركه » (قض ١٣) ... لا يهمه مراكز الناس ولا روحياتهم ... بل يضرب ضربته ، وليحدث بعد ذلك ما يحدث ... إن كان قد تجرأ أن يجرب المسيح له المجد ، فهل يهتم بالبشر ؟!",{h:"إنه يلقى سمومه كل حين على كل أحد . وربما الذى لا يهلك بها اليوم ، قد يهلك بها غداً ، أو بعد سنة ، أو بعد عشرين ... !"},"إن الشيطان مثابر ، نشيط ، لحوح ، دائب على العمل ، لا يثبط الفشل همته . ولا ييأس من علو قدر الناس فى الروحيات . هو ماض فى خطته لتحطيم الملكوت ، ولكى يضل حتى المختارين أيضاً ... والذى لا يستطيع أن يدنس جسده ، فعلى الأقل يدنس فكره . والذى لا يقبل طعنه فى روحياته ، على الأقل يلطمه بشوكة فى الجسد (٢كو ١٢ : ٧) . وإن لم يستطع أن يسقط أولاد الله ، فعلى الأقل يشتكى عليهم . لذلك قيل إنه :",{h:"٧ ـ المشتكى"},"وقد قال عنه سفر الرؤيا إنه « المشتكى على أخوتنا ، الذى كان يشتكى عليهم أمام إلهنا نهاراً وليلاً » (رؤ ١٢ : ١٠) .",{h:"إنه يشتكى على القديسين ، مدعياً أنه لم يأخذ فرصته لمحاربتهم ! ... أو أن فرصته التى أخذها قبلاً ، لم تكن كافية !"},"وقد وقف فى القديم يشتكى على أيوب أمام الله ، مدعياً أنه لم يأخذ فرصة لمحاربته . وقال لله « أليس إنك سيجت حوله ... باركت أعمال يديه ... ولكن إبسط الآن يدك ومس كل ماله ، فإنه فى وجهك يجدف عليك » (أى ١ : ١٠ ، ١١) .","ومع أن الله واجه الشيطان بقسوته وظلمه فى شكواه ، وقال له عن أيوب « إلى الآن هو متمسك بكماله . وقد هيجتنى عليه لأبتلعه بلا سبب » (أى ٢ : ٣) ، إلا أن الشيطان استمر فى شكواه للمرة الثانية ، وطلب فرصة أوسع ، وأخذ سماحاً لضرب أيوب فى جسده بقرح ردىء (أى ٢ : ٧) ...","عجيب أن الشيطان يفعل كل ما يريد ، و يظل يشكو !","وهو يشكو على الرغم من مواهبه العديدة ، فهو :"],25:[{h:"٨ ـ كثير المواهب"},"إنه كثير القدرات إلى حد بعيد . يعرف أشياء كثيرة و يتقنها .",{h:"فالمواهب التى منحت له وهو ملاك ، لم يسحبها الله منه ..."},"معرفته واسعة جداً فى كل مجال . حتى آيات الكتاب المقدس ، يعرفها جيداً ويحارب بها ، وكأنه من اللاهوتيين . وفى التجربة على الجبل ، إستخدم الكتاب المقدس بطريقته الخاصة (متى ٤ : ٦) . بل إنه هو صاحب جميع البدع والهرطقات ، وهو الذى وضع أفكارها فى أذهان المراطقة ، وقدم لهم مفاهيم خاطئة لآيات الكتاب . وصدق القديس أثناسيوس الرسول حينما قال : إن عدونا ليس هو الأريوسيين ، إنما هو الشيطان .","والشيطان يعرف الشعر . بل إن كثيراً من الشعراء يتحدثون عن شيطان الشعر ، وأنه ملهمهم أفكارهم ... لذلك ليس غريباً إن قال أحد علماء الأرواح ، إنه استحضر روح شاعر مشهور وسمع منه قصيدة بنفس أسلوبه ... ليس غريباً أن يكون الشيطان قد تدخل ، وأملى الوسيط شعراً بنفس الأسلوب !",{h:"والشيطان يعرف الموسيق والفن والنحت والرسم والأغانى ."},"ويمكنه أن يلهم المشتغلين بالملاهى كل ما يحتاجونه فى فنونهم لإغراء الناس وإسقاطهم ، أو إبعادهم بها عن عملهم الروحى .",{h:"والشيطان من علماء النفس البارزين ، بل هو فى مقدمتهم جميعاً ، بسبب خبرته العملية . وهذه الخبرة تساعده فى حروبه . كما أن حروبه أيضاً تزيد من خبرته ومن علمه . وكما أنه من علماء النفس ، هو أيضاً من علماء الأرواح ، لأنه روح ، يعرف ما للروح أكثر مما يعرف البشر ."},{h:"غير أن علم الشيطان يسير وفق أغراضه ."},"فالعلم الخالص شىء ، واستخدام هذا العلم لتحقيق غرض هو شىء آخر . وغرض الشيطان معروف وهو مقاومة الله وملكوته . لذلك هو يستخدم كل معارفه لتحقيق هذا الهدف الشيطانى .","ومن صفات الشيطان فى حروبه مع الإنسان ، أنه :"],26:[{h:"٩ ـ قاس"},"إنه يعمل بكل قسوة ، بلا رحمة . وقسوته واضحة جداً فى قصة أيوب الصديق . كما أنه جرّ كثيرين إلى الهلاك وأضاعهم ، كالذين هلكوا بالطوفان ، وبنار سادوم ، والذين ابتلعتهم الأرض أحياء (عد ١٦) .","وقسوته واضحة فى الذين يصرعهم ، و يصبحون فى حالة جنون بسببه . ومثال ذلك مجنون كورة الجدريين الذى « كان فيه شياطين ... وكان لا يلبس ثوباً ، ولا يقيم فى بيت بل فى القبور ... وقد ربط بسلاسل وقيود محروساً . وكان يقطع الربط و يساق من الشيطان إلى البرارى » (لو ٨ : ٢٦ ـ ٢٩) ، « وكان يصيح ويجرح نفسه بالحجارة » (مر ٥ : ٥) . وأمثلة هذا المصروع كثيرون ...",{h:"وتظهر قسوته كذلك فى محارباته للقديسين ، وفى المناظر المخيفة ."},"ففى حربه مع القديس أنطونيوس الكبير كان يظهر له فى مناظر مفزعة جداً ، وأحياناً فى هيئة وحوش مخيفة تصيح حوله بأصوات مرعبة . وفى إحدى المرات ضرب القديس بضربات شديدة مؤلمة للغاية ، وتركه بين حى وميت ... والذى يقرأ سيرة القديس قرياقوس السائح ، يجد أمثلة أخرى تشبه هذا النوع أو أشد ...",{h:"وهو قاس فيما يثيره على العالم من حروب وويلات وجرائم ."},"ومعروف جداً نتائج كل هذه ... ولكن الشيطان يفرح بكل ويلات العالم ، ويحسب ذلك انتصاراً له ، إلى جوار تحطيمه للنفوس وللعقول ، وبثه للخصومات وأسباب الإنشقاق والتمزق . فهو عامل تخريب لا يهدأ ، بكل عنف . وهو سعيد بتخريبه .","صدقونى ، إننا لو قرأنا عن قسوة الشيطان فى حروبه المفزعة للقديسين ، نقول عن أنفسنا إننا لم نُحارب أبداً من الشيطان . فحروبنا الحالية شىء تافه إلى جوار حروبهم ... والعجيب أنه فى كل قسوة الشيطان ، يتظاهر بالعطف أحياناً ، ولكنه :",{h:"١٠ ـ خبيث فى تظاهره بالعطف"},"عبارات العطف عنده وسيلة ماكرة لإسقاط الناس ..."],27:["فهو (يعطف) عليك حينما تصوم ، و يدعوك إلى الأكل ، من أجل صحتك ! محذراً إياك من المرض ومن الضعف ! و يقول لك إحذر من أن تقتل جسدك ، فهو وزنة تمجد بها الله . وقد قال الرسول « إنه لم يبغض أحد جسده قط بل يقوته و يربيه » (أف ٥ : ٢٩) .","وهو يعطف عليك حينما تنشط روحياً ، وتسهر فى الصلاة والقراءة والمطانيات ، و يدعوك فى عطف إلى النوم من أجل راحتك .",{h:"وهو (عطوف) يخشى عليك من (التطرف) فيدعوك إلى الإقلال من الجهاد ."},"وفى عمق عملك الروحى ، يقول لك : لا داعى لكل هذا ، فإن الآباء يعلموننا أن الطريق الوسطى خلصت كثيرين ... وهكذا يقول لك : إحترس من التطرف ، لئلا الشيطان يضربك ضربة يمين وهى أقسى ، ولئلا تقع فى المجد الباطل وهو شر الرذائل كلها . بل يقول لك : لا شك أن تطرفك هذا فى الجهاد هو من عمل الشيطان ، وهو لا يقصد بك خيراً ! فاستمع لقول الكتاب « لا تكن باراً بزيادة ... لماذا تخرب نفسك ؟ » (جا ٧ : ١٦) .",{h:"والشيطان (العطوف) يشفق عليك من البكاء على خطاياك ..."},"يقول لك : لماذا تبكى وتحيا فى الكآبة . ليس هذا هو طريق الله ... أليس أن خطاياك قد غُفرت ، ومحاها الرب بدمه ؟! لماذا تبكى عليها إذن ؟! أتريد أن تظل فى البكاء حتى تتلف أعصابك ونفسيتك ، وحتى تنكشف أمام الناس ؟! أليس أن الكتاب يقول « إفرحوا فى الرب كل حين » (فى ٤ : ٤) ... و يظل بك حتى تفقد إنسحاق القلب ، وتفقد دموع التوبة ، وتفتر حرارتك ... وإذ تفعل هذا ، تسهل عليك الخطية وربما تعود إليها . وطبعاً ينسيك قول الكتاب « بكآبة الوجه يصلح القلب » (جا ٧ : ٣) .",{h:"والشيطان (العطوف) يبرر لك أخطاءك ، حتى لا تتعبك ضميرك ."},"إنه يمنع عنك التبكيت ، حرصاً على مشاعرك ! وإشفاقاً عليك من الحزن ومن اليأس ! ولذلك فى كل أخطائك يقدم لك العديد من الأعذار ومن التبريرات ، و ينصحك قائلاً : لا تقل على كل شىء إنه خطأ ، ولا تبالغ فى تبكيت نفسك ، لئلا يقودك هذا إلى الوسوسة .... حقاً إن هذا خطأ ، ولكنك لم تكن تقصد ، ونيتك طيبة ، وهى تشفع لك . والله ينظر إلى النيات .... وهذا خطأ ، ولكن ماذا كان بإمكانك أن تفعل ؟! الظروف"],28:["كانت ضاغطة . وصدقنى لو أنا فى موضعك ما كنت أستطيع أن أفعل غير هذا . والله لا يطلب منك فوق طاقتك . لذلك لا تكتئب ...","وبتبرير أخطائك ، تجعل ضميرك واسعاً يبلع الجمل ، و يبعدك عن التوبة وعن الحرص والتدقيق ، وعن الأمانة فى القليل ...","إن (العطف) عند الشيطان ليس حباً ، إنما وسيلة للإسقاط . فاحترس منه ، ولا تسمع له . وكن حازماً مع نفسك . واسلك بتدقيق ... وتأكد أن الشيطان فى كل حروبه معك يكون غير مخلص . كل نصائحه غير مخلصة ، حتى لو كانت بمظهر الخير . إنه لا يريد سوى ضياعك .","من صفات الشيطان أيضاً أنه حسود .",{h:"١١ ـ حسود"},"قلبه لا يستريح مطلقاً أن يرى إنساناً ناجحاً ، أو إنساناً باراً ، فيعمل كل ما يستطيعه لإسقاط هذا وذاك .",{h:"وفى حسده يضرب ضرباته بلا رحمة ..."},"لقد حسد يوسف الصديق على ما رآه من رؤى ، فنقل الحسد إلى قلوب أخوة يوسف حتى باعوه كعبد . ثم حسده على نجاحه وثقة فوطيفار به ، فدبر له حيلة ألقاه بها فى السجن كفاعل إثم ...","وحسد العالم على إيمانه بالله ، فألقاه فى الوثنية ، وفى تعدد الآلهة وفى الإلحاد . ودبر لذلك كل صنوف الفكر والفلسفة ، وأيضاً العبادات البدائية . وصدق المزمور حينما قال « لأن كل آلهة الأمم شياطين » (مز ٩٦ : ٥) .",{h:"والشيطان يحسد المعرفة والحكمة ، ويحسد العفة ، ويحسد الإتضاع ..."},"لذلك فهو ينشر فى العالم الجهل والزنا والكبرياء ، بكل ما عنده من حق . لقد حوّل سليمان عن حكمته وأسقطه . وألقى فى العالم كثيراً من المعارف الخاطئة ، حتى « قال الجاهل فى قلبه ليس إله » (مز ١٤ : ١) . وأصبح الزنا من الحروب الخطيرة"],29:["التى تحارب العالم كله . كما صارت الكبرياء حرباً يقع فيها من لم يقع فى باقى الخطايا ومن يقع فيها أيضاً .",{h:"إن حسد الشيطان هو حسد مدمّر ، وليس مجرد مشاعر ."},"فهو إذ يحسد ، يضرب بكل قوة . كما حسد أيوب على كماله ، فضربه بكل قسوة ، واشتكاه أمام الله . وكما حسد سكان البرارى على زهدهم ونسكهم فأثار ضدهم أعنف الحروب . وكما حسد أوريجانوس أعلم أهل عصره وأستاذ اللاهوت الأول فى عصره ، فألقاه فى كثير من البدع حرمته من أجلها الكنيسة ، حتى قيل عنه « أيها البرج العالى ، كيف سقطت ؟! » ...",{h:"لذلك فى كل ما تعمله من بر ، توقع حسد الشياطين ."},"وتوقع أنهم لا يبقونك مطلقاً فى برك ، بل يحاولون إسقاطك بشتى السبل . فإن ضربوك ضربة فى يوم روحى عميق ، لا تيأس بل قل : هذا ما كنت أتوقعه . ولكنى أطلب من رحمة الله أن تعيننى حتى لا أسقط ثانية .",{h:"وإن منحك الله موهبة ، فنوقع أيضاً حسد الشياطين ."},"فهم إما أن يحاولوا إسقاطك فى الكبرياء ، أو استخدام الموهبة فى غير موضعها . وبهذا يكونون قد أضاعوا هدفها الروحى ونفعها لك ولغيرك ...","من صفات الشيطان الأخرى أنه :",{h:"١٢ ـ نهاز للفرص"},"الشيطان يحاول أن يستغل الفرص ، ليلقى فيها تجاربه . كما استغل جوع السيد المسيح بعد صوم أربعين يوماً ، لكى يجربه بتجربة الخبز .","وكما انتهز فرصة خوف بطرس ليلقيه فى إنكار المسيح .","وانتهز أيضاً فرصة تمسك اليهود بالسبت ليجعلهم ينكرون معجزات للمسيح لم يعملها أحد من قبل ، بل يتهمونه بالخطية (يو ٩ ، ١١) .","من صفات الشيطان أيضاً أنه :"],30:[{h:"١٣ ـ غير مخلص وغير أمين"},"قلنا قبلاً إن الشيطان قد يأخذ موقف الشفوق على صحتك ، سواء من جهة الصوم أو السهر ، أو تعب الجسد جملةً . و ينصحك فى ذلك بالراحة الجسدية ، حرصاً على سلامة صحتك ... !",{h:"ولكنه ليس أميناً حقاً من جهة إهتمامه بصحة جسدك ."},"إنه ينصحك بالراحة ، ويمنعك من السهر ، إن كان سهرك فى الصلاة أو التأمل ، أو القراءة الروحية ، أو فى ليالى الصلاة . ولكنك إن سهرت فى اللهو أو فى وسائل الترفيه المتنوعة ، فلا يحدثك عن مضار السهر خوفاً على صحتك !",{h:"وإن تعبت فى أمور العالم الباطلة ، لا ينصحك بالراحة ..."},"إن تعبك فى جمع المال ، وفى الجرى وراء السهر والجاه ، وفى السعى وراء ملاذك ومتعك ، وفى تنظيم الحفلات الصاخبة ، وفى اللعب والرياضة ، وفى كافة الأنشطة العالمية ... كل هذا لا يثير إشفاقه عليك ، ولا يدعوك فيه إلى الراحة ... !","إنما ينصحك بالراحة ، إن كان تعبك فى أى عمل روحى . جهادك الروحى فقط هو الذى يثير إشفاقه عليك وعلى صحتك ؟",{h:"لذلك إن دعاك إلى الراحة وقت جهادك الروحى ، فلا تطعه ."},"إنها فى حقيقتها دعوة منه إلى الكسل والتراخى ... أما أولاد الله ، فكانوا يفرحون بالتعب ، بل و يفتخرون به (١كو ١٥ : ١٠) . وكما قال القديس بولس الرسول « فى الأتعاب أكثر ... فى تعب وكد . فى أسهار مراراً كثيرة » (٢كو ١١ : ٢٣ ، ٢٧) . وقال أيضاً « كل واحد سيأخذ أجرته بحسب تعبه » (١كو ٣ : ٨) .",{h:"إن عرفت هذا ، إتعب من أجل الله ، على قدر طاقتك ."},"واعلم أن نصيحة الشيطان لك بالراحة ، نصيحة غير مخلصة ، وغير أمينة ، وغير صادقة . لقد تعب القديس الأنبا بولا الطموهى فى النسك ، إلى أن ظهر له ربنا يسوع المسيح وقال له « كفاك تعباً يا حبيبى بولا » . فرد عليه القديس « وماذا يكون تعبى هذا ، إلى جوار كل تعبك يارب لأجل خلاصنا ؟! » ."],31:[{h:"خير لك أن تتعب ههنا على الأرض ، لتنال أكاليل الجهاد ."},"من أن تستريح ههنا على الأرض ، وتتعب هناك فى الأبدية ...","واعلم أن تعبك هنا ليس منسياً أمام الله ، لأنه « ليس بظالم حتى ينسى تعب المحبة » (عب ٦ : ١٠) . وكل تعب تتعبه ههنا ، مكنوز لك هناك فى الأبدية .",{h:"ليس ههنا مكان الراحة . إنما هنا مكان الجهاد والتعب ."},"لذلك حينما يموت إنسان ، يقولون إنه تنيح أى استراح ...","فالشيطان ليس أميناً فى دعوتك إلى الراحة . إنه يخدعك ...",{h:"إنه يحدثك عن الصحة وقت النسك ، وليس وقت الفساد !"},"إن صمت ، يلبس الشيطان ملابس الأطباء ، و يلقى محاضرة مستفيضة عن أهمية البروتين الحيوانى والأحماض الأمينية الأساسية . و يظهر إهتمامه بجسدك وسلامته .","ولكنه لا يتحدث عن سلامة جسدك إذا داومت على التدخين أو المسكرات ، أو الشهوات الشبابية الضارة بالصحة . إنه ليس مخلصاً فى دعوتك إلى الصحة .",{h:"لذلك إن حاربك براحة الجسد وصحته ، فقل : ليس هذا وقته ."},{h:"إن كانت حرب الراحة من الشيطان ، فإن حرب الكسل أشد ."},"إننا حينما نتعب بالجسد ، نشعر براحة نفسية . والعكس صحيح .","حينما نكمل واجباتنا نشعر براحة وفرح ، مهما تعبنا بالجسد . وانتصارنا على جسدنا فى الصوم والسهر والمطانيات والعفة ، يعطينا راحة لا توصف ."],32:[{h:"الفصل الثالث"},{h:"حيل الشيطان"},"« نجنا من حيل المضاد ... » ،","« وإبطل سائر فخاخه المنصوبة لنا » .","( تحليل صلاة الغروب )"],33:["ما أكثر حيل الشياطين ! إنها لا تنتهى . إن لم تصلح حيلة منها ، يستبدلها بغيرها ، وبثانية وثالثة ... إلى أن يصل إلى غرضه . وليست هناك خطة واحدة أمامه لتوصّله . بل هو يتخذ لكل وضع ما يراه مناسباً ، دون أن يتقيد بشىء ...","على أنه من أشهر خططه الواضحة المتكررة ، بضعة أساليب صارت معروفة ومحفوظة ، نذكر من بينها ما يأتى ...",{h:"١ ـ خطية تلبس ثوب الفضيلة"},{h:"ما أسهل أن يقدم لك الشيطان بعض الخطايا بأسماء غير أسمائها ، بأسلوب يسهل قبوله . بحيث تلبس الخطايا ثياب فضائل ..."},"وكما قال السيد الرب « يأتونكم فى ثياب الحملان وهم ذئاب خاطفة » (متى ٧ : ١٥) .","فالتهكم على الناس والإستهزاء بهم ، يقدمه على اعتبار أنه لطف وظرف ، ومحبة ودالة ، وخفة روح ، ومحاولة للترفيه ... !","والدهاء يسميه باسم الذكاء ... !","و يقدم لك القسوة فى معاملة أولادك أو إخوتك الصغار ، باسم التأديب والتربية والتقويم . ويجعل ضميرك يوبخك إن لم تؤدبهم .","والتزين غير اللائق والتبرج ، يقدمها لك باسم الأناقة والنظافة .",{h:"إن الشيطان لا يقدم الخطية مكشوفة ، لئلا يرفضها الإنسان ."},"بل يقدمها باسم آخر ، وهى هى ، ولا فارق ...","يقول إننى سأدخل مع ( فلان ) فى حرب مسميات ، وأسقطه فيما أريد ، ربما دون أن يشعر ... أو قد يشعر ولكن ضميره لا يبكته ."],34:["لو أننى قدمت له الرياء بهذا الإسم المنفر ، فلن يقبله . إذن ماذا أفعل ؟ سأجعله مثل القبور المبيضة من الخارج (متى ٢٣) ، بحيث يكون فى الداخل شيئاً ، وفى مظهره الخارجى عكس ذلك تماماً . ولكننى سأدعو الرياء باسم مقبول : أسميه عدم إعثار الآخرين ، أو أسميه القدوة الحسنة .","ليس من ( الحكمة ) أن يسمى الشيطان الخطية خطية ، فيكشف حينئذ أوراقه ، ولا يصل إلى هدفه !","يقول السيد الرب فى حديثه مع تلاميذه :",{h:"تأتى ساعة ... يظن فيها كل من يقتلكم ، أنه يقدم خدمة ( قرباناً ) لله !! (يو ١٦ : ٢) ."},"ويقيناً أن الشيطان قدم خطية القتل إلى هؤلاء ، باسم « الغيرة المقدسة » أو « الدفاع عن الدين » أو « الجهاد المقدس » أو « تطهير الأرض من الخطاة » . وربما كان هذا هو شعور الكتبة والفريسيين وشيوخ الشعب ، فى تقديمهم السيد المسيح للصلب .","إن الذين انتهروا الأطفال ومنعوهم من الذهاب إلى المسيح (لو ١٨ : ١٥) ، ما كانت هذه قسوة فى نظرهم ، أو عدم إهتمام بالصغار . إنما لبس هذا التصرف ثياب الحملان ، وتسمى باسم فضيلة ، ربما إسمها « حفظ النظام » أو « حفظ كرامة المعلم الصالح » .",{h:"والكذب يمكن أن يقدمه الشيطان تحت إسم « الحكمة » !"},"يقدمه كنوع من حسن التصرف ، أو إنقاذ المواقف . والطبيب قد يكذب على المريض مرات عديدة ، و يسميها أمام ضميره « حفظ معنويات المريض » ، وحمايته من الإنهيار ، لكى يشفى .","والبعض يسمى بعض أنواع الكذب باسم « الكذب الأبيض » . وربما يسميه فى أول أبريل باسم : الدعابة أو الفكاهة والتندر ، أو أى إسم مشابه .",{h:"وبهذا الشكل ، ما أسهل على الشيطان أن يسمى الرقص فناً !"},"و يسمى الصور العارية والماجنة فناً أيضاً . وكذلك التماثيل التى من نفس النوع . و يدخل تحت هذا الإسم كل ما فى السينا والمسرح من التمثيل مهما كان خاطئاً ... وكل"],35:["ما فى الغناء والموسيق ، مهما كان معثراً أو مثيراً ...","وتحت إسم الفن يخفى الشيطان مجموعة كبيرة من الخطايا والعثرات ، لا تستحق هذا الإسم الجميل !",{h:"إلباس الخطية ثوب الفضيلة ، هو حيلة ماكرة من حيل الشيطان ."},"أتراه يدعو البخل بخلاً ؟! ما كان أحد إذن يقبله . إنما الشيطان قد يسميه « حسن تدبير للمال » أو « حفظ المال لحاجة المستقبل » أو يسميه « عدم التبذير » أو « عدم الإسراف » . وإذا أراد الشيطان أن يمنع غنياً من أن يدفع للفقراء ، يقول له : ليس من الخير أن تعوّدهم الشحاذة ، أو أن تعودهم التشرد والتواكل . إن عدم إعطائهم هو حكمة ، وعين الحكمة ، لكى يبحثوا عن عمل ، ولكى يأكلوا من عرق جبينهم حسب وصية الرب الإله (تك ٣ : ١٩) .",{h:"إعطاء الخطية إسم فضيلة ، يجعل الناس يستمرون فيها ..."},"فليس فقط من جهة الماضى ، لا يتبكت الإنسان من ضميره . وإنما أيضاً من جهة المستقبل يستمر الخاطىء فيما هو فيه ، بهذا الخداع من الشيطان .",{h:"أتراه كان يطلق إسم هرطقة على أفكار أريوس ومقدونيوس وسابيليوس وأمثالهم ؟!"},"كلا ، بل كان يقنعهم أن هرطقاتهم هى الدفاع عن الإيمان السليم !! وكان يزوّدهم بالتفسير الخاطىء لآيات الكتاب ، لكى يقبلوا أفكاره ، ولكى يقنعوا أيضاً غيرهم بها ...","إحترس إذن من المسميات الخاطئة ، ولا تسمح للشيطان بأن يخدعك . فإن الخطية هى الخطية مهما اختفت وراء إسم آخر ...","كذلك إحترس من حرب أخرى يلجأ إليها الشيطان ، وهى :",{h:"٢ ـ تحطيم فضيلة لاكتساب غيرها"},"إن الشيطان يتضايق من فضائلك الثابتة التى صارت وكأنها من طبيعتك . لذلك يحاول أن يحطمها بكل حيلة . وليس أسهل من أن يقدم لك فضيلة أخرى جديدة ، إن"],36:["لم تسلك فيها بإفراز ـ لقلة الخبرة ـ تضيع الفضيلة الأولى الثابتة . ومثال ذلك :",{h:"أ ـ إنسان يحيا فى وداعة وهدوء وسكون وسلام قلبى ودماثة خلق ..."},"يريد الشيطان أن يفقده كل ما فيه من رقة ، ومن كلمة طيبة ، ومن تواضع قلب . فماذا يفعل ؟ إنه لا يستطيع طبعاً أن يذم له الوداعة ، أو أن يقول له : أترك طبعك هذا المحبوب من الكل ... ولكنه يصل إلى ذلك عن طريق الإحلال ... يقدم له فضيلة بديلة ، دون أن يقول له إنها بديلة ... وكيف ؟",{h:"يشرح له أولاً أهمية الآية القائلة « غيرة بيتك أكلتنى » ."},"وكيف أن داود المشهور بالوداعة (مز ١٣٢ : ١) هو الذى قالها . وكيف أن التلاميذ تذكروها حينما صنع السيد المسيح الوديع « سوطاً من حبال ، وطرد الباعة من الهيكل ، وطرد الغنم والبقر ، وكبّ دراهم الصيارف وقلب موائدهم » (يو ٢ : ١٥ ، ١٧) . وقال لهم مكتوب : بيتى بيت الصلاة يدعى ، وأنتم جعلتموه مغارة لصوص » (متى ٢١ : ١٣) .",{h:"ويدعوه إلى محاربة الأخطاء ، ويزوده بكل الآيات اللازمة ."},"يقول له إن السيد المسيح وبّخ الكتبة والفريسيين بشدة ، وقال لهم فى أصحاح كامل « ويل لكم أيها الكتبة والفريسيون المراءون » (متى ٢٣) ، وواجههم بكل أخطائهم . وقال لهم « أيها القادة العميان » أكثر من مرة . وقال لهم « إنكم تشبهون القبور المبيضة من الخارج » . وقال « هوذا بيتكم يترك لكم خراباً » (متى ٢٣ : ٣٨) . ويوحنا المعمدان قال موبخاً قادة اليهود فى أيامه « يا أولاد الأفاعى . من أراكم أن تهربوا من الغضب الآتى ... » (متى ٣ : ٧) .","ثم يقول له : إسمع قول القديس بولس الرسول . إنه أمر :",{h:"يأمرك قائلاً « وبّخ . إنتهر . عظ » (٢تى ٤ : ٢) ."},"ولا يكمل له الآية « بكل أناة وتعليم » . ولا يقول له إنها موجهة إلى القديس تيموثاوس الأسقف (أسقف أفسس) ، وليس لكل أحد . ولا يشرح له كيف كان القديس بولس نفسه يوبخ . وكيف قال لكهنة أفسس « ... لم أفتر أن أنذر بدموع كل أحد » (أع ٢٠ : ١٧ ، ٣١) ... وهكذا يلح عليه أن يوبخ وينتهر ...",{h:"كأنه المسيح أو المعمدان ، أو القديس بولس ، أو تيموثاوس الأسقف ."}],37:["ويقتنع هذا « الضحية » المسكين . ويظل يوبخ الكل ، وهو لا يعرف الطريقة الروحية للتوبيخ . ولا من يوبخ من ؟ ولا بأى سلطان يفعل هو هذا ؟ وفى توبيخه يقع فى إدانة الآخرين ، وفى الغضب ، وفى القسوة ، وفى التشهير ، وتسوّد صور الناس فى نظره ، وربما بهذا الأسلوب يبعد الكثيرين عن الكنيسة ... و يتحول إلى قنبلة متفجرة ، تقذف شظاياها فى كل اتجاه ... !",{h:"وهكذا يفقد وداعته ورقته ودمائته ، ويكره الناس ويكرهونه ."},"ثم ما يلبث أن يتعب من هذا الأسلوب الذى لا يتفق مع طباعه ، ويحاول أن يعود إلى حاله الأول . ولكنه لا يجد قلبه نفس القلب ، ولا فكره نفس الفكر . بل يرى أنه قد فقد بساطته ونقاوة قلبه وفكره ، كما فقد حسن علاقاته مع الآخرين ، وفقد أمثولته الصالحة التى كان يستفيد بها غيره .",{h:"لقد أطمعه الشيطان فى فضيلة لا يعرفها ، وأفقده فضيلته الأولى ."},"فما احتفظ بالأولى ، وماكسب الثانية . وصار فى بلبلة !","وهو يسمح له بممارسة الثانية ، لأنها غير راسخة فيه ، ولا تتعب الشيطان الذى يستطيع أن يزعزعه عنها بسهولة .","من أجل هذا ، كان آباؤنا ينصحون أولادهم بقولهم : إن أية فضيلة يقدمها لك الشياطين ، و يقصدون بها أن يهدموا فضيلة أخرى عندك ، أرفضها وقل لهم :",{h:"هذه الفضيلة جيدة . ولكننى من أجل الله لا أريدها ."},"حقاً ، إن عمل الله لا يهدم بعضه بعضاً . وكل إنسان له شخصيته التى قد تختلف عن غيره . وقد لا يناسبه ما يناسب غيره . وليس كل أحد له سلطان أن يرتب وينظم ، وأن يوبخ وينتهر ، وأن يحكم ويدين . ومن يعطه الله هذا السلطان ، لابد سيمنحه أيضاً كيف يستخدمه حسناً ، دون أن يخطىء ...","وليس كل إنسان يستطيع أن يقول « ويل لى إن كنت لا أبشر » . فقد قال هذه العبارة القديس بولس الرسول الذى قال فى شرح ذلك « إذ الضرورة موضوعة علىّ » وأيضاً « قد استؤمنت على وكالة » (١كو ٩ : ١٦ ، ١٧) . وأنت ، ما هى الضرورة الموضوعة عليك ؟! ومن الذى استأمنك على وكالة ، كما استؤمن القديس بولس من فم المسيح نفسه . وكما أخذ المعمدان رسالته فى بشرى الملاك لأبيه (لو ١ :"],38:["١٥ ـ ١٧) . وكما أخذ القديس تيموثاوس مسئوليته بوضع اليد (٢تى ١ : ٦) .","مثال آخر للفضيلة الجديدة ، المقصود بها إضاعة فضيلة أخرى :",{h:"ب ـ إنسان يعيش فى نقاوة القلب ، بعيداً عن العثرات الجسدية :"},"يعيش محترساً تماماً ، لا يقرأ قراءات تعثره ، ولا ينظر إلى أية مناظر تعثره ، ولا يختلط بأية خلطة معثرة ، ولا يستمع إلى أية أحاديث معثرة . وهكذا يحتفظ بأفكاره نقية ، لا تُدخل إلى قلبه أى شىء غير طاهر ...","هذا الإنسان الطاهر ، يريد الشيطان أن يحاربه . ولا يستطيع أن يقدم له عثرة مكشوفة ، لأنه سيرفضها حتماً . فماذا تراه يفعل ؟",{h:"يفتح أمامه الباب ليكون مرشداً روحياً ، يقود الشباب للطهارة ."},"إذ كيف يعيش فى الطهارة وحده ، و يترك أولئك المساكين يسقطون كل يوم ، ولا يقدم لهم مشورة صالحة تنقذهم مما هم فيه ؟! و يقول له إستمع إلى قول الرسول « من رد خاطئاً عن ضلال طريقه ، يخلص نفساً من الموت ، و يستر كثرة من الخطايا » (يع ٥ : ٢٠) . ويظل به يقنعه لكى يقبل هذه الخدمة الروحية الحيوية ، حتى يقتنع ، ويقبل أن يرشد الذين يأتون إليه ... ثم تأتى بعد هذا الخطوة الثانية ، وهى :",{h:"لكى يكون إرشاده عملياً ، لا بد أن يستمع إلى مشاكلهم وأخطائهم ."},"و يظل هؤلاء يضعون فى أذنيه أخبارهم وقصص سقوطهم . وقد يقولون كل شىء بالتفاصيل . وربما يكون فى ما يحكونه ما يعثر ... و يستمع ( المرشد ) الطاهر إلى كل ما كان يبعد عن سماعه ، و يعرف ما كان لا يحب مطلقاً أن يعرفه . وما كان يحاول أن يبعد عنه ، أصبح الآن ينصبّ فى أذنيه ، بكامل رضاه ... وكل واحد يقدم صورة جديدة ، أو صوراً عديدة من الخطأ .",{h:"وعن طريق الإرشاد ، يجد صاحبنا عقله وقد امتلأ بصور دنسة !"},"وأصبح يعرف أشياء صارت تشوه طهارة تفكيره ، وتدنسه بأخبار وقصص « ذكرها أيضاً قبيح » (أف ٥ : ١٢) ... وحتى إن لم تعثره وتغرس فيه إنفعالات خاطئة ، فعلى الأقل ستنجس فكره . وكأنه قد قطف أثماراً غريبة من شجرة معرفة الخير والشر ...",{h:"فإن حاول أن يبتعد ، يقال له : ما ذنب هؤلاء الشبان ؟"}],39:["وقد يكونون قد تعلقوا به ، واستراحوا إلى إرشاده . وربما يتعبون ضميره بأنه إن تخلى عنهم سيرجعون إلى خطاياهم مرة أخرى . وقد يلحون عليه فى أن يظل يسندهم حتى يقفوا على أرجلهم ... وهكذا يحدث له ما حدث للوط البار ، إذ قيل عنه « إذ كان البار بالنظر والسمع ـ وهو ساكن بينهم ـ يعذب يوماً فيوماً نفسه الباره بالأفعال الأثيمة » (١بط ٢ : ٨) . وهذا الأخ قد يكون بالسمع فقط وليس بالنظر . وربما ما يسمعه يضع فى ذهنه صوراً لم ينظرها من قبل ، وكأنه نظرها فعلاً ...",{h:"وما أدرانا ، ربما هذا الأخ المرشد ، يسقط ، ولو بالفكر والقلب !"},"كان يمكن من أول القصة أن يحيلهم إلى أب اعتراف ويريح نفسه . ولكن الشيطان ورّطه ، أو قذف به فى أول الطريق ، فقبل ذلك بسلامة نية ، دون أن يعرف كيف يتطور به هذا الموضوع .","وقد ينجح أخيراً فى تحويل هؤلاء إلى آباء اعتراف . ولكن بعد أن يكون فكره هو قد صار مخزناً لقصص كثيرة وأخبار ، ضيعت نقاوته الأولى ، وأدخلت فى ذهنه معلومات جديدة عليه ، ينطبق عليها قول الحكيم « الذى يزيد علماً ، يزيد حزناً » (جا ١ : ١٨) .",{h:"ج ـ وقد تأتى حيلة الشيطان فى الإرشاد بصورة أخرى ، يقدم فيها لا أخباراً تدنس القلب ، بل شكوكاً تتعب العقل"},"إذ يكون القلب فى بساطة الإيمان ، وتكون القراءات كلها روحية تعمّق صلته بالله . و يأتى إليه من يطلبون معونته وارشاده فى شكوك تتعبهم . وتتوالى هذه الشكوك من هنا وهناك ، لكى تجد لها حلاً . و يبدأ إيمان هذا ( المرشد ) يتحول شيئاً فشيئاً من القلب إلى الفكر والبحث العلمى ... وقليلون من يحتفظون بالإثنين معاً ... ويجد الشكوك تتكاثر عليه . وليست له موهبة الرد على الشكوك ...",{h:"وينبغى أن نعرف أنه ليس كل أحد على مستوى الإرشاد ."},"الذين لهم هذه الموهبة ، لا يصيبهم ضرر سواء فى المشاكل الروحية وسماع الخطايا الجسدية ، أو فى المشاكل العقائدية وسماع الشكوك .","ولكن حيلة الشيطان الماكرة فى هذا الأمر أنه :",{h:"يقدم الإرشاد للذين ليست لهم الموهبة ، ويصيبهم منه ضرر ."}],40:["و يقدمه بأسلوب ضاغط ، يشعرهم به أنه ضرورة ملحة ، وأنه واجب مقدس وأن « من يعرف أن يعمل حسناً ولا يفعل ، فتلك خطية له » (يع ٤ : ١٧) . وما أسهل على القلب المتضع أن يقول فى انسحاق « ولكننى هنا لا أعرف » ، « أنا الذى لم أستطع أن أرشد نفسى ، كيف يمكننى أن أرشد آخرين ؟! » ...",{h:"والشيطان قد يقدم عملاً روحياً ، ليزيل به تأثر عمل روحى آخر ."},"فإن رأى إنساناً قد صلّى صلاة روحية عميقة ، وانسكب فى تأملات حارة أمام الله ، قد يرسل إليه إنساناً يطلب عمل المصالحة بين متخاصمين . لكنها إذا جلس وسط هؤلاء المتخاصمين ، بكل ما فى تصفية الجو من ضوضاء أو شوشرة أو شجار أو عتاب قاس ، تزول آثار الصلاة والتأملات . و يعود هذا المصلى إلى بيته ، وليس فى ذهنه سوى ما سمعه من مناقشات حامية ، ربما تجعل عقله يسرح إذا صلّى . وتحتاج أمثال هذه المواقف إلى إدماج الصلاة فيها ، وإلى تمهيدات روحية بعدها قبل الوقوف أمام الله للصلاة ...",{h:"وقد يرى الشيطان أن صلاتك حافلة بالتأملات ، فيريد تشتيتها :"},"فماذا يفعل ؟ يقول لك وأنت تصلى « إن هذا التأمل عجيب جداً وعميق ، وإن سمعه آخرون سيستفيدون منه . فلئلا تنساه ، قم الآن واكتبه . وهكذا يكون قد أخرجك من الصلاة إلى الكتابة ، وقطع وقفتك المتخشعة ـ أمام الله ، لكى تجلس وتكتب ، مهتماً بالآخرين أكثر من اهتمامك بالوقوف فى حضرة الله ...","وفى كل ما يجذبك إليه الشيطان من فضائل أخرى ، يكون هدفه :",{h:"يفقدك ما عندك ، مغرياً إياك بفضائل أخرى ليست معك ."},"أو هو يفقدك الثابت الذى فى يدك ، من أجل وعود فى أشياء قد لا تتم . أو قد يسمح لك ببعضها لكى يسحبه منك فيما بعد ...",{h:"٣ ـ إستخدام الفضائل فى غير موضعها"},"يقول الكتاب « لكل أمر تحت السموات وقت » (جا ٣ : ١) . فإذا استخدمت الفضائل فى غير وقتها وفى غير موضعها ، ربما تأتى بنتيجة عكسية ، ولا تخدم الغرض الروحى . وهذا بعض ما يقدمه الشيطان ضمن حيله الكثيرة ."],41:[{h:"فى وقت التوبة ، حينما يلزم الإنسحاق ، يقدّم فضيلة الفرح ."},"و يورد كل الآيات الخاصة بالفرح ، حتى يضيع الندم والإنسحاق والدموع ، كل هذه الأمور اللازمة لحفظ التوبة . وفى نفس الوقت يخفى الآيات الأخرى مثل « طوبى للحزانى الآن ، لأنهم يتعزون » (متى ٥ : ٤) .",{h:"وفى منهجه هذا ، يستخدم طريقة الآية الواحدة ..."},"وقد رفض السيد المسيح هذا المنهج . فعندما قال له الشيطان على الجبل « ... لأنه مكتوب ... » أجابه الرب « مكتوب أيضاً ... » (متى ٤ : ٦ ، ٧) . وهكذا أرانا أن منهج الآية الواحدة الذى يستخدمه الشيطان ، لا يمكن أن يوصل إلى حقيقة روحية سليمة ، طالما هناك آيات أخرى توضح الموضوع .",{h:"وقد يستخدم الشيطان آيات كثيرة فى اتجاه واحد يخدم غرضه ."},"إنه يذكر الآيات الخاصة بالرحمة ، حينما يلزم الحزم وتلزم العقوبة . و يذكر الآيات الخاصة بالعقوبة حينما يلزم العفو والحنو والرحمة .","ويحاول أن يقنع الإنسان بالصمت ، و يورد نصوصاً عديدة من الكتاب ، مستخدماً إياها فى الوقت الذى يجب فيه الكلام . كذلك يورد آيات عن فائدة الكلام وأهميته ، فى الوقت الذى يحسن فيه الصمت ...",{h:"كذلك يورد للإنسان آيات لا تناسبه ، وهى خاصة بغيره ."},"فهناك آيات خاصة بالرسل ورجال الكهنوت ، لا تنطبق على العلمانيين ، يقدمها لشخص عادى كما لو كانت تخصه هو ... مثل قول المسيح لتلاميذه الإثنى عشر « لا تدعوا لكم أباً على الأرض ... » (متى ٢٣ : ٩) .","ومثال ذلك أيضاً ذلك الشخص العنيف الذى كلما كان يرى شخصاً مخطئاً ، كان ينهال عليه ضرباً !! وذلك لأن الشيطان وضع فى أذنيه الآية التى تقول « فى أوقات الغدوات كنت أقتل جميع خطاة الأرض ، لأبيد من مدينة الرب جميع فاعلى الإثم » (مز ١٠١ : ٨) . من حيل الشيطان أيضاً فى محاربة البشر :"],42:[{h:"٤ ـ التشكيك"},"إن الشيطان يزرع الشكوك فى كل مجال من مجالات الحياة . لأن الإنسان فى حالة الشك يكون ضعيفاً يمكن للشيطان أن ينتصر عليه .",{h:"فهو مثلاً يغرس الشك من جهة التوبة ."},"سواء من جهة إمكانية التوبة ، أو من جهة قبول الله لها .","فهو يصور للإنسان أنه ليس من السهل عليه أن يتخلص من هذه الخطايا ، التى صارت طبيعة فيه ، أو عادة من عاداته ، أو صارت محبوبة لديه لا يمكنه مطلقاً الإستغناء عنها . وإذ يغرس فيه الشك الكامل فى قدرته ، يخفى عنه تماماً معونة الله ، أو يشككه فيها أيضاً ، كما قال داود النبى « كثيرون قاموا علىّ . كثيرون يقولون لنفسى : ليس له خلاص بإلهه ... » (مز ٣) .","أما إن صمم الإنسان على التوبة ، فإنه يشككه فى قبول الله لتوبته : إما لأنها أتت بعد فوات الفرصة ، أو لأنها توبة غير حقيقية ، أو لأن خطاياه بشعة من الصعب مغفرتها ! وتحتاج إلى عقوبات فوق احتماله !",{h:"وكل هدف الشيطان هو إلقاء التائب فى اليأس ."},"لكى تخور عزيمته ، ويبقى فى الخطية حيث هو ...","وكذلك يشككه الشيطان فى رحمة الله ، و يورد له آيات لا تحصى عن عدل الله ، وعن عقوباته . وربما تكون عقوبات عن خطايا أقل من خطاياه هو بكثير .","وشكوك الشيطان قد تدخل فى الحياة الشخصية أيضاً .",{h:"فهو يغرس الشك فى أيها أفضل : البتولية أم الزواج ."},"وأى طريق منها يختاره الإنسان يشككه فيه كذلك .","فإن اختار البتولية يشككه فى إمكانية الحياة فيها ، وكيف أنها صعبة جداً ، وهى فقط « للذين أعطى لهم » (متى ١٩ : ١١) ، « وكل واحد له موهبته الخاصة من الله » (١كو ٧ : ٧) . فما أدراك أن هذه موهبتك ؟! و يشرح له السقطات التى وقع فيها القديسون . و يقول له : هل أنت أفضل من داود ومن شمشون ، وكلاهما حل روح الرب عليه ؟!"],43:["وإن اختار الزواج ، يقول له : لقد فقدت إكليل البتولية . و يضع أمامه قول القديس بولس الرسول « غير المتزوج يهتم فيما للرب كيف يرضى الرب . أما المتزوج فيهتم فيما للعالم كيف يرضى إمرأته » (١كو ٧ : ٣٢ ، ٣٣) ، « ومن لا يزوج يفعل أحسن » (١كو ٧ : ٣٨) .","وهكذا يتركه فى بلبلة لا يعرف أى الطريقين يختار ... !",{h:"وهو يغرس الشكوك أيضاً فى موضوع الوحدة والخدمة ."},"إن اختار الإنسان طريق الوحدة ، يشرح له أمجاد الخدمة ، وكيف أنها طريق الرسل وأبطال الإيمان ، وأن « الذين ردوا كثيرين إلى البريفسيون كالكواكب إلى أبد الدهور » (دا ١٢ : ٣) ، وأنه « لا يوقدون سراجاً و يضعونه تحت المكيال ، بل على المنارة ، فيضىء لكل من فى البيت . فليضىء نوركم هكذا قدام الناس ... » (متى ٥ : ١٥ ، ١٦) .","وإن اختار الإنسان طريق الخدمة ، يقول له الشيطان : لقد فقدت طريق الملائكة الأرضيين ، وحياة السكون والهدوء التى يتفرغ فيها الإنسان لله وحده . أما أنت فقد اخترت طريق مرثا التى وبخها الرب بقوله « أنتِ تهتمين وتضطربين لأجل أمور كثيرة ولكن الحاجة إلى واحد » . ولم تختر طريق مريم التى جلست عند قدمى المسيح ، واختارت النصيب الصالح (يو ١٠ : ٤١ ، ٤٢) . و يذكره بالرؤيا التى ظهر فيها أن أرسانيوس المتوحد كان أفضل من موسى الأسود محب الأخوة وخادمهم .","وهكذا يستمر الشيطان فى غرس الشكوك . وكما قال يوحنا الدرجى : الراهب الذى يعيش فى الوحدة ، يحاربه الشيطان بمحبة الأخوة وخدمتهم . والراهب الذى يخدم الأخوة فى المجمع ، يحاربه الشيطان بمحبة الوحدة وحياة السكون والصلاة والتأمل .",{h:"والشيطان يغرس الشكوك فى العلاقات الإجتماعية كلها ."},"فهو يغرس الشكوك بين الزوج وزوجته ، وبين الصديق وصديقه ، وبين الشركاء فى العمل ، وبين الرئيس ومرؤسيه . يشكك فى محبة الواحد للآخر ، أو فى إخلاص وأمانة الواحد للآخر . بل يشككك فى كل تصرفات الناس ، وفى نياتهم ومقاصدهم . وكل ذلك لكى يزعزع صلات الناس ببعضهم البعض ، ويحولها إلى إنقسامات ونزاعات ، و يضيع الحب الذى هو عماد الحياة الروحية والإجتماعية كلها ..."],44:["حتى الأمور التى يمكن أن تمر ببساطة ، يعقدها الشيطان بشكوكه العديدة ، وقد يخلق منها مشاكل عويصة ... !",{h:"وهو يشكك أيضاً فى الإيمان ذاته وفى العقائد ."},"وكل البدع والهرطقات التى قاست منها البشرية هى من صنع الشيطان ومن أفكاره ، وكذلك كل المذاهب المتعددة وما بينها من صراعات . والإلحاد أيضاً هو من صنع الشيطان ...",{h:"والشيطان أيضاً يشكك فى إمكانية الحياة مع الله ."},"و يشرح أن الحياة الروحية صعبة وغير ممكنة . فمن من الناس يستطيع أن يسير فى الطريق الكرب ، أو أن يدخل من الباب الضيق (متى ٧ : ١٣ ، ١٤) . ومن يستطيع أن يصل إلى حياة الكمال التى يطلبها الرب منا (متى ٥ : ٤٨) . ومن يستطيع أن ينجو من حروب الشياطين ؟!","وفى كل ذلك يخفى عمل النعمة وعمل الروح القدس فى خلاص الإنسان ، ويخفى معونات الله الكثيرة !!",{h:"والشيطان قد يغرس فى القلب شكوكاً حول أب الإعتراف ."},"فيشككك فى مدى إهتمام أب الإعتراف بالمعترف ، ومدى محبته له ، ومدى كتمانه لأسراره ، و يشككك فى إرشاداته وصحتها وصلاحيتها للنمو الروحى . يشككك فى معرفته ، وأيضاً فى روحانيته . وهو يريد بكافة الطرق أن يبعد ضحيته عن أب الإعتراف ، الذى يكشف له حروب الشياطين وحيلهم ومكرهم . و يبقى المسكين بلا مرشد فيصبح فريسة سهلة للشياطين .","إنه يشككه فى أب الإعتراف ، لكى يخالفه ، أو يتركه ، أو أن يخفى عنه تدابيره . وكلها وسائل خاطئة . وقد يشككه أيضاً فى سر الإعتراف ذاته . و يقول له : لماذا تعترف على إنسان مثلك ؟!",{h:"وقد يشككه فى الفضيلة ذاتها ..."},"فيقول له مثلاً ما لزوم الإتضاع والوداعة ؟ إنها يضعفان شخصيتك ! وما معنى أن تترك حقك ، ولا تأخذه بالقوة ، حتى يتلاعب بك غيرك ... ؟ وهكذا مع باقى الفضائل .","أما أنت فلا تقبل الشكوك . وكلما أتاك شك ، قل : هذا من عمل الشيطان ..."],45:[{h:"ولا تقبل الشك داخلك ، ولا تستعمله ، ولا تدعه يستمر ..."},"إن كنت كفؤاً لمناقشته ، ناقشه واثبت زيفه ، واطرحه خارجاً . وإلا ، أطلب من الله أن يرفعه عنك . وتذكر قول الكتاب « كونوا راسخين ، غير متزعزعين » (١كو ١٥ : ٥٨) .","وأرجو بنعمة الله أن أحدثك عن الشكوك فى مناسبة أخرى ، بنطاق أوسع ، حينما نتحدث عن الحروب الروحية ، واحدة فواحدة بالتفاصيل .","سلاح آخر من أسلحة الشيطان فى حروبه ، هو :",{h:"٥ ـ حرب اليأس"},"اليأس حرب يلجأ إليها الشيطان بعد مقدمات طويلة تمهيدية ...","* وربما تكون هذه المقدمات سقطات متتالية يوقع فيها ضحيته ، بلا هوادة ، حتى يصرخ أخيراً ويقول لا فائدة فى . من المستحيل أن أخلص طالما أنا هكذا ... !","* وقد تكون هذه المقدمات إيحاءات يغرسها فى نفسه باستمرار ، باسم التواضع ! يقول فيها لنفسه كل يوم « أنا ضعيف وعاجز ، وكلى خطية » ... ولكن بدلاً من أن يوصله إلى الإتضاع ، يقوده إلى صغر النفس ، والشعور بأنه لن يقوم ثانية ...","* وربما تكون مقدمة حرب اليأس ، هى سقطة كبيرة (مثل سقطة يهوذا) يشعره الشيطان بعدها بأنه لا مغفرة ! أو قد لا تكون السقطة بهذه الدرجة ، ولكن ...",{h:"من عادة الشيطان أن يضخم فى الأخطاء ليوقع صاحبها فى اليأس ."},"والشيطان ماكر جداً فى هذه الناحية . فهو قبل السقوط يسهّل موضوع الخطية جداً ، حتى لتبدو شيئاً عادياً ، و يضع لها مبررات ... أما بعد الخطية ، إما أن يستمر فى سياسة التهوين لكى تتكرر ، وإما أن يدخل فى أسلوب التهويل ليوقع صاحبها فى اليأس . و يقول له : هل من المعقول أن يغفر الله خطية مثل هذه ؟",{h:"وربما يشعر الخاطىء أنه وقع فى التجديف على الروح القدس !"},"وهكذا لا تكون له مغفرة إلى الأبد (مر ٣ : ٢٩) . وطبعاً لا تكون لتلك الخطية أية علاقة بالتجديف على الروح القدس . فالتجديف على الروح هو طرد الروح القدس"],46:["من القلب ، طرداً كاملاً دائماً مدى الحياة . وهكذا لا تكون للإنسان توبة ، وبالتالى لا مغفرة . لأن المغفرة مرتبطة بالتوبة ، والتوبة مرتبطة بعمل الروح فى القلب .",{h:"وقد يجره إلى اليأس ، بإشعاره أنه لن يتوب ... !"},"يقول له : « هل من المعقول أنك ستترك الخطية ؟! مستحيل . لقد صارت تجرى فى دمك . عزيمتك إنتهت ، وإرادتك إنحلت . بل حتى مجرد الرغبة فى التوبة أصبحت غير موجودة عندك ... كم مرة حاولت أن تتوب ، وفشلت ؟! كم مرة إعترفت بخطاياك ، ورجعت إليها وربما بدرجة أسوأ ؟ ... » وهكذا يحطم معنوياته إلى أن يستسلم له ، و يتوقف عن المقاومة .","يقول له : إنك قد صرت بكليتك فى يدىّ . أنقلك من هذه اليد إلى الأخرى ، بكل سهولة ، كما أشاء . فلا داعى إذن لصراع فاشل لا تكسب منه شيئاً .",{h:"وطبعاً كل هذه تخاويف لا أساس لها ، وتهديدات زائفة ..."},"فإن الله قادر أن يمنح الإنسان التوبة ، مهما كانت حالته سيئة . والتاريخ يحكى لنا الحالات السيئة جداً التى كانت فيها مريم القبطية ، وبيلاجيه ، وأغسطينوس ، وموسى الأسود . ومع ذلك تابوا . وليس هذا فقط بل صاروا قديسين ...","ومع ذلك فكلما سقط الإنسان ، يحاول الشيطان إلقاءه فى اليأس .",{h:"ويقنعه بأن هذا سقوط دائم أبدى ! وليس سقوطاً طارئاً ."},"فما أجمل كلمة العزاء فى سفر ميخا النبى « لا تشمتى بى يا عدوتى . ( فإنى ) إذا سقطت أقوم » (مى ٧ : ٨) . والكتاب يقول إن « الصديق يسقط سبع مرات و يقوم » (أم ٢٤ : ١٦) . ومع هذا السقوط الكثير ، سماه الكتاب صديقاً ...",{h:"ومن وسائل الشيطان فى اليأس ، ضربه لنا فى أوقات روحية ."},"وهذه من حيله المشهورة ، حتى باتت معروفة للكثيرين . ومثال ذلك :","تكون فى سهرة روحية طول الليل فى الكنيسة ، فى بدء عام جديد ، وكلك رغبة وتصميم أن تبدأ حسناً بعام مبارك مقدس . وتحضر السهرة والقداس وتتناول . ثم تخرج لكى يرسل لك الشيطان إنساناً متعباً جداً يعكر دمك و يشيرك ، ويجعلك تغضب وتخطىء . وحينئذ يضربك الشيطان باليأس ، فتقول : أبعد كل هذا أسقط ! إذن لا فائدة ."],47:[{h:"كلا ، لا تيأس . فهذه هى حيله المعروفة ."},"قل كما قال النبى « إنى إن سقطت أقوم » ...","واعرف أن الشيطان لا يهدأ فى حربه . فى أول كل عام جديد ، وفى كل يوم روحى ، وبعد كل صلاة روحية ، وفى بداية كل صوم ، وبعد كل تناول ... توقّع منه ضربة لإسقاطك فإن فعل ، قل له إلعب لعبة أخرى ، فقد صارت ألاعيبك هذه مكشوفة ...","صدقونى إن الحروب فى المناسبات الروحية ، لا تحصى ... وقد تكون هذه الحروب مجرد حسد من الشيطان لعملك الروحى أو لنجاحك .",{h:"ومن وسائل اليأس ، أن الشيطان يغرى الإنسان بمستويات أعلى منه ."},"يضربه ضربات يمينية ، ويقنعه بمستويات روحية لا يستطيع الوصول إليها ، ويشجعه على ذلك بكل قوة . فإن نصحه أب اعترافه بالتدرج حتى يصل ، وأراد أن يقلل من هذا المستوى ، يشككه فى أب اعترافه ومستواه الروحى .","وما أسهل أن يسلك الإنسان يومين أو ثلاثة أو أكثر فى درجة عالية ، على غير أساس ، ثم لا يستطيع أن يستمر ، و يفشل . وهنا يبدأ الشيطان أن يعيّره و يلقيه فى اليأس ، و يقول له : إنك لا تصلح للطريق الروحى ! طبيعتك لا تتفق مع الحياة الروحية السليمة . و يستمر فى تحطيم نفسيته ... بينما لو تدرج ، كما نصحه أب الإعتراف ، لاستطاع أن يصل إلى هذا المستوى الذى أراده الشيطان أن يبدأ به .",{h:"لقد استطاع الشيطان أن يقنع الكتبة والفريسيين بأن يسلكوا بأسلوبه ."},"فكانوا فى إرشادهم الروحى « يحزمون أحمالاً ثقيلة عسرة الحمل ، و يضعونها على أكتاف الناس . وهم لا يريدون أن يحركوها بأصبعهم » (متى ٢٣ : ٤) . وهذه الأحمال الثقيلة تدفع أحياناً إلى اليأس ، إذ قد يقول حاملها : من يقدر على هذا ؟ من يستطيع أن يخلص ؟!",{h:"أما الرسل القديسون فلم يفعلوا هكذا ، بل رأوا فى قبول الأمم « أن لا يثقّل على الراجعين إلى الله من الأمم » (أع ١٥ : ١٩) ، وأرسلوا إليهم قائلين « لا نضع عليكم ثقلاً أكثر ، غير هذه الأشياء الواجبة » (أع ١٥ : ٢٨) . وقد قال القديس بولس الرسول « سقيتكم لبناً لا طعاماً ، لأنكم لم تكونوا بعد تستطيعون » (١كو ٣ : ٢) ."}],48:[{h:"لذلك إن أغراك الشيطان بما فوق مستواك ، فلا تقبل ."},"قل له : إذهب عنى يا شيطان ، فإن لى مرشدى الروحى الذى أسمع له . أما أنت فلا تقصد بى خيراً . ولك طرقك بلا نظام ، ولا توصل .","يروى عن القديس الأنبا أنطونيوس أن الشيطان أيقظه ذات ليلة لكى يصلى ، فلم يقبل القديس نصيحته . وقال له : أنا أصلى حينما أريد ، ومنك لا أسمع ...","إن الشيطان يرفع الإنسان لكى يسقطه . وإن سقط يدفعه إلى اليأس فى شماتة . وحرب اليأس هامة بالنسبة إلى الشيطان ...",{h:"فالإنسان حينما ييأس ، تتحطم روحه المعنوية ، ويفقد ثقته بنفسه ، وثقته بالله ، وثقته بإمكانية الحياة الروحية ، ويستسلم للسقوط ..."},"وهذا هو عين ما يريده الشيطان . لكيلا تقاومه فريسته ، فتهلك . وكأنه يقول لهذا الإنسان اليائس المستسلم له : إنك لن تفلت من يدى . أنت ذاهب إلى جهنم لا محالة . فلا فائدة . ولذلك نصيحتى لك أن تتمتع بالدنيا بضمة أيام ، بدلاً من أن تخسرها دنيا وآخره ... !",{h:"يقنعه الشيطان بصعوبة الحياة الروحية ، وبأنه ضعيف وطبيعته فاسدة ! كما يقنعه بأنه لن يفلت من يده ، ولا من العدل الإلهى ..."},"هذه هى أكبر أسلحة الشيطان فى حرب اليأس . والرد على كل ذلك بسيط . وهو أننا لا نحارب بإرادتنا الطبيعية ، لأن الحرب للرب (١صم ١٧ : ٤٧) ، وهو الذى يقودنا فى موكب نصرته (٢كو ٢ : ١٤) . وإن كنا نحن لا نستطيع ، بسبب ضعفنا وفسادنا وصعوبة الطريق ، فإننا نستطيع كل شىء فى المسيح الذى يقوينا (فى ٤ : ١٣) . يسندنا عمل النعمة ، وقوة الروح القدس العامل فينا ، وملائكة مرسلون لمعونتنا (عب ١ : ١٤) . وتسندنا شفاعة القديسين فينا ...","أما الشيطان فلا سلطان له علينا ، ولا نعبأ بتهديده ، وما أجمل قول الرسول « قاوموا إبليس فيهرب منكم » (يع ٤ : ٧) . أما العدل الإلهى فقد وفاه الرب على الصليب ، وقد قدّم لنا فى حبه خلاصاً هذا مقداره (عب ٢ : ٣) . ونحن « إن اعترفنا بخطايانا ، فهو أمين وعادل ، حتى يغفر لنا خطايانا ، و يطهرنا من كل إثم » (١يو ١ : ٩) . و يغسلنا فنبيض أكثر من الثلج (مز ٥٠) . وهو الذى قال لنا « إن كانت"],49:["خطاياكم كالقرمز ، تبيض كالثلج ... » (إش ١ : ١٨) .",{h:"إن حرب الشيطان هى اليأس ، بالطرق التى وحدنا عليها ."},{h:"أما الكتاب فإنه يشجعنا . ويجعل الرجاء من الفضائل الكبرى (١كو ١٣ : ١٣) ."},"وكثيرة هى وعود الله لنا وللكنيسة : إن أبواب الجحيم لن تقوى عليها (متى ١٦ : ١٨) . وإننا « بقوة الله محروسون » (١بط ١ : ٥) . وأنه قد نقشنا على كفه (إش ٤٩ : ١٦) . والكتاب يقول إن « الله لم يعطنا روح الفشل ، بل روح القوة ... » (٢تى ١ : ٧) . ولذلك نصحنا الرسول أكثر من مرة بأننا « لا نفشل » (٢كو ٤ : ١٦ ، غل ٦ : ٩) .",{h:"إن كنت ماشياً فى الطريق الروحى ، ووقعت ، لا تظن أنك لا تعرف المشى ، وتيأس ! بل قم وأكمل المسير ..."},"إن الشيطان يحسد خطواتك ويريد أن يعرقلها . فلا تدفعك عراقيله إلى اليأس . بل على العكس ، قم بقوة أكثر . واعرف أنه لولا نجاحك فى العمل الروحى ، ما كان الشيطان يحاربك ! حقاً ، لماذا يتعب الشيطان نفسه فى محاربة الساقطين ؟! إنه يتصدى بالحرى للقائمين ، وللذين يخاف جهادهم ضده .","إستمع إذن إلى قول الرسول « كونوا راسخين غير متزعزعين » (١كو ١٥ : ٥٨) .",{h:"كن قوى القلب بالله ، ولا تيأس ..."},"لا تيأس مهما كانت حروب الشيطان قوية .","ولا تيأس مهما سقطت ، ومهما نسيت الوصية ، ومهما فشل التدريب .","لا تيأس إذا كانت البداءة التى بدأت بها بداءة ضعيفة ، أو بداءة ساقطة ، أو بداءة ضائعة .","قل لنفسك : كل هذه مجرد حروب ، وأنا سأثبت فى الله .",{h:"سأسير نحو الله ، وإن كنت أجرّ رجلىّ جراً إليه ..."},"مهما سقطت مائة مرة فى الطريق ، سأقوم وأكمل طريق ...","ولن أقبل اليأس مطلقاً . إنه من عمل الشيطان .","ننتقل إلى حيلة أخرى من حيل الشيطان وهى أن :"],50:[{h:"٦ ـ الشيطان يغير خططه"},{h:"إن الشيطان لا يصر على خط معين فى محاربته للإنسان . إنما ما أسهل أن يغيّر خطه وخططه ، إن كان ذلك يوصله إلى إسقاط من يريد ."},"وسنضرب لذلك بعض أمثلة :","أ ـ شاب كان يحاربه الشيطان بالزنا حرباً عنيفة ويتعبه فيها ويسقطه أحياناً . فبدأ هذا الشاب فى حياة توبة ، وأصبح يحترس من هذه الخطية بالذات إحتراساً شديداً : يبعد عن كل أسبابها . ويسد كل الأبواب التى تأتى منها الخطية ، سواء كانت من القراءات أو السماعات أو اللقاءات . وفى نفس الوقت يقوى نفسه من الداخل بكل الوسائط الروحية ، و يصلى إلى الله بدموع لكى ينقذه ...","فماذا يفعل الشيطان إزاء هذا الحرص الشديد من خطية الزنا ؟",{h:"يقول : أتركه الآن ، لا أحاربه بهذه الخطية فترة طويلة ، حتى يظن أنه انتصر عليها تماماً ، فلا يحترس من جهتها . ولنحارب حالياً بخطية أخرى ..."},"و يتركه سنة أو إثنتين أو ثلاثاً ، بلا حروب فى هذه الخطية ، بلا عثرات ، بلا أفكار . و يلقيه مثلاً فى خطية كالكبرياء ...","يرى المسكين أنه نجا من الزنا ، فيفرح . و يغريه الشيطان بمستوى عال فى الصوم ، فى القراءة ، ثم فى الخدمة ، وفيما هو مستريح الفكر من الخطية ، ومستريح فى منهجه الروحى ، يدعوه الشيطان إلى تطبيق هذا المستوى على غيره . و يريه أنهم مقصرون ، وأنه فاقهم بمراحل ، فيوقعه فى الكبرياء . ويدعوه الى توبيخهم وتبكيتهم وإدانتهم : أبوك لا يصلى . أمك لا تصوم . إخوتك لا يتناولون . أسرتك لا تقرأ الكتاب . إذهب وبّخهم ، وبشدة ...","ويمتد نطاق التوبيخ واحتقار الآخرين ، وشتيمة واحتقار هؤلاء وأولئك ، لأنهم بعيدون عن الله ، مع تعالى القلب بما وصل إليه . وفيما هو يحاول أن يخلع الزوان ، يصير هو نفسه زواناً . إذ أصبح باسم الحق يشتم ، ويحتد ، ويدين ، ويحتقر ، ويتعالى على غيره ، ويسبح فى الغرور والكبرياء ، يقول كالفريسى « أشكرك يارب إنى لست مثل سائر الناس ... » (لو ١٨ : ١١) ."],51:["وتسأل الشيطان عن خطية الزنا التى أراح منها هذا الشاب ؟",{h:"فيجيب : الذى يهلك بالكبرياء ، كالذى يهلك بالزنا . كلاهما هالك ."},"أليس أن الذى يموت بالسلّ ، كالذى يموت بالسرطان ، كالذى يموت فى عملية جراحية ؟ كله موت ... والنهاية واحدة ... « تعدد الأسباب ، والموت واحد » ...","أما حرب الزنا التى يظن هذا الشاب أنه قد نجا منها ، ففى الحقيقة أن لها يوماً تعود فيه إليه ، حينما يقل إحتراسه من جهتها ، و يقل حرصه واجتهاده فى مقاومتها . حينئذ نضربه الضربة فلا يفيق منها . وتسأله كيف ؟ فيقول :","فى الفترة التى استراح فيها الشاب من حرب الزنا ، ظن أنها فارقته بلا عودة ، ولم يعد لها وجود فى حياته ، وأنها من الخطايا التى تحارب المبتدئين فقط . ولا يعقل أن تحارب المستويات العليا التى وصل إليها ! بل إن كثيرين أصبحوا يسترشدون به فى مقاومة هذه الخطية .","وهكذا أصبح يسمع تفاصيل عن هذه الخطية ما كان يسمح لنفسه أن يسمعها من قبل . وبعض أمور خافية عن معرفته ، صار يقرأ لها كتباً فى هذا الموضوع المعثر ، ليرد على أسئلة سائليه ، وما كان يقرأ هذه القراءات مطلقاً فى فترة حرصه واحتراسه !","وهكذا امتلأ ذهنه بأفكار صارت تترك فى نفسه مشاعر وتأثيرات ، تنمو بمرور الوقت وهو لا يدرى . إلى جوار أنه بسبب الكبرياء وإدانة الآخرين ، بدأت النعمة تتخلى عنه . وهنا أتت الساعة التى يضربه فيها الشيطان بهذه الخطية بالذات . و يسهل عليه إسقاطه . وتكون خطة الشيطان قد نجحت على الرغم من تغييرها فى الطريق ...",{h:"وهنا يقول الشيطان : إننى أرحته زمناً من هذه الخطية ، لكى لا يستعد لها . وحينما لا يستعد لها ، لا يدقق . وفى عدم تدقيقه يتساهل مع الخطية وأفكارى . وفى هذا التراخى وتساهله معى ، أضربه بالخطية التى استراح منها سنوات ، فيسقط بسهولة ."},"هذا هو الشيطان ... ! قد لا يحاربك الآن بخطية معينة ، ليس محبة منه لك ، إنما لأنه يجهز لك فخاً من نوع آخر .","ب ـ مثال آخر : إنسان آخر ساقط فى خطية الغضب ، وخطية الإدانة ، وخطايا السب والكلام الجارح . بدأ يستيقظ لنفسه ، ويدخل بقوة فى تداريب صمت ،"],52:["ليتخلص من خطايا اللسان جملة . فماذا يفعل الشيطان ؟",{h:"يقول : لا مانع من أن نغير الخطة . وبدلاً من محاربته بخطايا اللسان والغضب ، نحاربه بخطية الغرور مثلاً ..."},"بحيث يقتنع تماماً ، أنه لا يوجد إنسان أفضل منه . وكيف ذلك ؟ نريحه من خطايا اللسان تماماً ، فلا نحاربه بها الآن مطلقاً . وننصحه بشىء من النمو الفجائى فى العمل الروحى ، بلون من المغالاة ، ولا نحاربه فى ذلك .","و يظن أن لا يوجد مثله ، فيسلك فى الغرور . وربما يختلف مع أب اعترافه الذى لا يوافقه على تطرفه وغروره ، فلا يأبه . و يصبح فى وضع لا يخضع فيه لأحد ، ولا يطيع أحداً ، ولا يستشير أحداً ، ولا يحترم أحداً .","والغرور يسقطه ويهلكه ، بدون السقوط فى خطايا اللسان .","ومع ذلك فالغرور سيجعله يصطدم بالآخرين . ولا بد سيقع فى خطايا اللسان ، حتى بدون شيطان ! فكم بالأولى إذا حاربه الشيطان بها ...",{h:"إن الشيطان يعدّل خطته باستمرار . ينظر إلى حالة الإنسان ، ويختار له السقطة التى تناسبه . إنه يعرف متى يحارب ، وكيف يحارب ، وبأى نوع ... ؟"},"والذى لا يسقط بهذه الطريقة يسقط بغيرها .","والذى لا يسقط فى هذه الخطية الآن ، مصيره أن يسقط فيها هى بذاتها ، فيما بعد ، والفخاخ كثيرة ، موجودة ومنصوبة .","ج ـ مثال ثالث فى كيف يغيّر الشيطان خططه :","بدأ الصوم الكبير . وكان الشيطان فى العام الماضى يقاتل شاباً بترك الصوم ، فلم تنفع معه كل المحاربات :","* قال له ليشككه فى الصوم : ما معنى أن تصوم عن الأطعمة الحيوانية ؟! صم بالأحرى عن الخطية ، وحارب الحيوان الذى فى داخلك ... لأنه ما فائدة الصوم بدون طهارة ونقاوة ؟! ألا يكون صومك غير مقبول ؟!","ـ فأجاب الشاب : بل أنا أنفذ قول الكتاب « إفعلوا هذه ، ولا تتركوا تلك » (متى ٢٣ : ٢٣) . فأحاول أن أصوم الصومين معاً . أصوّم جسدى عن الطعام ، وأصوّم نفسى عن شهوة الخطية « أقمع جسدى وأستعبده » (١كو ٩ : ٢٧) بمنعه عن الأطعمة"],53:["الشهية ، وأتعود بذلك قهر النفس فلا تخطىء .","* قال الشيطان : ولكنك ضعيف ، وصحتك لا تحتمل الصوم . ولا بد تحتاج إلى البروتين الحيوانى لتعيش ، وبخاصة وأنت فى فترة نمو","ـ فأجابه الشاب بقول الرب « ليس بالخبز وحده يحيا الإنسان » (متى ٤ : ٤) . وتذكّر أن آدم وحواء كانا يعيشان على الثمار والبقول ، ثم عشب الأرض (تك ١ : ٢٩ ، ٣ : ١٨) . ولم يقل الكتاب إنها مرضا لنقص البروتين الحيوانى ! ...","* قال الشيطان : لا مانع إذن من أن تصوم . ولكن لا داعى لأن تصوم الصوم كله من أوله ، فهذا كثير . وأيضاً لا تضغط على نفسك فى الصوم ، لئلا يحاربك الشيطان بالمجد الباطل ! وأنت تعرف حروب الشياطين ، وخطورة ضربات اليمين .","ـ أجاب الشاب : لا أريد أن أتهاون . فالرب يدعونا إلى الكمال (متى ٥ : ٤٨) . ومهما صمت ، ماذا يكون صومى إذا قورن بأصوام القديسين ؟! إنه لا شىء ...","وصام الشاب . وحل الصوم هذا العام ، والشاب فى تصميمه .",{h:"ورأى الشيطان أن محاولة منع هذا الشاب عن الصوم ستكون محاولة عقيمة . لذلك بدأ يغيّر خطته إلى العكس ."},"* فقال للشاب : ما أفيد الصوم ! إن عمق فائدته تأتى من طول فترة الإنقطاع . ومن رأيى أن تنقطع كل يوم إلى الغروب من بدء الصوم .","ولكن لا بد أن تستشير أب اعترافك وتأخذ موافقته (وكان يعلم يقيناً أن أب الإعتراف لن يوافق) ... وهنا نصب له فخاً .","ولم يوافق أب الإعتراف ، ودعا الشاب إلى التدرج ...","* وهنا تدخل الشيطان ليقول : إن أب اعترافك هذا ، لا خبرة له بالصوم . وهو بإرشاده يعطل حياتك الروحية . و بطريقته هذه لا يمكن أن تنمو ، ولا أن تذوق حلاوة الصوم . بل أخشى عليك إذا ضغطت الظروف ، أن ينصحك يوماً بأن تفطر فى أسبوع الآلام !! والأفضل أن تغير أب اعترافك . ومن الممكن فى أمور الصوم وأمثالها ، أن لا تستشير أب الإعتراف ! أترك هذه الأمور أصرّفها معك بنفسى !","وهكذا غيّر الشيطان خطته ، من تشكيك فى الصوم ، إلى تشكيك فى أب"],54:["الإعتراف . ليس المهم عنده نوع الحرب ، إنما أن يسقط من يحاربه .","وبتحويل الشاب عن أب اعترافه ، جعله يسلك حسب هواه بلا مرشد ، مع كبرياء فى القلب يظن بها أنه أفضل من مرشده ، مع إدانة لهذا المرشد . وكل هذه وسائل تجره فى طريق السقوط إلى أسفل .","د ـ مثال رابع : شيطان المجد الباطل :","إنه شيطان يغيّر أسلوبه باستمرار ، ليطابق أى حال يراه ...",{h:"وصف بأنه شيطان مكوّر ، أى كالكرة يتقلب فى أى وضع ."},"وهو فى ذلك غير المكعب الذى لا بد أن يستقر على قاعدة معينة . أما المكور فحيثما تقلبه أو توجهه ، يتحرك ، على كل وجه ، كالكرة .","إن كنت جالساً إلى المائدة ولم تأكل ، يقول لك « يعجبنى نسكك هذا ، إنك لا تأكل كسائر الموجودين . وإن أكلت مثلهم تماماً ، يقول لك « هكذا القديسون : يتظاهرون بالأكل وهم صائمون ، لكى يخفوا فضائلهم » .",{h:"إن تكلمت ، يقول : إنه كلام الحكمة ، موضع إعجاب السامعين ..."},{h:"وإن صمتّ ، يقول : الصمت فضيلة القديسين مثل القديس أرسانيوس !"},"فكن حكيماً مع هذا الشيطان . ولا تصدقه فيما يقوله ، ولا تتأثر بكلامه وأحكامه . وإن حاربك بمديح نفسك لنفسك ، تذكّر خطاياك وضعفاتك ، وبكّت ذاتك عليها . أو تذكر ما ينقصك فى حياة البر ، حتى تقيم توازناً مع ما تسمعه من مديح ...",{h:"وعموماً ـ بالنسبة إلى أى شيطان ـ إذا غيّر خططه معك ، يمكن أن تغيّر أنت أيضاً خطتك معه ."},"ومثال ذلك ، القديس يوحنا القصير : كان الشياطين يمدحونه على ما وصل إليه من فضيلة ، حتى أن الإسقيط كله كان يطلب منه كلمة منفعة . فيجيبهم : ومن أنا المسكين ؟ ألعلى وصلت إلى ما وصل إليه الأنبا أنطونيوس أو الأنبا بوا ؟! إننى كل خطية . فإن قالوا له : حقاً إنك خاطىء وستهلك ، يجيبهم : وأين ذهبت محبة الله ورحمته ؟!","فكان الشياطين يقولون له « لقد حيرتنا . إن رفعناك إتضعت . وإن وضعناك إرتفعت » ... فكن أنت هكذا فى تعاملك مع الشياطين ."],55:["إن مدحوك ، تذكر خطاياك . وإن أراحوك من محارباتهم ، قل : لعلهم يعدّون لى ، فخاً لا أعرفه . فليرحم الرب ضعفى ...","بل أذكر أنك لم تصل إلى المستوى الذى يحاربك فيه الشيطان . مثل ذلك الأخ الذى شكا للقديس الأنبا بيشوى محاربة الشيطان له . فظهر الشيطان للقديس ، وقال له : من هو هذا الأخ لأحاربه ؟ أنا لم أسمع بعد بأنه قد ترهب !","إن حرب الشياطين الحقيقية حرب شديدة . وربما غالبيتنا لم يتعرضوا لها . والحروب التى تعرض لها القديسون كانت عنيفة ، لا يسمح الله أن نكابدها نحن .","إن شيطان المجد الباطل ، يقدم حرباً أساسها المديح . ولكن هناك طريقة عكسية لهذه تماماً يحارب بها الشيطان أحياناً ، وهى : حرب الكآبة ...",{h:"٧ ـ الكآبة"},"هى نوع من المبالغة الشديدة يحارب بها الشيطان التائبين ، أو الشاعرين بخطاياهم ، أو المنسحقين بقلوبهم ، لكى يجرهم إلى الضياع ...","يختار لهم الشيطان من بين كل آيات الكتاب المقدس آية واحدة يضمها أمامهم باستمرار وهى « بكآبة الوجه يصلح القلب » (جا ٧ : ٣) . و يقول لهم إن الكتاب لم يذكر مطلقاً أن المسيح قد ضحك ، ولكن ذكر أنه بكى مرات ...","وكلما يقع هذا الإنسان فى خطية ، أو يُحارب بشدة فى خطية ، يظل الشيطان يزيده كآبة . و يقول له : أنت لست إبناً لله ، لأنك خاطىء ، والكتاب يقول إن « المولود من الله لا يخطىء » (١يو ٣ : ٩ : ٥ : ١٨) .",{h:"و يقول له : وليس الله فقط ، بل حتى أب اعترافك القديس لا تستحق أن تكون له إبناً . إنك عار عليه . تسىء سمعته ."},"والأفضل أن تترك هذا الأب البار ، حتى لا يعيره الناس قائلين : أنظر ، هذه هى عينة أبنائك . وأيضاً أتركه حتى لا يأخذ دينونة بسببك ، وحتى لا تحزن نفسه باستمرار ، كلما يراك هكذا .","وهكذا يبعده عن الله ، والشعور بأبوته ، و يبعده عن أب الإعتراف ."],56:["وحتى إن أمسك الكتاب المقدس ليقرأ ، يقول له : وهل تتجرأ تمسك كتاب الله بيدك هذه غير الطاهرة . إن كل كلمة فى هذا الكتاب دينونة عليك . لأن السيد المسيح نفسه يقول عنك وعن أمثالك « الكلام الذى تكلمت به هو يدينه فى اليوم الأخير » (يو ١٢ : ٤٨) . وهذا يملأ نفسه بالكآبة ، حتى يترك الكتاب بنفس مُرّة يائسة ...",{h:"وحتى الخدمة ـ إن كان خادماً ـ يبعده عنها كغير مستحق ."},"فيقول له : إن الخدمة هى عمل القديسين وليس الخطاة . وأنت خاطىء لا تستحق أن تجلس فى مكان المعلمين ، وإلا ستكون عثرة ، كما أن الخدمة ستنسيك خطاياك التى يجب أن تضعها أمامك فى كل حين ، وتكتئب عليها ليلاً ونهاراً .",{h:"حتى إن وقف يصلى ، يمنعه قائلاً : « صلاة الأشرار مكرهة للرب » (أم ١٥ : ٨ ، ٢٨ : ٩) ..."},"و يقول له : هوذا المشار وقف بعيداً ، لا يجرؤ أن يرفع نظره إلى فوق (لو ١٨ : ١٣) . وأنت بكل استهتار ولا مبالاة ، تتحدث مع الله ، وأنت كاسر لكل وصاياه . ليتك تخجل من نفسك ، وتبعد عن هذه الصلاة الأثيمة !",{h:"وهكذا يبعده بالكآبة عن كل وسائط النعمة ، لينفرد به ."},"ينفرد به وهو وحيد ، بنفس محطمة ، وليس حوله إنجيل ولا صلاة ، ولا أب اعتراف ، ولا خدمة ولا اجتماعات كنسية ، بل ربما وليس حوله أيضاً أصدقاء ، إذ بعدوا عنه بسبب كآبته ، أو بعد هو عنهم ... وهكذا يصير فريسة سهلة للشيطان .",{h:"وما أسهل أن يقول له : أترك الوسط الدينى لأنه سبب كآبتك !"},"أو ما أسهل أن يرسل له هذه العبارة على أفواه أقاربه ، أو على فم طبيب معالج . و يجذبه بالتدريج إلى وسائل من اللهو للترفيه عنه من كآبته ، ولو إلى فترة مؤقتة ، يطيلها الشيطان بحيله الأخرى ، إلى أن يبعده عن الله تماماً ...","أو أن ألشيطان يسقطه بوسيلة أخرى وهى اليأس . وتكون الكآبة ممهدة لذلك .",{h:"وحيلة الشيطان فى الكآبة ، أنه أبعد فريسته عن الرجاء والمغفرة ."},"أبعده عن وجه الله المحب ، الذى استقبل إبنه الضال بكل ترحاب ، وفرح به ، وجعل الكل يفرحون ، وألبسه الحلة الأولى (لو ١٥ : ٢٢ ـ ٢٤) . بل إن الرب يقول إنه « يكون فرح قدام ملائكة الله بخاطىء واحد يتوب » (لو ١٥ : ١٠) ... حقاً إن"],57:["القديسين بكوا على خطاياهم ، ولكن ليس بغير رجاء . بل إن الكتاب يقول :","« لا تحزنوا كالباقين الذين لا رجاء لهم » (١تس ٤ : ١٣) .","الحزن على الخطية ، لا يفصلنا عن الله ، بل يقربنا منه . و يزيد محبتنا له ، لأنه على الرغم من خطايانا ، غفر لنا . بل قال بالأكثر « لأنى أصفح عن إثمهم ، ولا أذكر خطيتهم بعد » (أر ٣١ : ٣٤) . والله لا يسر بموت الشرير ، بل بأن يرجع ويحيا (حز ١٨ : ٢٣) .",{h:"مشكلة الذى فقد الرجاء بالكآبة ، أنه أخذ مشورة الحية ، الشيطان ."},"أما كلمة الله ، فإنها مملوءة عزاءً . وقلب الله باستمرار مملوء حباً . والكآبة جُعلت لكى تقود إلى التواضع والإنسحاق ، وليس إلى اليأس والإنفصال عن الله . أما إذا استخدم الشيطان هذه الكآبة بطرقه الشريرة ، فإنه لا شك يضيع صاحبها .","ها هو بطرس الرسول بعد أن أنكر المسيح ، ومع أنه بكى بكاءً مراً ، إلا أن السيد المسيح المجد ظهر له ، وقال له « إرعَ غنمى . إرعَ خرافى » (يو ٢١ : ١٥ ، ١٦) . أى رجاء يمكن أن يقال أكثر من هذا . لذلك فإن كآبة الوجه التى تصلح القلب ، ينبغى ألا تنفصل عن الحب وعن الرجاء .","ننتقل إلى نقطة أخرى من حروب الشياطين ، وهى :",{h:"٨ ـ السرعة"},"أعمال الشيطان تتصف بالسرعة ، أو بما يسمونه فى العامية ( جة ) ... بعكس أعمال الله التى تتميز بالهدوء والروية وطول الأناة . وقد تأخذ وقتاً ، ولكنها تكون متئدة وهادئة ، كقصة الخلاص ، ووعود الله ...",{h:"الشيطان يقدم لك فكراً ، ويظل يلح ويلح على تنفيذه بسرعة ..."},"وتشعر حينما يكون الفكر الشيطانى فى داخلك ، بحماس شديد للتنفيذ ، وبنار تتقد فى داخلك ، وحافز يدفعك دفعاً للتنفيذ ، الآن ، وبلا إبطاء ، ودون أن يأخذ الفكر فترة حضانة داخلك ، تناقشه وتفحصه وتبحثه ، وتنظر إليه من جميع الزوايا الأخرى ، وتراجع رأيك فيه ..."],58:[{h:"إنه يقصد بالسرعة أنك لا تفكر ، وأيضاً لا تستشير ."},"يريد بالسرعة أن ينفرد بك ، دون أن يدخل أحد بينكما ، تستشيره وتستفيد برأيه وخبرته وروحياته ، لا صديق ولا قريب ، ولا أب اعتراف ، ولا مرشد روحى ، ولا أى إنسان صاحب خبرة ، إنما بسرعة عليك أن تنفذ ...",{h:"وهو يريد بالسرعة أيضاً ، عدم عرض الأمر على الله بالصلاة ."},"لا يريد أن يعطيك فرصة تصلى فيها من أجل هذا الموضوع ، وترى ماذا يقول الله فيه ، ولا فرصة ترفع فيها قداساً من أجل الموضوع ، أو تصوم طالباً إرشاد الرب ... إنما يلح عليك بالفكر إلحاحاً ، ويقنعك به كأنه بديهية لا تقبل النقاش ... ولذلك قال الآباء :",{h:"كل فكر ، يلح عليك أن تنفذه بسرعة ، هو من الشيطان ."},"وطبعاً لا يقصد بهذا الرغبة فى التوبة والرجوع إلى الله ، والإلتصاق به بالحب ، بل الأفكار الأخرى التى تحتاج إلى مناقشة ، وليست عاجلة (كإنقاذ غريق أو إطفاء حريق) ... وكم من أمور أسرع الإنسان فى تنفيذها . وحينما رجع إلى نفسه ندم على ذلك جداً . وأحياناً تكون أفكار الخطية والشهوة ملحة جداً ، لا تعطى صاحبها فرصة للتفكير وتغيير مجرى مشاعره ...",{h:"الشيطان يقصد بالسرعة أيضاً ، أنه لا ينكشف ..."},"ربما تكون وراء فكرته أو اقتراحه كذبة أو حيلة لا يريد لها أن تنكشف بالتفكير أو بالإستشارة أو بالصلاة . فيلح على إتمامها بسرعة قبل كشفها . ولذلك فإن وجود أب الإعتراف مفيد هنا فى كشف حيل العدو . وقد قيل « الذين بلا مرشد ، يسقطون مثل أوراق الشجر » . لأنهم ينفذون بسرعة قبل أن يستشيروا . يلح عليهم الشيطان إلحاحاً ، فينمرمون فكره ، قبل أن تنكشف حيلته .",{h:"أما أولاد الله ، فإنهم لا يطيعون كل فكر يأتيهم ..."},"مثال ذلك الفكر الذى جاء للقديس مقاريوس لكى يذهب إلى البرية الجوانية ليرى الآباء السوّاح . يقول القديس « فبقيت مقاتلاً لهذا الفكر ثلاث سنوات ، لأعرف هل هو من الله أم لا » ... ما أعجب هذا الأمر ، بالنسبة إلى قديس عظيم كالقديس مقاريوس الكبير ، وبالنسبة إلى فكر روحى كزيارة السوّاح ... !"],59:[{h:"لم ير القديسون فى الإبطاء ضرراً ، بل فيه فائدة ..."},"إنهم لا ينفذون بسرعة لئلا يكون الفكر من الشيطان . وإبطاؤهم فى التنفيذ يعطيهم فرصة للتأكد ، ينتظرون فيها إلى أن يعلن الله رأيه فى الموضوع . وهم فى ذلك يقولون تلك العبارة الجميلة :",{h:"الذى من عند الله يثبت . والذى ليس من الله يزول ."},"وهكذا نرى أن القديس الأنبا غاليون لما ظهر له الشيطان فى هيئة راهب ، وقال له إنه أحد السوّاح ، وأن زملاءه السواح قد ضموه إلى صحبتهم ، ودعاه للسير معه . وأطاعه الأنبا غاليون ، دون أن يأخذ فرصة لعرض الأمر على الله وعلى أب الإعتراف ... حدث أن الشياطين الذين ظهروا فى هيئة سواح أتاهوه فى البرية ، ثم تركوه وهم يهزأون . وقالوا له « ستموت هنا وحدك ، فى هذا القفر » لولا أن الله أنقذه ...","هناك حيلة أخرى للشيطان غير السرعة ، أو هى عكسها . وهى :",{h:"٩ ـ التدرج الطويل"},"تتعدد وسائل الشيطان فى حروبه . وقد يبدو أحياناً شىء من التناقض بين أسلوب وآخر . ولكن يجمعها كلها هدف واحد ، وإن كانت الوسيلة تختلف بحسب نوعية الحالة ... وعموماً فالشيطان لا يحب الوتيرة الواحدة لئلا يألفها الناس .",{h:"فهو أحياناً يضرب ضربة سريعة فجائية ، لا يكون الشخص مستعداً لها . وأحياناً يسير فى تدرج طويل ، بحيث لا يشعر به صاحبه ..."},"والتدرج يلزمه وقت قد يطول . ولكن الشيطان لا يهمه الوقت ، إنما يهمه السقوط . والتدرج يصلح غالباً للأشخاص الذين لا يقبلون خطية معينة بسهولة . ولكنه يوصلهم إليها تدريجياً فى هدوء ، بجرعات قليلة ، أو قليلة جداً ، تزداد بالوقت ، حتى تقضى عليهم .",{h:"وقد يقسم الخطية إلى مراحل . كل مرحلة تثبت أقدامها بالوقت ."},"وربما تكون الخطوة الأولى إلى الخطية ، ليست خطية على الإطلاق ، ولا تتعب الضمير . فالمرحلة الأولى فى سقوط داود النبى ، كانت فى عدم خروجه إلى الحرب"],60:["بنفسه : يرسل الجيش و يبق هو فى بيته . والمرحلة الثانية كانت شيئاً من الترف دخل إلى حياته ، بعد أن كان مشرداً من برية إلى برية أيام مطاردة شاول الملك له ... وهاتان المرحلتان عبرهما داود دون أن يشعر بخطأ .",{h:"ولكن عوامل نفسية كانت تأخذ مجراها داخله وتفقده حرارته الروحية ."},"ثم دخل فى مرحلة ثالثة وهى الإكثار من الزوجات . وكان محللاً فى أيامه ، ولكنه بلا شك هبط به إلى مستوى الجسد . وإن كان مستوى الحلال ، ولكن ليس مستوى الكمال . وصار للجسد سيطرة عليه شعر أو لم يشعر .","المرحلة الرابعة ، أنه صعد إلى السطح ، يتمشى و يتفرج ، ولا مانع من أن ينظر إلى مساكن غيره ، و يبصر خصوصيات الناس . وهنا بدء إنحراف .","المرحلة الخامسة ، كانت ضربة شديدة من الشيطان أوقعت رجل المزامير العظيم فى خطية الشهوة ، ثم فى خطية الزنا .","المرحلة السادسة ، كانت التورط ، الذى أراد به إخفاء خطيئته بجملة من الخطايا أفقدته روحانيته ، وهبطت به من سىء إلى أسوأ .",{h:"وربما هذه المراحل ، كان الشيطان يعد لها منذ زمن ..."},"إنه يحب ـ حينما يضرب الضربة ـ أن تصيب مقتلاً . وهذا يتطلب منه أحياناً تمهيدات طويلة المدى . بحيث حينما يأتى ، يجد البيت مزيناً مفروشاً ، مهيئاً لعمله ، ويجد الضحية جاهزة بلا مقاومة ... وحتى إن قاومت تكون بلا قدرة على الإطلاق ، فتسقط أمامه بسهولة !",{h:"قصة يعقوب المجاهد :"},"إنها تشبه قصة سقوط داود ، فى أنها مثلها تعطينا فكرة واضحة عن خطة الشيطان فى أسلوب التدرج الطويل . وفيها استطاع أن يسقط ناسكاً عظيماً ، وقديساً له موهبة إخراج الشياطين . ولكن الشيطان هنا أمكنه أن يضرب القديس ثلاث ضربات قاتلة ، وكاد يهلكه لولا أن رحمة الله إقتادته إلى التوبة . فكيف حدث ذلك ؟","فتاة ( إبنة ملك ) ، صرعها روح نجس . وعجز الكل عن إخراجه ، فأتوا بها إلى"],61:["القديس يعقوب المجاهد . فصلّى عليها فخرج الروح النجس . ولكن ما أن رجعت إلى بلدها حتى عاد إليها مرة أخرى . فسافروا وأتوا بها إلى القديس ، فصلى عليها فخرج الروح . ولكن ما أن رجعت إلى بلدها حتى عاد إليها . فسافروا إلى القديس مرة ثالثة .",{h:"وتكررت لعبة الشيطان مرات عديدة ، حتى يئسوا من كثرة الأسفار ."},"وأخيراً ، قرر الملك أن تبقى الأميرة إلى جوار القديس . فبنوا لها حجرة . وكان الشيطان كلما يصرعها يدخلونها إليه . وتطور الأمر إلى أن أبقوها معه . ولما اطمأنوا على هدوئها تركوها معه . ومضوا ...","وبمرور الوقت تكونت دالة بينهما ، تطورت إلى الخطيئة . ثم حملت الفتاة منه . ورأى أن الخطية ستنكشف وتضيع سمعته ، وربما يقتله الملك . فوسوس له الشيطان أن يقتلها ، فقتلها ودفنها فى مكان بعيد فى الصحراء .","ومرت شهور ، وجاء رسل الملك للإطمئنان عليها . ولما سألوا القديس ، أخفى جريمته الثانية بالكذب . وقال لهم صرعها الشيطان مرة ، فانطلقت بسرعة هاربة فى الجبل ولم أستطع اللحاق بها ، واختفت ... وصدقوه لأنه لم يكن موضع شك .",{h:"وهكذا ضربه الشيطان ثلاث ضربات ، وأوقعه فى الزنا والقتل والكذب ."},"كل ذلك فى تدرج طويل ، ما كان أوله يوحى مطلقاً بآخره . ولكنها حيل الشيطان الذى يسبك مكيدته فى صبر عجيب .","وسياسة التدرج هذه لها حكمة كبيرة وهى :",{h:"فى كل خطوة يقترب الإنسان إلى جو الخطية ، ويعتاده ، ويضعف . إرادته تكون قوية جداً ، وهو خارج مجال الخطية . وقد يكون نافراً جداً من كل مجالاتها . وبالوقت يألفها ، ولا تصبح غريبة عليه . وبالتدريج تدخل إلى فكره ، ثم إلى مشاعره . وفى كل خطوة تضعف إرادته عن المقاومة أحسّ أو لم يحسّ ..."},{h:"ومن أمثلة التدرج الطويل موضوع العادات ."},"كل عادة مسيطرة على الإنسان ، لم تبدأ هكذا مطلقاً . وربما كان هو المسيطر عليها أولاً و يستطيع إبطالها . ولكن بالتدرج الطويل فقد سيطرته ، ثم سيطرت هى عليه . وربما الشيطان فى أول خطوة ، قال له عبارة واحدة وهى جرّب أو إختبر ... الحياة كلها خبرات . والأمر كله بيدك ، تستطيع أن تمتنع وقتما تشاء . وظل به هكذا إلى أن أتى"],62:["الوقت الذى فيه سلّم إرادته بالتمام ولم يعد يقاوم ، بل لا يشاء أن يقاوم !!",{h:"على أن التخلص من العادات ممكن لمن يريد ."},"الشيطان قد يقول لك لن تستطيع . وإن استطعت ستعود إليها مرة أخرى . إنها ضمن حرب اليأس . ولكن لا تستسلم . فإن العادة تكونت نتيجة عمل إرادى متكرر . و يمكن أن تتخلص منها بعمل إرادى عكسى متكرر ، أى تثبت فيه .","ونصيحتنا لمقاومة سياسة التدرج هذه من جانب الشيطان ، أن تبعد عن الخطوة الأولى ، بكل حزم ، مهما كانت تبدو بريئة ، أو يقنعك الشيطان بأنها بريئة .",{h:"واحترس من كذبه ، إن قال لك إنها خطوة واحدة ولن تتطور ."},"إن الشيطان لا يقبل على نفسه أن يتركها عند حدود الخطوة الواحدة ، دون أن يتقدم بها باستمرار نحو أغراضه البعيدة ... فاحترس منه .","بل احترس حتى من الخطوة الأولى ، وليس فقط من تطورها ، مهما بدت هذه الخطوة فى نظرك من الأمور الصغيرة . وهنا أحذرك من حيل شيطان ماكر ، هو شيطان الأمور الصغيرة .",{h:"١٠ ـ الأمور الصغيرة"},"هذا يحذرنا منه سفر النشيد قائلاً « خذوا لنا الثعالب ، الثعالب الصغيرة ، المفسدة للكروم » (نش ٢ : ١٥) . وهنا نجد تحذيراً هاماً وهو :",{h:"مع أنها صغيرة ، إلا أنها مفسدة للكروم ."},"أول خطر لهذه الثعالب الصغار أنها تستطيع الدخول إلى النفس . الثعالب الكبيرة ربما لا تجد فتحة مناسبة لها فى سياج البستان تدخل منها . أما الصغيرة فدخولها سهل .","الخطايا الكبيرة ربما يحترس منها الإنسان جداً ، و يبتعد عنها ، و ينفر منها ، لذلك فالشيطان قد يؤجل محاربته بها ، مادام هو متنبهاً لها . أما الأمور الصغيرة ، فيحاربه بها :",{h:"يحاربه بها ، لأنه لا يحترس منها ، ولا يهتم بها ."},"تقول لإنسان مثلاً : إحذر من العثرات . فيقول لك فى استغراب : « عثرات ؟!"],63:["وهل مثلى يخاف من هذه الأمور الصغيرة ؟! إنها قد تحارب الصغار أو المبتدئين . أما نحن فقد كبرنا عن أمثال هذه الأمور » ... لهذا يحاربه الشيطان بها ...","من كان يظن أن أبانا إبراهيم حبيب الله ، يخاف و يقول عن زوجته ساره إنها أخته ، فيأخذونها و يستبقونه ؟! لا شك أن الخوف والكذب من الأمور الصغيرة بالنسبة إلى رجل روحانى عظيم مثل أبينا إبراهيم أبى الآباء والأنبياء ... !",{h:"إن تنجيس الإنسان لا تلزمه خطية كبيرة مثل الزنا ، إنما يكفى لذلك خطية من اللسان الذى « يدنس الجسم كله » (يع ٣ : ٦) ."},"إنه « عضو صغير » ولكنه « عالم الإثم » ، « شر لا يُضبط ، مملوء سماً مميتاً » (يع ٣ : ٥ ـ ٨) . إنه ينجس الإنسان ، كما قال الرب « ليس ما يدخل الفم ينجس الإنسان ، بل ما يخرج من الفم ينجس الإنسان ... أما ما يخرج من الفم ، فمن القلب يصدر . وذاك ينجس الإنسان » (متى ١٥ : ١١ ، ١٨) . والعجيب أن خطية اللسان يقنعك الشيطان أنها من الأمور الصغيرة .",{h:"حقاً إن شيطان الأمور الصغيرة ، يمكن أن يهلك الإنسان ."},"فيمكن أن تغرق سفينة بسبب ثقب صغير فى قاعها ...","والإنسان لا يشترط أن يكون موته بواسطة وحش كبير يفترسه ، إنما يكفى لموته ميكروب صغير لا يُرى بالعين المجردة ... لقد قال السيد الرب فى عظته على الجبل :","« ومن قال يا أحمق ، يكون مستوجب نار جهنم » (متى ٥ : ٢٢) .","ما أسهل أن يقنعك الشيطان بأن كلمة ( أحمق ) وأشباهها هى من الأمور الصغيرة ! وربما كان حنانيا وسفيرا يظنان أن خطيتها أيضاً هى من الأمور الصغيرة ، وقد هلكا بها (أع ٥ : ١ ـ ١١) . وربما ظن سليمان أن زواجه بالأجنبيات هو من الأمور الصغيرة ، وقد رأينا نتائجه الخطيرة جداً على خلاص سليمان نفسه (١مل ١١ : ١-١١) .",{h:"إن « الأمور الصغيرة » قد لا تكون صغيرة فعلاً ."},"الشيطان يسميها هكذا ، ولكنها قد لا تكون كذلك ... وربما توصل إلى أخطر النتائج ، كما حدث مع سليمان وداود وحنانيا . وقد تتحول هذه الأمور الصغيرة إلى أشياء خطيرة جداً ..."],64:["إن الله يختبر إرادتنا بأى اختبار مهما بدا بسيطاً ، لكنه يكشف نفسيتنا من الداخل ، كما اختبر آدم وحواء بثمرة من ثمار الجنة .",{h:"فما هى هذه الأمور الصغيرة ؟ ما أمثلتها ؟"},"ربما تكون مثل تمسك الإنسان برأيه ، وعدم إستشارته لأحد . وقد يقول له الشيطان « وماذا فى ذلك ؟ أى خطأ فيه ؟ وهل لا بد أن تستشير ؟ وهل عقلك لا يكفى ؟! » . وقد تكون الأمور الصغيرة مثل قليل من التساهل مع الحواس والقراءات والسماعات ... أو عدم التدقيق فى الكلام ، أو عدم لوم النفس فى كل أخطائها .",{h:"طريقة الخلاص من شيطان الأمور الصغيرة هى حياة التدقيق ."},"كذلك التمسك بفضيلة « الأمانة فى القليل » فالرب يقول « الأمين فى القليل ، أمين أيضاً فى الكثير » (لو ١٦ : ١٠) .","تحدثنا عن الأمور الصغيرة . ومن حيل الشيطان أيضاً :",{h:"١١ ـ التأجيل"},"إن الشيطان يريد بكل جهده أن يمنعك عن العمل الروحى .",{h:"أما إن وجدك مصراً على العمل ، فإنه يدعوك إلى التأجيل ."},"يقول لك : لماذا الإسراع ؟ الأمر فى يدنا نستطيع أن نعمله فى أى وقت . ربما التريث يعطينا فكرة لفحص الأمر أكثر ، أو لاختيار أسهل السبل الموصلة إليه ، أو يعطينا مزيداً من الإقتناع ... على أية الحالات عندنا بعض أمور هامة فى أيدينا ، ننتهى منها أولاً . ثم نأتى إلى هذا الموضوع .",{h:"والمقصود بالتأجيل هو إضاعة الحماس للعمل ، أو إضاعة الفرصة ، أو ترك الموضوع فترة لعلك تنساها ، أو يحدث ما يغطى عليه ..."},"كأن تأتيك مشغولية كبيرة تأخذ كل اهتمامك ووقتك ، أو يحدث حادث يعطلك ، أو تحدث عوائق معينة تضع صعوبات أمامك فى التنفيذ ، أو يلقى الشيطان فى طريقك بخطية تفتر بها حرارتك الروحية ، فلا تنفذ ما كنت قد نويت عليه وأجلته ...","نتذكر أن الإبن الضال لما أتاه الشعور أن يقوم ليذهب إلى أبيه ، قام فعلاً وذهب"],65:["(لو ١٥ : ١٨ ، ٢٠) . ولو أنه أجّل ، ما كنا نضمن كيف تنتهى قصته .",{h:"ومن أمثلة مضار التأجيل ما حدث لفيلكس الوالى والملك أغريباس :"},"بينما كان القديس بولس الرسول يتكلم عن البر والتعفف والدينونة العتيدة أن تكون ، إرتعب فيلكس وقال للقديس بولس « أما الآن فاذهب . ومتى حصل لى وقت أستدعيك » (أع ٢٤ : ٢٥) . وبالتأجيل ضاع التأثر الذى كان عند فيلكس هذا . ولم يحصل له وقت ، ولم يستدع بولس .","كذلك أغريباس الملك ، بينما كان القديس بولس يترافع أمامه ، قال له : أتؤمن أيها الملك أغريباس بالأنبياء ؟ أنا أعلم أنك تؤمن . فقال أغريباس لبولس « بقليل تقنعنى أن أصير مسيحياً » . وبالتأجيل ، لم يحصل أغريباس على هذا القليل ليقتنع . ولم يذكر الكتاب أنه آمن .",{h:"ربما إحدى زيارات النعمة تدعوك ، فإن أجّلت ضاع تأثيرها ."},"إن الفرصة فى يدك ، والحماس فى قلبك ، فاعمل عمل الرب ولا تتهاون ولا توّجل ، لأن التأجيل ربما يكون خطوة إلى الإلغاء . والشيطان يقصد به ذلك . إنه لا يريد أن يمنعك فى صراحة . ولكنه فى لباقة يمنعك فعلاً ... بالتأجيل . فاحترس منه .",{h:"لا توّجل التوبة ، ولا الصلاة ، ولا عمل الخير جملة ."},"والكتاب يقول « لا تمنع الخير عن أهله ، حين يكون فى طاقة يدك أن تفعله . لا تقل لصاحبك : أرجع فأعطيك غداً ، وموجود عندك » (أم ٣ : ٢٧ ، ٢٨) .","هذا عن عمل الخير من نحو الغير . وكذلك من نحو نفسك . فكلما يتكلم روح الله فى داخلك ، لا توّجل الإستجابة لنداله . فالرسول يقول أكثر من مرة « إن سمعتم صوته ، فلا تقسوا قلوبكم » (عب ٣ : ٧ ، ١٥) .",{h:"إذن التأجيل لون من ألوان قساوة القلب ."},"والشيطان يدعوك إلى هذه القساوة ، فيما يدعوك إلى التأجيل ، أو هو يجعلك تعتاد قساوة القلب لتستمر بعيداً عن الله .","ومن ضمن الوسائل التى يقدمها الشيطان كسبب للتأجيل : المشغولية ."],66:[{h:"١٢ ـ المشغولية"},"بمشغوليات كثيرة يريد الشيطان أن يعطلك عن أى عمل روحى تعمله . هو لا يريدك مطلقاً أن تجلس مع الله ، أو أن تجلس مع نفسك . لأنه يخشى أن هذا الأمر يفصلك عنه و يلصقك بالله ، وهذا أخشى ما يخشاه ...","فإن رآك الشيطان سواظباً على صلواتك وقراءاتك ، ومواظباً على الإجتماعات الروحية وكل وسائط النعمة التى تنمى محبة الله فى قلبك ، حينئذ يحاربك بالمشغولية . وتكون إما مشغولية مؤقتة لتعطيل عمل معين ، أو مشغولية دائمة ، وهذه أخطر ...",{h:"قد تكون المشغولية عملاً إضافياً ، يأتيك منه ربح مادى ."},"بحيث لا توجد معه وقتاً تتفرغ فيه لله . و يقنعك أن هذا العمل لازم جداً لمعيشتك ولا يمكنك الإستغناء عنه . ومثل ذلك أيضاً ما يعرضه على البعض من دراسات عليا ، أو بحوث ، لتحسين مستواه العلمى ، بحيث ينتهى من بحث ليجد آخر أمامه ...",{h:"وقد تكون المشغوليات التى يقدمها خدمات كنسية تعطل وقت الصلاة ."},"الذى يرفض المشغوليات المادية ، يقدم له خدمات كنسية ، ويقنع ضميره بأهميتها . ونحن لا نعارض الخدمة ، إنما المفروض أن تكون فى حدود معينة بحيث لا تعطل الصلاة ولا التأمل ولا القراءة الروحية ، ولا الصلة الخاصة بالله .",{h:"ليس فقط من أجل روحانية الخادم ، بل أيضاً لنجاح الخدمة ."},"فالخادم إذا كثرت مشغولياته بحيث تفتر معها روحياته ، لا تكون خدمته ناجحة ولا يكون لها تأثير قوى . لأن جفاف حياة الخادم الروحية ، يجعل خدمته روتينية أو عقلانية ، لا تدخل إلى أعماق القلب ، ولا تخاطب الروح ...","وما أكثر الخدام الذين تجدهم مشغولين كل الوقت بأنواع أنشطة لا تنتهى ، ولا يجدون وقتاً يصلون فيه صلاة ، أو مزموراً ، أو ينفردون فيه مع الله . يعيشون على الرصيد الروحى القديم الذى كان لهم ، دون جديد يضيفونه إليه . وحياتهم مهددة بالضياع ...",{h:"هنا الشيطان لا يحارب العمل الروحى . ولكن لا يعطيه وقتاً ."},"لا يمنعك من الصلاة ولا من التأمل والقراءة ، ولا من الترتيل والتسبيح ، ولا من"],67:["المطانيات ولا من محاسبة النفس ، بل قد يجعلك تلقى دروساً ومحاضرات عن هذه الوسائط الروحية وفائدتها . ولكنه لا يترك لك وقتاً لممارستها . وتصبح ـ كما قال أحد الأدباء الروحيين ـ مثل الأجراس التى تدعو الناس إلى دخول الهياكل ، دون أن تدخل هى إلى الهياكل ! حقاً ما أجمل قول أحدهم « قضيت عمرك فى خدمة بيت الرب ، فمتى تخدم رب البيت ؟! » ...",{h:"هذا بالنسبة إلى الخدام . أما الأشخاص العاديون ، فما أكثر مشاغلهم ."},"هناك مشغوليات الزيارات ، والأحاديث والجدل والمناقشات . ومشغوليات الجرائد والمجلات ، والأخبار والتعليق عليها . ومشغوليات التسلية وهى كثيرة تشمل الكبار والصغار . أنظر إلى مباريات الكرة مثلاً ، وتأمل كم تأخذ من وقت الناس ومن مشاعرهم ومن حماسهم ومن تعليقاتهم ... ! وهناك أيضاً المشغوليات الفكرية ، والإجتماعية ، ومشغوليات المشاكل وهموم العالم الحاضر ، والمشغوليات المالية والإقتصادية ...","حتى الأطفال تشغلهم برامج التلفزيون ، ورواياته ، وقد تعطلهم عن الكنيسة . والكبار أيضاً تشغلهم هذه البرامج وتعطلهم !",{h:"إن الله يطل من سمائه على العالم ، فيجده عالماً مشغولاً ."},"إنه عالم يجرى بسرعة ، لا يجد وقتاً يتوقف فيه ليفكر إلى أين هو ذاهب ... ! وهو أيضاً عالم صاخب ، كله أحاديث وضوضاء ومناقشات وانفعالات ... وأين الهدوء اللازم للعمل الروحى ؟ غالباً ما تبحث عنه فلا تجده ... !","حتى أن كثيراً من رجال الإكليروس الذين كرسوا أنفسهم للرب ، وأصبحوا « نصيب الرب » ، تجدهم أيضاً مشغولين عن الرب بأمور كثيرة ! إن حرب ( مرثا ) حرب قائمة ودائمة ، كما يبدو فى عالمنا الحاضر « أنت تهتمين وتضطربين لأجل أمور كثيرة ، والحاجة إلى واحد » (لو ١٠ : ٤١ ، ٤٢) . أما أنت يا إبن الله وصورته ، فينبغى أن يكون لك الطابع الروحى .",{h:"ليكن الله فى مقدمة مشغولياتك ، إن لم يكن شاغلك الوحيد ."},"عملك الروحى ، وصلتك بالله ، وحياتك الروحية ، ينبغى أن تكون باستمرار فى مقدمة مشغولياتك وفى توزيع وقتك ، وبعد ذلك كل شىء . ضع خلاص نفسك أولاً ،"],68:["وأبديتك أولاً . ثم رتّب باقى مسئولياتك مهما كانت أهميتها . وتذكّر فى ذلك قول الرب :",{h:"ماذا ينتفع الإنسان ، لو ربح العالم كله وخسر نفسه ! » (متى ١٦ : ٢٦) ."},"وإن خسرت نفسك ، ماذا تعطى عوضاً عن نفسك ؟! وكل أولئك الذين ماتوا وتركوا هذا العالم ، بماذا نفعتهم مشغولياتهم ؟! ولما تركوا هذه المشغوليات بموتهم ، هل ارتبك العالم ؟ كلا ، طبعاً . هذا العالم قال عنه الحكيم :",{h:"« الكل باطل وقبض الريح . ولا منفعة تحت الشمس » (جا ٢ : ١١) ."},"إبدأ صباحك بالله ، قبل أية مشغولية أخرى . ليكن الله « فى البدء » . قل له « يا الله أنت إلهى . إليك أبكر . عطشت نفسى إليك » (مز ٦٣ : ١) . ونظم وقتك ، بحيث لا تطغى أية مشغولية على الوقت الذى تقضيه مع الله . ولا تخرج من منزلك قبل أن تقوم بكل واجباتك الروحية . ولا تجعل شيئاً يفوق روحياتك مهما كان ربحه ، ومهما كانت قيمته أو أهميته ...",{h:"إن الشيطان دائماً يضخّم فى أهمية المشغوليات التى تعطلنا ."},"أو يضخم فى إغراءنا بهذه المشغوليات . ولكن لا يوجد مطلقاً ما هو أهم من الله فى حياتك . ولا يصح أن تضحى بعلاقتك مع الله من أجل أى شىء ، أو أى شخص ، أياً كان . هوذا الرب يقول « من أحب أباً أو أماً ... أو إبناً أو إبنة أكثر منى ، فلا يستحقنى » (متى ١٠ : ٣٧) . فكم هى أقل ، باقى الأمور !",{h:"لذلك إن أتتك مشغولية جديدة ، فكّر كثيراً قبل قبولها ."},"لأن الشيطان قد لا يكتفى بمشغولياتك الحالية التى تعطلك ، فيحاول أن يضيف إليها مشغوليات أخرى ، لكى ترتبك ... ويقدم لك فى كل يوم عروضاً ربما تكون سخية ، ليشغلك بها . أما أنت فكن محترساً . وضع روحياتك أمامك ، قبل كل المشغوليات ...","إن كانت المشغولية حيلة من حيل الشياطين ، لتبعدك عن الله ، فهناك حيلة أخرى أكثر مكراً ، وهى :",{h:"١٣ ـ الفهم الخاطىء لمحبة الله"},"لا يناقش أحد فى محبة الله لنا ، وفى أهمية محبتنا له . ولكن الشيطان قد يقدم"],69:["مفهوماً خاطئاً لهذه المحبة . بحيث أنه يمكن للإنسان أن يخطىء كما يشاء ، معتمداً على محبة الله ورحمته ومغفرته ، ومعتمداً على الخلاص الذى قدمه على الصليب !",{h:"وكأن محبة الله تقود إلى الإستهتار وإلى التراخى !"},"حاشا ، فإن الكتاب يقول « أم تستهين بغنى لطفه وإمهاله وطول أناته ، غير عالم أن لطف الله إنما يقتادك إلى التوبة . ولكنك من أجل قساوتك وقلبك غير التائب ، تذخر لنفسك غضباً فى يوم الغضب ... » (رو ٢ : ٤ ، ٥) . و يقول أيضاً « هوذا لطف الله وصرامته . أما الصرامة فعلى الذين سقطوا . وأما اللطف فلك إن ثبتّ فى اللطف ، وإلا فأنت أيضاً ستقطع » (رو ١١ : ٢٢) .",{h:"إن الشيطان يقدم محبة الله ، بأسلوب يضيع مخافته !"},"و يستغل إلى أبعد الإستغلال ـ بتفسير خاطىء ـ قول القديس يوحنا « لا خوف فى المحبة . بل المحبة الكاملة تطرح الخوف إلى خارج » (١يو ٤ : ١٨) . وهكذا يحاول أن ينزع مخافة الله من قلوب الناس باسم المحبة ، بينما الكتاب يقول « رأس الحكمة مخافة الرب » (مز ١١١ : ١٠) .","هنا وأستأذنكم فى طبع كتاب لى عن ( مخافة الله ) ، وعلاقة هذه المخافة بالمحبة . كنت قد جهزته منذ أكثر من عام ، وأعلنت عنه ، ثم أرجأت طبعه . وفى صميمى أرى نشره لازماً ، لأن كثيرين يستغلون محبة الله إستغلالاً خاطئاً يبعدون به عن الحرص الروحى ، وربما يقعون به فى اللامبالاة . وكل هذا من حيل الشياطين !!",{h:"حقاً إن الله محب جداً وغفور ، ولكنه أيضاً عادل وقدوس ."},"وإن كان الله غير محدود فى محبته ، فهو أيضاً غير محدود فى عدله ، وغير محدود فى قداسته . وقداسة الله لا تقبل الخطية . وعدله يعاقب عليها ...","هذا من جهة محبة الله لنا . وماذا عن محبتنا نحن لله ؟",{h:"الشيطان يصوّر محبتنا لله ، كمجرد مشاعر ، لا أكثر !"},"بينما محبتنا لله هى فى مفهومها السليم ، المحبة العملية « لا نحب بالكلام ولا باللسان ، بل بالعمل والحق » (١يو ٣ : ١٨) . ومن يحب الله ، لا يخالفه ، لا يعصاه ، لا يفعل ما يغضبه . ولذلك إرتبطت محبتنا لله بطاعته وحفظ وصاياه . والرب قد قال"],70:["« إن حفظتم وصاياى ، تثبتون فى محبتى » (يو ١٥ : ١٠) ، « إن أحبنى أحد يحفظ كلامى » (يو ١٤ : ٢٣) . وقد قال القديس يوحنا الحبيب « هذه هى محبة الله ، أن نحفظ وصاياه » (١يو ٥ : ٣) . ومحبتنا لله ، معناها أننا لا نحب العالم وكل شهواته . لأن الكتاب يقول « إن أحب أحد العالم ، فليست فيه محبة الآب » (١يو ٢ : ١٥) . و يقول أيضاً « محبة العالم عداوة لله » (يع ٤ : ٤) .",{h:"فلا يخدعنك الشيطان ويقول لك : يكفى أن تحب الله ، وإفعل ما تشاء !"},"و يقصد تفعل ما تشاء من الأخطاء أو التقصيرات ! إن هذا فكر شيطانى ، يقصد به أنك لا تلوم نفسك على أخطائك ، وبالتالى تبقى فيها غير شاعر بأهميتها ! كما أنه يصور المحبة بمفهوم خاطىء ، كأنها مجرد مشاعر ، بلا عمل يدل عليها . وهو بهذا يهز القيم الروحية فى نظرك ...","حيلة أخرى من حيل الشياطين هى :",{h:"١٤ ـ هز المبادىء والقيم"},"الشيطان يشن على العالم الآن حرباً فكرية ، يريد بها أن يقدم مبادىء جديدة ومفاهيم جديدة ، تخدم أغراضه التى يريدها .",{h:"وفى هذه الحرب يحاول أن يهدم القيم والتقاليد ، وكل المسلّمات ."},"يشكك الناس فيها كلها . و يتهم كل من يتمسك بالتقاليد القديمة ، بأنه رجعى أو متخلف ، أو « دقة قديمة » غير متحضر !! كما لو كان القديم سُبّة ينبغى التخلص منها !",{h:"إنها ثورة من الشيطان على القيم ، وعلى العقائد أيضاً ."},"يريد الشيطان أن يكوّن تياراً عاماً خاطئاً ، كل من لا يسلك بمفاهيمه ، يهاجمه المجتمع و يتهكم عليه ! حتى أصبح كثير من المسلمات موضع جدل ونقاش ! ما هى الفضيلة ؟ وما هو الدين ؟ وما هى الحقوق وما هى الواجبات ؟ بل ما هى العلاقة بين الأب وإبنه فى مفهوم الحرية ؟",{h:"لقد أعطى الشيطان فى جيلنا مفهوماً منحرفاً للحرية ..."},"أراد فى هذا المفهوم أن يقنع الإنسان بأنه حرّ يفعل ما يشاء ، و يعتنق ما يشاء من"],71:["أفكار أو عقائد ، و ينشرها ، بلا أى قيد على الإطلاق ، مهما كانت آراؤه أو معتقداته أو تصرفاته خاطئة ، ومهما كانت خطرة على المجتمع ... !","والمعروف أن الحرية المطلقة لا يوافق عليها أحد ...",{h:"فالإنسان له أن يمارس حريته ، بحيث لا يعتدى على حريات وحقوق الآخرين ، وبحيث لا يسىء إلى المجتمع ، ولا يحطم ما فيه من قيم وأخلاقيات ."},"أما أن يمارس حرية بلا شروط ولا تحفظات ، فإن الحرية حينئذ ستكون مجالاً للإباحية والإستهتار ، ومجالاً للإنحراف الفكرى ، دون ضوابط !","وإن كان الله قد منح الإنسان حرية ، فإنه وضع له إلى جوار هذه الحرية وصايا ينفذها . كما أن الله سيحاسب الإنسان على مدى استخدامه لهذه الحرية ، و يعاقبه إن كان قد أساء بها إلى نفسه أو إلى غيره .",{h:"والحرية المطلقة التى يدعو إليها الشيطان ، لها أخطار سلوكية وعقائدية :"},"فالأخطار السلوكية نذكر كمثال لها الحرية التى أراد أن يسلك بها الهيبز والبيتلز وبعض الوجوديين الملحدين . بحيث لا مانع من أن يسيروا عراة فى الطريق العام ، أو أن يمارسوا الجنس بلا خجل ، ويخدشوا حياء المجتمع ... !","ومثال هذه الأخطاء أيضاً كل المناهج الإباحية ، وكل العثرات التى يصادفها المجتمع ، وتدفعه دفعاً إلى الفساد . ولا مانع عند الشيطان من ذلك ، باسم الحرية . وفى الواقع هذا خداع . فهناك مفهوم سليم للحرية من الناحية الروحية ...",{h:"فالحرية الحقيقية هى أن يتحرر الإنسان من الداخل ، من الأخطاء :"},"يتحرر من الشهوات والرغبات الخاطئة ، ومن العادات المسيطرة عليه التى تفقده حرية إرادته . أما إن حقق الإنسان رغباته ونزواته بكل ما فيها من انحراف ، واستمر مستعبداً لها ، خاضعاً للجسد وللمادة التى تقوده ، فماذا ستكون النتيجة إذن ؟!",{h:"حتماً إن العالم المستعبد لنزواته سيصل إلى كراهية الله الذى يقف ضد هذه النزوات . وهذه هى خطة الشيطان الماكرة !"},"أن يسعى إلى أن يكره الناس الله ، و يعتبرونه عدواً لهم ، لأنه يضيّع حرياتهم ، ويلغى وجودهم ، ويقف ضد رغباتهم ... ! وبدلاً من أن يصححوا رغباتهم ويصيروا أنقياء ، فإنهم يتمسكون بهذه الرغبات ويعادون الله بسببها !"],72:[{h:"والشيطان أيضاً ينشر حرية بلا قيد فى الفهم اللاهوتى ."},"بحيث أن كل إنسان يفسر الكتاب كما يشاء ، ويفهم منه ما يشاء ، وينشر ما يفهمه . وبهذا تتبلبل الأذهان وسط مفاهيم خاصة . وأمكن بهذه الحيلة أن توجد مئات المذاهب داخل المسيحية . سببها هذه الحرية الخاطئة التى يقولون فيها إن كل إنسان له حرية الإعتقاد دون الخضوع لسلطة دينية !!",{h:"إن الكنيسة لها إيمان واحد . وليست هى مجموعة متناقضات ."},"هذا الإيمان الواحد علّم به الكتاب المقدس ، فقال « رب واحد ، إيمان واحد » (أف ٤ : ٥) . وللجمهور المؤمنين « قلب واحد ، ونفس واحدة » (أع ٤ : ٣٢) . والكنيسة هى جسد واحد ، مهما تعددت أعضاؤه ، وهذا الجسد رأسه المسيح (أف ٥ : ٢٣) . ومادام رأسها هو المسيح ، فباستمرار لها فكر المسيح (١كو ٢ : ١٦) . وفكر المسيح واحد لا تناقض فيه .",{h:"فماذا إذن عن حرية الإعتقاد ؟ ما حدودها ؟"},"نحن لا نعارض أن كل إنسان له حرية الإعتقاد . ومحال أن يعتقد شيئاً على الرغم منه . فالذى له اعتقاد الكنيسة يصير عضواً فى الكنيسة . ومن ليس له اعتقادها يبق خارجاً عنها ، بكامل حريته . ويبق للكنيسة إيمانها الواحد .","والكنيسة لا تعتدى على حرية أحد ، ولا ترغمه على الإيمان . ولكن :",{h:"ليس لأحد أن يدعى عضويته فى كنيسة لا يؤمن بمعتقداتها ."},"وهنا يكون دفاع الشيطان عن الحرية لا معنى له . فالحرية موجودة . ولكن كل من يقبل أن يكون عضواً فى كنيسة عليه أن يلتزم بعقائدها . وهذا أمر بدهى . فإن لم يلتزم بعقائدها ، يكون قد خرج منها بإرادته . و ينطبق عليه قول القديس يوحنا الحبيب « منا خرجوا . ولكنهم لم يكونوا منا . لأنهم لو كانوا منا ، لبقوا معنا » (١يو ٢ : ١٩) .","نقول هذا ، لأنه باسم حرية الإعتقاد ، نجد أنه فى بعض كليات اللاهوت ، فى جهات كثيرة من العالم ، يدرس المحاضرون ما يشاءون دون الإلتزام بعقيدة الكنيسة التى ينتمون إليها ، أو التى يدرسون عقائدها . فيدخل الأستاذ إلى المحاضرة ، ويقول الذى يعجبه !",{h:"وهكذا وُجد فى بعض الكليات أساتذة لاهوت ملحدون !!"}],73:["وأفلح الشيطان ، باسم الحرية الزائفة ، أن يضرب ضربته و ينجح !!","أما الكنيسة المقدسة الجامعة الرسولية ، الملتزمة « بالإيمان المسلّم لنا من القديسين » (يه ٣) ، فلم تسمح بهذا مطلقاً ، بل كانت تحكم بحرم المبتدعين والمنحرفين وإخراجهم ، لكى تبقى الكنيسة بإيمان واحد ، تسلمه سليماً للأجيال المقبلة . وهكذا قال القديس بولس الرسول فى قوة :",{h:"« إن بشرناكم نحن ، أو ملاك من السماء ، بغير ما بشرناكم به ، فليكن أناثيما » (غل ١ : ٨) ."},"وقال القديس يوحنا الحبيب « إن كان أحد يأتيكم ، ولا يجىء بهذا التعليم ، فلا تقبلوه فى البيت ، ولا تقولوا له سلام . لأن من يسلم عليه يشترك فى أعماله الشريرة » (٢يو ١٠ ، ١١) . إنه حزم شديد من أكثر الرسل حديثاً عن المحبة .","لذلك كانت الكنيسة حريصة على الإيمان ، تدافع عنه ضد أى إنحراف . ولا تقبل مطلقاً أى إنحراف إيمانى يدخل إلى الكنيسة باسم الحرية ! لينشر أفكاراً خاصة ... !",{h:"لذلك فإن الشيطان لا يقبل سلطان الكنيسة ، ويحارب السلطان الكهنوتى ."},"خذوها قاعدة ثابتة على مدى أجيال التاريخ : كل من ينحرف فى عقيدته ، إذا لم يتب ، لابد أن يحارب السلطان الكهنوتى ، أى يحارب القوة التى تحكم على إنحرافه بسلطان من الله (متى ١٨ : ١٨ ، يو ٢٠ : ٢٣) .","ولما كان الشيطان ينشر أفكاره وانحرافاته فى كل ميدان ، وليس فى محاربة الكنيسة وحدها ، لذلك فقد لجأ الشيطان إلى حيلة معروفة وهى :",{h:"الوقوف ضد السلطة عموماً ، فى كل مجالاتها ..."},"و يقصد طبعاً أن يقف ضد كل سلطة سوف لا تقبل الإنحراف أو الخطأ ، بل تحاربه وتمنعه أو تعاقبه ، وذلك لكى يستمر الخطأ ...","فهو يحارب سلطة الأب فى الأسرة ، دفاعاً عن شخصية الأبناء !","وهو يحارب سلطة المعلم فى الكلية أو المدرسة ، لخلق جيل قوى !","وهو يحارب سلطة الدولة ، باسم الديمقراطية وحقوق الشعب !","وهو أيضاً يحارب سلطة الله ، لكى يشعر الإنسان بوجوده هو !","و بالتالى يحارب سلطة الإكليروس ، كوكلاء الله على رعيته (تى ١ : ٧) ."],74:[{h:"الشيطان لا يريد وجود رقيب يضبط الأخطاء ويقوّمها ."},"بينما الله يقول « قد جعلتك رقيباً ... فاسمع الكلمة من فى ، وانذرهم من قبلى » (حز ٣ : ١٧) . يريد الشيطان أن تبقى كل الأمور ، بلا ضابط ، بلا رقيب ، بحرية طائشة ، كما يقول الكتاب عن عهد القضاة : ولم يكن ملك فى إسرائيل فى تلك الأيام . وكان كل واحد يفعل ما يحسن فى عينيه » (قض ١٧ : ٦) ... كل واحد يعمل ما يعجبه ، وينشر ما يعجبه من آراء ومعتقدات . وإن وقفت ضده سلطه يهاجمها ، بل يهاجم مبدأ السلطة عموماً !! وهذه خطة الشيطان ...","ومن ضمن خطط الشيطان أيضاً :",{h:"١٥ الإنقياد للتيار العـــام"},"قد يكون التيار العام كله خاطئاً ، ويدعوك الشيطان أن تخضع لهذا التيار ، وتكون مثله ! وقد يهمس فى أذنيك :",{h:"الكل هكذا ... لماذا تشذ أنت ، ويكون لك أسلوب خاص ؟!"},"والجواب أننا نتبع الحق أياً كان موقعه ، فى جانب الأغلبية أو الأقلية . فإن كانت أغلبية الناس فى خطأ ، فإننا لا نتبعها . وهكذا فعل أبونا نوح : كانت كل الناس فى عهده أشراراً ، وكان هو وحده البار مع أسرته .",{h:"ما أسهل أن تكون الغالبية كلها مخطئة ، أو الجيل كله ."},"الغالبية فى وقت الصلب كانت مخطئة وصاحت أصلبه أصلبه (لو ٢٣ : ٢١) . بل الجيل كله ، قال عنه السيد المسيح « جيل فاسق وشرير » (متى ١٢ : ٣٩) . وغالبية الناس أيام آخاب الملك ، كانت تعبد الأصنام ، إلا سبعة آلاف ركبة فقط من بين مئات الآلاف (١مل ١٩ : ١٨) . وفى أيام موسى النبى ، حكم الرب على الشعب كله بأنه متمرد وصلب الرقبة ، ولم يدخل منه إلى أرض الموعد إلا إثنان فقط هما يشوع بن نون ، وكالب بن يفنة (عد ١٤ : ٢٠ - ٣٠) .","وإن رجل الله الثابت فى وصاياه ، هو الذى ينشد قائلاً :",{h:"سأطيع الله حقّ لو أطعت الله وحدى"}],75:[{h:"ولكن الشيطان يدفع دفعاً فى التيار العام بطرق شتى :"},"أحياناً يجعل الناس يجارون الخطأ من باب المجاملة ، أو من باب الخجل ، أو من باب التقليد ، أو خوفاً من تهكم الناس ومن تعييرهم ، أو نتيجة لضغط الظروف الخارجية وإلحاح الآخرين . أو أن يقول لهم الشيطان « هذه المرة فقط ، ولن تتكرر » ! ثم تتكرر طبعاً ... أو أن شخصاً قد يجارى التيار خضوعاً لسلطة أقوى منه أو خضوعاً لرئاسة ... وقد يجارى التيار جهلاً . وقد يقول له الشيطان :",{h:"هل من المعقول أن يكون كل الناس مخطئين ، وأنت الوحيد المصيب ؟!"},"هل من المعقول أن كل هؤلاء لا يعرفون أين يوجد الخير والحق ، وأنت الوحيد الذى تعرف ؟! إتضع يا أخى ... (و يتضع) الأخ ! و ينجرف فى التيار .","وقد يسير فى التيار نتيجة لصداقة أو صحبة خاطئة إستطاعت أن تؤثر عليه وتجذبه إلى طريقها ، كما سار سليمان الحكيم فى طريق نسائه (١مل ١١ : ٤) .",{h:"وقد يخضع الإنسان للتيار نتيجة لضعف شخصيته ..."},"وهكذا لا يقدر على المقاومة ، أو يقاوم قليلاً ولا يثبت . والعجيب أن أهل العالم يكونون أقوياء جداً فى دفاعهم عن طريقهم الخاطىء ، وفى سخريتهم من أولاد الله الذين لا يجارونهم . ويظلون ينعتونهم بشتى النعوت ، حتى يضعف هؤلاء ويخضعون ... ! يا للأسف ...","إن أولاد الله يجب أن يكونوا أقوياء فى مبادئهم ، ثابتين راسخين ، لا يتزعزعون أمام تهكمات الأشرار . وليتذكروا قول الكتاب :",{h:"« لا تشتركوا فى أعمال الظلمة غير المثمرة ، بل بالحرى وبخوها » (أف ٥ : ١١) ."},"فإن لم يستطيعوا أن يوبخوا أعمال الظلمة ، فعلى الأقل لا يشتركون فيها ... وليكن لهم أسلوبهم المميز فى الحياة ، الذى قال عنه القديس يوحنا الحبيب « بهذا أولاد الله ظاهرون ، وأولاد إبليس (ظاهرون) » (١يو ٣ : ١٠) . وكما قيل « من ثمارهم تعرفونهم » (متى ٧ : ١٦) . وقيل أيضاً « لغتك تظهرك » (متى ٢٦ : ٧٣) . وقد قال القديس بولس الرسول عن عدم الخضوع للتيار العام :",{h:"« لا تشاكلوا هذا الدهر » (رو ١٢ : ٢) ."},"أى لا تصيروا شكله . لا تصيروا مثله . لأن شكلكم معروف ، فأنتم صورة الله"],76:["ومثاله . وما أجمل قول الله فى ذلك « نعمل الإنسان على صورتنا ، كشبهنا » (تك ١ : ٢٦) . فكيف تتنازل عن صورتك الإلهية ، لتصير كصورة عالم ساقط منحرف .",{h:"إن دانيال والثلاثة فتية ، كانوا أقوى من التيار العام ."},"ليس فقط فى انفرادهم عنه بعبادة إلههم ، حتى لو أدى الأمر أن يلقى دانيال فى جب الأسود ، و يلقى الثلاثة فتية فى أتون النار ... بل حتى منذ بدء تعيينهم فى قصر الملك ، إذ رفضوا الطعام الملكى ، ولم يأكلوا مع سائر الفتيان . وما أجمل قول الكتاب « أما دانيال فجعل فى قلبه أن لا يتنجس بأطايب الملك ولا بخمر مشروبه » (دا ١ : ٨) .","صمم دانيال والثلاثة فتية على هذا الأمر ، مع أنهم كانوا أسرى حرب ، وتحت سلطان ، يخدمون وهم عبيد فى قصر الملك . ولكن قلوبهم وأرواحهم كانت حرة طليقة ، لا تخضع للتيار العام ، بل لمشيئة الرب .",{h:"لذلك كن شجاعاً ، وصاحب مبدأ ، وقاوم التيار العام إذا أخطأ ."},"لا تخضع للشيطان وكل نصائحه ، بل وكل مخاوفه . وارفض الخطأ مهما رأيت كباراً يسيرون فيه ! وإن وجدت الذين يسيرون فى طريق الحق قليلين ، فلا يضعف قلبك . فهذه هى القلة المختارة . وقد قال الرب « ما أضيق الباب وأكرب الطريق الذى يؤدى إلى الحياة . وقليلون هم الذين يجدونه » (متى ٧ : ١٤) . واعلم أنه :",{h:"لو وقعت الغالبية فى الخطأ ، فهذا لا يجعل الخطأ صواباً ."},"الخطأ هو الخطأ . ووقوع الأغلبية فيه لا يبرره . والمعروف أن الصواب طريقه صعب ، وقد لا يستطيعه كل الناس ، بل القلة المتميزة بمبادئها . فإن وجدت الشيطان قد ألقى الكل فى الخوف ، لا تخف أنت . وإن وجدت الغالبية تعلمت التملق والرياء ، فلا تكن أنت كذلك . وإن وجدت الكل قد استعملوا أساليب العالم فى لهوه وترفيهاته ورفاهيته وأزيائه ، فلا تكن كذلك . وإن وجدت لغة الناس قد تغيرت ، وأصبحت ليست كذى قبل ، فلتكن أنت بنفس لغتك الأولى .","وإن ضعفت مقاومتك للتيار ، فقل مع المرتل فى المزمور :",{h:"نجنا يارب من هذا الجيل ، وإلى الأبد آمين » (مز ١٢ : ٧) ."},"والرب قادر أن ينجيك من التيار العالم ، فلا يجرفك .","حيلة أخرى من حيل الشياطين لإسقاط أولاد الله ، وهى :"],77:[{h:"١٦ الإغـــراءات"},"منذ الخطية الأولى ، والشيطان يقدم إغراءات ليسقط ضحاياه . وكان أول إغراء قدمه لأبوينا الأولين هو « تصيران مثل الله ، عارفين الخير والشر » (تك ٣ : ٥) . واستمر يقدم إغراءات للبشر « شهوة الجسد ، وشهوة العين ، وتعظم المعيشة » (١يو ٢ : ١٦) . وقدم هذه كلها لسليمان الملك (جا ٢ : ١ - ١٠) .","وعلى الجبل قدم للسيد المسيح ثلاثة إغراءات : الخبز ، حمل الملائكة له على أجنحتها ، وكل ممالك الأرض ومجدها (متى ٤) . ورفض السيد كل هذا ، وأخزى الشيطان وطرده .",{h:"إن إغراءات الشيطان لا تسقط إلا قلباً يميل إليها ..."},"أو يمكن أن يميل إليها ... أما القلب القوى فإنه يرفض تلك الإغراءات ، أو قل إنها لا تغريه . إن الملكة إيزابل أرادت أن تؤثر على ياهو الملك وتغريه ، كما كان آخاب الملك تحت سيطرتها من قبل « فكحلت بالإثمد عينيها ، وزينت رأسها » (٢مل ٩ : ٣٠) . أما ياهو ، فلم يغره هذا الجمال الزائف ، بل احتقره وأمر بقتلها ...",{h:"والشيطان أحياناً ينتقى إغراءاته ، وأحياناً يجس النبض ..."},"يجس النبض لكى يرى هل محاربه يضعف أمام هذا الإغراء أم لا . فإن وجده لا يهتم ولا يتأثر ، يجرب إغراء آخر ، كما فعل مع السيد المسيح ، فوجده قوياً أمام كل إغراءاته . ومن خبرة الشيطان الطويلة ، أنه ينتقى لكل نوع من الناس ما يرى أنه يناسبه ...",{h:"وقد يغرى بالشىء الذى يرى الشخص محتاجاً إليه ."},"كما قدم للسيد المسيح تجربة الخبز ، حينما قيل عنه إنه « جاع أخيراً » (متى ٤ : ٢ ، ٣) . وقدم تجربة العرافة لشاول الملك فى الوقت الذى رآه فيه محتاجاً الى مشورة ولم يجد (١صم ٢٨ : ٤ - ٧) . وقدم تجربة العجل الذهبى لبنى إسرائيل فى وقت رآه مناسباً ، وقد غاب عنهم موسى النبى ، وغاب معه الإرشاد الروحى وهيبة النبوة (خر ٣٢ : ١ - ٤) ."],78:[{h:"والشيطان يقدم الإغراء قوياً مؤثراً ، يمنع التوبة والعمل الروحى ."},"فإن وجد إنساناً قد عزم على التوبة بكل عزم وقوة ، يقدم له خطية كان يشتهيها منذ زمن ، ويبحث عنها فلا يجدها . فيضعها أمامه فجأة تسعى بنفسها إليه من حيث لا يدرى ، فيغريه بها ليسقط ... وإن كان إنسان قد أبطل قراءة كتب معينة معثرة ، لا مانع فى هذا اليوم من أن يرسل إليه صديقاً ، يهديه كتاباً كان هذا (الضحية) يشتهى شراءه شهوراً طويلة ولا يجده فى السوق . فيجد نفسه أضعف من الإغراء ، فيقرأ ويسقط .","وإن تاب شاب عن خطية الزنا ، يجد خطية سمت إليه سمياً .",{h:"بحيث يظن المسكين أنها فرصة لا تعوّض . ويقول له الشيطان :"},{h:"لا تترك هذه الفرصة ، ويمكن أن تتوب بعدها ... !"},"وهكذا إن وجد الشيطان إنساناً يبعد عن الخطية ، يأتى إليه بأكبر إغراءات للخطية بالنسبة إليه . لأنه يعرف تماماً أين يوجد الجرح الذى يدوس عليه فيؤلمه ... فإن ثبت ووجدت خطية تسعى إليك فى إغراء عجيب ...",{h:"لا تقل هذه فرصة . بل قل : هذا بلا شك فعل الشيطان ."},"ليس هذا شيئاً طبيعياً ، ولا هو أتى عن طريق الصدفة . بل هى خطة مدبرة محكمة من عمل الشيطان . ومبارك هو الرب الذى كشفها لى لأهرب منها ... وكما قال الراهب القديس عبد المسيح الأثيوبى المتوحد ببرية شيهيت « فغ يا أباقى فغ » ...","نقطة أخرى بارزة فى حرب الشياطين هى :",{h:"١٧ التخـديـر"},"حينما يكون الإنسان متيقظاً ومتنبهاً لخلاص نفسه ، صاحياً عقلاً وروحاً ، فإنه من الصعب أن يسقط ... ولذلك قال أحد القديسين : إن الخطية تسبقها إما الشهوة ، أو الغفلة ، أو النسيان . فحالة الغفلة والنسيان ، هى تخدير من الشيطان للإنسان ...",{h:"فينساق إلى الخطية ، كأنه ليس فى وعيه !"},"ولذلك حسناً قيل فى توبة الإبن الضال إنه « رجع إلى نفسه » (لو ١٥ : ١٧) ."],79:["وكلمة (رجع) تعنى أنه لم يكن فى وعيه ، أو على الأقل لم يكن فى كامل وعيه ، طوال فترة الخطية . ولهذا لما رجع إلى نفسه بدأ يفكر بأسلوب آخر ، يختلف عن أسلوبه فى الخطية .",{h:"الشيطان يخدر الإنسان بحيث ينسى كل شىء ، ما عدا الخطية ."},"تكون كل حواسه وأفكاره ومشاعره مركزة فى الخطية وحدها . أما كل ما عداها فلا يحس به الإنسان اطلاقاً ، وكأنه قد نسيه تماماً تماماً ...","ينسى أنه صورة الله . ينسى الوصية . ينسى نتائجها . ينسى وضعه الروحى . ينسى تدرايبه الروحية . ينسى عبادته واحتراسه . ينسى وعوده لله وتعهداته ونذوره . ينسى إحترامه . بل قد ينسى أنه صائم ، أو أن هذه أيام مقدسة . و ينسى عقوبات الله وإنذاراته ... يكون كأنه مخدر تماماً . والشيطان قد خدره بالخطية ، بحيث أصبح لا يعى شيئاً غيرها ...",{h:"ولا يفيق إلا بعد السقوط ، حينما يكون كل شىء قد انتهى ."},"هكذا كان داود النبى مخدراً ، حينما أخطأ ، وجرته الخطية إلى خطية . ولم يفق من هذا التخدير إلا على صوت ناثان النبى يقول له « أنت هو الرجل » (٢صم ١٢ : ٧) . حينئذ فقط أفاق ، وأحس كم كانت أعماق خطيئته !","لعل قايين كان أيضاً مخدراً حينما قام على أخيه وقتله . ولم يفق إلا على قول الرب له « أين هابيل أخوك ؟ » (تك ٤ : ٩) . حينئذ فقط أفاق ، وشعر ببشاعة ما قد فعل ونتائجه وقال « ذنبى أعظم من أن يحتمل » (تك ٤ : ١٣) .",{h:"قد يفيق الإنسان بعد الخطية مباشرة ، وربما بعد مدة طويلة ."},"الإبن الضال لم يفق من تخديره ، إلا بعد أن أنفق كل ماله واعتاز ، وشعر بسوء حالته (لو ١٥ : ١٦ ، ١٧) . والغنى الذى عاصر لعازر المسكين لم يفق إلا فى الجحيم . ولكن هناك من يفيق بعد الخطية مباشرة ، مثل القديس بطرس الذى بعد إنكاره بكى بكاءً مراً (متى ٢٦ : ٧٥) . ويهوذا لم يفق إلا بعد فوات الفرصة .",{h:"هناك من يفيق من تخديره فيتوب . وهناك من يفيق فييأس ."},"الإبن الضال ، وداود النبى ، وبطرس الرسول ، لما أفاقوا تابوا ."],80:["أما يهوذا فلما أفاق ، أسلمه الشيطان إلى اليأس « فمضى وخنق نفسه » (متى ٢٧ : ٣ - ٥) . ومات فى خطيئته فهلك ...",{h:"لذلك هناك نصيحتان أقدمهما لك ، إذا خدّرك الشيطان :"},"الأولى ، أن تفيق بسرعة . كما قال المرتل « أنا أستيقظ مبكراً » (مز ٥٧ : ٨) . واحذر من أن تستمر مخدراً بالخطية إلى أن تصبح عادة ، أو يصير من الصعب عليك أن تفيق ، أو أن تصحو من تخديرك بعد أن تكون قد وصلت إلى نتائج سيئة جداً ...","النصيحة الثانية : هى أنك حينما تفيق ، إنما تفيق إلى توبة حقيقية وسريعة ، وليس إلى يأس أو صغر نفس ... واستغل الندم والإنسحاق لنفعك الروحى .","نقطة أخرى أقولها لك فى حروب الشياطين وهى :",{h:"١٨ تحـويـل الدين الى فلسـفة"},{h:"السيد المسيح أراد أن يكون الدين روحاً وحياة ."},"ولذلك قال « الكلام الذى أكلمكم به هو روح وحياة » (يو ٦ : ٦٣) . نفهم روح الكلمة ، ونحولها إلى حياة فينا . وهكذا يصير الدين طريقاً لتنقية القلب ، ومرشداً إلى الإلتصاق بالله ، ولكى تكون للإنسان حياة أبدية . ولعل هذا ما أراده الرب بقوله « أتيت لتكون لهم حياة ، وليكون لهم أفضل » (يو ١٠ : ١٠) .",{h:"ولكن الشيطان يريد أن يحول الدين إلى جدل ومناقشات ..."},"يريد أن العقل يحل محل الروح ، والجدل يحل محل الممارسة . وتصبح الحياة الدينية هى مجرد عقلانية . وكأن المسيحية هى فلسفة تُدرّس وتُحلّل ، وتصبح مجرد منهج للتعليم ، وليس حياة نحياها . والعقل لا يضر الشيطان فى شىء إن بقى مجرد عقل لا تحركه الروح . وهذا ما يريده الشيطان ...",{h:"بودى أن أترجم لكم كتاب ( ضد الأكاديميين ) للقديس أوغسطينوس ."},"إسم كتابه Contra Acadimos ليتنى أستطيع أن أترجم لكم بعض فقرات منه كمثال . والمعروف عن القديس أوغسطينوس أن له منهجاً روحياً عميقاً .",{h:"والمنهج العقلى الذى يريده الشيطان ، حاربه القديس بولس الرسول ."}],81:["وهذا واضح جداً فى الأصحاحين الأولين من رسالته الأولى إلى أهل كورنثوس ، فهو يقول « أتيت ليس بسمو الكلام أو الحكمة » ، « وكلامى وكرازتى لم يكونا بكلام الحكمة (الإنسانية) المقنع ، بل ببرهان الروح والقوة » (١كو ٢ : ١ ، ٤) ، « لا بحكمة كلام ، لئلا يتعطل صليب المسيح » (١كو ١ : ١٧) . فالتركيز على صليب المسيح عمل روحى ، يعطله الإنشغال بالفكر والجدل .",{h:"إن الهرطقات كانت لعبة شيطانية عقلية لتعطيل العمل الروحى ."},"العمق الروحى الذى عاشته الكنيسة فى عصر الإستشهاد ، طوال القرون الثلاثة الأولى ، وفى أوائل القرن الرابع ، والعمق الروحى الذى كان قد بدأ بالرهبنة منذ أواخر القرن الثالث ، وازدهر فى القرنين الرابع والخامس ، بكل ما فيه من حب لله ، وبكل ما فيه من الإرشاد الروحى من أقوال الآباء ... كل ذلك أثار حسد الشيطان ، فأراد أن يشغل العالم بالجدل والنقاش على مدى قرنين طويلين ... وهكذا ظهرت هرطقات أريوس ، وأبوليناريوس ، وسابيليوس ، ومقدونيوس ، ونسطور ، وأوطاخى ، وغيرهم ... كل ذلك فى فترة مركزة جداً دوّخت العالم فكرياً . وأصبح النقاش حول لاهوت الإبن وطبيعته يدور فى الشوارع حتى بين العامة . وألهم الشيطان مفاهيم للهراطقة وتفاسير لآيات الكتاب . وانشغل آباء الكنيسة فترة طويلة بالرد على البدع والهرطقات .",{h:"والشيطان يتمنى أن يشغلنا طول العمر بالحوار الفكرى والردود ..."},"ومازالت هذه هى خطته ، يرسل لنا فى كل جيل من يحاول أن يحوّل الدين إلى نقاش وجدل وفكر وحوار وآراء وردود ... مريداً بهذا أن يعطل العمل الروحى من جهة ، ويثير الإنقسام والخصومات من جهة أخرى ، ولو باسم الدين ، وباسم الدفاع عن العقيدة ، وتصبح الكنيسة مذاهب وشيعاً ، ويفرح الشيطان بهذا . من يسقطون فى الهرطقات مكسب له ، ومن يتعبون من الشكوك مكسب آخر . ومن ينشغلون عن العمل الروحى بهذه السلبيات وإضاعة جهودهم فى الردود ، كل ذلك مكسب أيضاً .",{h:"ونشكر الله أن الآباء الذين ردوا على الهرطقات كانوا روحيين ."},"تقرأ مثلاً كتاب (تجسد الكلمة) للقديس أثناسيوس فتجده كتاب روح كما هو كتاب لاهوت وعقيدة ... ولكن كثير ين انشغلوا بالفكر ... ونحن نشكر الله أيضاً أن حركة الهرطقات والرد عليها فى القرنين الرابع والخامس ، سارت معها جنباً إلى جنب"],82:["حركة الرهبنة وإرشادها الروحى . فأقامت توازناً مع الدوامات الفكرية .","كان الرد على الهراطقة لازماً جداً لحفظ الإيمان . ولكن كان الإنشغال بذلك تعطيلاً للكنيسة . ولكن الله حوّله إلى خير بتعميق الإيمان فى القلوب وبإزالة الشكوك .",{h:"وحتى فى الروحيات البحتة ، يحاول الشيطان تحويلها إلى فلسفة ."},"يمكن أن يجعل حتى الصلاة مثلاً منهجاً فكرياً له قواعده العقلية . وكذلك يمكن أن يفعل ذلك بالرهبنة ويحولها إلى مدارس تتصارع فكرياً بين الوحدة والعمل ، والتأمل والخدمة . ويتحول الأمر إلى نقاش وإلى صراع ، يسر به الشيطان ويفرح !",{h:"حتى صلاة « أبانا الذى » يحولها إلى صراع حول الترجمات ."},"وإذا بالناس وهم يصلون يقول أحدهم « خبزنا كفافنا » ويصيح آخر بصوت عال « الذى للغد » . وتتصارع الترجمات وتتبلبل الأفكار ، وبدلاً من التأمل فى الصلاة يدور الجدل والنقاش أية الترجمات أصح !!","ونفس الوضع قد يدور فى القداس الإلهى أيضاً : يريد الشيطان أن يقضى على التأمل والروحيات ، فيثير حرباً من الترجمات .",{h:"وفى داخل الكنيسة ما أسهل أن يثير أفكاراً جديدة ..."},"يجعل البعض يشغف بالجديد ، فيقدم تفسيراً جديداً ، أو معتقداً مغايراً للمفاهيم العامة . ويقول صاحبه وناشره إن كل من سبقوه قد أخطأوا . وبدلاً من استخدام الفكر الدينى للحب ولنقاوة القلب ، يحوله الشيطان إلى صراع وإلى حرب بين المتدينين بسبب الفكر والفهم الخاص ، وادعاء كل فريق أنه يدافع عن العقيدة ! وأنه الوحيد الصادق فى إيمانه ...","أو على الأقل يعطل الروحيين عن عملهم بالإنشغال بالسلبيات والرد عليها . وإن لم يفعلوا ذلك ، يملأ الجو شكوكاً وبلبلةً .","حرب أخرى من حروب الشيطان وهى :",{h:"١٩ فتـرة راحـة من الخطيــة"},"إنه لا يحارب باستمرار ، إن وجد للحرب الدائمة أضراراً ..."],83:["فهو قد يبطل الحرب فترة ، ليس إشفاقاً منه على من يحاربه ، وإنما لكى يجره إلى التهاون وعدم الحرص ، ثم يعود إليه بأسلوب أكثر قساوة فيسقطه . وبهذا يشعره على الدوام بعدم ثقة فى القدرة على حياة البر ، ويقنعه بأنه مهما تاب ، لابد سيعود إلى الخطية مرة أخرى .",{h:"أو قد يبعد الخطية عنه فترة ، ليشتاق إليها ."},"ربما كثرة ممارسة الخطية تولد الملل منها وكراهيتها . فتكون خطة الشيطان أن يبعدها فترة . ثم يعيدها بعد حين بأسلوب أكثر تشويقاً ، أو أكثر حدة ، أو بأسلوب غير متوقع ، لكى يسهل السقوط فيها .",{h:"وهكذا يستخدم أسلوب المنح والمنع فى المحاربة بالخطية ."},"إنه بهذا يلعب بمشاعر النفس البشرية ... ويجعلها باستمرار فى حالة عدم استقرار ، ما بين علو وهبوط . وأولاد الله يدفعهم ذلك إلى مزيد من الحرص والتدقيق ، وإلى مزيد من الإتضاع . ولكن الشيطان يريد أن يجعلهم فى جو من الخوف وعدم الثقة ، والشعور بأن البر فوق مستواهم .","ثم يتدرج من الهجوم الفكرى إلى هجوم عام يقول فيه : إن المسيحية ديانة سمو وكمال . ولكنه سمو غير عملى ، ليس فى مستوى قدرة الإنسان أن يناله . ويخفى فى كل ذلك الأمثلة التى قدمتها لنا سير الأبرار فى كل زمان ...","حرب أخرى من حروب الشيطان هى :",{h:"٢٠ الفضـائل الظـاهرة الجسـدية"},"يغرى الإنسان بالفضائل الظاهرة الجسدية ، بدلاً من الفضائل الروحية الخفية .","ونقصد بالظاهرة ، الظاهرة لصاحبها ، وليس فقط الظاهرة للآخرين . وهذه الفضائل الظاهرة يمكن أن يلقيه بها فى الإعجاب بالنفس والغرور ، أو يلقيه فى احتقار الآخرين الذين لم يصلوا إلى نفس المستوى .",{h:"وهذه الحرب يحارب بها الرهبان كما يحارب بها العلمانيين أيضاً ."}],84:["فإذا بدأ الراهب جهاده ، يجعله الشيطان يهتم بالصوم ، وبالمطانيات ، والسهر ، والصمت ، والإعتكاف . وكلها أمور ظاهرة ... وفى نفس الوقت لا يهتم بفضائل القلب من الداخل مثل الفرح والسلام والنقاوة والوداعة والهدوء ... الخ",{h:"وفى الصوم يحارب بالأسلوب الجسدانى ويترك الروحى ."},"فيجعل كل اهتمام الصائم بفترة الإنقطاع وكم تكون ، وبنوع الأكل ووجوب الإمتناع عن بعض مشتهيات ، والإقلال من كمية الماء التى يشربها . وكل هذه أمور جسدية ، ولا يشغل نفسه أبداً بالفضائل الروحية التى فى الصوم مثل : انسحاق القلب ، وسمو الروح ، وضبط النفس فى كل الأمور .","والشيطان يعرف أن مثل هذا الصوم الجسدى قد لا يفيد الإنسان روحياً . ويستغل هذا الأمر فيا بعد ، لكى يبعده عن الصوم كلية .",{h:"ونفس الوضع بالنسبة إلى المطانيات ."},"المهم هو عددها ، ونمو هذا العدد باستمرار . أما أن الإنسان فيا يسجد ، تلصق بالتراب نفسه (مز ١١٩) كما تلصق رأسه بالتراب ، فهذا ما لا يجعله يفكر فيه ! كذلك لا يجعله يهتم بالمشاعر الروحية التى تصحب المطانيات ، وما تصحبها أيضاً من صلوات ... وكل ما يقصده هو أن تتحول هذه المطانيات - على الرغم من كثرة عددها - إلى عمل جسدانى يمكن أن يرهقه دون أن يفيده ، كما يلقيه به فى المجد الباطل !",{h:"والوحدة أيضاً يهتم بمظهرها وليس بروحياتها ."},"كإنسان يحيا الوحدة كطقس ، وليس كمنهج روحى يتميز بفضائل معينة ، فيها يكون الفكر منفرداً بالله فى حب ، ويكون القلب قد مات كلية عن العالم . ولكن كثيراً ما يجعل الشيطان هذا المتوحد يقنع بمجرد سكنى المغارة والبعد عن الدير ، ويملأ قلبه بالكبرياء والسخط على الدير ومن فيه ، دون الإهتمام بالعمل الروحى داخل المغارة . وكما قال ماراسحق « يوجد إنسان قد يسكن فى القلاية خمسين سنة وهو لا يعرف طريقة الجلوس فى القلاية » .",{h:"وما ينطبق على الوحدة ، ينطبق على الصمت أيضاً ."},"فالمفروض أن هدف الصمت ، هو أن الإنسان يبعد عن أخطاء اللسان ، ويعطى نفسه فرصة للحديث مع الله . أما أن يقنع الإنسان بمجرد الصمت ، فهذا عمل جسدانى"],85:["ظاهر . إذ أن كل الأخطاء التى يقع فيها بلسانه ، يمكن أن يقع فيها بفكره مثل الإدانة والغضب والشتيمة والحدة ... الخ . فإن كان قلبه خالياً فى نفس الوقت من الحديث مع الله . يكون صمته بعيداً عن العمل الروحى .",{h:"وبنفس الطريقة قد يقنع الإنسان باختيار البتولية ."},"ويظن أن البتولية هى ذلك العمل الظاهر الذى هو عدم الزواج . وقد تكون نفسه غير بتولة ، وأفكاره دنسة . والعنصر الإيجابى فى البتولية الذى هو توجيه الحب كله نحو الله ، قد لا يكون موجوداً أيضاً . وهكذا يكون قد أخذ من البتولية ظاهرها ، دون روحها ودون فاعليتها داخل القلب ...",{h:"المفروض فينا أن نهتم بالعمل الروحى الداخلى ، فهو الأهم ."},"والرب قد قال « يا إبنى أعطنى قلبك » (أم ٢٣ : ٢٦) . فيبدأ الإنسان بنقاوة القلب ، وبمحبة الله ، وبالفضائل الداخلية . ثم من القلب النقى تخرج الصلاة النقية ، والمطانيات الظاهرة ، والصوم الروحانى ، وكل فضيلة أخرى ...","والعجيب أن المهتم بالفضائل الظاهرة ، كثيراً ما يصطدم بأب اعترافه ، وربما يفكر فى تغييره ، بينما حياته هو من الداخل ليست نقية أمام الله !",{h:"٢١ العنـــف"},{h:"إنها حرب يوجهها الشيطان إلى الروحيين كما إلى الخطاة ."},"يدرب الإنسان على العنف تجاه كل خطأ . وبالتالى يجعله عنيفاً فى مقابلة كل من يخالفه فى الرأى . وقد تختفى وراء هذا العنف كبرياء وقساوة قلب .","وربما كثير من أهل العالم يتميزون بالوداعة والهدوء ، بينما نجد من المتدينين من يكونون عنفاء جداً ، باسم الدين ، ساخطين على كل شىء ، شاعرين أنهم هم وحدهم الذين يعرفون الله ويسيرون فى طرقه . وبهذا العنف يسقطهم الشيطان فى عديد من الأخطاء التى لم يقع فيها العلمانيون . وينسيهم فضائل الوداعة واللطف التى هى من ثمار الروح القدس (غل ٥ : ٢٢) .","من حروب الشيطان أيضاً :"],86:[{h:"٢٢ المعطـــلات"},{h:"كل عمل روحى معرض لمعطلات عديدة من الشيطان ."},"فقد يعزم الإنسان من كل قلبه على عمل روحى . ويقف ضده الشيطان بكل قوة لكى يعطله عن تنفيذ ما يريد . وكما يقول الرسول « الإرادة حاضرة عندى . ولكن أن أفعل الحسنى لست أجد » (رو ٧ : ١٨) . وهذه المعطلات إما أن تكون ظروفاً خارجية ، أو من نسيان ، أو من عدم توافر الوقت ، أو من مقاومات من أعداء ، أو من أخوة كذبة ... ثم يأتى الشيطان ليقول :",{h:"قطعاً هذا العمل ليس من الله . وإلا كان قد سهل سبله !"},"أو قد يقول للناس عن هذا الإنسان الخير : لو كان هذا الإنسان من الله ، لكان الله قد وفقه فى عمله . ويضرب عصفورين بحجر واحد .","من حيل الشيطان أيضاً لإيقاع الإنسان : الخجل .",{h:"٢٣ الخجـــل"},"الخجل فضيلة إن أحسن الإنسان استخدامها . ولكن الشيطان كثيراً ما يستخدم الخجل بطريقة تساعد على السقوط ...","كإنسان كان جالساً وسط أناس يتكلمون كلاماً رديئاً من الناحية الخلقية ، أو يتحدثون بالسوء فى سيرة إنسان له مكانته ويشهرون به ، أو يسردون قصصاً غير لائقة ... وهذا الإنسان البار الجالس وسطهم ، الذى لم يكن يتوقع كل هذا ، يفكر أن يتركهم وينسحب ... ولكن يأتيه شيطان الخجل ، ويرغمه على البقاء ... فيستمر جالساً ويمتلىء عقله بأفكار ما كان يحب مطلقاً أن تجول بذهنه .",{h:"وعن طريق الخجل قد يوقع على تزكية لا يوافق عليها ضميره ."},"أو يوقع على أى بيان أو قرار ، هو فى داخله غير راض عليه ، أو يشترك فى مديح إنسان لا يستحق ذلك ... وإن حاول أن يمتنع يقف أمامه الخجل !",{h:"وقد يجعل الشيطان فتاة تخجل من ملابسها المحتشمة ."}],87:["وذلك إن كان التيار العام غير ذلك ... أو يجعلها تخجل من تدينها بوجه عام . تخجل من الصلاة ومن الصوم ، أو من معرفة ذلك عنها ... بل قد تخجل من تعليق صليب على صدرها . أو تخجل من رفض دعوة إلى حفل معين لا تستريح له روحياتها .","وبالمثل قد يخجل شاب متدين من رفض سيجارة تقدم له من زميل أو من أستاذ ... وكم من خطايا يقع فيها البعض بسبب شيطان الخجل !",{h:"والمفروض أن يرفض المتدين هذا الخجل ويبعد عن مجالاته ."},"أو يجد له سبباً يخرج به من الإحراج بلباقة . أو أن يكون قوى الشخصية يستطيع أن يدافع عن موقفه الروحى بإقناع الآخرين ... أو على الأقل يبعد عن الصحبة التى تحرجه وعن المناسبات التى يتعرض فيها لحرب الخجل .","عجيب أن المتدينين يخجلون من تدينهم ، بينما الخاطئون تكون لهم جرأة وجسارة فى أخطائهم وفى انتقادهم للأعمال الروحية .","حرب أخرى من حروب الشيطان هى :",{h:"٢٤ الوقـت الضـائـع"},"كما أن المؤمن قد يحارب أحياناً من شيطان الخجل ، كذلك يحاربه فى أحيان أخرى شيطان الوقت الضائع .",{h:"حياة الإنسان هى وقت ، يحاول الشيطان أن يضيعه ."},"والوقت الضائع هو الوقت الذى يمر بك بلا أدنى فائدة : لا فائدة روحية ، ولا فائدة عقلية أو صحية ، ولا فائدة للآخرين .","لا يهم الشيطان أن يجعلك فيه ترتكب خطية ... بل يكفيه أن هذا الوقت يضيع ، كجزء من حياتك بلا ثمر لك أو لغيرك .",{h:"والأمثلة كثيرة لهذا الضياع ، وهى متنوعة أيضاً ."},"منها أحاديث قد تطول بالساعات فى موضوعات لا فائدة منها ، وتكون بلا نتيجة . ومجادلات ومناقشات لا جدوى منها سوى تعب الأعصاب وضياع الوقت . وزيارات وسهرات ، وترفيهات زائدة عن الحد . ومسليات تأخذ كل الوقت وتعطل إيجابيات هامة"],88:["فى حياتك . ومثل جلوس البعض فى المقاهى للعب والكلام ، وقتل الوقت .","إن الذى يقبل ضياع وقته ، تكون حياته رخيصة فى عينيه !",{h:"٢٥ الشيطان يستخدم أعوانـاً"},"إنه لا يعمل وحده . فله أعوان من جنده الشياطين ، وأعوان من البشر أيضاً . وربما يكون هؤلاء من أحبائك أو أقربائك أو معارفك ، أو من الغرباء عنك .","لقد تكلم الشيطان على أفواه بعض الناس عند الصليب قائلاً للرب « إن كنت إبن الله ، إنزل من على الصليب » (متى ٢٧ : ٤٠) .",{h:"وقد يستخدم أقرباءك كما قيل « أعداء الإنسان أهل بيته »"},"(متى ١٠ : ٣٦) .","فيوحى إلى أحد الأحباء إليك جداً بنصيحة تتلف حياتك . أو يجعلهم يقفون ضد عملك الروحى ، أو ضد تكريسك ، أو ضد عبادتك أو يستخدمهم للتهكم عليك ... فكن محترساً . وكل ما تسمعه من النصائح إفحصه جيداً ، وتمسك بالحسن (١تس ٥ : ٢١) . ولكن إحذر من أن تقول لأحد أقربائك (أنت من أعوان الشياطين) .",{h:"وقد يكون أعوان الشيطان بالنسبة إليك صحبة شريرة ."},"وكما يقول الكتاب « المعاشرات الرديئة تفسد الأخلاق الجيدة » (١كو ١٥ : ٣٣) . لذلك ضع أمامك باستمرار المزمور الأول . فلا تسلك فى مشورة المنافقين ، وفى طريق الخطاة لا تقف ، وفى مجلس المستهزئين لا تجلس (مز ١) . إن كل هذه هى مجالس الشيطان ، هو يقودها ويدبرها ...",{h:"لا تظن أن الشيطان يتراءى لك بروُى العين لكى يحاربك ."},"فهذه درجة عالية جداً من الحروب لا يسمح بها الله إلا للقديسين الذين يحتملونها . فإن أراد مثلاً أن يشيرك ، يرسل اليك من يشيرك . ويكون هذا الذى أثارك من أعوان الشيطان ، على الأقل فى هذه النقطة بالذات . وهكذا كل من يعثرك : كل من يقودك إلى الخطية ، أو يساعدك عليها ، أو يوقعك فيها ...",{h:"والأشرار عموماً هم من أعوان الشياطين ."}],89:["كل أجهزة العبث وكل مسببات العثرات . وكل الفلاسفة الملحدين وكل دعاة الإلحاد . وكل ناشرى الشكوك ... وكل مسببى الشر ... وعن هذا كان داود النبى ورجاله يصرخون قائلين : إبطل يارب مشورة أخيتوفل (٢صم ١٥ : ٣١) . وكانت مشورة ضارة جداً بداود ورجاله ، قدمها أخيتوفل لأبشالوم فى ثورته على أبيه داود ...","إن الشيطان إذا أراد مثلاً أن يوقع العالم فى البدع والشكوك ، فلا يعنى هذا بالضرورة أن يفعل هذا بنفسه ، إنما يقدم هذه البدع إلى العالم عن طريق أعوانه من البشر ، ينشرونها ويشرحونها للناس ، ويدعونهم إلى اعتناقها ..",{h:"فعلينا أن نصلى كل حين ، أن ينجينا الرب من أعوان الشياطين ."},"وليس فقط من الشيطان وحده . بل من الشيطان وكل ملائكته وكل جنوده ، وكل أنصاره وأعوانه ، وكل منفذى مشيئته على الأرض ... كل قوات العدو ...",{h:"ملاحظــــة :"},"أ - من جهة حروب المناظر المخيفة ، وحروب الرؤى والأحلام والضلالات الشيطانية ، فقد تحدثنا عنها فى الفصل الثانى الخاص بصفات الشيطان وحروبه ، تحت صفة (قاس) وصفة (كذاب) .",{h:"ب - وهذه النقاط التى ذكرناها ليست هى كل حيل الشيطان ."},"ولا كل ما نعرفه عنها . فإن جعبة الشيطان لا تفرغ . وحيله لا تنتهى : القديمة والحديثة ، وما يمكن أن يخترعه الآن وفيا بعد . ولا شك أنه مجدد فى حيله ، رحمنا الله منه ومنها .","من أجل هذا ، نحن نصلى كل يوم فى تحليل الغروب :",{h:"« نجنا من حيل المضاد . وإبطل سائر فخاخه المنصوبة لنا » آمين ."}],90:[{h:"الفصل الرابع"},{h:"كيفية الإنتصار على حروب الشياطين"}],91:["كل ما ذكرناه قبلاً من صفات الشيطان وتنوع حيله ، إنما كتبناه لكم ، لا لكى تخافوا منه ، إنما لكى تحترسوا منه . وعلى الرغم من عنف الشيطان ومكره ، إلا أن الإنتصار عليه ممكن جداً ، بل إنه سهل أيضاً .",{h:"١ الإنتصـار ممكـن"},"إذا وضعت أمامك أن الإنتصار فى حروب الشياطين أمر صعب أو مستحيل ، ستخور قواك وتضعف وتستسلم ، وبالتالى ستسقط . أما أنت فإن حاربك الشيطان ، تأكد تماماً أنه فى إمكانك أن تنتصر ، وإلا ما كان الله يسمح بحرب غير متكافئة ...",{h:"تأمل باستمرار فى سير القديسين الذين انتصروا ."},"ضع أمامك قصة يوسف الصديق الذى انتصر على الرغم صعوبة التجربة التى تعرض لها . أما داود وشمشون فى سقوطها ، فخذ درساً من قصة كل واحد منها . إعرف ما هى أسباب سقوطه وتحاشاها . إن كل قصة سقوط أعطيت لنا ، إنما لفائدتنا ، لكى نحترس ونتعلم ...",{h:"الكتاب والتاريخ قدما لنا العديد من قصص الإنتصار ."},"نعرف أن التوبة ممكنة جداً ، مهما كانت الحالة سيئة ، وذلك من قصة توبة مريم القبطية ، وبيلاجية ، وبائيسة ، وأوغسطينوس ، وموسى الأسود . وكذلك توبة سليمان الحكيم ، وشمشون . لذلك إن حاربنا الشيطان باليأس من سوء ما وصلنا إليه نتذكر كل هذا لنتعزى ونتشجع .","ونعرف من قصة القديس الأنبا أنطونيوس ، كيف يمكن الإنتصار على الرغم من شدة الحروب وتنوعها وكثرتها . وكذلك من سير باقى القديسين ."],92:[{h:"كذلك علينا أن نتذكر باستمرار كيف أن الله بارك طبيعتنا ."},"إنه لما تجسد وأخذ هذه الطبيعة ، باركها . ولذلك نقول له فى القداس الغريغورى « وباركت طبيعتى فيك » . وأصبحت هذه الطبيعة قادرة جداً على قهر الشيطان . يكفى أننا صرنا هياكل للروح القدس ، وروح الله يسكن فينا (١كو ٣ : ١٦) . كما صرنا أبناء لله ، بطبيعة مولودة من فوق ، من الماء والروح (يو ٣ : ٣ ، ٥) .",{h:"وكما نتذكر القوة التى أعطيت لنا ، نتذكر القوى الروحية المحيطة بنا ."},"نتذكر أننا لسنا وحدنا فى حرب الشيطان . فروح الله القدوس يعيننا ، ويبكتنا على خطية (يو ١٦ : ٨) ، ويعلمنا كل شىء (١يو ٢ : ٢٧) ، ويرشدنا إلى كل الحق (يو ١٦ : ١٣) . فكيف يمكن أن ينتصر الشيطان علينا ، ونحن لنا شركة الروح القدس (٢كو ١٣ : ١٤) . وكذلك نعمة ربنا يسوع المسيح معنا (١كو ١٦ : ٢٣) . ولذلك نحيا ، لا نحن ، بل المسيح الذى يحيا فينا (غل ٢ : ٢٠) ... يضاف إلى هذا ملائكة كثيرون محيطون بنا ، أرسلوا لخدمتنا لنرث الخلاص (عب ١ : ١٤) . كما أن سحابة من الشهود الذين انتصروا (من القديسين) محيطة بنا أيضاً « لنطرح كل ثقل والخطية المحيطة بنا بسهولة » (عب ١٢ : ١) .",{h:"ولنتذكر أيضاً وعود الله لنا ، لكى نتشجع ..."},"إنه يقول « ها أنا معكم كل الأيام وإلى انقضاء الدهر » (متى ٢٨ : ٢٠) . « وإن كان الله معنا فمن علينا » (رو ٨ : ٣١) . إنه يقول لكل منا « لا أهملك ولا أتركك ... تشدد وتشجع . لا ترهب ولا ترتعب ، لأن الرب إلهك معك حيثما تذهب » (يش ١ : ٥ ، ٩) ، « أنا معك ، ولا يقع بك أحد ليؤذيك » (أع ١٨ : ١٠) .",{h:"ولنتذكر وعود الله للغالبين ، لكى تحمسنا فى جهادنا ."},"لذلك إقرأ وعود الله مثلاً لرعاة الكنائس السبع التى فى آسيا « من يغلب فسأعطيه أن يجلس معى فى عرشى ، كما غلبت أنا أيضاً وجلست مع أبى فى عرشه » ، « وسيلبس ثياباً بيضاً ... وسأعترف بإسمه أمام أبى وأمام ملائكته » (رؤ"],93:["٣ : ٢١ ، ٥) ، « سأعطيه أن يأكل من المن المخفى » ، « وأعطيه كوكب الصبح » ، « وأعطيه إكليل الحياة » (رؤ ٢ : ١٧ ، ٢٨ ، ١٠) ... حقاً من له أذنان للسمع فليسمع هذه الوعود التى تملأ القلب حماساً وقوة ...",{h:"كذلك فلنثق تماماً أن الله هو الذى يحارب عنا ."},"فمهما كان الشيطان قوياً ، من هو أمام قوة الله التى لا تحد ؟ وإن كان الشيطان كأسد يزأر ، فإن الله يرسل ملاكه ليسد أفواه الأسود (دا ٦ : ٢٢) . حقاً « إن الحرب للرب » (١صم ١٧ : ٤٧) . هو « يقاتل عنكم وأنتم تصمتون » (خر ١٤ : ١٤) . مادام الرب هو الذى يقاتل عنكم ، إذن لا تخافوا مطلقاً من الشيطان .",{h:"٢ لا تخـــافـــوا"},"لا تخافوا مطلقاً من الشيطان . فهو على الرغم من كل مواهبه وقوته وحيله ، كائن ضعيف أمام أولاد الله . قال عنه الرب :",{h:"« رأيت الشيطان ساقطاً مثل البرق من السماء » (لو ١٠ : ١٨) ."},"لقد داسه الرب على الصليب ، ولم يعد « رئيس هذا العالم » كما كان . بل قال عنه الرب قبيل الصليب « الآن دينونة هذا العالم . الآن يُطرح رئيس هذا العالم خارجاً » (يو ١٢ : ٣١) ، « رئيس هذا العالم قد دين » (يو ١٦ : ١١) . لذلك قال الرب :",{h:"« ها أنا أعطيكم سلطاناً لتدوسوا الحيات والعقارب وكل قوة العدو »"},"(لو ١٠ : ١٩) . إن وعد الرب لنا أن ندوس كل قوة العدو ، هو وعد كله قوة وعزاء ، ينزع الخوف من أى قلب ... ومن محبة الكنيسة لهذا الوعد الإلهى ، وضعته لنا فى آخر صلاة الشكر ، نذكره فى صلواتنا كل يوم بل كل ساعة ، حتى لا نخاف من الشيطان ولا من كل قوة العدو .",{h:"إذن ليس للشيطان سلطان علينا ، بل لنا سلطان عليه ."},"حتى الشياطين تخضع لنا باسم الرب (لو ١٠ : ١٧) . بل جعل الرب إخراج"],94:["الشياطين فى مقدمة الآيات التى تتبع المؤمنين (مر ١٦ : ١٧) . وطبعاً موهبة إخراج الشياطين لابد أن يسبقها الإنتصار أولاً فى حروب الشياطين . فالذى ينتصر على الشيطان فى تجاربه وإغراءاته ، ويجده الشيطان صلباً ، يبدأ أن يخافه . ويصير لهذا الإنسان سلطان عليه .",{h:"هناك محاضرة جميلة للقديس أنطونيوس عن ضعف الشياطين ..."},"سجلها القديس أثناسيوس الرسولى فى كتابه عن حياة القديس أنطونيوس ، يمكن أن تقرأوها ، لكى تتقوى قلوبكم فلا تخافوا الشياطين .","وكم من رهبان بسطاء ، لم ينالوا من العلم كثيراً ولا قليلاً ، إستطاعوا أن يحطموا الشيطان فى البرية . ومنهم القديس بولس البسيط .","كذلك فإن الشهداء والمعترفين استطاعوا أن يحطموا جميع إغراءاته وكل قوته وأسلحته .",{h:"والشيطان لا يسيطر إلا على الذى يخضع نفسه له ..."},"وعلى رأى المثل « إن العبيد هم الذين يخلقون السادة » ، أى أن ما فى العبيد من ذل وخضوع ، هو الذى يساعد السادة على السيطرة والتعالى . كذلك الحال مع الخاضعين للشيطان . أما الذين حررهم الإبن ، فبالحقيقة هم أحرار (يو ٨ : ٣٦) .",{h:"أكثر شىء يحبه الشيطان ، أن يجعلك تخاف منه ."},"لأنك فى خوفك تضعف أمامه وتضطرب ، وتظن أنك لا بد واقع فى يديه ، فتخور معنوياتك ، وتستسلم له ، عاجزاً عن المقاومة ... وهذا عين ما يريده منك ، لأن الخوف يعطيه ساطة عليك . ولكن السيد المسيح نصحنا ألا نخاف مطلقاً ، بقوله :",{h:"أنا هو . لا تخافوا . لا تضطرب قلوبكم ولا تجزع (متى ١٤ : ٢٧ ، يو ١٤ : ٢٧) ."},"لا تخف إذن . لأن قوة الله العاملة فيك ، هى أعظم بما لا يقاس من قوة الشيطان الذى يحاربك من الخارج . وثق أن خوفك فى داخلك هو أكثر ضرراً عليك من حرب الشيطان الخارجية .","إن الذين خافوا من جليات الجبار ، ضعفوا أمامه ولم يستطيعوا أن يقاوموه . أما داود الذى لم يخف ، فقد تقدم إليه بجسارة قلب ، معتمداً على معونة الرب ، وانتصر"],95:["عليه . وقصة داود وجليات تصلح رمزاً لحروب الشياطين . ولعلك تسأل داود عن السر فى عدم خوفه فيقول :",{h:"« الرب نورى وخلاصى ممن أخاف ؟! الرب عاضد حياتى ممن أرتعب ؟!"},"(مز ٢٧ : ١) ، ويستطرد « إن يحاربنى جيش فلن يخاف قلبى . وإن قام علىّ قتال ، ففى هذا أنا مطمئن » . لذلك أدخل حروب الشياطين بقلب مطمئن ، وحارب حروب الرب وأنت واثق أنك ستنتصر بمعونته . ما أصعب وما أخطر ما قيل فى سفر الرؤيا عن الخوف : « وأما الخائفون وغير المؤمنين والرجسون والقاتلون والزناة والسحرة وعبدة الأوثان وجميع الكذبة ، فنصيبهم فى البحيرة المتقدة بنار وكبريت » (رؤ ٢١ : ٨) .",{h:"وهكذا وضع الخائفين قبل غير المؤمنين وقبل القتلة والزناة !"},"ولعلك تسأل لماذا ؟ ربما لأن الذى يخاف من الشيطان ويستسلم له ، يقع فى كل هذه الخطايا . أو لأن الذى يخاف من الشيطان ويخضع له ، يكون خائفاً فى اليوم الأخير ، لأنه لم يجاهد ويغلب مثل المؤمنين المختارين .",{h:"ليتك تقرأ سير القديسين الذين لم يخافوا الشياطين ."},"إقرأ عن القديس الأنبا أنطونيوس الذى كانت الشياطين تظهر له على هيئة أسود ونمور ووحوش مفترسة ، تصيح بأصواتها المرعبة لتخيفه فيترك البرية ، ولكنه لم يخف ، وكان يجيبها بهدوء . أو إقرأ عن القديس مقاريوس الكبير الذى نام فى مقبرة ، وقد وضع جمجمة تحت رأسه . فكلّم الشياطين صاحبة هذه الجمجمة بصوت مسموع لكى تقوم معهم . فلم يضطرب القديس ، بل رفع رأسه قليلاً عن الجمجمة ، وقال لها « إن أردتِ ، قومى واذهبى معهم إلى الجحيم » ...","أما أنتم فلا تخافوا . لن تحاربكم الشياطين بهذه المخاوف التى حاربت بها القديسين . وهوذا الرسول يطمئنكم قائلاً :",{h:"الله أمين ... لا يدعكم تجربون فوق ما تستطيعون (١كو ١٠ : ١٣) ."},"إن الله لا يسمح للشيطان أن يجربكم بما هو فوق احتمالكم « بل سيجعل مع التجربة المنفذ لتستطيعوا أن تحتملوا » (١كو ١٠ : ١٣) . لهذا لا تخافوا مطلقاً من الشياطين وحروبهم ، سواء كانت بمخاوف أو بخطايا . إن الشيطان قد يثير ضجة ليخيف ، ولكنه لا يستطيع أن يعمل شيئاً للمؤمن الصامد ."],96:[{h:"إنى أشبّه ضجيج الشيطان بقصة الثعلب والطبلة ."},"كانت هناك طبلة معلقة على شجرة ، تعصف بها الريح فتحدث صوتاً مهولاً . ومرّ عليها ثعلب وراءه هذا الصوت الضخم فخاف أولاً . ثم تجرأ وهجم عليها ، فرآها فارغة من الداخل ، فضحك واحتقرها . يشبه ذلك أيضاً البالونة الكبيرة التى تبدو ضخمة ، ولكن شكّة دبوس صغير ، تجعلها كلا شىء ...","هكذا الشيطان فى حروبه : ضجيج بلا قوة . يحاول أن يخيف ، ولكنه لا يملك قوة . والشيطان ليس كائناً مطلق الحرية يفعل ما يشاء .",{h:"هناك الله ضابط الكل ، يمنع الشيطان حسبما يشاء ."},"وفى قصة أيوب الصديق ، ما كان الشيطان يتصرف حسب هواه ، بل إنه لا يحارب إلا فى النطاق الذى يسمح به الله (أى ١ ، ٢) .","إنه ليس قوياً بالشكل الذى تخافه . بل مجرد علامة الصليب فى إيمان ، تجعله يهرب من أمامك .",{h:"يريد الشيطان أن يوهمك بأنه قوى . ولكن لا تصدقه ."},"وتذكر باستمرار إنهزاماته المتكررة فى قصص القديسين . وتذكر أولئك الذين كانت لهم قوة أن يخرجوه ممن صرعهم . وكيف كان يصيح فى خوف أمام أولاد الله ويهرب .","إن عرفتم ضعف الشيطان ، قاوموه فى شجاعة .",{h:"٣ قـــاومـوه"},"ما أجمل أن نتذكر قول القديس يعقوب الرسول :",{h:"« قاوموا إبليس ، فيهرب منكم » (يع ٤ : ٧) ."},"وهنا عبارة « يهرب منكم » تدل على ضعف الشيطان . فالرسول لم يقل قاوموه فيتركككم ، إنما قال قاوموه فيهرب منكم ...","إن الشيطان يجس نبض الإنسان ، ليعرف ما هو ممدنه . فإن وجده من النوع الذى يخاف ، يبدأ أن يتسلى به ويجعله لعبته . أما إن وجده قوياً ويقاوم ، ولا يقبل الهزيمة ، حينئذ يخافه الشيطان ويهرب منه ... لذلك قاوموه ولا تغركم قوته . فالقديس بطرس الرسول لما قال « إبليس خصمكم كأسد زائر يجول ملتمساً من يبتلعه هو » قال بعدها مباشرة :"],97:[{h:"« فقاوموه راسخين فى الإيمان » (١بط ٥ : ٩) ."},"أى أن زئيره كأسد لا يخيفكم ، بل قاوموه . ليكن لكم قلب أسد أقوى منه . إن تذكرتم أن الشيطان يزأر كأسد ، تذكروا قول دانيال « إلهى أرسل ملاكه فسد أفواه الأسود » (دا ٦ : ٢٢) . قفوا أمام الشيطان إذن فى قوة وصمود ، بكل مقاومة ...",{h:"لا تستسلم ، بل اصمد فى الحرب ، كجندى صالح للمسيح ."},"حارب بكل قوتك ، واطلب معونة الرب . وهنا يعجبنى ما قيل فى سفر النشيد « تخت سليمان حوله ستون جباراً ... كلهم قابضون سيوفاً ومتعلمون الحرب . كل رجل سيفه على فخذه من هول الليل » (نش ٣ : ٨) . كن إذن متعلماً الحرب فى كل ما يثيره عليك الشيطان . وليكن سيفك على فخذك . بل كما يقول المرتل فى المزمور « تقلد سيفك على فخذك أيها الجبار ... إستله وانجح واملك » (مز ٤٥ : ٣ ، ٤) .",{h:"إن حاربك الشيطان بفكر أو شعور ، لا تستسلم بل قاوم ."},"لا تقبل كل ما يعرضه عليك . لا تفتح له قلبك ، ولا تفتح له عقلك ، ولا تسلّم له إرادتك ، ولا تتساهل معه ، بل قاومه بكل عنف . قاوم كل أفكاره وكل إغراءاته وكل شهواته وكل تجاربه . واحذر أن تتراخى ، لئلا تسمع تأنيب الرسول :",{h:"« لم تقاوموا بعد حتى الدم ، مجاهدين ضد الخطية » (عب ١٢ : ٤) ."},"حتى الدم ... حتى لو أدى الأمر أن تستشهد فى حربك ضده . كما يقال عن الضابط فى الجيش إنه « يحارب إلى آخر طلقة وآخر رجل » . وثق أنك لو فتحت للشيطان ولو ثقب إبرة فى فكرك أو فى إرادتك ، سيظل يتمادى ويوسع نطاقه حتى يتعبك . لذلك قاومه واطرده عنك . ومهما أراد أن يتفاهم معك فى شرح الخطية ، فلا تقبل .",{h:"لا تفاهم مع الشيطان فى الخطية . ولا نقاش ولا جدال ."},"وكما قال أحد القديسين « لا تأخذ وتعطِ مع إنسان يقاتلك به العدو » . إن الشيطان عندما يعرض عليك الخطية ، إنما يريد أن يتفاهم معك فيها ، أى يريد بقاءك فى مجال الخطية أطول مدة لتتأثر بها . وفى هذا أنت الخاسر .",{h:"لذلك قاومه من أول خطوة ، حينما تكون إرادتك فى يدك ."},"لأنك إن تأخرت فى مقاومته ، سيزداد تأثيره عليك ، وستقل إرادتك شيئاً فشيئاً ."],98:["وكلما طالت المدة معه تضعف مقاومتك ، مثلما حدث لشمشون مع دليلة ، لأنه لما كثر إلحاحها عليه ضاقت نفسه وأخبرها بسره (قض ١٣ : ١٥ - ١٧) .",{h:"لا تقل أنتظر على هذا الفكر حتى أعرف نهايته !"},"صدقنى ، أنت تعرف تماماً ما هى نهايته . فلا تخدع نفسك . مجرد فتح أبواب فكرك للشيطان هى خيانة للرب . لذلك إبعد كل البعد عن الشيطان وكل طرقه وكل جنده ، ولا تتساهل مع حيله ، ولا تتأخر . بل ارفضه بحزم وقل له « إذهب يا شيطان » (متى ٤ : ١٠) . فيعرف الشيطان أنك جاد فى رفضك له .",{h:"وبرفضك الحازم لكل أفكاره ، تصير لك هيبة عند الشيطان ."},"الشيطان يدرك تماماً بذكائه ما هى المقاومة الجادة ، وما هو التمريج بين الفرقتين (١مل ١٨ : ٢١) . يعرف من هو الذى يرفضه بقلب نقى ، ومن هو الذى يرفض من الخارج بينها قلبه متجاوب مع الشيطان . نعم إن الشيطان يمكنه أن يستنتج من الذى سيقاومه حتى الموت ومن الذى إذا ضغط عليه قليلاً يستسلم . فقاوم بجدية ، وبكل قوة ، ومن قلبك .",{h:"لست أحب أن يقول عنك الشيطان أنك إنسان طيب ."},"لا أريد أن يقول عنك : إنه إنسان طيب ، يثور علىّ جداً فى أول الأمر . ومع ذلك فإن قلبه أبيض سرعان ما يتصافى . ومع أنه يعارض كثيراً ، إلا أن الأمر ينتهى أخيراً بالموافقة والرضى ، مثل كل مرة ... !",{h:"والمقاومة هى رفض الخطية بكل صورها ، ورفض التنازل عن الكمال ."},"والإصرار القلبى على السير فى الطريق الروحى ، ورفض كل مقترحات الشيطان ، بل ومراقبة كل أفكاره من بعيد ، وعدم التفاوض مع شىء منها ، بل طردها من أول وهلة . وغلق كل أبواب النفس والفكر والقلب أمامها . وعدم التساهل فى شىء ، بحجة أن هذا الأمر بسيط ، أو أن هذه العثرة لا تؤثر فىّ !","المقاومة لازمة ولكن كيف ؟ يقول الرسول : قاوموه راسخين فى الإيمان ."],99:[{h:"٤ بالإيمــــــان"},{h:"أنت تغلب الشيطان بالإيمان . ولكن أى إيمان ؟ إنه :"},"الإيمان بعمل الله معك . الإيمان بأن الله يستطيع أن يبطل قوة العدو وكل فخاخه المنصوبة لنا . الإيمان بأن الله « لا يترك عصا الخطاة تستقر على نصيب الصديقين » (مز ١٢٥ : ٣) . الإيمان بأن الله أقوى من كل حيل العدو . وهو الذى يحارب عنا .","الحرب للرب (١صم ١٧ : ٤٧) ، الرب يقاتل عنكم وأنتم تصمتون (خر ١٤ : ١٤) .","تؤمن أن الحرب للرب . فلست أنت الذى تحارب الشيطان ، بل الله هو الذى يحاربه فيك ومعك . هو الذى يعطيك القوة التى تحارب بها ، والسلاح الذى تستخدمه ، وهو الذى يعطيك الخبرة فى مقاتلة الشياطين ، كما قال داود النبى :","« مبارك الرب ... الذى يعلم يدىّ القتال وأصابعى الحرب » (مز ١٤٤ : ١) .","فهل أنت أدخلت الله معك فى حروبك وفى تجاربك ومشاكلك ؟ إن كنت مهزوماً ، فربما لأنك لم تدخل الله معك . والله قادر تماماً أن يغلب بك ويتمجد فيك ، مهما كانت قوتك ضئيلة ومقاومتك لا شىء . فالكتاب يقول :","« ليس للرب مانع أن يخلص بالكثير أو بالقليل » (١صم ١٤ : ٦) .","إن حزقيا الملك لما وصله خطاب تهديد من ملك سنحاريب بجيشه الجبار ، وضع الخطاب أمام الله فى بيت الرب . وسكب نفسه أمام الله لكى يتصرف . وتدخل الله وأرسل ملاكه فضرب جيش سنحاريب (٢مل ١٩ : ٣٥) .",{h:"ونلاحظ كيف أن داود النبى كان ينتصر بالإيمان فى حروبه ."},"إنه يقول « لولا أن الرب كان معنا حين قام الناس علينا ، لابتلعونا ونحن أحياء ... نجت أنفسنا مثل العصفور من فخ الصيادين ... عوننا من عند الرب الذى صنع السماء والأرض » (مز ١٢٤) ، « عيوننا إليك يارب ... إحفظنى من الفخ الذى نصبوه لى ومن شكوك فاعلى الإثم » (مز ١٤١ : ٩) ، « ... ضاع المهرب منى ، وليس من يسأل عن نفسى . فصرخت إليك يارب . وقلت أنت هو رجائى وحظى فى أرض الأحياء » (مز ١٤٢ : ٤ ، ٥) ."],100:[{h:"بهذا الإيمان إنتصر داود فى حروبه كما انتصر على جليات ."},"مهما كان عدوك قوياً ، آمن أن الله سيخلصك منه . رتّل مع داود النبى وقل : صوت الرب يقطع لهيب النار . صوت الرب يزلزل القفر » (مز ٢٩ : ٧ ، ٨) . وفى إيمان قوى ، قاوم الشيطان مردداً قول بولس الرسول :",{h:"« أستطيع كل شىء فى المسيح الذى يقوينى » (فى ٤ : ١٣) ."},"وكن راسخاً فى هذا الإيمان ، واثقاً تماماً أن الله سيقف إلى جوارك وينصرك فى كل حروب الشيطان ، وأنه لن يتخلى عنك . وكما كان مع آبائنا وقادهم فى موكب نصرته ، سيكون معك أيضاً ، ولن يسمح أن يقع بك أحد ليؤذيك (أع ١٨ : ١٠) .",{h:"هذا الإيمان سيعطيك قوة قلب فى الداخل ، وقوة على الشيطان فى الخارج ."},"ولذلك نرى أن الرسول حينما يتكلم عن قتالنا مع الشياطين يقول « أخيراً يا إخوتى ، تقووا فى الرب وفى شدة قوته . البسوا سلاح الله الكامل لكى تقدروا أن تثبتوا ضد مكايد إبليس » (أف ٦ : ١٠ ، ١١) .","إذن الأمر لا تصلح له قوتنا الشخصية ، بل « تقووا فى الرب » . ولا تصلح له أسلحتنا البشرية ، بل علينا أن نلبس سلاح الله الكامل . ونشعر بقوة الله العاملة معنا .",{h:"وبهذه القوة ، لا تكون لنا روح الفشل ولا روح الإستسلام ."},"ولا تكون لنا روح التخاذل ، ولا روح اليأس ، لأن الله الذى نعتمد عليه قادر أن يحمينا فى كل حروب الشياطين . بهذه القوة استطاع القديس بولس الرسول أن يقول « حاربت وحوشاً فى أفسس » (١كو ١٥ : ٣٢) . وبهذه القوة إستطاع أن يقول « إن الله لم يعطنا روح الفشل بل روح القوة » (٢تى ١ : ٧) . لذلك أولاد الله لا يضعفون أبداً فى حروبهم .",{h:"إنهم جبابرة بأس ، لا يقوى عليهم الشيطان ولا الخطية ."},"ما أجمل التقرير الذى كتبه القديس يوحنا الرسول عن أولاد الله « كل من وُلد من الله لا يخطىء ، بل المولود من الله يحفظ نفسه ، والشرير لا يمسه » (١يو ٥ : ١٨) . كلهم لهم روح الغلبة ونيل المواعيد كما شرح الرب فى سفر الرؤيا (رؤ ٢ ، ٣) .","أنظروا إلى أيوب الصديق وشهادة الرب عنه « ليس مثله فى الأرض ، إنه رجل كامل ومستقيم ، يتقى الله ويحيد عن الشر . وإلى الآن هو متمسك بكماله » (أى ٢ :"],101:["٣) . هل مثل هذا يقدر عليه الشيطان ؟! كلا ، بل إن الله تحدى به الشيطان .",{h:"دائماً فى الحرب ضع أمامك الإنتصار وليس الفشل ."},"قل : أنا لا يمكن أن أفشل ، مادمت ألجأ إلى الله ، وهو يحارب عنى . أنا لا أخاف الشيطان ، بل أقول للرب « إن سرت فى وادى ظل الموت ، لا أخاف شراً ، لأنك أنت معى » (مز ٢٣) . إننى فى يمين الرب ، نقشنى على كفه (أش ٤٩ : ١٦) . وقال عن خرافه « أنا أعطيها حياة أبدية ، ولن تهلك إلى الأبد ، ولا يخطفها أحد من يدى ... ولا يقدر أحد أن يخطف من يد أبى » (يو ١٠ : ٢٨ ، ٢٩) .","بهذا الإيمان يمكن أن تنتصر . كذلك تنتصر بالإتضاع .",{h:"٥ بالإتضــــــاع"},"كان القديس الأنبا أنطونيوس يغلب الشياطين بالإتضاع :","فحينما كانوا يتكاثرون عليه ، كان يقول لهم باتضاع « أيها الأقوياء ، ماذا تريدون منى أنا الضعيف ؟! » وكان يصلى قائلاً « إنقذنى يارب من هؤلاء الذين يظنون أننى شىء ، مع أنى أضعف من أن أقاتل أصغرهم » . ولما كان الشياطين يسمعونه وهو يصلى هذه الصلاة المملوءة اتضاعاً ، ما كانوا يحتملون ، بل كانوا ينقشعون كالدخان .",{h:"والقديس مقاريوس الكبير كان يغلب الشيطان أيضاً بالإتضاع ."},"فى إحدى المرات ظهر الشيطان للقديس مقاريوس وقال له « ويلاه منك يا مقاره ! أى شىء أنت تعمله ونحن لا نعمله ؟! أنت تصوم ونحن لا نأكل . أنت تسهر ونحن لا ننام . أنت تسكن البرارى والقفار ونحن كذلك . ولكن بشىء واحد تغلبنا » فسأله القديس ما هو؟ فأجاب : باتضاعك تغلبنا .",{h:"الإتضاع يغلب الشيطان لأسباب كثيرة منها :"},"أولاً : لأن الشيطان غير متضع . والإتضاع يذكره بكبريائه التى أسقطته .","ثانياً : لأن الإتضاع يذكره بصورة المسيح الذى أخلى ذاته وأخذ شكل العبد ، لكى يخلص البشرية . ومجرد هذه الذكرى تتعبه ، فيذهب ."],102:["ثالثاً : لأن المتضع إذ هو معترف بضعفه يستعين بقوة الله لتعينه فى حروب الشيطان . وهذا أخوف ما يخافه الشيطان .","ولهذا كتبت مرة فى مذكرتى العبارة الآتية :",{h:"قال الشيطان لله : أترك لى الأقوياء فإننى كفيل بهم . أما الضعفاء فإننى لا أقوى عليهم . فإذ يرون أنه ليست لهم قوة ، يحاربونى بقوتك ."},{h:"إن قصة أنبا صرابامون أبى طرحه تثبت إخراج الشياطين بالإتضاع ."},"كانت زهرة إبنة الحاكم عليها شيطان ، فجاءوا إلى البابا ليصلى عليها ليخرج . فقال لهم البابا فى اتضاع « أنا ليست لى هذه الموهبة . إذهبوا إلى الأنبا صرابامون أبى طرحه » . فذهبوا إليه . فقال لهم فى اتضاع « صلاتى لأجلها لا تكفى » . وطلب صليب البابا ليرشمها به ، قائلاً إنه « ببركة هذا الصليب تشفى » . وكان يريد بهذا أن ينسب شفاءها إلى البابا وليس إلى نفسه . وهكذا شفيت ، لأن الشيطان لم يحتمل هذا الإتضاع .","تحدثنا عن أهمية الإتضاع فى حروب الشياطين ، مع بعض قصص من سير القديسين . وبقى أن نعرض لسؤال هام وهو :",{h:"ما هو الأثر العملى للإتضاع للإنتصار فى حروب الشياطين ؟"},"١ - المتضع يعترف دائماً بضعفه ويطلب من الله المعونة فتأتيه بقوتها . وهكذا ينتصر لأنه لم يعتمد على ذراعه البشرى ، بل على معونة الله .","٢ - المتضع يحترس من أقل الخطايا ، ويخاف السقوط فيبعد عن جميع العثرات . وبالتالى لا يلقى نفسه فى تجربة ولا يتهاون ، وبهذا الحرص الناتج عن الإتضاع ينتصر على الشيطان .","٣ - المتضع يكشف حروبه وضعفاته . فيمكن علاجها . وبهذا ينتصر .","٤ - المتضع دائماً يصلى . بل إن أصغر خطية يجعلها موضوعاً لصلاته . وهكذا يُدخل الله معه فى حروبه . وبهذا ينتصر .","٥ - نفس الإتضاع : فضيلة لا يحتملها الشياطين فيهربون .","وكما ينتصر الإنسان على الشياطين بالإتضاع ، ينتصر أيضاً بالحكمة والإفراز ."],103:[{h:"٦ بالحكمة والإفـراز"},"إن أتاك فكر ، لا بد أن تفحصه جيداً : هل هو من حروب الشياطين ؟ وأين الحق فيه ، وأين الباطل ؟ وهكذا تفعل مع الرؤى والأحلام ، ومع نصائح الآخرين ... ومع كل ضلالات الشياطين ... ومن أجل هذه المعرفة أو التمييز أو الإفراز ، ينبهنا الرسول بقوله « لا تصدقوا كل روح . بل امتحنوا الأرواح هل هى من الله ؟ ... » (١يو ٤ : ١) .",{h:"فما هى مصادر الحكمة هذه والمعرفة والإفراز ؟"},"هناك إنسان حكيم بطبيعته . خلقه الله هكذا ، ومنحه الذكاء والحكمة والمعرفة ، ويستطيع أن يكتشف حرب الشيطان ويميزها ، ويفرزها عن الفكر الروحى . وهناك من يقتنى الحكمة عن طريق القراءة فى الكتاب المقدس وفى الكتب الروحية وسير القديسين . ونوع ثالث يقتنى الحكمة بالخبرة . وفى كل سقوط يأخذ درساً ويعرف حيلة العدو ، فلا يسقط مرة أخرى . وفى ذلك قال أحد القديسين :",{h:"لا أتذكر أن الشياطين أطفوني فى خطية واحدة مرتين ."},"وقد يقتنى الإنسان الحكمة عن طريق المشورة والإسترشاد والتعلم .","وإذ يميز حرب الشيطان ويكشفها ، يبعد عنها ، فلا يخدعه العدو .","نقول هذا عن الذى يريد أن ينتصر . لأن هناك إنساناً يعرف أن هذه حرب من حروب العدو ، ومع ذلك يستمر فيها لأسباب داخل نفسه ، أو لإنحراف ، أو لأنه غير قادر على المقاومة ...",{h:"والحكمة كما تكشف حيل الشياطين ، تعطى أيضاً وسيلة للتصرف ."},"فالإنسان الحكيم يعرف كيف يفلت من حيل الشيطان : كيف يهرب من فخاخه ، وكيف يقوم إذا سقط . وكيف يبعد عن كل سبل الخطية .","وإذا لم يعرف ، تدعوه الحكمة أن يستشير ..."],104:[{h:"٧ بالمشـــورة والإعتـراف"},{h:"الإرشاد الروحى يكشف حيل الشياطين ، ويشرح كيفية النجاة منها ."},"كما أن المرشد يصلى من أجل النفس التى تكشف أفكارها لتنجو . وفى هذا قال القديس بولس الرسول « أطيعوا مرشديكم واخضعوا . لأنهم يسهرون لأجل نفوسكم كأنهم سوف يعطون حساباً ... لكى يفعلوا ذلك بفرح ... » (عب ١٣ : ١٧) . ولهذا فإن الذى يسلك فى الطريق الروحى بهواه ، يمكن أن يسقط فى فخاخ الشياطين . وقد قيل :",{h:"الذين بلا مرشد يسقطون مثل أوراق الشجر ."},"من أجل هذا كانت أهمية أب الإعتراف فى الكنيسة . تكشف له ما فى قلبك وتخجل وتنسحق نفسك أمام الله فى حضرته . ويرشدك إلى ما ينبغى أن تفعله . والإعتراف يكشف حروباً ربما المبتدئون لا ينتبهون لها .",{h:"وكثير من الخطايا يخلص منها المعترف بسبب فضيلة الإعتراف ."},"شياطينها لا تحتمل إنسحاق المعترف فى مذلة فتهرب . كما أن الشياطين تحب أن تعمل فى الظلمة ، والإعتراف يكشفها . كذلك الإرشاد يكسر فخاخها . والتحليل يضيع تعبها . وهكذا نرى أن الإنسان المعترف بخطاياه والمطيع للإرشاد ، يسلك فى طريق التوبة ، وينجو من حروب الشياطين . وحتى إن لم تتركه الخطية تماماً ، فإن قوتها تضعف فى مهاجمته .",{h:"لهذا يحاول الشيطان أن يمنع الإعتراف . ويشكك فى أب الإعتراف ."},"يدخل هنا شيطان الخجل ليمنع الإعتراف . ويدخل شيطان الشهوة ليقول « ما الفائدة إن كنت سأعود إليك ؟! » . ويدخل شيطان الفكر والجدل ليناقش موضوع الإعتراف جملة . ويدخل شيطان الشك ليشككك فى الإعتراف وأب الإعتراف .","أما أنت فكن ثابتاً . واعترف بكل هذا أيضاً . فلا يجد الشيطان حيلة فيك ، ويعتبرك خصماً متعباً ، فيتركك ..."],105:[{h:"٨ بالسـهــر والحـرص"},"لا يكفى أن تعترف وتكشف نفسك وتطلب الإرشاد ، إنما ينبغى أن تكون ساهراً على خلاص نفسك (*) . وهوذا الرسول يقول :",{h:"إصحوا واسهروا ، لأن إبليس خصمكم مثل أسد زائر ... » (١بط ٥ : ٨) ."},"إسهروا لأن عدوكم متيقظ وقوى ، لئلا يأخذكم فى ساعة غفلة أو تهاون أو تراخ ، أو فى ساعة فتور ، أو فى حالة نسيان لواجباتكم الروحية وعدم اهتمام بخلاصكم .",{h:"والكنيسة توجد لنا مناسبات عديدة تنادينا أن نتيقظ :"},"هناك أصوام تقول لنا إصحوا واستعدوا . وهناك قداسات تقول لنا تعالوا تناولوا باستحقاق . وعظات وقراءات واجتماعات كلها تنادينا أن نهتم بأبديتنا ، ونحارب حروب الرب بكل اهتمام . لذلك علينا أن نتيقظ لأن الكنيسة تدعونا أن نقول للرب فى بدء صلاة نصف الليل « إنزع من عقولنا نوم الغفلة ، وأعطنا يارب يقظة ... » .",{h:"الشيطان يحب أن يكون (فريسته) متهاوناً ليسهل القضاء عليه ."},"إن المتهاون فى واجباته الروحية من السهل أن يسقط ، إذ لا يكون محصناً باستعداد روحى ، ولا بالمشاعر الروحية التى تغرسها وسائط النعمة فى القلب . لذلك فى بعض الأوقات إذا أراد الشيطان إسقاط إنسان ، يبدأ معه بسلاح التهاون ، فيكسل فى صلواته وقراءاته واجتماعاته الروحية واعترافه وتناوله . وإذ لا يكون منتبهاً لنفسه يضربه الشيطان فيسقط .","أما المهتم بواجباته الروحية ، فإن الله يكون دائماً أمام عينيه ، فيستحى من السقوط ، كما أن الله يعينه فى حروبه .",{h:"هناك نوع لا يصحو لنفسه إلا بعد السقوط ."},"مثال ذلك الإبن الضال ، الذى لم يستيقظ إلا بعد الضياع والإستمرار فيه مدة . وكذلك داود النبى حينما سقط لم يكن صاحياً لنفسه . إنما صحا حينما قال له ناثان « أنت هو الرجل » ! وكذلك سليمان الحكيم لم يكن فى حكمته حينما سقط . ولم يشعر أن الكل باطل وقبض الريح ، إلا بعد أن أغوته النساء ... !","(*) إقرأ كتابنا [ السهر الروحى ] ليشرح لك هذا الموضوع بالتفصيل ."],106:[{h:"أما أنت فمادام عدوك يزأر ، إعلن حالة التعبئة العامة ."},"قل للشيطان قف عند الحدود لا تتعداها . وجهز أنت كل أسلحتك من صوم وصلاة ، وسهر ويقظة قلب ، وتوبة واحتراس ، وتمسك بالرب . وكن متنبهاً لكل حركة من العدو ، لكل رغبة ، لكل فكر ، لكل حركة من الحواس . وكما يقول الرسول « مستأسرين كل فكر لطاعة المسيح » (٢كو ١٠ : ٥) .","وفى سهرك الروحى ، إستمع إلى قول الرسول :",{h:"« إلبسوا سلاح الله الكامل ، لكى تقدروا أن تثبتوا ضد مكايد إبليس »"},"(أف ٦ : ١١) . كن ساهراً « وسيفك على فخذك من هول الليل » (نش ٣ : ٨) . نقصد سيف الروح ، ودرع البر ، وترس الإيمان (أف ٦) ، وكل الوسائط الروحية .",{h:"وهذا الإحتراس ، أو هذا الإستعداد ، يكون معك مدى الحياة ."},"إحترس حتى الموت . وكن صاحياً إلى آخر لحظة « لئلا يأتى بغتة فيجدك نائماً » (مر ١٣ : ٣٦) . السيد المسيح حورب حتى وهو على الصليب ، حين قيل له « إن كنت إبن الله إنزل من على الصليب » ... فكن إذن مستعداً باستمرار . ولا تقل قد كبرت ، أو قد خلصت !",{h:"واحترس من الشيطان الذى يحارب باللاهوتيات ."},"لئلا تقول « إرحمنى يارب » ، فيأتيك الشيطان وينهرك قائلاً : لا تقل إرحمنى مطلقاً . فقد رحمك الرب منذ زمان حينما فداك على الصليب وخلصك . إذن ما معنى كلمة « إرحمنى » هذه ؟! إنها هرطقة ! قل له : لقد رحمنى الرب وخلص نفسى . ولكننى لا أرحم نفسى ، بل كل يوم أضيع خلاصها ، لذلك أصرخ وأقول : إرحمنى . إسهر إذن على خلاص نفسك .",{h:"وفى سهرك أسلك بكل جدية وبكل تدقيق ."},"وكن أميناً جداً حتى فى القليل . فإن أمانتك وتدقيقك وجديتك ، تجعل الشيطان يهرب منك ، شاعراً أن حربه معك هى حرب خاسرة .","وهناك سلاح هام للإنتصار ، وهو أهم سلاح ، أعنى الصلاة ."],107:[{h:"٩ بالصـــلاة والصــوم"},"لما عجز التلاميذ عن إخراج شيطان ، قال لهم الرب :",{h:"هذا الجنس لا يخرج بشىء ، إلا بالصلاة والصوم (مر ٩ : ٢٩) ."},"وهكذا نرى أهمية الصلاة والصوم فى الإنتصار على حروب الشياطين ، أو بمعنى آخر أهمية إدخال الله فى حياتنا وحروبنا ، صارخين إلى الله وقائلين « نجنا من حيل المضاد ، وإبطل سائر فخاخه المنصوبة لنا » .",{h:"إننا نفشل فى حروبنا إن واجهنا الشيطان وحدنا ، بدون الله ."},"إنما نحن نقول لله : عدونا هذا القوى الذى يجول كأسد يزأر ، عدونا هذا الماكر الواسع الحيلة ، نحن يارب لا نقدر عليه بمهارتنا وذكائنا ، إنما النجاة هى من عندك أنت . نحن على قدر إمكاننا نميز الأرواح ، ونعرف الفكر الذى من عنده ونحترس منه . ولكن القوة تأتى من عندك .",{h:"بقدر إمكاننا نجاهد . ولكن أنت الذى تقودنا فى موكب نصرتك ."},"فى كل خطية كبيرة أو صغيرة ، لا نريد أن نقف وحدنا تجاه الشيطان ، إنما لابد أن يقف الله معنا . ولذلك نقول له فى بدء صلاة باكر « نسألك أن تحفظنا فى هذا اليوم بغير خطية » ، ونقول له فى ختام هذه الصلاة « هب لنا فى هذا اليوم الحاضر أن نرضيك فيه ، واحرسنا من كل شىء ردىء ، من كل خطية ، ومن كل قوة مضادة » ، « أحطنا بملائكتك القديسين ، لكى نكون بمعسكرهم محفوظين ومرشدين » ...",{h:"والمفروض أن نطلب معونة الله من أول الطريق ."},"كثيرون لا يلجأون إلى الله إلا بعد أن تضيق بهم السبل جداً ، كالذى لا يلجأ إلى الطبيب إلا بعد أن يشتد عليه المرض ويصل إلى حالة سيئة للغاية . أما نحن ، فإن الكنيسة تعلمنا أن نصلى من أجل النجاة قبل أن تأتى الحروب ...",{h:"وهكذا تكون صلاة وقائية ، قبل اللجوء إلى الصلاة العلاجية ."},"إننا نطلب من الله أن يبطل كل فخاخ الشيطان المنصوبة لنا . ولا ننتظر حتى نقع فى تلك الفخاخ ، ثم نطلب من الله أن يخرجنا منها ! وهكذا فى صلاة الشكر نطلب من"],108:["الله أن يبعد عنا « كل تجربة ، وكل فعل الشيطان ... وقيام الأعداء الخفيين والظاهرين » ... يبعدها عنا قبل أن تجىء ... « ولا يدخلنا فى تجربة » .",{h:"نحن لا نضطرب أمام حروب العدو ، إنما نطلب معونة الله ."},"هذا الشيطان الذى له خبرة ٧٠٠٠ سنة فى محاربة البشر ، أنا لا أقدر عليه . أما أنت يارب فأزلى ، كائن قبل أن يكون هذا الشيطان . وهو صنعة يديك من قبل أن يسقط . وتعرف كل حيله . وتستطيع أن تربطه وتقيده وتضع له حدوداً ، بل وتطرده طرداً . لذلك نجنى منه .","هكذا إلجأ إلى الصلاة . لأنك بدونها لا تخلص .",{h:"وإن فشلت فى محاربة العدو ، إعرف أنك فاشل فى صلواتك ."},"ولو كانت لك صلاة قوية ، لانتصرت حتماً . وتأكد أن الله إن سمع صراخ المساكين ، لابد أن يستجيب . إنه نفسه يقول « من أجل صراخ المساكين وتنهد البائسين ، الآن أقوم - يقول الرب - أصنع الخلاص علانية » (مز ١٢ : ٥) . لذلك قل له : « قم أيها الرب الإله ، وليتبدد جميع أعدائك ، وليهرب من قدام وجهك كل مبغضى إسمك القدوس » (عد ١٠ : ٣٥) . قم يارب « فإن البار قد فنى ، وقلت الأمانة من بنى البشر » (مز ١٢ : ١) . قم إصنع الخلاص علانية « إستل سيفك على فخذك أيها الجبار . إستله وانجح واملك » (مز ٤٥ : ٣ ، ٤) .",{h:"إن الشياطين هم أعداؤك يارب ، قبل أن يكونوا أعدائى ."},"إنهم يحاربون ملكوتك فىّ وفى غيرى ، فحاربهم عنى وعن الجميع . ولا تتركنا وحدنا فى حروب الشياطين ، لأننا بدونك لا نستطيع أن نفعل شيئاً (يو ١٥ : ٥) .","إن داود الذى اختبر نصرة الرب فى حروبه قال فى المزمور :",{h:"« يمين الرب صنعت قوة . يمين الرب رفعتنى » (مز ١١٨ : ٥ ، ٦) ."},"فهل جربت يمين الرب فى حياتك ؟ هل جربت خلاص الرب ، الذى قال عنه موسى النبى « قفوا وانظروا خلاص الرب ... الرب يقاتل عنكم وأنتم تصمتون » (خر ١٤ : ١٣ ، ١٤) . لو أنك اختبرت هذا ، لاستطعت أن تقول مع داود النبى « الرب لى معين وأنا أرى بأعدائى » (مز ١١٨) ، « يسقط عن يسارك ألوف ، وعن يمينك ربوات ، وإليك لا يقتربون » (مز ٩١ : ٧) ."],109:["إنك جربت تفكيرك وذكاءك وعزيمتك وتدبيرك ، ومعونات الناس لك ، ولكن هل جربت خلاص الرب ؟ هل جربت مفعول الصلاة القوية الممسكة بقرون المذبح ؟ ليتك تفعل ... لا تكن كإنسان يقول للرب :",{h:"أتركنى يارب أن أعمل . وإن وقعت ولم أقدر أن أقوم ، سأطلبك ."},"ولماذا تنتظر إلى أن تقع ولا تقدر أن تقوم . أطلبه من الآن ، تجد قوته إلى جوارك لكى لا تقع . طبعاً إن وقعت وطلبت الله سيقيمك ، لكنك ستقوم وأنت مجروح ومكسور ! إلجأ إلى اليد الحصينة التى تحميك ، واصرخ إلى الرب قائلاً « نجنا من حيل المضاد ، وإبطل سائر فخاخه المنصوبة لنا » ، وحينئذ يتدخل الله لإنقاذك . وحينئذ تغنى مع المرتل :",{h:"« الفخ انكسر ونحن نجونا . عوننا من عند الرب الذى صنع السماء والأرض »"},"(مز ١٢٤ : ٧ ، ٨) . أطلب من الرب إذن أن ينصرك كما نصر المجاهدين قبلك ، وأن يعطيك قوة كما أعطاهم ، وأن يعطيك نعمته وفعل روحه القدوس ، لكى تكون محصناً بقوته الإلهية ... واطلب إليه أن ينتهر الشيطان كما انتهره من قبل ، ويقول له « إذهب يا شيطان » (متى ٤ : ١٠) .",{h:"١٠ إذهـب يـا شيـطـان"},"عبارة (إذهب يا شيطان) التى بها إنتهر الرب الشيطان ، لم تكن للتجربة على الجبل فقط ، إنما أيضاً لكل حروب الشيطان مع البشر ...","فليتك تختبر قوة هذه العبارة فى حياتك ، حينما يتدخل الرب ويطرد الشيطان ، فلا يشتد فى حربه عليك ، أو على الأقل يفعل كما فعل فى التجربة على الجبل ويتركك إلى حين (لو ٤ : ١٣) .","فإن وجدت أن الحرب قد رفعت عنك ، ووجدت أن الأفكار والشهوات لا تتعبك كما كان يحدث قبلاً . وإن فارقك الفتور وأشرق عليك نور جديد ، فاعرف أن الرب قد انتهر الشيطان وطرده ... ليذهب بعيداً عنك .",{h:"إن الله لا يسمح أن نكون محاربين باستمرار من الشيطان ."},"ولا يسمح أن يمسكنا الشيطان بقبضته . وإن كان الله يترك الشيطان أحياناً"],110:["ليجربنا ، فذلك لكى ننال الفوائد الروحية التى فى هذه الحروب . وعندما يضغطنا الشيطان باليأس أو بالإضطراب ، ينتهره الله قائلاً : إذهب يا شيطان .",{h:"قد تمر على الإنسان أوقات راحة من حروب الشياطين ."},"ويجد نفسه طليقاً فى مجال الله ، فرحاً بعشرته ، بل يتعجب كيف كان يخطىء قبلاً ويسقط . وفى وسط هذا الجو الروحى والجو المريح ، يشعر أن المسيح له المجد الذى جرب حروب الشياطين ، قد انتهر الشيطان من أجله ... وكأنه يقول للشيطان : أنا قد أعطيتك حرية التجربة والإختبار ، ولكن ليس إلى هذا الحد . فاذهب يا شيطان ...",{h:"صدقونى يا إخوتى إن الخطايا التى نقع فيها هى شىء قليل من حروب الشياطين التى كان يمكن أن تضغط علينا بعنف . ولكن الله منعها عنا قبل أن تصل إلينا . ولم يسمح للشيطان أن يجربنا بها . أما الحروب التى سمح الله بها ، فهى التى تقدر أن تقاومها . ولو سمح بالأخرى ما كنت تحتمل ..."},"وقد تتعرض أحياناً لحرب قاسية ، وتكون على وشك السقوط ...",{h:"ثم تجد أنك نجوت من هذه الحرب بدون أن تشعر ."},"وذلك لأن الله قد تدخل . وقال للشيطان إذهب ... إنك ضغطت على هذا الإنسان بعنف ... ويذكرنا هذا بأن الله كان يضع للشيطان حدوداً فى حربه مع أيوب الصديق : مرة لا يمد يده إليه (أى ١ : ١٢) ، ومرة لا يمد يده إلى نفسه (أى ٢ : ٦) .",{h:"إن عبارة « إذهب يا شيطان » فيها عزاء كبير لنا ."},"تشعرنا أن حروب الشيطان محدودة ، وأنه ليست له حرية مطلقة حتى يفعل بنا ما يشاء . وأيضاً بأن الشيطان هو أيضاً تحت قبضة ضابط الكل ، القادر أن ينتهره حينما يشاء ، ويمنعه ويضع له حدوداً وسدوداً وقيوداً ... بل ويطرده . فلنطمئن إذن أن الحروب التى نتعرض لها هى فى حدود قوتنا وطاقتنا ومقاومتنا ، وأنه بإمكاننا أن ننتصر عليها ، إن أردنا .","إن الله أعطانا سلطاناً على الشيطان ، نقول له إذهب فيذهب .",{h:"ولكننا فى أحيان كثيرة لا نشاء أن نقول له : إذهب ."},"أحياناً نتراخى فى حربه ، ونعطيه فرصة فينا ومجالاً . وأحياناً نرضخ ونتراخى"],111:["ونؤجل طرده . وأحياناً نفاوضه ونهادنه ولا نكون حازمين معه . بل أحياناً نستسلم له ، أو نتعاون معه ... ولا نشاء مطلقاً أن نقول له : إذهب ...",{h:"بل أخشى أن البعض يفتح له قلبه وحواسه ، ويرحب به !"},"كثيرون لا يستطيعون أن يطردوا الشيطان بكلمة إذهب يا شيطان . لأن بينهم وبين الشيطان صداقات ومحبة وعشرة . وهناك قيود تربطهم به وتخضعهم لإرادته . بل لو انتهره الرب وذهب عنهم ، قد يسعون هم إليه ، ويتوسلون إليه قائلين : إرجع إلينا وأعنا ... ! هم لا يريدون أن يبتعد الشيطان عنهم !","إن القلب النقى هو الذى يستطيع أن ينتهر الشيطان ويقول له : إذهب . ويفرح بانتهار الرب له . ولكن البعض له حاجة عند الشيطان يستبقيه من أجلها ، بل ويدافع عنه ! تماماً مثلما فعل أهل أفسس فى دفاعهم عن آلهتهم أرطاميس وتمثالها (أع ١٩ : ٢٨) . لذلك فإن الرب كان أحياناً - قبل أن يشفى إنساناً - يسأله أولاً : أتريد أن تبرأ (يو ٥ : ٦) .",{h:"فإن شاء الرب أن يطرد الشيطان عنك ، إستجب له ..."},"فلتتحد إرادتك مع إرادة الله فى طرد الشيطان من حياتك ، مهما كان ذلك سيكلفك ، ومهما (أتعبك) ذهاب الشيطان بعيداً عنك . لأن الكتاب يقول « أمينة هى جراح المحب . وغاشة هى قبلات العدو » (أم ٢٧ : ٦) . فقد يقبّلك الشيطان متظاهراً بالحب ، موهماً إياك أنه يسعدك ويحقق شهواتك ورغباتك ، لكى لا تطرده من حياتك ، بينما هو يعدّ لك فخاخاً لهلاكك ! فلا تصدقه .","أدخل إلى أعماق قلبك وفكرك ، وقل : إذهب يا شيطان .","وحينما ينتهر الرب هذا الشيطان ، إنتهره معه بكل صدق وبكل حزم وحسم ، مع إلغاء كل ما سبق من علاقات بينك وبينه . ولا تحاول أن تجمع بين الله والشيطان فى حياتك . لأنه « لا شركة بين النور والظلمة » (٢كو ٦ : ١٤) .","لا تصادق عدواً لله ، ولا تشترك معه فى أى عمل . واطرد كل متعلقاته فى حياتك وفى بيتك وفى مكتبتك . كل صوره ، وكل كتبه ومجلاته ، وكل ملاهيه وأغانيه وقصصه ، وكل أجهزته ، وكل أعوانه . قل له : إذهب يا شيطان ، ومعك كل ما ينتمى إليك . واقفل أمامه جميع الأبواب حتى لا يعود إليك ."],112:[{h:"وليكن طرداً ، بكل جدية ، طرداً نهائياً ، بتصميم ..."},"لا طرداً متذبذباً ، متردداً ، قلقاً ... كما يقول المثل العامى « عين فى الجنة ، وعين فى النار » ! وتأكد تماماً أن بقاء الشيطان بكل حيله ، خسارة لك . واحترس من أن تقبل ربحاً عن طريقه - لأن هذا (الربح) يكون ثمناً لحياتك وأبديتك ...","ومن الوسائل التى تساعدك فى طرد الشيطان :",{h:"١١ مقـابـلـة الخطيـة بالوصـيـة"},{h:"إحفظ عدداً من الآيات فى مواجهة الخطايا التى تحاربك ."},"فمثلاً إن حاربك الشيطان بالغضب قل له « إن غضب الإنسان لا يصنع بر الله » (يع ١ : ٢٠) . أو قول أحد القديسين « ولو أقام الغضوب أمواتاً ، فما هو مقبول عند الله ، ولا يقبله أحد من الناس » .","وإن حاربك العدو بنظرة شريرة ، ضع أمامه قول الرب « من نظر إلى إمرأة واشتهاها ، فقد زنى بها فى قلبه » (متى ٥ : ٢٨) . وإن حاربك بالزنا ، تذكر قول الرسول « ألستم تعلمون أن جسدكم هو هيكل الروح القدس » (١كو ٦ : ١٩) ، « ألستم تعلمون أن أجسادكم هى أعضاء المسيح . أفآخذ أعضاء المسيح وأجعلها أعضاء زانية ؟! حاشا » (١كو ٦ : ١٥) .","وإن حاربك الشيطان بأخطاء اللسان ، ضع أمامك آيات الكتاب « كثرة الكلام لا تخلو من معصية » (أم ١٠ : ١٩) ، « ليكن كل إنسان مسرعاً إلى الإستماع ، مبطئاً فى التكلم » (يع ١ : ٢٠) ، وأيضاً قل « ضع يارب حافظاً لفمى ، وباباً حصيناً لشفتى » (مز ١٤١ : ٣) .","وإن حاربك الشيطان بمحبة العالم الحاضر ، وما فيه من مغريات ، ضع أمام ذلك قول الكتاب « محبة العالم عداوة لله » (يع ٤ : ٤) . وأيضاً « لا تحبوا العالم ولا الأشياء التى فى العالم . إن أحب أحد العالم ، فليست فيه محبة الآب » (١يو ٢ : ١٥) ، « العالم يمضى وشهوته معه » (١يو ٢ : ١٧) . وأيضاً تذكر كل ما ورد فى سفر الجامعة عن هذا الموضوع ، وبخاصة قول الكتاب « باطل الأباطيل . الكل باطل"],113:["وقبض الريح . ولا منفعة تحت الشمس » (جا ١ : ٢ ، ١٤ ، ٢ : ١١) .","وإن حاربك الشيطان بالكبرياء ، تذكر قول الكتاب « قبل الكسر الكبرياء ، وقبل السقوط تشامخ الروح » (أم ١٦ : ١٨) . وأيضاً « يقاوم الله المستكبرين . أما المتواضعون فيعطيهم نعمة » (يع ٤ : ٦ ، ١بط ٥ : ٥) .",{h:"إن أسلوب مواجهة الخطية بالوصية ، من نصائح القديس مار أوغريس ."},"وهو موجود بأسلوب واسع جداً فى ميامره عن (حرب الأفكار) ، تستطيع أن تقرأها فى مخطوطات الأديرة . ومع ذلك فأنت تستطيع أن تستخرج لنفسك من الكتاب مجموعة من الآيات تستخدمها فى حروبك ، وتحفظها جيداً فى ذاكرتك .",{h:"إن كلمة الله حية وفعالة (عب ٤ : ١٢) ولها تأثيرها ."},"وثق أنك حينما تتذكرها لا بد سيكون لها عمل رادع داخل نفسك . وهكذا قال الرب « كلمتى التى تخرج من فمى لا ترجع إلىّ فارغة . بل تعمل ما سررت به ، وتنجح فى ما أرسلتها له » (أش ٥٥ : ١١) . جرّب إذن قوة كلمة الرب فى حروب الشياطين"],114:[{h:"الفصل الخامس"},{h:"فوائد الحروب الروحية"}],115:[{h:"إن الله لا يمنع عنا حروب الشيطان . ولكنه يقف معنا فيها ، وأيضاً يجعلها لفائدتنا الروحية ."},"ومن أجل هذا ، فإن القديس الأنبا أنطونيوس ، بعد أن عاش معه القديس بولس البسيط فترة محتمياً تحت ظل صلواته ، طلب منه الأنبا أنطونيوس أن يسكن وحده ، لكى يستطيع فى الوحدة أن يجرب حروب الشياطين ويقتنى منها فائدة لنفسه .","فما هى الفوائد الروحية التى تقتنى من حروب الشياطين ؟ والتى مارسها المتوحدون فى البرارى والقفار حتى تفرغوا لمحبة الله ، وبالتالى لقتال العدو ؟",{h:"١ - الفائدة الأولى هى الإتضاع :"},"كلما تشتد حروب الشياطين على إنسان فى قوة وعنف ، يشعر بضعفه أمامها ، فيزول عنه انتفاخه ، وينسحق قلبه من الداخل ، ويرى أنه معرض للسقوط ، وأن إرادته ليست معصومة من الخطأ . ويعرف أن الخطية « طرحت كثيرين جرحى ، وكل قتلاها أقوياء » (أم ٧ : ٢٦) .",{h:"٢ - الصلاة والتمسك بالله وطلب معونته :"},"الإنسان وهو مستريح ، قد لا يطلب المعونة الإلهية ، وقد لا يشعر أنه فى مسيس الإحتياج إليها . ولكنه إذا اشتدت عليه الحرب ، يصرخ إلى الله لينصره على عدو قاس . وهكذا إذ يشعر بضعفه يتمسك بالرب فى صلاة عميقة ، وفى صلوات قوية ؛ هذا الذى قال « أدعنى فى وقت الضيق ، أنقذك فتمجدنى » (مز ٥٠ : ١٥) .",{h:"٣ - الحروب الروحية تدعو إلى الإشفاق على المخطئين :"},"الذى لم تحاربه الشياطين ، قد يقسو على المخطئين ويدينهم فى سقوطهم . أما الذى حورب ، وقد جرّب عنف العدو ، فإنه يشفق على كل خاطىء ويصلى لأجله . وكما قال القديس بولس الرسول « أذكروا المقيدين كأنكم مقيدون معهم . واذكروا المذلين"],116:["كأنكم أنتم أيضاً فى الجسد » (عب ١٣ : ٣) . وقال عن رب المجد « لأنه فيما هو قد تألم مجرباً ، يقدر أن يعين المجربين » (عب ٢ : ١٨) .",{h:"٤ - والحروب الروحية تعطى الإنسان خبرة :"},"فيتمرس بالقتال ، ويتعلم الحرب ، ويعرف حيل العدو وفنونه ، ويأخذ خبرة سواء من قيامه أو سقوطه . والمعروف أن كل ارتقاء درجة يسبقه امتحان ، من يجتازه يرتفع هذه الدرجة كما يحدث لطلاب العلم . وبهذا نرى أن الذين قد دخلوا فى حروب العدو إكتسبوا خبرة .","والخبرات الروحية هذه هى مدرسة تخرّج مرشدين روحيين ، قادرين على معونة غيرهم وتشجيعهم وكشف حيل العدو لهم .",{h:"٥ - والحروب بركة ننال بها أكاليل :"},"وكما قال أحد القديسين : لا يكلل إلا الذى انتصر . ولا ينتصر إلا الذى حارب . وفى احتمالنا لحرب العدو ، وصمودنا فيها ، ومجاهدتنا ومقاومتنا ، فى كل ذلك تظهر محبتنا للرب ، وننال على ذلك أكاليل . وكما قال أحد الآباء : ليس الجنود المنتصرون هم فقط الذين ينالون أكاليل فى الحرب ، وإنما أيضاً الذين جرحوا وأصيبوا ، مادامو لم يستسلموا للعدو وقاتلوه .",{h:"٦ - والحروب تعطينا باستمرار روح الصحو والإستعداد :"},"وكما قال الرب « لتكن أحقاؤكم ممنطقة ، ومصابيحكم موقدة » (لو ١٢ : ٣٥) . شعور الإنسان بأنه فى حرب ، يجعله باستمرار مستعداً للقتال ، يستخدم كل الوسائط الروحية من صلاة وصوم واتضاع ومشورة روحية ، لكى ينتصر . بينما ربما لو خفت الحروب ، لقاده ذلك إلى الفتور الروحى . أما الحرب فتجعله فى حالة تأهب مستمر ، وفى حالة حرص وتدقيق . والخوف من السقوط يجعله يستعد بأكثر قوة حتى ينتصر .",{h:"٧ - والحروب الروحية تجعلنا أقوياء لا نخاف :"},"إنما يخاف الحرب ، الشخص الذى لم يدخلها ولم يقاتل . أما الذى يجرب"],117:["الحروب ، فإن ذلك يعطيه شجاعة وجسارة قلب . وما يأخذه من أكاليل يشجعه على دخول حروب أخرى ، ولا يخشى الفشل فى الحرب . هل يستطيع تلميذ أن يقول إننى من خوف السقوط لا أدخل الإمتحان ، بل ولا أدرس ولا أدخل مدارس ؟! كلا . بل هو يدخل الإمتحانات فى شجاعة قلب ، ويقول : سأنتصر على كل مصاعب العلم وامتحاناته .",{h:"٨ - والحروب الروحية هى مدرسة للإيمان :"},"نرى فيها يد الله كيف تتدخل ، وكيف تعين وتنصر ، وكيف تنتهر العدو ، وكيف تعطى داود الصغير القوة لينتصر على جليات الجبار . وهكذا تعمّق إيماننا فى محبة الله ورعايته وعمله لأجلنا .",{h:"٩ - والحروب الروحية هى مبدأ تكافؤ فرص للشيطان :"},"أخذ الفرصة التى يقاتل فيها ، وبكل قوته . لئلا يحتج الشيطان على أولاد الله ويقول : لماذا يكافئهم الرب ؟ إننى لو أخذت فرصة لأسقطتهم ، كما اشتكى أيام أيوب ، وأخذ فرصته ، وبقى أيوب محتفظاً بكماله (أى ٢) . فالله يسمح للشيطان بأن يحارب المؤمنين ، ويعطى المؤمنين قوة على الإنتصار ، ويخرج الشيطان فى خزى .",{h:"١٠ - وأخيراً فالحروب الروحية تفتح أبواب الملكوت لنا ، وتحدد درجتنا فيه :"},"وكل إنسان ينال أجرته بحسب تعبه ، وبحسب جهاده . وبهذا نرى المؤمنين يبذلون كل جهدهم لكى يعبروا لله عن حبهم . لأنه كيف يظهر حبهم دون أن يُختبر بالحروب الروحية . وكيف تتحدد درجتهم فى الملكوت بدون هذا الإختبار الروحى .","فليكن الرب معنا فى كل حروبنا الروحية ، يقودنا فى موكب نصرته ."]}}}}();